-- ============================================================
-- Ereb4b (2/3): Günə-özəl push bildirişlərinin AR tərcüməsi
-- pregnancy_day_notifications + mommy_day_notifications — Azure/gpt-5.6-sol
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('86704e7d-f300-4ac8-a2e1-2a5068e8a7e2'::uuid, 'اللعب بالخضراوات 🥦', 'هل يرفض السبانخ؟ اكتشفي في وصفات الأطفال كيف تُخفين هذه الفيتامينات ببراعة داخل فطائر لذيذة وتفتحين شهيته.'),
  ('c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a', 'طفرة في الطول! 📏', 'هل أصبحت سراويله قصيرة مجددًا؟ يتسارع نموه الجسدي مع اقترابه من الشهر 25. أدخلي قياساته الحالية في متتبّع النمو، وشاهدي مخطط نموه بفخر.'),
  ('2f36e03e-8050-4c96-a7d2-3231c5e8bf3f', 'استكشاف الهواء الطلق 🌳', 'لم تعد جدران المنزل تتّسع لطاقته. اعثري على حديقة واسعة وآمنة ضمن الأماكن الصديقة للأمهات، ودعيه يركض بحرية ويفرّغ كل طاقته.'),
  ('484ef066-dacc-4b23-98a9-ef3409b6f055', 'اختبار الصبر على المائدة ⏱️', 'هل يلعب بالطعام ولا يأكل؟ شغّلي مؤقت التغذية، وتابعي مدة الوجبة، وحلّلي تطور شهيته من خلال المخطط في التطبيق.'),
  ('d99bde2e-2ab1-43d0-b2d0-95122a7f44ce', 'لماذا يضرب فجأة؟ 🛑', 'هل يمدّ يده بالضرب عندما يغضب؟ تعلّمي من خبير Anacan AI كيف تحوّلين المشاعر العدوانية الشائعة في هذا العمر إلى لعب وتعدّلين هذا السلوك بلطف.'),
  ('1a858fa5-276f-440e-972b-2b83e93db467', 'استراحة قهوة ☕', 'أعمال المنزل ورعاية الطفل... حان وقت الاستراحة! اعثري ضمن الأماكن الصديقة للأمهات على مقهى يضم ركنًا للأطفال، واستمتعي بقهوتكِ الساخنة في هدوء.'),
  ('e6b6723c-fd0e-4884-94df-d412f5e903e7', 'الاستيقاظ المبكر جدًا! 🌅', 'هل يستيقظ طفلكِ قبل شروق الشمس؟ احصلي فورًا على نصائح عملية من مساعد الخبراء بالذكاء الاصطناعي في Anacan لتتعلمي كيفية تنظيم نمط نومه.'),
  ('498eede0-22c9-4d0a-b512-067c46777cb9', 'اكتشاف كلمات جديدة 🗣️', 'ما الكلمة المضحكة التي ابتكرها اليوم؟ سجّلي هذا التطور اللغوي الرائع في ألبوم الطفل على هيئة مقطع فيديو بصوته، لتشاهداه بعد سنوات وتضحكا كثيرًا.'),
  ('710fba45-03e1-4e84-9d81-f9c99d7d2c40', 'هل تكادين تغفين وأنتِ واقفة ظهرًا؟', 'حضّري من وصفاتنا الصحية عصيرًا مخفوقًا بزبدة الفول السوداني يمنحكِ دفعة فورية من الطاقة من دون الحاجة إلى الكافيين.'),
  ('78d6a4b5-d4db-4754-8341-cf2bcc10342a', 'عرض لا ينتهي على السرير 🛌', 'هل يقفز على السرير بدلًا من النوم؟ تابعي مخطط مؤقت النوم، وحلّلي فورًا ما إذا كان لم يفرغ طاقته بالكامل أم أنه مرهق أكثر من اللازم.'),
  ('4622294e-c362-48ed-b4bf-63c35923b3ce', 'شاي دافئ وهدوء 🍵', 'توقف المؤقت ونام طفلكِ. لا تسارعي إلى أعمال المنزل! حضّري شاي المليسة واستمتعي بالهدوء فحسب.'),
  ('53c02e98-c468-40ac-9f02-6cb3c5e5158c', 'درع الكالسيوم 🦴', 'الكالسيوم ضروري للأسنان والعظام. استخدمي أداة متابعة التغذية للتأكد من حصول طفلكِ اليوم على الكمية الموصى بها من الزبادي والجبن، واستكملي أي نقص.'),
  ('f10247de-df8b-47ef-a539-e87f8db55ae2', 'الطبيب الصغير منهمك في عمله 🩺', 'هل يعطي دبدوبه حقنة أم يفحص بطنه؟ ألعاب الخيال في أوجها! التقطي هذه اللحظة اللطيفة فورًا باستخدام جلسة تصوير الطفل، واجعلي منها ذكرى لا تُنسى.'),
  ('1a31af42-99cc-4ebb-8d30-72e007760f62', 'الحاجة إلى الهدوء 🤫', 'حافظي على هدوء الغرفة باستخدام مقياس الصوت. فتقطّع نومه ليلًا يؤثر سلبًا في نموه وفي مزاجكِ صباحًا.'),
  ('04f27cd2-d5c6-4a88-a758-f59dfedfac03', 'إشارات الجهاز الهضمي 💩', 'أدخلي ملاحظاتكِ عند تغيير الحفاض. إذا كان هناك خطر للإصابة بالإمساك، فاحرصي على الاطلاع في التطبيق على توصيات الأطعمة الطبيعية الغنية بالألياف ووصفات المياه المنكّهة بالفواكه.'),
  ('2312b09a-1559-4ed0-aada-ff2063057e72', 'هل يخاف من الانفصال؟ 🌌', 'هل يبكي خلفكِ بمجرد خروجكِ من الغرفة؟ شغّلي له صوت الرحم من قسم الأصوات البيضاء، لتمنحيه ذلك الشعور القديم الدافئ بالأمان وتساعديه على الاستعداد للنوم.'),
  ('a2bb6939-4631-4be2-a871-cb519c3fdacb', 'بلا سكر، لكنه حلو 🍪', 'وداعًا لبسكويت المتاجر! اكتشفي ضمن وصفات الأطفال حلويات صحية بالتمر والشوفان يمكن تحضيرها في المنزل خلال 10 دقائق.'),
  ('5e9c412f-bcfb-4d5e-a447-66eebbf03e51', 'فن قول «لا!» 🛑', 'هل يقول «لا» لكل شيء؟ هذا ليس تحديًا لكِ، بل هو استكشاف لشخصيته المستقلة. ساعديه على تجاوز عناده بمنحه خيارين بدلًا من طرح أسئلة مغلقة عليه.'),
  ('64707418-d2a0-43f8-b7ef-86936fa426fe', 'هل خانتكِ ذاكرتكِ مجددًا؟', 'لا ترهقي ذهنكِ بتذكّر كل غرض صغير نفد من المنزل؛ أضيفيه فورًا إلى قائمة التسوق ودعي شريككِ يتولى الأمر.'),
  ('d3a41958-709d-460d-ae40-910c3a69b580', 'هل يستيقظ صارخًا في منتصف الليل ولا يهدأ؟', 'تؤثر أزمات عمر السنتين في النوم أيضًا. دعي ميزة تحليل البكاء تستمع إلى صوته لتحديد المشكلة بدقة.'),
  ('07a0b7ef-0c8f-405e-aede-5d8c497ab1df', 'هدوء الكهف 🌌', 'ألا يتعب من الركض ويرفض الذهاب إلى السرير؟ شغّلي مؤقت النوم واختاري صوت حفيف الغابة من قسم الأصوات البيضاء، لتحوّلي الغرفة إلى كهف هادئ للنوم.'),
  ('9849f311-0e6e-4965-b1a2-164cf002508c', 'حان وقت القفز 🦘', 'هل يقفز على الأرائك في المنزل؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مركز ترفيهي يضم ترامبولين وأرضية لينة، ليفرّغ طاقته بأمان.'),
  ('bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a', 'الأضراس الأخيرة؟ 🦷', 'هل يقضم كل شيء بلا سبب ويضع يديه في فمه؟ ربما تكون الأضراس الخلفية الأخيرة (الأضراس الثانية) في طريقها إلى الظهور. احرصي على مراجعة متتبع التسنين.'),
  ('e490e4c7-7ef7-4eec-a03a-11da14534526', 'يمكن للأعمال المنزلية أن تنتظر 🛑', 'لم تمسحي الأرضية؟ دعيها كما هي. يمكن ترتيب المنزل المتسخ، لكن تعافي الأم المنهكة يستغرق وقتًا طويلًا. استلقي على الأريكة واستمتعي بالهدوء فحسب.'),
  ('753bfaff-7926-4516-b6b5-e78d2b60a270', 'رفض الفاكهة 🍎', 'هل يرمي اليوم الفاكهة التي أحبها بالأمس على الأرض؟ الانتقائية في الطعام مشكلة شائعة في هذا العمر. اطلعي على أفكار تقديم ممتعة ومتنوعة ضمن الوصفات الصحية.'),
  ('8b287134-38e5-4f28-8d41-3ba7f9bcd5b7', 'الألعاب التخيّلية تزداد عمقًا 🧸', 'هل يطعم ألعابه ويضعها في الفراش؟ إنها ذروة تطور الخيال! سجّلي محاولات التعاطف هذه في متتبع النمو.'),
  ('b884ea59-629f-4f5c-a2db-ce8f7aee5def', 'القوة في الاتحاد🥂', 'بعد أن ينام طفلكِ، حضّري كوبًا من الشاي مع شريككِ للتخلص من ضغوط اليوم، وقدّرا بعضكما بعضًا قائلين: نحن فريق رائع.'),
  ('26ecdf90-afa5-4aeb-a939-0e9c19c4397d', 'لنحلل الروتين ⏱️', 'هل استغرق النوم مساءً 40 دقيقة؟ راجعي مخطط مؤقت النوم. ربما حان الوقت تمامًا لتقليص القيلولة النهارية بمقدار 20 دقيقة وتقديم موعد النوم مساءً.'),
  ('4efacff1-8d44-47f9-9c4b-52dbb8de0f37', 'نوبة صراخ في مكان عام 🛒', 'هل ألقى طفلكِ بنفسه على الأرض في المتجر لأنكِ لم تشتري له ما أراد؟ تجاهلي نظرات المحيطين وتحدثي مع Anacan AI لتتعلمي كيفية التعامل مع هذه النوبات بهدوء.'),
  ('6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6', 'لا تخافي من الاتساخ!', 'اكتشفي فورًا أفضل أدوات الرمل الحركي أو الألعاب الحسية في قسم المنتجات الموصى بها واطلبيها إلى منزلكِ.'),
  ('031a9c48-32b8-49a9-a9d1-55eb165785a3', 'فحص مخزون البروتين 🥚', 'البروتين ضروري للعضلات التي تنمو بسرعة. استخدمي أداة متابعة التغذية لحساب احتياج اليوم من البروتين (البيض واللحوم والبقوليات)، وعدّلي قائمة الطعام إذا كان هناك نقص.'),
  ('9a014c54-2569-48f1-8b59-1e18b3b2e5b1', 'فن الرسم بالأصابع! 🎨', 'هل لطّخ وجهه بالكامل أثناء اللعب بالألوان؟ بدلًا من الانزعاج، زيّني هذه اللحظة المرحة والمبدعة فورًا بالملصقات المبهجة في جلسة تصوير طفلكِ، ثم حمّليها إلى الألبوم.'),
  ('9b9b6d7f-8fb9-448e-ba10-0598457b94a6', 'هل عادت الاستيقاظات الليلية؟ ⏱️', 'هل يستيقظ باكيًا في منتصف الليل ويجد صعوبة في العودة إلى النوم؟ حلّلي إحصاءات مؤقت النوم. لعل قيلولته النهارية طالت أكثر من اللازم وأثّرت في نومه مساءً؟'),
  ('87f68482-c94a-42ff-b3af-66083c5353fb', 'لا يقرأ، بل يروي 📖', 'هل يصف لكِ الصور أثناء حكاية المساء؟ سجّلي بصوته هذه اللحظة الرائعة المليئة بالخيال.'),
  ('9bde240a-b972-41fa-8294-7b553545ae04', 'العظام تزداد قوة 🦴', 'يتطلب النمو السريع الكالسيوم. استخدمي أداة متابعة التغذية للتأكد من حصوله اليوم على الكمية المطلوبة من الجبن والزبادي، واستكملي أي نقص.'),
  ('ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b', 'لا يريد المشاركة؟ 🧸', 'هل يركض في الحديقة نحو ألعاب الأطفال الآخرين، لكنه يرفض إعطاءهم ألعابه؟ تعرّفي في قسم المدونات إلى كيفية تعليم الأطفال في عمر السنتين مفهوم تبادل الأدوار في اللعب.'),
  ('0fca32b2-cafe-4f95-9933-261c2771f460', 'لنحلّل روتينه بالكامل ⏱️', 'هل استغرق نومه مساءً 40 دقيقة؟ راجعي الرسم البياني في مؤقت النوم. ربما حان الوقت تمامًا لتقصير قيلولته النهارية بمقدار 20 دقيقة وتقديم موعد نومه مساءً.'),
  ('3c1dc66a-c7fe-45c2-99c5-908555ae99a9', 'قنبلة طاقة للأم ⚡', 'هل تكاد عيناكِ تُغمضان من كثرة الركض؟ لا تلجئي إلى الحلويات، بل إلى البروتين! أعيدي شحن طاقتكِ بسموذي زبدة الفول السوداني الذي يُحضّر في ٥ دقائق، من قسم الوصفات الصحية للنساء.'),
  ('83cfece3-b100-41d8-bb8e-0c02263c9e3e', 'هل يخاف من الظلال؟ 🌌', 'هل تزعجه الظلال على الحائط عندما تُظلمين الغرفة؟ قد يؤدي تطور الخيال إلى ظهور بعض المخاوف. شغّلي صوت الرحم من قسم الضوضاء البيضاء لتمنحيه شعورًا بالأمان في الغرفة.'),
  ('a23bc347-ea83-491e-af00-0e80deaecf0f', 'الخطوة الأولى نحو استخدام المرحاض؟ 🧻', 'هل تبقى حفاضته جافة تمامًا في الصباح ويشعر بالانزعاج؟ هذه إشارة رائعة. سجّلي ذلك في متتبع الحفاضات، وابدئي بقراءة مراحل الاستعداد للتدريب على استخدام النونية في قسم المدونات.'),
  ('46824a50-cc48-4a9c-ad3e-91d5073cd55e', 'عاصفة «لا!» 🛑', 'هل يعترض صارخًا على كل ما تقترحينه؟ في هذه اللحظات الصعبة من مرحلة عمر السنتين، احصلي فورًا على نصائح خبير Anacan AI للحفاظ على هدوئكِ وتحويل نوبات الغضب إلى لعب.'),
  ('51c7f01a-f92a-4f7e-97c1-5893c5304d42', 'رحلة البحث عن المنطق 🧩', 'لقد أصبح يملّ سريعًا من الألعاب البسيطة. اكتشفي في قسم المنتجات الموصى بها أحجيات خشبية وألعابًا هندسية تصقل ذكاءه وتعزز تركيزه.'),
  ('a1d0bf30-60c8-4128-8527-423ff92dd8f8', 'ركض ومطاردة بلا نهاية 🏃‍♂️', 'هل يقفز على الأرائك بدلًا من الذهاب إلى السرير؟ شغّلي مؤقت النوم، وسجّلي مدة العملية، وربما قدّمي موعد الروتين المسائي بناءً على الرسم البياني.'),
  ('1e0042aa-0b2b-4948-aaf5-3b9cec37c61f', 'جُمل مضحكة 🗣️', 'إن جُمله المكوّنة من ٣-٤ كلمات بأخطائها اللطيفة لا تُقدّر بثمن! لا تفوّتي هذا التطور الرائع، وأضيفيها فورًا إلى ألبوم الطفل في مقطع فيديو بصوته لتبقى ذكرى خالدة.'),
  ('4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671', 'هل يعبث بكل شيء لأنه لم يفرّغ طاقته؟', 'افتحي خريطة الأماكن الصديقة للأم، وابحثي عن حديقة آمنة ذات أرضية لينة ومنزلقات، ودعيه يلعب بحرية.'),
  ('63d48088-e9cb-43c1-afc1-9e4bb32ff340', 'نسختكِ الصغيرة 📸', 'هل يمسح طفلكِ بقطعة قماش عندما تكنسين الغرفة، أو يمشي مثلكِ؟ التقليد في ذروته!'),
  ('669259fd-a22a-4d24-b932-9eedd58dff3f', 'بلا سكر، لكنه حلو 🍪', 'وداعًا لبسكويت المتاجر! اكتشفي في وصفات الأطفال حلويات صحية بالتمر والتفاح تُحضَّر في المنزل خلال 10 دقائق، وأسعدي طفلكِ بها.'),
  ('14d92f0a-2caa-441a-b66e-e4531b0f2c30', 'عدوانية مفاجئة 🛑', 'هل يدفع أصدقاءه عند الغضب أو يحاول ضربكِ؟ اسألي مساعدنا الخبير Anacan AI فورًا عن كيفية توجيه المشاعر العدوانية في هذا العمر بلطف.'),
  ('a1ab1785-3fde-4782-bfe0-d24e5fc6ec72', 'هل يؤلمكِ ظهركِ؟ 🧘‍♀️', 'هل يؤلمكِ ظهركِ من حمل صغيركِ الذي يزن 13+ kq؟ اعتني بنفسكِ وحضّري شاي الزنجبيل المضاد للالتهاب والمريح للعضلات من قسم الوصفات الصحية.'),
  ('e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65', 'هل يخيفه الصمت؟', 'شغّلي صوت المروحة أو مجفف الشعر من قسم الضوضاء البيضاء في الغرفة، ولاحظي كيف يمنحه ذلك شعورًا مثاليًا بالأمان في بيئة النوم.'),
  ('7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb', 'ضبابية الذهن 🌫️', 'هل أنتِ مرهقة جدًا وتنسين كل شيء؟ حضّري وجبة خفيفة بالجوز الغني بأوميغا-3 من قسم الوصفات الصحية للنساء، ثم أفرغي ما في ذهنكِ في يوميات المزاج.'),
  ('8144388a-1733-475c-83c3-62e4fa74eb05', 'يرفض استخدام النونية؟ 🚽', 'هل يرفض الذهاب إلى المرحاض ويبكي؟ اسألي مساعدنا الخبير Anacan AI فورًا عمّا إذا كان من الأفضل أخذ استراحة من التدريب أو تجربة طريقة مختلفة.'),
  ('aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb', 'هل يأكل الفاكهة فقط؟ 🍎', 'هل يرفض البروتين أو الخضراوات؟ استخدمي أداة متابعة التغذية لحساب كمية الطعام الصحي التي تناولها اليوم، وابتكري تركيبات شهية مثل الزبادي بالفاكهة.'),
  ('0e790195-f407-4908-a021-252afa265e2e', 'توازن السوائل لدى الأم 💧', 'هل نسيتِ شرب الماء وأنتِ تركضين خلف طفلكِ؟ قد يكون هذا سبب الصداع. حضّري ماء الديتوكس بالنعناع والليمون من قسم الوصفات الصحية للنساء واستعيدي نشاطكِ.'),
  ('704cb940-aadd-424e-94f9-6bfecacafa6d', 'فحص الهضم الصباحي 💩', 'راقبي براز طفلكِ عند تغيير الحفاض. يزداد خطر الإمساك مع زيادة الأطعمة الصلبة، لذا سجّلي ذلك في التطبيق وأضيفي فورًا أطعمة غنية بالألياف، مثل الكمثرى والشوفان، باستخدام أداة متابعة التغذية.'),
  ('94804bde-ee95-44e1-87c0-8fe6a051dfb6', 'الخوف من الأصوات المفاجئة 🌪️', 'هل يخاف طفلكِ من صوت المكنسة الكهربائية أو الخلاط؟ شغّلي صوت مجفف الشعر من قسم الضوضاء البيضاء لتخفيف خوفه وتهيئته للنوم تدريجيًا.'),
  ('0c2ed459-b6ef-4583-9c57-19766bfe4257', 'فرز الألوان 🔴🔵', 'لدعم نمو التفكير المنطقي، ابحثي الآن في قسم المنتجات الموصى بها عن أحجيات هندسية (puzzle) مناسبة لعمر طفلكِ وألعاب خشبية ملوّنة، وساعديه على تنمية ذكائه.'),
  ('1d490bb4-d589-47e3-911a-0660496e1c17', 'العضّ والضرب 🦖', 'هل يرفع طفلكِ يده فجأة أو يعضّ عندما يغضب؟ اقرئي المقالات النفسية في قسم المدونات لتتعرّفي إلى كيفية تهذيب المشاعر العدوانية في هذا العمر بلطف.'),
  ('f82f821d-7bd9-4cb7-9d17-c92628dde594', 'هل أصبح الحذاء ضيقًا فجأة؟ 👟', 'هل يتعثّر طفلكِ كثيرًا أثناء الركض؟ ربما كبرت قدمه! أدخلي طوله الحالي ومقاس حذائه في متتبّع الوزن لمتابعة نموه الجسدي.'),
  ('ca3c13b4-94b6-44d7-a1be-1829a1d0e718', 'العظام تزداد قوة 🦴', 'يتطلب النمو السريع الكالسيوم. استخدمي أداة متابعة التغذية للتأكد من أن طفلكِ تناول حصته اليومية من الجبن واللبن، وعوّضي أي نقص فورًا.'),
  ('cbda41ad-a761-4c07-b60f-6e77f3dd54cc', 'أنتِ رائعة بالفعل 🌟', 'لقد أمضيتِ اليوم تركضين خلف طفلكِ بلا توقف، وشعرتِ بالتعب. افتحي مفكرة المزاج، واكتبي حتى أصغر شيء جميل فعلتِه من أجله اليوم، وصفّقي لنفسكِ واقفة!'),
  ('53d8ad5e-ba3b-4f31-a266-650eb5f83382', 'مساعد التنظيف الصغير 🧹', 'هل يمسح بقطعة قماش حين تكنسين الغرفة، أم ينقضّ على المكنسة الكهربائية؟ زيّني هذا التقليد الطريف فورًا بملصقات جلسة تصوير الطفل، ثم حمّليه إلى الألبوم.'),
  ('9d0ac1c5-216f-4fa0-95d2-f983474b4839', 'فحص مخزون الحديد 🥩', 'لتجنيب طفلكِ النشيط الإصابة بفقر الدم، تحققي من كمية الحديد التي تناولها اليوم، مثل اللحوم والبقوليات، باستخدام أداة متابعة التغذية، وحدّثي قائمة طعامه.'),
  ('8f01b040-4aa3-4a5f-a127-4287f88b0ef1', 'فن القفز 🦘', 'لم تعد الأرائك تكفيه! ابحثي عن مركز ترفيهي داخلي آمن يضم ترامبولين، وساعديه على تفريغ طاقته.'),
  ('cf348bab-0260-4da9-bc53-4069f0a6ddf3', 'الفنان الصغير منهمك في عمله 🎨', 'هل لطّخ وجهه بالكامل أثناء اللعب بالألوان؟ بدلًا من الانزعاج، استمتعي بهذه اللحظة المرحة والمبدعة.'),
  ('d6dd1818-c4fb-46af-be6f-20980791db71', 'هل عادت الاستيقاظات الليلية؟ ⏱️', 'هل يستيقظ باكيًا في منتصف الليل ويصعب عليه العودة إلى النوم؟ حلّلي إحصاءات مؤقت النوم. قد يكون السبب انتكاسة النوم في عمر سنتين أو التسنين.'),
  ('1d5cbb75-8a18-4083-a6e5-10d5b00dd31c', 'مهدئ طبيعي 🍃', 'هل كان يومًا حافلًا بالضوضاء والركض؟ أظلمي الغرفة، وشغّلي صوت خرير النهر من «الضوضاء البيضاء»، وامنحي دماغه ودماغكِ بعض الاسترخاء.'),
  ('947b2874-60ed-46dc-82cb-4ddf972a50b1', 'كيف هو مخزون البروتين؟ 🍗', 'البروتين ضروري للعضلات النشيطة. استخدمي أداة متابعة التغذية لتقييم توازن غذائه اليومي وإثراء قائمة طعامه.'),
  ('f56b8fb7-fe66-42a7-afb0-9342dd02a543', 'الأغاني المفضلة 🎤', 'هل يغني الأغنية نفسها أو يدندن بها بلا توقف؟ وثّقي إحساسه بالإيقاع وتطوره اللغوي بإضافة هذه اللحظة إلى الألبوم باستخدام الملصقات الموسيقية في جلسة تصوير الطفل.'),
  ('dc8f916f-27ea-45e1-9c5f-84435b0902fd', 'الإصرار على الأكل بنفسه 🥄', 'هل يأخذ الملعقة منكِ ويُلطّخ كل مكان؟ شغّلي مؤقت التغذية وحلّلي الوقت الذي تستغرقه تجربة الاستقلال هذه. فقط ابتسمي للطعام المتناثر.'),
  ('1d9a17fb-3ed7-4382-9eaf-1517914b5b98', 'لا أريد هذا البنطال! 👗', 'هل بدأت مرحلة الإصرار على قول: سأرتدي ملابسي بنفسي!؟ تعرّفي من Anacan AI إلى طرق تخفيف أزمات ارتداء الملابس صباحًا ومنحه حرية الاختيار.'),
  ('98d988ed-7e7f-4eb3-8b84-734112bb1929', 'أنتِ أيضًا بحاجة إلى صديقات 👯‍♀️', 'هل سئمتِ من التحدث مع طفلكِ فقط؟ ابحثي في الأماكن الصديقة للأمهات عن مراكز تضم مجموعات للعب، وتواصلي مع أمهات أخريات وتبادلن الخبرات.'),
  ('f6ae40aa-d27d-4aed-a0d9-bd51bad467d7', 'لنقرأ الكتاب بدلًا من تمزيقه 📖', 'هل يمزّق الصفحات وقت حكاية المساء أو لا يدعكِ تقرئين؟ اسألي Anacan AI فورًا عن كيفية حل هذه المشكلة من دون التأثير سلبًا في عادة القراءة.'),
  ('27d6b395-9576-4f2d-9566-57d41e7c6f41', 'لنحلّل الروتين بالكامل ⏱️', 'هل استغرق النوم مساءً 40 دقيقة؟ ألقي نظرة على مخطط مؤقت النوم. ربما حان الوقت تمامًا لتقليل القيلولة النهارية بمقدار 20 دقيقة وتقديم موعد النوم مساءً.'),
  ('dec1d9f5-52bc-4c79-9c9c-281f44046beb', 'أسئلة «لماذا؟» التي لا تنتهي 🤔', 'ألا يملّ من طرح الأسئلة؟ ما هذا؟ لماذا؟ لقد بدأت هذه المرحلة رسميًا! تعرّفي من المدوّنات إلى كيفية الاستجابة بصبر لفضول طفلكِ وحبّه للاستكشاف.'),
  ('e68bbf03-3f37-41e8-a1d9-32feba8b86d7', 'بلا سكر، لكنه حلو 🍪', 'وداعًا لبسكويت المتاجر! اكتشفي في وصفات الرضّع حلويات صحية يمكن تحضيرها في المنزل خلال 10 دقائق، وأسعدي طفلكِ بها.'),
  ('32443a45-bb1d-40cd-8cbf-77a3eda300d7', 'شاي ساخن وهدوء 🍵', 'توقّف المؤقت ونام طفلكِ. لا تسرعي إلى الأعمال المنزلية! حضّري قهوة مميزة من الوصفات الصحية، واستلقي على الأريكة واستمتعي بالهدوء فحسب.'),
  ('0963259b-f909-4657-ae5e-475b63d595ec', 'تمرّد على القيلولة! 🛌', 'هل يرفض طفلكِ قيلولة الظهيرة ويهرب منها؟ اسألي Anacan AI عن احتياجات الأطفال في عمر عامين إلى النوم وأسرار تخصيص وقت هادئ (quiet time).'),
  ('0bba2ea7-ff2c-40db-9921-cae50208c766', 'خبير خلع الملابس! 🧦', 'هل يحاول طفلكِ خلع جواربه أو سرواله بنفسه؟ هذا مؤشر رائع على تطور مهاراته الحركية.'),
  ('160a2dee-dfe4-4a75-b257-c4a10c478741', 'قوة الزنجبيل 🫖', 'هل يؤلمكِ ظهركِ وساقاكِ من الركض طوال اليوم؟ حضّري شايًا يساعد على استرخاء العضلات من قسم الوصفات الصحية واستريحي.'),
  ('20369d8a-500f-4d0c-8f13-a85f623e07d2', 'لنراقب الطيور 🕊️', 'هل شعر طفلكِ بملل شديد في المنزل؟ ابحثي عن حديقة خضراء، وقدّما الحبوب للطيور لتعزيز تعاطفه مع الطبيعة.'),
  ('69fc5add-e558-46f8-bee8-37acee27a9c1', 'حان وقت ابتكار حكاية 📖', 'هل مللتِ من قراءة الكتب؟ أطفئي الأنوار، وشغّلي صوت المطر من قسم الأصوات البيضاء، وابتكرا معًا حكايات خيالية في الظلام حتى تغطّا في النوم.'),
  ('d25adde2-a568-4bad-bacf-b25822698f2a', 'العودة إلى الطعام المهروس؟ 🥣', 'هل يتكاسل طفلكِ عن مضغ الطعام الصلب ويطلب الطعام المهروس مجددًا؟ تصفّحي وصفات الأطفال للاطلاع على وصفات أقراص شهية سهلة المضغ وغير مهروسة.'),
  ('181e78e0-6fdf-4595-ab68-0d67492cb40c', 'سأسكب بنفسي! 🥛', 'هل يريد طفلكِ سكب الماء في الكوب بنفسه فيبلّل كل شيء؟ لدعم هذه المهارات الحياتية العملية، اطّلعي على الأكواب الذكية المانعة للانسكاب في قسم المنتجات الموصى بها.'),
  ('68364d15-562a-4922-a1dc-902274f2d63c', 'هل يصفق الأبواب؟ 🚪', 'هل يصفق طفلكِ الأبواب ويبكي عندما يغضب؟ تواصلي فورًا مع خبيرنا في Anacan AI لتعلّم استراتيجيات تساعدكِ على التعامل مع هذه الانفعالات العاطفية الشديدة.'),
  ('de0f5d4f-9f96-42d7-a940-e7558af5d045', 'لا تتناولي وجبة خفيفة وأنتِ واقفة 🍎', 'قدّري نفسكِ! حضّري من الوصفات الصحية سلطة التوت الغنية بمضادات الأكسدة.'),
  ('7a5b3c40-a866-426b-8ed4-dd68302d6513', 'شغف بورق المرحاض 🧻', 'هل يسحب طفلكِ ورق المرحاض من اللفافة ويلعب به في الحمام؟ حوّلي هذا الاهتمام إلى فرصة، وابدئي الآن بقراءة مقال الانتقال إلى التدريب على استخدام النونية من خلال اللعب في قسم المدوّنات.'),
  ('d2a5512c-c089-47a6-aba1-367f406306e5', 'واحد، اثنان، ثلاثة... 🔢', 'هل يحاول طفلكِ عدّ الأشياء أثناء صعود الدرج؟ هذه أولى بوادر تطوّره في المهارات الرياضية.'),
  ('f4ef4af2-bbdc-456f-a980-4eeb315c77b8', 'هل اكتمل ظهور الأسنان؟ 🦷', 'هل تظهر أضراسه الأخيرة؟ لتلبية احتياجاته المتزايدة من الكالسيوم، احرصي على التحقق من كمية الزبادي والجبن التي تناولها اليوم باستخدام أداة متابعة التغذية.'),
  ('0480de3f-fc2e-475f-9c9a-7f062b43912d', 'هل غرفة النوم شديدة الدفء؟ 🌡️', 'هل يتقلّب طفلكِ كثيرًا في السرير ويتعرّق؟ تحققي من درجة حرارة الغرفة، وشغّلي مؤقت النوم واستخدمي صوت المروحة من قسم الضوضاء البيضاء لإضفاء إحساس نفسي بالبرودة على الغرفة.'),
  ('2b885719-7eb3-49f2-a501-3fdceb08a1dc', 'هل يبكي خلفكِ؟ 🚪', 'هل يصرخ طفلكِ خلفكِ حتى عندما تغادرين الغرفة؟ اسألي Anacan AI عن طرق لطيفة للتعامل مع هذه الموجة الجديدة من قلق الانفصال.'),
  ('4ef212ee-e501-41a3-bd1b-0f62028addbd', 'المنطق قيد العمل 🧩', 'هل أصبح طفلكِ بارعًا في مطابقة الأشكال الهندسية؟ استكشفي قسم المنتجات الموصى بها للعثور على ألعاب أكثر تعقيدًا تتحدى قدراته الذهنية بدرجة أكبر.'),
  ('132f97c4-bee0-471c-ad8b-a7fc3585b9d6', 'اختيار معجون الأسنان 🪥', 'هل بدأ طفلكِ يتعلّم بصق الماء؟ احرصي على قراءة مقالنا العلمي في قسم المدوّنات حول اختيار معجون أسنان يحتوي على الفلورايد أو يخلو منه.'),
  ('c85cd72a-3a99-42a3-86ab-1fa1d9a4f422', 'كعكات الطين! 🧁', 'هل يرغب طفلكِ في اللعب بالتراب في الحديقة؟ دعيه يتّسخ! خلّدي هذه اللحظات الرائعة التي تدعم نمو حواسه من خلال جلسة تصوير الطفل.'),
  ('da905da7-70f6-46f4-b372-c620f421daf8', 'أعيدي تشغيل ذهنكِ 🧘‍♀️', 'هل تشعرين بأن كل شيء يثقل كاهلكِ؟ افتحي مفكرة الحالة المزاجية واكتبي كل ما تشعرين به دون توقف لمدة 3 دقائق. فالكتابة تخفف التوتر فورًا.'),
  ('929b30f1-695d-4f66-a22b-9182b15561c4', 'اختبار الجاذبية! 🍎', 'هل يحب طفلكِ إسقاط الطعام أو الألعاب من الأعلى إلى الأسفل؟ تعلّمي من Anacan AI كيفية توجيه هذه الاستكشافات الفيزيائية بدلًا من إيقافها.'),
  ('a100b8dd-35f6-4549-ae5f-d60352e46cb5', 'نقص الألياف؟ 💩', 'هل أصبح براز طفلكِ صلبًا ويعاني من الإمساك؟ سجّلي ذلك في متتبّع الحفاضات، ثم أضيفي البرقوق المجفف أو الشوفان إلى قائمته الغذائية فورًا باستخدام أداة متابعة التغذية.'),
  ('f0258928-f8cb-46a1-adb3-9d7138af115d', 'أول رفيق للعب 👯‍♂️', 'هل يحاول طفلكِ باستمرار اللعب مع طفل آخر في الحديقة؟ اطّلعي في قسم الأماكن المناسبة للأمهات على مقاهي الأطفال التي تدعم هذه المرحلة الجديدة من التفاعل الاجتماعي.'),
  ('0b94a795-dee1-49c6-a4fb-e07d6174147f', 'تحليل مؤقت النوم ⏱️', 'هل ينام طفلكِ في وقت متأخر جدًا مساءً؟ ألقي نظرة على مخطط مؤقت النوم. قد يكون الوقت قد اقترب لتقليص قيلولته النهارية وتقديم موعد نومه مساءً.'),
  ('225bd8fb-b294-42ab-8941-6c8eee154c5f', 'هل ضاق الحذاء فجأة؟ 👟', 'هل يتعثر طفلكِ كثيرًا أثناء الركض؟ ربما كبرت قدماه! أدخلي طوله الحالي ومقاس حذائه في متتبّع النمو لمتابعة تطوره الجسدي.'),
  ('f7cd700a-6bea-4a3e-a6b4-0018529f2ea2', 'القهوة أم الماء؟ 💧', 'لا تحاولي التغلب على التعب بالكافيين! اكتشفي ضمن الوصفات الصحية للنساء مشروبات الديتوكس الغنية بالبروتين والفواكه، والتي تمنحكِ الطاقة.'),
  ('250e2ef0-defa-4388-a9c2-8574f1be0fed', 'طاهٍ صغير في المطبخ 👩‍🍳', 'حضّرا معًا عجينة بسكويت خالية من السكر من وصفات الأطفال. دعي طفلكِ يطوّر مهاراته الحركية ويأكل ما صنعته يداه بشهية.'),
  ('2ee3ac65-4c9f-4558-a181-e43a5be6a221', 'المتسلّق الصغير 🧗', 'هل أصبح تسلّق الأثاث هواية لدى طفلكِ؟ تصفّحي أدوات الحماية الخاصة في قسم المنتجات الموصى بها لتعزيز أمان المنزل إلى أقصى حد.'),
  ('e1c7d8a6-1882-42b5-8d1e-5420a73cc054', 'خرير المياه 🌊', 'هل كان يومًا حافلًا بالتوتر والركض؟ خفّفي الإضاءة، وشغّلي صوت خرير النهر من قسم الضوضاء البيضاء، واستسلما معًا للهدوء.'),
  ('09840996-6ece-429b-8105-2969a0ec7d4b', 'صفّقي لنفسكِ 🌟', 'هل نجحتِ في إنهاء اليوم من دون نوبات غضب؟ لولاكِ لما تحقق هذا التطور. افتحي يوميات المزاج واكتبي لنفسكِ رسالة شكر كبيرة تقديرًا لتفانيكِ!'),
  ('152dc6e1-3207-4818-a59d-35cf71d6d914', 'الحنان تجاه الألعاب 🧸', 'هل يغنّي طفلكِ أغنية مهد لدبّه أو يغطّيه؟ هذه علامة على تطور قوي في التعاطف. أضيفي اللحظة إلى ألبوم طفلكِ كمقطع فيديو مصوّر بالصوت، ووثّقي حنانه.'),
  ('cb411136-f146-4918-b034-820fe50cfd21', 'طفرة المفردات 🗣️', 'كيف تتطور حصيلته اللغوية؟ اكتشفي في قسم المدوّنات معايير تطور النطق الخاصة بهذا الشهر، والألعاب المنزلية التي تدعم هذا التطور.'),
  ('047ed43c-bb7c-4206-afa0-67d1dc0f765d', 'الطعام يتخذ أشكالًا ⭐️', 'هل يرفض طفلكِ تناول الفاكهة المقطعة بالطريقة المعتادة؟ حوّلي وقت الطعام إلى لعبة بصرية عبر أفكار التقديم الممتعة على شكل نجوم أو حيوانات في قسم وصفات الأطفال.'),
  ('5f17b1b2-9554-4ba7-b535-5f0af1522385', 'هل يختبئ ليتبرّز؟ 🙈', 'هل يختبئ خلف الستارة أو في زاوية ليتبرّز؟ هذه من أبرز العلامات النفسية على استعداده لاستخدام النونية! سجّلي ذلك في متتبّع الحفاضات، واقرئي مقالات التدريب في قسم المدوّنات.'),
  ('c569bc01-3134-4ece-a6d6-d600fb0bf88b', 'هل يؤلمكِ أسفل ظهركِ؟ 🧘‍♀️', 'توترت عضلاتكِ من حمل طفلكِ الذي يزداد وزنًا. حضّري شاي الزنجبيل المضاد للالتهاب من قسم الوصفات الصحية للنساء، واستلقي وخصّصي بعض الوقت لنفسكِ.'),
  ('504aaa66-e4f6-4eca-bd17-eead2d69deec', 'فن «سأرتدي ملابسي بنفسي» 👕', 'هل يحاول ارتداء سرواله على رأسه وقميصه في قدميه؟ لا تفوّتي هذه المحاولة الطريفة للاستقلالية! زيّني الصورة فورًا بالملصقات المرحة في قسم جلسة تصوير الطفل، ثم حمّليها إلى الألبوم.'),
  ('c0ee7f2f-8895-4772-8368-647fe5fed56e', 'استكشاف برك الماء 🌧️', 'لا داعي للبقاء في المنزل بعد المطر! اعثري على أقرب حديقة في قسم الأماكن الصديقة للأمهات، وألبسيه حذاءه المطاطي ودعيه يقفز في الوحل.'),
  ('e70f443c-46d9-4882-ab14-fad93c425a0f', 'نافذة النوم تتغير ⏱️', 'هل رفض قيلولته النهارية؟ شغّلي مؤقت النوم وقدّمي روتين المساء 30 دقيقة حتى لا يُصاب بنوبة انفعال بسبب الإرهاق الشديد مساءً.'),
  ('65eaf451-e5ab-4c54-9b0f-1a6331bd0312', 'المهارات الحركية الدقيقة تتطور 🧩', 'لقد أتقن بالفعل تركيب الأحجيات البسيطة. اكتشفي في قسم المنتجات الموصى بها أحجيات خشبية أكثر تعقيدًا ومتعددة القطع، تتحدى قدراته الذهنية بدرجة أكبر.'),
  ('c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f', 'نوبة بكاء على الأرض 🛑', 'هل يرمي نفسه على الأرض ويصرخ في مكان عام؟ لا تهتمي بنظرات الآخرين! تحدّثي مع Anacan AI وتعلّمي أساليب تساعدكِ على التعامل بهدوء مع هذه الانفجارات العاطفية الحادة.'),
  ('f9afcff7-9182-4728-9ed2-135f5b97e440', 'الكتب للقراءة لا للتمزيق 📖', 'هل يمزق الصفحات وقت قصة المساء؟ اقرئي في قسم المدوّنات كيف تجذبين انتباهه إلى القصة من دون التأثير سلبًا في حبه للقراءة.'),
  ('11eb0bc9-4158-4fbc-8d65-97be316f8b92', 'الكالسيوم لا يأتي من الحليب فقط 🧀', 'هل يرفض شرب الحليب؟ الكالسيوم ضروري للعظام. استخدمي أداة متابعة التغذية لحساب ما تناوله اليوم من الجبن أو الزبادي أو البروكلي، واستكملي ما ينقصه.'),
  ('d4efd00f-6d87-4868-a912-9b76b79425d0', 'عرض أمام المرآة 🤪', 'هل يعبس بوجهه وينظر إلى نفسه ثم ينفجر ضاحكًا؟ أضيفي فورًا مقطع فيديو لهذه اللحظة الطريفة التي يكتشف فيها ذاته إلى ألبوم طفلكِ، وتخلّصي من توتر اليوم.'),
  ('3f2f1108-7831-4796-88a8-5de7f4f81912', 'أنتِ أيضًا بحاجة إلى استراحة ☕', 'اخرجي من المنزل والتقطي أنفاسكِ قليلًا! ابحثي في الأماكن الصديقة للأمهات عن مقهى قريب يضم ركنًا للأطفال، واستمتعي بقهوتكِ الساخنة وتعرّفي إلى أمهات أخريات.'),
  ('875b72c1-d353-4eb2-8649-bca828613387', 'افتخري بنفسكِ 🌟', 'كل مهارة جديدة يتعلمها يوميًا، وكل خطوة واثقة يخطوها، هي ثمرة تفانيكِ. افتحي يوميات الحالة المزاجية واكتبي اليوم ملاحظة تستحقين أن تصفّقي لنفسكِ من أجلها بحرارة!'),
  ('9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1', 'هل يلوّح بالطعام ثم يرميه؟ 🥣', 'هل سئم الجلوس إلى المائدة وأصبح يرمي الملعقة؟ شغّلي مؤقت التغذية، وحلّلي مدة الوجبة عبر الرسم البياني، وتجنّبي تمامًا إجباره على تناول الطعام.'),
  ('4bafd57a-0f5f-4a7d-8215-cfd63b08cad2', 'هل يقتصر طعامه على لون واحد؟ 🟡', 'هل لا يريد سوى الأطعمة الصفراء (البطاطس، المعكرونة، الموز)؟ حلّلي قائمة طعامه باستخدام أداة متابعة التغذية، واكتشفي في وصفات الأطفال بدائل ملوّنة تحتوي على خضراوات مخفية.'),
  ('accea8e1-cb5f-4833-9081-056b6237ac04', 'الفرق بين «أنا» و«أنت» 🗣️', 'هل بدأ يتحدث عن نفسه مستخدمًا «أنا» بدلًا من صيغة الغائب؟ لدعم هذه القفزة الإدراكية الكبيرة، اسألي Anacan AI فورًا عن أسرار بناء حوار سليم.'),
  ('f9e8a36b-3135-4421-adad-49b6ce187cf2', 'حكاية أخرى فقط! 📚', 'هل يختلق أعذارًا جديدة بلا توقف لتجنّب الذهاب إلى السرير؟ شغّلي مؤقت النوم، وحافظي على الحدود، ثم شغّلي صوت أمواج المحيط من الأصوات البيضاء لتهيئة الغرفة للهدوء.'),
  ('52ee49fe-425d-44ef-9429-5ef1f4410d82', 'فن القفز 🦘', 'هل يحاول القفز من الدرج أو الأريكة؟ إنه بحاجة إلى مكان آمن لتنمية مهاراته الحركية. ابحثي في الأماكن الصديقة للأمهات عن مركز ترفيهي داخلي يضم ترامبولين، ووجّهي طاقته نحو نشاط مناسب.'),
  ('51803c0a-8b62-474c-8ecd-e45188efdf2a', 'لعبة طيّ الملابس 🧺', 'هل يريد مساعدتكِ أثناء جمع الملابس؟ أوكلي إليه مهمة مطابقة الجوارب! اقرئي في المدونات أسرار غرس الشعور بالمسؤولية من خلال اللعب.'),
  ('ede1e4a9-4d71-4eca-bacd-697cb6454edc', 'الخوف من الغرفة المظلمة 🌌', 'هل يبكي طفلكِ عند إطفاء الضوء؟ تزداد مخاوفه مع تطور خياله. شغّلي له صوت الرحم من قسم الضوضاء البيضاء لتمنحيه مجددًا شعوره القديم بالأمان.'),
  ('13aac5b4-c714-41fb-8e2e-16c1c92d8390', 'كيف ينشأ حب الكتب؟ 📖', 'هل يريد تمزيق الصفحات بدلًا من القراءة؟ اسألي Anacan AI عن طرق عملية لجذب انتباهه إلى الحكاية من دون الإضرار بعادة القراءة لديه.'),
  ('542e3a59-e25b-4803-a553-c3183744d2dc', 'سر الحديد: فيتامين C 🍋', 'لتحسين امتصاص الجسم للحديد، اطّلعي على قائمة طعام اليوم في أداة متابعة التغذية. واحرصي على تقديم سلطة غنية بالليمون أو الطماطم إلى جانب طبق اللحم.'),
  ('bb3d49d9-8e03-48af-9a82-d11c505ca32b', 'وقت قهوة الأم ☕', 'ضعي الأعمال المنزلية جانبًا وخذي نفسًا عميقًا! ابحثي في قسم الأماكن الصديقة للأمهات عن مقهى يضم ركنًا لألعاب الأطفال، واستمتعي بقهوتكِ الساخنة وتعرّفي إلى أمهات أخريات.'),
  ('0d828df8-79e8-40c6-a759-0255d981435d', 'صوت الليل: القطار 🚂', 'هل يزعجه الصمت المفاجئ بعد ضجيج النهار؟ شغّلي صوت القطار الرتيب من قسم الضوضاء البيضاء لحجب الأصوات الأخرى في المنزل ومساعدته على الاستعداد للنوم.'),
  ('8776b932-7a29-4e58-81cd-88646f84a4c7', 'هل أصبح الحذاء ضيقًا فجأة؟ 👟', 'هل يتعثّر أثناء الركض أو يحاول خلع حذائه؟ ربما كبرت قدمه! أدخلي قياساته الحالية في متتبّع النمو لمتابعة تطوره الجسدي على الفور.'),
  ('e742c56f-494a-46b7-82c7-113a5d4f0287', 'كرات طاقة من دون سكر 🍪', 'وداعًا لحلويات المتاجر! اكتشفي في وصفات الأطفال وجبات خفيفة صحية ولذيذة بالتمر والشوفان، تُحضَّر في 10 دقائق فقط، وأسعدي طفلكِ بها.'),
  ('81b85e80-d265-4f32-8c47-4b14aa23d8e1', 'نوبات عدوانية مفاجئة 🦖', 'هل يدفع أصدقاءه أو يحاول ضربكِ عندما يغضب؟ اسألي Anacan AI فورًا عن كيفية توجيه مشاعره العدوانية في هذه المرحلة العمرية بلطف.'),
  ('bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d', 'لا تنسي نفسكِ ⚡', 'هل تشعرين بالإرهاق عند الظهيرة؟ لا تلجئي إلى الحلويات! اختاري من الوصفات الصحية للنساء سموذي زبدة الفول السوداني الغني بالبروتين، لتحصلي على طاقة فورية وتستعيدي نشاطكِ.'),
  ('fdde906c-a398-4012-a073-4015f9852301', 'تحليل النوم بالمؤقت ⏱️', 'هل استغرق طفلكِ وقتًا طويلًا حتى ينام مساءً؟ شغّلي مؤقت النوم وتابعي المخطط. حلّلي ما إذا كان لم يفرّغ طاقته بالكامل أم أنه أُرهق أكثر من اللازم.'),
  ('63af320f-f496-491d-b573-f5b6663a91e4', 'شاي دافئ وهدوء 🍵', 'توقف المؤقت ونام طفلكِ. لا تقتربي من الأعمال المنزلية الآن! اختاري من الوصفات الصحية للنساء شاي المليسة، ودعي تعب اليوم يتلاشى مع بخاره الدافئ.'),
  ('86e064b7-8da1-4aa9-b551-ca85b1a25e7c', 'هل يحصل على ما يكفي من البروتين؟ 🍗', 'البروتين ضروري لعضلاته التي لا تتوقف عن الركض والقفز. استخدمي أداة متابعة التغذية لتقييم توازن غذائه اليومي وإثراء قائمة طعامه.'),
  ('947ec858-749d-4a0f-bf72-73a1503e2c5f', 'أسئلة «لماذا؟» التي لا تنتهي 🤔', 'ما هذا؟ ولماذا هو هكذا؟ لقد بدأت هذه المرحلة رسميًا! تعرّفي من خلال المدونات على كيفية الإجابة بصبر وبأسلوب يدعم نمو طفلكِ وفضوله الاستكشافي اللامتناهي.'),
  ('5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb', 'التسجيلات الصوتية القديمة 🎤', 'بعد أن ينام طفلكِ، افتحي ألبوم الطفل واستمعي إلى تلك الأصوات اللطيفة التي كان يصدرها قبل أشهر. اشعري بالفخر وأنتِ ترين مدى سرعة نموه!'),
  ('c3ea09ec-b61b-40ca-8245-a6b47232b78f', 'مرحلة «إنها لي!» 🧸', 'هل يرفض مشاركة ألعابه مع أي شخص في الحديقة؟ اسألي Anacan AI وتعرّفي على كيفية تعليم الطفل الذي يقترب من عمر 2.5 سنة مفهوم تبادل الأدوار في اللعب.'),
  ('0ba368ce-9746-48c2-a3e5-a973ee982121', 'عشق المعكرونة 🍝', 'هل يطلب طفلكِ الطعام نفسه منذ أيام؟ لقد بلغ انتقاؤه للطعام ذروته. ابحثي ضمن الوصفات الصحية عن صلصات مرحة يمكنكِ إخفاء الخضراوات فيها.'),
  ('92abce30-d667-4f40-9371-ee7642e09a28', 'مذاق الصمت 🤫', 'حلّ الهدوء أخيرًا في الغرفة. دعي المهام جانبًا واجلسي في الظلام. فعّلي مقياس الصوت لقياس مستوى هذا الصمت وأريحي ذهنكِ.'),
  ('e50a9ce1-a01a-4462-9bc9-e410e94685ff', 'أكملنا 800!🚀', 'حان الآن وقت المزيد من الأسئلة والحركة والاستقلالية. ابدئي هذه المرحلة الجديدة والمثيرة بنفَس عميق.'),
  ('0ea063ed-fd41-47e6-9ae7-1268a3f1138f', 'خرافات الأم المثالية 🛑', 'هل تلومين نفسكِ لأن وقت الشاشة طال اليوم؟ انسي صورة الأمهات المثاليات على الإنترنت. أنتِ رائعة بواقعكِ كما هو.'),
  ('6e5882b6-b1b9-4876-8253-b97551d73f12', 'ساحة لعب الأب 👨‍👧', 'هل بدأ صبركِ ينفد؟ أغلقي باب الغرفة واتركي طفلكِ وحده مع أبيه. دعيه يتولى قيادة ألعاب المنزل هذا المساء.'),
  ('c72b4558-e629-4a4b-bb39-ef072b6603b3', 'مرحلة «لماذا؟» 🤔', 'هل يسأل عن كل شيء: لماذا هو هكذا؟ دماغه يمتص المعلومات كالإسفنجة. تحلّي بالصبر وقدّمي له إجابات قصيرة ومنطقية.'),
  ('015a0c8f-c960-422b-8198-6bdb85909e68', 'هل كان يومًا صعبًا؟ 📝', 'أفرغي ما في قلبكِ بتدوين ضغوط اليوم في مفكرة المزاج. جميع الأمهات يمررن بهذه النوبات، ولستِ وحدكِ.'),
  ('5229a519-68a8-4340-8bba-d14464123530', 'ألعاب خيالية 🧸', 'هل يجعل السيارات تتحدث ويطعم دميته الدب؟ خياله ينطلق بلا حدود. سجّلي هذه القفزة المعرفية في متتبّع النمو وشاركيه اللعب.'),
  ('f8fbff5d-2a79-4ebc-90f5-c58d315a80ab', 'لديكِ بطارية أيضًا 🔋', 'هل تعبتِ من قول «لا» والركض طوال اليوم؟ أفرغي ما يثقل صدركِ في مذكرات المزاج. تذكّري أن تخصيص وقت لنفسكِ ليس رفاهية، بل ضرورة.'),
  ('fb79060e-f7c1-4e3e-983a-bf84e747b66e', 'الحذاءان معكوسان! 👟', 'هل يرتدي الحذاء الأيمن في قدمه اليسرى والأيسر في قدمه اليمنى ويرفض خلعهما؟ زيّني هذه المحاولة الطريفة للاستقلالية بملصقات مرحة في جلسة تصوير طفلكِ، وحوّليها إلى أطرف لقطة في الألبوم.'),
  ('10f0ddfb-06ae-4780-9b39-ba433d0edc10', 'موزة أم هاتف؟ 🍌', 'هل يضع موزة أو جهاز التحكم عن بُعد على أذنه ويجري محادثات خيالية؟ إنها قمة اللعب التخيلي! أضيفي هذه اللحظة الذهبية فورًا إلى ألبوم طفلكِ كمقطع فيديو بالصوت لتخلّديها في الذاكرة.'),
  ('24cc9d6f-2286-4f7a-a81a-633ab5dd91df', 'الخوف من الغرفة المظلمة 🌌', 'هل يتخيّل الأشياء في الغرفة وحوشًا عندما تطفئين الضوء؟ مع نمو الخيال قد تظهر المخاوف أيضًا. شغّلي له صوت الرحم من الأصوات البيضاء لتمنحيه ذلك الشعور القديم بالأمان التام.'),
  ('3c29abba-6cf4-47d2-a227-99611ccf0101', 'سر الحديد والطاقة 🥩', 'لوقاية طفلكِ النشيط من فقر الدم، تحقّقي من كمية الحديد التي تناولها اليوم (اللحوم، العدس، السبانخ) عبر أداة متابعة التغذية، وأثري قائمته الغذائية بأطعمة غنية بفيتامين C.'),
  ('074c97a3-66b5-4499-b8dd-c6ca41189da1', 'تناول السوائل والإمساك 💧', 'هل يركض كثيرًا لكنه يشرب القليل من الماء؟ راقبي برازه عند تغيير الحفاض. إذا كان هناك خطر للإصابة بالإمساك، فسجّلي ذلك في التطبيق وأضيفي فورًا أطعمة غنية بالألياف (الكمثرى، الشوفان) باستخدام أداة متابعة التغذية.'),
  ('33f7b16f-fd6e-4686-be50-8b9aabfa4a20', 'خبير الألوان والأشكال 🔴🟩', 'هل يصنّف المكعبات أو الأزرار أو الألعاب حسب ألوانها؟ اكتشفي الآن في قسم المنتجات الموصى بها أحجيات خشبية تنمّي المنطق وتتحدى قدراته الذهنية أكثر.'),
  ('912d3d15-f8b0-4ade-8219-5e9c81b99f0a', 'ذعر ليلي أم كابوس؟ 🤖', 'هل يستيقظ في منتصف الليل باكيًا ولا يهدأ؟ اطّلعي على مقالاتنا العلمية في قسم المدونات لفهم الفرق بينهما والتعامل مع الحالة نفسيًا بطريقة صحيحة.'),
  ('46ca17b0-646f-46ee-9f74-a67a0f778d4f', 'بطل الحكاية 🪄', 'أنشئي هذا المساء في «الحكايات الذكية» قصة مميزة يكون طفلكِ بطلها: الصغير الشجاع الذي يحب الليل.'),
  ('44efc816-fa09-4bf6-a073-38bbffbb2693', 'عناق «أحبكِ» 🫂', 'هل يأتي فجأة ليعانقكِ أو يداعب وجهكِ؟ لقد بدأ يعبّر عن حبه جسديًا. استمتعي بهذه اللحظة.'),
  ('764398f1-2f82-4a41-a767-bcf8004dd068', 'وضع الأشياء في مكانها 🧸', 'هل يضع اللعبة في الصندوق ثم يخرجها مجددًا؟ بدأ يتكوّن لديه مفهوم الداخل والخارج. احرصي على تسجيل هذه المهارة المعرفية في متتبّع النمو.'),
  ('850a613f-ecbc-4d9b-ab63-9701c3f268f9', 'هل لديكِ سؤال؟ 🤖', 'كيف ينبغي أن يكون تطور كلام الطفل بعد عمر سنتين؟ لا تتوهي بين معلومات الإنترنت؛ اكتبي مباشرةً إلى Anacan AI واحصلي على إجابة موثوقة مبنية على أسس علمية.'),
  ('4fcc8b4e-e106-490a-a901-8c89be671af5', 'الجمل الطويلة قادمة! 🗣️', 'هل بدأ يجمع 4-5 كلمات ليروي قصة طريفة؟ إنها طفرة في الحصيلة اللغوية! لا تفوّتي هذه اللحظة الذهبية؛ سجّلي صوته فورًا كذكرى في ألبوم طفلكِ، ووثّقي هذا التطور.'),
  ('569d530d-d6b9-4460-be46-292c62f656dd', 'رحلة البحث عن المنطق 🧩', 'لقد أتقن بالفعل ألغاز الصور البسيطة المكوّنة من قطعتين أو ثلاث. اكتشفي في قسم المنتجات الموصى بها ألعابًا خشبية أكثر تعقيدًا تتحدى ذكاءه وتساعده على فهم علاقة السبب والنتيجة.'),
  ('ce1a09c7-d2c5-485b-a920-bc02df41fb58', 'عاصفة في الحمّام 🛁', 'هل يرفض الخروج من الماء ويبكي؟ اسألي Anacan AI فورًا عن ألعاب تشتت انتباهه وطرق انتقال عملية تساعدكِ على إنهاء روتين الاستحمام من دون توتر.'),
  ('32be8503-ee3d-483e-baae-9b3b130b80cc', 'شجار على الدور عند الزحلوقة 🛑', 'هل يرفض انتظار الأطفال الآخرين في الحديقة؟ مع اقترابه من عمر 2.5 سنة، اقرئي في قسم المدوّنات مقالات التنشئة الاجتماعية لتتعرّفي إلى كيفية تعليمه مفهومَي انتظار الدور والمشاركة.'),
  ('36818534-e1f7-451b-9f88-51bf852bc139', 'تمرّد على القيلولة! ⏱️', 'هل رفض طفلكِ القيلولة وأصبح الآن مرهقًا للغاية؟ راجعي مخطط مؤقت النوم، وقدّمي روتين المساء 40 دقيقة على الأقل للوقاية من نوبات الذعر الليلي.'),
  ('54668cb8-852a-467f-9492-c88f3b1ba329', 'هل يحبس البراز؟ 💩', 'هل يقف ويحبس برازه مع اقتراب التدريب على استخدام النونية؟ قد يؤدي ذلك إلى إمساك نفسي. سجّلي هذا في متتبع الحفاضات، وأضيفي المشمش أو الشوفان إلى قائمته الغذائية فورًا.'),
  ('d3a86832-34ed-43f4-90d5-a80f77b22f80', 'ضاق ذرعًا بالبقاء بين أربعة جدران 🌳', 'هل يعجز عن تفريغ طاقته داخل المنزل فيقلب كل شيء ويرميه؟ افتحي خريطة الأماكن الصديقة للأمهات، واعثري على حديقة آمنة ذات أرضية لينة ومنزلقات، ودعيه يلعب بحرية في الهواء الطلق.'),
  ('24023d7c-2bc9-4102-89e5-fd869c13910d', 'طفرة في الطول والوزن! 📏', 'هل لاحظتِ عند إلباسه أن قمصانه أصبحت ضيقة أو أن حذاءه بات يضغط على قدميه؟ أدخلي طوله وقياساته الحالية في متتبع الوزن، وشاهدي بفخر كيف يرتفع منحنى نموه.'),
  ('af6b0980-8f3e-49f7-8539-9fc05967e656', 'تحققي من مخزون الحديد 🥩', 'هل يبدو شاحبًا أو يتعب بسرعة؟ تحققي من كمية الحديد التي تناولها اليوم في أداة متابعة التغذية، وقدّمي له مع اللحم مصدرًا لفيتامين C (كالليمون أو الطماطم) لتعزيز امتصاص الحديد.'),
  ('f5e0ef2c-4838-48df-b45d-d158a473879a', 'أنتِ أيضًا بحاجة إلى صديقات 👯‍♀️', 'هل تعبتِ من التحدث طوال اليوم بلغة الأطفال فقط؟ استخدمي الأماكن الصديقة للأمهات للعثور على مقاهي الأطفال التي ترتادها الأمهات بكثرة، وامنحي نفسكِ فرصة للتواصل الاجتماعي أيضًا.'),
  ('3046868d-cc9d-4ca4-8350-b813468ec4dd', 'احتياجات عاجلة 🛒', 'هل نفد الشامبو أو حفاضات الأطفال أو الشوفان؟ لا تعتمدي على ذاكرتكِ، بل دوّنيها في قائمة التسوق وزامنيها مع شريككِ.'),
  ('437a3027-38a4-47b2-a62c-a24094b2e7eb', 'هل يرمي نفسه على الأرض ويصرخ عندما لا يحصل على ما يريد؟', 'لا تزال نوبات الغضب شائعة في هذه المرحلة العمرية. ابقي بالقرب منه بهدوء، وعانقيه عندما يهدأ.'),
  ('bbf3c14f-5832-4554-88a9-fc0b10c25324', 'الصفحات تنبض بالحياة 📖', 'هل يبتكر طفلكِ نهاية القصة أثناء قراءتكِ لها؟ اكتشفي عبر Anacan AI تقنيات القراءة التفاعلية التي تدعم هذه اللحظة الرائعة من الخيال.'),
  ('c3d03381-340f-4ce1-b075-de3e6584aed7', 'شرب السوائل والإمساك 💩', 'هل يركض كثيرًا ويشرب القليل من الماء؟ راقبي برازه عند تغيير الحفاض (أو استخدام النونية). إذا كان معرّضًا للإمساك، فسجّلي ذلك في التطبيق وأضيفي البرقوق المجفف أو الشوفان إلى قائمته الغذائية فورًا باستخدام أداة متابعة التغذية.'),
  ('275e7b7b-377b-40f0-9e43-ab5886fc93b4', 'يلعب بالطعام 🥦', 'هل يسحق المعكرونة وينثرها حوله بدلًا من تناولها؟ في هذا العمر، يُعد الطعام لعبة أيضًا. سجّلي مقدار ما تناوله في خطة التغذية لتتمكني من متابعة التوازن الأسبوعي.'),
  ('7af19435-be8e-48dc-a066-aab689899f04', 'فيلسوف الصباح 🧦', 'هل أراد هذا الصباح أن يرتدي جوربه في يده؟ لا تنزعجي من لحظات الاستكشاف هذه المصحوبة بالعناد. دعيه يتجول هكذا قليلًا؛ فهذه طريقته في اختبار استقلاليته.'),
  ('f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7', 'قوة الماء السحرية 🛀', 'لقد أرهقكما الركض طوال اليوم. فالحمام الدافئ ليس للنظافة فحسب، بل هو أفضل وسيلة لتهدئة جهازه العصبي.'),
  ('1b2a22e9-6d73-4469-8535-2d773936acd1', 'الأنانية في الحديقة 🧸', 'هل يرفض إعطاء دلوه لأي شخص أثناء اللعب بالرمل؟ لا يزال مفهوم المشاركة ضعيفًا جدًا في عمر ٢٧ شهرًا تقريبًا. لا تتهميه بالأنانية، بل اشرحي له ببساطة مبدأ تبادل الأدوار.'),
  ('57e50587-fc65-4605-a4e9-bbde134adfea', 'نبرة صوت الأب 📖', 'لنُضفِ هذا المساء أجواءً مختلفة على الغرفة. أوكلي مهمة قراءة الكتاب أو سرد الحكاية إلى صوت الأب العميق والمطمئن، وخذي قسطًا من الراحة جانبًا.'),
  ('64f0ac54-c21f-4a4c-bcce-53662284a4f5', 'ذاكرة مذهلة 🧠', 'هل عثر هذا الصباح بدقة على اللعبة التي أخفيتِها بالأمس؟ لقد تطورت ذاكرته طويلة الأمد بصورة مذهلة.'),
  ('71700719-be0c-45bf-8d93-6cb51d48ed2d', 'دودة الكتب 📖', 'هل يجلب كتاب الحكايات المفضل لديه ويطلب منكِ قراءة الصفحة نفسها مرارًا وتكرارًا؟ التكرار هو طريقته في التعلّم. أعيدي قراءتها له بصبر.'),
  ('d6aaa644-5d8a-47cd-b998-227fc0b6f04b', 'يمكن للأعمال المنزلية أن تنتظر 🛑', 'لم تُمسح الأرضية؟ دعيها كما هي. يمكن تنظيف المنزل المتّسخ، لكن تعافي الأم المنهكة يستغرق وقتًا طويلًا. استلقي على الأريكة وأنصتي إلى السكون.'),
  ('04312503-34be-494a-8896-38312d406a86', 'طقم الشاي الخيالي 🫖', 'هل يصرّ على أن تشربي أنتِ أو ألعابه الشاي بأكواب خيالية؟ لعب الأدوار هو ذروة التطور الذهني!'),
  ('149beadc-5c37-404b-8b3e-f6ce437629da', 'آلام رقبة الأم 🧘‍♀️', 'هل تيبّست رقبتكِ وظهركِ من اللعب على الأرض وحمل طفلكِ؟ استريحي مع كوب من الشاي الأخضر بالزنجبيل، الذي يساعد على إرخاء العضلات ومقاومة الالتهاب، ويمكنكِ تحضيره من قسم الوصفات الصحية.'),
  ('2daba5bf-3da2-43ab-bc87-fdc726c1aabb', 'وحش تحت السرير؟ 👾', 'كلما تطوّر الخيال، بدت المخاوف أكثر واقعية. إذا كان يخاف من الظلال، فخفّفي الإضاءة وشغّلي له صوت الرحم (نبضات القلب) من قسم الضوضاء البيضاء، لتمنحيه ذلك الشعور القديم بالأمان التام.'),
  ('d0a47f18-7e98-462c-be4f-167fcf918411', 'شجار انتظار الدور عند الزحليقة 🛑', 'ألا يريد انتظار الأطفال الآخرين في الحديقة؟ مع اقترابه من عمر 2.5 عام، احرصي على قراءة مقالات التنشئة الاجتماعية في قسم المدونات لتتعلمي كيفية غرس مفهومي انتظار الدور والصبر لديه.'),
  ('dc66703c-31b3-4677-a6cd-dc09bb5b60cf', 'لا تشعري بالذنب 💖', 'هل أفقدكِ عناده اليوم صبركِ فارتفع صوتكِ؟ أفرغي ما يثقل صدركِ في يوميات المزاج. أنتِ لستِ آلة، ولستِ مضطرة إلى أن تكوني مثالية!'),
  ('f9ec5212-0b50-47f7-b50f-84f41a8701a2', 'موضة ارتداء الملابس بالمقلوب! 👕', 'هل ارتدى سرواله بالمقلوب وحذاءه في القدم الخطأ، ثم رفض خلعهما؟ لا تتدخلي في محاولة الاستقلال الطريفة هذه!'),
  ('f0d11fbf-f594-485d-b316-f567d5c6731d', 'هل مللتِ من البقاء في المنزل؟', 'اكتشفي ضمن الأماكن الصديقة للأم مقهًى يضم ركنًا لألعاب الأطفال. دعي طفلكِ يلعب واستمتعي بقهوتكِ ساخنة.'),
  ('b9ab0ee4-3e32-4c6f-9669-cbb581181150', 'سكينة على أنغام الموسيقى 🎶', 'أسهل طريقة لتهدئة نوبات التذمر في المساء هي تشغيل لحنه المفضل، واحتضانه والرقص معه ببطء.'),
  ('c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6', 'هل بقيتِ في المنزل لأن الطقس متقلب؟', 'دعي أداة الطقس والملابس تخبركِ فورًا بدرجة الحرارة التي لا يمكنكِ تقديرها من خلف النافذة، ثم اخرجي إلى الحديقة.'),
  ('ce87972f-2f28-45fe-80b3-aa0ec4116930', 'سأرتدي ملابسي بنفسي 👕', 'حتى لو وضع سرواله على رأسه، فلا تعيقي محاولاته لارتداء ملابسه بنفسه. فرغبته في الاستقلال في ذروتها! امنحيه الوقت ودعيه يجرّب.'),
  ('43a750e7-aff2-4c1a-baec-6890bc56e642', 'سأسكب بنفسي! 🥛', 'هل يريد سكب الماء في الكوب بنفسه فيبلل كل شيء؟ سهّلي مهمتكِ بالبحث في المنتجات الموصى بها عن أكواب أطفال ذكية مانعة للانسكاب، تساعده على تطوير مهارات الحياة العملية.'),
  ('8d131ccb-5e19-4d42-b8a6-86bf255b1f23', 'الطاهي في المطبخ 👩‍🍳', 'حضّرا معًا عجينة بسكويت بالموز خالية من السكر، من وصفات الأطفال. دعيه يطوّر مهاراته الحركية ويستمتع في الوقت نفسه بتناول ما صنعته يداه بشهية.'),
  ('bd7400ff-b3f7-4318-9c68-166242aa98f9', 'شاي ساخن وهدوء 🍵', 'انتهى المؤقت ونام طفلكِ. لا تسرعي إلى الأعمال المنزلية! حضّري شاي المليسة أو البابونج من الوصفات الصحية، واستلقي على الأريكة واستمتعي بالهدوء فحسب.'),
  ('65e69d4e-9f8b-4e23-8934-10178d918f6b', 'ما لكَ لي أيضًا! 🧸', 'هل يرفض إعادة لعبة طفل آخر في الحديقة؟ إنها مرحلة التمركز حول الذات. علّميه المشاركة بالتناوب، لا بالإجبار.'),
  ('1fe350a6-fb9b-4b57-8832-dec2f74e4b97', 'ماراثون الجري 🏃‍♂️', 'أصبح المشي مملًا بالنسبة إليه، فهو لا يفعل سوى الركض! أزيلي العوائق الصغيرة من وسط الغرفة، وراقبي هذه الطاقة التي لا تنضب بابتسامة.'),
  ('a661f7cf-1a9f-46de-b66d-252b9874aa1c', 'ألعاب الظلام 🐰', 'لا يريد النوم ويخاف من الظلام؟ أظلمي الغرفة تمامًا واصنعي بيديكِ مسرحًا للظلال على الحائط. حوّلي خوفه إلى متعة.'),
  ('a8a8e76c-4244-41ff-a34c-127f03070b5f', 'وقت الأم بلا إنترنت ☕', 'عندما ينغمس طفلكِ في عالمه ويتحدث إلى دُماه، لا تسارعي فورًا إلى غسالة الصحون. حضّري لنفسكِ فنجانًا من القهوة، وضعي هاتفكِ جانبًا أيضًا، وابتعدي تمامًا عن الإنترنت لمدة 15 دقيقة.'),
  ('41bea9aa-47ca-48e8-8cd4-15b1a0a181a6', 'أولى الجمل الطويلة 🗣️', 'ماما، ذهبت السيارة إلى هناك! لقد أصبح الآن يربط الكلمات معًا ويكوّن جملًا ذات معنى. أنصتي إلى هذه اللحظات التاريخية، واحرصي على تدوينها كذكرى في متتبّع النمو.'),
  ('69b61ce4-2f0a-419f-8ea0-47c763ae7f20', 'استراحة للقراءة في المدوّنة 📱', 'هل حان الوقت المناسب لبدء التدريب على استخدام النونية؟ إذا كنتِ مترددة، فادخلي إلى قسم المدوّنات في تطبيق Anacan واقرئي المقالات التي كتبها مختصون واعتمدها أطباء الأطفال.'),
  ('8ba7811e-fc92-4ddc-b1e8-28de83aa7843', 'تحليل اليوم 📝', 'هل كان يومًا صعبًا؟ دوّني كل ضغوط اليوم في يوميات الحالة المزاجية لتبوحي بما في داخلكِ. تمرّ جميع الأمهات بنوبات الغضب الصعبة هذه، ولستِ وحدكِ.'),
  ('3932254a-4956-424d-86dc-117f82815e3f', 'رفض شرب الماء 💧', 'هل يطلب باستمرار العصائر المحلّاة بدلًا من الماء؟ احسبي احتياجه اليومي من الماء، وقدّميه له في أكواب ملوّنة وجذابة.'),
  ('7f344552-48d5-4a0e-95d3-b9aa7199f33a', 'حكايات من نسج الخيال 🎭', 'هل يجعل دميته الدب تتحدث ويروي لها حكايات من نسج خياله؟ لقد انطلق خياله بلا حدود! راقبيه من بعيد ولا تتدخلي إطلاقًا.'),
  ('eda9b33e-46f7-44ed-b1db-b9ad146b53a3', 'لا ننام من دون حكاية 🪄', 'ألم تعد الحكايات الكلاسيكية تجذب انتباه طفلكِ؟ أنشئي في الحكايات الذكية حكايةً خاصة يكون طفلكِ بطلها.'),
  ('67860791-a8d9-49e2-af36-c3429ea56929', 'الفوضى جميلة 🌪️', 'هل سئمتِ من جمع الألعاب نفسها في الصندوق كل يوم؟ لا تجمعيها اليوم! فوضى المنزل ليست نهاية العالم، وراحتكِ النفسية أهم.'),
  ('a0432486-9631-45f3-ac61-64c5dc937b54', '10 دقائق بمفردكِ 🛀', 'ساد الهدوء في الغرفة. اطلبي من شريككِ أن يتولى إدارة كل شيء في المنزل، واستمتعي أنتِ بحمّام دافئ واقضي 10 دقائق على انفراد مع نفسكِ.'),
  ('fc396394-677d-4b99-a945-20af7aec5056', 'الكالسيوم لا يقتصر على الحليب 🧀', 'هل يرفض طفلكِ شرب الحليب؟ الكالسيوم ضروري للعظام. استخدمي أداة متابعة التغذية اليوم لحساب ما تناوله من الجبن أو الزبادي أو البروكلي، وعوّضي أي نقص.'),
  ('40c67b1f-86cb-4258-ae34-ac9f630e9bcd', 'نادي التضامن 💬', 'هل تشعرين بإرهاق شديد وأن لا أحد يفهمكِ؟ اكتبي فورًا إلى مجتمع Anacan. ستجدين هناك آلاف الأمهات اللواتي يعانين مثلكِ من قلة النوم ومستعدات لدعمكِ.'),
  ('5fa2d1b1-040b-4c74-81f7-5aaa581e81fc', 'عناد بلا منطق 🛑', 'هل قامت الدنيا هذا الصباح لأنكِ قدّمتِ الماء في كوب أحمر بدلًا من الأزرق؟ هذا ليس دلالًا، بل يحاول طفلكِ فقط اكتشاف مدى قدرته على التحكم في عالمه. تحلّي بالصبر.'),
  ('6555b02b-e564-49b7-b5ae-a0b3594560b0', 'كنز من الفيتامينات 🥗', 'تفعلين كل ما بوسعكِ ليشبع طفلكِ، لكن ماذا عنكِ أنتِ؟ اختاري من الوصفات الصحية وجبة غداء غنية بالحديد والكالسيوم تُحضَّر في 10 دقائق، واستعيدي طاقتكِ.'),
  ('74e20827-e129-489b-a3ba-b3145efc42b3', 'أمام المرآة 👀', 'هل يقف طفلكِ أمام المرآة، ويقلّد تعبيرات مختلفة، ويضحك مع نفسه؟ هذا دليل رائع على وعيه بذاته. راقبيه خلسةً واستمتعي بهذه اللحظات الطريفة.'),
  ('3e22553e-b182-4faa-9fc2-459fc9a92590', 'نوبات العناد 🛑', 'هل تُشعركِ نوبات الغضب التي تحدث في المتجر أو الحديقة بالإحراج؟ تذكّري أن المهم ليس ما يفكر فيه المحيطون، بل مشاعر طفلكِ في تلك اللحظة. تواصلي معه بصريًا وساعديه على الهدوء.'),
  ('e37f9999-21b9-4b48-be42-d9cbbc3d9c55', 'محاولات القفز 🤸‍♂️', 'هل يحاول القفز من الأريكة إلى الأرض أو القفز في الهواء وهو واقف؟ مهاراته الحركية الكبرى تتحسن! شجّعيه.'),
  ('ebbeae36-6d1a-428b-bb72-2ef8bd324080', 'لنحلّل الروتين بالكامل ⏱️', 'هل استغرق الخلود إلى النوم مساءً 40 دقيقة؟ راجعي مخطط مؤقت النوم. ربما حان الوقت لتقصير قيلولته النهارية كثيرًا وتقديم موعد نومه مساءً.'),
  ('1240eee6-bdc5-4609-ba23-b9d212dcb809', 'استكشاف الطبيعة ⛅', 'البقاء بين أربعة جدران يخنقكِ. افتحي أداة الطقس والملابس، وألبسيه بما يناسب حالة الطقس، ثم اصطحبيه فورًا إلى الحديقة ليستكشف أوراق الأشجار والحجارة.'),
  ('1e908b82-2f19-4ebe-b79e-40246a88bab7', 'استمتعي بالهدوء 🤫', 'لقد نام أخيرًا. والآن يزعجكِ حتى أخف صوت في المنزل. ضعي سماعات الأذن، ومن دون الاستماع إلى أي شيء، استمتعي فقط بقيمة الصمت.'),
  ('488aec04-c9ee-4eb7-9fb1-11c9a4093d08', 'اكتشاف الألوان 🎨', 'عندما تطلبين منه الكرة الحمراء، هل يشير إلى الحمراء تحديدًا؟ لقد بدأ بالفعل في التمييز بين الألوان. سجّلي هذه المرحلة الإدراكية الجديدة في متتبع النمو.'),
  ('3be3de73-5fca-4eff-b43e-5882d476d692', 'حجة «لقد شبعت» 🥣', 'هل يأكل ملعقتين ثم يقول إنه شبع ويهرب؟ لا تجبريه. جرّبي تقديم حصص صغيرة له، ولكن على فترات متقاربة.'),
  ('9e9231eb-622b-4591-8fb2-b2c0bedcc252', 'التعرّف إلى أجزاء الجسم 👀', 'عندما تسألينه: «أين كتفاك؟»، هل يلمسهما بإصبعه ويشير إليهما؟ قدراته الإدراكية في أوجها! واصلي اللعبة باستخدام أجزاء أكثر تعقيدًا من الجسم.'),
  ('99e86be1-9932-47a0-b9a8-f6b98dc7dfcf', 'مقاومة النوم 🥱', 'هل يرفض طفلكِ أخذ قيلولة الظهر ويقاوم النوم؟ يتوقف بعض الأطفال في هذا العمر عن أخذ القيلولة. بدلًا من الجدال، خصّصي «ساعة للهدوء» وتصفّحا كتابًا في السرير.'),
  ('f80a3604-81aa-4362-9508-4aa4c845b4bc', 'صوتيات الغرفة 🤫', 'هل يفزع طفلكِ من أدنى صوت بمجرد أن ينام؟ تحققي من مستوى الضوضاء في الغرفة باستخدام مقياس الصوت، وشغّلي الضوضاء البيضاء لحجب الأصوات القادمة من النافذة.'),
  ('25092d10-5861-4eec-8fa9-86857d835418', 'المساعد الصغير 🧹', 'هل يحاول طفلكِ أخذ الملابس أو الممسحة من يدكِ عندما تطوين الغسيل أو تمسحين الأرض؟ إنه يشعر بأنه أصبح كبيرًا. أعطيه قطعة قماش صغيرة ودعيه يساعدكِ.'),
  ('739e50cd-5199-4e7e-9448-99a52d59a069', 'قلعة الوسائد 🏰', 'حوّلي الغرفة هذا المساء إلى ساحة للعب. اصنعا قلعة صغيرة من وسائد الأريكة وادخلا إليها. ستعمّ بعض الفوضى، لكن هذه الضحكات تستحق ذلك بالتأكيد.'),
  ('a9e6d37d-aa66-4119-abcb-6619dfc78256', 'اختبار الانتباه 🧩', 'هل أصبح طفلكِ يلعب بلعبة واحدة لمدة 10-15 دقيقة؟ هذا يعني أن مدة تركيزه آخذة في الازدياد.'),
  ('1a9b02d2-5d73-4e72-a7df-f4672edf0835', 'روتين النوم مع الأب 👨‍🍼', 'دعي الأب يتولى الليلة تحضير طفلكِ للنوم، وتنظيف أسنانه وإلباسه ملابس النوم، واستمتعي بكوب من الشاي في هدوء.'),
  ('6c74968c-8cc0-4bee-8ae3-eae708b5b244', 'حيرة قائمة الطعام 🍲', 'أما زلتِ لا تعرفين ماذا ستطبخين اليوم؟ لا تتيهي في البحث على الإنترنت، بل اكتشفي وصفات جديدة وسهلة في مقالات تغذية الأطفال ضمن قسم المدونات في التطبيق.'),
  ('855cedcf-292a-4a61-b049-6fd355b3a599', 'استكشاف السبب والنتيجة 🤔', 'ماذا سيحدث إذا رميتُ هذا؟ ما وظيفة هذا الزر؟ يجري طفلكِ باستمرار تجارب عملية لاستكشاف ما حوله. راجعي إجراءات السلامة في المنزل مرة أخرى.'),
  ('380a71ea-f755-4ca8-a25d-c156eefcd118', 'عدم البكاء عند السقوط 🧗‍♂️', 'عندما يسقط طفلكِ سقطة خفيفة، هل ينظر إلى رد فعلكِ قبل أن يقرر البكاء؟ لا تهلعي، بل ابتسمي وقولي له: لا بأس، أنت قوي.'),
  ('77a38e1b-ddf2-4519-806e-48198f93ac3a', 'هل يخاف من الظلام؟  🌙', 'ضعي مصباحًا ليليًا صغيرًا ذا ضوء دافئ بجانب سريره. وأبقي بقية الغرفة مظلمة تمامًا للمساعدة على إفراز الميلاتونين.'),
  ('b3b925ae-8f35-4c41-918e-ce24c80daa1b', 'عداوة الخضراوات 🥦', 'هل يبعد جميع الخضراوات الموجودة في الحساء؟ ابحثي له عن بدائل متنوعة ضمن خطة التغذية. وإخفاء الخضراوات داخل كرات اللحم من أقدم حيل الأمهات.'),
  ('16c277b4-79fe-460a-b9a5-72a7e8683280', 'لا وجود للأم المثالية 💬', 'هل تشعرين بالسوء لأنكِ لا تستطيعين إنجاز كل شيء في آن واحد؟ انضمي فورًا إلى مجتمع Anacan. ستمنحكِ اعترافات الأمهات الصادقة هناك القوة.'),
  ('2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86', 'شغف الخربشة 🖍️', 'بدأت طريقة إمساكه بالقلم تتغير، وأصبح يرسم خطوطًا مقصودة على الورق. احرصي على تسجيل هذا التقدم الرائع في المهارات الحركية الدقيقة ضمن متتبّع النمو.'),
  ('72b641f0-637f-48cd-8a37-fcd8fc3414bf', 'جرعة القهوة ☕', 'لقد أنهككِ الركض طوال النهار. دعيه ينشغل بمفرده لمدة 15 دقيقة بنشاط آمن، مثل التلوين، واحرصي على الاستمتاع بجرعتكِ من القهوة.'),
  ('35817a20-39d6-4243-8610-08e856df9e52', 'رميات دقيقة ⚾', 'هل بدأ يحاول التقاط الكرة الكبيرة التي ترمينها إليه بذراعيه، بل ورميها إليكِ مجددًا؟ يتطور التناسق بين عينيه ويديه بسرعة. العبا بالكرة معًا في الممر.'),
  ('801c2145-44f5-4f5c-b680-cdaa0cf58a86', 'انتقال موسيقي 🛀', 'هل أصبح الروتين المسائي صعبًا؟ شغّلي موسيقى كلاسيكية هادئة في الخلفية أثناء استحمامه بماء فاتر. فتناغم الماء والموسيقى يهدّئ حتى أكثر الأطفال عنادًا.'),
  ('df6798e4-19ad-45ba-b5f8-d0bab8fc0951', 'حكايات من الخيال 📖', 'هل مللتِ من قراءة الكتب؟ أطفئي الأنوار، وشغّلي صوت المطر من قسم الضوضاء البيضاء، وابتكرا معًا حكايات خيالية في الظلام حتى تغطّا في النوم.'),
  ('ebf1eb36-04dc-42ad-9b92-cfc852cf267d', 'اكتشافات بنكهة الفاكهة 🍏', 'هل يرفض طفلكِ البروتين أو الخضراوات؟ احسبي احتياجه اليومي باستخدام أداة متابعة التغذية، وابتكري من وصفات الأطفال تركيبات شهية مثل الزبادي بالفواكه.'),
  ('14a13bdc-ca07-4dfa-9231-806da316a5bd', 'العدّ على الأصابع 🔢', 'هل يحاول طفلكِ قول واحد، اثنان، ثلاثة عند صعود الدرج أو ترتيب السيارات؟ هكذا تُرسى أسس التفكير الرياضي. عدّي معه كل شيء بصوت مرتفع.'),
  ('8bf6a243-dbba-488e-976d-ab76ac22fdef', 'نَفَس عميق 🧘‍♀️', 'لقد جفّ حلقكِ من الإجابة عن الأسئلة طوال اليوم. ما إن يسود الهدوء في الغرفة، استريحي بأخذ أنفاس عميقة فحسب، من دون النظر إلى أي شاشة.'),
  ('c86b2cf3-2c86-4802-abd7-eac1fbe8e326', 'شاي دافئ وهدوء 🍵', 'توقف المؤقت ونام طفلكِ. لا تسارعي إلى أداء الأعمال المنزلية! حضّري شاي المليسة أو البابونج من الوصفات الصحية، واستلقي على الأريكة واستمتعي بالهدوء فقط.'),
  ('37bdad79-de07-4752-a75a-2761546b1523', 'المشاركة صعبة 🧸', 'هل يتصرف طفلكِ بقسوة مع أخيه أو مع طفل في الحديقة؟ لا تزال المشاركة مفهومًا مجردًا بالنسبة إليه. لا تعاقبيه، بل أظهري له أنكِ تتفهمين مشاعره.'),
  ('966fb5ae-0b22-47d8-b524-7d0d8e3e8e61', 'حفلة شاي خيالية 🍵', 'هل يُشرككِ طفلكِ في ألعابه الخيالية ويطلب منكِ شرب الشاي من كوب فارغ؟ كوني جزءًا من خياله. فهذه الألعاب تُنمّي ذكاءه الاجتماعي.'),
  ('cab52685-d8da-4cce-a78e-b76068863ea1', 'حكاية الأب 📖', 'أريحي أحبالكِ الصوتية هذا المساء. ودعي الأب يتولى مهمة قراءة كتب طفلكِ المفضلة بأصوات مختلفة وبطريقة طريفة.'),
  ('dfbc5f7d-d4f2-4480-8272-664e257700f7', 'معركة البيجاما 👕', 'هل يتحول ارتداء الملابس مساءً إلى معركة كبيرة؟ اتركي له حرية الاختيار: هل تريد البيجاما البيضاء أم الزرقاء؟ غالبًا ما تنجح هذه الحيلة.'),
  ('437d195c-2ce7-46eb-a38c-e5ab8476f991', 'لعبة طفل آخر 🧸', 'هل يرفض طفلكِ إعطاء لعبته لطفل جاء ضيفًا إلى المنزل؟ هذا ليس أنانية، بل حفاظ على حدوده الشخصية. علّميه المشاركة بالقدوة، لا بالإجبار.'),
  ('49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875', 'نطق الكلمات 🗣️', 'هل ينطق بعض الكلمات بشكل ناقص أو طريف جدًا؟ لا تضحكي، بل كرري له النطق الصحيح بنبرة واضحة حتى يرسّخه دماغه.'),
  ('d03e0dcf-56bb-436b-bb3e-19d3231b91eb', 'اشتباه في الرعب الليلي 😭', 'هل يبكي طفلكِ في منتصف الليل وعيناه مغمضتان ولا يهدأ؟ أسمعي صوته فورًا لميزة تحليل البكاء. أحيانًا لا تكون غازات فحسب، بل نوبة رعب ليلي.'),
  ('42301ed7-ed5e-4c5a-a79b-59b5256decae', 'تقلّب المزاج صباحًا ☁️', 'هل يبكي طفلكِ على كل شيء بمجرد أن يفتح عينيه ولا يرضيه شيء؟ ربما يكون في خضم طفرة نمو. احتضنيه كثيرًا وامنحيه شعورًا بالأمان.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('4611486b-3235-40ef-8f07-a9ac44bd4de8'::uuid, 'دعيه يتّسخ 🏖️', 'هل يريد طفلكِ اللعب بالطين أو الرمل في الحديقة؟ دعيه يتّسخ! اعثري عبر التطبيق على أفضل الأماكن الصديقة للأمهات لممارسة هذا النشاط الداعم للتطور الحسي.'),
  ('b8751eb5-8b11-4040-9350-f54539cfefa1', 'روح الفريق 🥂', 'لقد اجتزتما يومًا صعبًا. بعد أن ينام طفلكِ، حضّرا كوبًا من الشاي وقدّرا جهود بعضكما قائلين: نحن ننجح فعلًا في هذه المهمة.'),
  ('dc029c20-8f5d-4aa9-a173-be7d3be13a69', 'كيف تشعرين؟ 🩸', 'هل انخفضت طاقتكِ فجأة أم أصبح مزاجكِ متقلبًا؟ ألقي نظرة على متتبّع الدورة الشهرية في التطبيق. ستساعدكِ متابعة دورتكِ الشهرية على تفهّم احتياجات جسمكِ بصورة أفضل.'),
  ('e1b2a066-88e9-4a4f-9df5-3af6a5d26b79', 'رفض القيلولة 🥱', 'ألم يخلد إلى النوم مجددًا؟ لا تدخلي في صراع يرهقكما معًا. فتصفّح كتاب بهدوء في الغرفة يُعدّ أيضًا نوعًا من الراحة للدماغ.'),
  ('17487e3f-403d-4b65-ab45-c514d335d8cb', 'التعبير عن المشاعر 📝', 'هل شعرتِ اليوم بإرهاق شديد، أم قال طفلكِ عبارة لطيفة جدًا؟ في كلتا الحالتين، افتحي يوميات المزاج وسجّلي هذه اللحظة لتبقى ذكرى في المستقبل.'),
  ('343623a3-2f2a-4afd-99aa-b377f0610f4c', 'معركة تنظيف الأسنان 🦷', 'ألا يسمح لكِ بتقريب الفرشاة من فمه؟ حوّلي الأمر من إجبار إلى لعبة. دعيه ينظف أسنانكِ أولًا، ثم يأتي دوركِ.'),
  ('7022b1d9-81c4-428f-be96-d38885bd2971', 'اللعب الحر 🧸', 'لستِ مضطرة إلى تسليته في كل دقيقة. فالملل لدى الأطفال هو بداية الإبداع. دعيه يستكشف شيئًا ما بمفرده في الغرفة.'),
  ('561010fd-17de-4698-b582-1c91bc73389a', 'فقط عانقيه 🫂', 'لا حاجة إلى أي أدوات أو كتب أو حكايات. هذا المساء، فقط ضمّيه إلى صدركِ، واستنشقي رائحته، واهمسي له بحبكِ في الظلام.'),
  ('927b3990-20b2-4f48-94c1-3ea0663bfcd4', '«لا» الحازمة 🛑', 'هل يبتعد ويقول «لا» عندما يحاول أحد تقبيله؟ احترمي حدوده الجسدية وألزمي الآخرين باحترامها أيضًا. فمن هنا تبدأ الثقة بالنفس.'),
  ('f73f1d7d-92d7-412b-a0e4-c0f949786729', 'تصفّحي المدوّنات 📱', 'هل تجدين صعوبة في التعامل مع نوبات غضب طفلكِ في عمر السنتين؟ اقرئي المدوّنات النفسية في تطبيق Anacan. ففهم ما يحدث في دماغ الطفل أثناء نوبة الغضب سيُسهّل عليكِ التعامل معها.'),
  ('7281bfed-2cc1-421c-942f-77684085a8cf', 'وقت الحكاية الذكية 🪄', 'ابتكري له هذا المساء مغامرة خاصة ضمن الحكايات الذكية: قصة الأرنب الشجاع الذي شعر بالخوف. ساعديه على تجاوز مخاوفه من خلال الحكايات.'),
  ('e96ff0af-1a62-4cbe-8543-0ed5c9498c20', 'فوضى المنزل 🌪️', 'هل تعود الغرفة التي تنظفينها كل يوم إلى الفوضى خلال 5 دقائق فقط؟ لا بأس! فالمنزل ليس متحفًا، بل مكان ينبض بالحياة. لا تركّزي على الفوضى، بل على فرحة طفلكِ.'),
  ('fa5b66d9-39b4-43f8-b655-5b6b176b299f', 'استيقاظ المخاوف 👻', 'هل أصبح يخاف من صوت المكنسة الكهربائية الصاخب ويختبئ خلفكِ، مع أنه لم يكن يخشاه من قبل؟ مع تطور الخيال، قد تظهر مخاوف غير مبررة. ربّتي عليه بحنان وامنحيه الشعور بالأمان.'),
  ('7b50e55a-c023-4d17-aacb-ffa1852fdee2', 'النعاس في عينيه 🥱', 'رغم شعوره بالنعاس، يرفض تمامًا الذهاب إلى السرير. اجعلي روتين هذا المساء مختلفًا قليلًا. وبدلًا من قراءة كتاب، استلقيا في السرير وذكّريه بالأحداث الجميلة التي عاشها اليوم.'),
  ('a4e24e0d-5f22-40d2-b64c-109e7cec356e', 'دفعة من الطاقة ⛅', 'هل يكاد طفلكِ يتسلق جدران المنزل؟ لا بد أن يفرّغ طاقته. راعي حالة الطقس واختاري له ملابس مناسبة، ثم اصطحبيه إلى الحديقة ودعيه يركض حتى يتعب.'),
  ('a628c2a6-552d-4e1a-a37b-9ed947ed297d', 'يقلّد صوتكِ 🗣️', 'هل يوجّه ألعابه مستخدمًا نبرة صوتكِ وعباراتكِ تمامًا؟ إنه أفضل مرآة لكِ. ستكون رؤية نفسكِ من منظور خارجي تجربة طريفة.'),
  ('a5f509e7-b242-4ca9-b7c5-aa083ba7699a', 'طفرة في الطول والوزن! 📏', 'هل لاحظتِ عند إلباسه أن قمصانه أصبحت ضيقة أو أن حذاءه يضغط على قدميه؟ أدخلي طوله وقياساته الحالية في متتبع النمو، وراقبي بفخر كيف يرتفع منحنى نموه.'),
  ('a9ef3c95-4b55-4dd2-abe5-e4a54e6509df', 'عندما تتعب الأم 🛑', 'أنتِ لستِ آلة. إذا لم تكن لديكِ اليوم طاقة لإعداد الطعام، فاطلبيه من الخارج. أن تكوني أمًا مثالية لا يعني أن تفعلي كل شيء بمفردكِ.'),
  ('ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f', 'نخب الانتصار 🥂', 'لقد اجتزتِ بسلام يومًا صعبًا مليئًا بالعناد. اجلسي وجهًا لوجه مع شريككِ وتبادلا نخب الشاي. أنتما تنجحان في تحمّل هذه المسؤولية الكبيرة.'),
  ('7cad0a21-48df-4f84-89c3-bca4ef4e2b8a', 'هل تعتقدين أنه لا يشرب ما يكفي من الماء؟💧', 'اجعلي شرب الماء عادة ممتعة بشراء أكواب ملوّنة له بأشكال مختلفة.'),
  ('d2d72f62-94bd-4b00-9bc2-090ee3d937fa', 'أحاديث هامسة 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واحكي له بصوت خافت جدًا وهمس عمّا حدث خلال اليوم. فالهمس من أفضل الطرق لتهيئة الدماغ للنوم.'),
  ('df67b2d6-67a7-45d0-8784-314cb9888630', 'حرية الاختيار 👗', 'هل يريد اختيار ملابسه بنفسه رغم أن ألوانها غير متناسقة إطلاقًا؟ لا بأس في ذلك. كي لا تحبطي إرادته، قدّمي له خيارين فقط: هذا أم ذاك؟'),
  ('308209fb-08e0-4807-8fb4-5bc201b75466', 'أصوات الأب الغريبة 🤡', 'أسرع طريقة لإضحاك طفلكِ هي أن يصدر الأب أصواتًا غريبة ويقوم بتعابير مضحكة. استمعي هذا المساء إلى صوت ضحكاته المرحة وابتسمي أنتِ أيضًا من بعيد.'),
  ('591ee14c-695d-499c-8f9b-1192b3fd9c23', 'حان وقت الفضفضة 💬', 'لقد بكى اليوم على كل شيء وشعرتِ بأن طاقتكِ قد نفدت. ادخلي فورًا إلى مجتمع Anacan واكتبي: كان اليوم صعبًا جدًا. سترين أن مئات النساء يعشن اللحظة نفسها.'),
  ('7b870bcd-23ba-4647-a5da-35a4bde7db6f', 'مهندس المكعبات الصغير 🧱', 'هل يحاول تركيب مكعبات الليغو الكبيرة معًا وصنع أشياء منها؟ إنه يكتشف علم الهندسة. أضيفي محاولاته الهندسية الصغيرة هذه إلى متتبّع النمو.'),
  ('3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d', 'تكرار الكلمات 🗣️', 'هل يكرّر فورًا كل كلمة جديدة يسمعها منكِ كالببغاء؟ إن حصيلته اللغوية تزداد. انتبهي جيدًا إلى الكلمات والمشاعر التي تعبّرين عنها أمامه.'),
  ('b4771ddf-ae8c-44a0-b4dd-2f61938d3c93', 'لحن المساء 🛀', 'لقد استنزف الركض طوال اليوم طاقتكما معًا. سيساعده حمّام دافئ ولحن هادئ وعذب في الخلفية على تهدئة جهازه العصبي تمامًا.'),
  ('fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65', 'لحظة الانهيار 🛒', 'يصرخ لأنكِ لم تشتري له اللعبة التي أرادها من المتجر. لا تهتمي بنظرات الآباء المثاليين من حولكِ. تواصلي معه بصريًا بهدوء واشرحي له الأمر.'),
  ('3a862b3f-38a2-4cda-8a77-17c531d3e5f5', 'دعي الأعمال المنزلية جانبًا 🛑', 'لم تُمسح الأرضية ولم تُطوَ الملابس؟ دعيها كما هي. يمكن ترتيب المنزل المتسخ، لكن تعافي الأم المنهكة نفسيًا يستغرق وقتًا طويلًا. استلقي على الأريكة.'),
  ('52c32776-811a-4d66-a0c4-6b1c34cdfc69', 'تقبّلي قلة النوم 😭', 'استيقظ في منتصف الليل ولا يريد النوم. لا تغضبي منه. دعي ميزة تحليل البكاء تستمع إلى صوته لتحديد السبب (ألم، غازات، خوف)، ثم احتضنيه بصبر.'),
  ('bc7db5e2-0eb7-4adc-85cd-1181aac8b268', 'البحث عن أصدقاء جدد 👫', 'هل يحاول الركض مع أقرانه في الحديقة والاقتراب منهم؟ لقد بدأت مرحلة التفاعل الاجتماعي رسميًا! راقبيه بفخر من بعيد مع الحرص على سلامته.'),
  ('100554ba-e336-4148-9dd0-9a0ceeecb04b', 'تعلّمي من المدونات 📱', 'هل سئمتِ من قول طفلكِ «لا» لكل شيء؟ هذه علامة تقليدية لمرحلة تحديات سن الثانية. اقرئي المدونات النفسية في التطبيق لتفهمي ما يدور في ذهنه.'),
  ('19cce24b-ae51-482e-8dc7-6812a220483b', 'لا تلومي نفسكِ 📝', 'هل نفد صبركِ اليوم ورفعتِ صوتكِ؟ عندما ينام طفلكِ، اكتبي مشاعركِ في مفكرة الحالة المزاجية وسامحي نفسكِ. أنتِ متعبة فحسب، وأنتِ بشر.'),
  ('1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5', 'صعود الدرج باستقلالية 🧗‍♂️', 'هل يتوق إلى صعود الدرج ممسكًا بيدكِ، أو حتى إلى صعوده بمفرده؟ إنه يختبر حدود قدراته الجسدية. امنحيه هذه الحرية مع الحرص على سلامته.'),
  ('380af2db-ede8-491b-ab1a-6f695da10f42', 'الخوف من الانفصال 🥺', 'حتى عندما تذهبين إلى الحمّام، ينتظركِ خلف الباب ويبكي. قد يشتد قلق الانفصال أحيانًا. طمئنيه بصوتكِ في كل مرة، وأخبريه أنكِ موجودة وأنكِ ستعودين.'),
  ('805c93f2-e2d3-43ec-9e6f-4782049680cd', 'ظلام الغرفة 🌙', 'لتساعدي طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية في الغرفة، وخصوصًا شاشات الأجهزة اللوحية. لا يُفرَز الميلاتونين إلا في الظلام.'),
  ('ba544f24-4325-4cce-9fad-539f5e144287', 'العناد وقت الطعام 🥣', 'هل يقول إنه شبع بعد تناول ملعقتين؟ لا تجبريه. بناء علاقة صحية مع الطعام أهم من إجباره على الأكل. قدّمي وجبات أكثر بحصص أصغر.'),
  ('0b8f75a4-5ddd-4527-a07d-f3a8b79df578', 'فرحة التصفيق 👏', 'هل يصفّق لنفسه بفخر عندما ينجح في فعل شيء ما، مثل بناء برج؟ إنه يبحث عن تشجيعكِ! فاحتفي أنتِ أيضًا بهذا الإنجاز الصغير بفرح كبير وصفّقي له.'),
  ('2ac10424-b1ee-4b11-b087-e5d8e74e2722', 'ساعة الهدوء ☕', 'إذا لم ينم طفلكِ نهارًا، فحددي ساعة هدوء (quiet time) لمدة ساعة واحدة على الأقل. دعيه يتصفح كتابًا في سريره، بينما تشربين الشاي وتتصفحين هاتفكِ.'),
  ('2eea19a8-6377-4aff-9f02-8b899ec1a730', 'استراحة للزوجين 🥂', 'نام الطفل. ضعي الآن الهاتف والأعمال المنزلية جانبًا. تحدثي مع شريككِ لمدة 20 دقيقة على الأقل في أي موضوع غير الطفل. فأنتما زوجان أيضًا، إلى جانب كونكما والدين.'),
  ('2102feb2-22f3-4c41-8de6-6f3e115e2d56', 'نهاية الحكاية 🪄', 'قد تصبح الحكايات التقليدية مملة. اجعلي الحكاية أكثر تفاعلًا هذه المرة، ودعي طفلكِ يختار نهايتها. حفّزي خياله بسؤاله: من تعتقد أنه ساعد الدب الصغير؟'),
  ('8df55e5c-cbbb-49b9-bd1a-b655d228f1d5', 'اختبار الحدود ⚠️', 'هل يفعل ما نهيتِه عنه وهو ينظر مباشرة إلى عينيكِ؟ إنه لا يحاول إغضابكِ، بل يختبر مدى ثبات حدودكِ. حافظي على ثباتكِ.'),
  ('aa89536f-3d4b-4a1e-9088-0384b755894e', 'التفاعل مع الصور 📖', 'هل يلمس صور الحيوانات أو الأطفال في الكتاب ويصدر أصواتًا عند رؤيتها؟ إدراكه البصري مذهل. سجّلي هذه الملاحظة في متتبّع النمو.'),
  ('0f4c51cd-27d9-4064-9aec-69b37d8e0a6f', 'رقصة الصباح 🎶', 'هل يستيقظ طفلكِ مفعمًا بالطاقة؟ لتخفيف فوضى الصباح، شغّلي أغنية أطفال مرحة وارقصا في الغرفة لبضع دقائق، وابدآ يومكما بابتسامة.'),
  ('3f35178a-8193-420a-abc5-0ec312dd4ef0', 'قائمة الاحتياجات 🛒', 'هل نفدت الحفاضات أو الشامبو أو مهروس الفاكهة؟ لا ترهقي ذهنكِ، بل دوّني كل شيء فورًا في قائمة التسوق وزامنيها مع شريككِ بنقرة واحدة.'),
  ('4ec6bcf9-c49a-4e82-9a6f-0ae618212221', 'صمت عميق 🤫', 'تكون النصف ساعة الأولى بعد نوم طفلكِ أكثر الأوقات حساسية. تحققي من مستوى الضوضاء بالديسيبل باستخدام مقياس الصوت، واخفضي صوت التلفاز، واستمتعي بهذا الصمت العميق الذي يخيّم على المنزل.'),
  ('79665648-b787-4a1e-b120-da8384605658', 'سر الحديد: فيتامين C 🍋', 'هل يبدو طفلكِ شاحبًا أو فاقدًا للشهية؟ تحققي من كمية الحديد التي تناولها اليوم في أداة متابعة التغذية، وقدّمي له مع اللحم سلطة غنية بعصير الليمون لتعزيز امتصاص الحديد.'),
  ('a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8', 'الاستيقاظ ليلًا 🌌', 'هل يستيقظ طفلكِ باكيًا في منتصف الليل ولا يهدأ؟ اطلعي على قسم المدونات لمعرفة الفرق بين الذعر الليلي والكوابيس وكيفية التعامل النفسي الصحيح معهما.'),
  ('f582b213-b9d3-463a-9b65-bba1181ecabf', 'فن رسم الدوائر! 🎨', 'هل يحاول طفلكِ رسم دوائر مغلقة بالقلم على الورق (أو على الحائط!)؟ إنها قفزة رائعة في تطور مهاراته الحركية.'),
  ('41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9', 'ديتوكس الخضراوات الورقية 🌿', 'هل تشعرين بالانتفاخ؟ تحققي من دورتكِ في متتبع الدورة الشهرية، واختاري وصفة سموذي أخضر من قسم الوصفات الصحية للنساء لتنقية جسمكِ واستعادة طاقتكِ.'),
  ('99409d74-b463-47c8-b5a8-30d9e195253d', 'شرب السوائل والإمساك 💩', 'هل يركض طفلكِ كثيرًا ويشرب القليل من الماء؟ راقبي برازه عند تغيير الحفاض (أو عند استخدام النونية). وإذا كان معرضًا للإمساك، فأضيفي الشوفان إلى طعامه.'),
  ('493d7552-4aa4-42f1-ab76-65529b782f6d', 'المهندس الصغير 🏗️', 'هل يعشق بناء الأبراج وهدمها؟ اكتشفي الآن في قسم المنتجات الموصى بها المكعبات المغناطيسية أو الخشبية التي ستعزز ذكاءه ومهاراته الحركية أكثر.'),
  ('96969038-76a5-48c3-b60c-aafe8839c46c', 'خذي نفسًا عميقًا 🌬️', 'هل أنهككِ الركض خلفه اليوم؟ افتحي مفكرة المزاج واكتبي عن شعوركِ بالتعب. لا تحاولي أن تكوني أمًا مثالية، فمشاعركِ مهمة أيضًا!'),
  ('3cbc904d-0d48-46fa-a264-4d48559d6b46', 'هل كان يومًا صعبًا؟', 'أفرغي ما في قلبكِ بكتابة ما شعرتِ به من توتر اليوم في مفكرة المزاج. تمر جميع الأمهات بهذه الأزمات، ولستِ وحدكِ.'),
  ('aabf621d-766b-4fe7-b19d-2316986fdc64', 'وليمة للأم 🥑', 'تفعلين كل ما بوسعكِ لإطعامه. لكن ماذا عنكِ؟ اختاري من الوصفات الصحية وجبة غداء غنية بالحديد تمنحكِ الطاقة، واجلسي بهدوء لتناولها.'),
  ('c60bf17d-5d16-4967-881d-d808bb5c5b6e', 'جمل من كلمتين 🗣️', 'ماما تعالي، ارمِ الكرة – تزداد حصيلته اللغوية يومًا بعد يوم. ادعمي تطور نطقه بتكرار كلماته غير المكتملة أمامه بالنطق الصحيح.'),
  ('274e44c7-f2f2-4e14-a2db-692e3ab50d92', 'نوبات الغضب في المتجر 🛒', 'هل ألقى بنفسه على الأرض لأنكِ لم تشتري له ما أراده في المتجر؟ لا تكترثي لنظرات الآخرين. انحني إلى مستوى عينيه وأخبريه أنكِ تتفهمين مشاعره.'),
  ('7ffa24e8-d5c5-47fa-bd56-46791566e3ed', 'ملابس مرتداة بالمقلوب 👗', 'هل يرتدي حذاءه في القدم الخطأ وقميصه بالمقلوب، ويرفض تمامًا خلعهما؟ دعيه كما هو! فهذه أبسط طريقة بريئة يؤكد بها فرديته.'),
  ('90cdd9aa-f5c9-402b-8ee4-af9073e319ae', 'سكينة مع الموسيقى 🎶', 'أسهل طريقة لتهدئة نوبات التذمر في آخر النهار هي تشغيل لحنه المفضل واحتضانه والرقص معه ببطء.'),
  ('c19b60f5-cbba-4300-8903-9c5cb8625ba7', 'افتخري بنفسكِ 🌟', 'كل مهارة جديدة يتعلمها طفلكِ يوميًا، وكل خطوة واثقة يخطوها، هي ثمرة جهودكِ وجهود شريككِ.'),
  ('e47a41a7-8601-4ce3-8c27-0c69ab445dad', 'إعلان الاستقلال 📜', 'هل يقول طفلكِ «سأفعل كل شيء بنفسي!» ويتسبب في تأخير المهام؟ اسألي Anacan AI فورًا عن طرق تحويل هذا العناد الذي لا يعرف حدودًا إلى فرصة للتطور.'),
  ('e4b29fb1-70d1-4a56-b112-96966513c6eb', 'تفاصيل الكتب 📖', 'هل يقلّب طفلكِ صفحات الكتاب ويشير بإصبعه إلى أدق التفاصيل في الصور؟ ذاكرته البصرية تعمل بشكل ممتاز. تحاوري معه حول ما يراه في الصور.'),
  ('14b9dba6-d0f2-4f3d-a4e8-f737b507b018', 'فنان الخربشات 🖍️', 'ما إن يمسك طفلكِ قلمًا حتى يبدأ بالخربشة على الجدران أو الورق. هكذا تتطور مهاراته الحركية الدقيقة من خلال الألوان.'),
  ('48cc1013-ae1c-4b86-9e80-78bd05d5745a', 'هدوء الليل 🛀', 'حمّام دافئ، وتدليك لطيف، وغرفة مظلمة. لا تغيّري روتين النوم أبدًا، فهو يرسل إلى دماغ طفلكِ إشارة بأن هذا هو أفضل وقت للنوم.'),
  ('a8d24ffb-d035-4c11-983e-8c2c2a9ad274', 'فضفضة الأمهات 💬', 'هل ترهقكِ فكرة «لماذا طفلي عنيد إلى هذا الحد؟» انضمي إلى مجتمع Anacan، وستكتشفين أن كل طفل يمر بأزمات مختلفة خلال نموه.'),
  ('5ae62f81-7331-472c-9b48-c967d0615a5b', 'بطل المساء: الأب 🦸‍♂️', 'أوكلي روتين النوم هذا المساء إلى زوجكِ باستخدام ميزة الشريك. دعيه يقرأ القصة، بينما تحضّرين لنفسكِ حمّامًا دافئًا لتتخلصي من ضغوط اليوم.'),
  ('88d95f7d-2e98-41b0-8554-4115adfb31c5', 'الانتقائية في الطعام 🥦', 'هل يرفض طفلكِ اليوم طعامًا تناوله بشهية بالأمس؟ حلّلي قائمة طعامه باستخدام أداة متابعة التغذية، واعثري في وصفات الأطفال على طرق تقديم متنوعة ومرحة.'),
  ('ee2ef852-cac1-4c22-a029-d59cd40dbe5f', 'صيد الوحوش! 👾', 'هل يبحث طفلكِ عن وحش تحت السرير؟ تزداد مخاوف الخيال في هذه المرحلة. شغّلي صوت المروحة من الضوضاء البيضاء لتهيئي له أجواءً آمنة ورتيبة في الغرفة وتساعديه على الهدوء.'),
  ('3389c70e-b510-475b-87c1-4f01743277cd', 'خطة الهروب من السرير 🛌', 'هل يحاول طفلكِ التسلق للخروج من سريره؟ يقترب موعد انتقاله إلى سرير الأطفال الكبار. أعيدي التحقق من سلامة الغرفة من مستوى الأرض.'),
  ('92afc025-d2fe-4c60-9ebd-9366e19b0175', 'استراحة للأم ☕', 'عندما يلعب طفلكِ بمفرده، لا تسارعي فورًا إلى أداء الأعمال المنزلية. فوضى الغرفة لن تهرب، لكن طاقتكِ قد تنفد. اجلسي واستمتعي بقهوتكِ الساخنة.'),
  ('c522fcae-04de-4086-b6e1-764904ead448', 'ذروة مرحلة «لماذا؟» 🤔', 'لماذا هذا هناك؟ لماذا أنام؟... عقل طفلكِ كالإسفنجة! قدّمي إجابات قصيرة ومنطقية عن أسئلته التي لا تنتهي. فهو يكتشف العالم من خلال كلماتكِ.'),
  ('3a442f56-c411-4f3c-a16a-32453afe5f33', 'التواصل في الحديقة 🌳', 'هل يلعب طفلكِ بجوار الأطفال الآخرين بدلًا من اللعب معهم؟ اللعب الموازي طبيعي تمامًا في هذا العمر. اصطحبيه كثيرًا إلى أماكن يلتقي فيها بأقرانه، مع مراعاة الطقس والملابس المناسبة.'),
  ('5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d', 'الأصدقاء الخياليون 🧸', 'هل يروي طفلكِ قصة لدبه المحشو أو يتظاهر بشرب الشاي من كوب فارغ؟ اللعب الرمزي من روائع النمو. سجّلي هذه القفزة المعرفية بفخر في متتبّع النمو.'),
  ('d4544a8c-8615-4a88-b7e6-c7dc2d3b805a', 'الحاجة إلى الهدوء 🤫', 'تكون أول نصف ساعة بعد استغراق طفلكِ في النوم الفترة الأكثر حساسية. تحققي من مستوى الديسيبل في الغرفة باستخدام مقياس الصوت، واضبطي صوت التلفاز في الغرفة المجاورة وفقًا لذلك.'),
  ('32813c49-da9b-4dca-8d61-b20de94b9fae', 'هل يريد امتلاك كل شيء؟ 🛑', 'لم يتكوّن لديه مفهوم المشاركة بعد. لا تجبريه، وبدلًا من ذلك طبّقي تدريجيًا قاعدة «لنلعب بالتناوب».'),
  ('b1d18fda-3875-4aca-b436-4ecb52ef49a6', 'أيام بلا ألم 🩸', 'هل اقتربت دورتكِ الشهرية وبدأت التقلصات؟ قبل اللجوء إلى الأدوية، اعتني بنفسكِ وحضّري كرات خفيفة من التمر والجوز الغنية بالمغنيسيوم، من قسم الوصفات الصحية للنساء.'),
  ('55fa43db-2800-421e-b0f2-748c40c7ef07', 'الملابس تصغر! 📏', 'هل أصبحت أكمام قمصانه قصيرة مجددًا؟ أدخلي قياساته الحالية في متتبّع الوزن، وشاهدي المنحنى الصاعد لتلاحظي بوضوح طفرة النمو مع اقترابه من الشهر 29.'),
  ('8a1a47bc-2d1d-4804-abb1-5b5294f326db', 'بطل القصة 📖', 'هل يطلب منكِ قراءة القصة نفسها للمرة 100؟ اقرئي في المدونات عن الدور المذهل لهذا التكرار، الذي قد يبدو مملًا، في تنمية ذكائه، وجدّدي صبركِ.'),
  ('c88c6893-fe11-4ce0-bf2d-ed7f94e0770d', 'أولى الفرضيات المنطقية 🤔', 'هل بدأ يُكوّن جملًا مثل: «إذا فعلتُ هذا، فسيحدث ذلك»؟ لا تفوّتي هذه القفزة الإدراكية الرائعة؛ سجّليها في مقطع فيديو بصوته، وأضيفيها إلى ألبوم طفلكِ وافتخري به.'),
  ('3469bb77-d2d2-406c-8c90-287cb3502fb6', 'اجتماع الفريق 🥂', 'بعد أن ينام طفلكِ، حضّري كوبًا من الشاي مع شريككِ للتخفيف من ضغوط اليوم، وقدّرا بعضكما بعضًا بقولكما: «نحن فريق رائع».'),
  ('69a15994-f6a2-4e74-92d0-633dfea33b45', 'اكتشفي مكانًا مناسبًا للأمهات ☕', 'لقد أرهقكِ النظر إلى الجدران نفسها في المنزل. اكتشفي من قسم الأماكن الصديقة للأمهات مقهًى يضم ركنًا للعب الأطفال؛ دعي طفلكِ يلعب واستمتعي أنتِ بقهوتكِ.'),
  ('71af31e1-67cd-4bc6-a54d-505d0d3ed0af', 'أصوات الحيوانات 🐶', 'هل يحاول أن يقول «مياو» عندما يرى قطة و«هاو هاو» عندما يرى كلبًا؟ تساعد أصوات الحيوانات كثيرًا على تنمية حصيلته اللغوية. العبي معه هذه اللعبة.'),
  ('1fe665ee-e68e-4e2a-b81e-f697b1100d0d', 'طبيب أطفال سريع 🤖', 'ما حجم الحصة الغذائية المناسب مع اقتراب طفلكِ من عمر 2.5 سنة؟ إذا كنتِ مترددة، فاطلبي فورًا من Anacan AI جدولًا دقيقًا ومستندًا إلى أسس علمية.'),
  ('8139ee6f-daa0-4072-ad02-2be67ee8488d', 'بطل الحكاية 🪄', 'ابتكري هذا المساء في الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: صغير شجاع يحب تنظيف أسنانه.'),
  ('9d6f4449-54d1-4585-9f63-6d19afec1bda', 'عناق «أحبكِ» 🫂', 'هل يأتي فجأة ليعانقكِ أو يداعب وجهكِ؟ لقد بدأ يعبّر عن حبه جسديًا. استمتعي بالسكينة التي لا تُضاهى التي تمنحكِ إياها هذه اللحظة.'),
  ('c32b736c-41b6-4e37-ad3d-7f15cea8084a', 'رفض النوم 🥱', 'هل يرفض أخذ قيلولته ويبكي؟ لا تدخلي معه في صراع. وبدلًا من ذلك، خصّصي 30 دقيقة لوقت هادئ يتصفّح خلاله كتابًا بصمت في الغرفة.'),
  ('c762e9b7-a5b4-4810-a642-39d1f9c28936', 'تبديل المناوبة 👨‍👧', 'لقد أرهقتِ ذهنكِ طوال اليوم بالإجابة عن أسئلة «لماذا؟». هذا المساء، أوكلي إلى شريككِ مهمة إلباسه ملابس النوم ووضعه في السرير، وخذي قسطًا من الراحة.'),
  ('dc54ef63-6d88-4c2f-9c5d-c431db5caf8b', 'موضة غير مألوفة 👗', 'هل يريد ارتداء سروال صيفي قصير في منتصف الشتاء، أو وضع البنطال على رأسه؟ لا تتدخلي في ذوقه. فهذه التجارب الطريفة هي طريقته في تأكيد فرديته.'),
  ('37bfacdd-d6ce-4a16-96d7-85b70834ca41', 'استكشاف ما في الطبق 🥦', 'هل يرمي اليوم على الأرض الطعام الذي أحبه بالأمس؟ افتحي أداة خطة التغذية، واستفيدي من أفكار القوائم المتنوعة والملونة التي أعدّها الخبراء لعمر 2.5 سنة.'),
  ('6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018', 'مخاوف مفاجئة 👻', 'هل بدأ يخاف من ظلام الغرفة أو من ظلال يتخيلها؟ مع تطور خياله، قد تظهر مخاوف غير منطقية. طمئنيه وأشعريه بأنكِ إلى جانبه.'),
  ('b459387d-d414-446b-ac06-391ffb5af36c', 'بطارية لا تنفد 🔋', 'لم تتمكني بعد من فتح عينيكِ، لكنه بدأ بالفعل ماراثون الركض على السجادة. حضّري لنفسكِ كوبًا كبيرًا من القهوة، فاليوم سيكون حافلًا بالحركة.'),
  ('5b291f89-d920-4ebd-a4e6-3d982c3f7c31', 'على خطى الفنان 🖍️', 'هل نفد الورق وحان الآن دور الجدران والأبواب؟ تتطور مهارات طفلكِ الحركية الدقيقة من خلال الألوان. افردي قطعة كبيرة من الكرتون في الغرفة وقولي له إن الرسم مسموح هنا فقط.'),
  ('a9576738-56a5-42cd-a95f-6e85e5fb1189', 'نوبات العناد غير المنطقية 🛑', 'هل قامت الدنيا لأنكِ قدّمتِ الماء في كوب أحمر بدلًا من الأزرق؟ هذا ليس دلالًا، بل إن طفلكِ يختبر حدودكِ وما إذا كان قادرًا على التحكم في عالمه. تحلّي بالصبر.'),
  ('e5ef4a95-198d-48b4-a37a-8ba378115031', 'قوة الماء العلاجية 🛀', 'هل أرهقكما الركض طوال اليوم؟ الحمّام الدافئ ليس للنظافة فحسب، بل هو من أفضل الوسائل الطبيعية لتهدئة جهاز طفلكِ العصبي المتوتر.'),
  ('891847ab-5f43-4ba4-a99f-cf7faceb076c', 'تقبّلي الفوضى 🌪️', 'هل سئمتِ من جمع الألعاب نفسها كل يوم؟ لا تجمعيها اليوم! فوضى المنزل ليست نهاية العالم، وراحتكِ النفسية أهم من كل شيء.'),
  ('9de03e77-6cb6-4585-9646-e7347bac18d6', 'أسكتي صوت الشعور بالذنب 💬', 'هل تلومين نفسكِ لأن طفلكِ قضى وقتًا طويلًا أمام الشاشة اليوم؟ انضمّي إلى مجتمع Anacan واقرئي كيف تمرّ أمهات أخريات أحيانًا بالمشاعر نفسها لتشعري بالارتياح. أنتِ لستِ وحدكِ.'),
  ('f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea', 'الشخصية في المرآة 👀', 'هل يصنع طفلكِ تعابير مختلفة أمام المرآة ويتحدث إلى نفسه ويضحك؟ إن وعيه بذاته رائع. راقبيه خلسة واستمتعي بفخر بهذه اللحظات الطريفة.'),
  ('765fd3c5-2a1b-4659-aa42-b76314ae48dc', 'الأنانية في الحديقة 🧸', 'هل يرفض إعطاء وعائه لأيّ شخص أثناء اللعب بالرمل؟ هذه ليست أنانية، بل حماية لحدوده. لا تجبريه، بل علّميه بلطف قاعدة «لنلعب بالتناوب».'),
  ('8329858a-b5aa-4e88-a094-94baf4b4dff4', 'الألعاب الخيالية 🧸', 'هل يحاول طفلكِ تقديم الماء لدُبّه أو دميته ويجري حوارًا معهما؟ اللعب الرمزي تحفة من تحف النمو. راقبي من بعيد هذا المخرج الصغير اللطيف باهتمام.'),
  ('98be6947-c839-4cba-807a-2d0a7d2db4bd', 'وجه الأب المضحك 🤡', 'أسرع طريقة لإضحاك طفلكِ هي أن يصدر الأب أصواتًا غريبة ويصنع تعابير مضحكة بوجهه. استمعي هذا المساء إلى ضحكاته المرحة وابتسمي أنتِ أيضًا في الخلفية.'),
  ('9c1b9283-eb25-42f4-8927-c54192637c35', 'طاقة الأم الصباحية ⚡', 'هل استيقظتِ متعبة هذا الصباح؟ لا تلجئي إلى السكريات. اكتشفي ضمن الوصفات الصحية وصفة الشوفان الغني بالبروتين والفواكه، التي تُحضَّر في 5 دقائق، وابدئي يومكِ بنشاط.'),
  ('1868bb46-a550-4249-8524-2b40ecd9cad3', 'تحتاجين إلى دعم الأب 🫂', 'هل تمرّين بأيام متلازمة ما قبل الحيض في متتبّع الدورة الشهرية وتشعرين بحساسية أكبر؟ استخدمي ميزة الشريك لتخبريه بأنكِ تحتاجين اليوم إلى مزيد من الدعم.'),
  ('5efae0dc-5ddd-4ac1-9526-ddfa449ec612', 'قلعة الوسائد 🏰', 'حوّلي الغرفة هذا المساء إلى ساحة لعب. ابنيا قلعة صغيرة من وسائد الأريكة وادخلا إليها. ستعمّ بعض الفوضى، لكنها بالتأكيد تستحق كل هذه الضحكات المرحة.'),
  ('e40e4ab0-cd42-4ed7-b968-edc0adab6461', 'مفاوضات كالمحامين 🗣️', 'هل يقول: «سألعب قليلًا ثم أرتدي ملابسي»؟ لقد بدأ يحاول التفاوض معكِ باحتراف. هذا مؤشر رائع على تطور النطق، لكن لا تنسي الحفاظ على حدودكِ بحب.'),
  ('f9854a88-373e-4d4d-91e8-4e24a9ea9cba', 'استكشاف الطبيعة 🌳', 'لقد سئمتِ البقاء بين أربعة جدران. حتى لو كان الطقس باردًا، ألبسي طفلكِ ملابس دافئة واصطحبيه إلى الحديقة لمدة 20 دقيقة. دعيه يستكشف الأوراق والحجارة، فالهواء النقي سيفيدكما كليكما.'),
  ('fb90f3c3-fde8-496d-b59b-6ba1236abd46', 'متعة «وجدتُك!» 🙈', 'أصبحت لعبة الغميضة الآن لعبته المفضلة. يختبئ خلف الستارة وينتظر أن تجديه. اجعلي هذه اللعبة الجزء الأكثر مرحًا من روتينكما اليومي.'),
  ('fce8d709-58cb-464d-bc50-7c2b9036555e', 'التعوّد على الظلام 🌙', 'أطفئي جميع الشاشات في الغرفة لمساعدته على النوم بسرعة أكبر. فالضوء الأزرق المنبعث من التلفاز يؤخر إفراز هرمون النوم.'),
  ('fc8def68-9f4f-421f-a543-941a3d40a533', 'كلمات جديدة 🧠', 'هل كوّن اليوم جملة معقدة ومختلفة، كأنه شخص بالغ؟ افتحي متتبّع النمو فورًا وسجّلي هذه القفزة المعرفية كذكرى لتقرئيها في المستقبل.'),
  ('115c548f-9326-4a38-a159-3195407d360e', 'استراحة للزوجين 🥂', 'نام طفلكِ. ضعي الآن الأعمال المنزلية جانبًا. تحدّثي مع شريككِ لمدة 20 دقيقة على الأقل في أي موضوع بعيدًا عن الطفل. فأنتما أيضًا زوجان.'),
  ('91f7fb7e-2bab-481e-816b-6e91267f93ae', 'الحبو الهادف 🐢', 'هل أصبح يمشي، لكنه أحيانًا يحبو بسرعة مبتعدًا عنكِ من أجل المرح؟ أزيلي العوائق الخطرة من الغرفة وشاركيه لعبة المطاردة والإمساك.'),
  ('ca59c65d-2643-4f9a-b7e1-efbf69908275', 'ساعة للأم بلا إنترنت ☕', 'عندما ينغمس طفلكِ في عالمه ويلعب، لا تسارعي فورًا إلى غسالة الصحون. حضّري لنفسكِ كوبًا من الشاي الساخن، وضعي هاتفكِ جانبًا، واقضي 15 دقيقة بلا إنترنت ومن دون التفكير في أي شيء.'),
  ('53f1873b-90e8-4dcd-884c-7bbec73835df', 'أحاديث هامسة 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجوار طفلكِ وتحدّثي بصوت خافت جدًا وهمسًا عما حدث خلال اليوم. فالهمس من أكثر الطرق هدوءًا وطمأنينة لتهيئة الدماغ للنوم.'),
  ('67fb000b-9452-4ae5-aa28-3a36f345f54a', 'أيام بلا ألم 🩸', 'هل اقترب موعد دورتكِ الشهرية وبدأت التقلصات؟ قبل اللجوء إلى الأدوية، اعتني بنفسكِ وحضّري وجبة خفيفة من التمر والجوز الغنيين بالمغنيسيوم من قسم الوصفات الصحية.'),
  ('f0ddb044-981f-4758-9737-12aa24392d50', 'العدّ بالأصابع 🔢', 'هل يحاول قول واحد، اثنان، ثلاثة عند صعود الدرج أو ترتيب ألعابه؟ إن حسّه الرياضي والمنطقي بدأ يتفتّح. عدّي معه الأشياء الموجودة في الغرفة بصوت مرتفع.'),
  ('841fa22f-136a-48a1-b594-4a69eafbc030', 'استعيدي طاقتكِ 🍲', 'لقد أنهككِ الركض والانشغال طوال الوقت. بدلًا من تناول وجبة خفيفة وأنتِ واقفة، حضّري لنفسكِ طبقًا خاصًا ومشبعًا وغنيًا بالكالسيوم، وتناوليه باستمتاع.'),
  ('1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3', 'خطوات جريئة 🧗‍♂️', 'هل يحاول طفلكِ التسلق إلى أعلى متشبثًا بالأريكة أو المقعد؟ إن توازنه وقوة عضلاته يتحسنان. احرصي على سلامته، لكن لا تمنعي محاولات هذا المتسلق الصغير أبدًا.'),
  ('a7098097-ad7b-4ef2-ac70-151dc53814b4', 'العناد في الطعام 🥣', 'هل يأكل ملعقتين، ثم يشير إلى أنه شبع ويهرب؟ لا تجبريه. إن بناء علاقة صحية مع الطعام أهم من إجباره على الأكل.'),
  ('f8b30c93-8e49-4cb9-8db0-9b3082221d0d', 'مراجعة اليوم 📝', 'هل شعرتِ اليوم بإرهاق شديد، أم قال طفلكِ كلمة لطيفة جدًا؟ في كلتا الحالتين، افتحي مفكرة المزاج وسجّلي هذه اللحظة لتبقى ذكرى للمستقبل، وعبّري عما بداخلكِ لتشعري بالارتياح.'),
  ('18e35d56-8285-420a-adac-121643743cd2', 'اختبار الانتباه 🧩', 'هل أصبح طفلكِ يقضي 10-15 دقيقة في اللعب بلعبة واحدة، مثل الأحجية؟ هذا يعني أن مدة تركيزه تزداد. قفي بهدوء في أحد أركان الغرفة وراقبيه.'),
  ('87548d0a-d1fb-4a91-8d0e-f51d5f31d60e', 'استكشاف السبب والنتيجة 🤔', 'ماذا سيحدث إذا رميتُ هذا؟ وما وظيفة هذا الزر؟ يجري طفلكِ تجارب عملية باستمرار. أعيدي تقييم سلامة المنزل مرة أخرى من مستوى نظره القريب من الأرض.'),
  ('f1a78ec7-6b62-43e2-8747-e4f8c033a5e7', 'لا نوم من دون حكاية 🪄', 'هل توقفت الحكايات الكلاسيكية عن جذب انتباه طفلكِ؟ ابتكري له حكاية خاصة يكون هو بطلها، وأضيفي إليها أصوات الطبيعة في الخلفية، وادخلي معه إلى عالم خياله.'),
  ('becd06f2-3767-4d60-98af-e6ee50a40e21', 'الرقص على أنغام الموسيقى 🎶', 'هل يبدأ طفلكِ فورًا بالتمايل مع الإيقاع عندما يسمع موسيقى مرحة؟ إن التناغم بين حاسة السمع والمهارات الحركية يتطور بصورة رائعة! شغّلي أغنية مرحة وارقصي معه في الغرفة.'),
  ('befcea5e-21fe-4c91-b025-35c7c94f17a1', 'حكاية الأب 📖', 'أريحي أحبالكِ الصوتية هذا المساء. دعي الأب يتولى مهمة قراءة كتب طفلكِ المفضلة له بطريقة طريفة وبنبرات صوت متنوعة.'),
  ('d245b047-0d4a-45c3-956c-817469ecd147', 'انتهت مرحلة «لماذا؟» وبدأت مرحلة «كيف؟» 🤔', 'إنها قفزة في الخيال والمنطق! بدأ طفلكِ الآن يسأل أيضًا عن كيفية عمل الأشياء. تعلّمي من خبيرنا Anacan AI أساليب الإجابة عن هذه الأسئلة بطريقة تناسب عمره ولا تشعره بالملل.'),
  ('0d9edca6-9e16-4f20-b482-5f21d8925331', 'تقبّلي قلة النوم 😭', 'استيقظ طفلكِ في منتصف الليل ولا يريد النوم. لا تغضبي منه. حاولي معرفة السبب (ألم، غازات، خوف)، وطمئنيه بالصبر والاحتضان.'),
  ('6fbdbe3b-91f8-4e0a-9823-628cb1856a3a', 'بقع عنيدة 👗', 'هل تتعبكِ البقع المستمرة على الملابس؟ لا تنزعجي، فطفلكِ يستكشف الأطعمة. استخدمي المرايل المصنوعة من السيليكون، واستمتعي بهذه اللحظات الملوّنة والفوضوية.'),
  ('9f08baf7-46d6-4ac6-b651-94901e800f6b', 'دعيني أساعدكِ! 🧹', 'هل يحاول طفلكِ أخذ الممسحة أو قطعة التنظيف من يدكِ عندما تمسحين الأرض أو تزيلين الغبار؟ إنه يشعر بأنه أصبح كبيرًا. أعطيه قطعة قماش صغيرة واسمحي له بالانضمام إلى فريقكِ.'),
  ('40197a85-31e6-4141-9d38-df9b89843274', 'أصغي إلى جسدكِ 🩸', 'هل تشعرين برغبة مفاجئة وشديدة في تناول الحلويات أو بالإرهاق؟ تحقّقي من التقويم في متتبّع الدورة الشهرية. إذا كان موعد دورتكِ الشهرية، فاختاري وجبة خفيفة غنية بالمغنيسيوم من الوصفات الصحية.'),
  ('4ca62724-362e-47af-b9dc-e138d57c7cbd', 'ظلال الغرفة 🌌', 'هل يخاف طفلكِ من الظلام والوحوش الخيالية؟ لا تجعلي الغرفة مظلمة تمامًا، وشغّلي له صوت الرحم من قسم الضوضاء البيضاء، لتمنحيه ذلك الشعور القديم بالأمان التام.'),
  ('f8e208a6-e2c2-4a88-b04c-adaeb10974b8', 'قلق الانفصال 🥺', 'هل يبكي طفلكِ خلفكِ عندما تغادرين الغرفة، حتى عند ذهابكِ إلى الحمام؟ إنه يظن أنكِ لن تعودي. طمئنيه دائمًا بقولكِ: «أنا هنا، هل تسمع صوتي؟»'),
  ('216f95a1-f03e-48c4-8e9d-615f08aa0853', 'ثرثار صغير 🗣️', 'هل أصبح طفلكِ يجمع 4-5 كلمات ويروي قصصًا مضحكة؟ إنه يشهد طفرة لغوية! لا تفوّتي هذه اللحظة الذهبية.'),
  ('91db0bda-d980-4153-bb7d-0ed55ffcd626', 'نَفَس عميق 🧘‍♀️', 'ربما جفّ حلقكِ من الإجابة عن الأسئلة طوال اليوم. ما إن يسود الهدوء في الغرفة، استريحي قليلًا بتنفس عميق، شهيقًا وزفيرًا، من دون النظر إلى أي شاشة.'),
  ('de182c61-510f-445a-9f50-8ed2459f90cf', 'نطق الكلمات 🗣️', 'هل ينطق بعض الكلمات بشكل ناقص أو مضحك جدًا؟ لا تضحكي، بل أعيدي نطق الكلمة أمامه بشكل صحيح وبنبرة سليمة، حتى يرسّخ دماغه النطق الصحيح.'),
  ('f4bf03e5-dc33-4bfa-a875-42962b014227', 'اللعب الحر 🧸', 'لستِ مضطرة إلى تسليته في كل دقيقة. فالشعور بالملل هو بداية الإبداع لدى الأطفال. دعيه يستكشف شيئًا ما بمفرده في الغرفة.'),
  ('3ead07a7-4417-4744-9277-6bedf5fa245b', 'لحظة يتوقف فيها الزمن 📸', 'عندما ينام طفلكِ، تأمّلي وجهه البريء. فرغم أنه أرهقكِ طوال اليوم، تشتاقين إليه بمجرد أن ينام، أليس كذلك؟ هذه المفارقة هي جوهر الأمومة.'),
  ('5f09ad8f-0fde-4f65-8032-dfe56e435a81', 'عادة شرب الماء 💧', 'هل يطلب باستمرار العصائر المحلّاة بدلًا من الماء؟ راجعي نظام السوائل في خطته الغذائية. شجّعيه على شرب الماء بتقديمه في أكواب ملوّنة ومميزة مزودة بمصاصات.'),
  ('e8fd5bc0-a904-4768-8c61-d9259b243761', 'فريق التصفيق 👏', 'هل يصفّق لنفسه فرحًا عندما ينجح في فعل شيء ما؟ ما إن تشهدي هذه اللحظة الرائعة، أدّي رقصة نصر صغيرة في المنزل وشاركيه فرحته!'),
  ('2a429f3f-0b1b-49c6-befd-28bf5cd2cf98', 'عندما تتعب الأم 🛑', 'أنتِ لستِ إنسانًا آليًا. إذا لم تكن لديكِ اليوم طاقة للطهي، فاطلبي الطعام الجاهز. أن تكوني أمًا مثالية لا يعني أن تفعلي كل شيء بمفردكِ.'),
  ('5c059ccd-12dd-4a31-9da6-6e33ef79b1be', 'رفض حازم 🛑', 'هل يبتعد عندما يحاول أحدهم تقبيله ويقول «لا» بحزم؟ احترمي حدوده الجسدية. من المهم جدًا أن يعترض على أي لمس من دون إذنه.'),
  ('41e28dbe-e3fb-4744-b4f1-9927a3802b24', 'رشّحي الأصوات 🤫', 'تزداد حساسية طفلكِ للأصوات في لحظات استغراقه في النوم. ولتحييد الأصوات القادمة من النافذة، شغّلي في الغرفة جهازًا يصدر ضوضاء بيضاء (white noise) خفيفة أو بعض الموسيقى.'),
  ('745737c8-7329-40d3-90c9-336ff2e4a2ae', 'معًا في المطبخ 🧑‍🍳', 'هل يريد طفلكِ مساعدتكِ في المطبخ؟ دعيه يساعدكِ عند سكب الدقيق أو الماء. حتى لو عمّت الفوضى المكان، فإن سعادته وشغفه بالتعلّم يستحقان ذلك.'),
  ('1938c0bd-ea98-478e-8da7-ef024a27ce71', 'القائمة ليست اختيارية، بل ضرورية 🛒', 'هل أضعف الحرمان من النوم ذاكرتكِ، فصرتِ تنسين ما عليكِ شراؤه من المتجر؟ لا ترهقي ذهنكِ. دوّني كل شيء في قائمة التسوق داخل التطبيق.'),
  ('30a1934e-958b-40a0-9b32-c4894a70a798', 'فقط عانقيه 🫂', 'لا حاجة إلى أي لعبة أو كتاب. هذا المساء، ضمّيه إلى صدركِ فحسب، واستنشقي رائحته، واهمسي له في الظلام كم هو غالٍ عليكِ.'),
  ('e00d8cce-8b3a-4ac6-ad35-5a22b01bd325', 'مهندس المكعبات 🧱', 'هل يحاول طفلكِ تركيب قطع الليغو الكبيرة معًا وصنع أشياء منها؟ إنه يكتشف مفاهيم المكان والهندسة. سجّلي هذه المحاولة الهندسية المميزة في متتبّع النمو.'),
  ('1a4b3925-7885-40fb-a56f-488e3358cee1', '10 دقائق بمفردكِ 🛀', 'ساد الهدوء في الغرفة. اطلبي من شريككِ أن يتولى إدارة كل شؤون المنزل، واستمتعي أنتِ بحمّام دافئ وبعض الوقت على انفراد مع نفسكِ.'),
  ('505c8d78-0b81-4cb5-96f5-e5571e1fc049', 'أزمة عمر 2 سنة 📱', 'هل أتعبكِ رفض طفلكِ لكل شيء؟ اقرئي المقالات في قسم المدوّنة لتفهمي أسباب عاصفة النمو هذه التي تدور في دماغه.'),
  ('5e96bc6a-ca0b-4e3c-9cde-441c31566ab3', 'مهمة الخضراوات السرية 🥦', 'هل يرمي طفلكِ الخضراوات الورقية أو البروكلي من طبقه؟ اكتشفي في وصفات الأطفال وصفة مافن منزلي ملوّن بالخضراوات، وحقّقي بسهولة هدفكِ اليومي من الفيتامينات في أداة متابعة التغذية.'),
  ('79a825c4-e46e-4e7d-81f2-4387a7318ef2', 'مشاركة الأسرار 💬', 'هل أنتِ مرهقة جدًا؟ انضمي إلى مجتمع Anacan. اقرئي القصص الحقيقية لآلاف الأمهات، واستمدّي القوة من شعوركِ بأنكِ لستِ وحدكِ.'),
  ('0048f15c-3ab2-4568-b3e6-cf763bd916d3', 'أخفي الخضراوات 🥦', 'هل يضع كل الخضراوات الموجودة في الحساء جانبًا؟ لا تدخلي معه في صراع. اهرسي الخضراوات وأخفيها في الصلصات أو كرات اللحم؛ فهذه إحدى أقدم حيل الأمهات.'),
  ('4d0d3015-35d0-4444-b757-3789d14e8ec4', 'التفاعل مع الصور 📖', 'هل يلمس الحيوانات أو الأشياء المختلفة في الكتاب ويُصدر أصواتًا عند رؤيتها؟ إن إدراكه البصري مذهل. تحدّثي معه عن شخصيات الكتاب.'),
  ('cfe51929-b2af-45a2-b23e-e670a8d3ebd8', 'مطاردة وقت النوم 🏃‍♂️', 'هل يختلق الأعذار بلا توقف حتى لا يذهب إلى السرير؟ اضبطي مؤقت النوم، وحافظي على الحدود، وشغّلي صوت المطر من قسم الأصوات البيضاء لتهدئة الغرفة.'),
  ('0727c4e7-7433-410a-9da5-27fff69d9877', 'تناول السوائل والإمساك 💩', 'هل يركض كثيرًا ويشرب القليل من الماء؟ راقبي برازه في النونية أو الحفاض. إذا كان معرضًا لخطر الإمساك، فسجّلي ذلك في التطبيق، ثم أضيفي الشوفان أو الكمثرى إلى قائمته الغذائية فورًا باستخدام أداة متابعة التغذية.'),
  ('5730e69b-8e67-40bb-94c5-56cb9dd41a75', 'البحث عن أصدقاء جدد 👫', 'هل يحاول الركض مع أقرانه في الحديقة والاقتراب منهم؟ لقد بدأت مرحلة التواصل الاجتماعي رسميًا! راقبي هذه المحاولات بفخر من بعيد، مع البقاء مستعدة لحمايته عند الحاجة.'),
  ('a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7', 'لحن الليل 🛀', 'لقد أنهككما الركض طوال اليوم. سيساعده حمام دافئ ولحن هادئ وعذب في الخلفية على تهدئة جهازه العصبي تمامًا.'),
  ('100fc6ed-66a7-4e9e-939c-15af0683652e', 'رفض القيلولة 🥱', 'ألم ينم مجددًا؟ لا تدخلي معه في صراع فتُرهقيه وتُرهقي نفسكِ. فاللعب بهدوء بالألعاب في الغرفة يُعد أيضًا نوعًا من الراحة للدماغ.'),
  ('ca5c9545-5eb9-432c-acea-7e6fe2c5ab98', 'الهدوء والقهوة 🤫', 'لقد نام! بدلًا من إفراغ غسالة الصحون الآن، اجلسي في ظلمة الغرفة. استمتعي بقيمة 15 دقيقة من الهدوء واسترخي.'),
  ('cc9ba302-22d8-43e5-a70d-2bed916f8d33', 'انظري إلى الأسفل! 👣', 'هل بدأ طفلكِ يمسك أصابع قدميه ويتفحصها، بل ويستمتع بالمشي حافيًا؟ إن استكشاف الأعصاب الموجودة في باطن القدم مهم جدًا لتوازنه.'),
  ('0bcb845e-25a8-4c8a-b05c-67b7a3788c4a', 'مفاجآت الطقس ⛅', 'عندما تخرجين في نزهة، لا تدعي الطقس يخدعكِ فيشعر طفلكِ بالبرد. لا تقرري بمجرد النظر من النافذة، بل تحققي مسبقًا من سرعة الرياح ودرجة الحرارة الفعلية في الخارج.'),
  ('1566736d-5f6a-420b-9aaa-9e37909efa16', 'يكتشف ذاته 👑', 'لا تفارق كلمتا «أنا!» و«إنه لي!» لسانه. إنها أبرز مراحل التمركز حول الذات. احترمي فرديته، فهذه مرحلة طبيعية من مراحل النمو.'),
  ('7aba0d06-67c9-4fba-811b-47eacf1ff2d7', 'مسؤولية الأب 👨‍🍼', 'يكفيكِ ما تشعرين به من تعب خلال النهار. أوكلي إلى الأب مهمة تجهيز طفلكِ للنوم وإلباسه ملابس النوم في المساء، واكتفي بالمشاهدة من بعيد.'),
  ('2876fc5f-fac3-4af5-b718-9c2f0d9b5314', 'تحتاجين إلى جرعة من الطاقة 🍲', 'هل بلغ التعب أعماق جسدكِ؟ كافئي نفسكِ بإعداد سلطة مميزة في 10 دقائق، تُشعركِ بالشبع وتمنحكِ النشاط في الوقت نفسه.'),
  ('2b82cde7-2302-4ad2-96b7-ca1beedb8f4f', 'نهاية معركة فرشاة الأسنان 🪥', 'هل يطبق فمه فور رؤية فرشاة الأسنان؟ ابحثي في قسم المنتجات الموصى بها عن فُرَش أسنان موسيقية أو دوّارة للأطفال تُسهّل هذه العملية، وحوّلي العناية بالنظافة إلى متعة.'),
  ('c3b0f127-530e-4b11-9687-7c0bcb24de5f', 'عاصفة منتصف الليل 😭', 'هل استيقظ طفلكِ في منتصف الليل باكيًا من دون سبب واضح؟ أهي الغازات أم مجرد نوبات هلع ليلية؟ احتضنيه بهدوء وطمئنيه من دون رفع صوتكِ.'),
  ('127ac6bb-4f6e-424f-91fb-e2d406c68c2a', 'خارج الجدران الأربعة ☕', 'بدأ الروتين المنزلي يشعركِ بالاختناق. افعلي شيئًا مختلفًا اليوم. اذهبي إلى مقهى هادئ قريب لتغيّري الأجواء لطفلكِ وتستمتعي في الوقت نفسه بمذاق قهوتكِ.'),
  ('1e376436-3f0d-4a14-a96b-e1c16c40c937', 'النوم الحساس 🤫', 'هل يفزع طفلكِ من أدنى صوت بمجرد أن يغفو؟ تحققي من صدى الصوت في الغرفة، وشغّلي الضوضاء البيضاء لحجب الأصوات القادمة من النافذة.'),
  ('e0d7037f-df25-46a9-8fd2-5b2b39c1432d', 'تسلّق الأثاث 🧗‍♂️', 'هل يحاول طفلكِ التمسك بالأريكة أو الكرسي والتسلق إلى أعلى؟ تختبر عضلات ساقيه ارتفاعات مختلفة. حافظي على سلامته، لكن لا تمنعي محاولات هذا المتسلق الصغير.'),
  ('458c2efd-1859-4a36-bc6c-218987ce42a4', 'لوحة فنية في الطبق 🥦', 'هل يرفض طفلكِ تناول الطعام؟ أحيانًا لا تكمن المشكلة في المذاق، بل في الشكل. حاولي فتح شهيته بتشكيل وجوه مرحة باستخدام الخضراوات الملونة.'),
  ('6007d88c-cdbb-46d0-9b99-4e7bdd857418', 'تهويدة المساء 🎶', 'لا يمكن لأي تطبيق أو صوت أن يحل محل تهويدة الأم. هذا المساء، ضمّي طفلكِ إلى صدركِ وغنّي له بهدوء تهويدته المفضلة التي تمنحه الشعور بالأمان.'),
  ('ade78fe2-3290-467b-9d4f-4aa0e7d81802', 'أول انتصار في الحمّام! 🚽', 'هل يرغب طفلكِ في الذهاب إلى النونية بنفسه؟ هذا هو أكبر انتصار في عمر 2.5 سنة! سجّلي هذا الإنجاز في متتبّع الحفاض/النونية، واقرئي في المدونات كيف يمكنكِ تسهيل هذه المرحلة الانتقالية أكثر.'),
  ('6c9cc94d-8363-4a16-b062-eb3e2640d824', 'انهيار الذاكرة 🛒', 'هل أضعف الحرمان من النوم ذاكرتكِ، فأصبحتِ تنسين ما عليكِ شراؤه من المتجر؟ لا ترهقي ذهنكِ. اكتبي كل شيء في قائمة، ودعي شريككِ يتولى الأمر عند عودته.'),
  ('8f8c331b-379e-4898-a071-076982bfc0c2', 'مفاوضات دبلوماسية 🤝', 'هل يرفض إعطاء لعبته للآخرين في الحديقة؟ بعد عمر 2.5 سنة، من المهم تعليمه مفهوم اللعب بالتناوب بدلًا من المشاركة. اقرئي في قسم المدونات كيف يمكنكِ غرس هذا المفهوم لديه.'),
  ('e1ad3771-efd0-4fef-8fce-2cfe9cc2174f', 'الاستيقاظ ليلًا 🌌', 'هل يستيقظ طفلكِ باكيًا في منتصف الليل ولا يهدأ؟ راجعي مخطط مؤقت النوم. وتصفحي قسم المدونات الآن لتتعرفي على الفرق بين الرعب الليلي والكوابيس.'),
  ('d3fd3ce0-fc06-4bdf-8472-041feda78c86', 'نوبات العناد 🛑', 'هل يقابل كل «لا» منكِ بالصراخ؟ تحدثي مع Anacan AI لتتعلمي كيفية التعامل بهدوء مع هذه الانفجارات العاطفية التي يصعب السيطرة عليها، واكتشفي أساليب تشتيت الانتباه.'),
  ('de972116-bddf-48f9-bc08-9f55438a9ed7', 'وقت الحكاية مع الأب 📚', 'أوكلي إلى شريككِ هذا المساء مهمة روتين ما قبل النوم! استخدمي وضع الشريك في التطبيق ليتولى هو قراءة الحكاية، بينما تستمتعين أنتِ بكوب من الشاي بهدوء.'),
  ('fd7112b4-d166-4f5f-ab2b-5f43c5c75632', 'تبادل الخبرات 💬', 'هل أخافتكِ حركة جديدة قام بها طفلكِ؟ لا تبحثي عن مقالات مخيفة على الإنترنت. استفيدي من نصائح الأمهات ذوات الخبرة في مجتمع Anacan.'),
  ('0b033378-5688-4baf-b5a5-b23c33fde967', 'سر الحديد: فيتامين C 🍋', 'هل يبدو طفلكِ شاحبًا أو فاقدًا للشهية؟ تحققي من كمية الحديد التي تناولها اليوم عبر أداة متابعة التغذية، وقدمي له مع اللحم سلطة غنية بعصير الليمون لتعزيز امتصاص الحديد.'),
  ('69b9bded-4194-4499-ad7b-42407cdd5970', 'الأطعمة الجافة فقط؟ 🍞', 'هل يرفض طفلكِ الأطعمة المهروسة والسائلة ولا يريد سوى الخبز والبسكويت؟ هذا انتقائية مرتبطة بقوام الطعام. حلّلي قائمته الغذائية باستخدام أداة متابعة التغذية، وابحثي عن بدائل صحية في وصفات الأطفال.'),
  ('a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9', 'أنصتي إلى جسدكِ 🩸', 'هل تنتابكِ فجأة رغبة شديدة في تناول الحلويات وتشعرين بالتوتر؟ راجعي التقويم في متتبع الدورة الشهرية. إذا كنتِ في فترة الدورة الشهرية، فحضّري وجبة خفيفة من التمر والجوز الغنيين بالمغنيسيوم من قسم الوصفات الصحية للنساء.'),
  ('16180139-d7b3-4c7d-9723-1b1d28274883', 'محققة الطبيعة 🔍', 'هل يعبث طفلكِ بكل شيء في المنزل؟ خذي عدسة مكبرة واخرجا! ابحثي عن حديقة خضراء ضمن الأماكن الصديقة للأمهات، واستكشفا الحشرات والأوراق معًا لتوجّهي طاقته نحو الطبيعة.'),
  ('1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8', 'هل أصبح الروتين المسائي صعبًا؟🛀', 'شغّلي موسيقى هادئة في الخلفية أثناء حمّامه الدافئ. فتناغم الماء واللحن يهدّئ حتى أكثر الأطفال عنادًا.'),
  ('39972a4c-ff8f-4f23-abf0-aefe71b44bb9', 'فوضى المنزل 🌪️', 'هل الألعاب متناثرة في كل أرجاء الغرفة؟ ليست النظافة أهم من 10 دقائق مرحة تقضينها معه. ستبقى الألعاب هناك غدًا أيضًا، فلا ترهقي نفسكِ.'),
  ('15d607dd-13ee-4b91-b920-e762edd4acd3', 'البحث عن الهدوء التام 🛋️', 'لا تسارعي إلى تفريغ غسالة الصحون فور نوم طفلكِ! استلقي على الأريكة، وأغمضي عينيكِ، واستمتعي لمدة 15 دقيقة بذلك الهدوء التام والنادر في المنزل.'),
  ('6417fc2a-8680-4b6d-9b78-5b97074e6a4c', 'الاعتياد على الظلام 🌙', 'لتساعدي طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية والشاشات في الغرفة. فلا يتسارع إفراز هرمون الميلاتونين إلا في بيئة هادئة ومظلمة.'),
  ('986722e4-1562-4f18-a164-dd6f65efe855', 'أنا أسمعكِ 🗣️', 'هل ينصت إليكِ باهتمام ويحاول تكوين جمل مشابهة؟ إنه يتحدث معكِ! أجيبيه بالكثير من الابتسامات وشجّعيه على مواصلة هذا التواصل.'),
  ('2eb3f64d-4f32-4bfb-81ca-c75ffc798fd6', 'حان وقت الخروج 🌳', 'هل تشعرين أن الجدران الأربعة تخنقكِ؟ ضعي طفلكِ في عربته واخرجا لاستنشاق الهواء النقي، ولو لمدة 20 دقيقة فقط. سيمنح هدوء الطبيعة طفلكِ ونفسيتكِ أثرًا رائعًا.'),
  ('48fd17bd-f8c5-4be3-9778-ec599f5cc5b0', 'انظري إلى الأسفل! 👣', 'هل بدأ يستمتع بالمشي حافي القدمين واستكشاف الملامس المختلفة بقدميه؟ تحفيز النهايات العصبية في باطن قدميه مهم جدًا لتوازنه.'),
  ('e607fc1e-dfa8-4735-b945-f39209fa5d8a', 'عالم الحكايات الساحر 🪄', 'جرّبي هذا المساء شيئًا مختلفًا تمامًا: حكاية السحابة الصغيرة التي تستكشف السماء. نوّعي نبرة صوتكِ بما يتناسب مع إيقاع الحكاية.'),
  ('4434b892-1b9a-48ea-bd05-6295b7705bc1', 'الهدوء في الروتين المسائي 🌬️', 'هل ظل يركض طوال اليوم ولا يستطيع أن يهدأ الآن؟ فعّلي مؤقت النوم وشغّلي صوت أمواج المحيط من الأصوات البيضاء، وحوّلي الغرفة إلى كهف هادئ للنوم يساعده على تصفية طاقته والاسترخاء.'),
  ('a8561422-a7d3-4164-876d-1471ce35f23d', 'يوم الأب في المطبخ 👨‍🍳', 'فعّلي وضع الشريك. إعداد الغداء وإطعام طفلكِ اليوم من مسؤولية الأب! أما أنتِ، فخصّصي هذا الوقت لنفسكِ واقرئي كتابًا أو استريحي.'),
  ('f2202a7a-5edc-4209-b790-4083df0975d2', 'الحبو الهادف 🐢', 'هل أصبح، إلى جانب المشي، يحبو أحيانًا بسرعة هاربًا منكِ من أجل المرح؟ أزيلي العوائق الخطرة من الغرفة وانضمّي إليه في لعبة المطاردة والإمساك هذه.'),
  ('9f77c4af-512a-49b9-8cbf-0c7c57609122', 'فيتامين D للعظام ☀️', 'فيتامين D ضروري لامتصاص الكالسيوم! تحقّقي من نظامه الغذائي اليوم باستخدام أداة متابعة التغذية، واطّلعي في قسم المنتجات الموصى بها على القطرات التي ينصح بها الأطباء.'),
  ('a85116cf-7f79-486c-8e28-8b90c93cfb63', 'أزمة التأخر 🛑', 'عليكِ مغادرة المنزل، لكنه يفعل كل شيء ببطء ولا يستعجل؟ في هذا العمر، لا يدرك الطفل مفهوم الوقت! بدلًا من استعجاله، تعلّمي من خبير Anacan AI كيف تجعلين الانتقال من نشاط إلى آخر أكثر سهولة.'),
  ('b222d604-2c4a-4c8d-9eda-efff14884581', 'البحث عن الأم المثالية 💖', 'هل نفد صبركِ اليوم وارتفع صوتكِ؟ لا تشعري بالذنب. بعد أن ينام طفلكِ، خفّفي عن نفسكِ بكتابة ما يثقل صدركِ في يوميات المزاج.'),
  ('259a4698-04af-4cc3-93e9-91599ab8a275', 'هل حان وقت توديع القيلولة؟ ⏱️', 'هل يرفض طفلكِ القيلولة تمامًا ثم يصبح شديد الإرهاق مساءً؟ حلّلي إحصاءات مؤقت النوم وجرّبي الانتقال إلى نظام ساعة الهدوء (quiet time).'),
  ('278f2f23-c655-4241-807c-401148d291e5', 'أزمات متلازمة ما قبل الحيض لدى الأم 🍫', 'هل تنخفض طاقتكِ قبيل دورتكِ الشهرية؟ قبل اللجوء إلى الأدوية، استعيدي نشاط جسمكِ بتحضير سموذي التوت المحلّى طبيعيًا، الذي يمنحكِ طاقة فورية، من قسم الوصفات الصحية للنساء.'),
  ('af74ff56-7d79-46b1-8bf0-e27bd2c06fed', 'سأقطّعه بنفسي! ✂️', 'هل يريد طفلكِ تقطيع الموز أو عجينة اللعب بنفسه في المطبخ؟ إنها رغبة رائعة تتطلب مهارات حركية دقيقة! اطّلعي فورًا في قسم المنتجات الموصى بها على السكاكين والمقصات الآمنة وغير الحادة المخصصة للأطفال.'),
  ('04970a72-c396-466c-9613-3a82e661e79f', 'لا يعرف لماذا يبكي 😭', 'هل يمر طفلكِ بنوبة غضب شديدة لأن الكوب أحمر وليس أزرق؟ قد يكون السبب الحقيقي هو التعب أو فرط التحفيز العاطفي. تحدّثي إلى الذكاء الاصطناعي من Anacan لتتعلمي كيفية التعامل بهدوء مع هذه الانفجارات العاطفية التي يصعب السيطرة عليها.'),
  ('c150e539-1698-44fc-be7c-18e8beb9b566', 'الأصوات الغريبة في الغرفة 🌌', 'هل يوقظ طفلكِ الصمت التام في الغرفة أو أصوات الطرق الخافتة القادمة من الجيران؟ شغّلي صوت المروحة من قسم الضوضاء البيضاء، ولاحظي كيف يصنع عزلًا صوتيًا مثاليًا في بيئة النوم.'),
  ('f0684802-cf6d-4a4b-96a5-44c5cabd2832', 'تنظيف المنزل معًا 🧹', 'هل يحتاج المنزل إلى التنظيف؟ فعّلي وضع الشريك! اكتشفي كيف يمكنكِ أنتِ ووالده وطفلكما الصغير، بعد إعطائه قطعة قماش صغيرة، تحويل التنظيف إلى لعبة عائلية ممتعة.'),
  ('20745776-36d1-4511-abf0-1fafb63ced1d', 'اللعب بدلًا من الشاشة 📱', 'هل يطلب طفلكِ مشاهدة الرسوم المتحركة بعد الظهر ويبكي؟ تعلّمي من الذكاء الاصطناعي من Anacan كيف تحدّين من وقت الشاشة دون توتر، وكيف تحوّلين انتباهه فورًا إلى لعبة أخرى.'),
  ('956585f5-6347-4c88-b6a3-3638bd223889', 'حان وقت قهوتكِ ☕', 'هل سئمتِ من البقاء في المنزل طوال الوقت؟ ابحثي ضمن الأماكن الصديقة للأمهات عن مقاهي الأطفال التي ترتادها الأمهات بكثرة، واخلقي لنفسكِ بيئة جديدة للتواصل الاجتماعي.'),
  ('96e63d94-22cd-4a99-8350-f721e6ade562', 'فن انتظار الدور 🧸', 'هل يرفض انتظار طفل آخر حتى ينزل عن الزحليقة في الحديقة؟ بعد عمر 2.5 سنة، احرصي على قراءة كيفية تعليمه الصبر واللعب بالتناوب في قسم المدونات.'),
  ('1cf87075-900c-4f1c-a89d-b12b8314ac9b', 'فحص مخزون الحديد 🥩', 'هل يبدو شاحبًا أو فاقدًا للشهية؟ تحققي من كمية الحديد التي تناولها اليوم عبر أداة متابعة التغذية، وقدّمي له مع اللحم سلطة غنية بعصير الليمون لتعزيز امتصاص الحديد.'),
  ('9c0be1cd-f5f7-43c2-bf11-199a917727ea', 'تدليك من الأب 💆‍♀️', 'هل تشنّج ظهركِ من الركض خلف طفلكِ طوال اليوم؟ استخدمي ميزة الشريك لتخبريه بأن الوقت قد حان ليمنحكِ هذا المساء تدليكًا قصيرًا للكتفين بعد أن يُنيم طفلكما.'),
  ('fcd8e598-c584-4111-a575-0192c20a2ba3', 'حوّلي شرب الماء إلى لعبة 💧', 'هل يركض كثيرًا ويشرب القليل من الماء؟ يزداد بذلك خطر الإمساك. سجّلي التبرز في التطبيق، ثم أضيفي الشوفان إلى قائمته الغذائية فورًا باستخدام أداة متابعة التغذية، واطلبي له زجاجات ماء ملوّنة من قسم المنتجات الموصى بها.'),
  ('819da396-26ce-4c11-baf2-c21f3a1ad406', 'انتقائية الطعام 🍝', 'هل لا يريد سوى المعكرونة؟ تحققي من التوازن الغذائي الأسبوعي باستخدام أداة متابعة التغذية. لا ترهقي نفسكِ بسبب القلق بشأن يوم واحد فقط.'),
  ('f0c36b67-8799-4202-8ab4-a072283a2c59', 'دموع الإرهاق 💧', 'هل تشعرين أنتِ أيضًا برغبة في البكاء؟ هذا طبيعي تمامًا. اكتبي مشاعركِ في يوميات المزاج، وتخلّي عن الشعور بالذنب.'),
  ('f35164ca-a4af-42c5-8f5c-d2b4e2de79f4', 'هل يتعرّف على الأرقام؟ 🔢', 'هل يحاول عدّ الأشياء أثناء صعود الدرج أو جمع ألعابه؟ أضيفي هذه الشرارات الأولى لتطوره الرياضي فورًا إلى ألبوم طفلكِ في مقطع فيديو مصحوب بصوته، وحوّليها إلى ذكرى تدوم مدى الحياة.'),
  ('d32651ed-78b7-4090-bd14-46fc6e60d9a7', 'نوبات الغضب بسبب الشاشة 📱', 'هل تقوم القيامة عندما تأخذين الهاتف؟ اسألي Anacan AI عن أسرار نفسية عملية وفعّالة لوضع حدود لوقت الشاشة من دون توتر.'),
  ('49972eb0-ce9d-4cba-ad0b-3cc84b80e743', 'نوبات الفزع الليلي 🤖', 'هل يستيقظ طفلكِ في منتصف الليل صارخًا ولا يتعرّف إليكِ؟ تعرّفي فورًا إلى ما ينبغي فعله في هذه الحالة وكيفية تمييزها، من خلال المقالات في قسم المدوّنات.'),
  ('4efefe1c-c867-4006-9142-0718a80c34db', 'لديكِ صديقات أيضًا ☕', 'الحديث مع طفلكِ وحده طوال الوقت مُرهق. اعثري على مقاهي الأطفال ضمن الأماكن الصديقة للأمهات، واستمتعي بفنجان قهوة وتواصلي مع أمهات أخريات.'),
  ('a185d77d-1385-43cb-bec6-87f42c458382', 'نوبات الغضب الصباحية 🛑', 'هل يبكي طفلكِ كلما قلتِ «لا»؟ تحدّثي إلى Anacan AI لتتعلمي كيفية التعامل بهدوء مع الانفجارات العاطفية وتشتيت انتباهه.'),
  ('1d63f653-1008-4746-a730-0e985e6ca79c', 'دعيه يتّسخ 🏖️', 'هل يريد اللعب بالطين؟ دعيه يتّسخ! اعثري ضمن المنتجات الموصى بها على أفضل المستلزمات التي تدعم نمو الحواس.'),
  ('ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4', 'طفرة في الطول 📏', 'هل أصبحت قمصانه قصيرة؟ إنه يكبر! أدخلي قياساته الحالية في متتبّع الوزن، وشاهدي بفخر كيف يرتفع منحنى نموه.'),
  ('cd4b46fb-6caf-421b-9a9e-22b85cfd2d73', 'شاي دافئ وهدوء 🍵', 'توقّف المؤقّت ونام طفلكِ. انسي الأعمال المنزلية! حضّري شاي المليسة من وصفاتنا الصحية، واستمتعي بالهدوء فحسب.'),
  ('3e08f834-ae99-412b-94f4-fcb284f337ca', 'تحليل الروتين ⏱️', 'هل يستغرق طفلكِ وقتًا طويلًا لينام مساءً؟ راجعي مخطط مؤقّت النوم. ربما حان الوقت لتقليص مدة قيلولته النهارية بشكل ملحوظ.'),
  ('02944013-1945-43f5-a622-bb7657b42970', 'أخفي الخضراوات 🥦', 'هل يرمي الخضراوات الورقية أو البروكلي من طبقه؟ اكتشفي في وصفات الأطفال كعكة منزلية ملونة وغنية بالخضراوات، وحققي بسهولة احتياجكِ اليومي من الفيتامينات في أداة متابعة التغذية.'),
  ('45019ac4-08ed-4d8b-8186-060ceb70601a', 'أنتما فريق رائع 🌟', 'كل مهارة جديدة يتعلمها وكل خطوة واثقة يخطوها هما ثمرة جهودكِ وجهود شريككِ. افتحي مفكرة المزاج وصفّقا لنفسيكما اليوم تقديرًا لعملكما كفريق!'),
  ('5613e3d7-d67b-4e9a-b92f-7ce15054b42e', 'طفرة في الطول والوزن! 📏', 'هل لاحظتِ عند إلباسه أن قمصانه أصبحت ضيقة أو أن حذاءه بات يضغط على قدميه؟ أدخلي طوله وقياساته الحالية في متتبع الوزن، وشاهدي بفخر كيف يرتفع منحنى نموه.'),
  ('3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e', 'وقت حكاية الأب 📚', 'مهمة تهيئة طفلكِ للنوم هذا المساء على عاتق شريككِ. دعيه يقرأ الحكاية، واستمتعي أنتِ بهذه الاستراحة القصيرة التي أُهديت إليكِ.'),
  ('751db3a1-bc4d-4599-b35d-5aadaed3cfca', 'أسئلة «لماذا؟» 🤔', 'إنه يريد فهم العالم. تعرّفي في المدونات إلى كيفية الإجابة بصبر عن أسئلته التي لا تنتهي. صبركِ يساهم في نموه.'),
  ('ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c', 'ضاقت بكم جدران المنزل الأربعة 🌳', 'هل يقلب طفلكِ كل شيء في المنزل رأسًا على عقب؟ اعثري على متنزه قريب عبر الأماكن الملائمة للأمهات. فالهواء النقي أفضل علاج لكِ وله.'),
  ('034073b2-a550-46ff-9473-8411c49fc4ec', 'الحديد والقوة 🥩', 'هل يبدو شاحبًا؟ تحققي من كمية الحديد التي يتناولها في أداة متابعة التغذية. وقدّمي له إلى جانب اللحم سلطة بالليمون لتعزيز امتصاص الحديد.'),
  ('3e853511-fee0-4626-9f71-c751f4b255ca', 'معركة فرشاة الأسنان 🪥', 'هل يهرب عندما يرى الفرشاة؟ اطلعي على الفُرش الموسيقية في قسم المنتجات الموصى بها. حوّلي العناية بالنظافة من واجب مفروض إلى لعبة ممتعة.'),
  ('6c779bea-dc2a-41ad-8ebb-96d5620eee3b', 'درع الكالسيوم 🦴', 'ألا يشرب الحليب؟ الكالسيوم ضروري للعظام. استخدمي أداة تتبّع التغذية لحساب ما يتناوله من الزبادي أو البروكلي وتعويض أي نقص.'),
  ('9550715f-5ff1-4a49-8dae-33944b52477f', 'جمل طويلة 🗣️', 'هل بدأ طفلكِ يروي قصصًا مضحكة؟ إن مفرداته تتطور بسرعة مذهلة! لا تفوّتي هذه اللحظة الذهبية، وسجّلي صوته كذكرى في ألبوم طفلكِ.'),
  ('2d4c6405-93aa-4a22-9aae-af7a8dcd04fc', 'الاستيقاظ المبكر 🌅', 'هل يستيقظ طفلكِ قبل شروق الشمس مفعمًا بالطاقة، بينما أنتِ منهكة؟ اسألي Anacan AI عن كيفية تنظيم هذا النمط. الحرمان من النوم لن يدوم إلى الأبد.'),
  ('49091c89-e2f8-4ecf-a7b6-b705116efa46', 'حكاية الأب 📚', 'فعّلي وضع الشريك. هذا المساء، الأب هو بطل الحكاية! دعيه يقرأ، بينما تُعِدّين قهوتكِ وتستمتعين بالهدوء خارج الغرفة.'),
  ('865b1ef2-1722-47cc-bf4d-3108a098404b', 'معضلة المشاركة 🧸', 'ألا يسمح لأحد باللعب بألعابه؟ هذا ليس أنانية، بل مرحلة طبيعية من نموه. تعلّمي من المدوّنات كيف تعلّمينه اللعب بالتناوب.'),
  ('983d85d9-b1dc-40ec-a012-9c7aba93c4d9', 'الدموع طبيعية 💧', 'هل أنتِ متعبة ولا تريدين سوى البكاء؟ أن تكوني أمًا قوية يعني أحيانًا أن تكوني قادرة على الاعتراف بضعفكِ.'),
  ('ee623f8b-a47a-4ef6-96d3-5754f3e3cd43', 'انخفاض الطاقة ⚡', 'هل تكادين تغفين واقفة عند الظهيرة؟ لا تلجئي إلى الكافيين، بل إلى البروتين! استعيدي نشاطكِ بسموذي زبدة الفول السوداني من وصفاتنا الصحية، فهو يمنحكِ طاقة فورية.'),
  ('fe3bdaaa-fafd-445d-b4e7-84a8026c6168', 'نوبات الصراخ المفاجئة 🛑', 'هل يرمي طفلكِ نفسه على الأرض بلا سبب واضح؟ شاركي مخاوفكِ مع Anacan AI لتتعلمي كيفية التعامل مع هذه النوبات بهدوء وتجاهل نظرات الآخرين.'),
  ('65dda26f-c428-4285-904a-5e44f932685c', 'نتخطى الأمر معًا 🥂', 'بعد أن ينام طفلكِ، اجلسي وجهًا لوجه مع شريككِ. وبدلًا من الحديث عن الطفل، ابتسما لبعضكما وقولا: «لقد نجونا اليوم أيضًا»، واستشعرا روح الفريق بينكما.'),
  ('68aff420-6957-4fb3-8fd3-172910f79641', 'حين يصبح الخروج ضرورة ⛅', 'هل تشعرين بأن الجدران الأربعة تخنقكِ؟ تحققي من درجة الحرارة الفعلية باستخدام أداة الطقس والملابس، ثم انطلقي إلى الحديقة من دون تردد. فالهواء النقي يهدئ حتى أشد نوبات الانفعال فورًا.'),
  ('70cc8a60-04a1-4e4e-b5c3-986f74563498', 'حذاء يستغرق ارتداؤه 20 دقيقة 👟', 'هل يصرّ على ارتداء حذائه بنفسه، فيتأخر خروجكما من المنزل؟ لا تدعي صبركِ ينفد.'),
  ('e2414d34-11c4-4990-9c63-38d30534a147', 'الجمل تصبح أطول 🗣️', 'أصبح الآن يربط الكلمات ببعضها ويكوّن جملًا طريفة تتوافق تمامًا مع منطقه الخاص. لا تفوّتي هذه اللحظات، وسجّلي حواراته اللطيفة بالفيديو باستخدام جلسة تصوير الطفل.'),
  ('ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f', 'ألعاب الظلام 🐰', 'هل يخاف عندما تنطفئ الأنوار؟ اجعلي الغرفة مظلمة تمامًا وابتكري ألعاب الظلال على الحائط باستخدام مصباح يدوي. حوّلي خوفه إلى متعة وساعديه على التصالح مع الظلام.'),
  ('005f91e2-a696-4de0-bf24-bb840b614746', 'طفرة في الطول والوزن 📏', 'هل أصبحت سراويله قصيرة مجددًا؟ إنه ينمو بسرعة! أدخلي قياساته الحالية في متتبّع النمو، وانظري بفخر إلى منحنى نموه الصاعد، ثمرة لياليكِ التي قضيتِها بلا نوم.'),
  ('4d0ac53a-0a7d-40d8-a958-4dd99382d977', 'استيقاظ بلا سبب 😭', 'هل استيقظ في منتصف الليل وهو يصرخ؟ لا تقلقي. استخدمي أداة تحليل البكاء للتحقق مما إذا كان السبب آلام النمو أم نوبات الذعر الليلي، ثم احتضنيه بصبر.'),
  ('7a36ad44-2dba-4854-82a6-8b3c27a56c6f', 'قهوة باردة كالثلج ☕', 'أن تُعدّي القهوة ثم تشربيها بعد 3 ساعات هو القانون الرسمي غير المكتوب للأمومة. افعلي شيئًا مختلفًا اليوم: دعيه يلعب وحده بألعابه، واشربي قهوتكِ ساخنة خلال 10 دقائق!'),
  ('d7ebaa5c-a836-4c14-8fc7-8ddab08162c6', 'تمويه الخضراوات 🥦', 'هل يدفع طفلكِ كل ما هو أخضر في طبقه إلى الجانب؟ لقد بلغ انتقاؤه للطعام ذروته. ستجدين في قسم خطة التغذية وصفات ذكية لهرس الخضراوات وإخفائها داخل أقراص الكفتة.'),
  ('2461cdb3-c847-4528-8c72-5b1258b6ff1d', 'الحدود في الحديقة 🧸', 'هل يرفض إعطاء دلوه لأي شخص في صندوق الرمل؟ هذه ليست أنانية، بل بداية إدراك مفهوم الملكية. علّميه المشاركة بالتناوب لا بالإجبار: الآن حان دوره.'),
  ('b0edd680-c98e-4626-b7fa-18383befe832', 'وصل الضيوف الخياليون ☕', 'هل يتحدث بمفرده في الغرفة مع أصدقاء غير مرئيين ويصب لهم الشاي؟ هذه ذروة تطور الخيال! راقبي كاتب السيناريو المبدع هذا من بعيد بكل فخر.'),
  ('dea0086a-894a-4d43-a110-0948ee956740', 'عصا السحر بيد طفلكِ 🪄', 'هل ملّ الحكايات الكلاسيكية؟ دعيه هذه المرة يختار بطل الحكاية الذكية بنفسه. كلب طائر أو شجرة ناطقة؛ أطلقي العنان لخياله.'),
  ('0a08658d-8354-4bb5-9ba8-b4c528e517fc', 'يضع قواعده بنفسه 🛑', 'هل يقول عن كل شيء: سأفعله بنفسي! يرتدي حذاءه بالمقلوب وقميصه بطريقة خاطئة، لكنه يصر على ذلك. لا بأس، فرغبته في الاستقلال أهم من المظهر، لذا دعيه يحاول.'),
  ('411275c3-b6bc-4218-a886-bbf3ee4ba697', 'العلاج بالماء 🛀', 'بعد يوم كامل من الركض، توترت أعصابه وأعصابكِ أيضًا. الحمام الدافئ ليس للنظافة فحسب، بل للاستفادة من قدرة الماء الساحرة على تخفيف التوتر.'),
  ('d5a4b327-9717-431f-8c67-ec44df34af85', 'الشعور بالإنهاك 🔋', 'هل تشعرين برغبة في الصراخ بسبب كل شيء؟ هذا احتراق نفسي. انضمي فورًا إلى مجتمع Anacan، واقرئي تجارب أمهات يعشن المرحلة نفسها لتحصلي على الدعم.'),
  ('38c563a6-395b-403a-8ffd-c4d46a16b207', 'مشاغبة في المطبخ 🧑‍🍳', 'هل يقيم حفلة موسيقية بالقدور بينما تطهين؟ إنه يريد أن يكون فردًا من الفريق أيضًا. أعطيه قطعة صغيرة من العجين ودعيه يشارككِ الطهي.'),
  ('ead40251-f5fc-4b01-b344-4b041fbbf0eb', 'أجمل حِمل 🫂', 'دفعكِ إلى الجنون طوال اليوم، وبكى بسبب كل شيء. لكن رائحة ذلك الجسد الصغير الدافئ وهو يلوذ بصدركِ عند النوم مساءً... هذا هو أجمل شعور في العالم.'),
  ('41765791-323c-438b-b416-30b7105b9c01', 'مكان للأم ☕', 'هل سئمتِ من الذهاب إلى الحديقة نفسها كل يوم؟ اكتشفي من بين الأماكن الصديقة للأمهات مقهى مختلفًا وهادئًا يمكن للأطفال اللعب فيه براحة، ودلّلي نفسكِ اليوم.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('dc90d262-2720-4f19-9f2a-dcf90cd5da80'::uuid, 'فهم الأشكال والمكان 🧩', 'يُصرّ طفلكِ على تركيب قطع الأحجية وإدخال الأشكال المختلفة في فتحاتها المناسبة. لا تتدخلي حتى إن أخطأ، فهو يتعلم مهارة حل المشكلات تحديدًا من خلال التجربة والخطأ.'),
  ('e0925ec9-2283-4167-888a-ee7948c21d0f', 'ضوضاء بيضاء طبيعية 🤫', 'يكون الدماغ في أعلى درجات نشاطه خلال أول نصف ساعة بعد الاستغراق في النوم. اضبطي مستوى الصوت في الغرفة باستخدام مقياس شدة الصوت. أحيانًا قد يكون صوت المطر الخفيف وحده كافيًا لينعم طفلكِ بنوم عميق.'),
  ('28ff0d8a-2265-4669-8253-5aac2bfb80da', 'اشكري نفسكِ 🎈', 'ليالٍ بلا نوم وأيام مليئة بالركض والانشغال... لكنكِ نجحتِ. قولي لنفسكِ اليوم: أحسنتِ، لأنكِ ترعين طفلكِ دون أن ترفعي صوتكِ!'),
  ('95ffd69a-c8c2-4b14-b98e-76c322f02229', 'الذهاب إلى المتجر بلا قائمة؟ مستحيل! 🛒', 'تذهبين إلى المتجر معتمدةً على ذاكرتكِ، ثم تعودين إلى المنزل من دون أهم ما تحتاجين إليه. توقفي عن ذلك، واجعلي تدوين كل ما ينقص في المنزل فورًا ضمن قائمة التسوق عادةً يومية.'),
  ('ec24c154-30dc-40d8-8aed-20579933d8fb', 'أطلقي العنان لمشاعركِ 📝', 'ألا يفهمكِ أحد؟ ألا يرى أحد مدى تعبكِ؟ مفكرة الحالة المزاجية هي خير كاتمة لأسراركِ. دوّني فيها كل ما تشعرين به من توتر وألم ووحدة، وستلاحظين كم سترتاح نفسكِ.'),
  ('093d545f-b52d-4160-be2f-88e5e1b53427', 'معركة الخضراوات مستمرة 🥦', 'هل رأى مجددًا قطعة الجزر الصغيرة في الحساء ورفض تناوله؟ صغّري الحصص وغيّري الأشكال، فالإبداع هو أقوى سلاح لدى الأم.'),
  ('59dde031-61d1-4132-874a-bbebe2bc223a', 'مأساة البسكويت المكسور 🍪', 'هل انتهى العالم لأن قطعة البسكويت انقسمت إلى نصفين؟ أهلًا بكِ في أزمات عمر 2.5 سنة الكلاسيكية. لا تبحثي عن المنطق، بل أخبري طفلكِ ببساطة أنكِ تتفهمين هذا الحزن الكبير.'),
  ('5e26eff6-747b-42a4-909a-13e90be41e9d', 'الواقع بلا فلاتر 🛑', 'هل تشاهدين مقاطع الأطفال الهادئين والنظيفين على شبكات التواصل الاجتماعي ثم تلومين نفسكِ؟ إنها مجرد أوهام لا تتجاوز 15 ثانية. واقعكِ الفوضوي والصاخب هو الأجمل.'),
  ('db6eccad-9548-4b17-8f6b-0466160ee8dc', 'احتجاج على ارتداء ملابس النوم 👕', 'لا يريد ارتداء ملابسه ويركض في المنزل؟ حوّلي المواجهة إلى لعبة. لنرَ من سيرتدي ملابسه أسرع؟ فالمنافسة غالبًا أفضل وسيلة لكسر العناد.'),
  ('118d8e02-86c1-4716-8dfd-287849e960b7', 'بدأ جهاز التسجيل الصغير بالعمل 🎙️', 'هل يكرر فورًا حتى أكثر الكلمات عفوية مما تقولينه؟ إنه مرآتكِ الحية. في هذا العمر، تنمو حصيلته اللغوية بسرعة هائلة، لذا دوّني هذه الكلمات الجديدة في متتبّع النمو.'),
  ('4ffb5f4c-fcb6-4d97-8d29-5662777e74bb', 'تسوّق سريع 🛒', 'هل شتّتت قلة النوم انتباهكِ؟ وهل تنسين باستمرار ما عليكِ شراؤه؟ أضيفي كل شيء فورًا إلى قائمة التسوق، ودعي زوجكِ يتولى مسؤولية التسوق بالكامل.'),
  ('8658617d-87c3-40a0-a148-d3af3d34503e', 'مسرح حكايات الأب 📖', 'لقد تعبت أحبالكِ الصوتية من قول «لا» طوال اليوم. سلّمي مهمة حكاية المساء إلى الأب اليوم. دعيه يغيّر نبرات صوته ويروي قصصًا طريفة، بينما تستريحين أنتِ.'),
  ('5d60ba67-a127-4fbd-bd24-40125cd3bcc8', 'لوحة الفنان الجديدة 🖍️', 'هل نفدت الأوراق وأصبح الآن يريد الرسم على الحائط أو الباب؟ إنه لا يشخبط، بل يستكشف العالم بمهاراته الحركية الدقيقة. أعطيه قطعة كبيرة من الورق المقوّى وحددي له المساحة المسموح بها.'),
  ('b27a302e-b37e-4606-900b-22135e770f9b', 'ملامسة السكون 🤫', 'انتهت فوضى المنزل أخيرًا ونام طفلكِ. افتحي مقياس الصوت، وتحققي من مستوى الهدوء في الغرفة، ثم استمتعي بهذا السكون لمدة 15 دقيقة من دون النظر إلى أي شاشة.'),
  ('1e03f3e4-2305-4ae5-883c-39581f248697', 'يكتشف الأرقام 🔢', 'يحاول العدّ قائلًا: واحد، اثنان، ثلاثة، أثناء صعود الدرج أو ترتيب ألعابه. ادعمي هذه المرحلة الرياضية من تطوره المعرفي بالعدّ معه.'),
  ('2e1f0716-93b5-4be3-9000-fdb28349534d', 'سلاح الأب السري 🤡', 'عندما لا تعود حيلكِ مجدية، تنقذ الأصوات الغريبة والوجوه المضحكة التي يصنعها الأب الموقف فورًا. في نوبات المساء، سلّميه المهمة مباشرةً.'),
  ('b24ba903-09d2-4243-a80b-995524b45caf', 'مقاومة القيلولة 🥱', 'ألا يريد الذهاب إلى السرير إطلاقًا؟ يبدأ بعض الأطفال في عمر 2.5 سنة برفض القيلولة. لا تجبريه على النوم، بل استبدلي القيلولة بوقت هادئ لقراءة الكتب لمدة 30 دقيقة.'),
  ('54501d8f-f370-4895-a96c-448bca275b4e', 'انظري إلى الأسفل، ماذا هناك؟ 👣', 'يستمتع طفلكِ كثيرًا بالمشي حافي القدمين وملامسة الأسطح المختلفة مثل الرمل والسجاد والحجر. ويسهم تحفيز الأعصاب الموجودة في باطن قدميه بدور مهم في تطوره العصبي.'),
  ('7212233e-c5da-4c83-bd8d-a74e469e3fcc', 'خفّفي الإضاءة 🌙', 'أطفئي جميع الأضواء القوية والشاشات ذات الضوء الأزرق في المنزل قبل النوم بساعة واحدة. هيّئي في المنزل أجواءً مسائية خافتة لمساعدة الجسم على إفراز هرمون الميلاتونين.'),
  ('efc5b454-d92c-49c6-a2a5-9e995c6d9a84', 'القلق بشأن الطبيب 🤖', 'هل تساوركِ شكوك بشأن اللقاحات أو الفيتامينات اللازمة في عمر 2.5 سنة؟ لا تضيعي بين المنتديات المخيفة على الإنترنت، واحصلي فورًا على إجابة دقيقة من Anacan AI.'),
  ('235bf352-67d4-4056-94d7-5429271d340f', 'جدالات صغيرة 🗣️', 'لا، أنا كبير وأعرف ما أفعله! بدأ يحاول مخالفتكِ مستخدمًا الحجج. أجيبيه بهدوء، ومن مستوى نظره نفسه، ولكن بحزم، من دون رفع نبرة صوتكِ.'),
  ('ae99921f-bf29-40ac-a251-a633a4741d07', 'تخصيص وقت لنفسكِ ليس ذنبًا 💆‍♀️', 'شعور «لا أقضي وقتًا كافيًا مع طفلي» يراود كل أم. لكنكِ تنسين أن الأم المنهكة لن تجد ما تمنحه لطفلها. خصّصي لنفسكِ استراحة لمدة 20 دقيقة ظهرًا لتلتقطي أنفاسكِ.'),
  ('0e43d226-9cd6-4c62-b9a7-e0206f0830ca', 'مفاجأة «وجدتُك!» 🙈', 'لقد تغيّرت قواعد لعبة الغميضة؛ فأصبح طفلكِ هو من يختبئ، ثم يخرج صارخًا: «أنا هنا!». دعيه يبتكر قواعد اللعبة واستمتعا بالضحك معًا.'),
  ('39e6032f-d2bf-40b5-98db-1f2ab3a5a379', 'سكينة المساء 🛀', 'إذا كان طفلكِ شديد العناد والانفعال هذا المساء، فضعيه في ماء فاتر. إن مجرد لعبه بالماء في حوض الاستحمام، بما للماء من أثر علاجي، سيساعده على التخلص من كل طاقته السلبية.'),
  ('2c4fbb59-42cd-4340-ba93-aee620d9df26', 'دندنة الأغاني 🎶', 'أثناء اللعب، يغني طفلكِ لنفسه مستخدمًا كلمات غير مفهومة. وهذه علامة على تطور النطق والسمع معًا. احرصي على تسجيل هذه المرحلة الجديدة في متتبّع النمو.'),
  ('491d12b8-51d5-4984-8dda-d40fbb4e95c8', 'وقت القراءة مع الأب 📖', 'لنُضفِ هذا المساء أجواءً مختلفة على الغرفة. أوكلي مهمة قراءة الكتاب إلى صوت الأب العميق والمطمئن، واستمتعي أنتِ في زاوية بقليل من الهدوء التام.'),
  ('c32299af-eeac-42f3-ab67-01688b0d4551', 'مجموعة دعم الأمهات 💬', 'هل عليكِ اتخاذ قرار صعب؟ (الحضانة، استخدام النونية، النوم). ستجدين في نصائح الأمهات ذوات الخبرة في مجتمع Anacan حلولًا واقعية لا يذكرها أي كتاب.'),
  ('1c02ca47-65ab-4daa-8468-3f801795414a', 'دعي المنزل فوضويًا 🌪️', 'هل سئمتِ من جمع الألعاب نفسها في الصندوق كل مساء؟ لا تجمعيها اليوم! فالمنزل ليس متحفًا، بل مكان ينبض بالحياة وينمو فيه مستكشف صغير.'),
  ('890c1216-15b7-4852-b1cb-42e4a141e897', 'الرمي والتقاط الكرة بمهارة ⚾', 'لم يعد طفلكِ يترك الكرة الكبيرة التي ترمينها إليه تفلت منه فحسب، بل يحاول التقاطها. إن التناسق بين عينيه ويديه يتطور بسرعة. نظّمي معه ألعابًا رياضية صغيرة في الممر.'),
  ('a764d770-048d-4a17-b477-fc4f761c3c2d', 'لا نوم من دون حكاية 🪄', 'أطفئي أضواء الغرفة تمامًا. اختاري من الحكايات الذكية خلفية هادئة ومريحة بلا كلمات، تقتصر على أصوات الطبيعة (الرياح، الغابة)، لتسهّلي الانتقال إلى النوم.'),
  ('1beec453-866b-4504-9a19-59d21f2305e4', 'قلق الانفصال مجددًا؟ 🥺', 'حتى عندما تذهبين إلى المرحاض، ينتظركِ خلف الباب ويبكي. قد يعود قلق الانفصال أحيانًا. طمئنيه بصوتكِ في كل مرة، وأخبريه أنكِ موجودة وستعودين، حتى لو كنتِ في غرفة أخرى.'),
  ('01e5d997-771c-4149-81ec-cf5e1b89ede9', 'تفريغ الطاقة ضروري 🌳', 'البقاء بين أربعة جدران يجعله عدوانيًا. ضعيه في عربته أو أمسكي بيده واخرجا لاستنشاق الهواء النقي. هدوء الطبيعة سيؤثر بصورة رائعة في نفسية طفلكِ ونفسيتكِ أيضًا.'),
  ('149c401f-2cba-4bc8-b3fb-54e3507ca6f5', 'الاعتياد على الظلام 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة. لا يُفرَز الميلاتونين سريعًا إلا في بيئة هادئة ومظلمة.'),
  ('1d84618d-c436-422f-bb3e-95d3ae0487d6', 'سيل «ما هذا؟» ☝️', 'هل يشير بإصبعه إلى كل شيء ويسأل عن اسمه؟ إنه يريد منكِ أن تعرّفيه إلى أسماء الأشياء من حوله. إنها قفزة كبيرة في التواصل! كرري له بصبر اسم كل غرض يشير إليه.'),
  ('0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2', 'فرحة التصفيق 👏', 'هل يصفق لنفسه بفخر عندما ينجح في فعل شيء؟ إنه يبحث عن استحسانكِ! صفّقي أنتِ أيضًا لهذا الإنجاز الصغير بفرح كبير وشجعيه.'),
  ('25c7776c-5416-4926-9ebf-f1fff97f3809', 'هل لديكِ سؤال؟ 🤖', 'هل يقلقكِ مخطط طول طفلكِ ووزنه بعد عمر 2.5 سنة؟ بدلًا من قراءة مقالات مخيفة على الإنترنت، احصلي من Anacan AI على معلومات دقيقة ومستندة إلى أسس علمية.'),
  ('8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2', 'أصوات الأب الغريبة 🤡', 'عندما لا تنجح محاولاتكِ، تنقذ أصوات الأب الغريبة الموقف. خلال نوبات الانفعال المسائية، أوكلي إليه المهمة فورًا وابتسمي وأنتِ تراقبين من بعيد.'),
  ('186e8c82-10c6-4dcc-8ae8-517e2888e663', 'لحن المساء 🛀', 'لقد أنهككما الركض طوال اليوم. حمّام دافئ ولحن هادئ وعذب في الخلفية سيهدّئان جهازه العصبي تمامًا.'),
  ('1c8d40ed-ce45-4ab5-a646-af121febdc6b', 'فخر الفريق 🥂', 'لقد اجتزتما يومًا صعبًا. بعد أن ينام طفلكِ، حضّري كوبًا من الشاي مع شريككِ، وشجّعا بعضكما قائلين: نحن حقًا نؤدي هذه المهمة على أكمل وجه.'),
  ('b19556d6-123c-4633-b806-8552c2789139', 'الطقس متقلّب ⛅', 'عندما تخرجين للتنزّه، لا تدعي الطقس يخدعكِ فتعرّضي طفلكِ للبرد. لا تتخذي قراركِ بمجرد النظر من النافذة، بل استخدمي مساعد الطقس والملابس لاختيار الزي الأنسب للأجواء في الخارج.'),
  ('d7f16071-fb32-41c6-bf73-3b61867ff844', 'قفزات جريئة 🧗‍♂️', 'يلقي طفلكِ بنفسه من الأريكة فوق الوسائد، مستكشفًا الجاذبية ومختبرًا شجاعته. بدلًا من منعه، خصّصي له مساحة آمنة للقفز داخل الغرفة.'),
  ('3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37', 'تقبّلي قلة النوم 😭', 'استيقظ طفلكِ في منتصف الليل ولا يريد النوم. لا تغضبي منه. حاولي معرفة السبب، واربتي عليه برفق لتشعريه بأنكِ إلى جانبه.'),
  ('904ee771-1822-4dbc-a79d-be6697d8f129', 'الصبر وقت نوبة الغضب 🛒', 'يصرخ في المتجر لأنكِ لم تشتري له اللعبة التي يريدها. لا تكترثي لنظرات من يبدون كأنهم آباء مثاليون من حولكِ. حافظي على هدوئكِ، وانظري في عينيه واشرحي له الأمر، ولا تتراجعي عن موقفكِ.'),
  ('c5b71abf-d92a-46da-8996-4282a02052e4', 'الانتقال إلى الشهر 31!  🎉', 'أصبح طفلكِ الآن في أكثر مراحل الطفولة تطورًا من الناحية الفكرية، وأكثرها حافلة بالتحديات في الوقت نفسه. كل جملة يقولها وكل سؤال يطرحه هو اكتشاف كبير بالنسبة إليكِ.'),
  ('0f2d9f90-69e8-4777-adab-24eab59b69a5', 'أزمات وقت الطعام 🥣', 'هل يأكل ملعقتين ثم يقول إنه شبع ويركض بعيدًا؟ لا تجبريه على الأكل. بناء علاقة صحية مع الطعام أهم من إنهاء كل ما في الطبق.'),
  ('1b92930f-874b-4bdc-b9d4-44b2ec744469', 'لقطة توقف الزمن 📸', 'بينما يلعب طفلكِ بلطف في الغرفة، افتحي فورًا ميزة جلسة تصوير الطفل، وخلّدي للمستقبل ملامحه المختلفة التي تبدو أكثر نضجًا وتلك العينين اللامعتين، من دون أي فلتر.'),
  ('cb9d6b16-c52e-4770-b96a-4ab41dd866dc', 'عندما تتعب الأم 🛑', 'أنتِ لستِ من حديد. إذا لم تكن لديكِ اليوم طاقة للطهي، فاسلقي بعض المعكرونة أو اطلبي طعامًا جاهزًا. أن تكوني أمًا مثالية لا يعني أن تفعلي كل شيء بمفردكِ.'),
  ('438805fb-6787-4d0d-b1d5-b2a1a747c30c', 'علامة الإمساك 💩', 'هل يركض كثيرًا لكنه ينسى شرب الماء؟ راقبي برازه عند استخدام النونية. احرصي على إضافة الشوفان الغني بالألياف والبرقوق إلى قائمة طعامه.'),
  ('6e0e2948-0156-4f7e-a4e9-342d621f5670', 'عرض لا ينتهي في السرير 🛌', 'هل يقفز ويركض على السرير بدلًا من النوم؟ شغّلي مؤقت النوم وحافظي على الحدود بحب. حوّلي الغرفة إلى مساحة هادئة للنوم بتشغيل أصوات الغابة من الضوضاء البيضاء.'),
  ('c7ebe08f-c601-4b91-b115-456e094665de', 'درع الكالسيوم 🦴', 'ألا يشرب الحليب؟ الكالسيوم ضروري للعظام. استخدمي أداة متابعة التغذية لحساب ما تناوله اليوم من الجبن أو الزبادي أو البروكلي، وعوّضي أي نقص.'),
  ('54448f6d-1a3b-4d93-a54d-a52f199ed706', 'قلعة الوسائد 🏰', 'حوّلي الغرفة هذا المساء إلى ساحة للعب. ابنيا قلعة صغيرة من وسائد الأريكة وادخلا إليها. ستعمّ بعض الفوضى، لكن هذه الضحكات المرحة تستحق ذلك بالتأكيد.'),
  ('71cd2e71-d81c-477a-9842-72269b236716', 'الإصرار على الأكل بمفرده 🥄', 'هل يمسك الملعقة ويلطّخ كل مكان؟ شغّلي مؤقت التغذية. لا تنظري إلى الطعام المتناثر، بل إلى الاستقلالية والثقة بالنفس اللتين يكتسبهما، وافتخري به.'),
  ('a40edf39-5245-44c1-a544-58bd483fee61', 'نزق الصباح ☁️', 'هل يبكي على كل شيء فور أن يفتح عينيه ولا يرضيه شيء؟ ربما يكون في خضم طفرة نمو. أنقذي يومه بمنحه الكثير من العناق والشعور بالأمان.'),
  ('08e4a521-2f7a-4298-b56b-2d48b11d0ee9', 'مناوبة الأب الليلية 👨‍🍼', 'يكفيكِ ما تشعرين به من إرهاق خلال النهار. أوكلي إلى الأب في المساء مهمة تجهيز طفلكِ للنوم وإلباسه ملابس النوم، واكتفي بالمشاهدة من بعيد.'),
  ('352c5750-18d9-48a8-a40c-2d51006fd988', 'تكرار الكلمات 🗣️', 'هل يكرر فورًا كالببغاء كل كلمة جديدة يسمعها منكِ؟ إن حصيلته اللغوية تتوسع. انتبهي جيدًا إلى الكلمات والمشاعر التي تعبّرين عنها أمامه، فهو يقلّد كل شيء.'),
  ('3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa', 'أخفي الخضراوات 🥦', 'هل رأى مجددًا قطعة الجزر الصغيرة في الحساء ورفض تناوله؟ يُعد هرس الخضراوات وإخفاؤها في أقراص اللحم ضمن خطة التغذية من أقدم حيل الأمهات وأكثرها فائدة.'),
  ('b0e5435a-23a4-401e-a5a2-1b672694e080', 'مفاجآت الطقس ⛅', 'عندما تخرجين للتنزه، لا تنخدعي بالطقس فتعرّضي طفلكِ للبرد. لا تتخذي قراركِ بمجرد النظر من النافذة؛ استخدمي مساعد الطقس والملابس لاختيار الزي الأنسب للأجواء في الخارج قبل مغادرة المنزل.'),
  ('c7c50614-edd2-448c-a9f6-e76579ba2f11', 'عاصفة منتصف الليل 😭', 'هل استيقظ في منتصف الليل باكيًا من دون سبب واضح؟ هل السبب غازات أم مجرد فزع ليلي؟ احتضنيه بهدوء وطمئنيه من دون رفع صوتكِ، ثم ساعديه على العودة إلى النوم.'),
  ('ccc01a90-d6a0-43fa-b96b-7ed5976f5309', 'الخوف من الانفصال 🥺', 'حتى عندما تذهبين إلى الحمّام، ينتظركِ خلف الباب ويبكي. قد يشتد قلق الانفصال أحيانًا. تحدثي إليه في كل مرة وأخبريه أنكِ موجودة وأنكِ ستعودين فورًا.'),
  ('1f77c97d-063c-457e-9c51-eaecc473dae1', 'البحث عن أصدقاء جدد 👫', 'هل يحاول الركض مع الأطفال من عمره في الحديقة والاقتراب منهم؟ لقد بدأت مرحلة التواصل الاجتماعي رسميًا! راقبيه بفخر من بعيد مع الحرص على سلامته خلال محاولاته الأولى.'),
  ('3eccfd90-7490-4750-87b2-6db63c387fc8', 'مصارعة ارتداء البيجاما 👕', 'هل يتحول ارتداء الملابس مساءً إلى معركة كبيرة؟ اتركي له حرية الاختيار: هل تريد البيجاما الحمراء أم الزرقاء؟ ستجعله هذه الحيلة الصغيرة يشعر بأنه صاحب القرار.'),
  ('a9a77950-254b-44a6-a42a-1aaac4de986d', 'ساعة الهدوء ☕', 'إذا لم يأخذ قيلولة نهارية، فحددي على الأقل 1 ساعة للهدوء (quiet time). دعيه يتصفح كتابًا في سريره، بينما تشربين الشاي وتصفّين ذهنكِ.'),
  ('78cdd6a4-a9f3-4cd8-8b42-3de0066371e3', 'السماح الكامل بالاتساخ 🏖️', 'هل يريد طفلكِ اللعب بالطين أو الماء؟ دعيه يتسخ! ستجدين ضمن المنتجات الموصى بها مستلزمات سهلة التنظيف لهذه الأنشطة التي تدعم تطوره الحسي.'),
  ('a54926e2-dcf2-4ae7-b48f-de76a56a8b5a', 'خفّفي الضوضاء 🤫', 'تزداد حساسية طفلكِ للأصوات في لحظات استغراقه في النوم. شغّلي في الغرفة جهازًا يصدر ضوضاء بيضاء (white noise) خفيفة أو موسيقى مستوحاة من الطبيعة لتحييد الأصوات القادمة من النافذة.'),
  ('b1b0d666-c61e-4108-b645-d26f43bbe56c', 'انظري إلى الأسفل، ماذا يكتشف؟ 👣', 'أصبح طفلكِ يستمتع بالمشي حافي القدمين وملامسة السجاد أو الحصى الموجودة في الغرفة. إن تحفيز الأعصاب الموجودة في باطن قدميه مهم جدًا لتوازنه ومهاراته الحركية.'),
  ('07396f85-0dfe-4998-a9ea-d36af8bc97dd', 'عانقيه فحسب 🫂', 'لا حاجة إلى أي لعبة أو كتاب أو حكاية. هذا المساء، ضمّيه إلى صدركِ فحسب، واستنشقي رائحته، واهمسي له في الظلام كم هو غالٍ عليكِ.'),
  ('0c781594-9b76-4258-9f91-7171c6608a1a', 'تبادل الخبرات 💬', 'هل أخافكِ عناد طفلكِ في كل شيء؟ لا تبحثي عن مقالات مخيفة على الإنترنت. استفيدي من التجارب الواقعية للأمهات ذوات الخبرة في مجتمع Anacan.'),
  ('598525b6-1a5f-4877-944f-c79292ee0167', 'ركض هادف 🐢', 'لم يعد طفلكِ يكتفي بالمشي، بل يركض بسرعة ويختبئ منكِ. أزيلي العوائق الخطرة من الغرفة، وانضمّي إليه بحماس كبير في لعبة المطاردة هذه.'),
  ('01e01b8e-03c9-4797-b794-5c6f68c813f6', 'حكاية الأب 📖', 'أريحي أحبالكِ الصوتية هذا المساء. ودعي الأب يتولى مهمة قراءة كتب طفلكِ المفضلة بطريقة مرحة وبنبرات صوت مختلفة.'),
  ('687bbb3b-79db-41d1-81e9-02d82200fd25', 'تبدأ مرحلة «لا» الحازمة 🛑', 'هل يبتعد طفلكِ ويقول «لا» بحزم عندما يحاول أحدهم تقبيله؟ احترمي حدوده الجسدية. فاعتراضه على اللمسات غير المأذون بها ضروري لبناء ثقته بنفسه في المستقبل.'),
  ('34a5aff2-1b83-44f1-acd3-59c942a78f84', 'يمنح الصور معنى 📖', 'عندما يرى الحيوانات أو الأطفال في الكتاب، يلمسهم ويسأل: ماذا يفعل هذا؟ إدراكه البصري مدهش. احكي له قصصًا غنية بالتفاصيل عن الشخصيات.'),
  ('638fb01b-1266-441c-a6a2-ad8bcb0172d8', 'وقت للأم 🥑', 'لا تتناولي غداءكِ واقفة وسط انشغالاتكِ اليومية. اختاري وجبة خفيفة تمنحكِ الطاقة من بين الوصفات الصحية، واجعلي تغذيتكِ أولوية، ولو لعشر دقائق فقط تسترخين فيها على الأريكة.'),
  ('543664cd-6c89-4ffd-ac7b-d08edd1101b7', 'أحاديث هامسة 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واحكي له بصوت خافت جدًا وهمس عما حدث خلال اليوم. فالهمس من أفضل الطرق لتهيئة الدماغ للنوم.'),
  ('93186474-3eab-43ed-a284-f876b4f1b709', 'الحديد والقوة 🥩', 'هل يبدو شاحبًا أو يتعب بسرعة؟ قدّمي له إلى جانب اللحم سلطة بالليمون أو الطماطم لتعزيز امتصاص الفيتامينات.'),
  ('fd977b6d-8463-4d3e-998c-e4dea887a555', 'قوة القوائم 🛒', 'هل تنسين دائمًا شيئًا عند الذهاب إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ ليحضرها زوجكِ بدقة عند عودته من العمل.'),
  ('7c36b46e-089a-4d1a-adf7-c6f69476bd88', 'دوّني مشاعركِ 📝', 'هل تشعرين أن لا أحد يفهمكِ أو يلاحظ إرهاقكِ؟ يوميات الحالة المزاجية خير رفيق لحفظ أسراركِ. دوّني فيها كل ما تشعرين به من توتر وألم ووحدة، وستلاحظين مدى سرعة شعوركِ بالراحة.'),
  ('b5b01983-be53-446e-a05f-8de98770b472', 'إنها لي 🧸', 'هل يرفض طفلكِ إعطاء لعبته لطفل جاء لزيارتكم؟ هذا ليس أنانية، بل حفاظ على حدوده الشخصية. علّميه المشاركة بأن تكوني قدوة له، لا بإجباره عليها.'),
  ('b791e063-932d-483a-b56e-e710cf0815c9', 'اللعب الحر 🧸', 'لستِ مضطرة إلى تسليته في كل دقيقة أو ابتكار ألعاب له باستمرار. فالشعور بالملل هو بداية الإبداع لدى الأطفال. دعيه يكتشف شيئًا ما بمفرده في الغرفة.'),
  ('193d109c-1b4e-4ffc-b28d-b0ef379e189f', 'الوحش المختبئ في الظلام 🌌', 'هل يخاف طفلكِ من الظلال عند إطفاء الأنوار؟ كلما اتسع خياله، بدت مخاوفه أكثر واقعية. شغّلي له صوت الرحم من قسم الضوضاء البيضاء، لتمنحيه ذلك الشعور الفطري بالأمان الذي يحتاج إليه.'),
  ('52e4f8ee-826b-476b-b87c-2f51c60ddd09', 'دموع مفاجئة 😭', 'هل يبكي طفلكِ بلا سبب فور استيقاظه؟ اكتشفي كيف تهدّئين صغيركِ بهدوء عندما تغمره المشاعر، من خلال التحدث إلى خبيرنا Anacan AI ومشاركته ما يشغلكِ.'),
  ('9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14', 'الحاجة إلى الهواء النقي 🌳', 'هل تشعرين بأن جدران المنزل الأربعة تضايقكما؟ قبل أن تنفد طاقتكما، ابحثي عن متنزه قريب في قسم الأماكن الملائمة للأمهات. فالهواء النقي أفضل دواء لكليكما.'),
  ('51ad8bab-02f3-44e2-b4ec-e672c59c18fa', 'دعيني أساعدكِ! 🧹', 'هل يحاول طفلكِ أخذ أدوات التنظيف منكِ عندما تمسحين الأرض أو تزيلين الغبار؟ إنه يشعر بأنه أصبح كبيرًا. أعطيه قطعة قماش صغيرة واسمحي له بالانضمام إلى فريقكِ، فهذا يدعم نموه وتطوره.'),
  ('aa639fbc-fe83-44f4-b9ac-8b3bd199a951', 'لا بد من تفريغ الطاقة 🌳', 'البقاء بين أربعة جدران يجعله أكثر عدوانية. ضعيه في عربته أو أمسكي بيده واخرجا لاستنشاق الهواء النقي. سيؤثر هدوء الطبيعة تأثيرًا رائعًا في طفلكِ وفي حالتكِ النفسية أيضًا.'),
  ('d88a96c2-0998-4bcd-a181-952127acf518', 'التعوّد على الظلام 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية في الغرفة، ولا سيما شاشات الأجهزة اللوحية. لا يُفرَز الميلاتونين إلا في بيئة مظلمة.'),
  ('5d05da29-b0e2-435e-9e14-f523b38e966b', 'تقبّلي السهر 😭', 'استيقظ طفلكِ في منتصف الليل ولا يريد النوم. لا تغضبي منه. حدّدي السبب (ألم، غازات، خوف)، واحتضنيه بصبر حتى يستغرق في النوم من جديد.'),
  ('7d1bf85e-e587-4da1-8ee8-b719514d8f71', 'البقع العنيدة 👗', 'هل أتعبكِ اتساخ الملابس بالبقع باستمرار؟ لا تنزعجي، فطفلكِ يستكشف الأطعمة. استخدمي المرايل المصنوعة من السيليكون، واستمتعي فحسب بهذه اللحظات الملوّنة والفوضوية.'),
  ('f3bd302c-47f2-4428-b12d-4062c2445dfe', 'الرفيق في المرآة 👀', 'خذي طفلكِ أمام المرآة. راقبي كيف ينظر بدهشة إلى انعكاسه ويصنع تعابير وجه مختلفة. إنه نشاط رائع لمساعدته على إدراك ذاته.'),
  ('30560050-23fa-4905-9bfc-f3082838579d', 'الاستعداد للنوم مع الموسيقى 🛀', 'هل أصبح الروتين المسائي صعبًا؟ شغّلي موسيقى هادئة في الخلفية أثناء استحمام طفلكِ بماء دافئ. فتناغم الماء واللحن يهدّئ حتى أكثر الأطفال عنادًا.'),
  ('a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf', 'معركة تنظيف الأسنان 🦷', 'ألا يسمح لكِ بتقريب الفرشاة من فمه؟ حوّلي الأمر إلى لعبة بدلًا من إجباره. دعيه ينظّف أسنانكِ أولًا، ثم يحين دوركِ.'),
  ('c0129df7-df96-4659-882d-c3fd4d3c25e7', 'العناد وقت الطعام 🥣', 'هل يتناول ملعقتين ثم يقول إنه شبع ويهرب؟ لا تجبريه. بناء علاقة صحية مع الطعام أهم من إجباره على الأكل. قدّمي له وجبات أكثر بكميات أقل.'),
  ('2f4c11d8-739d-4bb0-9942-69a623d77f66', 'عاصفة الهرمونات 🩸', 'هل تشعرين برغبة مفاجئة في تناول الحلويات وبالعصبية؟ تحققي من متتبّع الدورة الشهرية. فربما تكون متلازمة ما قبل الدورة الشهرية. لا تلومي نفسكِ، وادعمي جسمكِ بوجبة خفيفة غنية بالمغنيسيوم والتمر من قسم الوصفات الصحية.'),
  ('b69b6089-ef94-4c8e-8537-ca4464897520', 'نوبات الصباح بلا سبب 🛑', 'هل يبدأ بالصراخ والبكاء على كل شيء بمجرد أن يفتح عينيه؟ تحدّثي فورًا مع خبيرنا Anacan AI لتتعلمي كيف تهدّئين طفلكِ بهدوء عندما يكون مثقلًا بالمشاعر.'),
  ('c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4', 'دعيه يكمل نهاية القصة 📖', 'عندما تقرئين له قصة هذا المساء، توقفي قبل إكمال الجمل ودعيه يكملها! اسألي Anacan AI عن أساليب الحوار التي تدعم هذا التطور اللغوي المذهل.'),
  ('0b9c3636-088f-48ec-88e8-94ea05f16477', 'السماح الكامل بالاتساخ 🏖️', 'هل يريد اللعب بالطين أو الماء؟ دعيه يتّسخ! اعثري في قسم المنتجات الموصى بها على أدوات سهلة التنظيف لهذه الأنشطة التي تدعم التطور الحسي.'),
  ('202cf19c-e94a-473d-b9ba-56a3c22509c2', 'دعيني أساعدكِ 🧽', 'هل ينتزع طفلكِ قطعة القماش من يدكِ أثناء إزالة الغبار؟ إنه يريد أن يشعر بأنه كبير. أعطيه قطعة قماش صغيرة مبللة. قد يزيد الفوضى بدلًا من التنظيف، لكنه سيشعر بالفخر.'),
  ('4f32f07a-4c87-40d2-83db-3d4785cda04f', 'صوتيات المنزل 🤫', 'غفا بصعوبة في قيلولة الظهر، والآن قد يدفعكِ حتى أدنى صوت في المنزل إلى الجنون. فعّلي مقياس الصوت فورًا، وأغلقي النوافذ واستمتعي بهذا الهدوء التام.'),
  ('f750ae50-4664-4363-8c07-389c3fa0e9cb', 'معركة ارتداء الحذاء 👟', 'هل ارتدى الحذاء الأيمن في قدمه اليسرى ويرفض خلعه تمامًا؟ دعيه كما هو. فالمظهر أو ارتداء الحذاء بالطريقة الصحيحة ليس أهم الآن من شعوره بالاستقلالية.'),
  ('bcbba6df-cc6d-45d3-b424-d121d2ee2ecb', 'التصالح مع الظلام 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واحكي له بصوت خافت جدًا، أقرب إلى الهمس، ما حدث خلال اليوم. فالهمس من أكثر الطرق الطبيعية لتهيئة الدماغ للنوم.'),
  ('db4f7065-c5e8-4316-a750-ff341f726db5', 'الفنان الصغير 🎨', 'هل يرسم دوائر بالقلم على الحائط أو الورق؟ إنها قفزة كبيرة في تطور مهاراته الحركية الكبرى.'),
  ('eacddbb3-0cac-4a07-a3b8-0e2751f215e2', 'هل يبدأ البحث عن روضة أطفال؟ 🏫', 'هل بدأتِ تفكرين في الروضة مع اقتراب طفلكِ من سن 3 سنوات؟ إذا سئمتِ التفكير بمفردكِ، فانضمي إلى مجتمع Anacan واسألي الأمهات الأخريات عن تجاربهن وتوصياتهن.'),
  ('37d0e7fb-1a1f-4126-b2cd-6303007be080', 'حفلة شاي خيالية ☕', 'هل يناولكِ كوبًا فارغًا ويقول: اشربي الشاي؟ اللعب الرمزي تحفة من تحف النمو. ارتشفي بكل استمتاع ذلك الشاي الخيالي بدرجة حرارة الغرفة.'),
  ('aaf79d19-89d8-4b33-8891-ceb716e86559', 'الملابس مغطاة بالبقع 🎨', 'هل تلطخت ملابس نومه بالطعام وملابسه بالألوان؟ لا ينبغي للأطفال أن يكبروا من دون أن يتسخوا، بل عليهم أن يستكشفوا ويتسخوا. استخدمي المرايل المصنوعة من السيليكون، واتركي الباقي للغسالة.'),
  ('28f1c509-c643-44be-b37c-9bbbdb368b42', 'تحليل الروتين ⏱️', 'هل يستغرق طفلكِ ساعة كاملة ليغفو مساءً؟ راجعي مخطط مؤقت النوم. ربما حان منذ وقت طويل تقصير قيلولته النهارية كثيرًا وتقديم موعد نومه ليلًا.'),
  ('e4b4940d-8946-4ebd-8a09-0e41f12848e2', 'لننظف معًا 🧹', 'هل يحتاج المنزل إلى الترتيب؟ عندما تكنسين الغرفة، دعي طفلكِ يساعدكِ بمسح الأسطح بقطعة قماش. اقرئي في المدونات كيف يمكنكِ تحويل التنظيف معًا إلى لعبة ممتعة.'),
  ('08a08f0f-d89f-412b-a0e0-06835ec16be6', 'صراخ منتصف الليل 🤖', 'هل يستيقظ طفلكِ صارخًا في منتصف الليل ولا يتعرف إليكِ؟ قد يكون هذا رعبًا ليليًا. اسألي Anacan AI فورًا عن الطريقة الصحيحة للتعامل معه ولماذا ينبغي عدم إيقاظه.'),
  ('0b568eaa-4297-4b84-983b-14d42c18fb06', 'أسئلة «لماذا؟» لا تنتهي 🤔', 'يريد طفلكِ فهم العالم والعثور على تفسير منطقي لكل شيء. تعلّمي من Anacan AI كيف تجيبين بصبر عن أسئلته التي لا تنتهي من دون أن تشعري بالملل. صبركِ هو مستقبله.'),
  ('e029b1ab-4432-4819-9a9e-c44e5506a20c', 'من حقكِ شرب قهوتكِ ساخنة ☕', 'الغرفة فوضوية؟ دعيها كما هي. خصصي لنفسكِ 10 دقائق واشربي أخيرًا تلك القهوة وهي ساخنة. لستِ مضطرة إلى أن تكوني مثالية.'),
  ('7d7930a8-9ab0-45ba-bbf4-3a10238d3d72', 'الشوكولاتة التي تأكلينها سرًا 🍫', 'هل ذهبتِ إلى المطبخ وتناولتِ على عجل شيئًا حلوًا بعيدًا عن أنظاره؟ لا تلومي نفسكِ. من حق الأم تمامًا أن ترفع مستوى سكرها قليلًا كي تتحمل صخب اليوم.'),
  ('946cf6ed-b93e-4326-a1b8-4af737be38ff', 'المسرح للأب 🎭', 'لم تعد عبارة «أنهِي طعامك» التي ترددينها تجدي نفعًا. مرري المهمة إلى الأب. فعندما يحوّل الملعقة إلى طائرة محلقة، يختفي العناد بأعجوبة. استريحي واستمتعي بالمشاهدة.'),
  ('c17a59df-f595-4941-acce-8426080226bf', 'أزمة الملعقة ذات اللون الخطأ 🥄', 'هل قامت القيامة لأنكِ قدّمتِ الطعام بالملعقة الصفراء بدلًا من الخضراء؟ خذي نفسًا عميقًا. لا تبحثي عن المنطق في الموقف؛ فطفلكِ يختبر ببساطة قدرته على التحكم في العالم. بدّلي الملعقة وابتسمي.'),
  ('d6cb9a79-b32c-4069-9d3c-ac4297c600b6', 'استراحة لمدة 15 دقيقة 🛀', 'دخلتِ الحمام وأغلقتِ الباب وجلستِ تتصفحين هاتفكِ فحسب؟ نعم، هذه أشهر طريقة لدى الأمهات للهروب قليلًا والاسترخاء. استمتعي بذلك الهدوء دون أن تضطري إلى تبرير الأمر لأحد.'),
  ('0db2d13e-0a0c-45f3-a6f3-c4bf73384a78', 'حزم «لا تقبّلني!» 🛑', 'هل يدير وجهه ويدفع أحد الأقارب عندما يحاول تقبيله؟ لا تتدخلي في حدوده الجسدية! فاعتراضه على اللمسات غير المأذون بها ضروري لمستقبل صحي وآمن.'),
  ('aaaf42f2-3e96-489f-b1d3-e331bf487627', 'حقيقة الفزع الليلي 😭', 'هل استيقظ في منتصف الليل باكيًا وعيناه مغمضتان، ولا يستجيب لأحد؟ هذا هو الفزع الليلي. لا تهزّيه ولا تحاولي إيقاظه. ابقي بجانبه فحسب وامنحيه شعورًا بالأمان.'),
  ('be944652-2efc-45de-a928-8d34a23e4645', 'التخلص من التوتر في الطبيعة ضرورة 🌳', 'هل أصبحت فوضى المنزل اليوم لا تُطاق؟ تحققي فورًا من أداة الطقس والملابس، وتجهّزي بما يناسب، ثم انطلقي إلى أقرب حديقة. فالهواء النقي من أفضل ما يهدّئ طفلكِ.'),
  ('09900d01-e715-436d-95eb-cb7b3165dfb1', 'نسخة جديدة من الكلمات 🗣️', 'هل يقول «ما» بدلًا من «ماء»، و«تبير» بدلًا من «كبير»؟ يبدو ذلك لطيفًا جدًا لدرجة يصعب معها عدم الضحك. لكن كرري له الكلمة الصحيحة بلطف في كل مرة، حتى يرسّخ دماغه نطقها السليم.'),
  ('9853e360-5dcb-4105-84a8-77759e13bdcd', 'دعيه يكتب نهاية الحكاية 🪄', 'هل سئمتما كلاكما من الكتب التقليدية؟ اجعلي طفلكِ هذه المرة يختار نهاية القصة في الحكايات الذكية. أطلقي العنان لخياله بسؤاله: «برأيك، من ساعد ذلك البطل؟»'),
  ('d5f06496-2705-48a5-8325-2f0c28ac0a0f', 'عندما تنفد طاقتكِ 🔋', 'ألا تملكين اليوم طاقة لفعل أي شيء؟ اختاري من الوصفات الصحية سموذي غنيًا بالحديد والفيتامينات، يُحضّر في الخلاط خلال 5 دقائق، واشربيه سريعًا. اعتني بنفسكِ.'),
  ('42bb5c65-e45f-45b5-8da0-322b9acd1ab4', 'قائمة التسوق طوق نجاة 🛒', 'هل ذهبتِ إلى المتجر معتمدة على ذاكرتكِ، ثم عدتِ بعد أن نسيتِ حفاضات طفلكِ؟ هذا يحدث. اعتادي تدوين جميع احتياجاتكِ في قائمة التسوق، ودعي التطبيق يتولى تذكيركِ.'),
  ('f0084bbf-ef12-44c3-80b2-42b0bd99f526', 'أنا متعبة جدًا 🔋', 'الجميع ينتظر منكِ الطاقة، لكن بطاريتكِ نفدت. لا تطبخي شيئًا اليوم، بل اطلبي الطعام. كونكِ أمًا مثالية لا يعني أن عليكِ فعل كل شيء بمفردكِ. اسمحي لنفسكِ بذلك.'),
  ('001946c3-28e7-4dd7-a8dd-6edeeb1c5013', 'من الدوائر إلى الأشكال 🎨', 'هل يرسم دوائر بالقلم على الحائط أو الورق؟ هذه الشقاوة هي في الواقع قفزة كبيرة في تطور مهاراته الحركية.'),
  ('447f446e-b226-43bb-8269-02d7d4965189', 'تناغم الماء 🛀', 'لقد أنهككما الركض طوال اليوم. أثناء الاستحمام بماء فاتر، شغّلي في الخلفية أصواتًا طبيعية هادئة. سيساعد تناغم الماء حتى أكثر الأطفال عنادًا على الاستعداد للنوم.'),
  ('706c71ad-a073-4d24-bc8e-9dc899c5ba4e', 'نوبة غضب في المتجر 🛒', 'هل يصرخ طالبًا الحلوى أمام صندوق الدفع؟ لا تكترثي إطلاقًا لنظرات الآخرين التي توحي بأن طفلكِ سيئ السلوك. تواصلي معه بصريًا بهدوء، واشرحي له القاعدة، واثبتي على موقفكِ.'),
  ('4144a3ff-720b-4a72-a2d5-5866dd12fa04', 'هل يختلّ الروتين؟ ⏱️', 'هل يستغرق النوم مساءً أكثر من 1 ساعة؟ راجعي مخطط مؤقت النوم. ربما حان منذ وقت طويل تقصير القيلولة النهارية كثيرًا وتقديم موعد النوم مساءً.'),
  ('556e8775-c182-4e9f-b2c6-f0cf109ff616', 'تقليد الحيوانات 🐶', 'ألا يكتفي بإصدار الأصوات، بل يحبو مثل الكلب ويتدلل مثل القطة أيضًا؟ هكذا تجتمع لغة الجسد مع الخيال. انضمي إليه على السجادة وشاركيه هذه اللعبة بحماس كبير.'),
  ('b521243e-fc9e-4c87-849b-f17e742b8529', 'أزمة قيلولة الظهيرة 🥱', 'هل يرفض الذهاب إلى السرير ويبكي؟ عند الاقتراب من عمر 3 سنوات، يبدأ بعض الأطفال بالتخلي عن القيلولة. بدلًا من الصراع، أعلني أنها ساعة الهدوء، واقترحي عليه أن يلعب بألعابه بهدوء في السرير.'),
  ('9d29683b-c9aa-4b14-81df-782b8e1da8f5', 'هل يرفض النوم ويخاف من الظلام؟', 'اجعلي الغرفة مظلمة تمامًا، واصنعي بيديكِ ظلالًا على الحائط على هيئة طائر أو كلب. حوّلي الخوف إلى متعة، وساعديه على مصادقة الظلام.'),
  ('346ca24f-e8f9-47c9-9cc2-dc1b86281214', 'قلق الانفصال 🥺', 'يبكي خلفكِ حتى عندما تغادرين الغرفة لثوانٍ فقط. قد يعود قلق الانفصال أحيانًا. طمئنيه من بعيد في كل مرة بصوتكِ، وقولي له إنكِ موجودة: «أنا في المطبخ، سأعود حالًا».'),
  ('afa94b0b-8399-4813-8b1a-8a243185fcf4', 'ضغط السعي إلى الكمال 🛑', 'هل بدأ الأطفال الآخرون بالفعل بتسمية الألوان، بينما لا يرغب طفلكِ في ذلك؟ توقفي فورًا عن المقارنة! فلكل طفل وتيرته الخاصة في النمو. طفلكِ يتقدم وفق وتيرته، وهذا طبيعي تمامًا.'),
  ('d5610b5c-f92a-4668-b551-ccf2ba5bd9e4', 'حيلة الأب السرية 👨‍🍼', 'يكفيكِ ما تشعرين به من تعب خلال النهار. في المساء، اتركي للأب مهمة تجهيز طفلكِ للنوم وتنظيف أسنانه بأسلوبه المرح، واجلسي أنتِ بهدوء جانبًا واحتسي الشاي.'),
  ('47b60c96-b788-4cad-9b79-643917c1b944', 'مخاوف تتعلق بطب الأطفال 🤖', 'هل أثار مخطط طول ووزن طفلكِ البالغ من العمر 32 شهرًا قلقكِ فجأة؟ لا تبحثي في منتديات الإنترنت عن أمراض مخيفة، بل تعرّفي إلى الحقائق الدقيقة والمستندة إلى أسس علمية من Anacan AI.'),
  ('7f82c861-b627-4e20-b2ed-f2fb9f45756b', 'بيئة نوم طبيعية 🤫', 'النصف ساعة الأولى بعد نومه هي الفترة التي يكون فيها الدماغ في أشد حالات الحساسية. شغّلي في الغرفة جهازًا يصدر ضوضاء بيضاء خفيفة، مثل صوت المطر، لحجب الأصوات القادمة من النافذة.'),
  ('9bea836b-e06e-49f0-af98-259fe4009523', 'دعيني أشرح لكِ! ☝️', 'يشير إلى كل شيء بإصبعه ويطرح أسئلة متتالية. إنه يريد منكِ أن تسمّي له ما يراه في العالم من حوله. وهذه قفزة كبيرة في تطور التواصل! حتى إن شعرتِ بالتعب، كرري له أسماء الأشياء بصبر.'),
  ('68ebc7a3-cb63-4696-9089-9b8d5bd20d47', 'عانقيه فحسب 🫂', 'لا حاجة إلى أي لعبة أو كتاب أو حكاية. هذا المساء، ضمّيه إلى صدركِ فحسب، واستنشقي رائحته الجميلة، واهمسي له في الظلام كم هو غالٍ وعزيز.'),
  ('e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513', 'التنظيف معًا 🧹', 'هل يحتاج المنزل إلى الترتيب؟ عندما تكنسين الغرفة، دعيه يساعدكِ بالمسح بقطعة قماش. اقرئي في المدونات كيف يمكنكِ تحويل التنظيف إلى عمل جماعي ممتع.'),
  ('8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54', 'وقت مفاجئ للزوجين 🥂', 'نام طفلكِ مبكرًا على غير المتوقع! لا تضيّعي هذه اللحظة النادرة في تنظيف المنزل. اجلسي وجهًا لوجه مع شريككِ، وأغلقا التلفاز، واسأل كلٌّ منكما الآخر ببساطة كيف كان يومه.'),
  ('92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3', 'هندسة الأحجيات 🧩', 'يُصرّ طفلكِ على إدخال الأشكال في الفتحات المناسبة. حتى إن أخطأ أو شعر بالإحباط، فلا تسارعي إلى مساعدته. فمن خلال هذه المحاولات والأخطاء تحديدًا، يتعلّم مهارة حل المشكلات.'),
  ('2fb64a2b-9948-4425-9837-80add71d4e54', 'مغامرة استكشافية مع الأب في الحديقة 👨‍👧', 'الأمومة ليست مناوبة على مدار الساعة طوال أيام الأسبوع! أوكلي إلى الأب مهمة نزهة اليوم. دعيهما يمرحان معًا ويتّسخان بالطين، بينما تستلقين أنتِ على الأريكة وتستمتعين بالهدوء.'),
  ('9928c8dc-9b21-49a6-b0c4-fd4704041409', 'طفرة في الطول والوزن 📏', 'هل أصبح سرواله قصيرًا مجددًا؟ إن طفلكِ يكبر أمام عينيكِ يومًا بعد يوم! أدخلي قياساته الحالية في متتبع النمو، وانظري بفخر إلى منحنى نموه، ثمرة لياليكِ التي قضيتِها بلا نوم.'),
  ('ed4eff7e-2e68-4d65-af30-186f1086a150', 'سحر الموسيقى الكلاسيكية 🎶', 'هل بدأت نوبة عصبية غير مبررة في المساء؟ أطفئي التلفاز، وخفّفي الإضاءة، وشغّلي موسيقى كلاسيكية خافتة جدًا في الغرفة. سيغيّر الانسجام بين خرير الماء والموسيقى أجواء المكان.'),
  ('331370dc-1940-499c-abdb-15eb6fc3307a', 'عملاء سريون في الحساء 🥦', 'هل أعلن طفلكِ مقاطعة كل ما لونه أخضر؟ لا تقلقي. يُعد هرس الخضراوات وإخفاؤها في أقراص اللحم والصلصات بمساعدة خطة التغذية من أقدم حيل الأمهات وأكثرها فائدة.'),
  ('a9d400f1-6a44-4584-a532-eeed75cc3207', 'أغانٍ مبتكرة 🎤', 'يغنّي طفلكِ لنفسه بكلمات لا تنتمي إلى أي لغة أثناء ترتيب ألعابه. فمفرداته وإحساسه بالإيقاع يتطوران في الوقت نفسه. احرصي على تسجيل هذه المرحلة الموسيقية الجديدة في متتبع النمو.'),
  ('e7308375-84bd-4b4e-9322-163dcd46ff8e', 'معركة ملابس النوم 👕', 'هل أصبح ارتداء الملابس معركة كبيرة؟ اتركي له حرية الاختيار: ملابس النوم الحمراء أم الزرقاء؟ ستمنحه هذه الحيلة الصغيرة شعورًا بأنه صاحب القرار، وتُنهي الصراع.'),
  ('295a4c1e-3bba-40c5-820d-04095aefe60e', 'من سيقوم بالأعمال المنزلية؟ 🌪️', 'هل تراكمت الأعمال؟ دعيها تتراكم. اطلبي من شريككِ أن يتولى الأعمال المنزلية اليوم. استريحي، فأنتِ أهم شخص في هذا المنزل وأكثر من يحتاج إلى استعادة طاقته.'),
  ('546e217e-8060-4a89-877d-29e71165dae1', 'دعم الفريق 🥂', 'لقد تجاوزتما يومًا شاقًا. بعد أن ينام طفلكِ، حضّري كوبًا من الشاي مع شريككِ، وشجّعا بعضكما قائلين: نحن حقًا نؤدي هذه المهمة على أكمل وجه.'),
  ('f23e5345-9d7c-4e2d-871d-a259a849da6f', 'يمنح الصور معنى 📖', 'عندما يرى شخصيات الكتاب، يلمسها ويسأل: ماذا تفعل هذه؟ إدراكه البصري مذهل. ألّفا معًا نهاية جديدة وخيالية تمامًا للكتاب الذي تقرآنه.'),
  ('3edbcdb0-49d0-4dd6-973b-d76b6099a642', 'هوس التنظيف 🌪️', 'نظّفتِ المنزل ورتّبتِه، لكن بعد 10 دقائق عاد كل شيء ليبدو كأنه منطقة انفجار؟ استسلمي للفوضى اليوم. اجلسي على الأريكة ولا تنهضي حتى تنتهي من قهوتكِ.'),
  ('3eea40c1-536e-46c3-bd20-2051d2e3ccae', 'حل الأب الدبلوماسي 👨‍👧', 'هل لم تعد عبارة «أنهِي طعامكِ» تجدي نفعًا؟ مرّري المهمة إلى الأب. فعندما يحوّل الملعقة إلى مركبة فضائية طائرة، يختفي العناد بطريقة سحرية. استريحي واستمتعي بمشاهدة المشهد.'),
  ('ac669cdb-bbf4-4741-8460-56b46118bbec', 'محامي الصباح يباشر عمله 💼', 'لن أرتدي هذا القميص، بل سأرتدي الآخر! لم يعد في الغرفة طفل، بل محامٍ صغير يخوض معكِ نقاشًا احترافيًا. لا تجادليه، بل قدّمي له خيارين فقط لتمنحيه شعورًا بأنه صاحب القرار.'),
  ('8805c85d-beba-4d76-905f-2991bc6002f2', 'انتصار استخدام القصرية 🚽', 'هل يشعر بحاجته إلى قضاء حاجته ويسارع بنفسه إلى القصرية؟ إنه انتصار كبير!'),
  ('9a0661d6-3164-4575-bc05-58b2efdd3f26', 'دعيه يؤلف الحكاية 📖', 'ضعي الكتاب جانبًا هذا المساء. دعيه هو من يروي القصة! اسألي Anacan AI عن أساليب الحوار التي تدعم هذا التطور المذهل في خياله.'),
  ('a452ae82-775c-477d-b99f-ddd24ddd54fa', 'إشارات وقت تناول الطعام 🥣', 'هل يقول إنه شبع بعد تناول ملعقتين ثم يهرب من الكرسي؟ لا تجبريه. إن بناء علاقة صحية مع الطعام أهم بكثير من ضرورة إنهاء ما في الطبق. سيطلب الطعام بنفسه عندما يشعر بالجوع.'),
  ('aa995666-2118-43a4-9171-858348f38b54', 'القصص المصوّرة 📖', 'عندما يرى الحيوانات أو الأطفال في الكتاب، يلمسهم ويسأل: ماذا يفعل هذا؟ إن إدراكه البصري مذهل. ابتكري معه قصصًا عميقة ومضحكة عن الشخصيات.'),
  ('076945c8-0a00-4e34-b0d0-2a0bb6a70d19', 'هل يتغيّر جدول النوم؟ 😭', 'هل يستيقظ في منتصف الليل ولا يرغب في النوم؟ لا تغضبي منه. حاولي معرفة السبب، وداعبيه بلطف لتشعريه بأنكِ بجانبه، ثم انتظري حتى يستسلم للنوم.'),
  ('3d9ffa52-2fa2-4130-82de-58bdbc77e7b6', 'مفاجآت الطقس ⛅', 'عند الخروج في نزهة، لا تدعي مظهر الطقس يخدعكِ فيشعر طفلكِ بالبرد. لا تقرري بمجرد النظر من النافذة؛ استخدمي مساعد الطقس والملابس لاختيار الزي الأنسب للرياح في الخارج، ثم غادري المنزل مطمئنة.'),
  ('50a3f6bc-f0a4-4606-972d-9c8a2cc70695', 'فوائد اللعب الحر 🧸', 'لستِ مضطرة إلى تسليته طوال الوقت أو ابتكار ألعاب له باستمرار. فالملل هو الخطوة الأولى نحو الإبداع لدى الأطفال. دعيه يكتشف شيئًا بمفرده في الغرفة.'),
  ('0e8938b3-51a2-479f-a598-94b98e255136', 'أشياء منسية في قائمة التسوق 🛒', 'هل تنسين دائمًا أهم غرض عند الذهاب إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ، ليتمكن زوجكِ من شرائها بدقة أثناء عودته من العمل.'),
  ('2b8de8fb-82bc-4b54-a795-1fffd716ddd5', 'التواصل بلغة الجسد 🗣️', 'هل يرفع ذراعيه عندما تقولين: هل نذهب؟ أو يهز رأسه بقوة عندما لا يريد شيئًا؟ لقد تطورت قدرته على الفهم بشكل مذهل! أجيبيه بالكثير من العبارات التي تؤكد أنكِ تفهمينه.'),
  ('db645804-58ab-429b-bd1f-cae1d65c9e1e', 'الاستعداد للنوم بالموسيقى 🎶', 'جرّبي تهدئة نوبات الانفعال التي تبدأ بلا سبب في المساء باستخدام موسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة والفعالة المعجزات في المنزل، وتضفي السكينة على الغرفة.'),
  ('f865873b-dd5e-4259-93bf-a8d4ef0dc1b0', 'رفض اللون الأخضر 🥦', 'هل يرمي الخضراوات الورقية من طبقه؟ لا تحوّلي مائدة الطعام إلى ساحة معركة. اكتشفي في قسم الوصفات الصحية وصفات الكب كيك المنزلية بالخضراوات المخفية، ولبّي احتياجكما من الفيتامينات بهدوء.'),
  ('00bb1bab-f1b2-408a-929e-869ffd6367c6', 'سحر الهمس 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واهمسي في أذنه بصوت خافت جدًا بما حدث خلال اليوم. الهمس من أكثر الطرق الطبيعية والهادئة لتهيئة الدماغ للنوم.'),
  ('6948f738-9261-43c8-87d9-90b884505db8', 'محقّق البروكلي 🥦', 'هل يكتشف الخضراوات الخضراء في طبقه ويدفعها جانبًا؟ حان وقت إتقان فن التمويه. اكتشفي في قسم الوصفات الصحية وصفات ذكية تتيح لكِ هرس الخضراوات وإخفاءها داخل أقراص شهية.'),
  ('c7ff87eb-a94f-4bb4-85c6-085ae172efe9', 'الحفل الأول للمؤلف الصغير 🎤', 'هل يغنّي في أثناء ترتيب ألعابه بكلمات لا وجود لها في أي قاموس، لكن بإيقاع مميز؟ لا تقاطعي هذا الانفجار الفكري، وسجّليه في متتبّع النمو بوصفه أول لحن ألّفه.'),
  ('331b6c40-0fb5-4851-9134-928632566339', 'خطة للهروب إلى الطبيعة ⛅', 'لقد جعل البقاء بين أربعة جدران كليكما أكثر توترًا. تحققي من أداة الطقس والملابس، وتجهّزا فورًا وانطلقا إلى الحديقة. فالهواء الطلق يساعد على تهدئة حتى أشد نوبات غضب الأطفال الصغار.'),
  ('56824801-bf77-4597-b1ce-5aa469fe1db9', 'الصمت من ذهب 🤫', 'انتهت فوضى المنزل أخيرًا وغطّ طفلكِ في نوم عميق. افتحي مقياس الصوت، وتحققي من مستوى الهدوء في الغرفة (بالديسيبل)، ثم استمتعي بهذا الصمت الذهبي لمدة 15 دقيقة من دون النظر إلى أي شاشة.'),
  ('7614704a-6622-4005-bcc5-442f422f2e2c', 'موضة طليعية 👗', 'هل وضع سرواله على رأسه ويتجوّل في الغرفة متبخترًا؟ لا تتدخلي. فهذه التجارب المضحكة جزء من سعيه إلى الاستقلال والتعبير عن فرديته. نعم، قد يبدو مظهره غريبًا، لكن هذه اللحظات ممتعة للغاية.'),
  ('45e0f5b4-5219-47b6-9a9e-bcadb9ed774d', 'فقدان الذاكرة في المتجر 🛒', 'هل ذهبتِ إلى المتجر معتمدة على ذاكرتكِ، ثم عدتِ وقد نسيتِ أهم غرض؟ اعتادي تدوين جميع احتياجاتكِ في قائمة التسوق داخل التطبيق، ودعي ذاكرتكِ الرقمية تنقذكِ.'),
  ('8cab638c-2941-4e59-9d14-fa8e3dd46600', 'ضيوف غير مرئيين 👻', 'هل يتحدث طفلكِ وهو ينظر إلى مكان فارغ على الأريكة، بل ويصبّ الشاي لصديقه غير المرئي؟ لقد بلغت مرحلة الأصدقاء الخياليين أوجها! فهو الآن كاتب سيناريو عالمه الخاص. استمتعي بمشاهدة هذا العرض وابتسمي.'),
  ('d368c6ed-7184-4b38-b97e-6f9c7890966b', 'قدرة الماء على محو آثار اليوم 🛀', 'بعد يوم كامل من الركض، أصبحت أعصابكما متوترة. الحمّام الدافئ ليس للنظافة فحسب، بل للاستفادة من قدرة الماء الساحرة على تخفيف التوتر وغسل طاقة اليوم السلبية.'),
  ('37a646c6-efce-4c74-8923-488fc7f72713', 'مناوبة الأب في المطبخ 👨‍🍳', 'الأمومة ليست ماراثونًا تخوضينه وحدكِ. دعي الأب يُعدّ غداء عطلة نهاية الأسبوع ويُطعم طفلكِ، بينما تستلقين أنتِ على الأريكة وتستمتعين باستراحة ثمينة.'),
  ('38899b21-6787-484d-901a-76cdc0b3deb6', 'هل أنا وحدي هكذا؟ 💬', 'هل أنتِ متعبة جدًا وتشعرين بأن لا أحد يفهمكِ؟ اكتبي فورًا في مجتمع Anacan. ستمنحكِ رسائل آلاف الأمهات اللواتي يعانين قلة النوم نفسها ويقلن لكِ «أنا مثلكِ أيضًا» القوة والدعم.'),
  ('c34613c3-022a-46ef-a284-68eea41b09f7', 'دعيه يكتب السيناريو 🪄', 'لقد مللتما كلاكما من الكتب التقليدية. في الحكايات الذكية، دعي طفلكِ هذه المرة يختار نهاية القصة. اسأليه: «برأيك، من ساعد ذلك البطل؟» لتحفّزي خياله قبل النوم.'),
  ('29d7734b-e03c-4396-8939-93b0dfe516dc', 'مخزون الأم الغذائي 🥗', 'فكرتِ في 3 قوائم طعام مختلفة لإشباعه، لكن هل اكتفيتِ أنتِ بتناول لقيمات سريعة وأنتِ واقفة؟ اختاري من الوصفات الصحية سلطة غنية بالفيتامينات يمكن إعدادها في 10 دقائق، وامنحي نفسكِ ما تستحقينه من اهتمام.'),
  ('bdf82e6a-e184-465d-ab37-a709d395d1d4', 'مسرح تعابير وجه الأب 🤡', 'حين لا تعود محاولاتكِ مجدية، تنقذ الأصوات الغريبة التي يصدرها الأب الموقف فورًا. خلال نوبات المساء، مرّري الكرة إليه واستمتعي من بعيد بمتابعة الضحكات المرحة.'),
  ('f6962d3f-b694-40e4-9faf-0cd32b36de3d', 'عاملة النظافة الصغيرة 🧽', 'هل يشدّ المنشفة من يدكِ بينما تمسحين الغبار؟ إنه يريد أن يشعر بأنه كبير وعضو في الفريق. أعطيه قطعة قماش مبللة. قد يزيد الفوضى بدلًا من التنظيف، لكنه سيشعر بالفخر والتقدير.'),
  ('32681963-7779-41a7-9090-772ca76143b7', 'إذن بالفوضى 🌪️', 'هل سئمتِ من جمع الألعاب نفسها في الصندوق كل يوم؟ لا تجمعيها اليوم! فالمنزل ليس متحفًا، بل مكان ينبض بالحياة. لا تركّزي على الفوضى، بل على متعة طفلكِ في الاستكشاف.'),
  ('500b7216-41e0-45a9-a2b9-20687055dfdc', 'حان دور الأب 👨‍🍼', 'يكفيكِ إرهاق النهار. دعي للأب مهمة تحضير طفلكِ للنوم مساءً، وتنظيف أسنانه وإلباسه ملابس النوم، بينما تجلسين أنتِ بهدوء في مكان آخر وتحتسين الشاي.'),
  ('be6a944e-f3ba-401c-9b99-70457d5df68b', 'ماما، انظري إليّ! 👀', 'هل يأتي طفلكِ ويدير وجهكِ نحوه عندما تنظرين إلى الهاتف أو تنشغلين بأمر آخر؟ إنه يريد اهتمامكِ الكامل. أنصتي إليه مع التواصل البصري، وأشعريه بأنكِ تستمعين إليه وأنه مهم.'),
  ('e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c', 'الجمل تتحول إلى حكايات 🗣️', 'هل بدأ يجمع الكلمات ويروي قصصًا طريفة وخيالية؟ إنها طفرة لغوية!'),
  ('13a8c002-9f52-4112-970b-14cac50a9b5c', 'الصوتيات في الغرفة 🤫', 'تزداد حساسيته للأصوات في لحظات استغراقه في النوم. تحققي من مقياس الصوت وشغّلي جهازًا يصدر ضوضاء بيضاء خفيفة (white noise) في الغرفة لحجب الأصوات القادمة من النافذة.'),
  ('4892459c-b0fb-4a8c-89d7-1bb93e680c5b', 'المهندس الصغير 🤔', 'ماذا سيحدث إن رميت هذا؟ ما فائدة هذا الزر؟ إنه يجري تجارب عملية باستمرار. إنه يتعلم! أعيدي فحص سلامة المنزل من مستوى نظر طفلكِ قرب الأرض.'),
  ('dc8c6058-0791-46ab-b5d1-2637ff0b924e', 'لا تثقي بما ترينه من النافذة ⛅', 'عندما تخرجين للتنزه، لا تدعي ما ترينه من النافذة يخدعكِ. استعيني بميزة الطقس واختيار الملابس لتحددي الإطلالة الأنسب للرياح ودرجة الحرارة الفعلية في الخارج، ثم غادري المنزل براحة واطمئنان.'),
  ('7325d8d6-eeac-417b-abca-d32163dd16b4', 'منقذ التسوق 🛒', 'هل تنسين دائمًا أهم غرض عند ذهابكِ إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ، ليشتريها شريككِ بدقة في طريق عودته من العمل.'),
  ('d7e75209-c901-4086-8f01-b71b4374f127', 'العلاج بالماء 🛀', 'لقد أنهككما الركض طوال اليوم. أثناء الاستحمام بماء فاتر، شغّلي أصوات الطبيعة الهادئة في الخلفية. سيساعد تناغم الماء حتى أكثر الأطفال عنادًا على الاستعداد للنوم.'),
  ('f55edde1-4803-4d20-96d6-d40197fda19c', 'لا حازمة! 🛑', 'هل يبتعد طفلكِ ويقول «لا» بحزم عندما يحاول أحد تقبيله؟ احترمي حدود جسده. فاعتراضه على اللمسات غير المأذون بها ضروري لصحته النفسية.'),
  ('a279684f-8916-4183-8bdf-0b058193de01', 'نبرات صوت الأب 📖', 'أريحي أحبالكِ الصوتية هذا المساء. ودعي الأب يتولى مهمة قراءة كتب طفلكِ المفضلة بنبرات صوتية مختلفة وبأسلوب خيالي ومضحك.'),
  ('acb821ae-037d-451e-905f-fae976b254b3', 'ملكية خاصة 🧸', 'هل يرفض طفلكِ إعطاء لعبته لطفل ضيف زار منزلكم؟ هذا ليس أنانية، بل حفاظ على حدوده الشخصية. علّميه المشاركة بأن تكوني قدوة له، لا بإجباره عليها.'),
  ('7794de7c-0d82-4deb-b825-a11099a42226', 'إعلان رفض النوم 🥱', 'لا يريد طفلكِ الذهاب إلى السرير ويقاوم؟ يتوقف بعض الأطفال في هذه المرحلة عن أخذ القيلولة. بدلًا من خوض معركة، أعلني «ساعة الهدوء» واقترحي عليه أن يلعب بهدوء بألعابه في السرير.'),
  ('a2143b10-3a17-415c-a09b-d16e4c9ace11', 'فكّ شفرة الذعر الليلي 😭', 'هل يستيقظ طفلكِ في منتصف الليل باكيًا وعيناه مغمضتان ولا يستجيب لأحد؟ شغّلتِ صوته في أداة تحليل البكاء، وإذا كان ما يحدث ذعرًا ليليًا، فلا تحاولي إيقاظه. ابقي بجانبه فحسب وامنحيه شعورًا بالأمان.'),
  ('df260082-4554-4a41-9637-0bed22c395ae', 'أزمات انتقائية الطعام 🍝', 'هل يرفض اليوم طعامًا كان يحبه بالأمس؟ لا تحوّلي مائدة الطعام إلى ساحة معركة. تحققي من التوازن الأسبوعي باستخدام أداة متابعة التغذية، وابحثي في الوصفات الصحية عن طرق تقديم متنوعة وممتعة.'),
  ('181acf25-f33b-4b1f-a3df-4084c1837a73', 'طبيب الدبدوب المصاب 🩺', 'هل يربّت طفلكِ على لعبته عندما تسقط ويقول لها: «لا تبكي»؟ إنه يطوّر حسًا رائعًا بالتعاطف! سجّلي هذه المرحلة الذهبية من تطور شخصيته فورًا في متتبّع النمو.'),
  ('41b6bff2-f792-4d2c-a887-2fbdd7ee533a', 'دعوة إلى الميلاتونين 🌙', 'أطفئي جميع الأضواء الإضافية والشاشات ذات الضوء الأزرق في الغرفة لمساعدة طفلكِ على النوم بسرعة أكبر. يُفرَز هرمون النوم (الميلاتونين) بسرعة في بيئة مظلمة وخالية من الأجهزة الإلكترونية.'),
  ('afdd5971-fffc-43af-9956-3bc9d2687359', 'دبلوماسية صندوق الرمل 🧸', 'هل يرفض طفلكِ إعطاء دلوه لأي شخص في الحديقة؟ هذه ليست أنانية، بل مجرد اكتشافه لمفهوم الملكية الشخصية. اقترحي نظام تبادل الأدوار من دون إحراجه، وحلّي الأزمة بدبلوماسية.'),
  ('0574f644-1505-478c-8228-ceb707400249', 'التواصل البصري ضروري 🥂', 'نام طفلكِ مبكرًا على نحو غير متوقع! لا تستهلكي هذه اللحظة النادرة في تنظيف المنزل. اجلسي وجهًا لوجه مع شريككِ، وأطفئا التلفاز، وانظرا ببساطة في عيني بعضكما واسألا عن مجريات يومكما.'),
  ('091c7303-14ec-4220-83cd-0ec1c91a3ce2', 'مسجّل صوت حيّ 🎙️', 'هل يكرر طفلكِ فورًا، كالببغاء، حتى أكثر الكلمات عفويةً التي تتفوهين بها؟ إنه مرآتكِ الحية. انتبهي جيدًا إلى الكلمات والمشاعر التي تُظهرينها أمامه، فهو يقلّد كل شيء.'),
  ('e60389be-4932-49bf-9ebd-d4caa963b145', 'واقع القهوة الباردة ☕', 'تحضير القهوة ثم شربها مثلجة بعد 3 ساعات هو أحد قوانين الأمومة غير المكتوبة. افعلي شيئًا مختلفًا اليوم! دعي طفلكِ يلعب وحده بألعابه، واستمتعي بقهوتكِ ساخنة خلال 10 دقائق. أنتِ تستحقين ذلك.'),
  ('28610640-860d-43af-8a5a-381f751b562e', 'عاصفة الأم الخفية 🩸', 'هل تشعرين بتعب مفاجئ ورغبة في البكاء بلا سبب؟ افتحي متتبع الدورة الشهرية. ربما تمرين بمرحلة ما قبل الدورة الشهرية. لا تلومي نفسكِ، بل حضّري وجبة خفيفة غنية بالمغنيسيوم من قسم الوصفات الصحية، وأصغي إلى جسدكِ.'),
  ('51272fb1-4e13-49cf-9f74-cdaa0749b5ed', 'طبيب الأطفال الرقمي 🤖', 'هل أقلقكِ فجأة مخطط طول طفلكِ البالغ 33 شهرًا ووزنه؟ لا تبحثي في منتديات الإنترنت عن أمراض مخيفة، بل تعرّفي إلى الحقائق الدقيقة والفورية والمستندة إلى أسس علمية من Anacan AI.'),
  ('b5429001-8d63-464c-9e9d-56aab19950f8', 'تأثيرات موزارت 🎶', 'هل بدأ طفلكِ يتصرف بعدوانية بلا سبب في المساء؟ أطفئي التلفاز، وخفّفي الإضاءة، وشغّلي موسيقى كلاسيكية هادئة جدًا في الغرفة. سيغيّر تناغم الماء والموسيقى أجواء المكان بطريقة ساحرة.'),
  ('8510671a-e1a9-4df3-abde-5ad11cb9aee4', 'اختبارات الطيران 🧗‍♂️', 'هل يلقي طفلكِ بنفسه من الأريكة فوق الوسائد؟ إنه يختبر الجاذبية وشجاعته. بدلًا من منعه، أنشئي له منطقة آمنة للقفز في الغرفة، ودعيه يفرّغ طاقته.'),
  ('8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0', 'فك شفرة صراخ الليل 😭', 'نوبات البكاء التي تعجزين عن معرفة سببها مرهقة للغاية. توقفي عن التخمين، واستخدمي أداة تحليل البكاء لمحاولة فهم الرسالة الخفية وراء صوته، مثل الألم أو التعب، ثم هدّئيه.'),
  ('a4f7c95b-7fff-41b8-a6d4-80ab1d481977', 'خبير التمويه 🥦', 'هل يبعد طفلكِ الخضراوات الموجودة في الحساء وكأنه يبحث عنها بالمجهر؟ اكتشفي في قسم الوصفات الصحية وصفات لصلصات تجعل الخضراوات غير مرئية. الإبداع هو أعظم سلاح سري لدى الأم.'),
  ('30d43616-cc93-4cce-b2c3-cdd876b6c9e5', 'معركة فرشاة الأسنان 🦷', 'هل يرفض طفلكِ تقريب فرشاة الأسنان من فمه ويريد تنظيف أسنانه بنفسه؟ حوّلي الأمر إلى لعبة بدلًا من إجباره. دعيه ينظف أسنانكِ أولًا، ثم يحين دوركِ.'),
  ('ee52c904-b97d-4a34-b7fb-b60ab86aadcd', 'لوح طاقة للأم 🥑', 'لا تتناولي غداءكِ على عجل وواقفة وسط انشغالاتكِ اليومية. اختاري وجبة خفيفة تمنحكِ الطاقة من بين الوصفات الصحية، وضعي تغذيتكِ في مقدمة أولوياتكِ، ولو بالاستلقاء على الأريكة لمدة 10 دقائق فقط.'),
  ('51decf20-cf70-4c72-beb9-3712b300a999', 'ماراثون المطاردة 🏃‍♂️', 'لم يعد طفلكِ يكتفي بالمشي، بل يركض بسرعة ويختبئ عندما تنادينه. أزيلي العوائق الخطرة من الغرفة، وشاركيه لعبة المطاردة المرحة هذه.'),
  ('aff77c93-ed92-44bc-9afd-e64eb6ce5292', 'اكتشفي علم النفس 📱', 'هل سئمتِ من قول طفلكِ «لا» لكل شيء؟ اقرئي المقالات النفسية في التطبيق لتفهمي الأسباب العميقة وراء عاصفة التطور التي يشهدها دماغه.'),
  ('e18b761a-6fd6-438d-896c-ec7bd458b9c2', 'قوة الظلام 🌙', 'أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة لمساعدة طفلكِ على النوم بسرعة أكبر. يُفرَز الميلاتونين بسرعة فقط في بيئة مظلمة وخالية من الأجهزة الإلكترونية.'),
  ('0953ad75-dec1-4dc2-9d50-5eb074aad008', 'عانقيه فحسب 🫂', 'لا حاجة إلى أي لعبة أو كتاب أو حكاية. هذا المساء، ضمّيه إلى صدركِ فحسب، واستنشقي رائحته الجميلة، واهمسي له في الظلام كم هو غالٍ عليكِ.'),
  ('4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67', 'آلة «ما هذا؟» ☝️', 'هل يشير إلى كل شيء بإصبعه ويسأل عن اسمه؟ إنه يريد منكِ أن تسمّي له الأشياء من حوله. إنها قفزة كبيرة في تطور التواصل! حتى إن شعرتِ بالتعب، كرري أسماء تلك الأشياء بصبر.'),
  ('fb8b7427-667b-4244-909c-df4ca467d79e', 'أنتِ إنسانة 🛑', 'ألم يَسِر أي شيء اليوم وفق الخطة؟ لا تلومي نفسكِ. أنتِ أم حقيقية، ولستِ صورة وهمية منقّحة بفلاتر شبكات التواصل الاجتماعي. طفلكِ يحتاج إليكِ فحسب.'),
  ('5a4437a7-7519-4a4e-9c66-e797d5e763f5', 'المخرج في موقع العمل 🎭', 'هل ينظر طفلكِ إلى شخصيات الكتاب المصوّر ويروي أحداثًا من نسج خياله بالكامل؟ إن خياله في أوج تطوّره! استمعي بفخر إلى قصصه المدهشة من دون مقاطعته.'),
  ('932de885-b10a-4cc0-af8a-8db540c3d060', 'شاي دافئ وهدوء 🍵', 'انسي الأعمال المنزلية، فكل شيء يمكنه الانتظار. حضّري شاي المليسة من وصفاتنا الصحية واستمتعي بقضاء بعض الوقت مع نفسكِ فقط.'),
  ('ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424', 'العلاج في الحديقة 🌳', 'الجدران الأربعة تضيق بكِ. حتى لو كان الطقس باردًا، ألبسي طفلكِ ملابس دافئة واصطحبيه إلى الحديقة لمدة 20 دقيقة. دعيه يستكشف أوراق الشجر والحجارة، فالهواء النقي يمدّ دماغه بالأكسجين.'),
  ('12d65ca5-dc2d-4959-8af5-51ab64abb6bf', 'فنّ في الطبق 🥦', 'هل يرفض طفلكِ تناول الطعام؟ أحيانًا لا تكمن المشكلة في المذاق، بل في الشكل. حاولي فتح شهيته بتشكيل وجوه مرحة من الخضراوات الملوّنة، وحوّلي وقت الطعام إلى لعبة.'),
  ('27428d92-902e-4e8b-a566-975a32a7bf6a', 'قهقهات مرحة 🤡', 'عندما لا تنجح محاولاتكِ، تنقذ أصوات الأب الغريبة الموقف. أثناء نوبات الانفعال المسائية، سلّميه المهمة فورًا وابتسمي وأنتِ تراقبين من بعيد.'),
  ('71ce1c15-b947-45d9-8c0e-c8a77ece4ef7', 'الحياة البرية في المنزل 🐶', 'هل يصدر طفلكِ أصوات الحيوانات، بل ويحبو كالكلب ويتدلّل كالقط؟ إن لغة الجسد والخيال يمتزجان لديه بطريقة مدهشة. انضمي إليه في هذه اللعبة على السجادة.'),
  ('d50eb553-5709-43ce-81ea-ce5014437b1a', 'رسالة فخر 📝', 'في هذا الطريق الطويل المليء بالتقلبات، تكمن قوتكِ الكبرى في حبكِ له. افتحي يوميات المزاج واكتبي له رسالة قصيرة تعبّرين فيها عن فخركِ به، ليقرأها في المستقبل.'),
  ('20a1ef6d-4573-433a-a2b7-db48ed6c1114', 'المساعد الصغير 🧸', 'عندما تطلبين منه إحضار الحذاء، هل يذهب فعلًا ويحضره؟ مفرداته وقدرته على الفهم في أوج تطورهما! عززي ثقته بنفسه بإشراكه في المهام المنزلية البسيطة.'),
  ('9b33bb20-6873-451a-abe7-084cc34eff93', 'أنتما فريق حقيقي 🌟', 'كل خطوة واثقة هي ثمرة جهد مشترك بينكِ وبين شريككِ.'),
  ('9d370453-5ab2-46ed-b11b-b4f3648ebe3e', 'منزل فوضوي وأم سعيدة 🌪', 'هل تراكمت الملابس كالجبال وامتلأت غسالة الصحون؟ دعيها كما هي. اطلبي من شريككِ أن يتولى الأعمال المنزلية اليوم. استريحي، فأنتِ الركيزة الأساسية لهذا المنزل.'),
  ('32252794-61c5-419d-b7e8-539bc9987fc9', 'درس في تشريح الجسم 👀', 'عندما تسألينه: أين كتفاك؟ هل يلمسهما بإصبعه ويشير إليهما؟ قدرته على الاستيعاب الذهني في أوج تطورها! واصلي اللعبة باستخدام أجزاء أكثر تعقيدًا من الجسم لإثراء مفرداته.'),
  ('520e2a70-086b-4229-864f-4de7f51683ae', 'قوة الماء 🛀', 'لقد أرهقكما الركض طوال اليوم. شغّلي أصواتًا طبيعية هادئة في الخلفية أثناء الاستحمام بماء فاتر. سيساعد تناغم الماء حتى أكثر الأطفال عنادًا على الاستعداد للنوم.'),
  ('8083b651-9df8-40f8-a78a-23401da54600', 'الطعام ألذّ في طبق أمي 🥣', 'هل يدفع طبقه جانبًا ويحاول تناول ما تأكلينه؟ يثق الأطفال دائمًا بخيارات والديهم أكثر. اختاري من الوصفات الصحية أطباقًا يمكنكما تناولها معًا.'),
  ('23868e91-8f1b-41db-955e-cd3d4e20a70a', 'خطة ذكية للتنزه ⛅', 'عند الخروج للتنزه، لا تدعي مظهر الطقس يخدعكِ فيشعر طفلكِ بالبرد. لا تتخذي قراركِ بمجرد النظر من النافذة؛ استخدمي مساعد الطقس والملابس لاختيار الإطلالة الأنسب للرياح في الخارج، ثم غادري المنزل وأنتِ مطمئنة.'),
  ('5cf4179d-ca05-4825-ae51-8ae8bda4be3e', 'تدوين يومياتكِ 📝', 'بعد أن ينام طفلكِ، افتحي مفكرة المزاج. ما أكثر ما أتعبكِ اليوم، وما الذي أضحككِ؟ أطلقي العنان لمشاعركِ تمامًا وبوحي بكل ما في داخلكِ.'),
  ('f9781f63-e578-4e40-8665-b3d4fa014824', 'الواقع بعد الاحتفال 🚀', 'بعد احتفال الأمس، استيقظنا هذا الصباح مجددًا على الألعاب المبعثرة وعبارات «لا أريد!» الحياة مستمرة. خذي نفسًا عميقًا، فأنتِ أروع من يدير هذه الفوضى.'),
  ('fde949fd-c8a2-4b0b-a364-0d008da67880', 'أزمة القيلولة 🥱', 'لا يريد الذهاب إلى فراشه ويبكي؟ مع اقتراب سن الثالثة، يبدأ بعض الأطفال في التخلي عن القيلولة. بدلًا من خوض معركة، أعلني «ساعة الهدوء» واقترحي عليه أن يكتفي بتصفّح كتاب في فراشه.'),
  ('092fe7ca-f54f-4986-9a3f-884d05ff6c27', 'خطة الهروب من السرير 🛌', 'هل يحاول التسلق للخروج من سريره؟ أعيدي فحص الغرفة للتأكد من سلامتها. لقد اقترب موعد الانتقال إلى سرير الأطفال الكبار.'),
  ('9fdf76d2-ea34-465e-99e8-537978d670c9', 'بدء أسئلة «كيف؟» 🤔', 'تبدأ أسئلة «كيف يعمل هذا؟» في الحلول محل أسئلة «لماذا؟». إنه يحاول فهم آليات عمل الأشياء. تحلّي بالصبر وقدّمي له تفسيرات قصيرة ومنطقية.'),
  ('c9428152-a130-431b-ac89-26275023d613', 'استراحة للأم ☕', 'عندما يلعب طفلكِ بمفرده، لا تسارعي فورًا إلى أداء الأعمال المنزلية. فوضى الغرفة لن تهرب، لكن طاقتكِ قد تنفد. اجلسي واستمتعي بقهوتكِ الساخنة.'),
  ('b69e774e-9d7b-4da5-9fb4-5b192b81f712', 'سيناريوهات خيالية 🧸', 'هل يروي قصة لدبدوبه، أو يتظاهر بشرب الشاي من كوب فارغ؟ اللعب الرمزي تحفة من تحف النمو. لا تقاطعيه، بل راقبي هذا المخرج الصغير من بعيد.'),
  ('c131d97d-34fe-4f0d-ab19-20860829451c', 'الحاجة إلى الهدوء 🤫', 'النصف ساعة الأول بعد خلوده إلى النوم هو الوقت الأكثر حساسية. استخدمي مقياس الصوت للتحقق من مستوى الديسيبل في المكان، واضبطي صوت التلفاز في الغرفة المجاورة وفقًا لذلك.'),
  ('c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133', 'قدمان حافيتان 👣', 'يستمتع طفلكِ كثيرًا بالمشي حافيًا ولمس الأسطح المختلفة. فتحفيز الأعصاب الموجودة في باطن قدميه لا يُقدّر بثمن لنموه العصبي، لذا اسمحي له بالمشي من دون جوارب.'),
  ('c3c4fb6d-e99b-442f-b18d-4a0a69488a0a', 'ذاكرة رقمية 🛒', 'هل تنسين دائمًا شيئًا ما عند الذهاب إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ، ليشتريها زوجكِ بدقة في طريق عودته من العمل.'),
  ('cb069764-7f58-461b-a159-7d553277ecda', 'خيال ناطق 🪄', 'ابتكري له هذا المساء مغامرة خاصة في الحكايات الذكية: قصة الأرنب الشجاع الذي لا يخاف من المكنسة الكهربائية. من السهل جدًا مساعدته على تجاوز مخاوفه من خلال الحكايات.'),
  ('62149695-6298-4aba-847f-c8ce0b1eb19a', 'الأنا المجروحة 🛑', 'يقول: «سأفعل ذلك بنفسي!» ويرفض كل أشكال المساعدة. حتى إن ارتدى حذاءه بشكل معكوس، فلا تتدخلي. الحفاظ على ثقته بنفسه أهم من ارتداء الحذاء بالشكل الصحيح.'),
  ('86650154-88a4-4c7d-ab75-32f1a232aa9d', 'ضعي حدًا للشكوك 🤖', 'هل أقلقتكِ تغيرات مفاجئة في سلوك طفلكِ؟ لا تبحثي في منتديات الإنترنت عن أمراض مخيفة، بل تعرّفي إلى الحقائق الدقيقة والفورية والمستندة إلى العلم من Anacan AI.'),
  ('d8fdf53e-3f50-42fc-a36a-84c2b2cbfbee', 'حارس النوم 🤫', 'تكون الدماغ في ذروة نشاطها خلال النصف ساعة الأولى بعد نومه. اضبطي أجواء الغرفة باستخدام مقياس الصوت. أحيانًا قد يساعده مجرد صوت المطر الخفيف على الاستغراق في نوم عميق.'),
  ('5820d5b6-2a79-44ac-a012-46235cfe81f4', '5 أيام فقط لإكمال 1000 يوم! 🎈', 'أوشك العد التنازلي على الانتهاء! أنتِ على وشك إكمال رحلة عظيمة واستثنائية امتدت 1000 يوم بالتمام. ابتسمي وابدئي من الآن التحضير لهذه الذكرى المميزة واختيار أفكار مرحة للاحتفال!'),
  ('7ac49f38-01ad-4503-8e74-f0a0bf7621d8', 'ساعة القراءة الهادئة 🥱', 'هل يرفض الذهاب إلى السرير ويقاوم؟ يتوقف بعض الأطفال عن أخذ القيلولة خلال هذه المرحلة. بدلًا من الدخول في صراع، أعلني عن «ساعة الهدوء» واقترحي عليه أن يتصفّح الكتب في سريره فحسب.'),
  ('e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b', 'التواصل في الحديقة 🌳', 'هل يلعب طفلكِ لعبته الخاصة بجوار الأطفال الآخرين بدلًا من اللعب معهم؟ اللعب المتوازي طبيعي تمامًا في هذا العمر. تحققي من الطقس وألبسيه ملابس مناسبة، ثم اصطحبيه إلى الحديقة.'),
  ('88b776b7-0d43-49f1-b31c-da27294feb6f', 'طبيب أطفال سريع 🤖', 'هل تواجهين تراجعًا في تدريب طفلكِ على استخدام الحمّام؟ لا ترهقي نفسكِ، واسألي Anacan AI عن طرق التعامل مع هذه العملية النفسية.'),
  ('92aa3f00-711e-43bd-a2d7-1f3bfbc7744d', 'عناد «إنه لي!» 🛑', 'هل يريد امتلاك كل شيء؟ لم يكتمل لديه مفهوم المشاركة بعد. لا تجبريه، وبدلًا من ذلك طبّقي تدريجيًا قاعدة «لنلعب بالتناوب».'),
  ('adf1cd9b-1322-48c3-a05b-72b8aa90f9cc', 'أجواء ليلية ساحرة 🪄', 'هل يجد صعوبة في الخلود إلى النوم؟ أنشئي حكاية خاصة في «الحكايات الذكية»، وحوّلي العادات الجديدة إلى قصة ممتعة.'),
  ('269b7d14-00d0-4c42-84b9-6759e61b0baa', 'أزمة الطعام الجمالية 🥦', 'هل يرفض أكل حواف الخبز أو شرائح الخيار لأنه يراها قبيحة؟ قد تتخذ انتقائية الطعام أشكالًا غريبة. اكتشفي في خطة التغذية أذكى الطرق لهرس الخضراوات وإخفائها في الطعام.'),
  ('3619cb9e-e29f-4149-9f97-e65685c72f61', 'بدأ الحفل الصباحي 🎤', 'هل يبدأ بالغناء بأعلى صوت فور استيقاظه؟ طاقته مشحونة بالكامل عند الساعة 7 صباحًا. افركي عينيكِ وتابعي عرض نجم البوب الصغير هذا بابتسامة.'),
  ('4e5a485c-972c-4f14-b15e-6d0c1f1b8961', 'فيضان الحمّام 🛀', 'بالنسبة إليه، اللعب بالماء لا يتعلق بالنظافة بقدر ما يتعلق بتحويل الحمّام إلى مدينة ألعاب مائية. دعي الماء يتناثر. فالماء الدافئ والمرح سيغسلان كل ما تراكم لديه من عناد طوال اليوم.'),
  ('22cad895-d987-4916-ac97-672fe0a05ac0', 'فخ «واحدة أخرى» 📖', 'لا يريد الذهاب إلى السرير، ويماطل بطلب حكاية أخرى. ابتعدي عن الكتب التقليدية. أنشئي في «الحكايات الذكية» قصة قصيرة قبل النوم تضم الشخصيات التي ابتكرها، ثم اختتمي روتين النوم.'),
  ('418dbea1-2468-4df0-ad94-f76ab3c14a42', 'مصنع الميلاتونين 🌙', 'لتساعدي طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة. لا يُفرَز الميلاتونين بسرعة إلا في بيئة مظلمة وخالية من الأجهزة الإلكترونية.'),
  ('dcb96656-d377-4147-b075-f440d05b3b54', 'قواعد اللباقة 👋', 'عندما يغادر أحدهم من الباب، يلوّح طفلكِ بيده ويودّعه من تلقاء نفسه! هكذا يتطور ذكاؤه الاجتماعي وتعاطفه. شجّعي هذه التصرفات المهذبة لديه كثيرًا.'),
  ('32e0ad68-9613-493b-b8b0-dc5729e770dd', 'التنظيف معًا 🧹', 'هل حان وقت ترتيب المنزل؟ عندما تكنسين الغرفة، دعيه يساعدكِ بالمسح بقطعة قماش. اقرئي في المدونات كيف تحوّلين التنظيف إلى عمل جماعي ممتع.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('a3a1222f-3b9a-40aa-a53c-50cc656ba7c7'::uuid, 'هل يختل الروتين؟ ⏱️', 'هل يستغرق النوم مساءً وقتًا طويلًا؟ راجعي جدول مؤقت النوم. ربما حان منذ مدة وقت تقليص القيلولة النهارية كثيرًا وتقديم موعد النوم مساءً.'),
  ('ee3cf122-8fc4-43ea-906b-ef2165dd428d', 'عناد «أنا كبير!» 🛑', 'هل يريد التدخل في كل شيء ويتسبب في تأخير المهام؟ امنحيه خيارات بسيطة في معركة الاستقلال الطريفة هذه.'),
  ('98562e83-4876-4c00-8dbc-2ad2897e54b5', 'معجزة 1000 يوم! 👑', 'تهانينا! لقد قطعتِ طوال 1000 يوم بالضبط هذا الطريق العاصف والمرهق، لكنه أثمن رحلة في العالم! احتفلي فورًا بيوم الانتصار المميز هذا وشاركيه بفخر في مجتمع Anacan!'),
  ('c186b66b-55e3-4f3f-9de6-a20601b6d88b', 'رقصة انتصار الفريق 🥂', 'احتفلي هذا المساء مع شريككِ بتعب 1000 يوم ودموعها وأفراحها. ضعي شمعة على المائدة واحتفلي بفرح كبير بانتصار فريقكما الذي لا يُقهر!'),
  ('f26096f7-035d-44ff-ad7c-b1f1eaade001', 'لقد نجحتِ! 📈', 'كم قطع طفلكِ من طريق! لقد حلّت الآن ثقة هائلة محل ذلك الخوف الرقيق الذي رافق الأيام الأولى. لقد اجتزتِ هذه الأيام الـ1000 بفخر كبير! أنتِ رائعة حقًا!'),
  ('3af3aa71-d08b-4f87-af96-9527f5f91ec1', 'تمارين الصباح 🤸‍♂️', 'أنتِ لم تستيقظي بعد، لكنه يقفز فوقكِ في السرير. إنه أكثر منبّه صخبًا في العالم، لكنه أيضًا الألطف! ابدئي يومكِ بالضحك مع طاقته التي لا تنضب.'),
  ('8c84402b-2c57-4668-ad1d-96d138e6ba29', 'ورطة التسوق بلا قائمة 🛒', 'ذهبتِ إلى المتجر وعدتِ من دون شراء أهم غرض؟ هكذا هي ذاكرة الأمومة. لا تعتمدي على ذاكرتكِ، واجعلي تدوين كل احتياج صغير فورًا في قائمة التسوق عادةً لديكِ.'),
  ('90c41ad8-7de7-4c6d-ba3d-cf1aad328939', 'شاي على ضوء الشموع 🕯️', 'نام طفلكِ. أطفئي الأنوار وأشعلي شمعة على الطاولة. ليس الهدف أجواءً رومانسية، بل تهدئة أعصابكِ وعينيكِ المرهقتين بعد يوم حافل.'),
  ('4390f43b-f533-4c56-8aa2-5901fd06c8f5', 'ذكاء اصطناعي، مساعدة حقيقية 🤖', 'ما الدوافع النفسية وراء عناد طفلكِ في كل شيء؟ لا تبحثي في الإنترنت عن مقالات مخيفة. اطلبي من Anacan AI شرحًا علميًا ومختصرًا لأزمات الأطفال في عمر 33 شهرًا.'),
  ('70560836-1d71-42c8-8235-1ad990694b3b', 'اختلال الروتين ⏱️', 'هل يستغرق نوم طفلكِ مساءً أكثر من 1 ساعة؟ راجعي مخطط مؤقت النوم. ربما حان منذ فترة وقت تقصير القيلولة كثيرًا وتقديم موعد النوم المسائي.'),
  ('dfed41fd-982b-4955-b70f-6d43247a4468', 'معركة تمشيط الشعر 🪮', 'هل يصرخ طفلكِ عند تمشيط شعره أو لمسه وكأن ذلك أكبر عذاب في العالم؟ أوقفي المعركة. أعطيه المشط أولًا ودعيه يمشط شعركِ، ثم يأتي دوركِ.'),
  ('5b72c8ce-753e-4283-9bd2-18995d662a91', 'مخزون الحديد 🥩', 'هل يبدو طفلكِ شاحبًا أو فاقدًا للشهية؟ تحققي من تناوله للحديد في أداة متابعة التغذية. وقدّمي له مع اللحم سلطة بالليمون لزيادة امتصاص الحديد فورًا.'),
  ('b0a26358-dcc7-4a57-8694-6e91e9d4baaa', 'درس مشاركة الألعاب 🧸', 'قبل الذهاب إلى الحديقة، تحدثي مع طفلكِ قائلة: «اليوم سنتبادل ألعابنا بالتناوب». نعم، قد لا يشاركها مجددًا، لكن من الضروري أن يسمع هذه القاعدة المجرّدة مرارًا وتكرارًا.'),
  ('c1d1533f-3d3f-4fb5-a549-d74668c72b3d', 'حيلة الأب للنوم 👨‍🍼', 'ألا يريد ارتداء ملابس النوم ليلًا ويهرب منكِ؟ سلّمي المهمة للأب. فعندما يحوّل ارتداءها إلى مصارعة أو لعبة مضحكة، سيجد طفلكِ نفسه مرتديًا ملابس النوم من دون أن ينتبه.'),
  ('3aee856b-a30f-48de-84ad-3c91f83ed092', 'لغز الطبيعة 🍁', 'حوّلي التنزّه في الحديقة إلى لعبة: هيا نبحث عن أكبر ورقة صفراء! فالطبيعة هي أكبر مدرسة تفاعلية لطفلكِ.'),
  ('746f5afe-3705-4073-a3c0-ff69e92f5a25', 'سحر الغسالة 🧺', 'هل جلس أمام الغسالة منبهرًا بالملابس التي تدور داخلها؟ إنها وسيلة ترفيه مجانية تمامًا ومهدئة للذهن. لا تقاطعيه، واغتنمي أنتِ أيضًا الفرصة لتستريحي.'),
  ('8da8a36e-5d67-4dd0-ac14-245b62a8846a', 'فضفضة في مفكرة المزاج 📝', 'أمسكي هاتفكِ. وبدلًا من تصفّح شبكات التواصل الاجتماعي، افتحي مفكرة المزاج واكتبي كل ما أزعجكِ اليوم حتى تفرّغي ما بداخلكِ. فالعلاج الرقمي مفيد فعلًا.'),
  ('71f7d0fb-698f-4308-ad55-a95583a3469b', 'موعد الميلاتونين 🌙', 'كي يبدأ هرمون النوم في أداء دوره، أوقفي جميع مصادر الضوء الأزرق، مثل التلفاز والجهاز اللوحي، قبل النوم بساعة واحدة على الأقل. فالظلام والهدوء أفضل وسيلة للمساعدة على النوم.'),
  ('9d1de334-e45a-491d-8075-45ce379df7ad', 'لعبة «أنا الأم!» 🎭', 'هل يلوّح بإصبعه محذرًا دميته ويوبخها بنبرة صوتكِ؟ هناك نسخة صغيرة منكِ تتجوّل في الغرفة. قد تكون رؤية نفسكِ من الخارج مضحكة، لكنها أيضًا إشارة تدعوكِ إلى الانتباه إلى تصرفاتكِ.'),
  ('fc7921b2-eab6-4a37-aad0-63611df47ad7', 'رفض القيلولة 🥱', 'لا يريد الذهاب إلى السرير رغم أن النعاس يغلبه؟ هذا العناد شائع عند الاقتراب من سن 3 سنوات. لا تجبريه، بل خفّفي الإضاءة في الغرفة وأعلني بدء وقت هادئ لتصفّح الكتب.'),
  ('2a74e43d-d2e3-45ad-8762-627a59c365b2', 'لون العناد الصباحي 🔴', 'طلب الطعام في طبق أخضر، لكن عندما أحضرتِه بدأ يبكي قائلًا: لقد قلتُ الأحمر! توقفي عن البحث عن المنطق. ضعي الطعام في طبق أحمر فحسب، وحافظي على سلامة أعصابكِ.'),
  ('541b84ef-a3ed-43ff-8a33-aa153668c840', 'عاصفة منتصف الليل 😭', 'هل استيقظ طفلكِ في منتصف الليل باكيًا دون سبب واضح؟ هل السبب غازات أم فزع ليلي؟ توقفي عن التخمين، واكتشفي السبب باستخدام تحليل البكاء، ثم هدّئيه باحتضانه برفق.'),
  ('60323c41-a0d6-4029-8b71-994315dcb0cf', 'حوادث التدريب على النونية 🚽', 'هل تبول طفلكِ على السجادة مجددًا أثناء التدريب على استخدام النونية؟ خذي نفسًا عميقًا. فقد يؤدي غضبكِ إلى تراجعه. لا ترهقي نفسكِ نفسيًا بسبب شيء يمكن تنظيفه؛ فهذه مجرد مرحلة من عملية التعلّم.'),
  ('1a8259f8-8cae-4f18-b5c2-ee44aa10346d', 'مفاوض الحديقة 🗣️', 'يطيل الوقت قائلًا: «دعيني ألعب قليلًا بعد، 5 دقائق فقط!». لا يدرك مفهوم الوقت، لكن مهاراته في التفاوض ممتازة. اضبطي مؤقتًا وذكّريه بالقواعد بلطف وفي أجواء مرحة.'),
  ('bf1a9cee-65ab-4eac-ad90-70c1631bbc46', 'طفرة في الطول 📏', 'هل أصبحت سراويل طفلكِ قصيرة؟ إنه ينمو بسرعة! أدخلي قياساته الحالية في متتبّع النمو، وتأمّلي بفخر ثمرة لياليكِ التي قضيتِها بلا نوم.'),
  ('cff0599d-3a80-4d02-94df-22f42e5f09f2', 'استراحة للزوجين 🥂', 'نام طفلكِ. ضعا الآن الهاتفين والأعمال المنزلية جانبًا. تحدثي مع شريككِ لمدة 20 دقيقة على الأقل في أي موضوع مختلف، بعيدًا عن الأطفال والفواتير.'),
  ('5130988b-06fa-4ca0-8477-7c4e5105998f', 'عالم الحكايات السحري 🪄', 'جرّبي هذا المساء شيئًا مختلفًا تمامًا في الحكايات الذكية: قصة الغيمة الصغيرة التي استكشفت السماء. اجعلي نبرة صوتكِ تتناغم مع إيقاع الحكاية، ورافقِي طفلكِ إلى عالم النوم.'),
  ('632fc2f4-f865-49e5-8a30-eef5c63d0d4a', 'صدمة «انظري إليّ!» 👀', 'عندما تنظرين إلى هاتفكِ، يأتي طفلكِ ويضرب يدكِ أو يأخذ الجهاز منكِ. وهو محق تمامًا؛ فهو يريد اهتمامكِ الفوري والكامل. انظري في عينيه وأشعريه بأنكِ تستمعين إليه.'),
  ('df191a16-4b37-4a90-bbd4-c8972ecc1670', 'بقع عنيدة واكتشافات بلا قيود 🎨', 'هل تلطخت ملابس نوم طفلكِ بالطعام وملابسه بالألوان؟ لا ينبغي للأطفال أن يكبروا وهم نظيفون دائمًا؛ فهم يتسخون بينما يستكشفون العالم. الفوضى هي بصمة إبداعه، فلا تقلقي.'),
  ('4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb', 'استراحة الشوكولاتة السرية 🍫', 'أيتها الأم التي تختبئ خلف خزانة المطبخ لتتناول شيئًا حلوًا بسرعة وهي واقفة، نحن نراكِ! لا تلومي نفسكِ. من حقكِ تمامًا الحصول على دفعة الغلوكوز تلك لتتحملي الضجيج.'),
  ('c5c0175d-de40-45a7-97f9-43392b324696', 'ديكتاتور المنزل الصغير 👑', 'لا تجلسي هناك، بل هنا! لن تفعلي هذا أنتِ، بل سأفعله أنا! يريد طفلكِ إدارة المنزل. حافظي على التوازن من دون كسر إرادته بقسوة، وقولي له: اجلس أنت هنا، وسأجلس أنا هناك.'),
  ('2f5f6f47-30c9-4601-933d-5baa445585db', 'جلسة تدليك من الأب 💆‍♂️', 'لقد قضيتِ وقتًا طويلًا واقفة اليوم، ويؤلمكِ ظهركِ من الركض خلف طفلكِ. ما إن ينام، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ عماد المنزل، وحتى الأعمدة تحتاج إلى الراحة.'),
  ('e70841e8-9af5-471e-9ff6-b28774448a7f', 'لا تتدخلي 🧦', 'كعب جوربه في الأعلى، لكنه يتجول كأنه أكثر شخص فخرًا في العالم لأنه ارتداه بنفسه. لا تتدخلي ولو قليلًا. فشعوره بالاستقلالية أهم من ارتداء الجورب بطريقة صحيحة.'),
  ('f3fc49f1-990c-4271-ab6c-21a94434e4c2', 'متنفّسكِ الاجتماعي 💬', 'هل أنتِ منهكة وتشعرين بأنكِ أقل أم صبرًا في العالم؟ افتحي مجتمع Anacan فورًا. فقراءة تجارب أمهات أخريات يمررن بنوبات الانفعال نفسها تمنحكِ دعمًا نفسيًا كبيرًا.'),
  ('3bcabb18-ba8e-4729-bb3a-959b28fdcaeb', 'لغز الغيوم ⛅', 'هل تشعرين بالاختناق بين جدران المنزل؟ تحققي من الطقس، واختاري الملابس المناسبة، ثم اذهبي إلى الحديقة. اجلسا فحسب، وحاولا اكتشاف الأشكال التي تشبهها الغيوم في السماء. هذه اللعبة الهادئة تريح الدماغ وتنمّيه في الوقت نفسه.'),
  ('8fab2e02-e35e-45f0-a10f-554adfe7c2c6', 'انتهت فوضى المنزل أخيرًا.', 'شغّلي موسيقى lofi لحجب الأصوات القادمة من النافذة وإراحة روحكِ.'),
  ('9de02d84-1ac6-4478-a817-67045fcd6af5', 'أولى الأكاذيب اللطيفة؟ 🤥', 'لم أسكب الماء، بل دُبّي هو من سكبه. انتبهي! لقد تطور خيال طفلكِ إلى درجة أنه يستطيع اختلاق الأحداث لمصلحته. لا تتهميه بالكذب، بل ابتسمي وقولي له: أخبر دُبّك ألا يسكبه مرة أخرى.'),
  ('43d613a7-90fe-4d48-880a-a0dadfb94dab', 'عملية إخفاء الخضراوات 🥦', 'هل يضع الخضراوات الموجودة في الحساء جانبًا وكأنه يبحث عنها بالمجهر؟ ابحثي في قسم الوصفات الصحية عن وصفات لصلصات تُخفي الخضراوات. فالإبداع هو أقوى سلاح لدى الأم.'),
  ('6fd78011-ad7d-48f0-9941-25d07912808e', 'انظري إلى الأسفل، ماذا يكتشف؟ 👣', 'يستمتع طفلكِ كثيرًا بالمشي حافي القدمين ولمس الأسطح المختلفة. وتحفيز الأعصاب الموجودة في باطن قدميه مهم لتوازنه، لذا اسمحي له بالمشي من دون جوارب.'),
  ('dcc98b1b-6e09-41d3-9be6-78333aecdab4', 'حرّاس الليل 🧸', 'هل يخاف طفلكِ من الظلام؟ رتّبي دماه المحشوة وألعابه المفضلة حول سريره، وقولي له: «ستحميك حتى الصباح». فهذا الشعور البصري بالأمان فعّال للغاية.'),
  ('3d8d4230-c58c-4f55-bb5e-c5c92f713201', 'تأكيد الهدوء 🤫', 'بعد يوم صاخب، عندما ينام طفلكِ، قيسي مستوى الهدوء في الغرفة باستخدام جهاز قياس الصوت. فمجرد رؤية الأرقام تقترب من الصفر يمنح عقل الأم تأثيرًا أشبه بالعلاج.'),
  ('53046b7a-695e-4d17-9dda-231255060141', '«لا!» الصباحية 🛑', 'هل يقول «لا!» عندما تعرضين عليه شيئًا قبل أن يفتح عينيه حتى؟ مع اقترابه من سن الثالثة، لا تطرحي عليه سؤالًا، بل بادري بالفعل مباشرةً. لا تقولي: «هيا نغسل وجهنا وأيدينا»، بل قولي: «حان وقت غسل الوجه واليدين!».'),
  ('e5f27372-8ce2-40d6-acbc-12281fab28bb', 'خصّصي وقتًا لنفسكِ أيضًا 🥑', 'لقد أرهقكِ الانشغال والركض طوال اليوم. وبدلًا من تناول لقيمات سريعة وأنتِ واقفة، حضّري من قسم الوصفات الصحية طبقًا مميزًا ومشبعًا وغنيًا بالفيتامينات، وتناوليه باستمتاع. فأنتِ بالتأكيد بحاجة إلى الطاقة.'),
  ('096e15b3-74ca-4180-ab20-07ce9b214b2a', 'حديث هامس 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانب طفلكِ واحكي له بصوت خافت جدًا وهمس عمّا حدث خلال اليوم. فالهمس من أفضل الوسائل لتهيئة الدماغ للنوم.'),
  ('41df7f7d-e272-4737-8498-6c866ab9545a', 'تبادل الخبرات 💬', 'هل أخافكِ عناد طفلكِ في كل شيء؟ لا تبحثي عن مقالات مخيفة على الإنترنت. استفيدي من التجارب الواقعية للأمهات الخبيرات في مجتمع Anacan وابتسمي.'),
  ('8ac94a1b-a693-498b-9e54-d59e3331d567', 'راقص محترف 🎶', 'يبدأ بالرقص مع أول إيقاع يسمعه، سواء كان صوت إعلان أو بوق سيارة. انظري إلى الحياة بمرح مثله! انضمّي إليه في الغرفة وارقصا بجنون لبضع دقائق.'),
  ('540ed6cc-ab45-42f3-bbdf-f7d1a37e6094', 'حيلة الأب السرية 👨‍🍼', 'يكفيكِ إرهاق النهار. في المساء، اتركي للأب مهمة تهيئة طفلكِ للنوم وتنظيف أسنانه بأسلوبه المرح، واستريحي أنتِ بهدوء بعيدًا عنهما.'),
  ('75bb1e03-07ff-448a-b132-6eec4abf1a2d', 'ملابس تُطوى ثم تتبعثر 👗', 'تطوين الملابس بجهد كبير، ثم يأتي هو ويبعثرها كلها في لحظة. بدلًا من الانزعاج، حوّلي المهمة إلى لعبة: لنرَ من يستطيع رمي هذا القميص إلى مسافة أبعد؟'),
  ('ca77a3ff-10f8-4690-8926-270fe161b3d5', 'الإصرار على تناول الطعام بمفرده 🥄', 'هل يمسك الملعقة ويلطّخ كل شيء؟ شغّلي مؤقت الوجبة. لا تنظري إلى الطعام المتناثر، بل افرحي بالاستقلالية التي يكتسبها.'),
  ('25c4de30-89c3-4f45-952f-3b21fb85b41e', 'مستكشف حافي القدمين 👣', 'لا يريد ارتداء الجوارب ويركض ليختبئ؟ دعيه يشعر قليلًا بقدميه العاريتين بالأرض والسجادة والبلاط البارد. فتطوّر النهايات العصبية في باطن القدمين مهم للغاية لتوازنه.'),
  ('a0e0a012-48a8-4169-b4f6-62857311b266', 'أطفئي الأنوار ليأتي النوم 🌙', 'لتساعديه على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية في الغرفة وشاشات الأجهزة اللوحية. لا يُفرَز الميلاتونين إلا في بيئة مظلمة وخالية من الأجهزة التكنولوجية.'),
  ('ac0003df-1b37-4e86-98c2-561682149d03', 'رحلة بحث في الطبيعة 🍁', 'استعدّي وفقًا للطقس وارتدي ملابس مناسبة، ثم اخرجي. العبِي معه في الحديقة لعبة البحث عن أحجار مختلفة وأوراق ملوّنة. فالطبيعة في هذا العمر هي أكبر لعبة تفاعلية يمكنه الاستمتاع بها.'),
  ('85540a77-8c0c-40d1-bec5-6ddc93f07354', 'النسيان في المتجر 🛒', 'هل ذهبتِ إلى المتجر معتمدةً على ذاكرتكِ، ثم عدتِ وقد نسيتِ أهم شيء؟ اعتادي تدوين جميع احتياجاتكِ فورًا في قائمة التسوق، ودعي التطبيق يتولى تذكيركِ بها.'),
  ('181a440f-5684-4f29-a861-16adef184628', 'الوقت يطير!', 'انظري إلى الوراء ولاحظي كم تعلمتِ. لقد أصبح هذا المحامي الصغير قادرًا على التفاوض معكِ في كل شيء. افتخري به وبنفسكِ.'),
  ('31d8e844-a068-4aa5-8b2c-23a9d11616c4', 'بطل الحكاية 🪄', 'لقد مللتِ أنتِ وطفلكِ من الكتب الكلاسيكية. في الحكايات الذكية، اجعليه رائد فضاء يحلّق بين النجوم أو يغوص في أعماق البحار. أطلقا العنان للخيال قبل النوم.'),
  ('4280853d-50c1-4092-8d31-3279f5e3d68a', 'ساعة الهدوء ضرورية ☕', 'إذا كان يرفض القيلولة تمامًا، فلا تجبريه. لكن خصّصي 30 دقيقة لوقت الهدوء (quiet time). دعيه يبقى وحده في سريره مع بعض الكتب، وخذي أنتِ أيضًا استراحة في الغرفة.'),
  ('10fd3d36-ea93-4f52-8bc2-486b88206869', 'مذكّرات المزاج 📝', 'أمسكي هاتفكِ. وبدلًا من تصفّح وسائل التواصل الاجتماعي، افتحي مذكّرات المزاج ودوّني للمستقبل أطرف ما فعله اليوم، واللحظة التي أضحكتكِ أكثر من غيرها.'),
  ('502d3376-0322-4c07-aee1-71c209315c6b', 'مهمة الخضراوات المخفية 🥦', 'هل ينتقي الخضراوات من الحساء ويرميها؟ لا تدخلي معه في صراع. اكتشفي في خطة التغذية أساليب مبتكرة وذكية لهرس الخضراوات وإخفائها في الصلصات.'),
  ('ad687f75-6bde-4ad1-8992-78906bd61fd5', 'إصرار «ماما، انظري إليّ!» 👀', 'هل يأتي ويضرب يدكِ عندما تنظرين إلى هاتفكِ أو تنشغلين بعمل ما؟ إنه محق تمامًا؛ فهو يريد اهتمامكِ الكامل. ستساعده 5 دقائق من الوقت النوعي مع التواصل البصري على الهدوء.'),
  ('22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea', 'لعبة الهروب من الغرفة 🏃‍♂️', 'عندما تحاولين إلباسه ملابس النوم أو القميص، يهرب من الغرفة ضاحكًا. لا تعالجي الأمر بالغضب، بل حوّليه إلى لعبة. سيكون إلباسه أسهل إذا لعبتما لعبة المطاردة والإمساك.'),
  ('322a385d-8940-4d2a-9d21-4777e2660139', 'تنبيه الطقس ⛅', 'عندما تخرجين للتنزّه، لا تنخدعي بما ترينه من النافذة. استعيني بمساعد الطقس والملابس لاختيار الإطلالة الأنسب للرياح ودرجة الحرارة الفعلية في الخارج قبل مغادرة المنزل.'),
  ('bd0902bb-9be1-40b5-8e41-73f85b835f0e', 'مساعد الصباح 🧑‍🍳', 'يريد مساعدتكِ في تحضير الفطور. سيسكب الدقيق، ويريق الماء، وتعمّ الفوضى المطبخ... لكنه ينمو ويتطور من خلال هذه التجارب التي تنمّي مهاراته الحركية الدقيقة. تحلّي بالصبر.'),
  ('c929f83e-5e59-4728-8c79-df0502607758', 'عرض الأب الساحر 🤡', 'عندما لا تعود حيلكِ مجدية، تنقذ الأصوات الغريبة التي يصدرها الأب الموقف فورًا. أثناء نوبات المساء، دعيه يتولى الأمر واستمتعي من بعيد بالضحكات المرحة.'),
  ('61f1a424-1da9-48ab-b336-92c9137ef39e', 'العلاج بالحمّام الدافئ 🛀', 'لقد أنهككما الركض طوال اليوم. شغّلي أصواتًا طبيعية هادئة في الخلفية أثناء استحمامه بماء فاتر. سيساعد تناغم الماء حتى أكثر الأطفال عنادًا على الاستعداد للنوم.'),
  ('8ae2c146-2d4a-4919-80fe-7f15c41cdc0e', 'يريد أن يسكب بنفسه 💧', 'يصرّ على سكب الماء في الكوب بنفسه. جهّزي مناشف التنظيف ولا تحبطي استقلاليته. سيريق الماء، لكنكِ بعد بضع محاولات ستندهشين من مدى حرصه أثناء ملء الكوب.'),
  ('c8458955-5810-4609-a23d-82b155bf6112', 'الشعور بالإنهاك 🔋', 'هل تشعرين بأنكِ لستِ جيدة بما يكفي؟ هل تظنين أنكِ عاجزة عن تدبّر كل شيء؟ اطلعي على منشورات المجتمع؛ لستِ وحدكِ ولستِ مقصّرة. أنتِ عالم هذا الطفل بأكمله.'),
  ('87267db7-ab44-41b2-82ed-1d12fea90f71', 'قواعد لغوية غريبة 🗣️', 'يبتكر قواعد لغوية جديدة وخاصة به تمامًا، فيقول مثلًا: «أنا جاع» أو «هو كان يذهب جاء». لا تصححي له بصرامة، بل أجيبيه بتكرار الجملة بصيغتها الصحيحة فحسب.'),
  ('9a6f7d87-06ae-42b3-a4d0-b7eff2923976', 'نصيحة Anacan AI 🤖', 'هل لديكِ سؤال حول تفاعل طفلكِ اجتماعيًا مع الأطفال الآخرين في الحديقة؟ لا تضيّعي ساعات في البحث عبر الإنترنت؛ اسألي Anacan AI واحصلي فورًا على نصيحة مناسبة لمرحلة نموه ومعتمدة من أطباء الأطفال.'),
  ('a3b7ecf2-9668-46df-b331-9c7487819a32', 'تنبيه بشأن الذعر الليلي 😭', 'إذا بدأ بالبكاء فجأة أو صرخ وعيناه مغمضتان، فتحققي من الأمر باستخدام تحليل البكاء. إذا كان يعاني من الذعر الليلي، فلا تحاولي إيقاظه؛ ابقي بجانبه وطمئنيه بهدوء.'),
  ('b7283d95-1357-4ff9-9423-db4159e19c31', 'انتصار الفريق 🥂', 'لقد اجتزتما يومًا صعبًا آخر. اجلسي مع شريككِ وجهًا لوجه وارفعا كوبَي الشاي احتفالًا: نحن حقًا فريق أسطوري ونؤدي هذه المهمة ببراعة!'),
  ('c932a08e-a484-4595-8fa6-e57165ffaf96', 'مشكلة المشاركة 🧸', 'هل يرفض إعطاء لعبته لأي شخص؟ هذه ليست أنانية، بل مرحلة من مراحل النمو. تعرّفي من Anacan AI، مع اقترابه من سن 3 سنوات، إلى مفهوم اللعب بالتناوب بدلًا من المشاركة.'),
  ('23137ca6-6246-4dc7-b692-cdcd36eeac0f', 'الدراجة ثلاثية العجلات 🚴‍♂️', 'هل يحاول الضغط على الدواسات وقيادة الدراجة؟ لقد دخلت عضلات ساقيه وقدرته على التنسيق مرحلة جديدة! شجّعيه على ذلك في أماكن آمنة.'),
  ('b44d4b2a-f3eb-4e26-aa50-0105efb5648c', 'فيتامين للأم 🥑', 'أنتِ تفعلين كل ما بوسعكِ لإشباعه. ولكن ماذا عنكِ؟ اختاري من قسم الوصفات الصحية وجبة غداء خفيفة غنية بالحديد والكالسيوم.'),
  ('f62c402c-4ba9-489a-b6de-dde4e1aa3aae', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي الاستيقاظ ليلًا وحدكِ بالكامل. أيقظي شريككِ أيضًا؛ فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('10872122-03c1-4660-aabc-490c724034c9', 'جيوب مليئة بالكنوز 🍁', 'هل عدتما من الحديقة ووجدتِ في جيبه 3 أحجار وورقة شجر جافة وغصينًا؟ إنها كنوز ثمينة بالنسبة إليه. ما عليكِ سوى محاولة التخلص منها بأمان قبل أن ينثرها في المنزل.'),
  ('8f84e032-e8dd-4d1f-b3c6-5d57937006dd', 'لا تبحثي عن المنطق 👑', 'هل يطلب المثلجات أو حساء العدس المتبقي من الأمس على الإفطار؟ هناك ديكتاتور جديد في المنزل. شتّتي انتباهه فورًا بمنحه حق الاختيار (مثلًا: هل تريد تفاحة أم موزة؟).'),
  ('907a5bc5-4a7e-48ec-977c-d9c5440faba0', 'أعذار الهروب من السرير 🏃‍♂️', 'يريد الماء، ويريد الذهاب إلى المرحاض، ويريد تقبيل ستارة الغرفة... يبتكر عقله أعذارًا جديدة لتجنب النوم. ضعي حدودًا: كوب ماء واحد فقط، وانتهى الأمر. كوني حازمة.'),
  ('9c87f5af-e2e2-4310-ab2c-98ff6d5521d4', 'الانتقال إلى الوضع الصامت 🤫', 'تزداد حساسية طفلكِ أثناء استغراقه في النوم. حافظي على الهدوء.'),
  ('af1711a8-2ca3-45c1-ae35-556b3b0e2d67', 'ثنائي النوم مع الأب 📖', 'لنصنع هذا المساء أجواءً مختلفة في الغرفة. بدلًا من قراءة كتاب، ساعدي طفلكِ على النوم من خلال غناء أغنية هادئة وإيقاعية مع والده.'),
  ('b2328024-7846-4b25-a276-980c22ebcd52', 'ماما، تغذّي جيدًا 🥑', 'وسط انشغالاتكِ اليومية، لا تتناولي الغداء على عجل وأنتِ واقفة. اجلسي وحضّري سلطة مختلفة غنية بالحديد والكالسيوم، ثم تناوليها واستمتعي بمذاقها. طاقتكِ هي محرّك هذا المنزل.'),
  ('e037ab2c-d2a8-49ed-a1df-aac78a584118', 'خطوات نحو الصداقة 👫', 'هل شارك طفلكِ لعبته مع طفل آخر في الحديقة للمرة الأولى ومن تلقاء نفسه؟ هذا تطور كبير! فالتمحور حول الذات يتراجع، والتعاطف يتشكل. صفّقي له بفرح كبير.'),
  ('1f9d373c-817c-4a86-9cb9-a9b3d9fac797', '10 دقائق على ضوء الشموع 🕯️', 'نام طفلكِ وانتهت فوضى المنزل. أطفئي الأنوار، وتأملي الظلام أو ضوء شمعة فقط، وصفّي ذهنكِ وأفكاركِ تمامًا لمدة 10 دقائق.'),
  ('7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8', 'المواساة في المجتمع 💬', 'هل تخنقكِ فكرة أنكِ لن تعودي أبدًا إلى سابق عهدكِ؟ شاركي هذا الشعور العابر، رغم ثقله الشديد، مع الأمهات في مجتمع Anacan واحصلي على دعمهن.'),
  ('d270bdfa-5a84-42b7-8b44-3231febd32b3', 'ضفائر عنيدة 🪮', 'هل يرفض طفلكِ تمامًا أن تجمعي شعره أو تمشّطيه؟ توقفي عن المقاومة. قفي أمام المرآة، ومشّطي شعركِ أولًا بالطريقة التي يريدها، ثم أعطيه دوره.'),
  ('b155d377-4b41-487e-b8ee-74a365226635', 'معركة القيلولة 🥱', 'إذا رفض طفلكِ القيلولة، فلا تجبريه. بدلًا من محاولة تنويمه مرارًا وإرهاق أعصابكِ، خصّصي له وقتًا هادئًا في الغرفة ليلعب بألعابه.'),
  ('4ab501ea-956f-4adc-a27e-2e2bc99f59c6', 'وشوم على الجسم 🖍️', 'قد تكون بضع ثوانٍ من الصمت خطرة أحيانًا. دخلتِ الغرفة فوجدتِ طفلكِ يرسم وشومًا على ذراعيه بأقلام التلوين؟ خذي نفسًا عميقًا. فمهاراته الحركية الدقيقة تتطور، والحبر سيُغسل عن بشرته على أي حال.'),
  ('93712bd1-e114-4739-841f-9d8901785feb', 'الأب شريككِ 👨‍👧', 'هل نفدت طاقتكِ تمامًا بحلول المساء؟ قولي: «سأنسحب من هذا المشهد»، وسلّمي الطفل إلى والده. فترتيب الغرفة التي بعثراها معًا أسهل من التعامل مع الطفل بمفردكِ.'),
  ('9a4e49fa-28ce-4422-86d1-9b77699fd24c', 'الحاجة إلى الألياف 💩', 'يركض كثيرًا، لكنه ينسى شرب الماء. راقبي برازه في النونية. إذا كان هناك خطر إصابته بالإمساك، فأضيفي الشوفان والبرقوق إلى قائمة طعامه.'),
  ('2743b373-11c6-4a72-a371-988483c30fb4', 'الخوف من الظل 👻', 'هل بدأ فجأة بالبكاء في الشارع أو الغرفة؟ قد يكون السبب أن ظله يلاحقه! مع اقترابه من عمر 3 سنوات، يصبح خياله أكثر غرابة. احتضنيه وعرّفيه إلى ظله بابتسامة.'),
  ('344cf14d-0511-4f06-86bb-38e1e79297c3', 'جرّاح الطعام 🥦', 'لا يأكل الطعام، بل يكتفي بفصل حبات الأرز الصغيرة أو الأعشاب الخضراء منه بدقة جرّاح. ضمّي ذلك إلى خطة التغذية، واكتشفي طرقًا لتقديم الخضراوات مهروسة.'),
  ('85bf1b2b-8bd2-41a8-8e81-bd414469ff03', 'توديع كل شيء 🧸', 'قبل النوم، يريد أن يقول «تصبح على خير» لكل شيء في الغرفة، حتى السيارة والكرسي ومقبض الباب. هذا أحد طقوس الانتقال إلى النوم الجديدة التي اكتسبها، فلا تستعجليه.'),
  ('4699f7a7-a05a-4fb5-bcc3-1031cc990173', 'مكالمات عمل خيالية 🍌', 'هل يمسك موزة أو جهاز التحكم ويتحدث عبرها بجدية وكأنه يجري مكالمة هاتفية بلغة مختلقة؟ إنه يقلّد لغة جسدكِ بالكامل. صوّريه بالفيديو واحتفظي بالمقطع للمستقبل، فستضحكين كثيرًا.'),
  ('77b18a3d-16c2-454b-9fe4-daea00f5a342', 'هل يختلّ الروتين؟ ⏱️', 'هل يستغرق نومه مساءً أكثر من 1 ساعة؟ راجعي مخطط مؤقت النوم. ربما حان الوقت لإلغاء القيلولة النهارية تمامًا وتقديم موعد النوم مساءً.'),
  ('9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469', 'معركة فرشاة الأسنان 🪥', 'هل يطبق طفلكِ فمه بمجرد رؤية فرشاة الأسنان؟ لا تحوّلي النظافة إلى معركة. تصفّحي الفُرش الموسيقية في قسم المنتجات الموصى بها، وحوّلي هذا الروتين المزعج إلى لعبة ممتعة.'),
  ('3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a', 'عناد «ساقاي لا تعملان» 🛑', 'هل يجلس طفلكِ فجأة على الأرض أثناء العودة من الحديقة، ويقول إن ساقيه لا تعملان ويطلب منكِ حمله؟ هذا ليس تعبًا، بل محاولة للتأثير عليكِ. حوّلي الموقف إلى لعبة وقولي له: «لنرَ إن كنت تستطيع القفز كالأرنب حتى نصل إلى المنزل!»'),
  ('b948ea64-f471-4d36-958a-85e04a0250f1', 'الغميضة وقت استخدام النونية 🚽', 'هل يختبئ طفلكِ خلف الستارة أو بجانب الأريكة عندما يحتاج إلى قضاء حاجته؟ حان الوقت للانتقال إلى قسم المدونات وقراءة الخطوات العلمية لبدء التدريب على استخدام النونية.'),
  ('b9e8fff7-f7f2-410b-a103-f4cd6c6231f8', 'تنفيس الغضب في اليوميات 📝', 'هل قال لكِ أحدهم: «أنتِ في المنزل، فممَّ تتعبين؟» افتحي فورًا يوميات المزاج، وأفرغي كل غضبكِ على الشاشة بأناملكِ. كتابة مشاعركِ الحقيقية أفضل من التظاهر بالابتسام.'),
  ('0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc', 'عرض الحكايات مع الأب 📖', 'هذا المساء، لن يكون صوتكِ هو الذي يملأ الغرفة، بل صوت الأب. دعيه يقرأ الحكاية ويضفي عليها طابعًا مضحكًا بتغيير نبرة أصوات الشخصيات بين الغليظة والرفيعة. أما أنتِ، فاسترخي جانبًا واستمتعي بسماع الضحكات.'),
  ('2fc731d4-47df-4b97-8f67-c7df6aabac96', 'شوكولاتة الأم السرية 🍫', 'أيتها الأم التي تضع قطعة شوكولاتة في فمها وتمضغها بسرعة ما إن يدير طفلها ظهره، هذا الجلوكوز من أبسط حقوقكِ. فأنتِ بحاجة إلى شحن طاقتكِ كي تتمكّني من مجاراة كل تلك الحيوية طوال اليوم.'),
  ('edb08c0a-b151-4f7a-9713-c903f3f5c584', 'أفضل صديق غريب 🥄', 'رغم كل تلك الألعاب الباهظة، هل ذهب طفلكِ إلى المطبخ واختار ملعقة سيليكون مسطّحة، ثم صار يحملها طوال اليوم ويضعها في الفراش؟ عقل الطفل مدهش حقًا. لا تتدخلي، ودعيه يحب ملعقته.'),
  ('36ebb286-2e4d-4e44-a91d-6c026199737c', 'مهمة استكشاف الطبيعة ⛅', 'لقد أصابتكِ الجدران الأربعة بالخمول. تحقّقي من الطقس واختاري الملابس الأنسب. اخرجي مع طفلكِ في مهمة بسيطة للبحث عن ورقة شجر صفراء؛ فيفرّغ هو طاقته وتتنفّسين أنتِ بعض الهواء النقي.'),
  ('ba525880-dd70-46d8-9c0c-f0fb9b49240c', 'النوم على أصوات الطبيعة 🪄', 'ألا تجدي الموسيقى الكلاسيكية نفعًا؟ أغلقي القصة في قسم القصص الذكية وانتقلي إلى خلفية تحتوي فقط على أصوات المطر أو الغابة. فأصوات الطبيعة الرتيبة تجعل طفلكِ ينام وكأنه مسحور.'),
  ('ba82984e-ccd6-40f9-b991-bf586ff48b9d', 'تنهيدة الكبار 😔', 'يجلس على الأريكة، ثم يأخذ فجأة نفسًا عميقًا ويتنهد مثل الكبار. إنه يقلّدكِ ببراعة! اكتفي بمراقبة تعابير وجهه الدرامية من بعيد بابتسامة.'),
  ('268f32e3-3ad0-45c0-aef4-aba7ce610179', 'كوارث المطبخ 🧑‍🍳', 'عندما تطبخين، سيصرّ حتمًا على مساعدتكِ بجوار الموقد وسكب الملح. إن سمحتِ له فستفسد الوجبة، وإن لم تسمحي له فسيبكي. أعطيه وعاءً فارغًا وبعض الماء وقولي له: «اطبخ حساءك بنفسك».'),
  ('e612b840-bcec-4199-920b-e4d2f37aa7cb', 'مراجعة القائمة 🛒', 'هل أضفتِ كل ما تحتاجين إليه ليوم الاحتفال إلى قائمة التسوق؟ تأكدي من وجود البالونات والمفاجآت الصغيرة فيها أيضًا. أرسلي إلى شريككِ التذكير الأخير عبر التطبيق.'),
  ('eb50f918-4009-4323-94a0-e8fd1ccc9f1d', 'مراقبة الإضاءة 🤫', 'تكون أدمغة الأطفال في ذروة نشاطها خلال أول نصف ساعة من النوم. اضبطي أجواء الغرفة باستخدام مقياس الصوت. اعزلي الأصوات القادمة من النافذة ووفّري بيئة هادئة ومظلمة تمامًا.'),
  ('0cde3d33-fabc-43f7-bcba-b8c6c307e26e', 'مخرج القصة 🪄', 'افتحي القصص الذكية ودعيه يوجّه أحداث القصة هذا المساء. اسأليه: «إلى أين يذهب البطل الآن؟» ودعيه يخلد إلى النوم مع النهاية الطريفة غير المنطقية التي ابتكرها بنفسه.'),
  ('60a51ebc-ca29-4910-bc60-cd0880a0539a', 'دموع بلا منطق 🐶', 'هل بكى بحرقة لمدة 15 دقيقة لأن الكلب الذي رأيتماه في الشارع لم ينظر إليه؟ لا تبحثي عن المنطق، فهذا حزن عميق وحقيقي بالنسبة إليه. أكّدي مشاعره بقولكِ: «أعلم أنك كنت تريد أن ينظر إليك».'),
  ('e0a781fd-ff93-41bb-aced-df42a4ca9525', 'التصالح مع فوضى المنزل 🌪️', 'هل تغطي الألعاب أرجاء الغرفة؟ المهم ليس التنظيف، بل هذه اللحظات المرحة التي تقضينها معه. ستظل الألعاب موجودة غدًا، فلا ترهقي نفسكِ. أحيانًا يكون الاستسلام للفوضى أفضل طريقة للراحة.'),
  ('c145c120-a19a-477b-922c-6f3ffc430787', 'قواعد لغوية مبتكرة 🗣️', 'بدأ طفلكِ يبتكر صيغًا زمنية غريبة ومضحكة مثل «ذهبتُتُ» و«كان يأتيتي». إن حصيلته اللغوية تتطور! لا تصححي له وأنتِ تضحكين، بل كرري الجملة الصحيحة لتؤكديها.'),
  ('6e5eaf14-24e1-4f23-8d49-63a035b843ff', 'اللجوء إلى يوميات المزاج 📝', 'ألا يلاحظ أحد مدى إرهاقكِ؟ يوميات المزاج في التطبيق موجودة لتستمع إليكِ. اكتبي فيها اليوم كل التفاصيل الصغيرة التي أفقدتكِ صوابكِ، وأريحي ذهنكِ.'),
  ('b83f22c8-15c6-43cf-9689-94f8a790e4b9', 'اختبارات الطعام 🥣', 'كان طفلكِ حتى الأمس يأكل كل شيء، لكنه يبصق الطعام اليوم. إذا لم تكن لديه مشكلة في أسنانه، فهو يختبر حدودكِ فحسب. تصفحي الوصفات الصحية وجربي وصفات الأقراص الملونة واللذيذة التي تُخفى فيها الخضراوات.'),
  ('fe01f44d-664a-4a34-8ce6-39e87f7fdab2', 'وهم الدقائق الـ5 ⏱️', 'يقول إنه سيشاهد 5 دقائق أخرى فقط، لكنه لا يدرك مفهوم الدقائق الـ5. اضبطي مؤقت الهاتف واجعليه يفهم أن الوقت انتهى عندما يسمع رنينه. دعي التكنولوجيا تتحمل اللوم بدلًا منكِ.'),
  ('1fc309f5-659f-4b2e-bf6f-e17296d830ff', 'ركوب الخيل على ظهر الأب 🐴', 'لم يفرغ طفلكِ طاقته بالكامل ويرفض الذهاب إلى الفراش؟ ركوب ظهر أبيه والتجول في المنزل كأنه يمتطي حصانًا، مع نوبات من الضحك، هو أقصر الطرق وأكثرها متعة لتفريغ تلك الطاقة. الكرة الآن في ملعب الأب.'),
  ('69846205-68bb-4476-a7e0-45d4e68fae26', 'حاجة الأم إلى الهدوء 🩸', 'هل يزعجكِ كل صوت؟ تحققي من متتبّع الدورة الشهرية. يحتاج جسمكِ إلى الراحة. حضّري وجبة خفيفة غنية بالمغنيسيوم من قسم الوصفات الصحية، وخصصي بعض الوقت لنفسكِ.'),
  ('c6dcd330-d5df-4d87-b7a0-d8ab33a73063', 'نوبات صراخ بلا سبب 😭', 'هل يبكي طفلكِ بلا سبب بمجرد أن يفتح عينيه؟ هذا ليس دلالًا، بل فيض من المشاعر. اكتشفي كيفية التعامل معه أثناء نوبة الانفعال من خلال التحدث إلى خبيرنا بالذكاء الاصطناعي Anacan.'),
  ('6ac257ab-47ac-4e61-a9e4-2b538df0a8dc', 'مناوبة الأب في المطبخ 👨‍🍳', 'يتولى الأب اليوم إعداد الغداء وإطعام طفلكِ! أما أنتِ، فخصصي هذا الوقت لنفسكِ، واستلقي أو استريحي فحسب.'),
  ('4b98ee52-d8a1-4d7a-9183-64cdd8482ef0', 'كلمات خطرة 🤐', 'هل يكرر أمامكِ ضاحكًا تلك الكلمة السيئة التي سمعها في مكان ما، وينتظر رد فعلكِ؟ أقوى سلاح لديكِ هو عدم إبداء أي رد فعل. لا تضحكي ولا تغضبي، بل تجاهلي الأمر ببساطة. وسينساها.'),
  ('c2b89303-d5b8-4b81-97cd-3a091f15bb05', 'مقياس الصمت الذهبي 🤫', 'لقد نام أخيرًا! فعّلي أداة قياس الصوت وتابعي على الشاشة مستوى الصوت الفعلي في الغرفة (0-10 ديسيبل). رؤية هذه الأرقام هي أفضل تدليك لذهن الأم المتعبة.'),
  ('45a51286-f051-4f99-a23c-39a189481dfa', 'ملابس النوم العنيدة 👗', 'هل يرفض خلع ملابس النوم المتسخة والملطخة التي يرتديها منذ الصباح حتى المساء؟ المظهر ليس مهمًا في سن 3 سنوات. ما دام لا يشعر بالبرد، فدعيه يبقى هكذا بضع ساعات أخرى.'),
  ('4c871abf-c886-4fbd-909f-95e344736fa3', 'أنا في الحكاية الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب. افتحي الحكايات الذكية، واجعلي طفلكِ بطل القصة وغرفته المكان الذي يجب فتحه، وابتكري جلسة نوم استثنائية.'),
  ('9f3be00e-0091-4500-91da-22dc9ba62d93', 'ناقد الرسوم المتحركة 📺', 'يروي لكِ أحداث الرسوم المتحركة التي شاهدها بلغته وقواعده الخاصة، ويشرح بجدية من ذهب وإلى أين. استمعي إليه باهتمام وكأنكِ مندهشة. ودعيه يشعر بأنه أذكى شخص في العالم.'),
  ('89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8', 'من يستيقظون قبل الشمس 🌅', 'هل يستيقظ طفلكِ في الساعة 6 بينما تكونين منهكة؟ اسألي Anacan AI عن كيفية تنظيم هذا الروتين. وتذكّري أن الحرمان من النوم لن يدوم إلى الأبد، فكل شيء سيمر.'),
  ('e229522e-360b-4392-8cfc-620f6326286c', 'نخب الشريكين 🥂', 'نام طفلكِ. وحتى إن لم تتوفر الشمبانيا، فاسكبي الشاي الساخن في كوبين، وقولي لشريككِ: «لقد اجتزنا هذا اليوم الصعب أيضًا بسلام»، ثم تبادلا نخبكما. أنتِ شريكة رائعة.'),
  ('f802a634-da9b-44e2-a965-9f94ea543fd1', 'مفاجأة في القائمة 🛒', 'فتحتِ قائمة التسوق قبل الذهاب إلى المتجر، فإذا به يأتي من خلفكِ ويضغط على شاشة الهاتف ليضيف الشوكولاتة إلى القائمة. نعم، إنهم يفهمون التكنولوجيا أفضل منكِ!'),
  ('0d0524d6-a4ad-4051-b779-b554d981748f', 'تجعّد الأصابع في الحمّام 🛀', 'اللعب بالماء ممتع للغاية لدرجة أن طفلكِ لا يريد الخروج من حوض الاستحمام حتى بعد أن تتجعّد أصابعه. نبّهيه قبل 5 دقائق واضبطي مؤقتًا. غالبًا ما تنجح قاعدة «عندما يرنّ الجرس، نخرج».'),
  ('1460be31-c5b7-4f0f-9a6b-7ff5c2085c36', 'معركة تصفيف الشعر 🪮', 'استيقظ صباحًا وشعره منتصب في الهواء كأنه تعرّض لصدمة كهربائية. وما إن يرى المشط حتى تبدأ المطاردة. بدلًا من تمشيطه، بلّلي يديكِ بالماء ومرّريهما على شعره لتهدئته وإنهاء المعركة.'),
  ('fc5667d9-2c85-42d4-a92c-e90c3b994a0f', 'رأي الذكاء الاصطناعي 🤖', 'هل ظهرت لدى طفلكِ عادة غريبة، مثل قضم الأظافر، وأخافتكِ المقالات المنشورة على الإنترنت؟ توقّفي قليلًا. اسألي Anacan AI عن السبب الحقيقي المعتمد من أطباء الأطفال واطمئني.'),
  ('01349acb-919c-490a-bfce-f75e04518130', 'الطبيب معكِ 🩺', 'يأخذ سماعته الطبية اللعبة ويضعها على صدركِ ويطلب منكِ أن تتنفّسي. أنتِ المريضة، وهو كبير الأطباء. شاركيه هذه اللعبة، واستلقي وأغمضي عينيكِ واستريحي أثناء العلاج، ولو لمدة 5 دقائق فقط.'),
  ('d58d064b-a397-425d-9d57-3f6068e31cf1', 'دفعة من الطاقة 🏃‍♂️', 'يتسلّق طفلكِ جدران المنزل من فرط طاقته. تحقّقي من الطقس والملابس المناسبة، واحرصي على الخروج معه. الركض لمدة 30 دقيقة في الهواء الطلق أفضل ضمان لنومه مساءً.'),
  ('d96fbe0f-26f7-4473-9f0b-34109da6a744', 'سحر الهمس 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واحكي له بصوت خافت جدًا وهمس عمّا حدث خلال اليوم. الهمس من أكثر الطرق الطبيعية والهادئة التي تهيّئ الدماغ للنوم.'),
  ('2521dffb-415b-4bec-81f4-b18ee93644d8', 'التعوّد على الظلام 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية في الغرفة وشاشات الأجهزة اللوحية. يتسارع إفراز هرمون الميلاتونين في بيئة هادئة ومظلمة فقط.'),
  ('8ca17d8b-45e4-4184-b598-9b59778d5b0c', 'وقت شحن طاقة الأم 🔋', 'يركّب الأحجية بمفرده ويلتزم الهدوء منذ 10 دقائق، بينما تريدين استغلال هذه اللحظة في ترتيب المنزل. لا! اذهبي واستلقي على الأريكة. يجب أن تشحني طاقتكِ أنتِ أيضًا لتتمكّني من الصمود حتى المساء.'),
  ('0cd42656-20ce-4f47-aca2-4978ae93880d', 'تراجع في استخدام الحمّام؟ 🚽', 'هل تعلّم استخدام النونية ثم عاد إلى تبليل ملابسه؟ هذا تراجع طبيعي جدًا. لا تضغطي عليه، واسألي Anacan AI عن طرق تجاوز هذا الحاجز النفسي بهدوء ومن دون أزمات.'),
  ('3164bc6c-fe7e-4273-94e8-6750bee50d0a', 'استلهمي من المدوّنات 📱', 'ما طفرات النمو التي يمر بها طفلكِ مع اقترابه من عمر ٣٥ شهرًا؟ وما المهارات التي يُفترض أن يتقنها؟ تصفّحي مدوّنات النمو في التطبيق، وافرحي حين ترين مدى تقدّم طفلكِ.'),
  ('4d45db57-1817-4fc6-ad71-f2aeb4cd1050', 'الاستعداد للاحتفال 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي التهاني مع شريككِ بمناسبة بلوغه الرقم الكبير غدًا، وليدلّك كل منكما كتفي الآخر قليلًا. من الضروري أن تحصلا كلاكما على الراحة لتستمتعا بطاقة يوم الذكرى.'),
  ('41e90866-d00f-459e-8936-e28d83f9d539', 'سباق في غرفة النوم 🏃‍♂️', 'هل يقفز على الأريكة بدلًا من النوم؟ وهل لا تنتهي حججه لطلب المزيد من الماء؟ شغّلي مؤقت النوم وحافظي على حدودكِ.'),
  ('4f9eced2-7736-4f35-ad7d-6205edaad1e4', 'حان دور الأب في اللعب 👨‍👧', 'الأمومة ليست ماراثونًا لا ينتهي. دعي الأب يساعد طفلكِ اليوم على تفريغ طاقته في الحديقة، واستمتعي أنتِ ببعض الوقت الهادئ بمفردكِ على الأريكة.'),
  ('e18107ed-4459-4f40-b466-2d79ae0ff98c', 'قبعات الشتاء في الصيف 🧢', 'هل يريد ارتداء ملابس لا تناسب الطقس إطلاقًا؟ امنحيه خيارات بسيطة في سعيه إلى الاستقلال.'),
  ('37ca7eb9-999f-4245-9a90-94f0e28e6df4', 'آلة الأسئلة التي لا تتوقف 🤔', 'هل تُرهق ذهنكِ أسئلة «لماذا؟» و«كيف؟»؟ تعلّمي من Anacan AI كيف تجيبين عن فضوله الاستكشافي بإجابات منطقية من دون أن تشعري بالملل. صبركِ يدعم نموه.'),
  ('70e9f70c-b53f-462f-9274-badc9beebd25', 'مذكّرات الهدوء 📝', 'نام الإعصار الصغير في المنزل أخيرًا. أمسكي هاتفكِ الآن، واكتبي لنفسكِ في مذكّرات الحالة المزاجية رسالة شكر لأنكِ اجتزتِ هذا اليوم بسلام. أنتِ قادرة على ذلك.'),
  ('d941dd67-309a-49cb-833c-78b38c4762e7', 'دبلوماسية الملابس 👗', 'هل يريد ارتداء سروال صيفي في منتصف الشتاء؟ افتحي فورًا أداة الطقس والملابس، واشرحي له بطريقة منطقية، وبالاستعانة بالصور الظاهرة على الشاشة، أن الطقس في الخارج بارد.'),
  ('0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6', 'قيمة الهدوء 🤫', 'لقد نام أخيرًا. والآن حتى أدنى صوت في المنزل يثير أعصابكِ. أثناء ضبط حد الضوضاء في الغرفة باستخدام مقياس الصوت، شغّلي ضوضاء بيضاء متواصلة في الخلفية.'),
  ('bf9527d0-d7b0-4cb8-8523-c499e2e95693', 'نبدأ العدّ 🔢', 'هل يحاول أن يقول واحد، اثنان، ثلاثة أثناء صعود الدرج أو ترتيب ألعابه؟ هكذا تبدأ أسس التفكير الرياضي بالتكوّن. عدّي معه الأشياء الموجودة في الغرفة بصوت مرتفع.'),
  ('ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5', 'متلازمة الاحتراق النفسي 🔋', 'هل تشعرين برغبة في الصراخ بسبب كل شيء؟ أنتِ تعانين من الاحتراق النفسي. ادخلي إلى مجتمع Anacan واكتبي: أنا متعبة جدًا. سترين أن آلاف النساء يتضامنّ معكِ في اللحظة نفسها.'),
  ('405360f8-7a97-471c-825c-355eafed365d', 'رفض القيلولة 🥱', 'هل يرفض تمامًا أخذ قيلولة ويقاوم النوم؟ مع الاقتراب من سن 3 سنوات، يتوقف بعض الأطفال عن أخذ القيلولة. جرّبي استبدالها بساعة هدوء (sleep-free quiet time).'),
  ('6740b19e-f070-42e2-9b6e-76434890c90f', 'الذكريات تستيقظ 🧠', 'هل بدأ يؤلف جملًا عن الماضي، مثل: ذهبنا أمس إلى منزل جدتي؟ إن مفهوم الزمن والذاكرة طويلة المدى يتشكلان لديه. استمعي إلى ذكرياته باهتمام واطرحي عليه الأسئلة.'),
  ('f0257b2e-d5f4-40d8-9701-488c186af81f', 'هل يصرخ ويبكي في منتصف الليل وعيناه مغمضتان؟', 'لا تحاولي إيقاظه. دعي أداة تحليل البكاء تستمع إلى صوته للتأكد من أنه مجرد فزع ليلي، وابقي بجانبه بهدوء.'),
  ('f7c61cc4-7a2d-48d0-bf89-ec947a89cd75', 'مسؤولية الأب 👨‍🍼', 'لستِ مضطرة إلى القيام بكل شيء. هذا المساء، أوكلي إلى الأب بالكامل مهمة تنظيف الأسنان وارتداء ملابس النوم، وراقبيهما من بعيد.'),
  ('07c7c2cb-58bb-47db-ac0e-f81bd01e602b', 'قوة صوت الأم 🎶', 'لا تستخدمي أي جهاز هذا المساء. فقط ضمّيه إلى صدركِ وهمسي في أذنه بتهويدته المفضلة. صوتكِ هو ملاذه الأكثر أمانًا.'),
  ('1acb826a-9b73-413f-b0af-4614a74084bd', 'دعم سريع من طبيب الأطفال 🤖', 'هل يقلقكِ مخطط طول طفلكِ ووزنه مع اقترابه من سن ٣ سنوات؟ لا تقضي ساعات في البحث على الإنترنت، بل تعرّفي فورًا إلى المعايير الدقيقة والمعتمدة من أطباء الأطفال عبر Anacan AI.'),
  ('5bb344ff-e859-413b-93f7-4f25386f0835', 'يعرف اسمه وعمره 🎂', 'هل يحاول الإشارة بأصابعه عندما تسألينه: كم عمرك؟ هذا دليل رائع على وعيه بهويته. سجّلي هذه القفزة الذهنية في متتبّع النمو.'),
  ('2c139fbd-2360-47be-8201-67957bcf1684', 'مخرج أمام المرآة 🎭', 'هل يقف أمام المرآة ويقلّد تعابير مختلفة ويتحدث إلى نفسه؟ إنه يجرّب أدوارًا مختلفة. راقبيه خلسة واستمتعي بهذه اللحظات الطريفة.'),
  ('42026a5f-2788-45b9-acb9-1e97ccc1366b', 'تحتاجين إلى استعادة طاقتكِ 🍲', 'لقد أرهقكِ الركض طوال اليوم. اختاري من قسم الوصفات الصحية وجبة غداء مميزة وغنية بالحديد والبروتين، تحبينها أنتِ وطفلكِ.'),
  ('f413f7f2-f85e-4bd1-a054-6b9d46b4d341', 'مراجعة اليوم 📝', 'بمجرد أن ينام طفلكِ، افتحي مع شريككِ يوميات المزاج. اكتبا أطرف موقف قام به طفلكِ اليوم، وابتسما معًا لتخفيف التوتر.'),
  ('59d23d62-6dca-4962-aec7-eb093810797b', 'الاستعداد للنوم مع الموسيقى 🛀', 'هل أصبح الروتين المسائي صعبًا؟ شغّلي موسيقى كلاسيكية هادئة في الخلفية أثناء استحمام طفلكِ بماء فاتر. فتناغم الماء والموسيقى يهدّئ حتى أكثر الأطفال عنادًا.'),
  ('cac1efaa-10e1-4f19-b586-507cb8610102', 'إصرار «سأفعلها بنفسي» 🛑', 'يريد ربط حذائه بنفسه ويستغرق ذلك 10 دقائق من وقتكِ؟ لا تستعجلي، وامنحيه الوقت. فمحاولاته وأخطاؤه هي أساس قدرته المستقبلية على حل المشكلات.'),
  ('078ff563-48f3-4bd6-81ac-93fc21a3bab7', 'القهوة والتأمل ☕', 'هل قلب الغرفة رأسًا على عقب؟ دعي التنظيف جانبًا. وبينما ينشغل طفلكِ باللعب، اجلسي على الأريكة واحتسي قهوتكِ الساخنة وحدّقي في الجدار فحسب لتصفية ذهنكِ لمدة 10 دقائق.'),
  ('710f54a9-baa0-4889-a361-f7615894b552', 'تقليد المهن 🩺', 'هل يعالج دبه المحشو أو يصلح السيارات؟ لقد بلغت الألعاب الرمزية (لعب الأدوار) أوجها.'),
  ('9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a', 'ألعاب الظلال 🐰', 'لا يريد النوم؟ أظلمي الغرفة تمامًا واصنعي بيديكِ مسرحًا للظلال على الحائط. إنها أكثر الطرق متعةً للتغلب على الخوف من الظلام.'),
  ('3a84b553-313a-486c-95e8-2a799895283c', 'لا تبكِ 🫂', 'هل يقترب من طفل آخر يبكي في الحديقة ويربّت عليه؟ لقد بدأ حس التعاطف لديه يعمل رسميًا! راقبي هذا القدر الرائع من الرحمة بفخر.'),
  ('77ff1ffc-86a7-418d-bad4-4d026f199772', 'هل حان وقت الانتقال إلى سرير كبير؟ 🛏️', 'هل يحاول التسلق للخروج من سريره؟ ربما بدأتِ تتساءلين إن كان الوقت قد حان. اسألي Anacan AI عن قواعد السلامة والوقت الأنسب للانتقال إلى سرير الأطفال الكبار.'),
  ('e176efcb-aafc-4480-93eb-e1978282a880', 'موعد القراءة مع الأب 📖', 'أريحي أحبالكِ الصوتية هذا المساء. ودعي الأب يتولى مهمة قراءة كتب طفلكِ المفضلة مستخدمًا نبرات صوت مختلفة.'),
  ('65edab42-e5b4-4da3-8b99-8e271dd3fc16', 'يضع حدوده الشخصية ✋', 'هل يبتعد أو يقول لا عندما يحاول أحدهم تقبيله؟ احترمي حدود جسده وألزمي الآخرين باحترامها أيضًا. فمن هنا تبدأ الثقة بالنفس.'),
  ('605d2ada-99ba-4138-bd88-c091a6c53e2b', 'حماس «وجدتُك!» 🙈', 'أصبحت لعبة الغميضة لعبته المفضلة. يختبئ خلف الستارة وينتظر أن تجديه. وفي هذا العمر، تساعد الألعاب على ترسيخ مفهوم بقاء الأشياء لديه.'),
  ('c0738cb9-5d1f-47d6-821c-55b543c58b28', 'التعامل مع نوبات الغضب 🛑', 'هل تُشعركِ نوبات غضب طفلكِ في المتجر أو الحديقة بالإحراج؟ تذكّري أن المهم ليس ما يفكر فيه الآخرون، بل مشاعر طفلكِ في تلك اللحظة. احتضنيه بهدوء.'),
  ('244e81e4-ef8a-4010-a428-229aabe2c4b0', 'اطلبي المساعدة من شريككِ 🛒', 'أليس لديكِ وقت للتسوق؟ افتحي قائمة التسوق، ودوّني كل ما ينقص في المنزل، ثم أرسليها إلى شريككِ بنقرة واحدة. فتقاسم المهام أمر ضروري.'),
  ('e5509d0f-428a-4a25-9b61-f825746504ad', 'قراءة كتاب في هدوء 📖', 'دعي الصوت الوحيد في الغرفة هذا المساء يكون صوت تقليب صفحات الكتب. استلقيا معًا على السرير، ودعيه يتصفح كتابه المصوّر بينما تستريحين في هدوء.'),
  ('f568dd40-0374-40d2-8f34-9a863c9b7158', 'قفزات خطرة 🧗‍♂️', 'هل يحاول القفز من أعلى الأريكة إلى الأرض؟ إنه يثق كثيرًا بمهاراته الحركية. وبدلًا من منعه، ضعي وسائد ناعمة على الأرض وأنشئي له منطقة آمنة للقفز.'),
  ('1222929d-ba35-40ba-92f4-2c3b29988e2e', 'اختبار خرق القواعد ⚠️', 'هل ينظر مباشرةً في عينيكِ ويفعل ما طلبتِ منه ألّا يفعله؟ إنه لا يريد إغضابكِ، بل يختبر مدى ثبات حدودكِ. فكوني ثابتة في تطبيق القواعد.'),
  ('60d686a6-8001-479b-9d53-bcd85bcdffdb', 'دعي المنزل فوضويًا 🌪️', 'هل سئمتِ من جمع الألعاب نفسها كل يوم؟ لا تجمعيها اليوم! ففوضى المنزل ليست نهاية العالم، لكن الانهيار النفسي للأم أمر خطير.'),
  ('e7bfaacc-c0cc-4b36-8687-477371b3bc3d', 'اليوم في الحكاية الذكية 🪄', 'اختاري موضوعًا مميزًا للحكايات الذكية: دبدوب سحري يحب جمع ألعابه. لعل هذه القصة تساعدكِ في ترتيب المنزل غدًا!'),
  ('895f4348-4fb2-4124-9532-acf7d07409f6', 'طقوس الأب 👨‍🍼', 'للأطفال طقوس خاصة مع آبائهم. اتركي مهمة تنويم طفلكِ هذا المساء لقواعد الأب الطريفة، واستمتعي بكوب الشاي بهدوء خارج الغرفة.'),
  ('aca7ae85-535e-4175-ab27-d1ca390e78cb', 'اكتشاف الألوان 🎨', 'هل يصنّف الألوان بشكل صحيح قائلًا: هذا أحمر، وهذا أزرق؟ إنها قفزة كبيرة في التطور المعرفي! سجّلي هذا الإنجاز بفخر في متتبّع التطور.'),
  ('b6ee83b4-0d5f-4791-8483-ed7d1d3aa649', 'معًا في المطبخ 🧑‍🍳', 'هل يرغب طفلكِ في مشاركتكِ العمل؟ اختاري وصفة كعكة سهلة من بين الوصفات الصحية، ودعيه يساعدكِ في إضافة الدقيق أو الماء. حتى لو أحدث بعض الفوضى، فالمرح مضمون.'),
  ('2009290a-99c2-4bf0-a2b6-174daa69d49d', 'مستوى الضوضاء ليلًا 🤫', 'هل تمنع الأصوات القادمة من الشارع طفلكِ من الاستغراق في نوم عميق؟ حلّلي مستوى الضوضاء في الغرفة باستخدام مقياس الصوت.'),
  ('2a0f6e31-8cdc-436b-8432-73cf4dad5b5c', 'فنان منهمك في العمل 🖍️', 'قد تتحول الجدران والأبواب أحيانًا إلى لوحته. بدلًا من الغضب، أحضري قطعة كبيرة من الورق المقوّى، وافرديها على الأرض وقولي له: «هذا المكان لك». وجّهي إرادته في الاتجاه الصحيح.'),
  ('7750d70c-df5b-48b0-9b2f-522c15391059', 'سيل من الأسئلة 🤖', 'هل لا تنتهي أسئلتكِ حول سلوك طفلكِ مع اقترابه من سن 3 سنوات؟ Anacan AI هو طبيب أطفال وأخصائي نفسي رقمي متاح لكِ على مدار الساعة طوال أيام الأسبوع. اكتبي سؤالكِ واحصلي على إجابة فورًا.'),
  ('2859fc00-366b-44b7-ba24-815b9b659125', 'أطلقي العنان لمشاعركِ 📝', 'هل تشعرين بالوحدة الشديدة وبأن لا أحد يفهمكِ؟ هذا شعور طبيعي تمامًا. اكتبي مشاعركِ بصدق في يوميات الحالة المزاجية.'),
  ('4f59cf22-ccfa-43b9-8a30-62365a911312', 'يكتشف ذاته 👑', 'لا تفارق عبارتا «أنا!» و«هذا لي!» لسانه. إنها المرحلة الأبرز من التمركز حول الذات. احترمي فرديته، فهذه مرحلة طبيعية من مراحل التطور.'),
  ('1da71143-b8dd-434a-bf23-b7f16a2d4a80', 'شلال الاستقلالية 🥛', 'يصرّ على سكب الماء أو الحليب في الكوب بنفسه، والنتيجة؟ برك في كل مكان. خذي نفسًا عميقًا. هذه الفوضى هي ثمن تطوّر التناسق بين يديه وعينيه وتعزيز ثقته بنفسه. أعطيه قطعة قماش أيضًا ونظّفا المكان معًا بهدوء.'),
  ('7f1b27a1-aff6-4522-ba4e-76bb08fa648e', 'استراحة من الضوضاء 🎧', 'هل ما زالت نداءات «ماما، ماما، ماما!» تتردد في رأسكِ؟ خصّصي لنفسكِ استراحة قصيرة. دعيه ينشغل بنشاط آمن لمدة 15 دقيقة، واشربي قهوتكِ في هدوء تام. فبطاريتكِ تحتاج إلى الشحن أيضًا.'),
  ('9ebeb631-4aa4-4310-b78e-47bee6920a4e', 'التغلّب على رفض الاستحمام 🛁', 'هل يرفض دخول الحمّام ويتدحرج على الأرض احتجاجًا؟ بدلًا من قول «تعال لأغسلك»، قولي: «لنذهب ونحمّم سياراتك المفضلة (أو دماك)». فتحويل ما يجب فعله إلى لعبة هو أفضل وسيلة للتغلب على مقاومة الطفل.'),
  ('5188ae48-9680-4372-a0c2-b6a14d87d513', 'أزمة الحذاء في المنزل 👟', 'هل يبكي لأنه يريد ارتداء حذائه الخارجي داخل المنزل ويرفض خلعه تمامًا؟ الأمر لا يستحق معركة. امسحي نعله بقطعة قماش مبللة ودعيه يتجول به في الغرفة بفخر لبضع ساعات. أحيانًا يكون اختيار الأم خسارة بعض المعارك أعظم انتصار لها.'),
  ('a80b1c35-a6ce-48dc-a430-2268378d43f5', 'حان دور الأب 👨‍🍼', 'لقد تعبتِ طوال اليوم من قول «لا» ووضع القواعد. سلّمي إلى الأب هذا المساء معركة ارتداء ملابس النوم وتنظيف الأسنان. أغلقي باب الغرفة وخصّصي وقتًا كاملًا لنفسكِ، واكتبي ببساطة مشاعركِ اليوم في مفكرة المزاج.'),
  ('f6d030df-f5ef-4ef7-84fc-04dd7126bef2', 'ابتسامة في المجتمع 💬', 'هل استنزفكِ عناده اليوم حقًا؟ افتحي مجتمع Anacan فورًا واقرئي قصص الأزمات المشابهة، بل والأكثر طرافة، التي تواجهها أمهات أخريات في منازلهن. إن معرفة أنكن تخضن التجارب نفسها وأنكِ لستِ وحدكِ هي أفضل دعم نفسي.'),
  ('16b69d4c-feb3-42d5-b458-329c2a13a823', 'البحث عن أصدقاء جدد 👫', 'هل يحاول الركض مع أقرانه في الحديقة والانضمام إلى ألعابهم؟ لقد بدأت مرحلة التفاعل الاجتماعي رسميًا! شجّعيه وعلّميه كيف يحيّي الأطفال.'),
  ('db813abc-1129-479f-a1e4-e6beaeb2ec95', 'العلاج بالطبيعة للأم 🌳', 'هل تشعرين بأن جدران المنزل تخنقكِ؟ اصطحبي طفلكِ وانطلقي إلى أقرب حديقة. فالهواء النقي أفضل ما يهدّئ أعصاب طفلكِ المتعبة وأعصابكِ أيضًا.'),
  ('eddd6a67-3ce9-4446-ba23-dba7c167dca2', 'الطقس متقلب ⛅', 'هل تريدين الخروج في نزهة، لكن الطقس في الخارج خادع؟ استخدمي أداة الطقس والملابس لتختاري لطفلكِ الأنسب، بحيث تحميه من دون أن تجعله يتعرق.'),
  ('009a8d5c-9bba-4789-a6ee-e59d4c647832', 'فخر الفريق 🥂', 'لقد اجتزتما أسبوعًا صعبًا. اجلسي مع شريككِ وجهًا لوجه، وشجّعا بعضكما بقول: نحن نُحسن حقًا تربية هذا الطفل.'),
  ('d0adf273-d83c-415a-88b8-6fa5f74c5f51', 'يروي حكاية بالجمل 🗣️', 'هل ينظر طفلكِ إلى كتاب مصوّر ويؤلف حكاية من جمل يبتكرها بنفسه؟ لقد انطلق خياله وتطورت قدرته على الكلام معًا! أنصتي إليه باهتمام وصفّقي له.'),
  ('ff22b088-7f8b-4366-a32b-7bd8cd1aa92f', 'تضامن الأمهات 💬', 'هل أصابكِ التدريب على استخدام النونية بالإحباط؟ انضمي فورًا إلى مجتمع Anacan. ستمنحكِ قصص نجاح الأمهات الأخريات وإخفاقاتهن هناك القوة والدعم.'),
  ('1c47434b-8f04-4342-a73a-e77c7a63eb48', 'الخوف من الظلام 🌙', 'هل يخاف طفلكِ من ظلام الغرفة؟ ضعي مصباحًا ليليًا صغيرًا بجانب سريره، لكن تأكدي من أن الغرفة تظل مظلمة بما يكفي لإفراز الميلاتونين.'),
  ('77a1ab3f-8086-4334-93ed-03dab08fb152', 'يريد اختيار ملابسه بنفسه 👗', 'هل يفتح طفلكِ الخزانة ويريد تنسيق ألوان وملابس لا تناسب الموسم؟ ادعمي استقلاليته، لكن قدّمي له خيارين فقط لتُبقي زمام الأمور بيدكِ.'),
  ('b22d0c31-c528-4596-b176-4f64d3f5be5d', 'شحنة القهوة ☕', 'هل توقّف طفلكِ عن القيلولة ولم تعودي تجدين فرصة للراحة طوال اليوم؟ دعيه ينشغل بنشاط آمن لمدة 15 دقيقة، واحرصي على أخذ استراحة لشرب قهوتكِ واستعادة طاقتكِ.'),
  ('9787e3a9-8592-4bb2-8463-c4e695682c99', 'حِمل ثقيل وإرادة عنيدة 🛒', 'هل يصرّ طفلكِ عند العودة من النزهة على حمل أثقل غرض أو كيس بنفسه؟ حتى إن عجز عن تحريكه من مكانه، يرفض مساعدتكِ بشدة. دعيه يحاول قليلًا ويختبر قوته.'),
  ('bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001', 'الفيلسوف الصغير 🤔', 'هل رفع رأسه فجأة، بينما كانت عيناه توشكان على الانغلاق، وسألكِ سؤالًا فلسفيًا مثل: «ماما، أين تذهب الشمس لتنام؟» يواصل دماغه استيعاب العالم حتى في لحظة الانتقال إلى النوم. قدّمي له إجابة قصيرة تشبه الحكايات من دون الخوض في تفاصيل عميقة.'),
  ('c2525bad-5158-49a7-81ce-247259a08d2e', 'طلبات مستحيلة 🪄', 'هل استيقظ هذا الصباح وهو يصرخ مطالبًا إياكِ بإعادة شرائح التفاح إلى تفاحة كاملة؟ نعم، مع اقتراب سن الثالثة، يتحدى منطق الأطفال قوانين الفيزياء.'),
  ('1e3f3fa1-dbbc-4651-aa40-6590038f46b0', 'تقليد الحيوانات 🐶', 'هل يكتفي بإصدار أصوات الحيوانات، أم يحبو أيضًا كالكلب ويتدلل كالقط؟ هنا تجتمع لغة الجسد مع الخيال. انضمي إليه في هذه اللعبة على السجادة.'),
  ('4ac97d09-8bce-44ef-922e-5286afc49815', 'انتقائية الطعام 2.0 🥣', 'هل يرفض اليوم الحساء الذي كان يحبه حتى الأمس؟ لا تجبريه. ابحثي في قسم الوصفات الصحية عن وصفات بديلة ومتنوعة يمكنكِ إخفاء الخضراوات فيها.'),
  ('d8f03ef9-1ea4-48a4-a43d-dc4f633f2d60', 'حكاية النوم السحرية 🪄', 'ابتكري له في قسم الحكايات الذكية قصة بطل شجاع يستعد لبلوغ الثالثة، واجعليه يشعر بأنه يكبر ويزداد قوة.'),
  ('2a9575e0-ee4f-4f27-86a9-25def022748e', 'أبحث عنكِ! 👀', 'هل يبدأ بالبكاء مجددًا فور خروجكِ من الغرفة؟ قد يعود قلق الانفصال أحيانًا. طمئنيه بصوتكِ من بعيد، فلستِ مضطرة إلى البقاء أمام عينيه طوال الوقت.'),
  ('89de8241-ec59-4180-ba30-e03291e0f208', 'دعيه يروي نهاية الحكاية 📖', 'عندما تقرئين له حكاية هذا المساء، توقفي قبل إكمال الجمل ودعيه يكملها! اسألي ذكاء Anacan الاصطناعي عن أساليب الحوار التي تدعم هذا التطور المذهل للخيال.'),
  ('ca321f21-1031-4b14-96c8-69fa4c4201da', 'القائمة ضرورية 🛒', 'لا تنسي المستلزمات الضرورية لعيد الميلاد! لا ترهقي ذهنكِ، بل دوّني كل شيء فورًا في قائمة التسوق وزامنيها مع شريككِ.'),
  ('fabd170d-dc89-4100-b9c1-3acf59e32a5c', 'حديث مع نملة غير مرئية 🐜', 'هل ينحني طفلكِ في الشرفة أو الحديقة ليتحدث بجدية شديدة إلى نملة على الأرض؟ هنا يعمل الخيال والتعاطف معًا. التقطي هذه اللحظة الرائعة فورًا عبر جلسة تصوير طفلكِ، وضعيها في ألطف زاوية من الأرشيف.'),
  ('a860534c-7167-4781-b298-8321127fd089', 'وضع الطيران مع الأب ✈️', 'لم يتمكن طفلكِ من تفريغ طاقته في المنزل، ويرفض الذهاب إلى السرير. اطلبي مساعدة الأب. عندما يرفعه في الهواء ويتظاهر بأنه طائرة، تملأ الضحكات الغرفة، ويختفي كل التوتر الجسدي المتراكم خلال ثوانٍ.'),
  ('e0e56f8d-3c51-4c46-90f2-dbfa90060519', 'حرية التمرغ على الأرض 🌪️', 'هل ألقى طفلكِ بنفسه على الأرض وسط المتجر؟ لا تحاولي حمله أو تبرير الموقف لمن حولكِ. خذي نفسًا عميقًا. عندما تدخلين إلى مجتمع Anacan، سترين أن آلاف الأمهات يعشن اللحظة المحرجة نفسها، رغم أنها طبيعية.'),
  ('e9ba4911-0212-43aa-9a51-c6bf942facb9', 'عناد «لا تنظري إليّ!» 🙈', 'يبكي قائلًا: «لا تنظري إليّ!» لمجرد أنكِ نظرتِ إليه وابتسمتِ. يا لها من قمة المنطق العبثي! أديري وجهكِ جانبًا وانتظري حتى تنتهي هذه النزوة المضحكة؛ فأحيانًا لا يعرف الأطفال أنفسهم ما يريدون.'),
  ('3b9f5253-06a7-4aef-bfdf-bb0daf30818e', 'سحر الأضواء 🌙', 'هل بدأ طفلكِ يخاف من الظلام؟ أظلمي الغرفة تمامًا والعبا بمصباح صغير، واصنعا أشكالًا ضوئية على السقف. حوّلي الظلام الذي يخشاه إلى متعة ومغامرة استكشافية صغيرة قبل النوم.'),
  ('5d1a2a49-e134-453a-a974-f4cff4de0952', 'عشق ملابس النوم 👗', 'استيقظ طفلكِ صباحًا ويرفض بشدة خلع ملابس نومه الملطخة. إذا لم تكوني ستغادرين المنزل، فتجنبي هذه المعركة. أحيانًا تكون راحة الأم النفسية أهم بكثير من مظهر طفلها المرتب.'),
  ('c8ffca51-c2fa-4f5a-8090-6c144b596f9c', 'كنوز تخرج من الجيب 🍁', 'عدتما من الحديقة، فوجدتِ في جيبه 3 أحجار وورقة شجر يابسة وغصينًا صغيرًا. قد تكون قمامة بالنسبة إليكِ، لكنها كنز بالنسبة إليه. أعدّي صندوقًا لمجموعته ودعيه يضعها فيه بدلًا من بعثرتها في المنزل.'),
  ('176265d3-ef2f-4ec4-923c-4308870e611f', 'التخفف من العبء العاطفي 📝', 'ألا يوجد في منزلكِ من يلاحظ مدى تعبكِ؟ مفكرة المزاج هي كاتمة أسراركِ الأكثر هدوءًا. اكتبي فيها اليوم كل التفاصيل التي أفقدتكِ صوابكِ، ولاحظي كيف يشعر ذهنكِ بالخفة.'),
  ('15f19421-c415-4b7b-ad4d-54211e4ccb3a', 'الماء في كل مكان! 💧', 'أصرّ على أن يسكب الماء في الكوب بنفسه. فانسكب الماء وابتلّ كل شيء. لكن انظري إلى يديه الصغيرتين وهما تحاولان أخذ الممسحة وتنظيف المكان. إنه يتعلّم تحمّل المسؤولية من خلال أخطائه، فلا تغضبي.'),
  ('6d2f1d1e-d7d7-41c3-b906-1e286aab1a51', 'حان دور الأب 👨‍👧', 'الأمومة ليست سباقًا طويلًا لا ينتهي. دعي الأب يتولى نزهة الحديقة اليوم، واستمتعي أنتِ ببعض الوقت الهادئ بمفردكِ على الأريكة.'),
  ('cf9e0ee2-2f17-4a55-933b-735bc0754d7e', 'تدليك بالتناوب 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي مع شريككِ تدليك الكتفين للتخلص من ضغوط اليوم. فأنتما لستما مجرد والدين، بل أكبر داعمين لهذا المنزل وأحدكما للآخر.'),
  ('2caa3c21-d2d3-4566-921a-e08cdbce1397', 'لقد تعبتُ... 🔋', 'الجميع ينتظر منكِ الطاقة، لكن بطاريتكِ نفدت. لا تطهي شيئًا اليوم؛ اطلبي طعامًا جاهزًا أو اسلقي أبسط طبق من المعكرونة. كونكِ بطلة خارقة لا يعني أن عليكِ فعل كل شيء بمفردكِ.'),
  ('48299b62-1108-44e9-af43-b48460ffdfa2', 'سلام في حوض الاستحمام 🛀', 'مرّ اليوم كله وسط عبارات «لا أريد». الحمّام الدافئ ليس للنظافة فحسب، بل يساعد أيضًا على تهدئة جهازه العصبي المتوتر. استمعي إلى صوت الماء، وستتغير أجواء الغرفة في الحال.'),
  ('ab5bd705-a57d-40d7-b0a0-86107e824b4d', 'صعود الدرج بمفرده 🧗', 'هل يحاول صعود الدرج من دون مساعدة؟ مهاراته الحركية في أوج تطورها! راقبيه من قرب من دون أن تتدخلي. وخلّدي لحظة الاستقلال هذه باستخدام جلسة تصوير الطفل.'),
  ('33979ce6-ea09-4adc-ab85-0cf386a73156', 'سحر الصندوق الجذّاب 📦', 'اشتريتِ له لعبة باهظة الثمن تصدر أصواتًا، لكنه تركها وأخذ يلعب بعلبتها منذ 1 ساعة. لا يفضّل دماغ الطفل الأشياء ذات البنية الجاهزة، بل يحب الأشياء البسيطة التي تتيح له إطلاق خياله. راقبي وتعلّمي.'),
  ('5b89452a-e411-4130-87b7-6e1e33b0701e', 'ضوضاء بيضاء طبيعية 🤫', 'تزداد حساسيته في لحظات استغراقه في النوم. لتحييد الأصوات القادمة من الشارع، فعّلي صوت الخلفية في مقياس الصوت داخل الغرفة، وامنحيها أجواءً دائمة من السكينة.'),
  ('565fda98-0d2c-40b4-8230-13c64e585700', 'مأساة درزة الجورب 🧦', 'استيقظتما هذا الصباح على أزمة كبيرة: درزة الجورب تلامس إصبعه! تبلغ الحساسية العاطفية ذروتها مع الاقتراب من عمر 3 سنوات. لا تبحثي عن المنطق، بل ألبسيه الجورب مقلوبًا، وشاهدي كيف تنتهي هذه الأزمة العبثية خلال 10 ثوانٍ.'),
  ('acd26d8c-d24f-4082-9973-a1110aefb638', 'صياد البرك 🌧️', 'خرجتما بعد المطر فقفز مباشرة في بركة موحلة؟ اتسخت ملابسه، لكن انظري إلى بريق الاكتشاف في عينيه. خططي مسبقًا لإلباسه حذاءً مطاطيًا مناسبًا للطقس، ودعيه يستمتع بطفولته.'),
  ('b17158eb-f894-42c6-8d84-cab6d30d297a', 'تمنّي ليلة سعيدة للألعاب 🧸', 'حان وقت النوم، لكنه يودّع كل سيارة ودبدوب في الغرفة واحدًا تلو الآخر. إنها تحفة فنية في تأخير موعد النوم. اضبطي مؤقتًا، وطبّقي قاعدة توديع جميع الألعاب معًا خلال 3 دقائق.'),
  ('3b1d044a-5917-48bd-b4f3-847b5ba6d5db', 'أغرب غرض 🥄', 'لديه الكثير من الألعاب الباهظة، لكنه وجد مغرفة في المطبخ وظل يحملها طوال المساء، بل ويضعها في الفراش لتنام. من الصعب تفسير الأشياء التي تثير اهتمام عقل الطفل. لا تمنعيه، ودعيه يغمر تلك المغرفة بحبه.'),
  ('498b3498-4fee-4a00-9b62-ebe43844ae53', 'الجرّاح في طبق الحساء 🥣', 'لا يأكل طعامه، بل يكتفي بفصل قطع البصل الصغيرة أو حبات الأرز بدقة جرّاح. حان الوقت لهرس الخضراوات وجعلها غير مرئية. تصفّحي الوصفات الصحية، واكتشفي أكثر وصفات الأمهات إبداعًا لإخفاء الخضراوات.'),
  ('a13e9959-a476-4e99-9da8-13f5bff68864', 'أنا سأفتح الخزانة! 🚪', 'هل بكى هذا الصباح لأنكِ فتحتِ باب الخزانة، وأجبركِ على إغلاقه مجددًا كي يفتحه بنفسه؟ نعم، يجب أن تكون السيطرة كاملة بيده. ابتسمي لمحاولاته البريئة التي يقول فيها «سأفعلها بنفسي»، فهو يختبر إرادته.'),
  ('0a4a5638-968e-4cce-9213-12c0072354c4', 'المقياس الرقمي للصمت 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي خيّم على المنزل. فعّلي أداة قياس الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واشعري بذهنك يستريح ويستعيد طاقته تدريجيًا.'),
  ('b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a', 'صفعة «أنتِ أم سيئة!» 💔', 'هل قال لكِ «أنتِ سيئة» لأنكِ لم تعطيه الحلوى التي يريدها؟ لا تدعي ذلك يحطم قلبكِ. فهو لا يزال غير قادر على التعبير عن مشاعره بالكلمات المناسبة، وما يريد قوله في الحقيقة هو: «أنا غاضب جدًا». انظري في عينيه وتقبّلي شعوره.'),
  ('94fce04c-73e9-47bd-8d9d-3bd3da19122a', 'سأمشي وحدي! 🚶‍♂️', 'يرفض بشدة أن تمسكي بيده في الشارع، ويعلن استقلاله. امنحيه هذه الحرية في الأماكن الآمنة، وأبقي عينيكِ عليه ودعيه يكتشف العالم بخطواته الخاصة.'),
  ('b24a452c-9588-4b0c-923f-9c455be6d1e2', 'طاهي المطبخ الصغير 🧑‍🍳', 'هل يصرّ على وضع كرسي بجانبكِ والمشاركة بينما تفردين العجين؟ أعطيه قطعة صغيرة من العجين. سيمتلئ المكان بالدقيق، لكن ملامح وجهه الجادة والمنهمكة تستحق كل هذا التنظيف.'),
  ('09711673-d0fa-42b5-be98-012bd4b1ed8b', 'صعوبة الاستراحة من الشاشات 📺', 'هل سمحتِ له اليوم بمشاهدة المزيد من الرسوم المتحركة بسبب انشغالكِ، ثم شعرتِ بالذنب؟ لا تلومي نفسكِ. لا يمكنكِ أن تكوني أمًا مثالية كل يوم. أحيانًا تنقذكِ جليسة الأطفال الرقمية من الانهيار النفسي.'),
  ('8649e4ca-170c-4117-8af8-b0d7e819e84f', 'مسجّل صوت حيّ 🎙️', 'ها هو يقول للعبته هذا الصباح كلمة عابرة استخدمتِها أمس أثناء حديثكِ مع شريككِ! تتسع حصيلته اللغوية بسرعة مذهلة، وهو يقلّدكِ تمامًا. لا تنسي أنكِ قدوته.'),
  ('c0faa467-b596-4471-bbba-6d91e0e37db1', 'حيلة الهمس 🤫', 'يكون نشيطًا جدًا في السرير لدرجة أنه لا ينام. بدلًا من رفع صوتكِ، اخفضيه فجأة وتحدثي همسًا. عندما يركّز طفلكِ ليسمعكِ، ينتقل دماغه تلقائيًا إلى وضع النوم.'),
  ('48263ed0-f236-440c-a83e-807da51bd86f', 'الحاجة إلى الأكسجين ⛅', 'لقد أرهقتكِ الجدران الأربعة، وبدأت نوبات الغضب تندلع في المنزل. راقبي الطقس واختاري الملابس الأنسب. الخروج والركض فحسب سيساعدانه على تفريغ طاقته، ويمنحكِ أنتِ أيضًا نفسًا جديدًا.'),
  ('8fed0a18-52ae-4688-8137-532b6b55726c', 'هو من يدير الحكاية 🪄', 'لقد مللتما كلاكما من الكتب الكلاسيكية. افتحي الحكايات الذكية، واجعلي طفلكِ بطلها الرئيسي وغرفته المكان الذي يجب إنقاذه، لتصنعي جلسة نوم غير تقليدية وهادئة ومريحة.'),
  ('c7c388a1-a255-4a7c-a615-22236406e4e2', 'إبداع طليعي 🖍️', 'انتهت بضع ثوانٍ من الصمت بمفاجأة مقلقة. دخلتِ الغرفة فوجدتِه قد رسم لنفسه وشومًا بأقلام التلوين على ذراعيه أو بطنه. خذي نفسًا عميقًا؛ فمهاراته الحركية الدقيقة تتطور، والحبر سيزول عن بشرته بالغسل على أي حال.'),
  ('1bbd92c6-a12a-4c26-a63f-0946e226b656', 'ممنوع أن تنسي نفسكِ! 🥗', 'فكرتِ في 3 قوائم طعام مختلفة لإشباع طفلكِ، لكنكِ بقيتِ جائعة من جديد؟ اختاري من بين الوصفات الصحية وجبة غداء غنية بالحديد والكالسيوم يمكن تحضيرها في 10 دقائق، وامنحي نفسكِ ما تستحقينه من اهتمام.'),
  ('31e8c246-42c7-4bad-8ff1-c08af53874b1', 'نوبة غضب مفاجئة 💥', 'هل غضب فجأة أثناء اللعب وبدأ يقذف ألعابه؟ لا يزال غير قادر على التحكم في مشاعره. بدلًا من الصراخ، تعاطفي معه وقولي: «أرى أنك غاضب، تعالَ نتنفس بعمق معًا».'),
  ('96327d67-c216-46e6-b768-6cd8fce23852', 'نخب الزوجين 🥂', 'نام الطفل. حتى إن لم تتوفر الشمبانيا، اسكبا الشاي الساخن في الكؤوس، وتبادلا النخب قائلين: «لقد اجتزنا هذا اليوم الصعب أيضًا بسلام». أنتما أقوى قائدين في المنزل.'),
  ('3b764723-4ccb-4ab8-a1ed-3b072c5f8a25', 'بقيت 5 أيام على بلوغه 3 سنوات! 🚀', 'لا يُصدق! لم يتبقَّ سوى 5 أيام على بلوغه سن 3 سنوات. أنتِ من ربّيتِ هذا الصغير المستقل الذي يضع قواعده الخاصة داخل المنزل. اطلبي الكعكة الآن من Anacan وابدئي الاستعدادات.'),
  ('b8850dac-f142-4e24-bc24-56bb7962ebf6', 'وضع الطيران مع الأب ✈️', 'لم يتمكن من تفريغ طاقته في المنزل، ويرفض الذهاب إلى الفراش. اطلبي مساعدة والده. عندما يرفعه في الهواء ويحوله إلى طائرة، تملأ الضحكات الغرفة ويختفي التوتر الجسدي خلال ثوانٍ.'),
  ('ee7e813c-5a12-4710-b655-7b294f1ff478', 'استراحة الأم ☕', 'لقد تعبتِ من التحدث بلغة الأطفال. ابحثي ضمن الأماكن الصديقة للأمهات عن مقهى يضم ركنًا للأطفال، واستمتعي بقهوتكِ وتبادلي الحديث مع أمهات أخريات لتلتقطي أنفاسكِ.'),
  ('20794d75-b46f-481d-baa5-2b85b8516d4e', 'الحرية في الحديقة 🌳', 'البقاء بين أربعة جدران يجعله عدوانيًا. اصطحبيه إلى الحديقة، ودعيه يتغطى بالرمال، ويسقط وهو يركض، ويجمع الحجارة. هذه الحرية في الطبيعة هي أفضل محفز لنمو دماغه.'),
  ('3d4fe78e-9d18-4fa4-b11f-ee7836615ee7', 'مصنع الميلاتونين 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية في الغرفة وشاشات الأجهزة اللوحية. لا يُفرز الميلاتونين بسرعة إلا في بيئة هادئة وخافتة الإضاءة وخالية من الشاشات.'),
  ('a09d0a7b-0632-4bcf-8833-28f5ef0f9d93', 'بكاء تمثيلي 🎭', 'هل يتظاهر بالبكاء بصوت مرتجف، من دون دموع، ليحصل على ما يريده؟ إنه يتعلم كيف يتلاعب بكِ. تماسكي كي لا تضحكي، لكن لا تتنازلي أيضًا. ضعي حدودًا واضحة.'),
  ('20e8cb8e-6d52-4362-bb7b-a45ecbfa2cce', '«أحبكِ» مفاجئة 💖', 'هل نظر إليكِ فجأة وهو يلعب في وسط الغرفة وقال: «أحبكِ كثيييرًا»؟ إنها لحظة تستحق كل الليالي التي قضيتِها بلا نوم وكل التعب! استمتعي بذلك السلام العميق والفريد الذي تحمله هذه اللحظة.'),
  ('22b5d836-6305-422c-8cf7-c30a523392f2', 'رقصة الأب المجنونة 🕺', 'لا أحد يستطيع احتواء نوبة الغضب المسائية مثل الأب. دعيهما يرفعان صوت الموسيقى إلى أقصى حد ويرقصان معًا وهما يقفزان في الغرفة. أما أنتِ، فشاهدي هذه الطاقة المرحة من بعيد بكل فخر.'),
  ('909bc50f-85b7-40ab-a524-0abbcb0fac9f', '10 دقائق لكِ وحدكِ ☕', 'بينما ينشغل بذلك الفيلم الكرتوني، لا تهرعي إلى ترتيب غسالة الصحون! تمددي على الأريكة. اشربي قهوتكِ أخيرًا وهي ساخنة، وتخلي عن دور الأم لمدة 10 دقائق لتكوني نفسكِ فحسب.'),
  ('028ed2b5-737d-4edf-81c1-5a9151e5fbf0', 'مفاجأة الشوكولاتة في المتجر 🛒', 'فتحتِ قائمة التسوق قبل الذهاب إلى المتجر، ثم رأيتِه يأتي من خلفكِ ويضغط على شاشة الهاتف ليضيف إليها بعض الخربشات. نعم، إنه يقلّد حياتكِ الرقمية أيضًا!'),
  ('098cd94b-6989-48a8-9fdc-160a2f819cb0', 'متعة القواعد المبتكرة 🗣️', 'لقد ابتكر صيغًا زمنية غريبة ولطيفة جدًا، مثل «أنا ذهبتُتُ» و«هو كان يأتي سابقًا». تتطور حصيلته اللغوية بسرعة مذهلة! دوّني هذه اللغة الخاصة التي ابتكرها في متتبّع النمو لتبقى ذكرى محفوظة.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('50dce5d9-294a-44b8-b1c9-316b84d5df14'::uuid, 'ماذا يوجد تحت السرير؟ 👻', 'هل يعتقد أن الوحوش تختبئ في الظلام؟ خذي زجاجة مملوءة بالماء فقط، ورشّي منها في الغرفة باعتبارها «رذاذًا طاردًا للخوف» كي يطمئن. واجهي الخيال بالخيال.'),
  ('2cd29d0d-0cf1-403e-806d-35f84215b2df', 'بدأت الحفلة في الساعة 5 صباحًا! ⏰', 'لم تشرق الشمس بعد، لكنه بدأ يومه بالقفز على السرير. قد تكونين ما زلتِ ناعسة، لكنه مستعد لغزو العالم. انضمي إليه ودعي هذه الطاقة المجنونة توقظكِ أنتِ أيضًا.'),
  ('5e21d0fb-8027-46a5-b7ea-7b3a58d0cd11', 'وصل الضيوف الخياليون ☕', 'هل يتحدث طفلكِ بمفرده في الغرفة مع أصدقائه غير المرئيين ويصبّ لهم الشاي؟ هذه ذروة تطور الخيال! راقبي من بعيد كاتب السيناريو المبدع هذا بكل فخر، فهو يصنع عالَمًا كاملًا بالفعل.'),
  ('19c93357-3662-4a7d-bd13-a71d938dc00a', 'دعيني أشرح لكِ! ☝️', 'يأتي إليكِ ليشرح لكِ شيئًا تعرفينه أصلًا، بتعبير جاد وذكي للغاية على وجهه. إنه يختبر معرفته. حتى لو اضطررتِ إلى تمالك نفسكِ كي لا تضحكي، فاستمعي إليه بكل جدية.'),
  ('6ab81ee1-daa9-4300-97cb-c7dad69d9baf', 'بوح في يوميات المزاج 📝', 'أمسكي هاتفكِ. بدلًا من تصفح حياة الآخرين على شبكات التواصل الاجتماعي، افتحي يوميات المزاج وسجّلي أطرف موقف قام به اليوم لتحتفظي به للمستقبل. فالعلاج الرقمي مفيد بالفعل.'),
  ('ee467fcc-7c51-4e6a-ba68-1e6466be7d10', 'تمرّد على القيلولة 🥱', 'هل يرفض الذهاب إلى السرير تمامًا؟ هذه المقاومة شائعة جدًا مع اقتراب سن 3 سنوات. لا تجبريه ولا تتركيه يبكي. خفّفي الإضاءة في الغرفة وغيّري الروتين بإعلان وقت هادئ لتصفّح الكتب.'),
  ('3a35865f-054d-413c-b3ad-81c68c171c47', 'قلق الانفصال مجددًا؟ 🥺', 'هل يبكي خلفكِ حتى عندما تغادرين الغرفة لثوانٍ؟ قد يعود قلق الانفصال أحيانًا مع اقتراب سن 3 سنوات. طمئنيه من بعيد في كل مرة بصوتكِ، وقولي له إنكِ موجودة: «أنا في المطبخ، سأعود حالًا».'),
  ('96b4e611-59a4-4d8b-a157-87f9d477e265', 'تأكيد الهدوء 🤫', 'بعد يوم صاخب، وعندما ينام طفلكِ، قيسي هدوء الغرفة باستخدام جهاز قياس الصوت. فحتى رؤية الأرقام تقترب من الصفر تمنح دماغ الأم أفضل تدليك بصري.'),
  ('c1d1539d-38e2-40da-9e66-eb22e0cbbd09', 'ضغط المثالية 🛑', 'هل بدأ أطفال آخرون بالفعل في تعداد الألوان، بينما لا يرغب طفلكِ في ذلك؟ توقفي عن المقارنة فورًا! لكل طفل وتيرته الخاصة في النمو. يتقدم طفلكِ وفق إيقاعه الخاص، وهذا طبيعي تمامًا.'),
  ('08d5ac7d-b540-46e7-9f43-7f771edfd887', 'الاستعداد للانتصار 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي مع شريككِ تدليك الكتفين للتخلص من ضغوط اليوم. يجب أن تكونا مفعمين بالطاقة للاحتفال غدًا بعيد ميلاده 3 وما يصاحبه من ركض وانشغال!'),
  ('2d61ffa4-9df3-4b29-acca-6b87ebc82745', 'مجموعة دعم الأمهات 💬', 'هل تمرّين بيوم صعب وتشعرين أن كل شيء يفوق طاقتكِ؟ ستجدين في مجتمع Anacan نصائح واقعية من أمهات ذوات خبرة، وحلولًا مستمدة من الحياة لن تجديها في أي كتاب. استلهمي منهنّ.'),
  ('dd4c2432-4936-49e7-844c-aec9116027b4', 'على أعتاب عامه الثالث! 🎂', 'غدًا يوم عظيم! لقد قطعتما معًا رحلة طويلة منذ ذلك اليوم الذي شعرتِ فيه بركلته الأولى في بطنكِ. تأمّليه طويلًا اليوم، واختاري ملابسه، وأفرغي مساحة في ذاكرة هاتفكِ لجلسة تصوير طفلكِ غدًا.'),
  ('36c78cd2-37d5-4665-84a1-551e9c9c2557', 'احتفلي مع شريككِ 🥂', 'احتفلي هذا المساء مع شريككِ بما حملته الأعوام الثلاثة من تعب ودموع وفرح. أشعلا شمعة على المائدة، وصفّقا بابتسامة وفرح كبير لانتصار فريقكما المتماسك!'),
  ('6148534d-dac4-4ca6-9b42-87f0242f8cdb', 'ثلاثة أعوام رائعة! 👑🎉', 'تهانينا! لقد بلغ طفلكِ الثالثة! مرّ 1095 يومًا وأنتِ تخوضين هذه الرحلة الحافلة بالتحديات والمتعبة، لكنها الأجمل في العالم! احتفلي بهذا اليوم المميز فورًا وشاركي فرحتكِ مع الجميع!'),
  ('94dba968-6bd5-4b01-b8ef-b33b80729320', 'أنتِ رائعة! 📈', 'كم قطع طفلكِ من شوط طويل! لقد تحوّل ذلك الخوف المرهف في الأيام الأولى إلى ثقة وخبرة كبيرتين. اجتزتِ هذه الأعوام الثلاثة بكل فخر! أنتِ حقًا أم رائعة!'),
  ('278a6dcf-b4d5-435f-bebd-984362b1ec54', 'العودة إلى الواقع بعد الاحتفال 🚀', 'بعد احتفال الأمس الكبير، استيقظتِ هذا الصباح مجددًا على الألعاب المبعثرة وعبارات «لا أريد أن أرتدي ملابسي!». عادت الحياة إلى إيقاعها المعتاد. خذي نفسًا عميقًا، فأنتِ أفضل من يدير هذه الفوضى.'),
  ('5242afc1-567f-496d-81cf-522c0271690e', 'دعيه يتحكّم في الحكاية 🪄', 'لقد سئمتما كلاكما من الكتب التقليدية. افتحي الحكايات الذكية، واجعلي طفلكِ بطلها الرئيسي وغرفته المكان الذي ينبغي إنقاذه، لتصنعي جلسة نوم مميزة وهادئة ومريحة.'),
  ('d5e65c0a-6f82-4fee-945e-ee1f72e84c4a', 'إصرار «سأفعلها بنفسي» 🛑', 'هل يريد ربط حذائه بنفسه ويستغرق ذلك 10 دقائق من وقتكِ؟ لا تتعجّلي، بل امنحيه الوقت. فمحاولاته وأخطاؤه هي أساس قدرته المستقبلية على حل المشكلات.'),
  ('48550c10-c030-428e-9c25-ccd73ca09c55', 'تبحثين عن روضة أطفال؟ 🏫', 'مع اقتراب طفلكِ من سن ٣ سنوات، هل تراودكِ فكرة إلحاقه بروضة أطفال، لكنكِ لا تستطيعين اتخاذ القرار؟ إذا سئمتِ التفكير وحدكِ، فانضمي إلى مجتمع Anacan واقرئي تجارب الأمهات الحقيقية مع رياض الأطفال.'),
  ('df1cf1ea-2772-44a6-8cb7-33857989fedf', 'تدوين المشاعر 📝', 'هل قال لكِ أحدهم: أنتِ في المنزل، فممَّ تتعبين؟ افتحي فورًا مفكرة المزاج، وأفرغي كل غضبكِ على الشاشة بأصابعكِ. تدوين مشاعركِ الحقيقية علاج، وهو أفضل من التظاهر بالابتسام.'),
  ('3deb7e49-2093-4c39-a51d-8dd6fd44d138', 'العداء للخضراوات مستمر 🥦', 'هل لمح مجددًا قطعة الجزر الصغيرة في الحساء ورفض تناوله؟ استعيني بخطة التغذية لهرس الخضراوات وإخفائها في أقراص اللحم؛ فهي إحدى أقدم حيل الأمهات وأكثرها فائدة. جرّبيها!'),
  ('9dd6923c-7dc5-4341-8507-b21e0f3c9ee4', 'الطبيب الصغير يفحصكِ 🩺', 'يأخذ سماعته الطبية اللعبة، ويضعها على صدركِ ويطلب منكِ أن تتنفسي. أنتِ المريضة، وهو كبير الأطباء. شاركيه هذه اللعبة، واستلقي وأغمضي عينيكِ واسترخي أثناء العلاج، ولو لخمس دقائق فقط.'),
  ('ebf71c8a-d8a3-4875-8021-e3145bf8ae06', 'الحد الأقصى للأصوات 🌙', 'لقد نام أخيرًا. والآن يزعجكِ حتى أخف صوت في المنزل. خفّفي الإضاءة، وأطفئي التلفاز، واستمتعي في قلب الظلام بحلاوة ذلك الهدوء النادر.'),
  ('19419b9a-b627-43ae-9610-e43b875264b1', 'الزحف والركض نحو هدف 🐢', 'لم يعد المشي وحده يكفيه؛ بل يركض بسرعة ويختبئ منكِ ويطلّ من خلف الأبواب. أزيلي العوائق من الغرفة، وانضمي إلى لعبة المطاردة هذه بطاقة طفل كبير.'),
  ('20d0afb1-a487-43f5-b6f3-0f8cd2bca864', 'أطفئي الأنوار ليأتي النوم 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية والشاشات ذات الضوء الأزرق في الغرفة. لا يُفرَز هرمون النوم (الميلاتونين) بسرعة إلا في بيئة مظلمة وخالية من الأجهزة التقنية.'),
  ('c8f7bf43-25ab-4e4d-96d4-6f6b9ab81f33', 'ذكاء اصطناعي، إجابة حقيقية 🤖', 'هل ظهرت لدى طفلكِ عادة غريبة، مثل قضم الأظافر، وأخافتكِ المنتديات على الإنترنت؟ توقفي. اسألي Anacan AI عن سببها الحقيقي المعتمد من أطباء الأطفال واطمئني.'),
  ('58d0ef6e-2eed-490f-85f9-8fd8f899a9bd', 'التصالح مع فوضى المنزل 🌪️', 'هل تنتشر الألعاب في كل أرجاء الغرفة؟ ما يهم ليس التنظيف، بل تلك اللحظات المرحة التي تقضينها مع طفلكِ. ستبقى الألعاب مكانها غدًا أيضًا، فلا ترهقي نفسكِ. أحيانًا يكون الاستسلام للفوضى أفضل وسيلة للراحة.'),
  ('d52a333c-1a4b-40fd-a11c-b3544628c6df', 'حيلة الأب السرية 👨‍🍼', 'يكفيكِ ما تشعرين به من إرهاق خلال النهار. في المساء، اتركي للأب مهمة تهيئة طفلكِ للنوم وتشجيعه على تنظيف أسنانه بأسلوبه المرح، واستمتعي أنتِ ببعض الراحة والهدوء.'),
  ('dbff772c-4b84-4bcd-8132-9e03a5a6d600', 'صديق مقرّب غير مألوف 🥄', 'مع وجود كل تلك الألعاب الباهظة، هل ذهب طفلكِ إلى المطبخ ووجد ملعقة مسطحة من السيليكون، ثم أخذ يتجول بها طوال اليوم ويضعها في الفراش؟ عقل الطفل مذهل! لا تمنعيه، ودعيه يحب ملعقته.'),
  ('5e23814c-ef4e-4708-8223-e1ab2ac7daa9', 'النوم على صوت الهمس 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واحكي له بصوت خافت جدًا، همسًا في أذنه، عما حدث خلال اليوم. الهمس من أكثر الوسائل الطبيعية والفعالة لتهيئة الدماغ للنوم وحجب الضوضاء.'),
  ('e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c', 'مفاجأة في القائمة 🛒', 'فتحتِ قائمة التسوق قبل الذهاب إلى المتجر، وفجأة جاء طفلكِ من خلفكِ وضغط على شاشة الهاتف لتكتشفي أنه أضاف الشوكولاتة إلى القائمة. نعم، إنهم يفهمون التكنولوجيا أفضل منكِ!'),
  ('fc07a24b-5d02-4f37-9d95-b46ab5b5f190', 'هدم هادف 🧱', 'يبني برجًا بجهد كبير، ثم يهدمه بضربة واحدة وهو يضحك. إنه يتعلم مبادئ الفيزياء والعلاقة بين السبب والنتيجة. لا تنزعجي، فكل برج يهدمه يصنع روابط عصبية جديدة في دماغه.'),
  ('aa798243-c44e-4178-957c-647030916048', 'تنبيه بشأن الطقس ⛅', 'عندما تخرجين للتنزه، لا تدعي المنظر من النافذة يخدعكِ. استعيني بمساعد الطقس والملابس لاختيار الإطلالة الأنسب للرياح ودرجة الحرارة الفعلية في الخارج، واخرجي من المنزل مطمئنة ومستعدة تمامًا.'),
  ('b3ff48b4-aa5c-406e-999b-73655dca1c90', 'ناقد الرسوم المتحركة 📺', 'يروي لكِ أحداث الرسوم المتحركة التي شاهدها بقواعده اللغوية الخاصة، ويشرح بجدية من ذهب وإلى أين. أنصتي إليه باهتمام وتظاهري بالدهشة، ودعيه يشعر بأنه أذكى شخص في العالم.'),
  ('c83099cc-b126-47d8-b334-d8faf9b45dde', 'قوة الظلام 🌙', 'لتساعدي طفلكِ على النوم بسرعة، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة. يُفرَز الميلاتونين بسرعة فقط في بيئة مظلمة وخالية من الأجهزة الإلكترونية.'),
  ('9f30d9e0-ccc5-4b30-b84e-6fc58af9aa3b', 'ذوّاقة انتقائيون 🥦', 'هل يرفض اليوم طعامًا كان يحبه بالأمس؟ التقلبات الغذائية في سن ٣ سنوات طبيعية. اختاري من الوصفات الصحية أطباقًا ملوّنة ومبتكرة بطريقة تقديم مرحة تجذب اهتمامه.'),
  ('b755d54c-d2cb-47a2-92bb-44a36d855874', 'الخيال يحلّق 🚀', 'لم يعد يلعب فحسب، بل يبتكر سيناريوهات أيضًا! ففي لحظة، يتحول صندوق من الورق المقوّى إلى مركبة فضائية. سجّلي بفخر هذه القفزة المعرفية في متتبّع النمو، وشاركيه اللعب.'),
  ('ef6fe3c1-b830-477f-93ee-842f8b450ab9', 'ملخّص اليوم 🌙', 'خفّفي الإضاءة قبل النوم، وتحدثا عمّا أضحككما أكثر شيء اليوم. هذه الأحاديث القصيرة قبل النوم تصقل قدرته على التعبير.'),
  ('00481a1e-da97-4621-84c5-0bde2c4df340', 'المُطارِد الخفي 👻', 'هل بدأ يبكي خوفًا من ظلّه على الحائط؟ مواجهة الظلال من أطرف المواقف الشائعة في سن ٣ سنوات. أطفئي الأضواء، وشغّلي مصباحًا يدويًا، واجعلي الظلال ترقص لتحوّلي هذا الخوف إلى طقس نوم ممتع.'),
  ('81f8ee8c-8ca4-4260-b2ea-e74f425fe201', 'خيمة من كومة الملابس ⛺', 'هل بعثر كومة الملابس النظيفة التي انتهيتِ للتو من طيّها وبنى لنفسه خيمة؟ قبل أن تغضبي، ألقي نظرة داخل تلك الخيمة. فعالم الخيال وفرحة طفلكِ هناك أثمن من جهدكِ في طيّ الملابس.'),
  ('c4bb77ab-6874-45a4-8118-c089a7246538', 'أزمة بطاقة الملابس 🏷️', 'إنها تحكّ رقبتي! تلك البطاقة الصغيرة خلف القميص هي العدو الأكبر هذا الصباح. تبلغ الحساسية الحسية ذروتها في سن ٣ سنوات. لا تجادليه، بل اقطعي البطاقة ببساطة، وامنحي اليوم فرصة ليبدأ بسلام.'),
  ('04cb5d8f-0591-4ccc-8e31-0cf6555eb83a', 'سفن تغرق في حوض الاستحمام 🛀', 'دخلتما الحمّام للعب بالماء، وها هو يحاول إغراق الألعاب التي تطفو على سطحه. إنه يكتشف الفيزياء! دعي الماء يتناثر في كل مكان؛ فطاقته ستأخذ معها أيضًا عناد طفلكِ المتراكم طوال اليوم.'),
  ('123c0368-cc37-47f7-bb36-f227dd4d9131', 'حيوان أليف خيالي 🐕', 'هل يداعب كلبًا أو قطة غير موجودة في الغرفة ويمنحها اسمًا؟ لقد تجاوز خياله الحدود المادية بالفعل. ضعي وعاء ماء غير مرئي في إحدى زوايا الغرفة، وشاركيه هذا الوهم اللطيف.'),
  ('ecca6ba2-c00d-4fde-a20b-1268d23c90e0', 'وليمة في قالب الثلج 🧊', 'مهما فعلتِ، لا يأكل تلك الخضراوات؟ غيّري طريقة تقديمها تمامًا. وزّعي الوجبات الخفيفة المفيدة على الخانات الصغيرة في قالب مكعبات الثلج (ice cube tray). فالتقديم غير المعتاد يفتح الشهية دائمًا.'),
  ('56159a04-f4fe-4e35-a3dd-8bcc4853f3c9', 'وضع الطيران مع الأب ✈️', 'يركض في المنزل ويرفض الذهاب إلى السرير. اطلبي مساعدة الأب. فعندما يرفعه في الهواء ويلعب معه لعبة الطائرة، تملأ الضحكات الغرفة، وتتبدد كل طاقته الجسدية المكبوتة خلال ثوانٍ مع التعرق.'),
  ('69ac9098-fc9c-4474-aa9d-090c0c3f7cdf', 'إخراج مسرحي في السادسة صباحًا 🎬', 'لا تزالين نائمة، لكنه يقف عند رأسكِ قائلًا: أنتِ الدب، وأنا الأرنب! أدّي دوركِ في هذا المسرح العبثي وأنتِ نصف نائمة، وأصدري أصوات القضم. فالأمومة تتطلب أحيانًا أفضل مهارات التمثيل.'),
  ('aa6e4c45-6848-4e91-8836-f55617de9313', 'فضفضة المجتمع 💬', 'أنتِ متعبة جدًا ولا ترغبين في شرح أي شيء لأحد. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية أمهات أخريات يعانين من إرهاق مشابه تمنحكِ شعور «لستُ وحدي»، وقد تكون أفضل علاج.'),
  ('7b3c2751-f23f-4467-abdf-9463831a86cb', 'المتعة الرقمية للصمت 🤫', 'لقد نام أخيرًا! الصمت الذي خيّم على المنزل عميق لدرجة أن أذنيكِ تكادان تطنّان. فعّلي مقياس مستوى الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واستشعري بصريًا كيف يتعافى دماغكِ ببطء.'),
  ('7d093b24-909b-4f92-b3df-fe627f2322c0', '«أنا سأقود!» في المتجر 🛒', 'يصرّ على دفع عربة التسوق بنفسه، فتجدان نفسيكما تصطدمان بالرفوف. وحتى لا تحبطي إرادته، دعيه يدفع العربة معكِ. ولتجنب نسيان المشتريات، أبقي «قائمة التسوق» في التطبيق مفتوحة.'),
  ('803c4a83-8bb9-4a65-a6e0-a757e4e816cf', 'أكملي الجمل الناقصة 🗣️', 'عندما ينسى كلمة، هل يشير بيده وينتظر منكِ أن تخمّنيها؟ راقبي لحظة ارتياحه حين تقولين: آآه، هل تقصد الكرة؟ حصيلته اللغوية تكبر، لكن دماغه يعمل أسرع من لسانه فحسب.'),
  ('e7437e5e-38bf-45b1-8db0-74786f20b535', 'استراحة للزوجين 🥂', 'نام طفلكِ. الآن ضعي الهواتف والأعمال المنزلية جانبًا. اجلسي وجهًا لوجه مع زوجكِ وتحدثا لمدة 20 دقيقة فقط عن موضوع لا يتعلق بالفواتير أو الطفل. فأنتما أيضًا زوجان!'),
  ('3a4c5cc8-5f54-4aef-b016-9394a079ec83', 'كنوز الجيوب 🪨', 'هل وجدتِ في جيب سرواله أثناء غسله 3 أحجار بأحجام مختلفة وقشرة كستناء؟ بالنسبة إليه، هذه أثمن مجموعة في العالم. بدلًا من رميها، اجمعيها في علبة صغيرة واصنعي له صندوق كنوز.'),
  ('68c1a1ff-c119-4521-aae1-9a7a984caad7', 'أطفئي الأنوار ليأتي النوم 🌙', 'لمساعدته على النوم بسرعة، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بساعة واحدة. يُفرَز الميلاتونين (هرمون النوم) بسرعة في بيئة مظلمة وخالية من الأجهزة التكنولوجية.'),
  ('9021ef15-5cf5-4f9d-8592-aab7e32c65a0', 'الشعور بالاحتراق النفسي 🔋', 'هل تشعرين برغبة في الصراخ بسبب كل شيء؟ هل تخترق الضوضاء رأسكِ؟ هذا احتراق نفسي بكل معنى الكلمة. ضعيه فورًا في مكان آمن (أو اتركيه مع والده)، ثم انتقلي إلى غرفة أخرى واكتبي كل ما يثقل كاهلكِ في يوميات المزاج من دون تنقيح.'),
  ('a5815a11-4b6f-4f3d-a6ff-4d587c286a65', 'استيقاظ على أنغام الموسيقى 🎶', 'لم تشرق الشمس بالكامل بعد، لكنه يقفز على السرير ويُصدر أصواتًا إيقاعية. إنه أعلى منبّه في العالم صوتًا، لكنه أيضًا ألطفها! ابدئي يومكِ بابتسامة أمام طاقته التي لا تنضب.'),
  ('afb9fd4f-60e2-4547-87e2-d867963a1345', 'تدوين المشاعر 📝', 'بعد أن ينام طفلكِ، افتحي يوميات المزاج. دوّني للمستقبل أكثر موقف طريف وعبثي فعله اليوم وأضحككِ بشدة. ستدمع عيناكِ حين تقرئينه بعد سنوات.'),
  ('db2d884d-1367-4ebc-a61b-9a450673d64d', 'تجربة ساعة الهدوء 🥱', 'لا يريد أخذ قيلولة رغم أن النعاس يملأ عينيه؟ إنها مقاومة كلاسيكية في سن 3 سنوات. لا تجبريه؛ خففي الإضاءة في الغرفة وأعلني عن ساعة هادئة لتصفّح الكتب، وابدئي بذلك روتينًا جديدًا.'),
  ('0f647bd8-9749-4a55-969b-bfc85ddb7152', 'سلاح الأب السري 🤡', 'عندما لا تعود محاولاتكِ مجدية، تنقذ الأصوات الغريبة والوجوه المضحكة التي يصنعها الأب الموقف فورًا. خلال نوبات الانهيار المسائية، مرّري إليه المهمة مباشرةً واسترخي وأنتِ تراقبين من بعيد.'),
  ('5407f02f-f40a-48e1-b4f8-80cd1fc9345c', 'ديكتاتور الصباح بدأ عمله 👑', 'لا تجلسي هناك، فدُبّي سيجلس! إنه من يدير مائدة الإفطار بأكملها. حافظي على التوازن من دون كسر إرادته بعنف، وقولي له: «حسنًا، ليجلس دُبّك هناك، وسأجلس أنا هنا».'),
  ('a1a50d57-7314-4042-848d-a89f6c8fc209', 'هروب إلى الطبيعة ⛅', 'البقاء بين أربعة جدران جعله وجعلكِ أكثر توترًا. تحققي من أداة الطقس والملابس، وانطلقي فورًا إلى الحديقة. فالركض في الهواء الطلق والشعور بالحرية يبددان حتى أشد نوبات غضب الطفل الدارج بسرعة مذهلة.'),
  ('e61af62b-257c-41ec-8846-9d470f2646d9', 'لحظات الليل الهادئة 🛀', 'قضى اليوم كله وهو يردد: «لا أريد». الحمام الدافئ ليس للنظافة فحسب، بل يساعد أيضًا على تهدئة جهازه العصبي المتوتر وإعادة توازنه. سيزيل صوت الماء ودفؤه كل ذلك العناد.'),
  ('8169372c-8d17-46fc-bfc3-eda3a929eaa6', 'نسيان التسوق 🛒', 'ذهبتِ إلى المتجر معتمدةً على ذاكرتكِ، ثم عدتِ وقد نسيتِ حفاضات طفلكِ؟ لا بأس، يحدث هذا أحيانًا. اعتادي تدوين كل احتياجاتكِ فورًا في قائمة التسوق، ودعي التطبيق يكون ذاكرتكِ الرقمية.'),
  ('a15765ea-b7ce-42a7-91ae-209256ee1beb', 'ماما، انظري إليّ! 👀', 'عندما تنظرين إلى هاتفكِ أو تنشغلين بعمل ما، يأتي فيضرب يدكِ أو يقف أمامكِ. ومن حقه تمامًا أن يرغب في اهتمامكِ الكامل. خمس دقائق فقط من اللعب مع تواصل بصري متواصل كفيلة بتهدئته.'),
  ('de1347cd-769b-44d4-8aff-75ce2b7d2f0c', 'تأكيد السكون 🤫', 'بعد يوم صاخب، وعندما ينام طفلكِ، قيسي هدوء الغرفة باستخدام مقياس الصوت. إن رؤية الأرقام تقترب من الصفر تمنح دماغ الأم إحساسًا بالراحة يشبه أجمل تدليك.'),
  ('0ff315d9-2ad1-4c8c-9187-ea4c26042a66', 'ما أسرع مرور الوقت!', 'لقد أصبح الآن شخصًا له قراراته الخاصة تمامًا. ستشعركِ شخصيته القوية هذه بفخر كبير في المستقبل. لن تتكرر هذه الأيام، فاحتضنيه بكل حب.'),
  ('e4430813-5ad7-446e-9502-6e658d83eddd', 'جرّاح الخضراوات 🥦', 'هل يُبعد الخضراوات الموجودة في الحساء جانبًا وكأنه يبحث عنها بالمجهر؟ لا تدخلي في صراع معه. اكتشفي في الوصفات الصحية طرقًا متنوعة ولذيذة لهرس الخضراوات وإخفائها في الصلصات.'),
  ('c30ee50d-9665-4368-af0d-6578c2cc302b', 'استمعي إلى جسدكِ 🩸', 'تشعرين بإرهاق غير مبرر ورغبة في البكاء؟ افتحي متتبع الدورة الشهرية. فجسدكِ يرسل إليكِ إشارات. أظهري التعاطف مع نفسكِ بتناول وجبة خفيفة غنية بالمغنيسيوم من الوصفات الصحية.'),
  ('c49b057e-0774-42da-aec0-ee5fcc238471', 'انتقائية الشهية 🍝', 'هل لا يأكل طفلكِ سوى 2-3 أطعمة يحبها؟ لا تقلقي. تحققي من التوازن الأسبوعي باستخدام أداة متابعة التغذية، وتجنبي الضغط عليه على مائدة الطعام.'),
  ('462a51f8-d8f0-4c41-8551-81fbd18e8c62', 'دعيه يبتكر نهاية الحكاية 🪄', 'لقد مللتِ أنتِ وطفلكِ من الكتب الكلاسيكية. افتحي الحكايات الذكية ودعيه يوجّه أحداث القصة هذا المساء. اسأليه: «إلى أين ستذهب السيارة الآن؟» ودعيه يستسلم للنوم مع النهاية الطريفة التي ابتكرها من خياله.'),
  ('a8ffc7b0-9821-4b11-9ed7-be3302b5f4fb', 'خرافات الأم المثالية 🛑', 'أطفال مواقع التواصل الاجتماعي يلقون الشعر بالفعل، بينما لا يزال طفلكِ يخلط بين الكلمات؟ توقفي عن المقارنة فورًا! لكل طفل مساره الخاص والمختلف في النمو. طفلكِ رائع كما هو، وينمو وفق وتيرته الخاصة.'),
  ('fca7853a-0c3e-4553-8c15-c32fa7564774', 'أولمبياد ارتداء الحذاء 👟', 'ارتدى الحذاء الأيمن في قدمه اليسرى ويرفض تمامًا خلعه؟ دعيه كما هو. فشعوره بالاستقلالية وفخره بأنه أنجز الأمر بنفسه أهم من ارتداء الحذاء بالطريقة الصحيحة. كما أن ذلك يضع أساس مهارات حل المشكلات مستقبلًا.'),
  ('344d14b0-cfc9-4ff3-af6f-44e0148ab198', 'مأساة القمامة المختفية 🗑️', 'يبحث طفلكِ باكيًا عن قصاصة الورق عديمة الفائدة التي رماها بنفسه ثم ألقيتِها أنتِ في القمامة! هذا بالضبط هو منطق سن 3 سنوات. وبما أنكِ لا تستطيعين استعادتها، فشتتي انتباهه فورًا بشيء أكثر بريقًا.'),
  ('be71bad2-041d-4cb4-a658-89cb36e8a738', 'وقت إعادة شحن الأم 🔋', 'يركّب الأحجية بمفرده ويلتزم الهدوء منذ 10 دقائق، بينما تريدين استغلال هذه اللحظة لترتيب المنزل. لا! استلقي على الأريكة. أنتِ أيضًا بحاجة إلى إعادة شحن طاقتكِ لتتمكني من مواصلة هذا الإيقاع حتى المساء.'),
  ('d2f93631-6ef4-4ba4-9cac-259dafd2fb22', 'التعوّد على الظلام 🌙', 'هل يشعر طفلكِ بالقلق عند إطفاء أنوار غرفة النوم؟ ضعي مصباحًا ليليًا صغيرًا بلون دافئ (أصفر أو برتقالي) في إحدى زوايا الغرفة. أما بقية الغرفة، فينبغي أن تظل مظلمة تمامًا لمساعدته على النوم العميق.'),
  ('5625eb93-64b3-45e9-9346-29a2c6af885f', 'التواصل مع الطبيعة ضروري 🌳', 'بين أربعة جدران، تتحول طاقته إلى سلوك عدواني. مهما كان الطقس، ألبسيه ملابس مناسبة وخذيه إلى الخارج حتمًا. فملامسة التراب وجمع أوراق الشجر يهدّئان جهازه العصبي على الفور.'),
  ('d33d70dc-19c8-4087-8ed8-270685911bfd', 'قوة الهمس الساحرة 🌙', 'لقد أُرهقت أحبالكِ الصوتية من قراءة الحكايات. أطفئي أضواء الغرفة تمامًا، ثم تمدّدي بجانبه واهمسي في أذنه بصوت خافت جدًا بما حدث خلال اليوم. الهمس من أكثر الوسائل تهدئةً لتهيئة الدماغ للنوم.'),
  ('e578603f-02ec-4734-b19f-2d0ca949a8e2', 'كائن مدهش 🎈', 'في هذه الرحلة الطويلة، هناك الكثير مما يثير الدهشة. مثلًا، أن يستخدم اليوم الكلمة التي تعلّمها بالأمس في جملة فلسفية! هذه الأيام لن تتكرر.'),
  ('0cdb7f22-d990-414a-b36e-54d6d47e1b4f', 'استراحة الشوكولاتة السرية 🍫', 'أيتها الأم التي تأكل الشوكولاتة سرًا بعيدًا عنه، مختبئة خلف خزانة المطبخ، ذلك الغلوكوز من حقكِ. لا تلومي نفسكِ! لا بد أن تستعيدي طاقتكِ لتتمكني من تحمّل كل تلك الطاقة المجنونة. خذي نفسًا وواصلي المضغ.'),
  ('62a2e4b7-b7ef-4d46-a134-22e1f4da5625', 'هو بطل الحكاية الذكية 🪄', 'هذا المساء، اجعلي اسم طفلكِ هو اسم بطل الحكاية مباشرةً ضمن الحكايات الذكية. واغرسي فيه القيم بطريقة غير مباشرة، بأن تحكي له كيف أن شخصية الحكاية لم تنظف أسنانها ثم ندمت على ذلك.'),
  ('ce8759a7-ff69-4b27-a788-668b48e71999', 'مهندس ورق الحمّام 🧻', 'بضع دقائق من الصمت... ثم تدخلين الغرفة لتجدي أن ورق الحمّام بأكمله قد فُكّ ونُشر في أنحاء المنزل! بدلًا من الغضب، اجمعي الأوراق واصنعا معًا رجل ثلج. تغلّبي على الفوضى بالإبداع.'),
  ('1f94fede-7afb-4d0a-8e39-07ab7d2da0c4', 'كوني أنتِ الطفلة، وسأكون أنا الأم 👩‍👧', 'بدأت لعبة تبادل الأدوار! إنه يأمركِ قائلًا: تعالي إلى هنا، وكلي طعامكِ. تقبّلي تجربته القيادية هذه بكل سرور، وأدّي دور طفلته من دون اعتراض.'),
  ('77330b1b-94b4-4438-9dd4-9ea117490b54', 'ذكاء اصطناعي، حل حقيقي 🤖', 'لماذا يبدأ طفل في عمر 3 سنوات فجأة بقضم أظافره؟ انسي المقالات المخيفة والصادمة على الإنترنت. اسألي Anacan AI عما إذا كان ذلك مجرد استجابة مؤقتة للتوتر، واحصلي على إجابة علمية.'),
  ('143f9431-42d8-41e6-9983-ce9dde347219', 'الملابس مغطاة بالبقع 🎨', 'هل تلطخت ملابس نومه بالطعام وملابسه بالألوان؟ لا ينبغي للأطفال أن يكبروا وهم نظيفون طوال الوقت، بل أن يتسخوا أثناء الاستكشاف. استخدمي المرايل المصنوعة من السيليكون، واتركي الباقي للغسالة.'),
  ('6aecb8fd-7228-4ba7-9f34-65a8f0cda801', 'تسلّق الأثاث 🧗‍♂️', 'هل يتشبث بالأريكة أو المقعد ويحاول التسلّق؟ إن توازنه وقوة عضلاته يتحسنان. حافظي على سلامته، لكن لا تمنعي محاولات هذا المتسلّق الصغير أو استكشافه لقوانين الفيزياء.'),
  ('0db41c26-c87d-4bd7-8650-e9fd07449904', 'فضفضة الأمهات 💬', 'هل ترهقكِ فكرة أن هذا الطفل لن يهدأ أبدًا؟ انضمي إلى مجتمع Anacan، وسترين أن كل طفل يمر بهذه النوبات العاصفة مع اقترابه من سن الثالثة، وحينها ستتنفسين الصعداء.'),
  ('448fd3b8-143f-4fee-a40b-1b20e42ebbba', 'واحد، اثنان، ثلاثة... عشرة! 🔢', 'هل يحاول عد أصابعه أو ألعابه؟ لقد بدأ ذكاؤه الرياضي بالظهور. لا تفوّتي هذه المحاولات الصغيرة التي تتطور بسرعة مذهلة.'),
  ('5a020277-4aac-4623-8f46-93168c2f54e5', 'مناوبة الأب الليلية 👨‍🍼', 'لا تتحمّلي وحدكِ تمامًا الاستيقاظ ليلًا ومهمة إعادة طفلكِ إلى النوم. أيقظي شريككِ أيضًا؛ فالعمل كفريق يعني تقاسم المسؤولية بالتساوي. الليلة، مهمة تنويم الطفل تقع بالكامل على عاتقه.'),
  ('026f00f3-6e56-4ac5-a91b-bd5bd82cd187', 'تجربة ساعة الهدوء 🥱', 'هل يرفض أخذ قيلولة بعد الظهر ويبكي؟ لا تجبريه. خفّفي الإضاءة في الغرفة، وأعلني عن ساعة هادئة لتصفّح الكتب، وابتكري روتينًا جديدًا يمنحكما الراحة.'),
  ('53b445aa-e1d7-4c46-9d5a-07132c91031c', 'خيالات الظلام 🌌', 'هل تتحول الأشياء في الغرفة إلى وحوش عندما تنطفئ الأنوار؟ شغّلي له صوت الرحم من قسم الضوضاء البيضاء، لتعيدي إليه ذلك الشعور الفطري الرائع بالأمان.'),
  ('f4eb03a9-f74f-423a-ab2a-59d54da2db98', 'البحث عن المنطق 🧩', 'لم تعد الألعاب البسيطة تجذبه، وأصبح يبتكر ألعابًا أكثر تعقيدًا. ابحثي في قسم المنتجات الموصى بها عن ألعاب تتحدى ذكاءه أكثر وتنمّي تفكيره المنطقي.'),
  ('135b57f3-06e7-4fc4-b590-bec1151ee33b', 'سحر الماء الدافئ 🛀', 'قضى اليوم كله وهو يقول: «لا أريد». الحمّام الدافئ ليس للنظافة فحسب، بل يساعد أيضًا على تهدئة جهازه العصبي المتوتر. سيغسل صوت الماء ودفؤه كل عناده ويبدّدانه.'),
  ('57cfce2e-d64c-49cb-9f8b-295055620f21', 'لغز الطبيعة 🍁', 'أجواء المنزل المملّة تضايقكما معًا. اذهبا إلى الحديقة وانطلقا في مهمة للعثور على أغرب حجر من حيث الشكل. فالطبيعة هي أكبر مختبر لطفلكِ، وستبدّد كل توتره.'),
  ('682b0a2a-83c6-46cb-a100-02da150309f7', 'تقليد الحيوانات 🐶', 'هل يكتفي بإصدار الأصوات، أم يحبو أيضًا كالكلب ويتمطّى كالقط؟ تندمج لغة الجسد والخيال لديه بطريقة مدهشة. انضمي إليه في هذه اللعبة على السجادة وتخلّصي من توتركِ أيضًا.'),
  ('01a8a883-66ea-4e90-9796-1cd4c7aa4386', 'وقت للأم بلا إنترنت ☕', 'عندما ينغمس طفلكِ في عالمه ويلعب، لا تسارعي فورًا إلى ترتيب المنزل. اسكبي لنفسكِ كوبًا من الشاي الساخن، وضعي هاتفكِ جانبًا، واجلسي لمدة 15 دقيقة فقط من دون التفكير في أي شيء.'),
  ('7fc36514-28e6-4738-b9f6-f0c9cd9fa57d', 'استراحة للزوجين 🥂', 'نام طفلكِ. ضعي الآن الأعمال المنزلية جانبًا. تحدّثي مع شريككِ لمدة 20 دقيقة على الأقل عن أي موضوع بعيدًا عن الطفل والمصاريف. فأنتما زوجان أيضًا!'),
  ('8b2d61db-8be9-4916-a184-f14d02885b17', 'آلة «ما هذا؟» ☝️', 'هل يشير إلى كل شيء بإصبعه ويسأل عن اسمه؟ إنه يريد منكِ أن تسمّي له الأشياء من حوله. هذه قفزة كبيرة في التواصل! حتى لو شعرتِ بالتعب، واصلي تكرار أسماء الأشياء له بصبر.'),
  ('6716e6c0-2c87-4096-9dc2-661b570d83da', 'جهاز التحكّم في الثلاجة 📺', 'ألا تجدين جهاز التحكّم بالتلفاز؟ ابحثي في الثلاجة أو خزانة الأحذية. إنه يكتشف العالم من خلال وضع الأشياء وفق منطقه الخاص الذي ابتكره. بدلًا من الانزعاج، تعاملي مع لعبة التحري العبثية هذه بروح مرحة.'),
  ('7e1b9939-5806-440f-9214-8ee42a76c83e', 'البحث عن جرح خيالي 🩹', 'بمجرد أن يستيقظ، يجد جرحًا غير مرئي في جسده ويطالبكِ بقلق بأن تضعي عليه لاصقًا طبيًا. هذا ليس ألمًا جسديًا، بل حاجة خالصة إلى الاهتمام والحنان. لا تجادليه؛ ضعي ذلك اللاصق الصغير وقبّلي موضعه، وبذلك تنقذين يومكِ.'),
  ('e44cdd54-2858-49fa-8fd7-06dc369d29b6', 'جلسة تدليك من الأب 💆‍♂️', 'لقد أمضيتِ وقتًا طويلًا واقفة اليوم، ويكاد ظهركِ يؤلمكِ بشدة من الركض خلف طفلكِ. ما إن ينام، اطلبي من زوجكِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ عماد المنزل، ولا بد لهذا العماد أن يستعيد قوته.'),
  ('9c8523f0-548b-4581-bde4-2a8295db3639', 'دعوة إلى الظلام 🌙', 'لتساعدي طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة. يُفرَز الميلاتونين بسرعة في بيئة مظلمة وخالية من الأجهزة الإلكترونية، مما يسهّل الاستغراق في النوم.'),
  ('b7c3f40e-e406-412b-86a2-1c33a12692d8', 'التفكير في الحضانة 🏫', 'هل تشعرين بأن طفلكِ أصبح بحاجة أكبر إلى التواصل الاجتماعي؟ وهل حان الوقت المناسب لإلحاقه بالحضانة؟ انضمي إلى مجتمع Anacan واقرئي تجارب الأمهات الحقيقية في التأقلم، لتسهّلي على نفسكِ اتخاذ القرار.'),
  ('d8d022ce-8e44-42aa-972f-aa293c4341c8', 'دعيني أساعدكِ! 🧽', 'هل يصرّ طفلكِ على وضع كرسي بجانبكِ واللعب بالماء في أثناء غسل الصحون؟ في الحقيقة، هو لا يريد المساعدة بقدر ما يريد أن يكون في قلب ما تفعلينه. أعطيه وعاءً بلاستيكيًا صغيرًا ودعيه يفركه بالصابون أيضًا.'),
  ('63dc600c-4255-41f7-8695-78dd689a1998', 'حكايات هامسة 🪄', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه واهمسي في أذنه بصوت خافت جدًا بقصة قصيرة من الحكايات الذكية. الهمس من أكثر الطرق الطبيعية والهادئة التي تهيئ الدماغ للنوم.'),
  ('76d2443b-1074-45cd-a82d-59ba223792bb', 'مسجّل صوت حيّ 🎙️', 'ها هو اليوم يردّد للعبته تلك العبارة العاطفية أو الغريبة التي قلتِها لصديقتكِ عبر الهاتف أمس! تتّسع حصيلته اللغوية بسرعة مذهلة، وهو يقلّدكِ. لذا عليكِ الآن الانتباه إلى كلماتكِ أكثر من أي وقت مضى.'),
  ('a624ef08-9c66-462b-82e4-a4aa90f5b17b', 'قدّري نفسكِ 🥗', 'حضّرتِ البيض له بـ4 طرق مختلفة كي يأكل، ولكن ماذا أكلتِ أنتِ؟ كافئي نفسكِ بطبق مميز من الوصفات الصحية، لا يستغرق تحضيره سوى 5 دقائق ويكون غنيًا بالحديد والكالسيوم.'),
  ('0f7458af-fb58-4fe6-9907-6a5b773bca96', 'الاستعانة بالضوضاء البيضاء 🤫', 'تزداد حساسية طفلكِ للأصوات في أثناء استغراقه في النوم. لتحييد الأصوات القادمة من النافذة، فعّلي صوت الخلفية في مقياس الصوت داخل الغرفة، لتوفّري له أجواءً هادئة ومستقرة.'),
  ('ce6bc378-f040-49dc-a292-ef6ffa4a4247', 'متلازمة الجوع المفاجئ 🥱', 'ما إن يدخل طفلكِ إلى السرير حتى يقول: «ماما، أنا جائع»، ويريد الركض إلى المطبخ. إنها حيلة بارعة لتأخير النوم! أدرجي في خطة التغذية وجبة خفيفة صغيرة تساعد على النوم في المساء، مثل الموز، لتتجنبي هذه الحجة مسبقًا.'),
  ('7a0aa78e-7c5e-4ec5-9361-dc21cc74b32f', 'قلق الصمت 🤫', 'يتصفح الصور بمفرده في الغرفة، ويخيّم على المنزل صمت عميق. أما أنتِ، فيثير هذا الهدوء شكوككِ وتنتظرين وقوع كارثة في أي لحظة. اطمئني، فهم يرغبون أحيانًا في البقاء بمفردهم أيضًا. استرخي واستمتعي بهذه اللحظة النادرة بعيدًا عن الشاشات.'),
  ('7dcdfa61-d4a7-4888-bf22-0453312c6bae', 'أفكار بصوت عالٍ 💭', 'يستلقي في السرير ويروي لنفسه بصوت عالٍ ما حدث خلال يومه. فهذه طريقته في معالجة المعلومات والذكريات. افتحي متتبّع النمو، وسجّلي بفخر مدى تطور قدرته على سرد القصص بعفوية.'),
  ('dcfa33ac-90f3-4b1d-b8de-e6f8c966ff39', 'خطوط السجادة 📏', 'يحاول المشي من دون أن يدوس على خطوط السجادة، ويطلب منكِ أن تفعلي الشيء نفسه. هنا تتكامل المهارات الحركية الكبرى مع تنسيق الانتباه بشكل رائع. لا تفسدي اللعبة؛ شاركيه بضع خطوات واقفزي معه فوق الخطوط نفسها.'),
  ('80fe5b22-0f4c-4f31-ac99-30418e5a6c6a', 'نسمة للأم 🌬️', 'تملأ فوضى المنزل أذنيكِ بالضجيج. تحققي من الطقس والملابس، وارتدي ما يلزم حتى إن كانت الملابس ثقيلة، ثم اخرجي لمدة 15 دقيقة فقط. دعيه يجمع الحجارة من الأرض، بينما تستنشقين بعمق الهواء البارد والنقي الذي يلامس وجهكِ.'),
  ('93c26bc0-b2a6-4580-91d3-d91792e077a2', 'لغة الديناصورات 🦖', 'هذا الصباح، ليس طفلكِ إنسانًا، بل ديناصورًا لا يجيب عن أسئلتكِ إلا بالزئير. يُعدّ لعب الأدوار وسيلة رائعة لتنمية الشخصية. توقفي للحظة عن أداء دور الأم، وتحوّلي إلى ديناصور آخر يخاطبه بلغته.'),
  ('b992124a-a4ae-4e30-a81b-b79de4b95a68', 'الاعتراف بالإرهاق 📝', 'هل تشعرين أن لا أحد يفهمكِ وأن جهودكِ لا يراها أحد؟ تخلّي عن الابتسامات المتكلّفة. اكتبي في مفكرة المزاج مدى استنزافكِ الحقيقي اليوم. فكل كلمة تسكبينها على الشاشة ستزيح عن كتفيكِ حملًا ثقيلًا.'),
  ('075e0950-03bc-496b-a1a2-1172377fb523', 'الذكاء الاصطناعي ومخاوفكِ 🤖', 'هل أصابكِ القلق فجأة لأن طفلكِ لا يستطيع نطق بعض الحروف؟ أغلقي المنتديات غير المتخصصة والمخيفة على الإنترنت. اسألي Anacan AI عن معايير تطور النطق في عمر 3 سنوات، واحصلي على إجابة علمية ومطمئنة.'),
  ('9bbc80a7-dd83-4c11-86b7-3f3e1fd0e2b9', 'سيرك في السرير 🎪', 'عندما يحين وقت النوم، يتحول السرير فجأة إلى حلبة سيرك. يقفز ويزحف ويصرخ. خفّفي الإضاءة من دون رفع صوتكِ. إنه يتخلص من آخر ما تبقى لديه من طاقة. هدّئي هذه العاصفة تدريجيًا بقصة بطيئة الإيقاع جدًا من الحكايات الذكية.'),
  ('c4897803-48e7-46f1-aca1-db692fe7b9f1', 'مقبض الباب الذي لا يقبل المشاركة 🚪', 'يركض أمامكِ قائلًا: أنا من سيفتح الباب! وإذا فتحتِه أنتِ، يبكي ويطلب منكِ إغلاقه مجددًا كي يفتحه بنفسه. الشعور بالسيطرة هو كل شيء في هذا العمر. دعيه يفتح الباب؛ فهذه الانتصارات الصغيرة تعزز ثقته بنفسه، التي تكون هشة في هذه المرحلة.'),
  ('2b40e6c9-46bc-4fb2-8d09-1e690e1a478c', 'مجتمع التضامن 💬', 'لقد عاند كثيرًا اليوم لدرجة أنكِ تشعرين بأنكِ أم سيئة. ادخلي فورًا إلى مجتمع Anacan. عندما تقرئين عن تمرّد أطفال الأمهات الأخريات اليوم، ستدركين أنكِ لستِ وحدكِ وأنكِ في الواقع تقومين بعمل رائع.'),
  ('4f85a7f5-323c-4830-b901-61f69a9b8176', 'التردد الخفي 🤔', 'يأتي إليكِ ويقول عبارات متناقضة تمامًا، مثل: أعطيني ماءً، لكن لا تعطيني. توجد في ذهنه رغبتان متعارضتان في الوقت نفسه. لا تبحثي عن الكثير من المنطق؛ ضعي الماء على الطاولة فحسب واتركي القرار لصراعه الداخلي.'),
  ('fb64f95e-ceac-49e1-96ee-95e171273ead', 'محاولات استخدام المطرقة والمفك 🛠️', 'يطرق الأثاث بأي لعبة صلبة تقع في يده متظاهرًا بإصلاحه. ورغم أن الأصوات قد تصيبكِ بالصداع، فإن هذا استكشاف يتعلم من خلاله العلاقة بين السبب والنتيجة. أعطيه صندوقًا كرتونيًا فارغًا وملعقة خشبية، ودعيه يواصل إصلاحاته الصاخبة هناك.'),
  ('0b8c858b-4b69-4199-b627-a7a497686efd', 'ليس قمامة، بل فن 🎨', 'لقد صنع في وسط الغرفة عملًا فنيًا ضخمًا من قصاصات الورق الصغيرة والخيوط المقطّعة، ولا يسمح لكِ بالتخلص منه. ضعي هوس النظافة جانبًا. احترمي الفوضى التي أبدعها؛ فالتنظيف يمكن أن ينتظر حتى الغد.'),
  ('5f97fec7-d72f-4377-af18-4420a1663ca4', 'علاج مقياس الصوت 🤫', 'انتهت أخيرًا الضوضاء المتواصلة في المنزل. لقد نام طفلكِ. افتحي تطبيق قياس الصوت وراقبي الأرقام على الشاشة وهي تنخفض حتى 0 ديسيبل. اشعري كيف يداعب الصمت المطلق في الغرفة ذهنكِ بصريًا.'),
  ('63b3f3e0-ceca-4b44-a2ea-ae171ce3413f', 'مسرح أمام المرآة 🎭', 'يقف أمام المرآة منذ الصباح الباكر ويتدرّب على تعابير مختلفة للبكاء والضحك والدهشة. إنه يتعلم كيف يعبّر عن مشاعره وكيف تتغير ملامح وجهه! شاهدي هذا الأداء التمثيلي العبقري من بعيد بكل فخر.'),
  ('14f4e22b-ebcd-4b44-af1e-7caf9bc49874', 'ذراعا الأب السحريتان 🫂', 'تكاد ذراعاكِ تنفصلان من حمله طوال اليوم، لكنه لا يزال يريد أن تحتضنيه. نادي والده. التحليق بين ذراعي الأب سيلبّي حاجة طفلكِ إلى الاهتمام، ويمنح ذراعيكِ وظهركِ الراحة التي تحتاجين إليها بشدة.'),
  ('8e97dc44-4076-463e-90aa-e9a38f43a406', 'المنطق وراء الأسئلة 🧐', 'لماذا لا تمشي الأسماك؟ يستيقظ عقله في الصباح الباكر محمّلًا بالأسئلة الفلسفية. وحتى إن وضعتكِ أسئلته في مواقف محيّرة، فحاولي شرح الأمور له دون كلل. صوتكِ هو أكثر الطرق أمانًا وجمالًا بالنسبة إليه لفهم الكون.'),
  ('d78d5945-d2b9-4d6b-be69-c36a9e85a337', 'فوضى قائمة التسوق 🛒', 'أنتِ أمام صندوق الدفع في المتجر، وفجأة أدركتِ أنكِ نسيتِ أهم غرض مجددًا. فعقلكِ مشتت أصلًا بين ألف أمر. من الآن فصاعدًا، اعتادي على إضافة أي غرض إلى قائمة التسوق في التطبيق فور تذكّره، لتسهّلي الأمر على نفسكِ.'),
  ('62d4901b-19ff-4b33-a0e0-89d727535d96', 'الفخر بارتداء الملابس بالمقلوب 🧦', 'كعب الجورب فوق قدمه، لكنه يتجول بفخر لأنه ارتداه بنفسه. لا تتدخلي ولو قليلًا. فشعوره بأنه نجح في فعل ذلك بنفسه هو أساس نفسي أثمن بمليون مرة من المظهر الأنيق أو ارتداء الملابس بالطريقة الصحيحة.'),
  ('79c5f477-357d-4a5a-a226-aa71c2153c6a', 'حكايات هامسة 🌙', 'لقد استخدمتِ صوتكِ كثيرًا اليوم حتى شعرتِ بالإرهاق. أطفئي الأنوار، واستلقي بجانبه، واحكي له همسًا في أذنه ما حدث خلال اليوم. فالهمس يجذب انتباهه ويهيّئ دماغه بطريقة آسرة للدخول في نوم عميق.'),
  ('b3b80c54-4891-4e55-9e0b-d88a4a322bdd', 'حفل موسيقي في المطبخ 🥄', 'أخرج القدور والملاعق الخشبية وأقام حفلًا صاخبًا وسط المطبخ. ورغم أن الضجيج قد يصيبكِ بالصداع، فإن هذا يساعد على تنمية إحساسه بالإيقاع ومهاراته الحركية. قولي له «أحسنت!» وتأملي أن ينتهي الحفل سريعًا.'),
  ('26929739-4514-47f4-b2ff-3f79743e2a52', 'مقياس الصمت الذهبي 🤫', 'انتهت الفوضى في المنزل أخيرًا ونام طفلكِ. لا تهرعي إلى غسل الأطباق! افتحي مقياس الصوت، وتأملي ذلك السكون التام في الغرفة (0-10 ديسيبل)، ولاحظي بصريًا كيف يستريح عقلكِ على مدى 15 دقيقة.'),
  ('691e79df-4ad4-4dc1-80d2-9bb367dfc70e', 'مأساة تقشير الموزة 🍌', 'هل اندلعت ثورة في الغرفة عند الساعة 8 صباحًا لأنكِ قشّرتِ الموزة بدلًا منه؟ القاعدة الذهبية لهذه المرحلة العمرية: يجب أن يقرر هو كل شيء. لا يمكنكِ إعادة القشرة إلى مكانها، لذا حوّلي انتباهه فورًا إلى شيء طريف آخر لإنهاء نوبة الغضب.'),
  ('cfe53a47-5049-4180-8a26-333de41ec18f', 'متلازمة السمع الانتقائي 🙉', 'ألا يسمعكِ حين تطلبين منه جمع ألعابه، لكنه يلتقط فورًا صوت غلاف الشوكولاتة من الغرفة المجاورة؟ لا مشكلة في سمعه، بل يسمع فقط ما يحلو له. جرّبي همس القواعد له، فهذا سيثير فضوله.'),
  ('46cb3019-8e96-4dd4-93b2-6c2a4bab0f53', 'كنوز تخرج من الجيوب 🪨', 'هل وجدتِ في جيب سرواله عند غسله حجرين وورقة شجر يابسة وعودًا مكسورًا؟ قد تبدو لكِ هذه الأشياء نفايات، لكنها مجموعته الثمينة التي يكتشف بها الكون. بدلًا من رميها، اجمعيها في صندوق كنوز صغير.'),
  ('4c758b24-b5bb-4fba-9fae-76aff0e5119d', 'تمويه البروكلي 🥦', 'هل يستبعد الخضراوات الخضراء من الحساء بدقة جرّاح؟ لقد بلغ انتقاؤه للطعام ذروته. حان الوقت لاكتشاف وصفات مميزة وذكية في خطة التغذية، تُخفي الخضراوات عن الأنظار وتحولها إلى أقراص ملوّنة شهية.'),
  ('56a63f2b-c314-4614-a2a4-36e4a75775f5', 'هو مخرج الحكاية 🪄', 'لقد مللتما كلاكما من الكتب الكلاسيكية. افتحي الحكايات الذكية ودعيه يوجّه أحداث القصة هذا المساء. اسأليه: إلى أين ستذهب السيارة الطائرة الآن؟ ودعيه يخلد إلى النوم على النهاية الطريفة والغريبة التي ابتكرها.'),
  ('4cbe2cb0-5188-4114-8447-b099245e7121', 'وضع الطيران مع الأب ✈️', 'لم يتمكن من تفريغ طاقته في المنزل، والآن يرفض الذهاب إلى السرير. اطلبي مساعدة الأب. حين يرفعه في الهواء ويتظاهر بأنه طائرة، تملأ الضحكات الغرفة ويختفي كل التوتر الجسدي المتراكم خلال ثوانٍ.'),
  ('9afa0a7d-99d2-4d5f-a4cb-8f47ca178b6a', 'التنفّس وسط مجتمع يفهمكِ 💬', 'هل أنتِ مرهقة جدًا وتشعرين بأنكِ أقل أم صبرًا في العالم؟ افتحي مجتمع Anacan فورًا. إن قراءة تجارب أمهات أخريات يعشن نوبات الغضب الغريبة نفسها تمامًا تمنحكِ دعمًا نفسيًا كبيرًا.'),
  ('bd33d5a6-7358-4409-91cf-48f9ce76cb44', 'دوامة «لماذا؟» التي لا تنتهي 🌪️', 'لماذا تطير الطيور؟، لماذا يجعل الماء الأشياء مبللة؟، لماذا «لماذا» هي لماذا؟... يندفع نحوكِ قطار من الأسئلة المتلاحقة. حتى إن شعرتِ بالتعب، قدّمي له إجابات منطقية ومختصرة. فهو يتعلم أسرار الكون من نبرة صوتكِ.'),
  ('5940af77-4cae-40d5-a543-2bf3a6668855', 'الهروب إلى الطبيعة ⛅', 'لقد جعل البقاء بين أربعة جدران كليكما أكثر توترًا، وأرهقتكِ فوضى المنزل. تحققي من أداة الطقس والملابس، ثم انطلقي فورًا إلى الحديقة. فالركض بحرية في الهواء الطلق يوقف حتى أشد نوبات غضب الأطفال الصغار بسرعة مذهلة.'),
  ('d6b3a2c2-7743-47f8-927a-59220b3461a1', 'مساعد الغسيل 🧺', 'تطوين الملابس بجهد كبير، بينما يدّعي طفلكِ أنه يساعدكِ ثم يعيد نثرها في أرجاء الغرفة. بدلًا من الانزعاج، حوّلي المهمة إلى لعبة: لنرَ من سيتمكن من رمي هذه الجوارب في السلة أسرع؟'),
  ('95036444-eb4a-4cd7-a33d-678f3daaa180', 'مفهوم الموضة الطليعية 👗', 'ارتدى سروالًا صيفيًا قصيرًا فوق سترته الشتوية ولا يريد خلعه؟ لا بأس. فالطفل الذي يخرج بين الناس بملابس غير متناسقة هو في الحقيقة طفل يدافع بشجاعة عن قراره. لا تكسري إرادته.'),
  ('98f4059e-feba-4e5c-88c8-f44ceadd630c', 'فكّ لغز الذعر الليلي 😭', 'استيقظ طفلكِ في منتصف الليل باكيًا وعيناه مغمضتان، ولا يستجيب لأحد. تحققي من الأمر باستخدام تحليل البكاء؛ وإذا كان ما يحدث نوبة ذعر ليلي، فلا تحاولي إيقاظه. ابقي إلى جانبه فحسب وامنحيه شعورًا بالأمان بهدوء.'),
  ('bfca2126-084c-4371-a225-6bbeaa8fe2d1', 'تنبيه الطقس ⛅', 'عندما تخرجين في نزهة، لا تنخدعي بما ترينه من النافذة. استخدمي مساعد الطقس والملابس لاختيار الزي الأنسب للرياح ودرجة الحرارة الفعلية في الخارج، وغادري المنزل مطمئنة ومستعدة.'),
  ('25567149-e2e9-4c4d-aaff-501c9547f638', 'مجتمع يحفظ أسراركِ 💬', 'أنتِ مرهقة جدًا ولا ترغبين في شرح أي شيء لأحد. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية أمهات أخريات يعانين من إرهاق مشابه تمنحكِ شعورًا بأنكِ لستِ وحدكِ، وقد تكون أفضل علاج.'),
  ('3df12920-0213-48db-ae96-b67ec62ae28a', 'حفل مباشر والجيران 🎤', 'أمسك طفلكِ ملعقة ووقف في وسط الغرفة يغني ويصرخ بأعلى صوته. لا تكترثي بما قد يفكر فيه الجيران. هناك نجم ينمو في منزلكِ، وما عليكِ سوى التصفيق له.'),
  ('3f3676c6-cf62-4752-a389-70e0f348c529', 'انتقال موسيقي إلى النوم 🎶', 'جرّبي تهدئة نوبات الانفعال المفاجئة في المساء بموسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة والفعالة المعجزات في المنزل، وتضفي على الغرفة سكينة لا مثيل لها.'),
  ('3e411b4b-9fe8-4f71-93e2-682182a18dba', 'الشعور بالذنب بسبب وقت الشاشة 📺', 'سمحتِ لطفلكِ اليوم بمشاهدة المزيد من الرسوم المتحركة بسبب انشغالكِ، وتشعرين بتأنيب الضمير؟ لا تلومي نفسكِ. فأحيانًا تكون جليسة الأطفال الرقمية هي السبيل الوحيد لإنقاذكِ من الانهيار النفسي.'),
  ('66770f83-ef83-4481-9f8c-e9788791f68a', 'عملية إخفاء الهاتف 📱', 'لا تجدين المكان الذي وضعتِ فيه هاتفكِ، ثم يظهر بعد فترة من صندوق الألعاب. طفلكِ لا يريد أن يتقاسم انتباهكِ مع الهاتف. ضعي الجهاز جانبًا وامنحيه اهتمامكِ الكامل دون انقطاع لمدة 15 دقيقة.'),
  ('b18d81af-044b-40e7-b55d-b23baee972a4', 'المقياس الرقمي للصمت 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي خيّم على المنزل. فعّلي مقياس الصوت، وانظري إلى الرقم 0-10 ديسيبل الظاهر على الشاشة، واستشعري بصريًا كيف يبدأ عقلكِ بالاسترخاء تدريجيًا.'),
  ('09d17b10-a60b-4930-b773-b0f5bb7e0366', 'لن أعطي لعبتي لأحد! 🧸', 'لا يريد إفساح المجال لأحد عند الزحليقة أو في منطقة الرمل بالحديقة، ويتمسك بألعابه بقوة. هذا ليس أنانية، بل حماية لحدوده. لا تجبريه على المشاركة، بل علّميه نظام تبادل الأدوار من خلال اللعب.'),
  ('0a13d571-0f47-4b38-ba09-6279a4e6c3b5', 'دعوة إلى الظلام 🌙', 'هل يشعر بالقلق عند إطفاء الأنوار في غرفة النوم؟ ضعي مصباحًا ليليًا صغيرًا بلون دافئ في إحدى زوايا الغرفة، مع إبقاء بقية الغرفة مظلمة تمامًا لضمان نوم عميق.'),
  ('f1a7ace3-b71a-47a5-8150-e29d91b1d2f6', 'عندما تتعب الأم 🛑', 'أنتِ لستِ آلة. إذا لم تكن لديكِ اليوم طاقة لإعداد الطعام، فاطلبي وجبة جاهزة أو اكتفي بسلق المعكرونة. أن تكوني أمًا مثالية لا يعني أن تفعلي كل شيء بمفردكِ. اسمحي لنفسكِ بذلك.'),
  ('012a4a46-c01f-4202-b7ec-b6dfb922b323', 'مفاجأة في القائمة 🛒', 'فتحتِ قائمة التسوق قبل الذهاب إلى المتجر، وفجأة جاء طفلكِ من خلفكِ وبدأ يضغط على شاشة الهاتف ويضيف إليها خربشات عشوائية. نعم، إنه يقلّد حياتكِ الرقمية أيضًا!'),
  ('0f7001d8-21ca-493f-95e3-7b29b5f52d2b', 'بوحٌ في يوميات المزاج 📝', 'أمسكي هاتفكِ. بدلًا من تصفح حياة الآخرين على وسائل التواصل الاجتماعي، افتحي يوميات المزاج ودوّني أطرف موقف قام به اليوم ليبقى ذكرى للمستقبل. العلاج الرقمي مفيد حقًا.'),
  ('507a4882-997e-48f9-8d0c-a6ff5f18c3ac', 'مفاوضات كالمحامين 🗣️', 'هل يقول: دعيني ألعب 5 دقائق فقط، ثم سأرتدي ملابسي؟ إنه يحاول بالفعل التفاوض معكِ باحترافية. تطوره اللغوي ممتاز، لكن لا تنسي الحفاظ على حدودكِ وقواعدكِ بحب.'),
  ('222c5b3e-e10d-4be3-be74-5b7c060039a8', 'سكينة الليل 🛁', 'لقد أنهككما الركض طوال اليوم، أنتِ وطفلكِ. أثناء الاستحمام بماء فاتر، شغّلي في الخلفية أصواتًا طبيعية هادئة. سيساعد تناغم الماء حتى أكثر الأطفال عنادًا على الاستعداد لنوم عميق.'),
  ('658a0f7f-5501-4d36-97c8-25ebf4c2bf93', 'الإرهاق من كثرة اللمس 🔋', 'يتسلق عليكِ طوال اليوم، ويطلب حضنكِ ويلعب بشعركِ، بينما تحتاجين أنتِ فقط إلى بعض المساحة الجسدية. الإرهاق من كثرة اللمس (touched out) شعور حقيقي. ومن حقكِ أن تنعزلي في غرفة بمفردكِ ولو لمدة 15 دقيقة.'),
  ('fd872988-ca1c-4392-86ef-3fa893d01f3e', 'الخوف من فتحة تصريف حوض الاستحمام 🛀', 'هل بدأ طفلكِ، الذي كان يعشق البقاء في الماء، فجأة بالبكاء خوفًا من فتحة تصريف حوض الاستحمام؟ مع تطور الخيال قد تظهر مخاوف غير منطقية. غطّي الفتحة بلعبة بلاستيكية وطمئنيه.'),
  ('380c78ab-6c26-4edf-8c80-e7615f9b4b80', 'استراحة للزوجين 🥂', 'نام طفلكِ. ضعي الآن الأعمال المنزلية جانبًا. تحدثي مع شريككِ لمدة 20 دقيقة على الأقل في أي موضوع بعيدًا عن الطفل والمشكلات والنفقات. فأنتما زوجان قبل أن تكونا والدين!'),
  ('752bc100-4fdb-4f78-84aa-dd9676151255', 'التحدث إلى الجمادات 🗣️', 'هل يتحدث بجدية تامة إلى حجر في الحديقة أو كرسي في المنزل، بل ويوبخهما؟ إنه يستوعب العالم من حوله من خلال اللعب الرمزي. احرصي على تسجيل هذه السيناريوهات المميزة في متتبع النمو.'),
  ('7bfbea7d-ee3e-4b33-88e0-e90f78f2538d', 'جلسة تدليك من الأب 💆‍♂️', 'لقد قضيتِ اليوم وقتًا طويلًا واقفة، وأصبح ظهركِ يؤلمكِ من الركض خلف طفلكِ. ما إن ينام، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ عماد المنزل، وحتى الأعمدة تحتاج إلى الترميم.'),
  ('14bae514-5bcb-45ca-923d-75a7333cefe5', 'حيلة تأجيل النوم ⏱️', 'هل يشعر فجأة بالعطش عند حلول موعد النوم، أو يطلب الذهاب إلى الحمام، أو يبدأ بتوديع الجدار؟ اضبطي مؤقتًا، وطبّقي قاعدة «عندما يرن الجرس، ينام الجميع» لتضعي بصبر حدًا لهذا الوداع الذي لا ينتهي.'),
  ('4ec63d29-5d5a-4c61-aeca-3683d2926fad', 'مخزون الأم الغذائي 🥗', 'فكرتِ في قوائم طعام متنوعة لإشباعه، لكن هل بقيتِ أنتِ جائعة مجددًا؟ اختاري من الوصفات الصحية وجبة غداء غنية بالحديد والكالسيوم يمكن إعدادها خلال 10 دقائق، وامنحي نفسكِ ما تستحقينه من اهتمام.'),
  ('7886ad64-9846-4990-9753-652093d6bac5', 'كارثة اللون الخطأ 🔴', 'هل قامت القيامة لأنكِ قدّمتِ الماء في كوب أحمر بدلًا من الأزرق؟ هذا ليس دلالًا، بل إن طفلكِ يختبر حدودكِ وما إذا كان قادرًا على التحكم في العالم من حوله. غيّري الكوب من دون الدخول في صراع عناد، وحافظي على طاقتكِ.'),
  ('bfa1d504-f493-414c-a978-4ad885726ef7', 'أطلقي العنان لمشاعركِ 📝', 'ألا يرى أحد مدى تعبكِ في المنزل؟ مفكرة المزاج هي كاتمة أسراركِ الأكثر هدوءًا. اكتبي فيها اليوم كل التفاصيل التي أفقدتكِ صوابكِ، ولاحظي كيف يخف العبء عن ذهنكِ.'),
  ('1800a436-63cf-4ef5-8469-ebb0dffa942d', 'ذكاء اصطناعي، حل حقيقي 🤖', 'هل ظهرت لدى طفلكِ عادة غريبة، مثل لف شعره، وأخافتكِ المقالات على الإنترنت؟ توقفي. اسألي Anacan AI عن السبب الحقيقي الذي يؤكده أطباء الأطفال، وتخلّصي من القلق غير الضروري.'),
  ('3f147988-5fe0-4104-b53b-bcd1de9eb553', 'منطق الغميضة 🙈', 'يقف في منتصف الغرفة ويغطي عينيه بيديه منتظرًا منكِ أن تجديه! منطق سن الثالثة: ما دمت لا أراكِ، فأنتِ أيضًا لا ترينني. تظاهري بأنكِ صدّقتِ هذا الوهم البريء، وابحثي عنه في الغرفة بصوت مرتفع.'),
  ('e71a10b9-dee7-4968-a1f7-387196804ef0', 'أطفئي الأنوار ليأتي النوم 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بساعة واحدة. فالميلاتونين (هرمون النوم) يُفرز بسرعة في بيئة مظلمة وخالية من التكنولوجيا.'),
  ('2cc2d175-4d74-4e12-832a-3885acc3e55b', 'ذاكرة رقمية 🛒', 'هل تنسين دائمًا شيئًا عند ذهابكِ إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ فورًا، ليشتريها زوجكِ بدقة في طريق عودته من العمل، ولا ترهقي ذهنكِ.'),
  ('8949a363-0fca-4998-bc28-ec5b3f0fc9b2', 'قاعدة «سأفعلها بنفسي!» 👟', 'يريد ربط حذائه بنفسه، وقد تأخرتما بالفعل 10 دقائق عن مغادرة المنزل. لا تستعجليه. فالحفاظ على ثقته بنفسه أهم لنموه من الالتزام الصارم بجدول زمني مضطرب.'),
  ('b6dabad1-9ff8-435e-b107-865df601701d', 'قوة الهمس السحرية 🤫', 'إنه نشيط جدًا في السرير ولا ينام. بدلًا من رفع صوتكِ، اخفضيه فجأة وتحدثي همسًا. عندما يركّز طفلكِ كي يسمعكِ، ينتقل دماغه تلقائيًا إلى وضع الاستعداد للنوم.'),
  ('982b6e37-c6cb-46f9-bd93-9fafd76bcda8', 'ساعة الهدوء 🥱', 'لا يريد أخذ قيلولة الظهر ويبكي؟ لا تجبريه. خفّفي الإضاءة في الغرفة وأعلني عن ساعة هادئة لتصفّح الكتب، وابتكري روتينًا جديدًا يساعدكما على الاسترخاء.'),
  ('dd274cad-cc38-4230-a074-0f529d065804', 'لن آكل هذا اليوم 🥣', 'لا تستطيعين اليوم إقناعه حتى بتذوّق الحساء الذي أكله بشهية بالأمس. إذا لم تكن لديه مشكلة في أسنانه، فهو على الأرجح يختبر الحدود فحسب. اطّلعي على وصفات بديلة ومتنوعة توفر الفيتامينات نفسها ضمن خطته الغذائية.'),
  ('ef5d3cbd-0aa0-493b-94cf-cb55ec5a7526', 'أصوات الأب الغريبة 🤡', 'حين لا تعود محاولاتكِ مجدية، تنقذ أصوات الأب الغريبة وملامح وجهه المضحكة الموقف فورًا. خلال نوبات المساء، سلّميه المهمة مباشرة واستريحي وأنتِ تراقبين من بعيد.'),
  ('805b4060-d925-4469-abb9-000b87b286a1', 'أحجية الطبيعة 🍁', 'أجواء المنزل المملة تضايقكما معًا. اذهبا إلى الحديقة وانطلقا في مهمة للعثور على أغرب حجر من حيث الشكل. فالطبيعة هي أكبر مختبر لطفلكِ، وستساعده على التخلص من كل توتره.'),
  ('88ec7e91-36e6-4aab-9210-fc0f8e69cab3', 'ضيوف خياليون حول المائدة ☕', 'هل يمدّ إليكِ كوبًا فارغًا ويقول: «اشربي الشاي»، ثم يتحدث مع صديق غير موجود في الغرفة؟ إنها تحفة من تحف تطور الخيال. لا تقاطعي هذا العرض الذي يدور في إحدى زوايا الغرفة، بل شاركيه واشربي ذلك الشاي أيضًا.'),
  ('9c237165-d4a6-41d4-ba0a-333830a89409', 'أنا في الحكاية الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب. افتحي الحكايات الذكية، واجعلي طفلكِ بطلها الرئيسي وغرفته المكان الذي ينبغي فتحه، وابتكري جلسة نوم استثنائية.'),
  ('62114884-cb2a-44c8-ab0b-33ab815b8e09', 'سلام في الحمّام 🛀', 'اللعب بالماء ممتع لدرجة أنه لا يريد الخروج من حوض الاستحمام حتى بعد أن تتجعد أصابعه. نبّهيه قبل 5 دقائق واضبطي المؤقت. غالبًا ما تنجح قاعدة «عندما يرن الجرس، نخرج».'),
  ('9f52c47e-5431-4d83-b54d-9c8d7cbf5228', 'حرية «لا تمسكي بيدي!» 🚶‍♂️', 'يرفض بشدة أن يمسك بيدكِ في الشارع، ويريد الركض بحرية. امنحيه هذه الحرية في الأماكن الآمنة. أبقي عينيكِ عليه، ودعيه يكتشف العالم بخطواته الخاصة.'),
  ('354da7a1-73e7-4191-ab3d-5f7d75ac4224', 'يتكوّن مفهوم الزمن ⏱️', 'هل يستخدم طفلكِ كلمات «غدًا» و«أمس» و«لاحقًا» كثيرًا، ولكن في غير موضعها أحيانًا؟ إن إدراكه للزمن آخذ في التكوّن! استمعي إلى محاولاته هذه بابتسامة.'),
  ('8b9fda41-95cb-4937-8a79-67166a02c4b7', 'استراحة للأم ☕', 'عندما يلعب طفلكِ بمفرده، لا تسارعي فورًا إلى أداء الأعمال المنزلية. ففوضى الغرفة لن تهرب، لكن طاقتكِ قد تنفد. اجلسي واستمتعي بقهوتكِ الساخنة.'),
  ('c1a7e066-6918-4641-ab6d-c5c20c553974', 'خطة الهروب من السرير 🛌', 'هل يحاول طفلكِ التسلق للخروج من سريره؟ أعيدي تفقد الغرفة لضمان سلامته. لقد اقترب موعد الانتقال إلى سرير الأطفال الكبار.'),
  ('46401ae3-aa9a-4ec9-afa2-b6cab38572ff', 'سيناريوهات خيالية 🧸', 'هل يطعم طفلكِ ألعابه ويعالجها؟ اللعب الرمزي هو أساس التعاطف. سجّلي هذه القفزة المعرفية بفخر في متتبّع النمو.'),
  ('4cba464d-475d-46de-93c9-1a54b6d0a768', 'أجواء ليلية ساحرة 🪄', 'هل يواجه طفلكِ صعوبة في النوم؟ حوّلي العادات الجديدة إلى حكايات من خلال إنشاء قصة في الحكايات الذكية عن بطلها دبدوب يفرّش أسنانه.'),
  ('7ef518fa-cecf-4467-bd34-eb7fb3a21761', 'التفاعل في الحديقة 🌳', 'هل يلعب طفلكِ بجوار الأطفال الآخرين بدلًا من اللعب معهم؟ اللعب الموازي طبيعي تمامًا في هذا العمر. شجّعيه على التفاعل الاجتماعي من دون الضغط عليه.'),
  ('85dcc8b6-3ff2-43d3-9d96-7c1edd51dcff', 'محقّق البروكلي 🥦', 'هل يكتشف طفلكِ قطعة الخضار الخضراء الوحيدة في الحساء ويرفض تناوله؟ اكتشفي في خطة التغذية ألذ الطرق لتشتيت انتباهه وإخفاء الأطعمة المفيدة، مثل مزج الخضراوات بالمعكرونة الملوّنة.'),
  ('9d17ee0d-df59-4f5d-b9e7-c0b06e40eb21', 'الاعتراف بالمشاعر 📝', 'هل تشعرين بالذنب لأنكِ تقولين «لا» لكل شيء طوال اليوم؟ افتحي مفكرة المزاج. اكتبي اليوم، من دون أي تنقيح، أكثر أفكاركِ قتامة: «ليتني كنت وحدي». لا تلومي نفسكِ؛ فكل أم تشعر أحيانًا بالإرهاق وترغب في الهروب.'),
  ('d319859d-6f77-4ec4-b4f9-90c9441fac9e', 'آثار النمو 📈', 'في سن الثالثة، تتطور مهارات طفلكِ الحركية وحصيلته اللغوية وذكاؤه العاطفي بسرعة. وحتى لا تنسي اكتشافاته الصغيرة، دوّنيها بانتظام واحفظيها في متتبّع النمو.'),
  ('01326cb0-274c-49ad-8b92-7ce1373a0568', 'يعتذر ثم يكرر الفعل نفسه 🧸', 'هل يعتذر بصدق عن ضرب شخص أو كسر شيء، ثم يكرر الفعل نفسه تمامًا بعد ٥ دقائق؟ إنه لا يستطيع التحكم في اندفاعاته بعد. اشرحي له القاعدة بصبر، مرارًا وتكرارًا.'),
  ('1efb2536-bf55-4365-890d-581fbbac3193', 'الحاجة إلى الفضفضة 💬', 'هل عليكِ اتخاذ قرار صعب؟ (الحضانة، التدريب على استخدام الحمّام، النوم). ستجدين لدى الأمهات الخبيرات في مجتمع Anacan نصائح وحلولًا واقعية مستمدة من الحياة، لا تجدينها في أي كتاب.'),
  ('d2d2c46d-7705-4c59-b1ff-a6a3d0986863', 'دعيه يكتب نهاية الحكاية 🪄', 'لقد مللتِ أنتِ وطفلكِ من الكتب الكلاسيكية. هذه المرة، دعي طفلكِ يختار نهاية القصة في الحكايات الذكية. أطلقي العنان لخياله قبل النوم بسؤاله: «برأيك، من ساعد ذلك البطل؟»'),
  ('37e65e72-e2dc-4492-b8ea-92aeab4db745', 'أم سليمة، طفل سليم 🥑', 'وسط انشغالاتكِ اليومية، لا تتناولي الغداء على عجل وأنتِ واقفة. اجلسي وحضّري سلطة متنوعة غنية بالحديد والكالسيوم، وتناوليها باستمتاع. طاقتكِ هي محرّك هذا المنزل، فحافظي عليها.'),
  ('9a78401e-398c-45fd-a3a7-dae1cd59ed31', 'تأكيد الهدوء 🤫', 'بعد يوم صاخب، وعندما ينام طفلكِ، قيسي هدوء الغرفة باستخدام مقياس الصوت. حتى مجرد رؤية الأرقام وهي تقترب من الصفر تمنح دماغ الأم أفضل تدليك بصري.'),
  ('ba7f66f9-da13-4eea-9e4a-a968d14f269b', 'اقتحام تحضير الطعام 🧑‍🍳', 'حين تفردين العجين، سيضع كرسيًا بجواركِ حتمًا ويحاول المشاركة في كل خطوة. دعيه يرش الدقيق في وعاء بلاستيكي مخصص له. ستعمّ الفوضى المطبخ، لكن ملامح وجهه الجادة والمنشغلة تستحق كل عناء التنظيف.'),
  ('06f0acb2-a541-42e5-8b33-ed2285d3285f', 'تبادُل الشكر 🥂', 'لقد تجاوزتما يومًا صعبًا. بعد أن ينام طفلكِ، حضّري كوبًا من الشاي مع شريككِ واشكريه قائلة: «لقد ساعدتني كثيرًا في هذا اليوم العاصف». هكذا تُبنى روح الفريق.'),
  ('4217bad1-d028-470b-a2a2-ceacb5b15105', 'ذكاء اصطناعي، إجابة حقيقية 🤖', 'ما الأسباب العلمية والمؤكدة من أطباء الأطفال لأزمات سن الثالثة؟ بدلًا من قراءة التعليقات المخيفة على الإنترنت، اطلبي فورًا من Anacan AI تحليلًا دقيقًا واحترافيًا لنفسية طفلكِ.'),
  ('50050f6d-75e8-48b1-9632-bcebb31ce6fa', 'فرط التحفيز الحسي 🔋', 'ظل طفلكِ طوال اليوم يتسلق عليكِ ويشد شعركِ ويُحدث الضجيج. جهازكِ العصبي يطلق إنذارًا أحمر. الإرهاق من كثرة اللمس حقيقي تمامًا. اتركي طفلكِ مع شريككِ وانسحبي إلى الغرفة لبعض الوقت.'),
  ('0efdad7b-f986-4a21-8e04-fc9cffca1b7d', 'طرق نطق طريفة 🗣️', 'ينطق الكلمات بطرق غريبة ونبرات خاصة به لدرجة يصعب معها منع الضحك. لا تصححي له وأنتِ تضحكين، بل أنصتي إليه باهتمام وأجيبيه بتكرار الجملة بصيغتها الصحيحة فحسب.'),
  ('6d1f309e-d64f-4916-a1e2-48f064024563', 'مشكلة النسيان في المتجر 🛒', 'ذهبتِ إلى المتجر معتمدةً على ذاكرتكِ، ثم عدتِ وقد نسيتِ حفاضات طفلكِ؟ لا بأس، فهذا يحدث. اعتادي تدوين جميع احتياجاتكِ فورًا في قائمة التسوق، ودعي ذاكرتكِ الرقمية تنقذكِ.'),
  ('b478188b-090e-49fa-8067-44d7985fc9d2', 'أفرغي مشاعركِ على الورق 📝', 'ألا يرى أحد مدى تعبكِ؟ مفكرة الحالة المزاجية موجودة لتصغي إليكِ. اكتبي فيها اليوم كل التفاصيل الصغيرة التي أفقدتكِ صبركِ، وأريحي ذهنكِ.'),
  ('51755ad7-f4a2-46b5-9170-1977fdac0046', 'تهيئة الظروف لهرمون النوم 🌙', 'لمساعدة طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بساعة. يُفرَز هرمون النوم في بيئة مظلمة وخالية من الأجهزة التكنولوجية.'),
  ('556d15ad-f396-4daf-9a38-c5bd773f19f0', 'الحرية في الحديقة 🌳', 'البقاء بين أربعة جدران يجعله أكثر عدوانية. استخدمي مساعد الطقس والملابس لاختيار الزي الأنسب للرياح في الخارج، ثم اصطحبيه إلى الحديقة. دعيه يتمرغ في الرمل ويركض ويتعثر. الحرية هي أفضل ما يدعم نموه.'),
  ('b2f0448e-4bda-4f45-8af5-d1f543150cda', 'عناق غير متوقع 💖', 'بينما يلعب في وسط الغرفة، ينظر إليكِ فجأة ثم يركض نحوكِ ويعانقكِ. إنها لحظة تستحق كل الليالي بلا نوم وكل التعب! استمتعي بذلك السلام العميق والفريد الذي تمنحكِ إياه هذه اللحظة.'),
  ('df69592f-4c0f-4591-8df6-51164eef4e12', 'هذا ليس خطئي! 🤷‍♂️', 'سكب الماء على الأرض عمدًا، لكنه ألقى اللوم على الطاولة قائلًا: «الطاولة تحرّكت». هذا ليس كذبًا، بل غريزة لدى دماغ الطفل للتهرّب من المسؤولية والدفاع عن نفسه. لا تدخلي معه في صراع، بل قولي: «تعالَ نساعد الطاولة ونمسح الماء معًا»، وهكذا تعلّمينه تحمّل المسؤولية من دون جرح مشاعره.'),
  ('7ac03452-73e8-4680-9a3a-f2917f96ee7f', 'تأثير الجدران الأربعة ⛅', 'تشعرين بالاختناق في المنزل، بينما يصبح طفلكِ أكثر عدوانية. تحقّقي من الطقس والملابس، واختاري الأنسب، ثم انطلقي معه إلى الحديقة بحماس. فالهواء والحركة بحرية هما أفضل وسيلة لتنقية دماغه وتهدئة أعصابكِ المرهقة أيضًا.'),
  ('ab102c70-f16b-4f7f-8521-b11e20c36d7a', 'مهمة طيّ الملابس 🧺', 'تطوين الملابس النظيفة بجهد كبير، ثم يندسّ بينها خلال 2 ثانية ويبعثرها كلّها. ويخيّم صمت عميق على الغرفة... هل بلغت أعصابكِ أقصى توترها؟ خذي نفسًا عميقًا. ارتمي فوق كومة الملابس المبعثرة واستسلمي لهذه الفوضى وأنتِ تضحكين.'),
  ('e3d6247b-8c6f-4322-9f82-93d3245cab38', 'مخرج الحكاية الذكية 🪄', 'لقد مللتما كلاكما من أبطال الكتب الكلاسيكية. افتحي الحكايات الذكية، ودعيه يبتكر أحداث قصة هذا المساء. اسأليه: «إلى أين سيذهب الديناصور الطائر الآن؟»، ودعيه يغفو داخل عالم الخيال الذي نسجه بنفسه.'),
  ('62178f50-5d62-4afb-bacf-33c6e7bf5732', 'وضع الطيران مع الأب ✈️', 'لم يتمكّن من تفريغ طاقته في المنزل، ويختلق ألف عذر كي لا يذهب إلى فراشه. استدعي والده. حين يرفعه في الهواء ويلعب معه لعبة الطائرة، تملأ القهقهات الغرفة، وتتلاشى كل الطاقة العدوانية الجسدية المتراكمة مع التعرّق والحركة.'),
  ('7338bae4-7d68-4f02-8b9f-7e3603f62bb9', 'صدمة «أنتِ أم سيئة!» 💔', 'هل نظر إليكِ وقال: «أنتِ سيئة» لأنكِ لم تشتري له اللعبة التي أرادها؟ لا تدعي ذلك يكسر قلبكِ. فهو لا يزال عاجزًا عن التعبير عن مشاعره بالكلمات المناسبة؛ وما يريد قوله في الحقيقة هو: «أنا غاضب ومحبط جدًا». تواصلي معه بصريًا، وأخبريه ببساطة أنكِ تتفهّمين شعوره.'),
  ('c4d16b0b-f2b1-40f5-8462-8e7c3419883e', 'إصراره في المتجر: «أنا سأقود!» 🛒', 'يريد دفع عربة التسوّق بنفسه، فيصطدم بالرفوف ويلفت أنظار الجميع. وكلما تدخّلتِ، بدأ بالبكاء. دعيه يدفعها معكِ. ولتجنّب النسيان، أبقي «قائمة التسوّق» في التطبيق مفعّلة حتى تقلّلي العبء على ذهنكِ.'),
  ('159b5a7f-d190-47d4-8cda-ba692f07b0d0', 'هدوء مقياس الصوت 🤫', 'لقد نام أخيرًا! الصمت الذي خيّم على المنزل عميق لدرجة أنه يكاد يصمّ أذنيكِ. فعّلي مقياس الصوت، وانظري إلى قراءة 0-10 ديسيبل على الشاشة، واستشعري بصريًا كيف يبدأ دماغكِ بالتعافي ببطء.'),
  ('66da20be-59e4-4c6a-b44a-168bd86bf8c2', 'مسرح أمام المرآة 🎭', 'يقف أمام المرآة منذ الصباح ويتدرّب على تعابير مختلفة للبكاء والضحك والدهشة. إنه يكتشف كيف يعبّر عن مشاعره وكيف تتغيّر ملامح وجهه. شاهدي هذا الأداء التمثيلي العبقري من بعيد وأنتِ تبتسمين.'),
  ('69d26c82-f68d-4fca-acec-f2cabf4901f8', 'ذراعا الأب السحريتان 🫂', 'تكاد ذراعاكِ تنفصلان من حمله طوال اليوم، لكنه ما زال يريد أن تحتضنيه. نادي والده. فالتحليق بين ذراعي أبيه سيلبّي حاجته إلى الاهتمام، ويمنح ذراعيكِ الراحة التي تحتاجان إليها بشدة.'),
  ('b233c7da-a3d8-4dbb-a50a-7267ec7bfbc6', 'ليس قمامة، بل فن 🎨', 'لقد صنع في وسط الغرفة عملًا فنيًا ضخمًا من قصاصات الورق الصغيرة والخيوط المقطّعة، ولا يسمح لكِ برميه. ضعي هوس النظافة جانبًا. احترمي الفوضى التي أبدعها، فالتنظيف يمكن أن ينتظر حتى الغد.'),
  ('3613ef28-90fe-4c93-a13a-cc4ded2b5ad4', 'إصرار «سأفعلها بنفسي!» 🛑', 'يريد أن يربط حذاءه بنفسه، وقد تأخرتما بالفعل 10 دقائق عن مغادرة المنزل. لا تستعجليه. فالحفاظ على ثقته بنفسه أهم لنموه من الالتزام بجدول زمني تعرّض لبعض التأخير. دعيه يحاول.'),
  ('67736a86-09e4-4211-ade6-1d5d48e8a05f', 'حكايات هامسة 🌙', 'لقد استخدمتِ صوتكِ كثيرًا اليوم حتى تعبت رئتاكِ. أطفئي الأنوار، واستلقي بجانبه، واحكي له همسًا في أذنه ما حدث خلال اليوم. يساعده الهمس على تركيز انتباهه، ويهيّئ دماغه لنوم عميق بطريقة أشبه بالتنويم.'),
  ('8d9fad31-a8cd-481f-953a-35d411108040', 'خرافة الأم المثالية 🛑', 'هل أصبح الأطفال على وسائل التواصل الاجتماعي يعرفون الألوان والأرقام ويعدّون بالإنجليزية، بينما لا يريد طفلكِ ذلك؟ توقفي فورًا عن المقارنة! لكل طفل وتيرته الخاصة والمختلفة في النمو. طفلكِ رائع كما هو، ويتقدّم وفق وتيرته الخاصة.'),
  ('4c7e076f-90de-4c2c-ae58-d9d897931fd4', 'هل انتهى وقت القيلولة؟ ⏱️', 'هل يستغرق نومه مساءً أكثر من 1 ساعة؟ راجعي جدول نومه. في خضمّ مرحلة سن 3 سنوات، قد يكون الوقت قد حان لإلغاء القيلولة تمامًا وتقديم موعد النوم مساءً.'),
  ('b52dda4e-86c5-4200-973f-b7fbeb8869cc', 'أسئلة «لماذا؟» التي لا تنتهي 🌪️', 'لماذا لا تمشي الأسماك؟، أين ذهبت الشمس؟ منذ الصباح الباكر، يبحث عقله الصغير عن الحكمة بسرعة 100 سؤال في الساعة. حتى إن شعرتِ بالتعب، قدّمي له إجابات منطقية ومختصرة. فهو يتعرّف إلى أسرار الكون من خلال نبرة صوتكِ.'),
  ('ece2fe16-c57e-4a1f-a594-5e39da1118d6', 'بوح المجتمع 💬', 'أنتِ متعبة جدًا ولا ترغبين في شرح أي شيء لأحد. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية الأمهات الأخريات وهن يواجهن إرهاقًا مشابهًا ونوبات غضب طريفة من أطفالهن ستمنحكِ شعورًا بأنكِ لستِ وحدكِ، وهذا أفضل ما قد يهدّئكِ.'),
  ('fabbf657-c431-4c98-ba31-613ca3dc8a47', 'الطاهي الصغير في المطبخ 🧑‍🍳', 'عندما تفردين العجين، سيضع كرسيًا بجانبكِ حتمًا ويحاول المشاركة. دعيه يرش الدقيق في وعاء بلاستيكي خاص به. ستعمّ الفوضى المطبخ، لكن ملامحه الجادة والمنهمكة وشعوره بأنه قادر على فعل ذلك أيضًا يستحقان كل عناء التنظيف.'),
  ('7e88dfb0-8648-40c5-a6ab-3a3cf4987fb3', 'فخر ارتداء الملابس بالمقلوب 🧦', 'كعب الجورب فوق قدمه، لكنه يتجوّل بفخر لأنه ارتداه بنفسه. لا تتدخلي ولو قليلًا. فشعوره بأنه نجح في فعل ذلك بنفسه أساس نفسي أثمن بمليون مرة من المظهر الأنيق أو ارتداء الملابس بطريقة صحيحة، لذا دعيه يقضي يومه هكذا.'),
  ('ca2fd133-6b0b-4852-a4b2-b830a12f0bc0', 'دقائق بلا اتصال للأم ☕', 'إنه يركّب الأحجية بمفرده ويلتزم الهدوء منذ 10 دقائق، بينما تريدين استغلال هذه اللحظة لترتيب المنزل. لا! اذهبي واستلقي على الأريكة. فأنتِ أيضًا بحاجة إلى شحن بطاريتكِ حتى تتمكني من مواصلة هذا الإيقاع حتى المساء.'),
  ('e264b682-e7a9-4579-80a1-6e47fe7bccb3', 'التصالح مع الظلام 🐰', 'هل يرفض النوم ويقول إنه يخاف من الظلال في الغرفة؟ أظلمي الغرفة تمامًا واصنعي بيديكِ على الحائط ظلالًا على شكل طائر أو كلب. بتحويل الخوف إلى متعة، ستساعدينه على مصادقة الظلام والتحكم في خياله.'),
  ('03f9e2c0-9e7a-47b1-892e-0261f73bfa13', 'الذكاء الاصطناعي والمخاوف 🤖', 'هل أقلقكِ أن طفلكِ لا يزال غير قادر على نطق بعض الحروف نطقًا صحيحًا؟ أغلقي المنتديات المخيفة على الإنترنت. اسألي ذكاء Anacan الاصطناعي عن معايير تطور النطق في عمر 38 شهرًا، واحصلي على إجابة علمية وواقعية.'),
  ('8c0fa05b-b55a-47a2-b4af-b9fb41bdabf9', 'كوني أنتِ الطفلة، وأنا الأم 👩‍👧', 'بدأت لعبة تبادل الأدوار! إنه يصدر لكِ تعليمات مثل: «تعالي إلى هنا، كلي طعامكِ، لا تبكي». تقبّلي تجربته القيادية هذه بكل سرور، وأدّي دور طفلته بهدوء ومن دون اعتراض؛ فهذه إحدى أهم الطرق الأساسية لتنمية التعاطف.'),
  ('b97073a4-f745-41b1-953a-0e776ded1591', 'أطفئي الأنوار ليأتي النوم 🌙', 'لتساعدي طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بساعة واحدة. فالميلاتونين يُفرز بسرعة في بيئة مظلمة وخالية من التكنولوجيا.'),
  ('2fc82c8d-f425-4306-866a-3f621177b592', 'ناقد الرسوم المتحركة 📺', 'يروي لكِ بطريقته الخاصة أحداث الرسوم المتحركة التي شاهدها، ويشرح بجدية من ذهب وإلى أين. استمعي إليه باهتمام وكأنكِ مندهشة، ودعيه يشعر بأنه أذكى شخص في العالم.'),
  ('63daef22-cfd1-421f-8f7d-267873d17f9e', 'لا وجود للكمال 🛑', 'ألم يسر أي شيء اليوم وفق الخطة؟ لا تلومي نفسكِ. أنتِ أم حقيقية، ولستِ صورة وهمية منقّحة بفلاتر وسائل التواصل الاجتماعي. كل ما يحتاج إليه طفلكِ هو ابتسامتكِ واحتضانكِ.'),
  ('e3cb9a40-b6ca-4e32-b4da-ab6d4899625b', 'فكّ شفرة الرعب الليلي 😭', 'هل استيقظ طفلكِ في منتصف الليل باكيًا وعيناه مغمضتان، ولا يستجيب لأحد؟ تحققي من الأمر عبر تحليل البكاء؛ وإذا كان ما يحدث رعبًا ليليًا، فلا تحاولي إيقاظه. ابقي بجانبه فحسب وامنحيه شعورًا بالأمان بهدوء.'),
  ('10d94f4d-5823-4afc-963c-ff0397bf1a29', 'فقط احتضنيه 🫂', 'لا حاجة إلى أي لعبة أو كتاب أو حكاية. هذا المساء، ضمّيه إلى صدركِ فحسب، واستنشقي رائحته الجميلة، واهمسي له في الظلام كم هو غالٍ لديكِ.'),
  ('3860d960-f463-4c1e-873a-4917b9b7c101', 'كلمات خطرة 🤐', 'هل يكرر أمامكِ ضاحكًا تلك الكلمة السيئة التي سمعها في مكان ما، وينتظر رد فعلكِ؟ أقوى سلاح لديكِ هو عدم إبداء أي رد فعل. لا تضحكي ولا تغضبي، بل تجاهلي الأمر فحسب. وسينسى تلك الكلمة قريبًا.'),
  ('fbd7d1b9-4e13-463d-80fa-fbbd34869d9e', 'السماح بفوضى المنزل 🌪️', 'هل سئمتِ من جمع الألعاب نفسها كل يوم؟ لا تجمعيها اليوم! فالمنزل ليس متحفًا، بل مكان ينبض بالحياة. استريحي وركّزي على متعة طفلكِ في التعلّم بحرية بدلًا من التركيز على الفوضى.'),
  ('267500b1-a84b-4046-a247-9d2097325550', 'انظري إلى الأسفل، ماذا يكتشف؟ 👣', 'يستمتع طفلكِ بالمشي حافي القدمين وملامسة السجاد أو بلاط الغرفة. إن تحفيز الأعصاب الموجودة في باطن قدميه مهم جدًا لتوازنه ومهاراته الحركية، لذا دعيه يمشي من دون جوارب.'),
  ('2b6e6b05-f741-49ca-84e3-fa8deb8b2661', 'استراحة للزوجين 🥂', 'نام طفلكِ. ضعي الآن الأعمال المنزلية جانبًا، وتحدثي مع شريككِ لمدة 20 دقيقة على الأقل عن أي موضوع آخر غير الطفل والمصاريف. فأنتما أيضًا زوجان!'),
  ('8fdbd74e-0b03-4420-a816-6a0ea6ecdb73', 'أصوات الأب الغريبة 🤡', 'عندما لا تعود محاولاتكِ مجدية، تنقذ أصوات الحيوانات الغريبة التي يصدرها الأب وتعابير وجهه المضحكة الموقف فورًا. في نوبات الانفعال المسائية، سلّميه المهمة واستمتعي من بعيد بمشاهدة الضحكات المرحة.'),
  ('b32c30b6-11a0-4afc-aed3-bdfb0cc56622', 'ثورة القيلولة 🥱', 'لا يريد الذهاب إلى السرير ويبكي؟ لا تجبريه. خفّفي الإضاءة في الغرفة وأعلني عن وقت هادئ لتصفّح الكتب، وابتكري روتينًا جديدًا يريحكما معًا، وهكذا تستريحان كلاكما.'),
  ('07209316-984c-477d-a3c0-ff2c7202c5fa', 'التفكير في الحضانة 🏫', 'هل تشعرين بأنه أصبح بحاجة أكبر إلى التفاعل الاجتماعي؟ وهل حان الوقت المناسب للحضانة؟ انضمّي إلى مجتمع Anacan واقرئي تجارب الأمهات الحقيقية في التأقلم لتسهّلي قراركِ.'),
  ('3f7992d5-c092-46f7-84f8-f10e51f36593', 'نوبة غضب مفاجئة 💥', 'هل غضب فجأة أثناء اللعب وبدأ يرمي ألعابه؟ لا يزال غير قادر على التحكم في مشاعره. بدلًا من الصراخ، تعاطفي معه وابقَي قريبة منه قائلةً: «أرى أنك غاضب، تعالَ لنتنفس بعمق معًا».'),
  ('a376f906-e66c-4618-827e-79f3b75ebd16', 'هل ينزعج عند إطفاء أضواء غرفة النوم؟ 🌙', 'ضعي مصباحًا ليليًا صغيرًا بلون دافئ في إحدى زوايا الغرفة. أما بقية الغرفة فيجب أن تظل مظلمة تمامًا ليحظى بنوم عميق.'),
  ('171bedf4-3516-44a5-9404-c089661d5bbd', 'التحدث إلى الجمادات 🗣️', 'قد يتحدث بجدية تامة إلى حجر في الحديقة أو كرسي في المنزل، بل ويوبّخهما. فهو يستوعب العالم من خلال اللعب الرمزي. احرصي على تسجيل هذه السيناريوهات المميزة في متتبّع النمو.'),
  ('a74f3aea-565f-455f-bdbe-9ee44f6c7e35', 'سحر الماء الدافئ 🛀', 'أحيانًا لا ينجح أي شيء، ويظل يبكي بسبب كل شيء. ضعيه في حوض استحمام مملوء بالماء الفاتر، وأضيفي إليه قليلًا من الرغوة. ستنشر قدرة الماء الساحرة على تخفيف التوتر السكينة فورًا في الغرفة وتهدّئ جهازه العصبي.'),
  ('b4c6b7ac-81bd-476f-9816-9e8c14627206', 'تنبيه الطقس ⛅', 'عند الخروج في نزهة، لا تدعي المنظر من النافذة يخدعكِ. استعيني بمساعد الطقس والملابس لاختيار الزي الأنسب للرياح ودرجة الحرارة الفعلية في الخارج، ثم اخرجي من المنزل مطمئنة ومستعدة، وأتيحي لطفلكِ فرصة تفريغ طاقته في الهواء الطلق.'),
  ('c583d30d-5142-4b40-bcb3-399830284928', 'السماح الكامل بالاتساخ 🏖️', 'هل يريد طفلكِ اللعب بالطين والرمل؟ دعيه يتّسخ! اختاري من قسم المنتجات الموصى بها مستلزمات سهلة التنظيف لهذه الأنشطة الداعمة للنمو الحسي، وأطلقي له العنان.'),
  ('0446eb50-5fac-4056-ad65-76a95baf67f3', 'مواجهة الظلال 👻', 'هل يخاف من ظلّه على الحائط ويختبئ خلفكِ؟ فالخيال لا يعرف حدودًا. أظلمي الغرفة واستخدمي مصباحًا يدويًا لصنع أشكال ظلّ بيديكِ على الحائط.'),
  ('b090e002-92d1-408a-8249-476d9566115b', 'الاستعداد للنوم بالموسيقى 🎶', 'جرّبي تهدئة نوبات المساء المفاجئة التي تبدو بلا سبب بتشغيل موسيقى كلاسيكية هادئة. غالبًا ما تصنع هذه الحيلة البسيطة والفعّالة المعجزات في المنزل، وتضفي على الغرفة سكينة مريحة.'),
  ('ba177a78-642c-483b-9a15-4d4a68a758af', 'نداء الجسد 🩸', 'لا تستسلمي للانزعاج والتعب من دون معرفة السبب. راجعي متتبّع الدورة الشهرية، فجسمكِ يرسل إليكِ إشارات. وبدلًا من لوم نفسكِ، استريحي وتناولي وجبة خفيفة غنية بالمغنيسيوم.'),
  ('1a2422fa-5d4e-4bbc-9f26-d69dd838496d', 'تغيير الكلمات عن قصد 🗣️', 'هل يصرّ على قول «رايسة» بدلًا من «سيارة» وينتظر منكِ أن تضحكي؟ لقد بدأ يكتشف حسّ الفكاهة. اضحكي معه، لكن لا تنسي أن تلفظي الكلمة الصحيحة بلطف في كل مرة، حتى يحفظ دماغه النطق الصحيح أيضًا.'),
  ('21b5ead3-32a1-4d0e-96a9-1e38bf19fcec', 'ماما، لا تنسي أن تأكلي 🥗', 'لقد طهوتِ له البيض بـ4 طرق مختلفة، لكن ماذا أكلتِ أنتِ؟ كافئي نفسكِ بطبق مميز من الوصفات الصحية، لا يستغرق تحضيره سوى 5 دقائق ويكون غنيًا بالحديد والكالسيوم، لتحافظي على طاقتكِ.'),
  ('cc6b3853-5963-47b7-b4f5-310bfd1919c2', 'حيلة تأخير موعد النوم ⏱️', 'هل يشعر فجأة بالعطش عند حلول موعد النوم، أو يطلب الذهاب إلى الحمّام، أو يبدأ بتوديع الحائط؟ اضبطي مؤقتًا، وطبّقي قاعدة «عندما يرنّ الجرس، ينام الجميع» لإنهاء سلسلة الوداع التي لا تنتهي بصبر وهدوء.'),
  ('629ea652-62bd-4947-96b6-0e7f4cabb751', 'اجتماع مع الألعاب 🧸', 'هل يصفّ كل دببته وسياراته ثم يشرح لها شيئًا بإصبعه بمنتهى الجدية؟ إنها بوادر تطوّر مهارات القيادة والانتباه. قفي في زاوية من الغرفة وراقبي اجتماعه الخيالي بصمت، من دون إزعاجه.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('9d8da9d6-f615-4275-a01c-20687a161090'::uuid, 'منقذ التسوق 🛒', 'هل تنسين دائمًا أهم غرض عندما تذهبين إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ ليشتريها زوجكِ بدقة في طريق عودته من العمل، ولا ترهقي ذهنكِ.'),
  ('2b451101-7b49-4ea1-a25f-f07ea36f7e85', 'تنفيس الغضب في المذكرات 📝', 'هل قال لكِ أحدهم: ما الذي يُتعبكِ وأنتِ في المنزل؟ افتحي فورًا مذكرات الحالة المزاجية واسكبي كل غضبكِ على الشاشة بأصابعكِ. تدوين مشاعركِ الحقيقية علاج بحد ذاته، وهو أفضل من اصطناع الابتسامة.'),
  ('5163d6f3-dfbf-4dc7-9c33-5c739a29b5c5', 'دعيني أشرح لكِ! ☝️', 'يأتي طفلكِ ليشرح لكِ شيئًا تعرفينه أصلًا، بملامح جادة وذكية للغاية. إنه يختبر معلوماته. ورغم أنكِ تحاولين جاهدة ألا تضحكي، استمعي إليه بكل جدية وأكّدي له صحة فكرته.'),
  ('62a5480b-e62d-48dc-a56f-7c512e104949', 'المقياس الرقمي للهدوء 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي عمّ المنزل. فعّلي أداة قياس الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واشعري بأن ذهنكِ يسترخي تدريجيًا.'),
  ('523ef85e-fa2f-49a1-b3f9-34f2d35d22a1', 'استطلاع الطقس ⛅', 'أجواء الخارج غير واضحة تمامًا؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا يمكنكِ ملاحظتها من النافذة، وبالملابس المناسبة.'),
  ('5b3dc48b-525e-45b8-ba47-dd1abb851741', 'يخلع حذاءه بنفسه 👟', 'هل أصبح إلباسه أشبه بمباراة مصارعة؟ ها هو يسحب جواربه وحذاءه ويخلعهما بنفسه. أُعجبي بمهاراته الحركية!'),
  ('cd7f1c0e-ee93-462d-ae3c-cb3021a5d6c8', 'دعم الأب 🫂', 'عند الاستيقاظ ليلًا، انهضي أنتِ مرة وزوجكِ مرة أخرى. اقتسما العبء بالتساوي تمامًا كفريق واحد.'),
  ('3522ca83-324c-49f9-ba7a-ffdc8c379ba2', 'الذهاب إلى الحمام لتأخير النوم 🚽', 'يكاد يغطّ في النوم، ثم يقول فجأة: أريد الذهاب إلى الحمام. تأخذينه، فلا يحدث شيء. إنها إحدى أدق حيل فن تأخير النوم. لا تصرخي، بل ضعي حدًا واضحًا: هذه آخر مرة نذهب فيها، ثم نعود مباشرة إلى السرير.'),
  ('2333a8bc-122b-4087-9603-3c895b2daf77', 'لا منطق للانتقائية في الطعام. 🥦', 'هل يرفض اليوم حتى تذوّق ذلك الحساء الذي كان يتناوله بشهية حتى الأمس؟ انتقلي إلى الوصفات الصحية، واكتشفي كيف تُخفين الخضراوات المهروسة في صلصات المعكرونة الملوّنة. أتقني فن التمويه.'),
  ('5e903417-88bd-42b5-bb8c-507e12e432bf', 'مملكة تحت الماء 🛀', 'لم يعد الاستحمام في حوض الاستحمام مجرد نظافة، بل أصبح مهمة غواصة. دعي الماء يتناثر في كل مكان. فتأثير الماء الساحر سيغسل كل تلك الطاقة السلبية والعنيدة التي تراكمت لدى طفلكِ طوال اليوم، ويأخذها إلى البالوعة.'),
  ('d3d2b281-0b44-4f04-8791-8ceca32ccdb3', 'المخترع العبقري 👟', 'يضع حذاءه على أذنه ويتحدث بجدية قائلًا: «ألو»، ثم يواصل كلامًا غير مفهوم. إنّه يبتكر وظائف جديدة للأشياء! لا تفوّتي توثيق هذا المشهد العبثي والعبقري. التقطي لهذا المخترع الطريف صورًا في جلسة تصوير لطفلكِ، وضعيها في أبرز مكان في ألبوم الذكريات.'),
  ('185309c1-aba3-48ec-9411-535c92af4024', 'علاج الصمت الرقمي 🤫', 'أخيرًا، خيّم على الغرفة صمت مطبق. لا تتعجّلي في ترتيب غسالة الصحون. فعّلي مقياس الصوت، وراقبي الأرقام على الشاشة وهي تنخفض حتى 0 ديسيبل، واشعري كيف يستعيد ذهنكِ المرهق صفاءه.'),
  ('4794fa88-36bd-4251-a4ea-871854d0d5ac', 'فنان يصنع المزيد من الفوضى ✂️', 'هل يمزّق كل ورقة نظيفة تقع بين يديه إلى ألف قصاصة صغيرة وينثرها في الغرفة؟ إنّه يدرّب مهاراته الحركية الدقيقة! لا تغضبي ولا تسرعي إلى المكنسة. اجمعي تلك القصاصات في صندوق والعبا معًا لعبة تساقط الثلج.'),
  ('bcbae78a-e00a-4482-8778-25c54ab9a376', 'المنافس في المرآة 🪞', 'يقف أمام المرآة ويقطّب حاجبيه لنفسه، ويصنع تعابير غاضبة وغريبة. إنّه يختبر كيف تبدو المشاعر على وجهه. راقبي بصمت وفضول تدريب هذا الممثل المسرحي الصغير.'),
  ('9ecbc8da-836b-48fc-a294-6aaa4bafb6f3', 'اشتياق إلى العزلة 🚪', 'لقد أتعبكِ طفلكِ الذي ظلّ يتسلّق جسدكِ ويتشبث بكِ طوال اليوم. دخلتِ الحمّام وأغلقتِ الباب، وبقيتِ وحدكِ لمدة 5 دقائق. افتحي فورًا يوميات المزاج، وأفرغي على الشاشة ذلك الشعور بالاختناق الذي بداخلكِ لتشعري بالارتياح.'),
  ('acb8e717-26b4-427c-9df9-4c6aeb16734c', 'مخرج الحكاية 🪄', 'لقد أرهق صوتكِ هذا المساء. افتحي الحكايات الذكية. قولي لطفلكِ: «أنت بطل الحكاية اليوم، والمطر يهطل في الخلفية»، واصنعي له أجواء صوتية خاصة وهادئة ومصممة من أجله، لتأخذيه برفق إلى عالم النوم.'),
  ('676880bc-91f2-426e-9b15-e2ce61b68fc4', 'المسافر بين الأسرّة 🛏️', 'يبدأ ليلته في سريره، ثم يستيقظ صباحًا في سريركِ، مستلقيًا بالعرض تمامًا وقدماه على وجهكِ. استقبلي استيلاءه على المكان بالضحك؛ فرائحتكِ الدافئة هي أكبر مساحة أمان له.'),
  ('bf74dbb7-0eae-47bc-acea-2beeb831e679', 'سحر الصندوق 📦', 'هل ألقى جانبًا تلك اللعبة الباهظة والصاخبة التي اشتريتها له، وأمضى 1 ساعة يلعب بعلبتها؟ لا يحب دماغ الطفل السيناريوهات الجاهزة، بل الأشياء الفارغة التي يستطيع ملأها بخياله. صندوق الكرتون بالنسبة إليه مركبة فضائية، فلا تلمسيه.'),
  ('42b797ef-b169-4515-ad62-c08b78bfdaca', 'تمرّد الصيف في الشتاء ❄️', 'الرياح تعصف في الخارج، لكنه يصرّ على ارتداء سرواله الصيفي القصير. محاولة الشرح مضيعة للوقت. افتحي أداة الطقس والملابس، وأريه على الشاشة رمز الطفل الذي يرتدي ملابس سميكة. حيلة «انظر، حتى الهاتف يقول إن علينا ارتداء السروال اليوم» فعّالة جدًا.'),
  ('74bf7168-d7dc-468c-87a3-562a3bef9f2a', 'قضمة خيالية 🍏', 'لا يحمل شيئًا في يده، لكنه يقترب منكِ ويمدّ إليكِ تفاحة خيالية قائلًا: «خذي، اقضمي». يُعدّ لعب الأدوار من أهم المساحات التي تتشكّل فيها الشخصية. اقضمي الفراغ بشهية كبيرة مع صوت قرمشة، وأكّدي له أنها ألذ تفاحة في العالم.'),
  ('d3d1367f-aa40-489c-9f91-b803403dff09', 'الوحش عند النافذة 👻', 'ينعكس في الغرفة ظل شجرة تتمايل في الخارج، فيشعر بالخوف ويختبئ خلفكِ. لا تشغّلي ضوء الغرفة. أمسكي مصباحًا يدويًا وسلّطيه نحو الظل، ثم قولي: «انظر، إنها الشجرة ترقص فحسب»، وحوّلي خوفه إلى سحر.'),
  ('2297d6cd-94fd-4ed9-af73-4f9ce43ef7d6', 'ماراثون «انظري إليّ!» 👀', 'هل قال لكِ فور استيقاظه صباحًا «ماما، انظري إليّ» 40 مرة بالضبط؟ إنه يقفز ويدور وينتظر استحسانكِ. أبعدي عينيكِ عن الهاتف، وانظري إليه بتركيز كامل لمدة 3 دقائق فقط، وقولي له: «أنت رائع». سيكون هذا الاهتمام المتواصل كافيًا لإشباع حاجته.'),
  ('4e536027-0b7a-4ac3-acef-a7ba874bd609', 'من حق الأم أن تتكاسل 🍕', 'هل تشعرين اليوم بأنكِ تريدين الصراخ بسبب كل شيء؟ هل المنزل في فوضى عارمة؟ دعي التنظيف جانبًا ولا تدخلي المطبخ. اطلبي بيتزا أو وجبة سهلة من الخارج. تخلّي عن وهم الأم المثالية؛ فصحتكِ النفسية أثمن بكثير من الطعام المنزلي.'),
  ('c57f5d91-caec-47eb-964d-abcee011e0e2', 'غيبوبة الزوجين 📺', 'نام الطفل! جلستِ أخيرًا مع زوجكِ على الأريكة لمشاهدة فيلم، لكنكما غفوتما بعد 10 دقائق فقط. هذا هو واقعكما. ذلك المشهد المتعب والجميل لنومكما متكئين أحدكما على الآخر هو الحب بعينه.'),
  ('bd96c118-6b22-4005-829a-5d2036e47887', 'المفاتيح المختفية 🔑', 'ألا تجدين مفاتيح المنزل؟ ابحثي في الثلاجة أو خزانة الأحذية. يختبر طفلكِ مفهوم بقاء الأشياء من خلال إخفائها. اختاري الضحك بدلًا من الانزعاج خلال رحلة البحث الطريفة هذه عن الكنز.'),
  ('c22e7a31-d31e-4595-845a-77f2550b33d1', 'سحر الهمس 🤫', 'يستلقي في السرير ويرفع ساقيه في الهواء، رافضًا النوم. بدلًا من الصراخ، اخفضي نبرة صوتكِ فجأة ولا تتحدثي معه إلا همسًا. وعندما يركّز طفلكِ ليسمعكِ، سيهدأ دماغه تلقائيًا وينتقل إلى وضع النوم.'),
  ('11c8bab9-c92e-47a2-b7c0-34d8c43e8735', 'راحة الذراعين 🫂', 'يؤلمكِ جسدكِ من تسلّقه عليكِ طوال اليوم وطلبه المستمر للعناق. في المساء، مرّري المهمة إلى الأب. فعندما يحمله على ظهره ويتظاهر بأنه حصان، تُلبّى حاجة طفلكِ إلى الاهتمام، وتحصل ذراعاكِ على الراحة التي تحتاجان إليها.'),
  ('5ddf0bc2-3619-404d-a56d-27e47d73626e', 'حفل الصباح 🎤', 'لم تشرق الشمس بالكامل بعد، لكنه يقفز على السرير ويغني بصوت عالٍ بلغة لا تفهمينها. نعم، ما زلتِ تشعرين بالنعاس، لكن طاقة الحياة التي تدور في الغرفة ستدفعكِ أنتِ أيضًا إلى النهوض. اكتفي بالابتسام لصوته.'),
  ('c7c4ce1e-98e4-4beb-992c-e1f8c9783567', 'الذكاء الاصطناعي المنقذ 🤖', '«ماما، إلى أين تذهب الشمس لتنام؟» هل أربككِ السؤال؟ لا تجعلي الشرح معقدًا. اطرحي السؤال على Anacan AI مع ذكر عمر طفلكِ، واحصلي على إجابة رائعة بأسلوب قصصي يستطيع عقل طفل في الثالثة فهمها بسهولة، ثم احكيها له.'),
  ('0daa509c-a73b-47b1-a76d-b85764cf98f2', 'دموع صامتة 💖', 'لقد دفعكِ إلى حافة الجنون طوال اليوم. لكنه الآن نائم في سريره ببراءة شديدة تجعلكِ تتأثرين وأنتِ تنظرين إليه، أليس كذلك؟ هذه بالضبط هي أكبر مفارقات الأمومة. وتلك الدمعة التي تنساب من عينكِ تعبّر عن امتنانكِ لوجوده.'),
  ('2d96922a-7550-4150-a8ed-19cdd56a8801', 'مهمة الطعام السرية 🥣', 'كان يحب البيض حتى الأمس، أما اليوم فلا تستطيعين إقناعه بتذوقه. لا تدخلي في صراع مع إرادته. كوني أنتِ الفائزة بتحضير وصفات صحية ووجبات خفيفة مبتكرة، تقدّمين فيها البروتين بأشكال مختلفة وملونة وممتعة.'),
  ('a6a15ff2-f8a6-4007-b1d8-974680e64a8d', 'انهيار المنطق 🛑', 'يصرخ مطالبًا بأن تقدّمي له الماء في الكوب الأحمر، وعندما تسكبينه فيه يبكي ويسألكِ لماذا سكبتِه هنا. لا مجال للمنطق في هذا الموقف. إنه متعب فحسب ويحتاج إلى تفريغ مشاعره بهذه النوبة. انتظري بهدوء، وستهدأ العاصفة من تلقاء نفسها.'),
  ('c58d19cd-28c0-452e-ab4b-85c75da1f2b0', 'أول نكتة بلا منطق 🤡', 'يقول: «ركب الكلب السيارة فانفجر!» ثم ينفجر ضاحكًا بمفرده. لا معنى للنكتة، لكنه بدأ للتو يكتشف حس الفكاهة لديه. لا تبحثي عن المنطق، بل شاركيه ضحكته البريئة والمرحة بصوت عالٍ.'),
  ('0a22f56d-c8f3-477d-a3c0-1cf48a52b75f', 'سياسة الزحليقة 🛝', 'يقف أعلى الزحليقة في الحديقة ولا يسمح للأطفال الآخرين باستخدامها. لا تشعري بالحرج ولا تسحبيه إلى الأسفل بقسوة. تجاهلي نظرات الآخرين وذكّريه بلطف بأن لكل طفل دوره. فهذه طريقته في حماية إحساسه بالملكية.'),
  ('2e61e71c-40b9-4acb-82fb-ac9b3ee6a222', 'لم يعد رضيعًا! 🌟', 'لقد أصبح إنسانًا متكاملًا له قراراته وأسئلته الغريبة وقلبه الكبير. اشكري نفسكِ كثيرًا لأنكِ تربّينه بالتوجيه من دون أن تحطّمي شخصيته القوية. أنتِ تقومين بعمل رائع.'),
  ('a5162fa5-e190-42b6-b85c-5309ce76b381', 'انتصار بلا شمبانيا 🥂', 'بعد يوم شاق، اسكبي الشاي الساخن العادي في الأكواب. اجلسي مع شريككِ وجهًا لوجه على الأريكة، وقولا: «لقد نجونا اليوم أيضًا من تلك الفوضى»، ثم ارفعا الكوبين احتفالًا. فأنتما قائدا المنزل وفريقه في الوقت نفسه.'),
  ('1681892e-80a4-445a-827d-19733c9c6b73', 'قوة المجتمع 💬', 'تستنزفكِ فكرة: «لماذا طفلي عنيد إلى هذا الحد؟». انضمّي إلى مجتمع Anacan. عندما تقرئين عن نوبات الغضب العبثية المشابهة التي تحدث في بيوت الأمهات الأخريات، ستدركين أنكِ لستِ وحدكِ وأن ما تمرّين به طبيعي تمامًا.'),
  ('450f109f-b886-4ee2-8c86-66186d74b732', 'إيقاع الأضواء 🌙', 'لمساعدته على النوم سريعًا، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بـ1 ساعة. يُفرَز الميلاتونين بسرعة في بيئة مظلمة وخالية من الأجهزة الإلكترونية، ما يسهّل عليكِ مهمة تنويمه.'),
  ('b4a0c1d1-e187-401c-89d3-83448ef5f879', 'فطور الديناصور 🦖', 'يريد في وجبة الإفطار أن يأكل مثل الديناصور، فيقرّب فمه مباشرة من الطبق من دون استخدام يديه. لا تحوّلي الموقف إلى درس في آداب المائدة! دعيه يكون ديناصورًا لمدة 5 دقائق؛ فسرعان ما سيملّ من اللعبة ويمسك الملعقة بنفسه.'),
  ('331d91d4-ea8d-4af5-be08-e82eb1b8836d', 'سرعة «سأفعلها بنفسي» 🐢', 'عليكِ الخروج من المنزل، لكنه يصرّ على ارتداء حذائه بنفسه، ويستغرق ذلك 15 دقيقة بسرعته السلحفائية. إن تدخلتِ، فقد تستمر نوبة البكاء 30 دقيقة. لا تركّزي على الوقت الضائع؛ انتظري وركّزي على الحفاظ على ثقته بنفسه.'),
  ('15c2879b-fa80-4ef3-b734-53366c8b7916', 'حبّ مفاجئ 🥰', 'يترك لعبته فجأة وهو يلعب، ويركض نحوكِ ويلفّ ذراعيه حول عنقكِ قائلًا: أحبكِ. هذه هي اللحظة السحرية التي تمحو كل ذلك الإرهاق والحرمان من النوم. ضمّيه بقوة إلى صدركِ واستنشقي رائحته بعمق.'),
  ('c0446dd4-cfe7-4c72-9419-07304cef46d7', 'حكاية الأب الغريبة 📖', 'صوتكِ متعب هذا المساء، لذا أوكلي مهمة قراءة الحكاية إلى الأب. سيبتكر قصة طريفة لا تمتّ بصلة إلى صور الكتاب، ويُغرق طفلكِ في نوبة من الضحك. أما أنتِ، فاستمتعي بمشاهدة هذا المشهد من بعيد مع كوب من الشاي.'),
  ('df2fef22-961b-4197-8f8b-a55345b6bbaa', 'عاصفة عربة التسوق 🛒', 'رغم أن عربة التسوق الكبيرة تفوقه حجمًا، فإنه يصرّ على دفعها بنفسه. وبدلًا من أن يبكي أمام الجميع، دعي يديه على طرف العربة ووجّهيها أنتِ بخفة ومن دون أن يلاحظ.'),
  ('1528a888-1cfa-4bf5-b2b7-c533244518f5', 'حرية الملابس المقلوبة 👗', 'ارتدى سرواله بالمقلوب ويقول بإصرار شديد: أنا ارتديته بنفسي. لا تهتمّي بالمظهر. فثقته المتنامية بنفسه وشعوره بالاستقلال أهم بكثير من ارتداء ملابسه بطريقة صحيحة. افتخري بهذا المتمرّد الصغير.'),
  ('3b7890c9-fcdd-4513-a90d-c39e56fa7a0a', 'قهوة وسط الفوضى ☕', 'بعثر جميع ألعابه في وسط الغرفة ليبني لنفسه قلعة. وكلما رتّبتِ تلك الفوضى، سيبعثرها من جديد. لذا توقفي عن المقاومة، واجلسي في أحد أركان الغرفة واحتسي قهوتكِ ساخنة، ثم تأمّلي الفوضى من بعيد واسترخي.'),
  ('903ab62c-4fd0-4ad9-9a8c-ad3cf62e1e9a', 'ظلال الغرفة 🐰', 'هل بدأ يخاف من الظلام؟ أظلمي الغرفة تمامًا، واستخدمي مصباحًا صغيرًا لصنع ألعاب ضوئية وظلال حيوانات على السقف. حوّلي الظلام الذي يخيفه إلى متعة ومغامرة استكشافية صغيرة تضحكان خلالها معًا قبل النوم.'),
  ('86b8fc9f-0ab7-4475-bc84-a0cb2dacfefd', 'أمل بنوم متواصل 🤞', 'نام طفلكِ وعمّ المنزل صمت عميق. وأمنيتكِ الكبرى هي ألا يستيقظ هذه الليلة. شغّلي بهدوء صوت حفيف الغابة الرقيق من جهاز الأصوات الخلفية، لمساعدته على البقاء في مرحلة النوم العميق.'),
  ('906c34fb-a999-448f-8756-7ba4d8fc80cd', 'مختبر الطبيعة 🍂', 'تشعرين بالضيق في المنزل، وطفلكِ متململ. تحققي من الطقس وملابسه، واحرصي على اصطحابه إلى الخارج. اجعلي مهمتكما ببساطة جمع الأغصان والأوراق الجافة، ليُفرغ طاقته وتخرجي أنتِ أيضًا من بين الجدران الأربعة وتتنفسي الصعداء.'),
  ('af0535a2-83d1-4838-8bfc-0cfb607ff2f5', 'أمّ الألعاب 🧸', 'يأتي صوت من الغرفة. تنصتين جيدًا، فتجدين طفلكِ يوبّخ دبدوبه بنبرة صوتكِ نفسها وبعباراتكِ ذاتها! إنه أفضل نسخة مصغّرة منكِ. إنها فرصة مثالية لترَي تصرفاتكِ من منظور خارجي.'),
  ('0300b128-8698-433f-8d28-7ef165f88a96', 'فطور لا يقبل المشاركة 🍳', 'يرفض تمامًا أن يعطيكِ شيئًا مما في طبقه، لكنه يأتي ويصرّ على تناول البيض من طبقكِ. يثق الأطفال دائمًا بخيارات والديهم أكثر. لا تقاومي، وقدّمي لقمتكِ بحب إلى هذا الأناني الصغير.'),
  ('334f9c8b-ef27-4cd7-845a-eb18706654fc', 'كارثة التسوق بلا قائمة 🛒', 'اعتمدتِ على ذاكرتكِ، ثم عدتِ إلى المنزل واكتشفتِ أنكِ نسيتِ شراء الحليب، أهم شيء لطفلكِ. ذهنكِ مثقل بما يكفي أصلًا. من الآن فصاعدًا، اعتادي تدوين ما تحتاجين إليه في قائمة التسوق بالتطبيق فور تذكّره، لتجنّبي نفسكِ التوتر.'),
  ('ea78fdb3-c1ec-46eb-bb72-f6ee58c3526f', 'محيط في حوض الاستحمام 🌊', 'لم يعد الاستحمام في الحوض من أجل النظافة، بل أصبح لعبة لصنع الأمواج. دعي الماء يتناثر في كل مكان. فتأثير الماء الساحر سيغسل كل تلك الطاقة السلبية والعنيدة التي تراكمت لديه طوال اليوم، ويصرفها بعيدًا، ويساعده على النوم بعمق.'),
  ('056e606b-664d-4a4e-94b5-81db6f2adf23', 'أنتِ مثالية 🛑', 'هل تلومين نفسكِ حين ترين على وسائل التواصل الاجتماعي أمهات يصنعن كل يوم أعمالًا فنية مع أطفالهن، ومنازلهن تلمع من شدة النظافة؟ لا تصدّقي تلك المرشحات. فبيتكِ الفوضوي والصاخب والحقيقي هو أدفأ وأكمل عشّ للحب بالنسبة إلى طفلكِ.'),
  ('156b6d8e-1bbe-4769-b258-c89d41a67564', 'حُجّة المحامي الصغير 🗣️', '«سآكل الشوكولاتة لأنني أصبحت كبيرًا». لقد بدأ يربط بين السبب والنتيجة ويحاول التفاوض معكِ وإقناعكِ! هذا دليل رائع على تطور مهاراته اللغوية. أثني عليه، لكن حافظي بلطف أيضًا على حدودكِ وقواعدكِ.'),
  ('838e23dd-ecaf-4568-9687-59518e77bc77', 'العلاج بالصمت 🤫', 'لقد نام أخيرًا! فعّلي مقياس الصوت، وراقبي الأرقام على الشاشة وهي تنخفض حتى 0 ديسيبل، واشعري كيف يصفو ذهنكِ المتعب وكيف يداعبكِ هذا الصمت المرئي برفق.'),
  ('1645ac24-40c0-4cef-8645-e26caf67a799', 'حادث في المطبخ 🧑‍🍳', 'بينما تفردين العجين، يأتي طفلكِ ويغمس يده في الدقيق، فيكسو كل شيء باللون الأبيض. نعم، عمّت الفوضى في المطبخ وازداد عملكِ. لكن التقطي فورًا تعبير وجهه الجاد والمنهمك باستخدام جلسة تصوير الطفل. ستزول الفوضى، لكن الذكرى ستبقى.'),
  ('58f0130e-9824-44fe-9963-a1e86c3e18cc', 'افتخري بنفسكِ 🚀', 'عندما تنظرين إلى الماضي، ترين كيف أصبح طفلكِ يتمتع بشخصية قوية. تأمليه طويلًا اليوم وافتخري بنفسكِ لأنكِ ربّيتِ إنسانًا رائعًا إلى هذا الحد.'),
  ('f65305c4-c08d-4180-9df9-53864d7df4a9', 'شكرًا لفريقكِ 🥂', 'لقد تجاوزتما يومًا آخر صعبًا وعاصفًا. بعد أن ينام طفلكِ، اسكبي كوبًا من الشاي لكِ ولشريككِ وقولي له: لقد ساعدتني كثيرًا اليوم، شكرًا لك. فالأبوة والأمومة تصبح أجمل حين تكون ضمن فريق متعاون ومتوازن، لا حين يتحملها شخص واحد.'),
  ('52fd1b46-da9f-4903-91e9-9855c04a5c68', 'بوادر التعاطف 🧸', 'هل يربّت على لعبته عندما تسقط ويقول لها: لا تبكي؟ إذًا بدأ شعوره بالتعاطف يتكوّن! احرصي على تسجيل هذه المرحلة اللطيفة في متتبّع التطور.'),
  ('8cc847d7-8dbe-41eb-84d4-4cb88879af35', 'ملابس بالمقلوب 👗', 'هل يصرّ على ارتداء القميص الذي بيده بحيث يكون ظهره إلى الأمام؟ لا تدخلي في صراع معه. دعيه يتجوّل في المنزل هكذا ليوم واحد، ولا تكسري إرادته.'),
  ('8ec0eb18-27f1-4127-9c31-f0777f9a4904', 'نحن فريق واحد! 💖', 'بعد يوم شاق، اجلسي وجهًا لوجه مع شريككِ وتحدثا عما يثقل قلبيكما. فدعمكما المتبادل يقسم العبء إلى النصف تمامًا.'),
  ('47e4625b-1969-49f3-9819-a17d4bddc0c8', 'هندسة البطانية 🛏️', 'يكاد يغطّ في النوم، ثم يبدأ فجأة بالبكاء: طرف البطانية مطوي! إن استقامة البطانية بدقة المليمتر مسألة مصيرية بالنسبة إليه. خذي نفسًا عميقًا، وسوّي البطانية كأنها مكوية، واكتفي بالابتسام لهذا التدقيق المضحك.'),
  ('743bf968-dea7-4d72-ac2d-22654230f0a2', 'صمت مريب 🤫', 'خيّم فجأة صمت عميق على المنزل. يشير مقياس الصوت إلى 0 ديسيبل. إذا كان طفلكِ صامتًا، فهذا يعني أن عملية استكشاف كبيرة تجري في مكان ما. ادخلي الغرفة وأنتِ مستعدة نفسيًا لرؤية رسومات على الجدران أو أوراق مقصوصة.'),
  ('9fa0703c-5759-4d65-aa22-1042aa7b5843', 'لا تدخلي في جدال. 💼', 'لن آكل تلك العصيدة لأنها صفراء! سيقدّم منطقًا عبثيًا متماسكًا ومقنعًا إلى درجة أنكِ ستشعرين بالذنب تقريبًا. لا تدخلي في جدال. قولي له: معك حق، إنها صفراء. ما رأيك أن نضيف إليها بعض حبات التوت الأحمر؟ وهكذا أرضي المحامي الصغير.'),
  ('15c2d5ec-3e4a-4b1d-b6d2-a891cc587847', 'معركة الماء مع الأب 🛁', 'هذا المساء، طقوس الاستحمام مسؤولية الأب بالكامل. دعيهما يرشّان الماء في كل مكان، واستمتعي أنتِ بالهدوء التام خلف الباب.'),
  ('2054a805-49e3-459b-8315-84f392392707', 'تمرّد خزانة الملابس 🥽', 'يريد التجول في المنزل مرتديًا نظارة سباحة وقبعة شتوية. يصرّ على ذلك ويرفض خلعهما. انسي الأعراف الاجتماعية، ودعيه يقضي يومه بهذه الإطلالة المختلفة والمضحكة حتى لا تحدّي من إبداعه وحريته في اتخاذ القرار.'),
  ('5be61e62-9e95-417b-9db3-15386a93c72a', 'مفاجأة عربة التسوق 🛒', 'عندما اقتربتِ من صندوق الدفع، وجدتِ في عربة التسوق 3 أنواع مختلفة من الشوكولاتة و1 قطعة صابون غريبة الشكل لم تختاريها. أعيدي تلك الأغراض إلى مكانها بحركة سريعة. ولتجنّب النسيان، أبقي عينيكِ دائمًا على قائمة التسوق حتى لا تحيدي عن هدفكِ.'),
  ('22ac2508-9b42-4e19-b15b-cc1dca8c750b', 'جهاز السمع متوقف 🙉', 'تقولين: «اجمع ألعابك، تعال واغسل يديك»، لكن لا استجابة على الإطلاق. التظاهر بعدم السماع هو الهواية المفضلة في سن 3 سنوات. بدلًا من الصراخ، اقتربي منه واهمسي في أذنه بصوت خافت جدًا. سيجذب التغيّر المفاجئ في نبرة صوتكِ انتباهه فورًا.'),
  ('4bb7714f-90ea-44a6-8f84-3a989d3c428e', 'ابتزاز وقت الاستحمام 🛀', 'كان يبكي عند دخوله، والآن يصرخ لأنه لا يريد الخروج من الماء. لقد سحره تأثير الماء المغناطيسي. نبّهيه قبل 3 دقائق واضبطي المؤقت. طقوس «عندما يرن الجرس، ينتهي اللعب» تنجح دائمًا.'),
  ('a6053646-98c9-47f9-ae28-32c8e38f416e', 'مصمم الطعام 🥦', 'يفصل الأطعمة في طبقه حسب ألوانها وأشكالها، ويدفع الخضراء منها إلى حافة الطاولة. استعيني بخطة التغذية. اربحي هذه اللعبة باكتشاف كيفية تحويل تلك الخضراوات إلى هريس غير مرئي وإخفائها في أقراص اللحم والصلصات.'),
  ('454d0433-fa13-4bd5-95fe-c40365aff560', 'كبير أطباء المنزل 🩺', 'يأخذ سماعته الطبية اللعبة ويضعها على صدركِ، ثم يقطّب حاجبيه ويقول: «تنفّسي». أنتِ المريضة المطيعة. حوّلي لعبة الأدوار هذه إلى فرصة؛ أغمضي عينيكِ واستلقي على الأرض فحسب طوال الفحص الذي يستغرق 3 دقائق، وأريحي ظهركِ.'),
  ('603f7d3e-e83f-41b9-ade3-bd0fa858fbaf', 'أحبال الأب الصوتية 📖', 'صوتكِ متعب اليوم وحلقكِ جاف. سلّمي مهمة حكاية المساء إلى الأب. سيُغرق الطفل في الضحك وهو يروي قصة مضحكة وخيالية تختلف تمامًا عن الصورة الموجودة في الكتاب. أما أنتِ، فاستمتعي بمشاهدة هذا المشهد الجميل من بعيد مع كوب من الشاي الدافئ.'),
  ('e4995ac6-5e09-45b3-8f40-851f3616a9f6', 'مرحلة «ماما، انظري!» 👀', 'يقفز طفلكِ من الأريكة ويكرر الحركة نفسها 50 مرة بالضبط، وهو يقول في كل مرة: «ماما، انظري إليّ!». ارفعي عينيكِ عن الهاتف. إنه لا يقفز من أجل الحركة نفسها، بل من أجل بريق الاستحسان الذي يراه في عينيكِ. امنحيه 5 دقائق كاملة من انتباهكِ دون مقاطعة، حتى يشبع حاجته إليه.'),
  ('41b57fa8-5ee9-47c4-bdaf-6650d5ddc287', 'تنويم بالموسيقى 🎶', 'بدأت نوبات الغضب والبكاء التي تندلع بلا سبب في أواخر النهار. أطفئي التلفاز، وخففي الإضاءة، وشغّلي في الغرفة موسيقى كلاسيكية هادئة جدًا. ستغيّر ترددات الموسيقى العميقة أجواء المكان بطريقة ساحرة، وتنشر السكينة في الغرفة.'),
  ('bfa22ff0-d771-4756-a950-034bebcc6d6a', 'كاتب سيناريو الرسوم المتحركة 📺', 'يروي لكِ طفلكِ أحداث فيلم الرسوم المتحركة الذي شاهده بحبكة مختلفة تمامًا وبأسلوب مقنع إلى درجة أنكِ تكادين تصدقينه. إن خياله الرائع آخذ في التشكّل.'),
  ('d113ec32-8781-4153-b853-ad718dad74e9', 'زر إعادة الضبط للأم 🚪', 'الضجيج يخترق رأسكِ، وتشعرين برغبة في الصراخ بسبب كل شيء. افتحي مفكرة الحالة المزاجية، واكتبي فيها بحرية كل ما تشعرين به من إنهاك. سيساعدكِ هذا العلاج الرقمي القصير على استعادة توازنكِ من جديد.'),
  ('0b46f253-2b1f-4b21-b471-54a500b94e42', 'رقصة مع الظلام 🌙', 'لمساعدة طفلكِ على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بساعة واحدة. يُفرَز الميلاتونين (هرمون النوم) بسرعة أكبر في بيئة مظلمة وخالية من الأجهزة التكنولوجية، ما يسهّل الانتقال إلى النوم.'),
  ('53f4b2ce-2dcb-457d-bccf-d9242c156c63', 'كنز الشارع 🍁', 'يعرض عليكِ طفلكِ بفرح غطاء زجاجة متسخًا وجده على الأرض أو حجرًا ذا لون مميز، وكأنه عثر على ذهب. بدلًا من أن تقولي له: «ارمه، إنه متسخ»، قولي: «يا له من لون غريب! تعالَ نغسله في المنزل»، وقدّري شغفه بالاكتشاف.'),
  ('d8d7f0fc-2a92-4098-ba6e-6f7e5e3ee95f', 'عادت ساعة الفلسفة 🤔', 'لماذا تهب الرياح؟ لماذا تتساقط الأوراق؟ أسئلة فلسفية عميقة ترهق ذهنكِ منذ الصباح الباكر. لا تعقّدي الشرح، بل فسّري له الطبيعة بلغة قصصية يستطيع فهمها. نبرة صوتكِ هي أكثر الطرق أمانًا بالنسبة إليه لفهم الكون.'),
  ('4a8b061c-822f-4468-b267-6996ffaeb6d8', 'حفل موسيقي في المطبخ 🥄', 'يُخرج طفلكِ القدور والملاعق الخشبية ويقيم حفلًا موسيقيًا في وسط المطبخ. ورغم أن رأسكِ قد يؤلمكِ، فإن هذا جزء من تطور إحساسه بالإيقاع وإبداعه. لا تتدخلي على عجل، ودعي موجات تلك الطاقة الجامحة تملأ الغرفة لبضع دقائق.'),
  ('79b03a5c-cc04-4f7b-9361-f8120f787406', 'العزاء في المجتمع 💬', 'تراودكِ فكرة: لماذا طفلي عنيد إلى هذا الحد؟ وتؤرقكِ من الداخل. انضمي إلى مجتمع Anacan. عندما تقرئين عن نوبات الغضب العبثية المشابهة التي تحدث في بيوت الأمهات الأخريات، ستدركين أنكِ لستِ وحدكِ، وأنكِ تربّين طفلًا طبيعيًا وسليمًا تمامًا.'),
  ('c0b67368-8315-449a-b685-71a8e309a2c6', 'دفء أنفاسه 💖', 'لقد دفعكِ إلى الجنون طوال اليوم، وبكى بسبب كل شيء. لكنه الآن مستلقٍ في السرير وملتصق بصدركِ، وتملأ الغرفة أنفاسه الدافئة المنتظمة. هذه هي أعظم مكافأة للأمومة. ضمّيه إلى صدركِ، واشعري بكل تعبكِ يتلاشى مع أنفاسه.'),
  ('07a807e7-5500-4214-ab98-d5372a84c109', 'ثمرة العمل الجماعي 🥂', 'لقد اجتزتما يومًا آخر صعبًا وعاصفًا. بعد أن ينام طفلكِ، اسكبي كوبًا من الشاي لكِ ولشريككِ، وقولي له بامتنان: «لقد نجونا اليوم أيضًا من هذه الفوضى، نحن فريق رائع». فالأبوة والأمومة تصبحان أجمل بالدعم، لا عندما يتحمل أحدكما المسؤولية بمفرده.'),
  ('7715199a-4ef6-480d-9548-a833acc549dd', 'الحذاءان بالمقلوب 👟', 'ارتدى حذاءيه بالمقلوب، لكنه يمشي بفخر شديد وكأنه فتح العالم. إذا تدخلتِ وحاولتِ تصحيح وضعهما، فستفسدين كل شيء. ثقته بنفسه واستقلاليته أهم من المظهر. دعي هذا المتمرد الصغير يخطو بفخر.'),
  ('b205ec5f-9776-4abd-8a5c-b967e050819e', 'فوضى في المطبخ 🧑‍🍳', 'بينما تفردين العجين، يأتي ويغمس يده في الدقيق، فيغطي البياض كل مكان. نعم، عمّت الفوضى المطبخ. لكن سارعي إلى توثيق ملامح وجهه الجادة والمنهمكة باستخدام جلسة تصوير الطفل. ستنتهين من التنظيف، أما تلك اللقطة الطريفة فستبقى إلى الأبد.'),
  ('18bd2439-9788-43c4-81c5-8852d0241a0d', 'مرآة حية 🦜', 'إنه يوبّخ لعبته مقلّدًا تمامًا تعابير وجهكِ عندما تغضبين. راقبي نفسكِ فورًا من الخارج! فهو يقلّد كل ما يراه. هذا المشهد الطريف الذي يدعو إلى التأمل مرآة رائعة تساعدكِ على الانتباه أكثر إلى تصرفاتكِ.'),
  ('57b60f69-46b8-4792-b8f6-95c7ec477f5b', 'أنا في الحكاية الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب وتعبتِ من قراءتها. افتحي الحكايات الذكية، واجعلي طفلكِ بطل القصة وأصوات الغابة الهادئة خلفية لها، لتصنعي جلسة نوم استثنائية لا تتطلب منكِ أي جهد.'),
  ('8391ff6e-4225-4aa9-9011-6c07f64cfe8a', 'هواء نقي ⛅', 'تحققي من الطقس وملابسه، واحرصي على اصطحابه إلى الخارج. اجعلي مهمته جمع الأغصان الجافة والحجارة؛ فيفرّغ طاقته، وتتحررين أنتِ أيضًا من البقاء بين أربعة جدران وتتنفسين بعمق.'),
  ('1d548457-d3f9-490c-889a-735e0fede3a4', 'الهجرة في السرير 🛏️', 'ينام بوضعية صحيحة ليلًا، ثم يستيقظ صباحًا وقدماه على الوسادة ورأسه في الزاوية المقابلة تمامًا من السرير. إنه يستكشف العالم حتى في نومه! استمتعي بمشاهدة هذه الهجرة الطريفة في السرير واضحكي قبل أن توقظيه.'),
  ('9fa8e885-34cc-4a52-b9b9-6155faa47396', 'تأجيل النوم الفلسفي 🦉', 'ما إن يدخل السرير حتى يطرح أسئلة عميقة مثل: ماما، لماذا لا تسقط النجوم؟ هدفه ليس تعلّم العلوم، بل تأجيل النوم. قدّمي إجابات قصيرة وخيالية ولطيفة، ثم انشري فورًا هدوء النوم في الغرفة مع الحكايات الذكية.'),
  ('b5e65866-a678-4ef1-91b0-5f12331c2cae', 'البطل المتنكّر 🦸‍♂️', 'هل يصرّ على التجوّل داخل المنزل بحذاء شتوي أو قناع بطل خارق؟ دعي معايير المجتمع وقواعد الأناقة جانبًا. فهذا جزء من اكتشافه لشخصيته. دعيه يشعر بأنه بطل وهو يتجوّل بحذائه في الغرفة.'),
  ('0497aa5e-024a-43eb-ba38-bda044dfec73', 'أسنان الديناصور 🦖', 'يرفض بشدة تنظيف أسنانه ويرمي الفرشاة؟ حوّلي الأمر إلى لعبة! أعطيه فرشاة احتياطية وقولي: لننظف أولًا أسنان ديناصورك اللعبة. وبينما ينظف أسنان الديناصور، نظّفي أنتِ أسنانه بحيلة لطيفة.'),
  ('2824815e-ab93-4e74-b868-7dee6ae3bcac', 'بقع الاستقلالية 🥣', 'يصرّ على تناول الزبادي بالشوكة فيتّسخ كل شيء. لا تتدخلي ولا تنتزعي الشوكة من يده. يمكن تنظيف الطعام المسكوب، لكن من الصعب استعادة شعوره بأنه «يفعل ذلك بنفسه». ألبسيه مريلة من السيليكون وراقبي المشهد بصبر.'),
  ('33c034f1-168d-424b-b367-21b9eb4799c9', 'دقائق الأم الـ10 🚪', 'لقد خدّر الضجيج عقلكِ. افتحي يوميات المزاج، وأفرغي بحرية على الشاشة كل ما دفعكِ إلى الجنون اليوم، ثم اضغطي زر إعادة الضبط الداخلي لديكِ.'),
  ('1fc95e57-80a1-42af-8907-c939c12adef9', 'جاذبية سلة المهملات 📦', 'رغم وجود الكثير من الألعاب الباهظة والمضيئة، يذهب ليلعب ساعات بزجاجة ماء بلاستيكية فارغة أو صندوق من الورق المقوّى. لا يحب خيال الطفل السيناريوهات الجاهزة، بل يفضّل الأشياء البسيطة المفتوحة أمام الإبداع. راقبي وتعلّمي.'),
  ('61bc311a-ba5b-43dc-b36e-6a65967f1df0', 'ثورة الأحلام ☁️', 'بمجرد أن يستيقظ صباحًا، يعبس في وجهكِ ويغضب منكِ. والسبب؟ لأنكِ لم تعطيه اللعبة التي أرادها في حلمه! لا يزال دماغ الطفل عاجزًا عن التمييز تمامًا بين الحلم والواقع. اعتذري له بجدية، وابتسمي في سرّكِ لهذا الموقف العبثي.'),
  ('c193e688-7d18-417e-aa1d-53580a727596', 'نظرات صامتة 🥂', 'نام طفلكِ أخيرًا. جلستِ أنتِ وشريككِ جنبًا إلى جنب على الأريكة، ولم تعد لديكما طاقة حتى للكلام. تنظران إلى بعضكما في صمت وتبتسمان فحسب. نعم، هذه النظرات الصامتة هي أجمل طريقة لتقولا: نحن ننجح في التعامل مع هذه الفوضى.'),
  ('98f98e2b-5170-4983-96d7-fe8b44837cdf', 'مسرح الظلال على الحائط 🐰', 'يتذرع بخوفه من الظلام ليهرب من السرير. أطفئي جميع أضواء الغرفة، وشغّلي المصباح اليدوي، واصنعي بيديكِ على الحائط ظلالًا لطيور وكلاب. خلال ثوانٍ، سيتحول الظلام الذي يخشاه إلى أكثر مسارح العالم أمانًا بالنسبة إليه.'),
  ('bf60fea7-a806-46ec-a023-ae8a1e62e95a', 'حيلة مغادرة الحديقة 🌳', 'حان وقت العودة من الحديقة، وبدأت نوبات البكاء. لا تحاولي سحبه بالقوة. اصنعي جوًا من المنافسة بقولكِ: لنرَ مَن سيصل إلى السيارة ركضًا أولًا؟ فالأطفال لا يرفضون أبدًا السباق والفوز.'),
  ('e6013d08-4f44-4955-a2ce-c8556d1e2010', 'الضيف غير المرئي 👻', 'يصرّ أثناء الإفطار على أن تضعي طبقًا لصديقه الخيالي أيضًا. هذا ليس دليلًا على فراغ نفسي، بل قفزة في تطور ذكائه. ضعي ذلك الطبق، واسكبي لضيفكِ بعض الشاي الخيالي، وكوني جزءًا من هذا العرض الرائع.'),
  ('3cde3483-1ec6-4721-b8a3-2803d38e22f1', 'اكتشافات لغوية جديدة 🗣️', 'يبتكر للأشياء أسماء جديدة تمامًا من خياله، ولا وجود لها في أي لغة. ويصرّ على أن تستخدمي أنتِ أيضًا تلك الكلمات! افتحي متتبّع التطور، واحرصي على تسجيل كلماته الطريفة لتقرئيها وتضحكي عليها في المستقبل.'),
  ('50316f93-f1fa-4052-831d-66931b46940d', 'كنوز المنزل المخفية 🔑', 'ألا تجدين مفاتيح المنزل أو جهاز التحكم؟ اذهبي وابحثي داخل فرن الألعاب أو تحت سريره. إنه يختبر العالم من خلال إخفاء الأشياء. وفي رحلة البحث الطريفة عن الكنز هذه، اختاري الضحك وأخذ نفس عميق بدلًا من الغضب.'),
  ('e6c3f535-9f72-4297-8076-fd7145c977da', 'مفارقة الاستحمام 🛀', 'كان يبكي لأنه لا يريد دخول حوض الاستحمام، والآن يصرخ لأنه لا يريد الخروج منه! لقد سحره تأثير الماء المهدئ. وحتى لا يتحول خروجه من الماء إلى مشهد درامي، سمّي المنشفة «العناق الدافئ»، ثم لفّيه بها وأخرجيه.'),
  ('0d31e21b-368c-475e-b2bc-811f2bd6c64c', 'إصرار «هذا لي!» 🧸', 'يحتضن أي غرض عشوائي في المنزل ويصرخ: هذا لي! ويرفض إعطاءه لأي شخص. إنه يستكشف حدود الملكية. لا تتهميه بالأنانية، بل اعتبري ذلك الغرض ملكًا له في تلك اللحظة فحسب.'),
  ('81e2b129-a3fd-4f20-b3aa-69e3df1d9014', 'نبرة صوتكِ 🌙', 'إنه لا يصغي إلى حبكة الحكاية في الكتاب، بل إلى نبرة صوتكِ. انسي الحبكة هذا المساء. أطيلي الحكاية واقرئيها بصوت خافت كأنها موسيقى هادئة، لترسلي مباشرةً إلى جهازه العصبي إشارة تدعوه إلى النوم.'),
  ('92e01489-6842-4c96-9e36-b31b3377a1e1', 'وهم وسائل التواصل الاجتماعي 📱', 'هل ترين الأمهات المثاليات على الإنترنت وتلومين نفسكِ على فوضى منزلكِ؟ توقفي. لا تصدّقي مقاطع الفيديو المفلترة التي لا تتجاوز مدتها 15 ثانية.'),
  ('267b7226-68df-4c3e-8db0-91462616e5aa', 'ديسيبل الصمت 🤫', 'لقد نام أخيرًا! لا تهرعي إلى ترتيب الغرفة. فعّلي أداة قياس الصوت وانظري إلى رقم 0-10 ديسيبل الظاهر على الشاشة. سيمنح ذلك التأكيد البصري على الصمت التام في المنزل دماغكِ المتعب إحساسًا يشبه أجمل تدليك.'),
  ('9a9573ec-71e1-4545-84fd-a3a1f5b2af6b', 'أستاذ الفلسفة 🧐', 'إنه لا يسأل: «ماما، لماذا الشمس هناك؟»، بل يسأل ببساطة: «لماذا الشمس موجودة؟». تزداد أسئلته تجريدًا يومًا بعد يوم. لا ترهقي ذهنكِ بمحاولة تقديم شروح علمية لساعات. فإجابة قصيرة ودافئة تشبه الحكايات، مثل: «لأنها تحب أن تمنحنا الدفء»، ستُرضيه تمامًا.'),
  ('c8cadde3-c829-4a73-89c2-d28ffc494046', 'الساقان في إجازة 🚶‍♂️', 'يجلس فجأةً على الأرض في منتصف الشارع ويقول: «ساقاي مكسورتان، احمليني». لا، إنه ليس متعبًا، بل يختبركِ فحسب. لا تستسلمي لابتزازه. قولي له: «لنرَ كيف سنمشي مثل البطريق حتى نصل إلى السيارة؟»، وحوّلي الأمر إلى لعبة.'),
  ('d2c59147-ed1d-426c-a22f-74bab5a93a1b', 'حمية ملوّنة 🥕', 'قرر اليوم ألا يأكل سوى الأطعمة البرتقالية اللون، ويرفض كل شيء آخر. ها هو منطق الأطفال يعمل مجددًا! اكتشفي كيف يمكنكِ إخفاء الخضراوات في وصفات صحية. وتغلّبي على هذا العناد بوصفات متنوعة مُحضّرة من هريس اليقطين والجزر.'),
  ('d7d30904-6d53-4964-8b13-c4680a8d7346', 'مطرب الصباح 🎤', 'منذ الصباح الباكر، وبينما تكادين تفتحين عينيكِ، يقيم حفلةً في وسط الغرفة ممسكًا بلعبته. لا تحاولي إسكاته. فهذه الطاقة الجامحة التي لا تنضب لدى الأطفال تجلب في الحقيقة البركة والبهجة إلى المنزل. انظري إليه وابتسمي.'),
  ('e2fc49a4-e751-47d3-a247-fa5b6429b0ca', 'لمسة شافية 💆‍♂️', 'لا يهدأ في السرير مهما حاولتِ. ضعي الحكاية والموسيقى جانبًا. دلّكي ساقيه الصغيرتين أو ظهره بلطف شديد وبحركات ناعمة. فالتلامس الجسدي سيخفّض فورًا مستوى الكورتيزول (هرمون التوتر) في جسمه وجسمكِ، ويساعدكما على النوم.'),
  ('297d6ab5-a5e9-4978-98b2-bd85528e89d5', 'فتات غير مرئي 🧹', 'تمسك مكنسة صغيرة وتنظف بها الغبار غير المرئي عن السجادة بملامح شديدة الجدية. إنها ببساطة تقلّدكِ. التقطي صورة لهذه اللحظة المليئة بالمسؤولية ضمن جلسة تصوير طفلكِ؛ فأصغر عاملة نظافة في المنزل وألطفها منهمكة في عملها.'),
  ('79e7bb66-f1dd-4164-bbd9-7c802b073b10', 'علاج مقياس الصوت 🤫', 'لقد استسلم أخيرًا ذلك الإعصار الصغير الجامح في المنزل للنوم. لا يُسمع في الغرفة سوى صوت غسالة الصحون. افتحي تطبيق قياس الصوت، وأغمضي عينيكِ بينما تتأملين أرقام الديسيبل المنخفضة على الشاشة. هذا الهدوء البصري هو أفضل تدليك لعقلكِ.'),
  ('fee25f48-2972-4bf2-9d26-d0fbea33a7f3', 'استيقاظ على طريقة القطط 🐾', 'هذا الصباح، طفلكِ ليس إنسانًا؛ بل يمشي على أربع، ويتمسّح بساقكِ، ولا يتواصل إلا بالمواء. إنها ذروة الخيال في ألطف صوره. وبدلًا من وضع القواعد، قدّمي له أنتِ أيضًا وعاءً خياليًا من الحليب واستمتعي بهذه اللعبة.'),
  ('0d53c056-84aa-4820-a905-2f2e60542791', 'بوح في المجتمع 💬', 'هل صرختِ اليوم بسبب كل شيء وشعرتِ بأنكِ أقل أمهات العالم صبرًا؟ أرجوكِ تذكّري أنكِ لستِ وحدكِ. ادخلي إلى مجتمع Anacan واقرئي كيف شعرت أمهات أخريات اليوم بالإرهاق نفسه، ودعي شعوركِ بالذنب يهدأ.'),
  ('844a3d1a-225d-46c7-945c-c5eaf88248c4', 'حكاية الأب المجنونة 📖', 'هذا المساء، لن يكون صوتكِ هو الذي يملأ الغرفة. أعطي كتاب الحكايات للأب، ودعيه يروي القصة عمدًا بصورة معكوسة ومضحكة وعبثية. وراقبي من بعيد كيف يستمتع طفلكِ بتصحيح كلامه ويقهقه ضاحكًا معه.'),
  ('c862c51e-5b03-4e55-bd66-35165e58d3d8', 'مهندس معماري طليعي 🥞', 'يرصّ فطائر الإفطار فوق بعضها ليبني برجًا، ثم يثقب وسطه ويمرّر إصبعه من خلاله. اللعب بالطعام بالنسبة إليه مشروع هندسي جديد. تغاضي عن اتساخ المائدة؛ فهكذا يستكشف قوام الطعام.'),
  ('772055c7-02e3-4df1-ab25-b0a7ed011afe', 'متجر خيالي 🍅', 'يجمع ألعابه في زاوية من الغرفة ويبيعكِ حبة طماطم خيالية مقابل نقود خيالية. تعاملي مع لعبة البيع والشراء هذه بجدية تامة. اشتري حبة الطماطم الخيالية وتظاهري بأنكِ تأكلينها بشهية. يُعدّ لعب الأدوار من أقوى أسس ذكائه الاجتماعي وتفكيره الرياضي.'),
  ('9c4fcd9f-eca4-4781-b7b6-58a379dc2126', 'شوكولاتة الأم السرية 🍫', 'أيتها الأم التي تأكل قطعة شوكولاتة سرًا خلف خزانة المطبخ بعيدًا عن عيني طفلها، إن تلك الجرعة من الغلوكوز من أبسط حقوقكِ. فأنتِ أيضًا بحاجة إلى شحن طاقتكِ كي تتحملي طوال اليوم كل ذلك النشاط وأسئلة «لماذا؟» التي لا تنتهي. خذي نفسًا عميقًا وامضغيها باستمتاع.'),
  ('a0a70ea3-00c4-4338-848e-bcb45a1157ff', 'الفزع الليلي 😭', 'هل يستيقظ طفلكِ في منتصف الليل باكيًا وعيناه مغمضتان، ولا يستجيب لأحد؟ تحققي من ذلك باستخدام تحليل البكاء؛ وإذا كان فزعًا ليليًا، فلا تهزّيه ولا تحاولي إيقاظه. ابقي بجانبه بهدوء وامنحيه شعورًا بالأمان، وسيمر الأمر.'),
  ('2d19f095-845a-4bde-a575-de7451355856', 'منطق بارد كالثلج 🥶', 'هل يفتح طفلكِ الثلاجة ويطلب قالب الثلج، ثم يرفض تركه رغم برودة يديه؟ إنه يختبر مفهومي الدفء والبرودة بجسده. ضعي ماءً فاترًا في وعاء وماءً مثلجًا في آخر، وحوّلي هذا الاكتشاف إلى تجربة علمية صغيرة؛ وسيتخلى عن عناده فورًا.'),
  ('5b70990d-933c-46b2-be30-1407db2c7b1b', 'الخروج إلى الطبيعة ضرورة ⛅', 'بين أربعة جدران، تتحول طاقة طفلكِ إلى عدوانية، وتبدأ كل جملة يقولها بكلمة «لا». مهما كان الطقس أو نوع الملابس، جهّزيه بما يناسب واصطحبيه إلى الخارج. فملامسة التراب ستعيد ضبط جهازه العصبي على الفور.'),
  ('72b51261-3fd9-4ba4-a07e-a52ab32038d0', 'المصباح الليلي 🌙', 'هل يشعر طفلكِ بالقلق عند إطفاء أضواء غرفة النوم؟ ضعي مصباحًا ليليًا صغيرًا بلون دافئ (برتقالي أو أحمر) في إحدى زوايا الغرفة. أما بقية الغرفة، فيجب أن تظل مظلمة تمامًا لدعم إفراز الميلاتونين والنوم العميق.'),
  ('0bee47e7-94df-4d8c-b500-e8adc690d1ff', 'قائمة التسوق الرقمية المنقذة 🛒', 'هل تقفين وسط المتجر متسائلة: ما الذي جئتُ لشرائه؟ فعقل الأم مشغول أصلًا بألف شيء. اعتادي تدوين ما تحتاجين إليه في «قائمة التسوق» داخل التطبيق فور تذكّره، وخفّفي العبء عن نفسكِ.'),
  ('7574c80e-2022-481c-9e84-dd04a5dc3520', 'مقلب «دعيني أساعدكِ!» 🧽', 'هل يصر طفلكِ، بينما تغسلين الأطباق، على وضع كرسي بجانبكِ واللعب بالماء؟ في الحقيقة، هو لا يريد المساعدة بقدر ما يريد أن يكون في قلب الحدث. أعطيه وعاءً بلاستيكيًا صغيرًا وإسفنجة. سيغرق المطبخ بالماء، لكن ثقته بنفسه ستكبر كثيرًا.'),
  ('ed6ba029-b0b0-4d21-8825-996dcfdf7f9e', 'التردد السحري للموسيقى 🎶', 'جرّبي تهدئة نوبات الصراخ والانفعال غير المبررة في آخر النهار بموسيقى كلاسيكية هادئة. غالبًا ما تغيّر هذه الحيلة البسيطة والفعّالة أجواء الغرفة المشحونة بطريقة سحرية، وتغمر طفلكِ بالسكينة.'),
  ('df056dc0-b341-46d5-89e8-51170248ba0c', 'مهندس خزانة الملابس 👗', 'يريد طفلكِ اليوم الخروج مرتديًا جوربين غير متطابقين وقميصًا بالمقلوب. لا تكترثي لمعايير التناسق التي يفرضها المجتمع. فحرية اتخاذ قراره والدفاع عنه درس حياتي أهم بكثير من تنسيق الألوان. اسمحي له بذلك.'),
  ('ed70e165-6613-45b8-9098-e5a1501e357a', 'الذكاء الاصطناعي والطمأنينة 🤖', 'هل أقلقتكِ التقلبات العاطفية الحادة لدى طفلكِ مع اقترابه من عمر ٣ سنوات ونصف؟ أغلقي منتديات الإنترنت المخيفة والمثيرة للقلق. واحصلي من Anacan AI على إجابات مطمئنة تستند إلى أسس علمية ونفسية حول أزمات هذه المرحلة العمرية.'),
  ('fd525f60-163f-4a76-b89b-734831b1ea09', 'دعيه يكتب القصة 🪄', 'هل مللتما من الكتب الكلاسيكية وأصبحت أجواء الغرفة رتيبة؟ افتحي القصص الذكية ودعيه يوجّه أحداث قصة هذا المساء. اسأليه: إلى أين ستذهب السيارة الطائرة الآن؟ ودعيه ينام وهو يخوض مغامرات خيالية مليئة بالانتصارات.'),
  ('4cc9dfab-73bb-408b-8fd7-0cdb3ba02840', 'سحر الهمس 🤫', 'يستلقي في السرير ويرفع ساقيه في الهواء، ولا يريد النوم إطلاقًا. بدلًا من الصراخ، اخفضي نبرة صوتكِ فجأة ولا تتحدثي معه إلا همسًا. عندما يركّز طفلكِ ليسمعكِ، سيهدأ دماغه تلقائيًا وينتقل إلى وضع النوم كما لو كان تحت تأثير التنويم.'),
  ('815c8c47-103f-4098-9702-cdb4705b486d', 'لحظة بلا مهام للأم 🛋️', 'حين يشاهد الرسوم المتحركة أو ينشغل بألعابه، هل تهرعين إلى تفريغ غسالة الصحون أو نشر الملابس؟ توقفي! اقضي تلك الدقائق الـ١٠ مستلقية على الأريكة، تحدّقين في السقف ولا تفكرين في شيء. أنتِ لستِ روبوتًا.'),
  ('ac5c326d-30b1-4f87-8420-9236c8047849', 'أكملي جمله غير المكتملة 🗣️', 'عندما ينسى كلمة، يشير بيديه ويقطّب حاجبيه منتظرًا منكِ أن تعرفيها. حصيلته اللغوية تتسع، لكن دماغه يعمل أسرع من لسانه فحسب. أكملي جملته بصبر، وشاهدي على وجهه ذلك الارتياح الذي يقول: نعم، هذا بالضبط ما كنت أريد قوله.'),
  ('7eaa01a6-6e1b-4778-9360-22935e0a6bcc', 'مصممة الطعام 🥦', 'يفصل الأطعمة في طبقه حسب ألوانها وأشكالها، ويدفع الأطعمة الخضراء جانبًا. تصفّحي الوصفات الصحية، واكتشفي كيف تحوّلين تلك الخضراوات إلى هريس غير ملحوظ وتخفينها داخل صلصات لذيذة، لتفوزي بهذه اللعبة بذكاء ومن دون أن يدري.'),
  ('91e22232-e032-41dd-a3bf-200483eec697', 'ركوب الخيل على ظهر أبيه 🐴', 'لم يفرّغ طاقته بالكامل وما زال يرفض الذهاب إلى السرير. اطلبي مساعدة أبيه. عندما يحمله على ظهره ويتظاهر بأنه حصان يعدو، تملأ القهقهات الغرفة، ويتبدد خلال ثوانٍ كل التوتر الجسدي المتراكم وتلك الطاقة التي لا تنتهي، بينما يتصبب عرقًا.'),
  ('f8f487ed-ac2b-4c2b-a252-bb33ce8ad0c5', 'الكلمات غير اللائقة 🤐', 'يكرر أمامكِ ضاحكًا تلك الكلمة السيئة التي سمعها في الشارع أو على التلفاز، وينتظر رد فعلكِ بفضول شديد. أقوى سلاح لديكِ هو عدم إبداء أي رد فعل. لا تضحكي ولا تغضبي، بل تجاهلي الأمر فحسب. وسرعان ما سينسى تلك الكلمة.'),
  ('77e473a7-cc66-4af3-964b-ebd4e0ce22a0', 'هذا ليس خطئي! 🤷‍♂️', 'سكب الماء على الأرض عمدًا، لكنه ألقى باللوم على الطاولة قائلًا: «الطاولة تحركت». هذا ليس كذبًا، بل غريزة للدفاع عن النفس. لا تدخلي معه في جدال، بل قولي: «تعالَ نساعد الطاولة ونمسح الماء معًا»، وبذلك تغرسين فيه تحمّل المسؤولية دون جرح مشاعره.'),
  ('a43b3c7f-b8b9-440c-abc6-6650d2627176', 'دعم المجتمع 💬', 'هل يخنقكِ فجأة شعور أنكِ لن تعودي أبدًا إلى شخصيتكِ الحرة السابقة؟ شاركي هذا الشعور العابر، لكنه ثقيل وعميق جدًا، مع الأمهات في مجتمع Anacan، واستمدّي منهن المواساة والدعم لأنهن مررن بالتجربة نفسها.'),
  ('1eb146d3-b624-4eb5-88ee-21bab3e1a546', 'عانقيه فحسب 🫂', 'لا حاجة إلى أي لعبة أو كتاب صاخب أو حكاية. هذا المساء، ضمّيه فحسب إلى صدركِ، واستنشقي رائحته النقية بعمق، واهمسي له في الظلام كم هو غالٍ عليكِ وكم تحبينه.'),
  ('39c13cd6-54ea-4fd8-a9da-7ceece969e6d', 'إصراره في المتجر: «أنا سأقود!» 🛒', 'يريد دفع عربة التسوق بنفسه، فيصطدم بالرفوف ويُحدث فوضى. وبدلًا من أن تتركيه يبكي أمام الناس، دعي يديه على طرف العربة ووجّهيها أنتِ بخفة دون أن يلاحظ. أمّا ما قد تنسينه، فتحققي منه في قائمة التسوق.'),
  ('dcf51c40-2de5-47dc-a87f-c99740f37d0f', 'فوضى الألعاب 🌪️', 'هل سئمتِ من جمع الألعاب نفسها كل يوم؟ لا تجمعيها اليوم! فالمنزل ليس متحفًا، بل مكان دافئ ينبض بالحياة وينمو فيه مستكشف صغير. لا تركّزي على الفوضى، بل على متعة طفلكِ في الاستكشاف بحرية، وخذي قسطًا من الراحة.'),
  ('7f0898f3-4281-4b25-877c-f3060088913f', 'انظري إلى الأسفل، ماذا يكتشف؟ 👣', 'يستمتع بالمشي حافي القدمين، وبملامسة السجاد أو الحصى في الغرفة والبلاط البارد. إن تحفيز الأعصاب الموجودة في باطن قدميه مهم جدًا لتوازنه ونموه العصبي، فلا تمنعيه أبدًا من المشي دون جوارب.'),
  ('a17ad881-1738-43fa-b18c-dd0c7b263be1', 'ذكاء اصطناعي، حل واقعي 🤖', 'هل أخافتكِ ردود فعل طفلكِ الحادة تجاه كل شيء؟ انسي المقالات المقلقة على الإنترنت. اسألي Anacan AI عمّا إذا كان ذلك مجرد استجابة مؤقتة للتوتر، واطمئني بالحصول على إجابة علمية معتمدة من أطباء الأطفال.'),
  ('be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e', 'المقياس الرقمي للصمت 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي عمّ المنزل. فعّلي أداة قياس الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واشعري بصريًا كيف يتعافى دماغكِ تدريجيًا ويستريح.'),
  ('07324b19-8c8c-4d15-8c79-0b07b4d8c8cf', 'المحيط في حوض الاستحمام 🌊', 'لم يعد الاستحمام في الحوض مجرد تنظيف، بل أصبح لعبة لصنع الأمواج. دعي الماء يتناثر في كل مكان والحمّام يبتل. فتأثير الماء الساحر سيغسل تلك الطاقة السلبية العنيدة التي تراكمت لدى طفلكِ طوال اليوم ويحملها إلى المصرف.'),
  ('501e8f67-b2b7-4164-9b32-0326fabd781c', 'أسرار خلف الباب 🚪', 'هل يدخل غرفته ويغلق الباب خلفه ويرغب في البقاء وحده؟ لقد بدأ مفهوم المساحة الشخصية والشعور بالاستقلالية يتكوّنان لديه. اتخذي تدابير السلامة وامنحيه هذا القدر البسيط من الخصوصية. إنه يكبر.'),
  ('9e8cbc80-ee70-4ea5-ab36-76dd4e2487c7', 'اعتراف في مفكرة المزاج 📝', 'أمسكي هاتفكِ. وبدلًا من تصفّح الحياة المثالية للآخرين على شبكات التواصل الاجتماعي، افتحي مفكرة المزاج وسجّلي للمستقبل أطرف موقف فعله اليوم وأكثر لحظة أضحكتكِ. فالكتابة فيها علاج نقي للنفس.'),
  ('4acc88e2-20b2-4215-8fcd-8a14393b92b9', 'نخب الزوجين 🥂', 'نام طفلكِ. وحتى إن لم تتوفر الشمبانيا، اسكبي الشاي الساخن في كوبين وتبادلي النخب مع زوجكِ قائلين: «لقد اجتزنا هذا اليوم العاصف أيضًا بسلام». فأنتما قائدا المنزل وفريقه الذي لا يتزعزع.'),
  ('4b9f4b0d-becb-4db4-85ec-0a0caae64162', 'دموع بلا منطق 🐶', 'هل انخرط في البكاء لأن الكلب الذي رأيتماه في الشارع لم ينظر إليه، أو لأن ورقة شجر سقطت على الأرض؟ لا تبحثي عن المنطق في الموقف. فهذا حزن عميق وحقيقي بالنسبة إليه. اكتفي بتأكيد مشاعره بقولكِ: «أعلم أنكَ كنت تريد أن ينظر إليك».'),
  ('9ae0817a-4137-49f1-8c45-fb16cc1d750b', 'سياسة الحديقة 🤝', 'هل يدفع طفلًا آخر عند الزحليقة لأنه يريد استخدامها أولًا؟ لا تزال المشاركة مفهومًا معقدًا لم يترسخ لديه تمامًا. وبدلًا من إشعاره بالخجل أو معاقبته، ذكّريه ببساطة بالنظام قائلةً: «إنه دوره الآن».'),
  ('23303195-392c-42b3-a778-b5f932e7d2fb', 'صرخة الجسد 🩸', 'لا تستسلمي للانزعاج والإرهاق غير المبررين. راجعي متتبّع الدورة الشهرية؛ فجسدكِ يرسل إليكِ إشارات. وبدلًا من لوم نفسكِ، استريحي وتناولي وجبة خفيفة غنية بالمغنيسيوم.'),
  ('455a26dd-2714-4e7f-a8b0-c2319880fdbd', 'معركة مع الظلال 👻', 'هل يخاف من ظله على الحائط ويختبئ خلفكِ؟ مع اقترابه من منتصف سن الثالثة، لا يعرف خياله حدودًا. أظلمي الغرفة واصنعي بيديكِ أشكالًا من الظلال على الحائط باستخدام مصباح يدوي. حوّلي الظلام الذي يخشاه إلى أمتع لعبة بالنسبة إليه.'),
  ('ca0412c4-f03e-412b-a720-1ce839d731c8', 'سحر الحكايات 🪄', 'ابتعدي عن أسلوب القراءة التقليدي وافتحي الحكايات الذكية. اصنعي في الغرفة مسرحًا صوتيًا صغيرًا، وقلّدي بفمكِ صوت الرياح وصرير الباب وخطوات بطل الحكاية. سينبهر طفلكِ بهذا العرض.'),
  ('5ee7392d-5b0b-4213-bc93-84f42871cfbd', 'حيلة تأجيل النوم ⏱️', 'هل يشعر طفلكِ فجأة بالعطش عند حلول موعد النوم، أو يرغب في الذهاب إلى الحمّام، أو يبدأ بتوديع الجدار؟ اضبطي مؤقتًا، وطبّقي قاعدة «عندما يرن الجرس، ينام الجميع»، لتضعي بصبر حدًا لهذا الوداع الذي لا ينتهي ولهذه المناورات البارعة.'),
  ('8ed6ac5e-566a-43de-a26f-f6688bac7a5c', 'أمّ الألعاب 🧸', 'يأتي صوت من الغرفة، فتنصتين باهتمام، وإذا بطفلكِ يوبّخ دبدوبه بنبرة صوتكِ تمامًا وبعباراتكِ المميزة نفسها! إنه نسختكِ الأكثر دقة. إنها فرصة رائعة لتري تصرفاتكِ من منظور خارجي.'),
  ('fcc9b956-df18-4d44-8e28-2c6ce0162f8e', 'استطلاع الطقس ⛅', 'هل الطقس في الخارج غير واضح تمامًا، فالشمس مشرقة لكن الرياح تهب أيضًا؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا يمكنكِ تقديرها من النافذة، وتقترح عليكِ الإطلالة المناسبة، ثم اخرجي للتنزه من دون تردد أو إضاعة الوقت عند الباب.'),
  ('542ab746-c3f8-40a2-81ae-c00828c5ed07', 'حيلة الأب السرية 👨‍🍼', 'لقد نلتِ ما يكفي من إرهاق النهار وضجيجه. في المساء، أوكلي إلى الأب مهمة تهيئة طفلكِ للنوم وتنظيف أسنانه بأسلوبه المرح، واستريحي أنتِ في غرفة أخرى بعيدًا عنهما، في هدوء تام.'),
  ('843abd1b-ca68-4402-b6ea-b248f8954a8f', 'لوح طاقة الأم 🥑', 'أعددتِ له قائمة طعام بـ4 طرق مختلفة، لكن ماذا أكلتِ أنتِ؟ اختاري من الوصفات الصحية وجبة خفيفة مميزة وغنية بالكالسيوم لا يستغرق تحضيرها سوى 5 دقائق، واستمتعي بها ولو كنتِ واقفة؛ فأنتِ محرّك هذا المنزل.'),
  ('9b9022d6-2ceb-4fd3-b3c5-141395cf895c', 'فطور لا يقبل المشاركة 🍳', 'يرفض طفلكِ تمامًا أن يعطيكِ شيئًا من طبقه، لكنه يأتي مصرًّا على تناول البيض أو الجبن من طبقكِ. يثق الأطفال دائمًا ثقة كاملة باختيارات والديهم. لا تدخلي في صراع، وقدّمي له لقمتكِ بكل حب.'),
  ('3a219301-d574-4311-87ab-5dc04ddcfd8f', 'تدليك بروح الفريق 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي مع شريككِ تدليك الكتفين للتخلص من كل الضغوط الجسدية والنفسية التي خلّفها اليوم. فأنتما لستما مجرد والدين يتقاسمان المنزل نفسه، بل فريق دعم متماسك لا يتزعزع.'),
  ('602df0e4-a84c-493f-a594-485626339a2a', 'أطفئي الأنوار ليأتي النوم 🌙', 'لمساعدة طفلكِ على النوم بسرعة، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل ساعة من موعد النوم. فالميلاتونين (هرمون النوم) يُفرَز بسرعة في بيئة مظلمة وخالية من الأجهزة التكنولوجية، ما يساعد على الانتقال إلى النوم.'),
  ('871e1c8b-981d-456b-8f8e-49b3f9df1255', 'استلهمي من المدوّنات 📱', 'ما طفرات النمو التي يمر بها الطفل مع اقترابه من الشهر 40؟ وما المهارات التي يُفترض أن يتقنها؟ تصفّحي مدوّنات النمو في التطبيق، واستمتعي في قرارة نفسكِ برؤية مدى تقدّم طفلكِ في الإدراك والتفكير المنطقي.'),
  ('dc309f01-53dd-4d8e-b0a5-566a9cb979d1', 'إكمال الجمل الناقصة 🗣️', 'عندما ينسى كلمة، يبدأ بالإشارة بيده وعقد حاجبيه منتظرًا منكِ أن تعرفي ما يقصده. وعندما تكملين جملته بصبر، راقبي علامات الارتياح على وجهه وكأنه يقول: نعم، هذا بالضبط ما كنت أقصده. أنتِ مترجمته الوحيدة.'),
  ('35170eca-5526-4a79-8f60-bb6c6204b11e', 'متلازمة الجوع المفاجئ 🥱', 'ما إن يدخل السرير حتى يقول: أمي، أنا جائع، ويحاول الركض إلى المطبخ. إنها حيلة بارعة لتأخير النوم! اختاري ضمن خطة التغذية وجبة خفيفة مسائية تساعد على النوم، وأبطلي هذه الحجة مسبقًا.'),
  ('a52300ac-c13a-4b61-bfa8-c7cb27b41cfa', 'ابتزاز «قدماي متعبتان» 🚶‍♂️', 'هل يجلس فجأة على الأرض أثناء السير في الشارع ويقول: قدماي تؤلمانني، احمليني؟ قد لا يكون ذلك تعبًا جسديًا، بل محاولة لاستمالتكِ. حوّلي الأمر إلى لعبة: لنرَ من سيقفز مثل الأرنب ويصل إلى المنزل أسرع؟'),
  ('ed5f6008-15d7-44f7-a33c-21fd4bedec89', 'زر إعادة الضبط لدى الأم 🚪', 'الضجيج يكاد يخترق رأسكِ، وتشعرين برغبة في الصراخ بسبب كل شيء. افتحي مفكرة مزاجكِ واكتبي فيها بحرية كل ما تشعرين به من إنهاك. ستساعدكِ هذه الجلسة الرقمية القصيرة على استعادة توازنكِ من جديد.'),
  ('045a4c72-4a86-41d2-b03b-ae2eaef10270', 'حكاية الأب 📖', 'صوتكِ متعب هذا المساء، لذا أوكلي إلى الأب مهمة قراءة الحكاية. سيؤلف قصة طريفة وخيالية تختلف تمامًا عن الصورة الموجودة في الكتاب، ويُغرق الطفل في الضحك. أما أنتِ، فاستمتعي بمشاهدة هذا المشهد من بعيد مع كوب من الشاي.'),
  ('4f62a7a1-3c14-48ad-8798-069c557ed2c1', 'مساعد الغسيل 🧺', 'تطوين الملابس بجهد كبير، بينما يقول إنه يساعدكِ ثم يعيد بعثرتها كلها في الغرفة. بدلًا من الغضب، حوّلي المهمة إلى لعبة: لنرَ من يستطيع إلقاء هذه الجوارب في السلة بسرعة ودقة أكبر؟'),
  ('b2fc2b4c-64df-4f47-be2c-e630a4d24c5c', 'لا بد من الانطلاق إلى الطبيعة ⛅', 'بين أربعة جدران، تتحول طاقة طفلكِ إلى عدوانية، وتبدأ كل جملة يقولها بكلمة «لا». مهما كان الطقس، ارتدي أنتِ وطفلكِ الملابس المناسبة، واحرصي على اصطحابه إلى الخارج. فملامسة التراب ستعيد التوازن إلى جهازه العصبي فورًا.'),
  ('20cf0e7c-3293-4269-b577-f8012d7d5117', 'انهيار المنطق 🔴', 'يصرخ مطالبًا بأن تقدّمي له الماء في الكوب الأحمر، وحين تسكبينه فيه يبكي قائلًا: لماذا سكبتِه هنا؟ لا مكان للمنطق في هذه اللحظة؛ فهو متعب فحسب ويحتاج إلى تفريغ مشاعره بهذه النوبة. انتظري بهدوء، وستمضي العاصفة من تلقاء نفسها.'),
  ('3d467b3e-4418-42f9-965d-e11c13d74805', 'كنوز تخرج من الجيوب 🪨', 'هل وجدتِ في جيب سرواله عند غسله حجرين وورقة شجر جافة وعودًا مكسورًا؟ قد تبدو لكِ هذه الأشياء نفايات، لكنها مجموعته الثمينة التي توثّق استكشافه للكون. بدلًا من رميها، اجمعيها في صندوق كنوز صغير.'),
  ('78fd11f7-de1e-4540-906f-51f08156be41', 'أنا في الحكاية الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب. افتحي الحكايات الذكية، واجعلي طفلكِ بطل القصة وغرفته المكان الذي سيخوض مغامرة اكتشافه، وابتكري جلسة نوم صوتية استثنائية لا تتطلب منكِ أي مجهود.'),
  ('5294e5b4-881b-4e55-b798-fa4dd914d649', 'ليس نفايات، بل فن 🎨', 'لقد صنع في وسط الغرفة عملًا فنيًا ضخمًا من قصاصات الورق الصغيرة والخيوط المقطّعة، ويرفض أن ترميه. ضعي هوس الترتيب جانبًا، واحترمي الفوضى التي ابتكرها؛ فالتنظيف يمكن أن ينتظر حتى الغد.'),
  ('b303b530-f33d-4aed-9563-288f674e5686', 'مساعدة تحليل البكاء😭', 'استيقظ طفلكِ في منتصف الليل باكيًا وعيناه مغمضتان، ولا يستجيب لأحد. تحققي من الأمر باستخدام تحليل البكاء؛ فإذا كان يعاني من الذعر الليلي، فلا تحاولي إيقاظه. ابقي بجانبه في صمت فحسب، وسيعود إلى النوم خلال بضع دقائق.'),
  ('d0b48160-e2df-4f83-a2aa-8dad8ce91b39', 'الحديث مع الجمادات 🗣️', 'يتحدث بجدية تامة إلى حجر في الحديقة أو كرسي في المنزل، بل ويوبّخهما. من خلال اللعب الرمزي، يستوعب العالم وقواعده. احرصي على تسجيل هذه السيناريوهات المميزة في متتبّع نموه وتطوره.'),
  ('3486268f-4b63-480f-87b2-0334f163c85e', 'اللعب في حوض الاستحمام 🌊', 'لم يعد الاستحمام في الحوض من أجل النظافة، بل أصبح لعبة لصنع الأمواج. دعي الماء يتناثر في كل مكان ويبلّل حمّامكِ. فتأثير الماء الساحر سيغسل كل تلك الطاقة السلبية والعنيدة التي تراكمت لديه طوال اليوم، ويحملها بعيدًا مع مياه الصرف.'),
  ('c30e7d23-adbf-430f-894c-89ab12e4b61e', 'هدم هادف 🧱', 'يبني برجًا بجهد كبير، ثم يهدمه بضربة واحدة وهو يضحك. إنه يتعلّم مبادئ الفيزياء والعلاقة بين السبب والنتيجة. لا تنزعجي، فالأبراج التي يهدمها تمثّل روابط عصبية جديدة تتكوّن في دماغه. ساعديه على بنائه من جديد.'),
  ('f4280214-1e8a-4015-949d-34ae67c41790', 'معركة القيلولة 🥱', 'لا يريد الذهاب إلى السرير ويبكي؟ لا تجبريه. خفّفي الإضاءة في الغرفة وأعلني عن وقت هادئ لتصفّح الكتب، وابتكري روتينًا جديدًا يمنحكما الراحة، بحيث يستريح كل منكما بطريقته.'),
  ('4a5979ea-637a-48c3-a6a9-1af57b3d55c4', 'المتجر الخيالي 🍅', 'يجمع ألعابه في زاوية من الغرفة ويبيعكِ حبات طماطم خيالية مقابل نقود خيالية. تعاملي مع لعبة البيع والشراء هذه بجدية تامة. اشتري منه حبة الطماطم الخيالية وتظاهري بأنكِ تأكلينها بشهية. تُعدّ ألعاب تقمّص الأدوار من أقوى أسس ذكائه الاجتماعي.'),
  ('58c30ae3-2599-434d-af6b-bb25c9a1766d', 'تنويم بالموسيقى 🎶', 'هل بدأت نوبات البكاء والعواصف المفاجئة بلا سبب في أواخر النهار؟ أطفئي التلفاز، وخفّفي الإضاءة، وشغّلي موسيقى كلاسيكية هادئة جدًا في الغرفة. ستُغيّر ترددات الموسيقى العميقة أجواء المكان بطريقة ساحرة.'),
  ('d8b0e257-5429-4bf7-b2a7-1bb116658651', 'لا وجود للكمال 🛑', 'هل نفد صبركِ اليوم؟ لا تشعري بالسوء تجاه نفسكِ. ابتعدي عن أوهام الأم المثالية التي ترينها على الإنترنت. أنتِ أم حقيقية، ومن الطبيعي أن تعيشي مشاعركِ وتشعري بتعبكِ.'),
  ('4673a3e6-d285-4515-9173-039b8bcbc1e0', 'منقذ التسوّق 🛒', 'هل تنسين دائمًا أهم غرض عند الذهاب إلى المتجر؟ قائمة التسوّق بانتظاركِ في التطبيق. دوّني احتياجاتكِ فيها ليشتريها شريككِ بدقة عند عودته من العمل، ولا ترهقي ذهنكِ.'),
  ('dd38c03c-a89e-4942-af31-f459dbf71386', 'مرحلة «ماما، انظري إليّ!» 👀', 'يقفز من الأريكة ويكرّر الحركة نفسها 50 مرة، قائلًا في كل مرة: «ماما، انظري إليّ!». ارفعي عينيكِ عن الهاتف. إنه يقفز ليرى بريق الاستحسان في عينيكِ. امنحيه 5 دقائق من الاهتمام المتواصل حتى يشعر بالاكتفاء.'),
  ('effd03a1-4f68-42a7-8c25-eabba9947bc3', 'حكايات هامسة 🌙', 'لقد رفعتِ صوتكِ كثيرًا اليوم وأُرهقت رئتاكِ. أطفئي الأنوار، واستلقي بجانبه، واحكي له همسًا في أذنه ما حدث خلال اليوم. يساعده الهمس على تركيز انتباهه، ويهيئ دماغه بطريقة أشبه بالتنويم للدخول في نوم عميق.'),
  ('b2543089-e56e-4e5f-b7a7-8528d7fea1b5', 'ديكتاتور الصباح يتولى القيادة 👑', 'لا تجلسي هناك، فدُبّي الصغير سيجلس هناك! إنه يدير مائدة الإفطار بأكملها. حافظي على التوازن والسلام في الغرفة من دون كسر إرادته بعنف، وقولي: «حسنًا، ليجلس دُبّك هناك، وسأجلس أنا هنا».'),
  ('c7639a79-f169-46c8-bd32-85e01fd08685', 'شاي على ضوء الشموع 🕯️', 'نام طفلكِ. أطفئي الأنوار وأشعلي شمعة على الطاولة. ليس لإضفاء أجواء رومانسية، بل فقط لتهدئة أعصابكِ المتوترة طوال اليوم وعينيكِ المتعبتين من الشاشات والضوضاء.'),
  ('c83edf54-e27c-4125-b28b-f2d18dfa66d3', 'إرهاق اللمس 🔋', 'يتسلق عليكِ طوال اليوم، ويطلب العناق ويلعب بشعركِ. إرهاق اللمس (touched out) شعور حقيقي. من حقكِ أن تنعزلي في غرفة بمفردكِ لمدة 15 دقيقة على الأقل، وأن تشعري بأن جسدكِ ملك لكِ وحدكِ.'),
  ('01e96341-0baa-4735-9565-edc8b43ed916', 'ركوب الخيل على ظهر الأب 🐴', 'لم يفرغ طاقته بالكامل بعد، ويرفض الذهاب إلى السرير. اطلبي مساعدة الأب. عندما يحمله على ظهره ويتظاهر بأنه حصان يركض، تملأ الضحكات الغرفة، ويتلاشى خلال ثوانٍ كل التوتر الجسدي المتراكم وتلك الطاقة التي لا تنضب مع بعض التعرق.'),
  ('384ff620-f71d-4bc9-9283-5e83ec033e38', 'اعتراف في المجتمع 💬', 'هل صرختِ اليوم بسبب كل شيء وشعرتِ بأنكِ أقل أمهات العالم صبرًا؟ أرجوكِ تذكّري أنكِ لستِ وحدكِ. ادخلي إلى مجتمع Anacan، واقرئي كيف تشعر أمهات أخريات بالإنهاك بالقدر نفسه اليوم، لتشعري بالارتياح.'),
  ('da72ebf1-980c-4fb3-a9bf-5164e9b3b0a9', 'المنافس في المرآة 🪞', 'يقف أمام المرآة، ويقطّب حاجبيه لنفسه، ويصنع تعابير غاضبة وغريبة. إنه يختبر كيف تبدو المشاعر على وجهه. راقبي بصمت واهتمام تدريبات هذا الممثل المسرحي الصغير.'),
  ('2c31302d-18e1-44cd-8719-76e1444cd735', 'عملية الطعام السرية 🥣', 'حتى الأمس كان يحب البيض، أما اليوم فلا تستطيعين إقناعه بتذوقه. لا تدخلي في صراع مع إرادته. كوني أنتِ الفائزة بتحضير وصفات ذكية لوجبات خفيفة صحية، تقدّمين فيها البروتينات بأشكال متنوعة وملونة وممتعة.'),
  ('723d3b58-0a46-493d-ba9b-9e4d8c6656ee', 'تأكيد الصمت 🤫', 'بعد يوم صاخب، وعندما ينام طفلكِ، قيسي هدوء الغرفة باستخدام جهاز قياس مستوى الصوت. إن رؤية الأرقام تقترب من الصفر تجعل ذلك الهدوء المرئي أشبه بأجمل تدليك لعقل الأم.'),
  ('f226f50f-54a9-4f4e-ad02-b0959087d7d6', '«أحبكِ» مفاجئة 💖', 'بينما يلعب في وسط الغرفة، ينظر إليكِ فجأة ثم يركض نحوكِ ويعانقكِ. لحظة تستحق كل الليالي بلا نوم وكل التعب! استمتعي بذلك السلام العميق والفريد الذي تغمركِ به هذه اللحظة.'),
  ('3517ce10-8615-407d-be3b-394eda1c9fa6', 'أطفئي الأنوار، حان وقت النوم 🌙', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية قبل موعد النوم بساعة. يُفرَز الميلاتونين (هرمون النوم) بسرعة فقط في بيئة مظلمة وخالية من الأجهزة الإلكترونية.'),
  ('7daa2d64-db1d-42ea-8cec-a0101d304bbf', 'الحاجة إلى الألياف 💩', 'يركض كثيرًا، لكنه ينسى شرب الماء. راقبي برازه في النونية. إذا كان معرضًا للإمساك، فسجّلي ذلك في التطبيق وأضيفي الشوفان والبرقوق إلى قائمته الغذائية فورًا باستخدام أداة متابعة التغذية.'),
  ('e079d221-e081-498b-8457-7e4dc4555c89', 'الكلمات غير اللائقة 🤐', 'يكرر لكِ ضاحكًا تلك الكلمة السيئة التي سمعها في الشارع أو على التلفاز، وينتظر رد فعلكِ بفضول شديد. أقوى سلاح لديكِ هو عدم إبداء أي رد فعل. لا تضحكي ولا تغضبي، بل تجاهلي الأمر ببساطة. وسرعان ما سينسى تلك الكلمة.'),
  ('2b47e995-a54a-442e-b303-43e9894db748', 'دعيه يكتب نهاية الحكاية 🪄', 'لقد مللتما كلاكما من الكتب الكلاسيكية. هذه المرة، دعي طفلكِ يختار نهاية القصة في الحكايات الذكية. أطلقي العنان لخياله قبل النوم بسؤاله: «برأيك، من ساعد ذلك البطل؟»'),
  ('e7a2ec95-d6ca-43e4-8ed9-23193c18bf3a', 'منطق بارد كالثلج 🥶', 'يفتح الثلاجة ويطلب قالب الثلج، ولا يتركه رغم برودة يديه. إنه يختبر بجسده مفهومي الدفء والبرودة. ضعي ماءً فاترًا في وعاء وماءً مثلجًا في آخر، وحوّلي هذا الاستكشاف إلى تجربة علمية صغيرة.'),
  ('fd41f13f-2abd-4cce-ba8e-06a55c0b506f', 'جولة الركض مع الأب في الحديقة 👨‍👧', 'الأمومة ليست مناوبة متواصلة 24/7. فعّلي وضع الشريك! دعي الأب يساعده اليوم على تفريغ طاقته التي لا تنتهي في الحديقة، واستمتعي أنتِ في المنزل بالهدوء التام.'),
  ('587f6b4e-5494-4f6a-8efa-28e0cb53f529', 'حفل موسيقي في المطبخ 🥄', 'يُخرج القدور والملاعق الخشبية ويقيم حفلًا موسيقيًا في وسط المطبخ. حتى لو أصابكِ الصداع، فهذا يساعد على تنمية إحساسه بالإيقاع وإبداعه. لا تتدخلي على الفور، ودعي موجات تلك الطاقة الجامحة تملأ الغرفة لبضع دقائق.'),
  ('a36ee256-d6c9-4345-a732-3a052e7dd260', 'استكشاف الطقس ⛅', 'هل الجو في الخارج غير صافٍ تمامًا، والشمس مشرقة لكن الرياح تهب أيضًا؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا تظهر من النافذة وبالملابس المناسبة، واخرجي للتنزه من دون تردد أو إضاعة الوقت عند الباب.'),
  ('c95b298d-8316-46aa-ace1-1fc1956a0fda', 'تدليك جماعي 💆‍♂️', 'بعد أن ينام طفلكِ، تبادلي تدليك الكتفين مع شريككِ للتخلص من ضغوط اليوم. فأنتما لستما مجرد والدين يعيشان في المنزل نفسه، بل فريق دعم متماسك لا يتزعزع.'),
  ('272c7bb7-edd9-4323-8db9-05fe3c752757', 'تقلبات عاطفية حادة 🤖', 'هل أقلقتكِ التقلبات العاطفية الحادة لدى طفلكِ مع اقترابه من سن الثالثة والنصف؟ أغلقي المنتديات المخيفة والمثيرة للقلق على الإنترنت. واحصلي من Anacan AI على إجابة مطمئنة تستند إلى أسس علمية ونفسية حول أزمات هذه المرحلة العمرية.'),
  ('53a9bbe1-a99a-4438-963b-9b63a44c8eb3', 'معجزة الماء الدافئ 🛀', 'أحيانًا لا يجدي شيء نفعًا، ويظل طفلكِ يبكي على كل شيء. ضعيه في حوض استحمام مملوء بالماء الفاتر، وأضيفي إليه قليلًا من الرغوة. ستجلب قوة الماء الساحرة في تخفيف التوتر الهدوء فورًا إلى الغرفة بأكملها وإلى جهازه العصبي.'),
  ('b49dbabf-98b6-4f35-8748-de30793c2722', 'مهندس خزانة الملابس 👗', 'يريد طفلكِ اليوم الخروج بجوربين غير متطابقين وقميص مقلوب. لا تكترثي لمعايير التناسق التي يفرضها المجتمع. فحرية اتخاذ قراره والدفاع عنه درس حياتي أهم بكثير من تناغم الألوان. اسمحي له بذلك.'),
  ('00f8be55-b6c0-4a3e-8a0e-ee6c807fdab5', 'مسجل صوت حي 🎙️', 'ها هو هذا الصباح يكرر للعبته كلمة عفوية، وربما غير ضرورية، قلتِها أمس أثناء حديثكِ مع شريككِ! إنه مرآتكِ الحية. انتبهي جيدًا إلى المشاعر التي تعبّرين عنها أمامه، فهو يقلدها واحدة تلو الأخرى.'),
  ('885b2dd9-966f-46c2-bbae-00f0fd65a479', 'حكاية الأب المرحة 📖', 'هذا المساء، لن يكون صوتكِ هو الذي يملأ الغرفة. أعطي كتاب الحكايات للأب، ودعيه يروي القصة عمدًا بطريقة معكوسة ومضحكة وعبثية. وراقبي من بعيد كيف يستمتع طفلكِ بتصحيح كلامه وكيف يضحك على والده بصوت عالٍ.'),
  ('fdf68496-5c5f-493c-aaed-7e9ab140b9c8', 'قوة المجتمع 💬', 'هل تستنزفكِ فكرة: لماذا طفلي عنيد إلى هذا الحد؟ انضمي إلى مجتمع Anacan. عندما تقرئين عن نوبات الغضب العبثية المشابهة التي تحدث في بيوت الأمهات الأخريات، ستدركين أنكِ لستِ وحدكِ وأنكِ تسيرين في طريق طبيعي تمامًا.'),
  ('7a91d538-17ac-47d6-a73e-975aed76abb5', 'رجل الأعمال الصغير 🍅', 'يجمع ألعابه في إحدى زوايا الغرفة ويبيعكِ طماطم خيالية مقابل نقود خيالية. تعاملي بجدية تامة مع لعبة البيع والشراء هذه. اشتري منه الطماطم الخيالية وتظاهري بأنكِ تأكلينها بشهية. تُعد ألعاب تقمّص الأدوار من أقوى أسس ذكائه الاجتماعي ومنطقه الرياضي.'),
  ('87c32869-7e9b-4faa-bbbe-1c640a3da5bb', 'درع الكالسيوم 🦴', 'الكالسيوم ضروري للعظام التي تنمو بسرعة. ألا يشرب الحليب؟ استخدمي أداة متابعة التغذية واحرصي اليوم على حساب ما تناوله من الجبن أو الزبادي أو البروكلي.'),
  ('dca4203c-2783-4935-8d52-5e2abbd31c77', 'الهروب من السرير 🏃‍♂️', 'أعطيني ماءً، ابحثي عن لعبتي... لا تنتهي أعذار سن 3 سنوات لتجنّب النوم. شغّلي مؤقت النوم وتمسّكي بالحدود بحزم.'),
  ('0f8f4362-f6e4-4b76-8a62-4dbaf7dbf605', 'الحِمل الضخم 🎒', 'يصرّ على حمل حقائبكِ الثقيلة أو المظلة الكبيرة بنفسه، ويجرّها بصعوبة لكنه يرفض المساعدة بشدة. دعيه يختبر قوته؛ فهو يريد أن يشعر بأنه أقوى بطل في المنزل، فلا تعيقي استقلاليته.'),
  ('13ddaeb9-9c7f-4a7b-ad20-6e0285eb57cf', 'هوية جديدة 🕷️', 'يستيقظ صباحًا ويقول لكِ بجدية تامة: أنا لست طفلًا، أنا عنكبوت. مع اقترابه من الشهر 40، يتجاوز خياله كل الحدود. لا تجادليه؛ امنحيه دور العنكبوت الذي يتناول فطوره وشاركيه هذا المسرح العبثي.'),
  ('b2a11f30-5597-4b15-9f01-835c2894a09b', 'أعذار لا تنتهي 🦶', 'عندما يكاد يغفو تمامًا، يحاول النهوض من السرير بحجة أن إصبع قدمه يحكّه. لقد أتقن فن تأخير النوم. كوني حازمة، وتظاهري بحكّ قدمه ثم أطفئي الأنوار بإصرار؛ فأنتِ من تضعين الحدود.'),
  ('417acfcf-4492-4093-aa86-48285ecc470a', 'شرط قبعة الأب 🧢', 'يشترط أن يرتدي والده قبعة شتوية كي يذهب إلى السرير. دعي والده يرتديها ويُصدر أصواتًا مضحكة. ستجعلكما هذه الطرافة الغريبة في المساء تضحكان قبل النوم، كما ستبدد عناد الطفل فورًا.'),
  ('7516076d-1a63-4620-b73e-63a31b706bac', 'عناد يتحدى قوانين الفيزياء 💧', 'هل يبكي بحرقة قائلًا: أريد الماء جافًا؟ عندما يطلب عقل الطفل أشياء مستحيلة، فهو في الحقيقة يختبر مدى تمسّككِ بقراركِ. لا تبحثي عن المنطق في الموقف، بل شتّتي انتباهه فورًا بشيء آخر ملوّن.'),
  ('b726a724-b8d0-4de2-92f7-30636fde8d1a', 'الهدوء داخل الخزانة 🚪', 'ساد المنزل هدوء مفاجئ، فوجدتِه مختبئًا داخل الخزانة يلعب بمفرده. إنه يبحث عن مساحة خاصة به. لا تُخرجيه فورًا؛ فهو أيضًا يريد الابتعاد عن الضوضاء والبقاء وحده قليلًا ليريح ذهنه.'),
  ('4b514d29-e0d8-49a4-850f-900d0c46bffa', 'الغضب الصامت 😤', 'عندما لا يحصل على ما يريد، يعقد ذراعيه وينظر إلى الحائط ويعبّر عن استيائه منكِ بدلًا من البكاء. هذه مرحلة جديدة ومهمة جدًا في تنظيم المشاعر. لا تضغطي عليه؛ فبعد 3 دقائق سيعود إليكِ ضاحكًا وكأن شيئًا لم يكن.'),
  ('4b721431-3565-4047-8fb3-144c9d3a8f8b', 'مقياس الهدوء الذهبي 🤫', 'ضوضاء المنزل تجعل أذنيكِ تطنّان. عندما ينام أخيرًا، فعّلي أداة قياس الصوت. إن تأمل تلك الأرقام القريبة من الصفر على الشاشة، وذلك الصمت الرقمي، هو أجمل تدليك بصري لعقل الأم المتعبة.'),
  ('6fcf10ba-99bd-4b23-bbff-0487161fbfe4', 'اكتشاف لغة جديدة 🗣️', 'بدأ يبتكر كلمات مركبة وغريبة من تأليفه، مثل طائر-راكض ودافئ-بارد. تتوسع حصيلته اللغوية بسرعة مذهلة. احرصي على تسجيل هذه الكلمات الطريفة التي ابتكرها في متتبّع التطور، لتبقى أرشيفًا لا يُنسى.'),
  ('2c413ba6-81fc-4861-95ac-e87a4f29055d', 'رفيق غريب في الطريق 🥄', 'عند الذهاب إلى الحديقة، يصرّ على اصطحاب مغرفة وجدها في المطبخ بدلًا من سياراته. لا تمنعيه! فستصبح تلك المغرفة اليوم في الحديقة أغرب ألعابه، لكنها الأكثر فائدة لحفر الرمل.'),
  ('b865240d-5ee4-4c57-917c-6139d1ce4039', 'القطط تخاف من الماء 🐈', 'يقول: أنا قطة، والقطط لا تستحم، كي يتجنب دخول حوض الاستحمام. تقبّلي دوره وواصلي اللعبة قائلة: وهل تريد هذه القطة اللعب بفقاعات الصابون؟ شجّعيه بهذه الطريقة، وتجاوزي اعتراضاته بقوة الخيال.'),
  ('f573b98e-335c-4b92-b5f7-06c122ba5b12', 'مفاوضات احترافية 🛒', 'بدلًا من البكاء طلبًا للحلوى في المتجر، يساومكِ قائلًا: إذا اشترينا هذه، فسأتناول حسائي. تهانينا، محاميكِ الصغير يكبر! أبقي قائمة التسوق مفتوحة كي لا تنسي ما تحتاجينه ولا يتشتت انتباهكِ أثناء التفاوض معه.'),
  ('605e9c74-a673-4f1f-9b27-383f6a4810eb', 'مرحلة «انظري إليّ!» 👀', 'يقفز من الأريكة ويكرر الحركة نفسها 50 مرة، منتظرًا استحسانكِ في كل مرة. ارفعي عينيكِ عن الهاتف. إنه لا يقفز من أجل الحركة نفسها، بل من أجل بريق الحب والاستحسان في عينيكِ.'),
  ('61cf1118-2d1d-4e42-9dac-f7a6ca616e71', 'رفيقة أسراركِ الصامتة 📝', 'هل تشعرين أن لا أحد يفهمكِ وأنكِ تُرهقين كثيرًا في المنزل؟ دعي الابتسامات المصطنعة جانبًا. اكتبي في مفكرة حالتكِ المزاجية كيف استُنزفت طاقتكِ حقًا اليوم. فكل كلمة تسطرينها على الشاشة ستزيح عن كاهلكِ عبئًا ثقيلًا.'),
  ('a2f88e5e-134a-4514-9134-a36d1a155887', 'نوم على الأرض 🥱', 'قاوم طفلكِ القيلولة ورفضها، لكنه تكوّر ونام على السجادة وسط ألعابه. لا تحمليه إلى السرير فتوقظيه، بل دعيه يستمتع ببراءته في وسط الغرفة، وخذي أنتِ أيضًا قسطًا من الراحة لمدة 1 ساعة.'),
  ('489a0197-f1e2-44a5-bece-55d85fa323ae', 'استطلاع الطقس ⛅', 'الشمس مشرقة، لكنه يريد ارتداء معطفه الشتوي. لا تجادليه. افتحي أداة الطقس والملابس وأريه رمز الطفل ذي الملابس الخفيفة على الشاشة. فحيلة «انظر، الهاتف يقول إن الجو دافئ اليوم» تنجح دائمًا ببراعة.'),
  ('64df174c-9f28-403f-83be-8452dd687caf', 'زمام القصة بيده 🪄', 'لم تعد الحكايات الكلاسيكية تجذب انتباهه. افتحي الحكايات الذكية واسأليه: إلى أين سيذهب هذا القطار السحري الآن؟ دعيه يغفو وهو غارق في خياله مع تلك النهاية الغريبة والعبثية تمامًا التي ابتكرها بنفسه.'),
  ('e9ba59d9-6287-434c-823d-456c6d21f0ef', 'موعد طبيب الأسنان 🦷', 'أمسك الفرشاة ويريد فحص أسنانكِ بمنتهى الجدية. افتحي فمكِ وامتثلي لتعليمات هذا الطبيب الطريف. يُعد لعب الأدوار من أكثر الطرق فاعلية ومتعة لتنمية الشخصية والتغلب على المخاوف.'),
  ('cafa10cc-4494-418e-834e-6ddf05c49140', 'ليست قمامة، بل كنز 🍬', 'هل أقام الدنيا لأنكِ رميتِ غلاف الشوكولاتة القديم الذي احتفظ به لأيام ولم يلعب به؟ ما ترينه قمامة قد يكون جزءًا ثمينًا من مجموعته. ولتهدئة بكائه، حوّلي انتباهه فورًا إلى شيء أكثر جاذبية.'),
  ('d9ad6664-d013-4d53-b45b-e81b7aa6c58c', 'انتصار بلا شمبانيا 🥂', 'نام طفلكِ. حتى إن لم تكن هناك شمبانيا، اسكبي الشاي الساخن في الكؤوس وتبادلي نخبًا مع شريككِ قائلين: «لقد تمكنا اليوم أيضًا من إدارة هذه الفوضى العاصفة». فأنتما فريق المنزل الراسخ الذي لا يعرف الكلل.'),
  ('e8db8e88-207e-4ac3-9421-9b1c49bdfd27', 'محقق البروكلي 🥦', 'هل اكتشف قطعة الخضار الخضراء الوحيدة في الحساء ورفض تناوله؟ طبّقي في خطة التغذية أبرع الحيل لخلط الخضراوات مع المعكرونة الملونة لتشتيت انتباهه، أو إخفائها بعد هرسها.'),
  ('cc3a0c4f-7f53-45a5-9f17-0dcfdb18b0c4', 'ذروة التعاطف 🩹', 'هل يضع ضمادة على ذراع دبدوبه ويقبّله لأنه يؤلمه؟ تأمّلي قلبه الكبير المفعم بالرحمة. وسجّلي بكل فخر هذا التعاطف العميق في متتبّع النمو بوصفه من أجمل سماته الشخصية.'),
  ('1f4d8560-3286-4e95-8474-fcafd793fada', 'ساحة الأب 👨‍👧', 'هل نفد صبركِ؟ أغلقي باب الغرفة واتركي طفلكِ وحده مع والده. دعيه يتولى وحده قيادة ألعاب المنزل هذا المساء، واستريحي أنتِ.'),
  ('af913905-7dd6-4f3e-bf26-424dee34a1c5', 'انظري ماذا أفعل! 🤸‍♂️', 'هل يحاول جذب انتباهكِ بالوقوف على قدم واحدة أو القفز؟ إنه يبحث عن استحسانكِ. سجّلي مهارة التوازن الجسدي هذه في متتبّع النمو وصفّقي له.'),
  ('cd8e0cdd-1b7c-42e3-856f-3b4914ee1697', 'معارك الخضروات 🥦', 'هل يدفع الخضروات الخضراء إلى جانب الطبق؟ لا تدخلي في صراع معه. ابحثي ضمن الوصفات الصحية عن طرق ذكية لإخفاء الخضروات داخل الكعك أو أقراص اللحم.'),
  ('52a1e30d-f365-493c-8480-78b508714eb6', 'هل يخاف من الظلام؟ 👻', 'غالبًا ما يظهر الخوف من الظلام عند الاقتراب من سن 3.5 سنوات. ضعي مصباحًا ليليًا صغيرًا في الغرفة، وابتكري في الحكايات الذكية قصصًا عن أبطال شجعان.'),
  ('cbfa1fac-401d-41c2-974d-c9424b7436ce', 'حديث الأمهات 💬', 'هل ترهقكِ فكرة: «لماذا لم يعتد طفلي بعد على استخدام النونية تمامًا؟» انضمي إلى مجتمع Anacan، وستدركين أن لكل طفل وتيرته الخاصة.'),
  ('cde5f67f-33e9-4a06-9155-b70a56cb6c73', 'هل يغيّر نطق الكلمات؟ 🗣️', 'هل يتعمّد تغيير بعض الحروف وإصدار أصوات مضحكة ثم يضحك عليها؟ إنه يكتشف مرونة اللغة. شاركيه أنتِ أيضًا والعبا معًا ألعاب الكلمات.'),
  ('57748696-ab80-425d-85cf-6283ca454879', 'مشاعر الرفقة 👫', 'هل بدأ يحاول اللعب مع الأطفال الآخرين في الحديقة بشكل تفاعلي، لا بالتوازي معهم؟ لقد بدأت مرحلة التفاعل الاجتماعي رسميًا! راقبي هذه اللحظة من بعيد مع الحرص على سلامته.'),
  ('465bfed4-fe0b-4cbe-96cc-61ab753a7ff8', 'فن على الجسد 🖍️', 'ساوركِ الشك بسبب الهدوء المفاجئ، فوجدتِ طفلكِ يرسم تحفة فنية على ذراعيه بأقلام التلوين. لا تغضبي؛ فهو يستكشف مهاراته الحركية الدقيقة، ويمكن غسل بشرته بالماء على أي حال. خذي نفسًا عميقًا ووثّقي هذه اللحظة الطريفة.'),
  ('5f1b9ed1-3342-457d-874b-d33366fcceaf', 'سحر الهمس 🤫', 'يكون طفلكِ نشيطًا جدًا في السرير لدرجة أنه لا ينام. بدلًا من رفع صوتكِ، اخفضيه فجأة وتحدّثي إليه همسًا فقط. عندما يركّز ليستمع إليكِ، سينتقل دماغه تلقائيًا إلى وضع النوم.'),
  ('6ac2df5a-944c-4a22-9450-7bfad30550c4', 'قوة مجتمع الأمهات 💬', 'هل ترهقكِ فكرة أن هذا الطفل لن يهدأ أبدًا؟ انضمّي إلى مجتمع Anacan. عندما تقرئين تجارب الأمهات المشابهة، بل والأكثر طرافة، مع عناد أطفالهن، ستدركين أنكِ لستِ وحدكِ وستتنفسين الصعداء.'),
  ('7b051600-3f87-4940-baec-461cd64e5af1', 'أستاذ الفلسفة 🤔', 'لماذا لا نرى الريح؟ ولماذا تسقط الأوراق؟ أسئلة عميقة ترهق ذهنكِ منذ الصباح الباكر. لا تحاولي تقديم تفسيرات علمية لساعات؛ ففي هذا العمر، ستكفيه تمامًا إجابات خيالية ولطيفة مثل: لأن الأشجار تبدّل ملابسها.'),
  ('7bab0bc1-e2b8-4588-8d81-ecc8ddbde523', 'رقصة الظلال 🐰', 'يتذرّع طفلكِ بخوفه من الظلام ليهرب من السرير. أطفئي جميع أضواء الغرفة، وشغّلي مصباحًا يدويًا، واصنعي بيديكِ ظلال طيور وكلاب على الحائط. خلال ثوانٍ، سيتحوّل الظلام الذي يخشاه إلى مسرح ممتع.'),
  ('d0ef94fa-1acc-4932-b3b2-947791c88119', 'الذكاء الاصطناعي المنقذ 🤖', 'ألا تجدين إجابات لأسئلة طفلكِ أو تفسيرًا لتصرفاته الغريبة؟ استعيني بـ Anacan AI. سيشرح لكِ بأسلوب أطباء الأطفال، وبطريقة موجزة ومطمئنة، كيف تعمل أدمغة الأطفال الذين تجاوزوا سن الثالثة.'),
  ('2e15df12-458b-434c-ac05-d42b6b0a04b3', 'دفء أنفاسه 💖', 'لقد أرهقكِ طوال اليوم وعاندكِ في كل شيء. لكنه الآن مستلقٍ في السرير وملتصق بصدركِ، وتملأ أنفاسه المنتظمة الغرفة. هذه هي أعظم مكافأة للأمومة. ضمّيه إلى صدركِ وانسي كل التعب.'),
  ('b9503491-2c22-4639-94ac-cc1a79aea888', 'فخر الحذاء المعكوس 👟', 'ارتدى طفلكِ حذاءه بالعكس، لكنه يمشي بفخر شديد وكأنه فتح العالم. لا تتدخّلي ولا تحاولي تصحيح وضعه. ثقته بنفسه واستقلاليته أهم بمليون مرة من المظهر الأنيق لملابسه.'),
  ('9fedc843-d647-418d-b31f-ad9bf956e849', 'قائمتكِ في جيبكِ 🛒', 'وسط فوضى الحياة اليومية، هل نفد الشامبو أم المناديل المبللة؟ لا تحاولي الاحتفاظ بكل شيء في ذاكرتكِ، بل دوّنيه فورًا في قائمة التسوق وزامنيها مع زوجكِ.'),
  ('ac1c42c5-b375-4935-bfbe-c3b0f8da74a1', 'الحاجة إلى الهدوء 🤫', 'أول نصف ساعة بعد نوم طفلكِ هي الفترة الأكثر حساسية. تحققي من مستوى الضوضاء بالديسيبل باستخدام مقياس الصوت، واخفضي صوت التلفاز في الغرفة المجاورة.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('602f2986-8e86-421e-ab71-94038d048ccf'::uuid, 'يتحدث كمحامٍ 🗣️', 'هل بدأ يحاول التفاوض معكِ بالكلمات؟ هل يقول: دعيني ألعب قليلًا ثم سأنام؟ إن مهاراته اللغوية تتطور بشكل رائع، لكن لا تنسي الحفاظ على حدودكِ.'),
  ('6701933c-47e8-4c97-996b-a27409d87c3c', 'الأحجيات والمنطق 🧩', 'هل يحاول تركيب أحجيات مكوّنة من 5-6 قطع؟ إنه يتعلم مبادئ الهندسة والمنطق. لا تعيقي هذه الحركات المتكررة، فهي مفيدة لتعلّمه.'),
  ('a0d7169c-229c-430c-a926-4c31eef15e2c', 'دعم الأب 🫂', 'احرصا على التناوب عند استيقاظ طفلكِ ليلًا. ففي بعض الأحيان، لا يهدّئه فورًا في الظلام سوى ربتات والده المنتظمة ورائحته المألوفة.'),
  ('55bba77e-306b-49e8-94ad-180de8387a8b', 'طلب التفاحة الزرقاء 🍏', 'ما إن يفتح عينيه حتى يصرخ طالبًا منكِ تفاحة زرقاء. لا تشرحي له أن هذا غير موجود في الطبيعة، ولا تحوّلي الموقف إلى درس في الفيزياء أو الأحياء. قولي له: التفاحات الزرقاء ما زالت نائمة، تعال نوقظ التفاحة الحمراء، وقدّمي لمنطقه العبثي ردًا عبثيًا بالقدر نفسه، لكنه فعّال.'),
  ('5d5d4766-5ced-4cf7-8ea9-3acdffe118cf', 'هوس البطانية 🛏️', 'يكاد يغطّ في النوم، ثم يبدأ فجأة بالبكاء قائلًا: البطانية تلامس قدمي اليسرى! ابتسمي في سرّكِ لهذا الهوس الجديد الذي ابتكره طفلكِ في عمر 3 أعوام ونصف لتأخير موعد النوم. عدّلي البطانية من دون أن تقولي شيئًا، ثم أطفئي أضواء الغرفة تمامًا وبحزم.'),
  ('8bcf9de1-187f-451e-8f68-1235d768b6ad', 'ثمن الهدوء المريب 💄', 'هذه هي نتيجة 10 دقائق من الهدوء المفاجئ في المنزل: تدخلين الغرفة فتجدينه قد لوّن وجهه والمرآة بأحمر شفاهكِ المفضل. لقد فات أوان الغضب.'),
  ('dbfc71ef-a5a7-4ece-831b-f33ebb8aff4c', 'ريمكس الكلمات 🗣️', 'يدمج كلمتَي الماء والحليب ليبتكر كلمات خيالية تمامًا مثل «حليباء»، ثم يضحك. إنه يصنع ريمكس خاصًا بقاموسه! شاركيه هذه الألعاب اللغوية بضحكة عالية، فبهذه التجارب تحديدًا يتعلم دماغه استكشاف حدود اللغة.'),
  ('4d3c3b0d-80ec-45f4-815f-fb2e6cc34948', 'انفجار مفاجئ من الحب 🫂', 'الطفل الذي طلب منكِ في الصباح أن تبتعدي، يلف ذراعيه بقوة حول عنقكِ عند الذهاب إلى الفراش ويقول: «أحبكِ بقدر الدنيا كلها». تلك هي مفارقة الأمومة! استنشقي أنفاسه الدافئة ودعي تعب اليوم كله يتلاشى.'),
  ('50186ca0-d65c-4eb2-80df-487222e57b43', 'ماما، ابتعدي عني! 💔', 'عندما لا يتحقق له ما يريد، ينظر إليكِ ويقول: «لا أريدكِ، ابتعدي عني!». لا تدعي ذلك يحطم قلبكِ، فهو لا يعرف بعد كيف يدير غضبه. لا تأخذي كلامه على محمل شخصي، بل قولي له: «أنا هنا، وسنتحدث عندما تهدأ»، وامنحيه مساحة ليعيش مشاعره.'),
  ('ee0e20bd-35e2-417c-adfc-d1000ee7da40', 'محامي متجر البقالة 🛒', 'بدلًا من أن يرتمي على الأرض مطالبًا بالحلوى في متجر البقالة، يساومكِ قائلًا: «إذا اشترينا هذه، فسأتناول حسائي في المنزل». تهانينا، محاميكِ الصغير يكبر! ولتجنب النسيان، أبقي قائمة التسوق مفتوحة حتى لا تنحرفي عن هدفكِ الأساسي أثناء التفاوض معه.'),
  ('2ee42120-6dce-4972-a1f5-41636027a46e', 'تسونامي حوض الاستحمام 🌊', 'لم يعد الاستحمام في الحوض من أجل النظافة، بل أصبح لعبة لصنع تسونامي صغير. دعي الماء يتناثر في كل مكان. فتأثير الماء المغناطيسي الساحر والممتص للطاقة سيغسل كل تلك الطاقة السلبية والعنيدة التي تراكمت داخله طوال اليوم، ويحملها إلى البالوعة.'),
  ('3a758cd5-028f-4ac8-be02-5dda6a95b453', 'من حق الأم أن تتكاسل 🍕', 'هل تشعرين اليوم برغبة في الصراخ بسبب كل شيء؟ هل المنزل في حالة فوضى؟ دعي التنظيف جانبًا، ولا تشعلي الموقد. اطلبي بيتزا أو أي وجبة جاهزة هي الأسهل. تخلّي عن وهم الأم المثالية، فصحتكِ النفسية أثمن بكثير من الطعام المنزلي.'),
  ('d683b351-38a0-49ed-a8b1-b2fe98cd3d08', 'الإصرار على سكب الماء بنفسه 💧', 'يصر على أن يسكب الماء بنفسه من الإبريق الكبير في الكوب الصغير. فينسكب الماء على الطاولة، ثم على الأرض. لكن انظري إلى يديه الصغيرتين وهما تمسكان بقطعة القماش وتحاولان تنظيف المكان. إنه يتعلم المسؤولية من خلال الأخطاء، وتلك الفوضى هي جوهر النمو.'),
  ('746ce0d9-945c-4d05-9518-1097d9f22fcd', 'التعرّف إلى المقص الصغير ✂️', 'هل يحاول قص الورق بمقص بلاستيكي آمن للأطفال؟ إنه تمرين رائع للمهارات الحركية الدقيقة! احرصي على تسجيل ذلك في متتبع النمو.'),
  ('42ac5c0d-b412-4999-8839-ddf0e44a9d4b', 'ذراعا الأب السحريتان ✈️', 'كاد ذراعاكِ تنفصلان من حمله طوال اليوم، لكنه لا يزال مفعمًا بالطاقة ويرفض الذهاب إلى السرير. استدعي الأب للمساعدة. فعندما يرفعه في الهواء ويلعب معه لعبة الطائرة، تملأ القهقهات الغرفة، وتتبدد في ثوانٍ كل تلك الطاقة المتراكمة التي بدت بلا نهاية.'),
  ('5a50a7bc-7ff1-421e-abac-beffc69e1480', 'تحدي حافة الرصيف 🧱', 'في الطريق إلى الحديقة، يصرّ على السير فوق أضيق وأعلى جزء من حافة الرصيف كأنه بهلوان يمشي على حبل، بدلًا من سلوك الطريق المعتاد. هكذا تتطور مهاراته الحركية الكبرى وقدرته على التوازن! أمسكي بذراعه لحمايته، ودعيه يبلغ هذه القمة الصغيرة التي تحمل أهمية كبيرة بالنسبة إليه.'),
  ('fd37073a-86b1-4420-9d46-293b17c2e64b', 'نزهة مع كلب غير مرئي 🐕', 'يقف في وسط الغرفة، ويمد يده إلى الأسفل ليداعب كلبًا غير مرئي ويتحدث إليه. إنها أكثر مراحل الخيال براءة. اسأليه: «ما اسم الكلب؟»، وضعي وعاء ماء خياليًا في إحدى زوايا الغرفة، لتصبحي ممثلة مساعدة في هذا العرض المسرحي الرائع.'),
  ('29371981-c485-4102-9d09-323cae4a8b4c', 'تمرّد خزانة الملابس 🕶️', 'جاء لتناول الفطور مرتديًا نظارة شمسية وقبعة شتوية، ورفض خلعهما رفضًا قاطعًا. لا تكترثي بالمظهر أو بما سيقوله الناس. فحرية اتخاذ قراره والدفاع عنه أساس نفسي أهم بكثير من مدى ملاءمة ملابسه.'),
  ('51cdbeb9-6ab2-41f5-bfe2-9e148aedb489', 'المقياس الرقمي للصمت 🤫', 'تكاد ضوضاء المنزل تجعل أذنيكِ تطنّان. وعندما يخلد أخيرًا إلى النوم، فعّلي أداة قياس الصوت. إن مشاهدة مستوى الصمت الرقمي على الشاشة وهو ينخفض إلى 0-10 ديسيبل تمنح دماغ الأم المتعب أجمل تدليك بصري مهدئ.'),
  ('fca5f016-a334-4b48-86a0-e10c617f28f2', 'منقذ النملة 🐜', 'هل وقف في الحديقة باكيًا ليحمي نملة على الأرض من أن تُدهس؟ انبهري بهذا القدر الهائل من التعاطف والرحمة في قلبه.'),
  ('02c49204-da15-4fa6-aab8-953dbda0aa33', 'أنا في الحكاية الذكية 🪄', 'لقد أرهقت قراءة الكتب الكلاسيكية أحبالكِ الصوتية. افتحي الحكايات الذكية، واجعلي طفلكِ بطل القصة، وأصوات الغابة الهادئة خلفيتها، لتصنعي جلسة نوم استثنائية آسرة لا تتطلب منكِ أي جهد.'),
  ('b5cdd715-cb24-4a73-93b6-d40eb1d78c2e', 'المواساة الصامتة من المجتمع 💬', 'هل تخنقكِ فجأة فكرة: «لن أعود أبدًا إلى شخصيتي السابقة الحرة الخالية من الهموم»؟ ادخلي إلى مجتمع Anacan. ستجدين العزاء عندما تقرئين أن أمهات أخريات يعشن أيضًا هذه المشاعر الثقيلة والطبيعية جدًا، وأنها مجرد مرحلة من مراحل الأمومة.'),
  ('d01a4de6-1799-4ace-b8f9-b22ea720b143', 'إصرار «انظري إليّ!» 👀', 'هل يأتي ويدير وجهكِ نحوه عندما تنظرين إلى الهاتف أو تنشغلين بشيء آخر؟ إنه يريد اهتمامكِ الكامل. اجعليه يشعر بأنكِ تستمعين إليه من خلال التواصل البصري معه.'),
  ('ee6a7a57-d3a9-4c19-bc94-5bb7b56c8f9c', 'حان دور الأب 👨‍🍼', 'لا تتحملي الاستيقاظ ليلًا وحدكِ طوال الوقت. أيقظي شريككِ أيضًا؛ فالعمل كفريق يعني تقاسم المسؤولية بالتساوي.'),
  ('4e5540da-110f-46b1-a6fe-0833314d27a6', 'حيرة ماذا أطبخ 🍲', 'هل نفدت أفكاركِ لقائمة الأطعمة التكميلية؟ لا تتيهي في الإنترنت، واكتشفي نكهات جديدة في قسم الوصفات الصحية.'),
  ('7d3efca9-83bd-4ef7-a064-007baae56a2f', 'حكاية خاصة 🪄', 'أنشئي في الحكايات الذكية قصة مميزة يكون طفلكِ بطلها: صغير شجاع يلوّن العالم بمقصه السحري.'),
  ('fa3aa9fa-1390-45bd-833a-86ce9790410b', 'دعيني أساعدكِ! 🧹', 'هل يحاول أخذ الملابس من يدكِ عندما تطوينها؟ إنه يشعر بأنه أصبح كبيرًا. أعطيه منشفة صغيرة ودعيه يساعدكِ.'),
  ('9049cae3-8dbb-4e95-8c21-0965664d904f', 'سأخبركِ بسرّ 🤫', 'عندما يدخل السرير وتوشك عيناه على الإغماض، يقول فجأة: ماما، سأخبركِ بسرّ، محاولًا طرد النوم. لقد أصبح الأطفال خبراء بحق في فن تأخير موعد النوم. ابتسمي وقولي له: ستخبرني بسرّك في المنام، ثم أطفئي الأنوار بحزم.'),
  ('a097a156-cfb7-4bbb-a187-0b6a9ba7dade', 'كريمة البسكويت فقط 🍪', 'هل لعق الكريمة الموجودة في وسط قطع البسكويت الدائرية، ثم صفّ الأجزاء الجافة على حافة الطاولة؟ تهانينا، لقد تعرفتِ رسميًا إلى فلسفة الطعام لدى طفل بعمر 3.5 سنوات. اكتشفي في قسم الوصفات الصحية وجبات خفيفة أكثر توازنًا، لكنها ممتعة وتلفت انتباهه.'),
  ('bf046ede-b62a-43aa-8a59-9305494237e5', 'ممنوع أن تغنّي! 🛑', 'بدأتِ تدندنين مع أغنية الأطفال التي كانت تُعزف في الخلفية، فصرخ على الفور: لا تغنّي! فهو المغني المنفرد الوحيد في الغرفة، ومحاولاتكِ الغنائية تزاحمه على مسرحه. لا تنزعجي، واتركي المسرح لهذا الأناني الصغير.'),
  ('524b4634-31bf-4fa3-860b-d29e08cc3c10', 'نبرات صوت مختلفة في الحكاية 🪄', 'افتحي القصص الذكية هذا المساء، لكن اقرئي النص بأصوات مختلفة. اجعلي صوت الدب غليظًا وصوت الطائر رقيقًا، واصنعي مسرحًا صغيرًا في الغرفة. فهذا يكسر الرتابة ويجذب انتباه طفلكِ فورًا إلى عالم الحكاية، ومنه إلى النوم.'),
  ('603225e8-0807-426b-b793-892dfeb9e281', 'اكتشافات بالهمس في الظلام 🌙', 'أطفئي أضواء الغرفة تمامًا. استلقي بجانبه، واهمسي في أذنه بصوت خافت جدًا عمّا حدث خلال اليوم أو عن أكثر صفة تحبينها في شخصيته. الهمس من أكثر الطرق سحرًا لتهيئة الدماغ للنوم ونسيان الضوضاء.'),
  ('60fcf611-529f-4586-9532-af738483766f', 'مظلة داخل المنزل ☂️', 'الشمس مشرقة في الخارج، لكنه يريد التجول داخل المنزل بمظلة مفتوحة. فخياله لا يعترف بقيود المكان المادية. إذا كانت هناك مساحة فارغة في المنزل، فدعيه يُنشئ لنفسه مخيمًا صغيرًا تحت تلك المظلة. لا تخنقي منطق طفلكِ بأعراف المجتمع.'),
  ('831decae-1343-4bbb-bf11-1f398cc1bc2d', 'اختبار «لا» في المتجر 🛒', 'طلب الحلوى في وسط المتجر تمامًا، فقلتِ «لا»، وبدأ هو بالبكاء. وعلى الرغم من نظرات الآخرين التي تحاكم أسلوب تربيتكِ، لم تتراجعي عن قراركِ. أنتِ أم رائعة! ولتجنب النسيان، أبقي عينيكِ على قائمة التسوق كي تتمكنا من المغادرة سريعًا.'),
  ('1d613098-d421-410e-ae85-8cfd9552b432', 'لماذا ناديتِ باسمي بلا سبب؟ 😤', 'قلتِ له ببساطة: «تعال، الطعام جاهز»، لكنه غضب وبدأ يبكي قائلًا: «لماذا ناديتِ باسمي؟». في هذا العمر تكون المشاعر مختلطة إلى درجة أنهم قد ينزعجون أحيانًا حتى من لا شيء. لا تشرحي شيئًا، فبعد دقيقتين سيهرع إلى الطعام من تلقاء نفسه.'),
  ('ca0366a7-8e5e-4057-8bed-6cb2f6dcfa02', 'الذكاء الاصطناعي والمخاوف الغريبة 🤖', 'هل بدأ فجأة يخاف من السيارة الحمراء التي اعتاد اللعب بها دائمًا؟ إذا كانت المخاوف غير المبررة تقلقكِ، فأغلقي منتديات الإنترنت المليئة بالتجارب الصادمة. واحصلي من Anacan AI على إجابة علمية ومطمئنة حول غرائب خيال الطفل في عمر 3.5 سنوات.'),
  ('cacabcad-105f-4eff-bcae-aa81bf6e1cbd', 'مشاهدة فيلم معًا كزوجين... 🎬', 'نام طفلكِ! وأخيرًا جلستِ مع شريككِ على الأريكة لمشاهدة فيلم، لكنكما غرقتما في نوم عميق عند الدقيقة 10. هذا هو واقعكما. ذلك المشهد المتعب وأنتما نائمان متكئان أحدكما على الآخر هو أصدق تجسيد للعمل الجماعي.'),
  ('45baf1a1-9599-41ad-8361-b1f8a05e79a2', 'فتات الخبز في السرير 🍞', 'تفتحين عينيكِ صباحًا فتجدين السرير مليئًا بفتات البسكويت المملح. اتضح أنه أعد لنفسه وجبة الإفطار في الصباح الباكر. بدلًا من الصراخ، سجّلي هذه المهارة المستقلة في حل المشكلات كذكرى طريفة في متتبع النمو.'),
  ('6b819068-b681-48a9-82bf-6d4801827c9e', 'تحديق الأم في الجدار 🛋️', 'تعمّ الضوضاء الغرفة، ويضرب طفلكِ ألعابه بعضها ببعض، بينما تحدّقين أنتِ في الجدار الفارغ وقد شرد ذهنكِ تمامًا. هذه آلية دفاعية يستخدمها دماغكِ. لا تلومي نفسكِ على لحظة الجمود تلك التي تستمر 5 دقائق؛ فأنتِ بحاجة إليها لتعودي إلى الحياة من جديد.'),
  ('6b9b4528-1015-4f69-940f-0bb0951b3bab', 'أسئلة صادمة في الأماكن العامة 😳', 'هل سأل بصوت عالٍ في الحافلة أو المتجر: لماذا أنف هذه السيدة كبير هكذا؟ إنها تلك اللحظة التي تتمنين فيها لو تنشق الأرض وتبتلعكِ! بدلًا من إسكاته وإشعاره بالخجل، حوّلي انتباهه فورًا إلى غرض ملوّن آخر، واخرجي من الموقف بلباقة.'),
  ('8d369fcb-2b04-4658-a824-5b34c817cbfd', 'تحديات الأب غير المنطقية 🎲', 'يركض في أرجاء المنزل ليلًا حتى لا يرتدي ملابس النوم. فيقترح والده لعبة عبثية قائلًا: لنرَ إن كنت تستطيع ارتداء ملابس النوم وأنت مغمض العينين! وفجأة، يرتديها الطفل من دون أن ينتبه. لا يسعنا أمام ألعاب الآباء غير المنطقية والفعّالة هذه إلا التصفيق.'),
  ('5eac5298-1552-4198-9ef8-4a16006b3701', 'الحنين إلى «أنا رضيع!» 🍼', 'هل بدأ فجأة يحبو ويبكي مثل الرضيع ويقول: أنا رضيع، احضنيني؟ قد يخيفهم النمو أحيانًا أيضًا، فيرغبون في الاحتماء بذكريات طفولتهم المبكرة الآمنة. احتضنيه وداعبيه لبضع دقائق كما كنتِ تفعلين في تلك الأيام.'),
  ('bb01fed8-0d6f-4127-8a47-f959e37b46e4', 'حساء من الوحل 🍲', 'يمزج الماء بالتراب في الحديقة، ثم يمدّ إليكِ الوحل قائلًا: ماما، أعددت لكِ حساءً. لا مجال للاشمئزاز! تظاهري بتناول ذلك الحساء وكأنه ألذ طعام في العالم.'),
  ('c5e8c723-3ce3-424f-8294-5aece5936ca5', 'المتعة الرقمية للهدوء 🤫', 'انتهت الفوضى في المنزل أخيرًا ونام طفلكِ. افتحي مقياس الصوت وراقبي على الشاشة مستوى الهدوء في الغرفة (0-10 ديسيبل). رؤية تلك الأرقام القريبة من الصفر تؤثر في دماغ الأم المتعبة كأنها أغلى جلسة سبا في العالم.'),
  ('204c6838-b697-4616-9592-52e0162c6a92', 'الخدش على الموزة 🍌', 'بعد تقشير الموزة، رأى عليها خدشًا صغيرًا لا يتجاوز بضعة مليمترات، فصرخ: إنها فاسدة! سعي الأطفال إلى الكمال البصري يكاد يصل إلى حد الجنون. اقطعي ذلك الجزء بالسكين وقولي: لقد أنقذتها! وهكذا تنهين هذه الدراما الصغيرة.'),
  ('49d8e195-1371-46c6-a98a-c6f38e78e098', 'مهمة إغلاق الأبواب 🚪', 'يستمتع كثيرًا بإغلاق أبواب جميع غرف المنزل من الداخل وترككِ خارجها. إنه يعيد ابتكار مفهوم المساحة الشخصية! اتخذي الاحتياطات اللازمة حتى لا تنحشر أصابعه، لكن لا تفسدي عليه كثيرًا لعبة إعلان منطقته الخاصة.'),
  ('5b590891-270c-48fa-a5d7-d69f319ed48e', 'تدليك الكتفين من الأب 💆‍♂️', 'لقد أمضيتِ وقتًا طويلًا واقفة اليوم، حتى كاد ظهركِ ينكسر من الركض وراء طفلكِ وجمع الألعاب من الأرض. ما إن ينام، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ عماد المنزل، ولا بد للأعمدة أن ترتاح وتستعيد قوتها.'),
  ('5ff3402c-285a-4d58-a123-bc33ce162448', 'سأفعلها بنفسي! 🛑', 'يصرّ طفلكِ على ربط حذائه بنفسه، لكنه لا يستطيع فيغضب، ويرفض مساعدتكِ بعصبية أيضًا. خذي نفسًا عميقًا. الحفاظ على ثقته بنفسه أهم لمستقبله من الالتزام بجدول زمني تعرّض لبعض التأخير. انتظري.'),
  ('8d87e4f8-f5ae-4ad1-80cc-5a4fd0448346', 'مأساة «لقد نظر إليّ!» 👀', 'هل بدأ طفلكِ ينتحب في الحديقة لمجرد أن طفلًا آخر نظر إليه؟ بالنسبة إلى طفل بدأ للتو اكتشاف حدوده الاجتماعية، قد تبدو حتى نظرة شخص آخر تدخّلًا في مساحته. عانقيه وشتّتي انتباهه بقولكِ: «لقد كان ينظر فقط إلى قميصك الجميل».'),
  ('b272e283-3b37-4825-9917-d8f7f4f54d69', 'الهدوء مع الحكايات الذكية 🪄', 'يركض طفلكِ في الغرفة ويرفض الذهاب إلى السرير. خفّفي الإضاءة، ثم ابتكري قصة ممتعة في الحكايات الذكية واقرئيها له.'),
  ('ef54bc8d-fa9d-46df-a5e1-6c01e83dfefc', 'صفّ الألعاب في طابور 🚗', 'صفّ طفلكِ جميع سياراته من أحد طرفي الغرفة إلى الطرف الآخر بدقة متناهية، ولا يسمح بتحريك أيٍّ منها ولو قليلًا. إنه يبحث عن النظام البصري. راقبي عمل هذا المهندس الصغير بصمت من بعيد، ولا تفسديه.'),
  ('0136ed32-a803-4c48-aa0d-ab3379945e1c', 'كوني قارئة صامتة في المجتمع 💬', 'أنتِ متعبة جدًا ولا ترغبين في شرح أي شيء لأحد أو الفضفضة. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية كيفية تعامل الأمهات الأخريات مع نوبات الغضب العبثية نفسها قد تكون أقوى علاج صامت.'),
  ('b9bc7eed-7b9f-4aa8-8301-118abf554ade', 'أزمة حجم الملعقة الخطأ 🥄', 'كادت تقوم ثورة لأنكِ قدّمتِ الحساء بملعقة كبيرة. «كنت أريد الملعقة الصغيرة!» رغم أن الطعام هو نفسه، فإن الحجم الفعلي للملعقة يغيّر، وفق منطقه، مذاق الطعام الذي سيأكله. لا تجادليه، بل غيّري الملعقة ببساطة ووفّري طاقتكِ.'),
  ('c2cb9b1d-61a5-43c0-97ec-813152f9cfe1', 'هوس «غطّيني!» 🛏️', 'يكاد طفلكِ يغطّ في النوم، ثم ينكشف طرف الغطاء فيصرخ: «غطّيني!» استقامة حواف الغطاء تمامًا مسألة بالغة الأهمية بالنسبة إليه. سوّي الغطاء كأنه مكوي، وابتسمي في سرّكِ لهذه الطقوس الطريفة قبل النوم.'),
  ('4aca275a-17a5-44c6-88b5-fa54de701839', 'حبّ الضمادات 🩹', 'لقد وجد جرحًا وهميًا في جسده ويصرّ على أن تضعي عليه ضمادة. ليس هذا ألمًا جسديًا، بل مجرد حاجة إلى اهتمام الأم وحنانها. ضعي تلك الضمادة الصغيرة وقبّلي موضعها، وصدّقي أن ذلك سينقذ يومكِ.'),
  ('6549682b-784d-4e30-b184-53c2ea51b45f', 'المتعة البصرية للصمت 🤫', 'انتهت الفوضى في المنزل أخيرًا ونام طفلكِ. لا تسرعي إلى غسل الأطباق! افتحي مقياس الضوضاء وتأمّلي الهدوء التام في الغرفة (0-10 ديسيبل) لمدة 15 دقيقة، واشعري كيف يستريح ذهنكِ وكيف يشفيكِ هذا الصمت المرئي.'),
  ('c51feab8-8101-47a7-82b7-0a8e946ff974', 'هندسة الرمال 🏰', 'يحفر في صندوق الرمل بالحديقة بعمق وكأنه يبحث عن كنز، وقد اتّسخت ملابسه بالطين. لكن لا تقاطعي لحظة الاكتشاف هذه. إن اختيار ملابس مناسبة للطقس ولا بأس باتّساخها مسبقًا سيمنحكِ فرصة للاستمتاع بهذا المشهد دون توتر.'),
  ('95e37724-7f25-4dc6-a06e-d194ca45d333', 'رياضة المساء - القفز فوق الأب 🤸‍♂️', 'لم يتمكن طفلكِ من تفريغ طاقته ولا يريد الذهاب إلى السرير. اطلبي من الأب أن يستلقي على الأريكة واسمحي لطفلكِ بالقفز فوقه. ستملأ الأصوات المضحكة التي يصدرها الأب الغرفة بالضحك، وستنفد كل تلك الطاقة الزائدة خلال ثوانٍ.'),
  ('9680e706-6c53-46d8-b37d-e2b2ed358ee7', 'عناية الأم بنفسها 🥗', 'فكّرتِ في 3 قوائم طعام مختلفة لإشباعه، لكن هل بقيتِ أنتِ جائعة مرة أخرى؟ اختاري من قسم خطة التغذية وجبة غداء تمنح الطاقة، وغنية بالحديد والكالسيوم، ويمكن تحضيرها خلال 10 دقائق؛ فهي ليست للأطفال فقط بل للأمهات أيضًا. وامنحي نفسكِ ما تستحقينه من اهتمام.'),
  ('c0f71481-4d8f-40e3-87af-c4432426cfab', 'لعبة «من أنتِ؟» 🎭', 'ينظر إليكِ صباحًا بملامح شديدة الجدية ويقول: «من أنتِ؟ أين أمي؟». إنها ذروة تطور الخيال! شاركيه اللعبة وقولي: «أنا جارتكم، ستأتي أمك حالًا»، وغيّري نبرة صوتكِ لتواصلا هذا العرض المسرحي الرائع.'),
  ('17737c7f-74cb-4797-867c-90a8c03b4bfe', 'فنّ ورق الحمّام 🧻', 'بضع دقائق من الصمت... ثم تدخلين الغرفة فتجدين لفافة ورق الحمّام بأكملها قد فُكّت وانتشرت في المنزل! بدلًا من الغضب، اجمعي الأوراق واصنعا معًا رجل ثلج أو كرة. تغلّبي على الفوضى بالإبداع، لا بالصراخ.'),
  ('300e5d4c-57c8-45bf-bdcd-829a6024697a', 'كلمات حبّ تُهمس في الأذن 💖', 'لقد دفعكِ إلى الجنون طوال اليوم وعاندكِ في كل شيء. لكنه الآن نائم في سريره ببراءة شديدة... استلقي بجانبه واهمسي في أذنه بمدى حبكِ له، وبالأشياء الجميلة التي فعلها اليوم. يشعر الأطفال بصوت أمهم المليء بالحب حتى وهم نائمون.'),
  ('42d87f04-8d19-4c11-b1e4-703ee34de8db', 'اكتشاف الغسالة 🧺', 'يجلس طفلكِ أمام الغسالة ويركّز على الملابس وهي تدور، وكأنه يشاهد فيلمًا كرتونيًا. إنه ترفيه مجاني تمامًا ومهدئ للذهن. لا تقاطعيه، بل اغتنمي أنتِ أيضًا الفرصة واستريحي.'),
  ('56f07d8f-4184-4cda-b356-e566ad65a81d', 'محاولات الهروب من الحكاية 🏃‍♂️', 'أثناء قراءتكِ الحكاية، يقفز من السرير كلما سنحت له الفرصة ويركض ليحضر لعبة. إنه لا يريد الاستسلام للنوم. اخفضي صوتكِ فجأة إلى حدّ كبير وابدئي القراءة همسًا. سيضطر إلى العودة إلى السرير والتركيز كي يسمعكِ، ثم سيغفو.'),
  ('6cd2dfdf-7fcd-4bc3-bbbb-00a4d393d5f8', 'أنا كبير، سأشرب القهوة! ☕', 'يمد يده نحو فنجانكِ ويقول بإصرار: «لقد كبرت، وسأشرب القهوة أنا أيضًا!». إنه يريد فقط أن يكون جزءًا من عالمكِ. ضعي قليلًا من الحليب والكاكاو في فنجانه الصغير، وقولي له: «انظر، هذه قهوتك الخاصة بالأطفال»، ثم تبادلا نخب الفناجين معًا.'),
  ('7a51f55e-c494-489a-927c-6f2193813549', 'الطقس وحيلة ارتداء طبقات من الملابس ⛅', 'يكون الطقس متقلبًا مع اقتراب الربيع؛ باردًا صباحًا ودافئًا ظهرًا. تذكّركِ أداة الطقس والملابس باتباع أسلوب البصلة، أي إلباس طفلكِ طبقات متعددة. وفي الحديقة، انزعي عنه طبقة كلما شعر بالدفء، لتجنّبي تعرّقه وتخففي توتركِ أيضًا.'),
  ('063d0e5f-8a19-45c6-b301-96c01e527e0a', 'لعبة الأنف المسروق 👃', 'تقولين له: «أخذت أنفك!» وتُظهرين له إبهامكِ، فيصدق ذلك فعلًا ويبدأ بالبكاء! قد لا يتمكن خيال الطفل في عمر 3.5 سنوات أحيانًا من التمييز بين الواقع والوهم. قولي فورًا: «ها قد أعدته إلى مكانه»، ثم قبّلي أنفه وحوّلي هذه الصدمة الصغيرة إلى ابتسامة.'),
  ('31689193-e8a3-408a-bec9-cc30d1fc08c4', 'تبادل النظرات الصامتة مع شريككِ 🥂', 'نام الطفل أخيرًا. تجلسين أنتِ وشريككِ جنبًا إلى جنب على الأريكة، ولا تملكان حتى طاقة للكلام. تكتفيان بالنظر إلى بعضكما في صمت والابتسام. هذا التبادل الصامت للنظرات هو أجمل طريقة لتقولا: «نحن نتعامل مع هذه الفوضى ببراعة».'),
  ('7834ecb1-6218-4b7b-a3ed-c138894407b9', 'الذكاء الاصطناعي ونوبات العناد المفاجئة 🤖', 'هل أصبح طفلكِ الذي كان هادئًا حتى الأمس يتفاعل اليوم بعدوانية مع كل شيء؟ لا تبحثي على الإنترنت عن أسباب مخيفة. اسألي Anacan AI عن الأسباب النفسية لهذه القفزة النمائية (mental leap)، وبدّدي قلقكِ بإجابة معتمدة من أطباء الأطفال.'),
  ('9dcc2901-fb6b-4d84-a478-46c76064f671', 'أنا وجدته - الطفل الصغير المتملّك 🔑', 'يلتقط جهاز التحكم أو مفاتيح والده من الأرض في المنزل ويصرّ قائلًا: «أنا وجدته، إذًا هو لي!». بالنسبة إليه، العثور على الشيء يعني امتلاكه. لا تنتزعيه من يده بالقوة؛ بل قولي: «شكرًا لأنك وجدته من أجلي»، ثم استعيديه بعد توجيه انتباهه إلى لعبة أخرى.'),
  ('c3b5e358-e6dc-46cb-a0bf-1d51adcfbfec', 'منتجع صحي مصغّر في الحمّام 🛀', 'هذا المساء، لا تضعي طفلكِ وحده في حوض الاستحمام، بل خصّصي وقتًا لنفسكِ أيضًا. بعد أن ينام طفلكِ، املئي الحوض بالماء الدافئ مع قليل من الرغوة وأضيئي شمعة واحدة في الحمّام. أغلقي الباب واستمتعي بـ15 دقيقة تخرجين فيها من دور الأم وتعودين إلى ذاتكِ من جديد.'),
  ('cfb02ba9-2584-45e0-a1c3-ce6672adabe6', 'محاولة تصفيف الشعر ✂️', 'تدخلين الغرفة فتجدين طفلكِ يحمل مقصًا ويحاول قص شعر دميته. عيش هذه اللحظة هو كابوس كل أم. خذي المقص منه بهدوء، واحتفظي بهذه المحاولة الطريفة لتصفيف الشعر كذكرى مضحكة في جلسة تصوير طفلكِ.'),
  ('175e4578-dab7-4e75-8a87-dd96baf6d2c6', 'أعيدي الأغنية! 🎶', 'يريد سماع الأغنية التي كانت تُبث عبر الراديو وانتهت مرة أخرى. تشرحين له أنها كانت على الهواء مباشرة وقد انتهت، لكنه يبكي قائلًا: أعيديها! لا يستوعب عقل الطفل بعدُ فكرة البث المباشر. لتشتيت انتباهه، ابدئي بغناء الأغنية بنفسكِ بصوت مختلف ومضحك.'),
  ('a0a2a59b-c696-48e8-beb8-ba5ae29c9bb7', 'إضافات غير ضرورية إلى قائمة التسوق 🛒', 'قبل الذهاب إلى المتجر، فتحتِ قائمة التسوق، فإذا بطفلكِ يأتي من خلفكِ ويضغط على شاشة الهاتف، مضيفًا إليها حروفًا غير مفهومة وكلمة «شوكولاتة» مرارًا. نعم، إنهم يستكشفون العالم الرقمي بسرعة كبيرة!'),
  ('f9e8851b-f40e-4ed9-a246-2e1405232755', 'كوب شاي في هدوء ☕', 'يرتّب ألعابه في صف وسط الغرفة ويلهو بمفرده. أرجوكِ، لا تهدري تلك اللحظة في تنظيف المنزل! اجلسي على الأريكة، واشربي قهوتكِ أو شايكِ ساخنًا، واستمتعي بهذا الهدوء لمدة 10 دقائق من دون التفكير في أي شيء.'),
  ('92b2cc3b-1b0f-4e45-a121-5ff8bfe1a92e', 'حيلة مؤقّت النوم ⏱️', 'هل يشعر فجأة بالعطش عند حلول موعد النوم، أو يرغب في دخول الحمّام، أو يودّع الجدار؟ اضبطي مؤقّتًا وطبّقي قاعدة «عندما يرنّ الجرس، ينام الجميع»، لتُنهي هذا الوداع الذي لا ينتهي وتفادي هذه المناورة البارعة من دون جدال.'),
  ('9d39f5c1-6418-4ab4-8bba-64b21fccd4ac', 'الفنان الحقيقي يختار الجدار 🖍️', 'بضع ثوانٍ من الصمت انتهت بكارثة. تدخلين الغرفة فتجدين طفلكِ قد رسم تحفة فنية على الجدار بأقلام التلوين. خذي نفسًا عميقًا. فمهاراته الحركية الدقيقة تتطور، ويمكن تنظيف الجدار في جميع الأحوال. احرصي على تصوير هذه التحفة لتضحكي عليها في المستقبل.'),
  ('dda9eb22-cebb-4f1b-962b-3223d17b83eb', 'قوة مجتمع Anacan 💬', 'هل تستنزفكِ فكرة: لماذا طفلي عنيد إلى هذا الحد؟ ادخلي إلى مجتمع Anacan. عندما تقرئين عن نوبات الغضب العبثية المشابهة التي تحدث في منازل الأمهات الأخريات، ستدركين أنكِ لستِ وحدكِ وأنكِ تسيرين في مسار طبيعي تمامًا.'),
  ('1c56259d-5943-4110-9eaf-5c1870b222b1', 'لعبة الغميضة في الصباح الباكر 🙈', 'تكونين متأخرة عن العمل أو الحضانة، بينما يختبئ طفلكِ خلف الستارة ويقول: «ابحثي عني!». رغم أن أعصابكِ قد تكون مشدودة، فإن الصراخ لن يؤدي إلا إلى إطالة الأمر. شاركيه اللعب لدقيقتين قائلةً: «ترى أين اختبأ طفلي الجميل؟»، ثم اعثري عليه وأخرجيه من مخبئه.'),
  ('7b148d61-8829-4863-ab9e-6d4a0bb51f81', 'فرز الطعام حسب لونه 🍅', 'يفرز طفلكِ الأطعمة في طبقه حسب ألوانها وأشكالها، ثم يدفع كل ما هو أخضر إلى الجانب. ادخلي إلى خطة التغذية واكتشفي كيف تحوّلين تلك الخضراوات إلى هريس غير ملحوظ وتخفينها في صلصات لذيذة، لتفوزي بهذه اللعبة سرًا.'),
  ('b42730c5-7949-4ebf-93b6-63b027cfa615', 'حكايات الأب المختلقة 📖', 'لن يكون صوتكِ هو الراوي في الغرفة هذا المساء. أعطي كتاب الحكايات للأب، ودعيه يروي القصة بطريقة معكوسة ومضحكة وعبثية عن قصد. واستمتعي بمشاهدة طفلكِ وهو يصحح له بكل حماس ويضحك من قلبه مع أبيه.'),
  ('4e6a6d24-79a1-45e7-b7a8-72b6ff0e22f5', 'تفريغ الغضب في دفتر المزاج 📝', 'ألا يرى أحد مدى تعبكِ في المنزل؟ دفتر المزاج هو رفيق أسراركِ الأكثر هدوءًا. اكتبي فيه كل التفاصيل التي أثارت غضبكِ اليوم، ثم شاهدي على الشاشة كيف يخف العبء عن ذهنكِ وتتلاشى همومكِ.'),
  ('5c983784-bca8-4998-adca-b16664e5be99', 'التجول في المنزل بالقبعة 🧢', 'يريد طفلكِ ارتداء قبعة الشتاء داخل المنزل. يصرّ على ذلك ويرفض خلعها. انسي الأعراف الاجتماعية؛ وحتى لا تحبطي إبداعه وحريته في اتخاذ القرار، دعيه يقضي يومه بهذه الإطلالة المختلفة والمضحكة. ما دامت درجة حرارة الغرفة مناسبة، فدعيه يتجول بها.'),
  ('9d6dd60c-7863-4418-b9e4-e9cffd903339', 'صدمة «أنتِ لا تسمعينني!» 😠', 'بينما تنظرين إلى هاتفكِ أو تحرّكين الطعام، يأتي طفلكِ ويدير وجهكِ نحوه قائلًا: «انظري إليّ!». وهو محق؛ فهو لا يريد مجرد وجودكِ الجسدي، بل يريد اهتمامكِ الكامل وغير المشتت. توقفي عما تفعلينه واستمعي إليه لمدة 3 دقائق فقط، مع الحفاظ على تواصل بصري كامل.'),
  ('45e62ed0-8906-4bfa-998b-97725faac7dc', 'محاولات التعارف في الحديقة 🤝', 'يقترب طفلكِ من طفل لا يعرفه في الحديقة ويعرّف بنفسه قائلًا: «اسمي...». تتشكل مهاراته الاجتماعية بسرعة مذهلة. سجّلي محاولاته الجريئة للتواصل في متتبع النمو، لتبقى ذكرى تدعو إلى الفخر ضمن تطور شخصيته.'),
  ('6538fe5a-5021-49de-8c05-b4294e3a7259', 'مرحلة «لا» العنيدة 🛑', '«هل تريد الماء؟» — «لا!». لكنه يبكي طلبًا للماء بعد 5 ثوانٍ فقط. إنها مرحلة يختبر فيها نتائج قراراته؛ فقد يقول «لا» حتى للأشياء التي يريدها فعلًا. ضعي الماء على الطاولة ولا تجبريه، وسيشربه بعد أن ينتهي صراعه الداخلي.'),
  ('c5259254-085d-4cab-81d7-de92adaaa126', 'نوم هانئ مع الحكايات الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب. افتحي الحكايات الذكية، واجعلي طفلكِ بطلها الرئيسي وغرفته المكان الذي ينبغي فتحه، وابتكري جلسة نوم صوتية استثنائية لا تتطلب منكِ أي جهد، واستريحي أنتِ أيضًا.'),
  ('3267eb25-4eba-48a9-b86e-272c45f62299', 'مسرح الظلال في الغرفة المظلمة 🐰', 'يتذرع بالخوف من الظلام ليهرب من السرير. أطفئي جميع أضواء الغرفة، وشغّلي المصباح اليدوي، واصنعي بيديكِ على الحائط ظلالًا لطيور وكلاب. وفي ثوانٍ، سيتحول الظلام الذي يخيفه إلى مسرح ممتع.'),
  ('4ac972f2-0058-41fe-9a63-593036a6aa46', 'الحفاظ على الهدوء باستخدام مقياس الصوت 🤫', 'ضجيج المنزل يصمّ أذنيكِ. عندما يخلد أخيرًا إلى النوم، فعّلي أداة مقياس الصوت. إن مشاهدة تلك الأرقام القريبة من الصفر على الشاشة، وذلك الصمت الرقمي، هي أجمل تدليك بصري لعقل الأم المتعبة.'),
  ('b4510edb-beed-40b8-b0ad-884291f78f89', 'ديكتاتورية «لا تجلسي!» 🪑', 'ترغبين في الجلوس على الأريكة، لكنه يركض قائلًا: «دبدوبي سيجلس هناك، قفي أنتِ!». إنه يحاول إدارة المنزل. حافظي على التوازن والسلام في الغرفة من دون كسر إرادته بقسوة، وقولي له: «دبدوبك هنا، وسأجلس أنا بجانبه».'),
  ('a33e5975-6dcb-4e61-93db-f52a429ffcb8', 'Anacan AI: لماذا يكذب الأطفال؟ 🤥', 'قال: «أنا لم أسكب الماء، بل اللعبة هي التي فعلت ذلك». فهل يكذب أم يُعمل خياله؟ لا تبحثي على الإنترنت عن إجابات مخيفة. اسألي Anacan AI واكتشفي أن هذه التصورات لدى طفل بعمر 3.5 سنوات مرحلة طبيعية تمامًا من مراحل النمو، واطمئني.'),
  ('f03a726a-5a9c-4eda-ab04-4d6b21a432cd', 'نوبة ضحك مع شريككِ 🥂', 'لقد نام طفلكِ أخيرًا. وبينما تروين لشريككِ ذلك الموقف العبثي الذي أفقدكِ صوابكِ خلال اليوم، تنفجران فجأة في نوبة من الضحك. أجل، هذه الضحكات هي ألذ مكافآت الأمومة والأبوة.'),
  ('fce85c76-de6a-416c-a8d9-e7fd462bd967', 'اصطحاب الألعاب إلى الحمّام 🛀', 'لا يريد الاستحمام، لكنه يوافق على دخول الماء بعد أن يجمع كل سياراته ودببته البلاستيكية في حوض الاستحمام. لا تمنعيه. فتلك الألعاب في الحوض هي أفضل وسيلة تساعده على الاستسلام لتأثير الماء المهدئ.'),
  ('383239b8-7f85-4507-9f51-cdc8a13d1e8f', 'عشق المعكرونة 🍝', 'يرفض اليوم اللحم الذي كان يحبه حتى الأمس، ولا يريد طوال اليوم سوى تناول المعكرونة. لا تدخلي معه في صراع إرادات. تعلّمي من الوصفات الصحية كيف تُخفين البروتينات والخضراوات داخل المعكرونة على هيئة صلصة غير ملحوظة، واكسبي الجولة.'),
  ('6fb57a61-aa7b-441f-afc3-ed5b09208ed5', 'رقصات أمام المرآة 🪞', 'يقف طفلكِ أمام المرآة ويغني ويجرّب حركات رقص مختلفة. إنه يختبر إيقاع جسده وكيف يبدو! سجّلي بسعادة هذا الوعي الجسدي والإحساس بالإيقاع في متتبّع النمو.'),
  ('86182307-b484-4518-a023-a22ef5f8216d', 'ثنائي النوم الهامس 🌙', 'يكون طفلكِ نشيطًا جدًا في السرير لدرجة أنه لا ينام. بدلًا من رفع صوتكِ، اخفضي نبرته فجأة وابدئي بغناء أغنيته المفضلة همسًا. عندما يركّز طفلكِ ليسمعكِ، سيشعر دماغه تلقائيًا بالاسترخاء وينتقل إلى وضع النوم.'),
  ('4cd431fe-3e79-44d3-a7ca-53965a307626', 'تمشيط الشعر هو العدو 🪮', 'ما إن يرى المشط حتى يصرخ ويفرّ من الغرفة. أوقفي الصراع. أعطيه المشط أولًا ودعيه يمشّط شعركِ أو شعر دميته. بعد أن يشعر بأنه المتحكّم، سيسمح لكِ بأخذ دوركِ.'),
  ('7de027d7-5609-44f6-aeb7-25a62639a344', 'الدعم في مجتمع Anacan 💬', 'هل يخنقكِ فجأة شعور بأنكِ لن تعودي أبدًا إلى ذاتكِ القديمة الحرة؟ شاركي هذا الشعور العابر، لكنه ثقيل وعميق جدًا، مع الأمهات في مجتمع Anacan، واحصلي منهن على المواساة والدعم لأنهن مررن بالتجربة نفسها.'),
  ('f8f300ba-8e5d-4a43-a3bc-e71f82ec47f0', 'العلاج بالماء 🌊', 'أحيانًا لا ينجح أي شيء، ويظل طفلكِ يبكي بسبب كل شيء. ضعيه في حوض استحمام مملوء بالماء الفاتر، وأضيفي قليلًا من الرغوة. سيضفي تأثير الماء الساحر والمهدئ راحة فورية على الغرفة بأكملها وعلى جهازه العصبي.'),
  ('11b4acb5-0c50-4711-bda6-86d12a2c254b', 'موعد التدليك مع الأب 💆‍♂️', 'لقد وقفتِ طويلًا اليوم، ويؤلمكِ ظهركِ من الركض خلف طفلكِ وجمع الألعاب من الأرض. ما إن ينام، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ عماد المنزل، ولا بد للأعمدة أن ترتاح وتستعيد قوتها.'),
  ('48e0f071-5110-45a7-a007-23be77bbd305', 'زهو القميص المقلوب 👕', 'ارتدى طفلكِ قميصه بالمقلوب، ويستعرضه بفخر كأنه فتح العالم. فالطفل الذي يخرج بين الناس بملابس مقلوبة هو طفل يدافع عن قراره. لا تتدخلي ولو قليلًا، بل اغبطيه على هذه الثقة بالنفس.'),
  ('b20bcc48-1ecb-4706-9d32-0f8329c7cd46', 'اختبارات متجر البقالة 🛒', 'عند اقترابكِ من صندوق الدفع، وجدتِ في عربة التسوق 3 قطع شوكولاتة مختلفة لم تختاريها. إنه يختبر حدودكِ. أعيدي تلك الأغراض إلى أماكنها بحركة سريعة. ولتجنّب النسيان، أبقي عينيكِ دائمًا على قائمة التسوق في التطبيق.'),
  ('229bf8d4-9bef-44e1-90de-84a850188af4', 'واقع القهوة الباردة ☕', 'أن تُعدّي القهوة ثم تشربيها باردة كالثلج بعد 3 ساعات هو قانون الأمومة الرسمي. لكن افعلي شيئًا مختلفًا اليوم! دعي طفلكِ يشاهد رسومه المتحركة المفضلة، واستمتعي بقهوتكِ وهي ساخنة. أنتِ لستِ آلة، ومن حقكِ أن تستريحي.'),
  ('78ebbc01-68e9-48f1-b518-6ad7212482ec', 'الصمت الرقمي لمقياس الصوت 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي عمّ المنزل. فعّلي أداة قياس الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واشعري بصريًا كيف يستعيد عقلكِ عافيته ببطء.'),
  ('83129caa-97cc-414e-93e5-8bffa69fcbb9', 'أنا أمكِ! 👩‍👧', 'بدأت لعبة تبادل الأدوار! يعطيكِ طفلكِ أوامر مثل: تعالي إلى هنا، ادخلي إلى السرير، لا تبكي. تقبّلي تجربته القيادية هذه بكل سرور، وأدّي دور طفله بهدوء ومن دون اعتراض؛ فهذا يساعد على تنمية التعاطف.'),
  ('257a6a67-1139-417f-a422-373f16be4a85', 'مهمة الفيتامينات السرية 🥣', 'لا تستطيعين اليوم إقناعه حتى بتذوق الطعام الذي كان يحبه بالأمس. لا تدخلي في صراع مع إرادته. جرّبي وصفات وجبات خفيفة صحية تقدّم البروتينات بأشكال مختلفة وملونة وممتعة، وكوني أنتِ الفائزة.'),
  ('e8a36b6d-250c-4114-bd67-1068cf626c68', 'لعبتي مريضة 🩺', 'يمسك طفلكِ بسماعة الطبيب اللعبة، ويفحص دبدوبه بجدية ثم يضع له ضمادة لاصقة. من خلال اللعب الرمزي، يتعلم التعاطف ويفهم العالم من حوله. انضمي إلى اللعبة أنتِ أيضًا بأداء دور مريضة في المستشفى.'),
  ('fc4c9174-8969-47bc-b1ba-7be545e849f3', 'أحلام مع الحكايات الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب. افتحي الحكايات الذكية، واجعلي طفلكِ بطل القصة وغرفته المكان الذي ينبغي فتحه، لتصنعي جلسة صوتية استثنائية قبل النوم من دون أي مجهود.'),
  ('3bc4e55a-369a-4bca-8a42-e2a95a607168', 'اعترافات يوميات المزاج 📝', 'ألا يرى أحد مدى إرهاقكِ في المنزل؟ يوميات المزاج هي رفيقة أسراركِ الأكثر هدوءًا. اكتبي فيها اليوم كل التفاصيل التي دفعتكِ إلى الجنون، وانظري إلى الشاشة لتري كيف يخفّ العبء عن ذهنكِ وتتلاشى همومكِ.'),
  ('7da1ffab-3792-4ba0-b3b7-ce279478fa15', 'الطقس وتقلباته المفاجئة ⛅', 'هل الطقس في الخارج غير مستقر، فالشمس مشرقة لكن الرياح تهب أيضًا؟ دعي أداة الطقس والملابس تخبركِ فورًا بسرعة الرياح التي لا يمكنكِ تقديرها من النافذة وبالملابس المناسبة، ثم اخرجي للتنزه من دون تردد أو إضاعة الوقت عند الباب.'),
  ('be5cb204-e61d-452b-9a0e-bb977bd6249c', 'دموع بلا منطق ☀️', 'هل انخرط في البكاء قائلًا إن الشمس تنظر إلى عينيه؟ لا تبحثي عن المنطق في الغرفة. فهذا بالنسبة إليه حزن عميق حقًا، وهو يغضب لأنه لا يستطيع التحكم في العالم. فقط أكّدي شعوره بقولكِ: «سأسدل الستارة وأخفي الشمس».'),
  ('05028726-3b26-4576-b76c-968926aa3c37', 'الحنين إلى بعض العزلة 🚪', 'الضوضاء تخترق رأسكِ، وتشعرين برغبة في الصراخ بسبب كل شيء. ضعيه في مكان آمن، وادخلي الحمام وأغلقي الباب. حدّقي في الجدار لمدة 5 دقائق فقط، ولا تفعلي شيئًا. ستساعدكِ هذه الاستراحة القصيرة على استعادة استعدادكِ لمواصلة دوركِ كأم.'),
  ('3d57cc08-81bc-4a6c-804c-4488f1dababe', 'قاعدة القدمين الحافيتين 👣', 'يستمتع بالمشي حافي القدمين وبملامسة السجاد أو الحجارة الموجودة في الغرفة والبلاط البارد. إن تحفيز الأعصاب الموجودة في باطن قدميه مهم جدًا لتوازنه وتطوره العصبي، فلا تمنعيه أبدًا من المشي بلا جوارب ما دام لا يشعر بالبرد.'),
  ('903639ea-1976-4233-a451-64887050fd95', 'أصوات الأب الغريبة 🤡', 'عندما لا تعود محاولاتكِ مجدية، تنقذ أصوات الحيوانات الغريبة التي يصدرها الأب وتعابير وجهه المضحكة الموقف فورًا. خلال نوبات الانهيار المسائية، سلّميه المهمة مباشرةً، واستريحي وأنتِ تشاهدين من بعيد.'),
  ('4cb1e963-5e79-4f65-b536-3c251c29e851', 'سأطبخ اليوم 🧑‍🍳', 'هل يصرّ على وضع كرسي بجانبكِ والتدخل فيما تفعلين حين تفردين العجين؟ في الحقيقة، هو لا يريد المساعدة، بل يريد أن يكون في قلب العملية تمامًا. أعطيه قطعة صغيرة من العجين. ستعمّ الفوضى المطبخ، لكن ثقته بنفسه وإبداعه سيكبران كثيرًا.'),
  ('7f5013df-f5cb-4869-9600-c6ec01184189', 'تسجيل الكلمات الجديدة 📈', 'يبتكر للأشياء أسماءً جديدة من خياله تمامًا، لا وجود لها في أي لغة. ويصرّ على أن تستخدمي أنتِ أيضًا تلك الكلمات! افتحي متتبّع النمو واحفظي هذه الكلمات المضحكة في الأرشيف، لتقرئيها وتضحكي عليها في المستقبل.'),
  ('df048442-7c05-4ccf-850d-802c3f348e55', 'التصالح مع الظلام 🌙', 'لتساعديه على النوم سريعًا، أطفئي جميع الأضواء الإضافية وشاشات الأجهزة اللوحية في الغرفة قبل موعد النوم بساعة واحدة. يُفرَز الميلاتونين سريعًا فقط في بيئة مظلمة وخالية من الأجهزة التقنية، ما يساعد على الانتقال إلى النوم.'),
  ('18eabc56-86a4-4978-a5a6-151a3c410b3b', 'أطفئي الأنوار وأصغي إلى الصمت 🤫', 'لقد نام أخيرًا. والآن يزعجكِ حتى أخف صوت في المنزل. خفّضي الإضاءة، وأطفئي التلفاز، واستمتعي وسط الظلام بحلاوة تلك اللحظات النادرة من الصمت. هكذا يتبدد حتى تعب اليوم كله.'),
  ('90892878-829c-442e-a1ef-747f03a0affd', 'نوبات الزعل بلا سبب 😤', 'قلتِ له فقط: «تعال، الطعام جاهز»، فإذا به يعقد ذراعيه وينظر إلى الحائط غاضبًا منكِ. في هذا العمر تكون المشاعر متداخلة جدًا، لدرجة أن الأطفال قد يزعلون أحيانًا من دون أي سبب. لا تحاولي شرح أي شيء، فبعد 2 دقيقة سيهرع إلى الطعام من تلقاء نفسه.'),
  ('e85911c9-eb5a-4470-b9d6-9a1a5872b746', 'Anacan AI: مخاوف الطفل 🤖', 'هل بدأ فجأة يخاف من السيارة الحمراء التي اعتاد اللعب بها دائمًا؟ إذا كانت هذه المخاوف غير المفهومة تقلقكِ، فأغلقي منتديات الإنترنت المليئة بالتجارب الصادمة. واحصلي من Anacan AI على إجابة علمية ومطمئنة حول غرائب خيال الطفل في عمر 3.5 سنوات.'),
  ('037f6c5f-0014-4a61-89cc-f6268f8f792a', 'تأثير الهمس المنوّم 🌙', 'يستلقي في السرير ويرفع ساقيه في الهواء، ولا يريد النوم إطلاقًا. بدلًا من الصراخ، اخفضي صوتكِ فجأة وتحدثي معه همسًا فقط. عندما يركّز طفلكِ ليسمعكِ، سيهدأ دماغه تلقائيًا ويدخل في وضع الاستعداد للنوم.'),
  ('b0b14a33-4ccb-42a3-a0a7-0359199a066c', 'الاسترخاء في مجتمع Anacan 💬', 'أنتِ متعبة جدًا ولا تريدين شرح أي شيء لأي شخص. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية أمهات أخريات يعانين من إرهاق مشابه تمنحكِ شعور «لستُ وحدي»، وقد تكون أفضل علاج لكِ.'),
  ('b51e5eaf-9b52-4501-9631-0ad7c9e7aebd', 'وابل الأسئلة: لماذا؟ 🌪️', '«لماذا لا تمشي الأسماك؟»، «إلى أين ذهبت الشمس؟». منذ الصباح الباكر، يبحث عقله عن إجابات فلسفية بسرعة 100 سؤال في الساعة. حتى إن شعرتِ بالتعب، قدّمي له إجابات قصيرة. فهو يكتشف أسرار الكون من خلال نبرة صوتكِ.'),
  ('56c9f928-e47b-4ebf-bb44-4ec5cb4ae53f', 'إنه لي! - التملّك لكل شيء 🧸', 'يحتضن أي غرض عشوائي في المنزل ويصرخ: «هذا لي!»، ويرفض إعطاءه لأي شخص. إنه يكتشف حدود الملكية. لا تتهميه بالأنانية، بل وجّهي انتباهه إلى لعبة أخرى ثم استعيدي الغرض.'),
  ('77d341ac-ecee-44bc-a34c-b8046e7ebe38', 'نصيب الأم 🥗', 'فكرتِ في 3 قوائم طعام مختلفة لإشباعه، ولكن هل بقيتِ أنتِ جائعة مرة أخرى؟ من قسم خطة التغذية، اختاري غداءً غنيًا بالحديد والكالسيوم، يمنح الطاقة ويُحضَّر خلال 10 دقائق، ليس للأطفال فقط بل للأمهات أيضًا، وامنحي نفسكِ ما تستحقينه من اهتمام.'),
  ('97e76dee-bae4-4d8b-bffd-646b99d0b6bc', 'نخب الزوجين 🥂', 'بعد يوم شاق، اسكبي الشاي الساخن العادي في الأكواب. اجلسي مع زوجكِ وجهًا لوجه على الأريكة، وقولا: «لقد نجونا اليوم أيضًا من تلك الفوضى»، ثم اقرعا الكوبين معًا. فأنتما قائدا المنزل وفريق واحد في الوقت نفسه.'),
  ('0dc18b7e-e572-47af-8c7b-0d7785728f82', 'الإصرار على سكب الماء بنفسه 💧', 'يُصرّ طفلكِ على أن يسكب الماء بنفسه من الإبريق الكبير في الكوب الصغير. فينسكب الماء على الطاولة ثم على الأرض. لكن انظري إلى يديه الصغيرتين وهو يأخذ الممسحة ويحاول تنظيف المكان. إنه يتعلم تحمّل المسؤولية من خلال أخطائه، فلا تغضبي.'),
  ('4f75092c-a7ba-4a8b-9f64-4af1718f2cab', 'المحيط في حوض الاستحمام 🌊', 'لم يعد الاستحمام في حوض الاستحمام مجرد وسيلة للنظافة، بل أصبح لعبة لصنع الأمواج. دعي الماء يتناثر من حوله. فتأثير الماء الساحر سيغسل كل ما تراكم لديه طوال اليوم من عناد وطاقة سلبية، ويحمله بعيدًا مع مياه الصرف.'),
  ('d4d0d422-f5f6-490e-8c72-e88ef36a1315', 'قائمة التسوق - الأشياء المنسية 🛒', 'هل تنسين دائمًا أهم غرض عند ذهابكِ إلى المتجر؟ قائمة التسوق بانتظاركِ في التطبيق. دوّني فيها احتياجاتكِ ليشتريها شريككِ بدقة عند عودته من العمل، ولا ترهقي ذهنكِ بأعباء غير ضرورية.'),
  ('418c1711-4059-4957-81d3-edd1c0d2c899', 'هندسة معمارية في الحديقة 🏰', 'يحفر طفلكِ في صندوق الرمل بالحديقة حفرة عميقة وكأنه يبحث عن كنز، وقد تلطخت ملابسه بالطين. لكن لا تقاطعي لحظة الاكتشاف هذه. اختاري له مسبقًا ملابس مناسبة للطقس ولا بأس باتساخها، لتتمكني من الاستمتاع بمشاهدة هذا المشهد بلا توتر.'),
  ('4690cd10-6ebf-45be-8b49-fc76a078e4f1', 'صداقات غريبة مع الجمادات 🗣️', 'يتحدث بمنتهى الجدية إلى حجر في الحديقة أو كرسي في المنزل، بل وقد يوبخهما. إنه يستوعب العالم من حوله من خلال اللعب الرمزي. احرصي على تسجيل هذه السيناريوهات المميزة في متتبّع النمو.'),
  ('a43560ca-6c77-420e-beaa-23a6e7c51732', 'أنا بطل الحكاية الذكية 🪄', 'اجعلي بطل الحكاية الذكية هذا المساء يحمل اسم طفلكِ نفسه. أخبريه أن الشخصية في الحكاية رتبت غرفتها ثم نامت بهدوء، وهكذا يمكنكِ غرس القواعد لديه بطريقة غير مباشرة بدلًا من الصراخ عليه.'),
  ('9e327ded-a5c0-48ad-901c-52606eb80762', 'مذكّرات المزاج - لحظة للتنفيس 📝', 'أمسكي هاتفكِ. وبدلًا من تصفح حياة الآخرين على شبكات التواصل الاجتماعي، افتحي مذكّرات المزاج وسجّلي أطرف موقف قام به طفلكِ اليوم لتحتفظي به للمستقبل. سيساعدكِ هذا النوع من العلاج الرقمي على الاسترخاء أيضًا.'),
  ('a7cb2140-287a-4406-a2b5-5d7c82c31a2d', 'ركوب الخيل على ظهر أبي 🐴', 'لم يفرّغ طفلكِ طاقته بالكامل بعد، ولذلك يقاوم الذهاب إلى السرير. اطلبي مساعدة أبيه. فعندما يحمله على ظهره ويتظاهر بأنه حصان يعدو، تملأ الضحكات الغرفة، ويتبدد خلال ثوانٍ كل التوتر الجسدي المتراكم وتلك الطاقة التي لا تنتهي، مع بعض التعرّق.'),
  ('e21478c9-e278-43bf-8cfc-ce997f28ab6d', 'مرحلة «انظري إليّ!» 👀', 'يقفز عن الأريكة ويكرر الحركة نفسها 50 مرة بالضبط، وهو يقول في كل مرة: «أمي، انظري إليّ!». أبعدي عينيكِ عن الهاتف. فهو لا يقفز من أجل الحركة نفسها، بل من أجل بريق الاستحسان الذي يراه في عينيكِ. امنحيه 5 دقائق متواصلة من اهتمامكِ حتى يكتفي.'),
  ('4a32ef42-8519-4a15-ae15-b2e86c604165', '0 ديسيبل على مقياس الصوت 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي خيّم على المنزل. فعّلي مقياس الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واشعري بعقلكِ وهو يسترخي ببطء، وكأن هذا الصمت المرئي يداعب أعصابكِ.'),
  ('5db98ad2-4a41-4a94-8924-de68639a6a28', 'رقص حر 🎶', 'يبدأ بالرقص مع أول إيقاع يسمعه، سواء كان صوت إعلان أو بوق سيارة. انظري إلى الحياة بمرح مثله! انضمي إليه في الغرفة وارقصا بجنون لبضع دقائق، وستشعرين بكل توتركِ يتلاشى.'),
  ('8095b6da-2b93-462b-bce2-881fa1732924', 'المتابعة - فخر بالتطور 📈', 'لم يعد رضيعًا! لقد أصبح إنسانًا متكاملًا له قراراته وأسئلته الغريبة وقلبه الكبير. أنتِ تقومين بعمل رائع!'),
  ('064149bc-eacb-463c-b371-3ee4af7db167', 'خطوط الحدود على السجادة 🗺️', 'لقد سنّ قانونًا يقضي بالانتقال من الغرفة إلى المطبخ عبر الدوس على الخطوط الحمراء في السجادة فقط. هكذا تعمل المهارات الحركية الكبرى والانتباه معًا. لا تخرقي هذه القاعدة غير المنطقية، بل ارقصي معه فوق الخطوط واجعليها تمرينكِ الصباحي.'),
  ('2980ee34-de75-4617-8093-160c3c2da3a0', 'مسرح تحت الوسادة 🎪', 'دخل إلى السرير، لكنه وضع رأسه تحت الوسادة وأخذ يتحدث إلى نفسه. أظلمي الغرفة تمامًا. دعيه ينسج سيناريوهاته في ملاذه المظلم والآمن، وينتقل ببطء إلى عالم النوم، ولا تتدخلي.'),
  ('af38ac43-154c-4c60-9f01-51c84d74b264', 'اختبار المعكرونة في الجيب 🍝', 'هل وجدتِ معكرونة جافة في جيب البنطال الذي وضعتِه في الغسالة؟ قد تكون قمامة بالنسبة إليكِ، لكنها بالنسبة إليه ربما مؤونة احتياطية تحسبًا لشعوره بالجوع في الطريق. لا تلوميه، بل دوّني هذه البوادر الأولى لمهارة التخطيط كذكرى طريفة في متتبّع التطور.'),
  ('881d0866-6df6-4dec-801b-67b99df853c5', 'طلب «جفّفي الماء!» 💧', 'بدلًا من شرب الماء في الكوب، يصرخ قائلًا: «إنه مبلل جدًا، جفّفيه!». أهلًا بكِ في عبثية سن 3.5 سنوات. محاولة الشرح ستستنزف طاقتكِ. قولي له: «حسنًا، سأحضر لك ماءً جافًا آخر»، ثم قدّمي له الماء نفسه في كوب بلون مختلف.'),
  ('d2f34bfd-32c7-43f7-89fd-d8226236a390', 'رشوة الأب السرية 🤫', 'لا يريد تنظيف أسنانه. يقترب منه والده سرًا ويقول: «إذا نظّفت أسنانك، فسأريك الحجر السحري الموجود في جيبي». أحيانًا لا بد من كسر قواعد الأمومة بهذه الحيل الأبوية المبتكرة والماكرة، لكنها فعّالة على الفور.'),
  ('f968f309-08cf-46ae-901b-44ed8420ced0', 'إطلالة من الشرفة على المجتمع 👀', 'يخرج إلى الشرفة ويلوح بيده صارخًا لكل من يمر في الطريق، ثم يحزن عندما لا يرد عليه أحد. حاجته إلى التواصل الاجتماعي في ذروتها. لا تسحبيه إلى الداخل، بل قولي له: «إنهم بعيدون جدًا، وربما لم يسمعوك»، وحافظي على تعاطفه من دون جرح مشاعره.'),
  ('01eb4758-ff80-4ee6-b2d8-884207fd7862', 'جلسة قراءة صامتة للكتاب 📖', 'هذا المساء، لا يتحدث أحد. افتحي الحكايات الذكية، وبدلًا من قراءة النص بصوت عالٍ، تأمّلا الصور بصمت على أنغام أصوات الطبيعة الهادئة الصادرة من الجهاز. ستُتعب الصور ذاكرته البصرية وتقوده تلقائيًا إلى النوم.'),
  ('fae36977-58eb-48b1-8551-438307ad854b', 'الطريقة الخاطئة لتقديم البيضة 🍳', 'تحدث نوبة غضب عارمة لأنكِ قطعتِ البيضة المسلوقة إلى نصفين. «كنت أريدها كاملة!» شكل الطعام وطريقة تقديمه من أكثر الأمور حساسية لديهم. تصفّحي الوصفات الصحية لتتعلمي كيفية تقديم الأطعمة بالشكل المناسب وتقطيعها بطرق مرحة.'),
  ('fed4ec8b-badd-4ae2-b8cd-74446e67eee7', 'محقق الطبيعة 🔍', 'جلس في الحديقة بلا حراك لمدة 20 دقيقة لمجرد مراقبة عش النمل. لا تستعجليه. إذا كنتِ قد استخدمتِ مساعد الطقس والملابس وألبستِه مسبقًا ملابس مناسبة للطقس وسميكة من الأسفل، فدعي عالم الأحياء الصغير هذا يكتشف العالم.'),
  ('0601b05e-a2e4-4730-b08b-f661e0e89b2a', 'مختبر صغير في حوض الاستحمام 🛀', 'يضيف إلى الماء أنواعًا مختلفة الألوان من الصابون ليحضّر جرعة سحرية. نعم، سيعمّ الحمامَ البلل والفوضى. لكنه يتعلم عن المذيبات وامتزاج المواد. هذا الاستكشاف العلمي أجمل وسيلة تخلّصه من إرهاق المساء وتهيّئه لنوم هادئ.'),
  ('15d2ba80-4fad-4f86-8e70-6261ae666ebc', 'عزلة اجتماعية داخل الخزانة 🚪', 'ساد الصمت فجأة وسط المنزل. ثم وجدتِه يلعب وحده في الظلام داخل خزانة الملابس. هذا ليس اكتئابًا، بل مجرد لحظة لإعادة ضبط مشاعره. أغلقي الباب برفق وامنحيه رفاهية الاستمتاع بهذه المساحة الخاصة.'),
  ('869bedae-ce51-4c50-8799-4b322d523e09', 'ثورة رفض اللمس 🔋', 'لقد استنزفكِ جسديًا طفلكِ الذي يتسلق عليكِ ويشد شعركِ طوال اليوم. ضعيه فورًا في مكان آمن وانتقلي إلى غرفة أخرى. اكتبي في مفكرة مزاجكِ «جسدي لم يعد ملكي»، لتخففي العبء النفسي لمتلازمة الإنهاك من كثرة اللمس.'),
  ('aa506c93-122a-43f1-8742-2605113c516c', 'أنا من وجدتُ هذا في المتجر 🛒', 'عندما تقتربين من صندوق الدفع، تظهر في العربة عبوة بسكويت لم تضعيها أنتِ. لقد نفّذ طفلكِ عملية استكشاف بصمت. افتحي قائمة التسوق وقولي: انظر، هذا غير موجود في قائمتنا، سنكتبه في المرة القادمة، وبذلك اجعلي القائمة الرقمية هي صاحبة القرار.'),
  ('0b6916b1-4773-417f-aed4-71c7ff7f85e9', 'متعة الشاي معًا 🥂', 'بعد يوم شاق، اسكبي في الكوبين شايًا ساخنًا عاديًا. اجلسي مع شريككِ وجهًا لوجه على الأريكة، وتبادلا نخب الشاي قائلين: لقد نجونا من فوضى اليوم أيضًا، نحن فريق رائع. أنتما الأساس المتين لهذا المنزل.'),
  ('8bce8353-bf73-417b-8a15-56b41142ba18', 'عملية الخضراوات السرية 🥦', 'يجد حبة الأرز أو قطعة الجزر الوحيدة في الحساء ويقول: لن آكل هذا. ادخلي إلى خطة التغذية، وتعلّمي كيف تحوّلين البروتينات والخضراوات إلى كعكات ملوّنة لتتحايلي على هذا الطاهي الصغير العنيد.'),
  ('ef39807d-1235-46a3-9ca8-a0f70bb2fa23', 'أولمبياد تسلّق الأثاث 🧗‍♂️', 'يتسلّق حافة الأريكة متجهًا نحو النافذة. المنزل مليء بالمخاطر بالنسبة إليكِ، لكنه صالة رياضية بالنسبة إليه. بدلًا من إثارة الذعر بقولكِ: انتبه، ستسقط! وجّهي حاجته إلى الحركة بشكل صحيح بقولكِ: ضع يدك هنا.'),
  ('000abcf3-b4c9-4928-8d58-c7a8f138f07f', 'الذكاء الاصطناعي والطمأنينة 🤖', 'هل دفعكِ التلعثم المفاجئ لدى طفلكِ أو نوبات غضبه إلى البحث على الإنترنت عن أمراض خطيرة؟ توقفي! اسألي Anacan AI عمّا إذا كان ذلك مرتبطًا بطفرة النمو في عمر 3 سنوات، واحصلي على إجابة مطمئنة ومعتمدة من أطباء الأطفال.'),
  ('ac974535-4db4-4ecb-aa90-d75a7dabe40a', 'المؤثرات الصوتية في الغرفة 🪄', 'شغّلي الحكايات الذكية. أثناء قراءة القصة، اصنعي مسرحًا صوتيًا في الغرفة بمجرد تقليد صرير الباب وصوت الرياح والهمسات. ستجذب هذه الموجات الصوتية غير المألوفة انتباهه فورًا إلى عالم الحكاية، ومنه إلى نوم عميق.'),
  ('e9945ad4-3802-48f8-b0bf-d94527c3999b', 'الهروب من الظل 👻', 'بينما تمشيان في الشارع، يخاف فجأة من ظلّه ويختبئ خلفكِ. لا تبحثي عن المنطق؛ هكذا يعمل خيال الطفل في عمر 3.5 سنوات. قولي له: هيا نقفز فوق الظل، وحوّلي ما يخيفه فورًا إلى لعبة حركية.'),
  ('06d21315-e90d-4d7c-a84d-b0f3acd86dc9', 'تدليك كتفي الأب 💆‍♂️', 'لقد وقفتِ طويلًا اليوم، ويكاد ظهركِ ينكسر من الركض خلف طفلكِ وجمع الألعاب عن الأرض. ما إن ينام، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. أنتِ محرّك المنزل، ولا بد للمحرّك من الراحة واستعادة طاقته.'),
  ('28383f04-88e3-44f0-b462-99283a8b08f3', 'صرخة الجسد 🩸', 'لا تستسلمي للانفعال والتعب من دون سبب. راجعي متتبع الدورة الشهرية، فجسدكِ يرسل إليكِ إشارات. وبدلًا من لوم نفسكِ، استرخي مع وجبة خفيفة غنية بالمغنيسيوم من قسم الوصفات الصحية.'),
  ('4c7f9f66-bdd5-4db6-8e78-8af325982d85', 'فلسفة الصباح الباكر 🤔', 'لماذا لا تسقط الطيور؟ لماذا أصبحت الشجرة خضراء؟ لقد بدأ المؤتمر العلمي منذ الصباح الباكر. إذا سئمتِ تقديم تفسيرات دقيقة، فأعيدي إليه السؤال قائلةً: برأيك، لماذا؟ ثم استمتعي بإجاباته الخيالية المدهشة.'),
  ('ab1d1514-de05-4637-8009-2407cc320f46', 'اتفاق مؤقت النوم ⏱️', 'حين يحين موعد النوم، يشعر فجأة بالعطش أو يرغب في الذهاب إلى الحمام أو يبدأ بتوديع الجدار. اضبطي المؤقت، وطبّقي قاعدة أن الجميع يطفئون الأنوار عندما يرن الجرس. وهكذا يمكنكِ بصبر وضع حد لهذا الوداع الذي لا ينتهي ولهذه المناورات البارعة.'),
  ('310065f1-7769-41dc-b05f-15aba7ca4982', 'نوبة «أريده» في المتجر 🛒', 'هل يصرخ طلبًا للحلوى أمام صندوق الدفع؟ لا تكترثي إطلاقًا لنظرات الآخرين التي توحي بأنه طفل سيئ. انظري في عينيه بهدوء واشرحي له القاعدة وتمسكي بموقفكِ. إن لم تكن في قائمتكِ، فلن تشتريها.'),
  ('d64359e3-bdb5-49c3-9bc4-e2e55cdc8d1e', 'لعبة «من أنتِ؟» 🎭', 'ينظر إليكِ بملامح جادة جدًا ويقول: من أنتِ؟ أين أمي؟ إنه يلعب معكِ لعبة تمثيل! واصلي هذا العرض الرائع بتغيير نبرة صوتكِ والقول: أنا الجارة، وستأتي أمك حالًا.'),
  ('f9b49a33-7a6d-4463-b26d-b51d28283257', '«أحبكِ» المفاجئة 💖', 'بينما يلعب في وسط الغرفة، ينظر إليكِ فجأة ثم يركض نحوكِ ويعانقكِ. إنها لحظة تستحق كل الليالي التي قضيتِها بلا نوم وكل ذلك التعب! استمتعي بذلك السلام العميق والفريد الذي تجلبه هذه اللحظة، وستنسين كل تلك الفوضى على الفور.'),
  ('3674bd2e-5c13-4e77-8d3d-732d072d4226', 'ليس قمامة، بل فن 🎨', 'لقد صنع في وسط الغرفة عملًا فنيًا ضخمًا من قصاصات الورق الصغيرة والخيوط المقطعة، ولا يسمح لكِ برميه. ضعي هوس النظافة جانبًا. احترمي الفوضى التي صنعها، فالتنظيف يمكن أن ينتظر إلى الغد.'),
  ('a910e33f-005d-4ed1-a228-647503e47993', 'سكينة الصمت 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي عمّ المنزل. فعّلي مقياس الصوت، وانظري إلى قراءة 0-10 ديسيبل على الشاشة، واشعري كيف يسترخي ذهنكِ تدريجيًا وكيف يداعبكِ هذا الصمت المرئي.'),
  ('f14df610-5f47-47f4-b085-7728f03a38c4', 'أكملي الجمل الناقصة 🗣️', 'عندما ينسى كلمة، يشير بيده ويعقد حاجبيه منتظرًا منكِ أن تخمّنيها. حصيلته اللغوية تتسع، لكن دماغه يعمل أسرع من لسانه فحسب. أكملي جملته بصبر، وراقبي على وجهه تلك الراحة التي تقول: نعم، هذا بالضبط ما كنت أقصده.'),
  ('489e6dea-7ed3-426f-a373-fa7b11cafdff', 'اللعب على ظهر أبيه 🐴', 'لم يتمكن من تفريغ طاقته بالكامل، ويرفض الذهاب إلى السرير. اطلبي مساعدة أبيه. عندما يحمله على ظهره ويتظاهر بأنه حصان يعدو، تملأ الضحكات الغرفة، ويختفي كل التوتر الجسدي المتراكم وتلك الطاقة التي لا تنضب خلال ثوانٍ مع بعض التعرّق.'),
  ('654f0e0a-2920-4fe5-8cf5-be2fa96fa926', 'لوح طاقة للأم 🥑', 'حضّرتِ له قائمة طعام بأربع طرق مختلفة كي يأكل، ولكن ماذا أكلتِ أنتِ؟ اختاري من الوصفات الصحية وجبة خفيفة مميزة وغنية بالكالسيوم لا يستغرق إعدادها سوى ٥ دقائق، واستمتعي بمذاقها حتى لو تناولتِها واقفة؛ فأنتِ محرّك هذا المنزل وتحتاجين إلى شحن طاقتكِ.'),
  ('f72407e2-133f-448d-813f-15315e00fa30', 'الاستيقاظ كقطة 🐾', 'هذا الصباح، هو ليس إنسانًا؛ بل يمشي على أربع، ويتمسّح بساقكِ، ولا يتواصل إلا بالمواء. إنها واحدة من ألطف لحظات الخيال. بدلًا من وضع القواعد، قدّمي له أنتِ أيضًا وعاءً خياليًا من الحليب واستمتعي بهذه اللعبة.'),
  ('784cb32f-466a-4d9b-9df3-23fb3c0de764', 'تنويم بالموسيقى 🎶', 'بدأت نوبات الغضب والبكاء التي تهبّ بلا سبب في أواخر النهار. أطفئي التلفاز، وخفّفي الإضاءة، وشغّلي موسيقى كلاسيكية هادئة جدًا في الغرفة. ستغيّر ترددات الموسيقى العميقة الأجواء كالسحر وتملأ الغرفة بالسكينة.'),
  ('791a6f93-24a4-4445-acfb-0bee156d7b20', 'فطور لا يُقتسم 🍳', 'يرفض تمامًا أن يعطيكِ شيئًا مما في طبقه، لكنه يأتي إليكِ ويصرّ على تناول البيض من طبقكِ. يثق الأطفال دائمًا ثقة تامة باختيارات والديهم. لا تقاومي؛ ناوليه لقمتكِ بمحبة وابتسمي.'),
  ('840bd918-95f6-4c59-bcb3-4b0f4eaea73b', 'الحديث مع الأشياء الجامدة 🗣️', 'يتحدث بجدية تامة إلى حجر في الحديقة أو كرسي في المنزل، بل ويوبّخهما. إنه يستوعب العالم من خلال اللعب الرمزي. احرصي على تسجيل هذه السيناريوهات المميزة في متتبّع نموه، فهي علامة على إبداع كبير!'),
  ('11214951-0661-40fc-a2c7-d7aedff5cf90', 'بوح في يوميات المزاج 📝', 'خذي هاتفكِ. بدلًا من تصفّح الحياة المثالية للآخرين على وسائل التواصل الاجتماعي، افتحي يوميات المزاج ودوّني للمستقبل أطرف ما فعله اليوم، واللحظة التي أضحكتكِ أكثر من غيرها. الكتابة هناك أنقى أشكال العلاج النفسي.'),
  ('18c831a2-2a8d-41b4-aec0-3fc3423e4549', 'السلام الداخلي مع مقياس الصوت 🤫', 'لقد نام أخيرًا. لكن الطنين في أذنيكِ لا يتوقف. افتحي مقياس الصوت في التطبيق. وراقبي عبارة 0 ديسيبل على الشاشة، واشعري كيف يتسلل هدوء الغرفة إلى ذهنكِ ويمنحكِ الراحة والتعافي.'),
  ('64255b01-33d4-405e-b645-f0ff22d8defe', 'لص الهاتف 📱', 'بينما كنتِ تصبّين لنفسكِ الشاي، لاحظتِ أن هاتفكِ اختفى، ثم وجدتِه خلف الأريكة يقول «ألو» مثلكِ. إن طفلكِ يستكشف عاداتكِ الرقمية. وعندما تستعيدين الجهاز، حوّلي الأمر إلى لعبة وقولي: «يبدو أن هاتفي يريد التحدث معك أيضًا».'),
  ('d0533c80-d46b-4d9f-9654-8ce50e72523b', 'سياسة «ارتدِ ملابسك بنفسك!» 👖', 'يرفع قدميه في الهواء وكأنه يقول: «أنا رضيع، ألبسيني أنتِ». يتأرجح الأطفال بين الاستقلال والاعتماد على الآخرين. لا تجبريه على ارتداء ملابسه. ضعي القطعة بجانبه واستخدمي حيلة مرحة بقولكِ: «هذا البنطال الخارق ينتظر صاحبه».'),
  ('5d82c548-2228-430b-916c-6c21c900e5fe', 'القوة الغامضة للهمس 🌙', 'يختلق الأعذار للهروب من السرير. اخفضي صوتكِ تمامًا ولا تتحدثي إلا همسًا. سيضطر إلى تركيز انتباهه جسديًا ليفهمكِ، وسيساعده هذا التركيز على تهدئة دماغه والاستسلام للنوم.'),
  ('e401c834-583c-49ec-8d04-289b6b62d99b', 'المواساة في مجتمع Anacan 💬', 'هل يخنقكِ شعور «لن أكون مثالية أبدًا»؟ تخلّصي من وهم أمهات Instagram المثاليات. ادخلي إلى مجتمع Anacan واقرئي الاعترافات الصادقة لأمهات تعمّ الفوضى منازلهن ويرسم أطفالهن على الجدران، ثم قولي لنفسكِ: «أنا طبيعية تمامًا».'),
  ('fb0d15e4-b6e4-45a0-af9f-62f33e8c81a6', 'منطق الديناصورات 🦖', 'في الصباح لا يجيب عن أي سؤال، بل يزأر فقط. إنه اليوم ديناصور T-Rex. تماشي مع هذه الشخصية التي ابتكرها واسأليه: «هل تأكل ديناصورات T-Rex العصيدة؟»، لتُكملي طقوس الصباح من دون دموع.'),
  ('5a7d778f-6e03-4003-a60c-0214c0dc5a0b', 'أبطال أبي الخياليون 🦸‍♂️', 'انسوا حكايات الكتب هذا المساء. ليرْوِ الأب قصة خيالية رائعة يكون الطفل نفسه بطلها. وستجعله عبارات مثل: «ثم استلّ سيفه... ونظّف أسنانه!» ينفجر ضاحكًا ويستعد للنوم.'),
  ('732719f9-46cf-4097-a068-781df2eeaf00', 'انتقاد رسمه بنفسه 🖍️', 'يريكِ خربشاته السوداء ويقول: «هذه أنتِ، لكنها لم تكن جيدة»، ثم يمزقها ويرميها. لقد بدأت تتكوّن لديه القدرة على نقد نفسه! لا تقلّلي من شأن مشاعره، بل ادعمي تطوره بقولكِ: «ما رأيك في تجربة اللون الأحمر أيضًا في الرسم القادم؟».'),
  ('3d278e8d-5fc9-46fa-ad40-bcef90b99e90', 'قال لكِ: أنتِ أم سيئة! 💔', 'قال هذه العبارة لأنكِ لم تشتري له السيارة التي أرادها، فشعرتِ بوخزة في قلبكِ. لكن تذكّري أنه لا يزال غير قادر على التعبير عن مشاعره بطريقة صحيحة؛ فما يريد قوله في الحقيقة هو: لقد شعرت بخيبة أمل. فقط عانقيه وتقبّلي شعوره.'),
  ('d54e4e25-89e6-430d-b9c4-307312ee2246', 'مفهومه الخاص للموضة 👗', 'يريد الذهاب إلى الحديقة مرتديًا صندلًا صيفيًا فوق جوارب شتوية. يصرّ على ذلك ويرفض خلعه. انسي معايير المجتمع، ودعيه يقضي يومه بهذه الإطلالة المختلفة والمضحكة حتى لا تحبطي إبداعه؛ فهو يتعلّم معنى الحرية.'),
  ('9fab66ef-18f3-4cdb-8e01-0a4f9485cffe', 'المنافس في المرآة 🪞', 'يقف أمام المرآة ويقطّب حاجبيه، ويجرّب تعابير غاضبة وغريبة. إنه يختبر كيف تبدو المشاعر على وجهه. راقبي في هدوء واستمتاع تدريبات هذا الممثل المسرحي الصغير.'),
  ('b8be3052-4ca5-4460-8506-d2c5926555b2', 'وقت عزلة للأم 🚪', 'تشعرين أن الضجيج يخترق رأسكِ، وترغبين في الصراخ بسبب كل شيء. ضعيه في مكان آمن، وادخلي الحمّام وأغلقي الباب. افتحي يوميات المزاج واكتبي فيها بحرية كل ما تشعرين به من إنهاك. ستساعدكِ هذه الجلسة العلاجية القصيرة على استعادة توازنكِ.'),
  ('cc703a6d-3143-4136-a5f9-9d4bb2fc1aa6', 'التصالح مع الظلام 🐰', 'يهرب من سريره متذرّعًا بخوفه من الظلام. أطفئي جميع أضواء الغرفة، وشغّلي مصباحًا يدويًا، واصنعي بيديكِ على الحائط ظلال طيور وكلاب. سيتحوّل الظلام الذي يخيفه إلى مسرح ممتع خلال ثوانٍ.'),
  ('217250d8-e2a0-42ca-ac61-232ced171632', 'خطة استطلاع الطقس ⛅', 'الشمس ساطعة في الخارج، لكن الرياح تهب أيضًا. لا تنخدعي بما ترينه من النافذة. دعي أداة الطقس والملابس تخبركِ فورًا بدرجة الحرارة المحسوسة غير الظاهرة وبالملابس المناسبة التي يمكن ارتداؤها في طبقات، كي تخرجي في نزهة مريحة وصحية من دون تردّد عند الباب أو إضاعة للوقت.'),
  ('4a193a83-4450-45ef-8b03-b9487c79d984', 'هذا ليس خطئي! 🤷‍♂️', 'سكب الماء على الأرض عمدًا، ثم ألقى اللوم على لعبته قائلًا: هي دفعتني. هذا ليس كذبًا، بل آلية دفاع لدى دماغ الطفل. لا تدخلي معه في جدال، بل قولي: تعال لنعلّم هذه اللعبة أيضًا كيف ننظّف المكان، وحوّلي الموقف بذكاء.'),
  ('c170e0aa-73e3-4e36-8c66-e8887556d5ab', 'عاصفة المحيط في حوض الاستحمام 🌊', 'لم يعد الاستحمام في الحوض مجرّد وسيلة للنظافة، بل أصبح لعبة لإحداث تسونامي صغير. دعي الماء يتناثر في كل مكان؛ فتأثير الماء الساحر القادر على امتصاص الطاقة سيغسل كل ما تراكم لديه طوال اليوم من عناد وطاقة سلبية ويحمله بعيدًا مع مياه الصرف.'),
  ('1219c5e2-02af-4f74-a734-ea08c3018209', 'ممنوع أن تغنّي! 🛑', 'بدأتِ تدندنين مع أغنية الأطفال التي تُعزف في الخلفية، فصرخ فورًا: لا تغنّي! فهو المغني المنفرد الوحيد في الغرفة، ومحاولاتكِ الغنائية تزاحمه على مسرحه. لا تنزعجي، واتركي المسرح لهذا الأناني الصغير.'),
  ('9dfdb936-66eb-43a1-b7d1-6fccd5198f88', 'أنا في الحكاية الذكية 🪄', 'هذا المساء، سمّي بطل الحكاية الذكية باسم طفلكِ مباشرةً. أخبريه أن الشخصية في الحكاية رتّبت غرفتها أيضًا ثم نامت بهدوء، وهكذا اغرسي فيه القواعد بطريقة غير مباشرة بدلًا من الصراخ عليه.'),
  ('28d0f55b-6b15-4788-8b02-4740d679f342', 'هل يختلّ الروتين؟ ⏱️', 'هل يستغرق النوم مساءً وقتًا طويلًا؟ راجعي مخطط مؤقت النوم. ربما حان الوقت فعلًا لإلغاء القيلولة النهارية تمامًا وتقديم موعد النوم مساءً.'),
  ('2c32efa0-ce45-4ee9-9fb5-78b505fc81dc', 'ناقد الرسوم المتحركة 📺', 'يروي لكِ أحداث فيلم الرسوم المتحركة الذي شاهده بلغته وقواعده الخاصة، ويشرح لكِ بجدية مَن ذهب وإلى أين. استمعي إليه باهتمام وكأنكِ مندهشة. دعي خياله ينطلق ويشعر بأنه الأذكى في العالم.'),
  ('bc152191-c6d9-4a5e-b03a-d59aaa89994d', 'دعم المجتمع الصامت 💬', 'أنتِ متعبة جدًا ولا ترغبين في شرح أي شيء لأحد أو حتى الفضفضة. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية كيف تتعامل الأمهات الأخريات مع نوبات الغضب العبثية نفسها هي أقوى مواساة صامتة.'),
  ('487012f7-5a3f-49e2-9f9d-2533c14f18c9', 'الهروب من السرير 🏃‍♂️', 'أعطيني ماءً، ابحثي عن لعبتي... لا تنتهي أعذار الطفل ذي الثلاث سنوات لتجنّب النوم. شغّلي مؤقت النوم، وحافظي على الحدود بحزم، وهدّئي الغرفة باستخدام الضوضاء البيضاء.'),
  ('543ac832-5997-4074-94fa-e27c0915dc20', 'حكواتي صغير 🗣️', 'هل بدأ يجمع الكلمات ويؤلف حكايات خيالية وسيناريوهات مدهشة؟ لا تفوّتي هذه الطفرة اللغوية الرائعة؛ سجّلي صوته فورًا وخلّدي هذه اللحظة في ألبوم الطفل.'),
  ('75d14b5e-1909-445c-9146-d6cc02f1b594', 'درع الكالسيوم 🦴', 'الكالسيوم ضروري للعظام التي تنمو بسرعة. ألا يشرب الحليب؟ استخدمي أداة متابعة التغذية واحسبي اليوم كمية الجبن أو الزبادي أو البروكلي التي تناولها.'),
  ('5be6af82-89c1-4468-a900-9f899a3717f7', 'مرحلة «إنه لي!» 🧸', 'هل يرفض إعطاء لعبته لأي شخص؟ هذه ليست أنانية، بل مرحلة طبيعية من النمو. اقرئي في المدونات عن مفهوم اللعب بالتناوب بدلًا من المشاركة وطبّقيه.'),
  ('6c5b3273-7cbb-4026-9d69-cd0596d59019', 'ثورة الصباح 🛑', 'هل يرفض اليوم باشمئزاز طعامًا كان يحبه كثيرًا بالأمس؟ هذا ليس فقدانًا للشهية، بل مجرد محاولة لفرض السيطرة. تحدّثي مع Anacan AI عن كيفية الحفاظ على هدوئكِ أثناء نوبات الغضب، وخذي نفسًا عميقًا، ولا تحوّلي مائدة الطعام إلى ساحة معركة أبدًا.'),
  ('e85b3357-f072-4120-8d16-ffdc101f5e86', 'وقت اللعب مع الأب 👨‍👧', 'الأمومة ليست مناوبة متواصلة 24/7. حان الوقت ليتولى شريككِ دوره! دعي طفلكِ يفرّغ اليوم طاقته التي لا تنضب مع أبيه في الحديقة، واستمتعي أنتِ في المنزل بالهدوء التام.'),
  ('4b47f634-fca5-4f0e-a391-d61c2ad9b71e', 'استراحة الأم ☕', 'من المتعب التحدث مع طفلكِ بلا توقف والإجابة عن أسئلته. ابحثي في الأماكن الصديقة للأمهات عن مقهى يضم ركنًا للأطفال، واحتسي قهوتكِ الساخنة، وتحدّثي مع أمهات أخريات لتلتقطي أنفاسكِ قليلًا.'),
  ('4e86cfa1-9302-4174-a4b5-457a860c75dd', 'دور الأب في حكاية المساء 📚', 'طقوس النوم هذا المساء من مسؤولية الأب بالكامل. دعيه يقرأ الحكاية، واستمتعي أنتِ خلف الباب بالهدوء التام.'),
  ('ffd19c6f-d0e4-4ed0-b594-f10907dbe2d7', 'سأفعلها بنفسي! 🛑', 'هل يصرّ على فعل كل شيء بنفسه ويجعل ارتداء الملابس يستغرق 3 أضعاف الوقت؟ لا تنظري إلى الفوضى، بل إلى ثقته بنفسه وهي تنمو. عندما ينفد صبركِ، اقرئي في المدونات عن حل الأزمات باللعب وخذي نفسًا عميقًا.'),
  ('086dfc4e-9fb2-412e-ade9-cb121424e290', 'شاي ساخن وهدوء 🍵', 'توقّف المؤقت ونام طفلكِ. انسي الأعمال المنزلية، فكل شيء يمكنه الانتظار. حضّري مشروبًا مميزًا من الوصفات الصحية، واستمتعي بقضاء بعض الوقت مع نفسكِ.'),
  ('577db9f8-8f80-4ad0-9e5c-4fd106adca75', 'لعبة الغميضة في الصباح الباكر 🙈', 'أنتِ متأخرة عن العمل أو الحضانة، بينما يختبئ طفلكِ خلف الستارة ويقول: «اعثري عليّ!». حتى إن كنتِ على وشك فقدان أعصابكِ، فإن الصراخ سيطيل الأمر أكثر. شاركيه اللعبة لمدة 2 دقيقة قائلةً: «أين طفلي الجميل يا ترى؟»، ثم اعثري عليه وأخرجيه من مخبئه.'),
  ('61996b98-7da4-41e9-be9f-afe630090cfe', 'فرز الطعام حسب لونه 🍅', 'يفرز طفلكِ الطعام في الطبق حسب ألوانه وأشكاله، ويدفع الأطعمة الخضراء جانبًا. ادخلي إلى خطة التغذية، واكتشفي كيف تحوّلين تلك الخضراوات إلى هريس غير ملحوظ وتخفينها في صلصات شهية، لتفوزي بهذه اللعبة بذكاء ومن دون أن يدري.'),
  ('01916001-64ad-41ab-8fea-1c1101a3ae1c', 'الحاجة إلى الهدوء 🤫', 'لقد نام أخيرًا! لا تكادين تصدقين الهدوء الذي عمّ المنزل. فعّلي مقياس الصوت، وانظري إلى الرقم 0-10 ديسيبل على الشاشة، واشعري كيف يسترخي ذهنكِ تدريجيًا وكأن هذا الصمت المرئي يداعب حواسكِ.'),
  ('95ce868b-b982-4c4e-baa7-7ca7cd3520b4', 'كنوز تخرج من الجيوب 🪨', 'هل وجدتِ في جيب سرواله أثناء غسله حجرين وورقة شجر يابسة ونصف عود؟ قد تكون هذه الأشياء قمامة بالنسبة إليكِ، لكنها مجموعته الثمينة التي جمعها أثناء استكشاف عالمه. بدلًا من رميها، ضعيها في صندوق كنوز صغير.'),
  ('97aa3207-a7a2-42a1-9e74-01d2388db3b1', 'مهمة إغلاق الأبواب 🚪', 'يستمتع طفلكِ كثيرًا بإغلاق أبواب جميع غرف المنزل من الداخل وترككِ في الخارج. يبدو أن مفهوم المساحة الشخصية لديه يشهد ثورة! اتخذي الاحتياطات اللازمة لحماية أصابعه من الانحشار، لكن لا تفسدي تمامًا لعبته في إعلان منطقته الخاصة.'),
  ('2f583ff5-e2c4-4fbb-acdc-470ccf241970', 'فنّ ورق المرحاض 🧻', 'بضع دقائق من الصمت... ثم تدخلين الغرفة لتجدي أن لفافة ورق المرحاض بأكملها قد فُكّت وانتشرت في أرجاء المنزل! بدلًا من الغضب، اجمعي الأوراق واصنعا معًا رجل ثلج أو كرة. تغلّبي على الفوضى بالإبداع، لا بالصراخ.'),
  ('6ae9e7b9-b61e-4945-82bd-3ceb19652949', 'اكتشاف الغسالة 🧺', 'يجلس طفلكِ أمام الغسالة ويركّز على الملابس وهي تدور وكأنه يشاهد فيلمًا كرتونيًا. إنه ترفيه مجاني تمامًا ومهدئ للذهن. لا تقاطعيه، بل اغتنمي الفرصة لتستريحي أنتِ أيضًا؛ فقد أخذت الفوضى استراحة قصيرة.'),
  ('c8193b18-f83a-473a-bda3-5d573d734271', 'همسات الحب في أذنه 💖', 'لقد دفعكِ إلى الجنون طوال اليوم وعاند في كل شيء. لكنه الآن ينام في سريره ببراءة شديدة... استلقي بجانبه واهمسي في أذنه بمدى حبكِ له وبالأشياء الجميلة التي فعلها اليوم. يشعر الأطفال بصوت أمهم المفعم بالحب حتى وهم نائمون.'),
  ('8f4abc30-5451-459c-a1af-55ec249af8b0', 'صدمة «أنتِ لا تسمعينني!» 😠', 'بينما تنظرين إلى هاتفكِ أو تحرّكين الطعام، يأتي طفلكِ ويدير وجهكِ نحوه قائلًا: انظري إليّ! وهو محق. فهو لا يريد مجرد وجودكِ الجسدي، بل يريد اهتمامكِ الكامل من دون تشتت. توقفي عما تفعلينه واستمعي إليه مع الحفاظ على تواصل بصري كامل لمدة 3 دقائق فقط.'),
  ('86c98bc5-4f00-463f-9722-124e19e389a1', 'لا بد من الانطلاق إلى الطبيعة ⛅', 'بين أربعة جدران، تتحول طاقته إلى عدوانية، وتبدأ كل جملة يقولها بكلمة «لا». مهما كان الطقس أو نوع الملابس، جهّزيه بما يناسب واصطحبيه إلى الخارج. فملامسة التراب ستساعد جهازه العصبي على استعادة توازنه فورًا.'),
  ('04ffb755-8100-4999-9284-739b81b180be', 'إنه لي! - الرغبة في امتلاك كل شيء 🧸', 'يحتضن أي غرض عشوائي في المنزل ويصرخ: «هذا لي!» ولا يسمح لأحد بأخذه. إنه يكتشف حدود الملكية. لا تتهميه بالأنانية، بل حوّلي انتباهه إلى لعبة أخرى ثم استعيدي الغرض.'),
  ('1f9e9c23-d051-49a3-8538-a3275546e6a3', 'ليس قمامة، بل فن 🎨', 'لقد صنع في وسط الغرفة عملًا فنيًا كبيرًا من قصاصات الورق الصغيرة والخيوط المقطوعة، ولا يسمح لكِ بالتخلص منه. ضعي هوس النظافة جانبًا. احترمي الفوضى التي ابتكرها، فالتنظيف يمكن أن ينتظر حتى الغد.'),
  ('55f7cd1c-adbb-4e6a-bcc0-5847c157d42a', 'ركوب الخيل على ظهر الأب 🐴', 'لم يتمكن من تفريغ طاقته بالكامل، ويرفض الذهاب إلى السرير. استعيني بالأب. عندما يحمله على ظهره ويتظاهر بأنه حصان، تملأ الضحكات الغرفة، ويتبدد خلال ثوانٍ، وسط التعرق، كل التوتر الجسدي المتراكم وتلك الطاقة التي لا تنتهي.'),
  ('11adcff5-957f-4e30-8ecc-96f09d1482fe', 'عالم الحكايات 🪄', 'ضعي الحكايات الكلاسيكية جانبًا. افتحي الحكايات الذكية. أنشئي حكاية خاصة.'),
  ('4418649d-d556-4a03-af91-b1d0242b6324', 'دعم المجتمع 💬', 'أنتِ مرهقة جدًا ولا ترغبين في شرح أي شيء لأحد أو الفضفضة. ادخلي إلى مجتمع Anacan واكتفي بالقراءة. إن رؤية كيفية تعامل الأمهات الأخريات مع نوبات الانفعال العبثية نفسها هي أقوى مواساة صامتة.'),
  ('6e6ecb59-b07b-44ae-b10f-31d088fcccf0', 'ديكتاتور الصباح يتولى المهمة 👑', '«لا تجلسي هناك، فدُبّي الصغير سيجلس هناك!» إنه يتحكم في المائدة بأكملها أثناء الإفطار. من دون كسر إرادته بقسوة، حافظي على التوازن والسلام في الغرفة بقولكِ: «حسنًا، ليجلس دُبّك هناك، وسأجلس أنا هنا».'),
  ('1b1ca975-b7c1-4e57-9e31-3f5e83031e0f', 'تمرد القيلولة 🥱', 'لا يريد الذهاب إلى السرير ويبكي؟ لا تجبريه. خفّفي الإضاءة في الغرفة وأعلني بدء «وقت تصفح الكتب بهدوء»، لتنشئي روتينًا جديدًا يريحكما معًا؛ وهكذا يحصل كل منكما على الراحة بطريقته.'),
  ('9069176c-b719-421b-bb4f-85cd101945a6', 'محاولات الهروب من الحكاية 🏃‍♂️', 'أثناء قراءة الحكاية، يقفز من السرير عند كل فرصة ويركض لإحضار لعبته. فهو لا يريد الاستسلام للنوم. اخفضي نبرة صوتكِ فجأة وابدئي القراءة همسًا. سيضطر إلى العودة إلى السرير والتركيز كي يسمعكِ.'),
  ('e4d134d2-7f4f-4894-b6f3-6051d4c2f528', 'الطقس وحيلة ارتداء طبقات من الملابس ⛅', 'مع اقتراب الربيع، يكون الطقس متقلبًا؛ باردًا في الصباح ودافئًا عند الظهيرة. تذكّركِ أداة الطقس والملابس باستخدام طريقة البصلة، أي إلباس طفلكِ عدة طبقات. وفي الحديقة، انزعي عنه طبقة كلما شعر بالدفء، لتجنّبي تعرّقه وتخففي توتركِ في الوقت نفسه.'),
  ('918e0a4a-7932-41e0-b1cb-29b726120c0e', 'الذكاء الاصطناعي ونوبات العناد المفاجئة 🤖', 'هل أصبح طفلكِ الذي كان هادئًا حتى الأمس يتفاعل اليوم بعدوانية مع كل شيء؟ لا تبحثي على الإنترنت عن أسباب مخيفة. اسألي الذكاء الاصطناعي من Anacan عن الأسباب النفسية لهذه القفزة النمائية (mental leap)، وبدّدي قلقكِ بإجابة معتمدة من أطباء الأطفال.'),
  ('b03065aa-7764-4054-8d16-b42a880815cc', 'لعبة الأنف المسروق 👃', 'تقولين: «أخذتُ أنفك!» وتُظهرين له إبهامكِ، فيصدق ذلك فعلًا ويبدأ بالبكاء! في عمر 3.5 سنوات، قد لا يستطيع خيال الطفل أحيانًا التمييز بين الواقع والوهم. قولي فورًا: «آها، لقد أعدتُه إلى مكانه»، وقبّلي أنفه لتحوّلي هذه الصدمة الصغيرة إلى ابتسامة.'),
  ('f9660fac-3163-450f-a18c-f1ac86faf296', 'تواصل صامت بالعينين مع شريككِ 🥂', 'نام طفلكِ أخيرًا. تجلسين أنتِ وشريككِ جنبًا إلى جنب على الأريكة، ولا طاقة لديكما حتى للكلام. تنظران إلى بعضكما في صمت وتبتسمان فحسب. هذه النظرة الصامتة أجمل طريقة لتقولا: «نحن نتعامل مع هذه الفوضى ببراعة».'),
  ('48be6a74-039a-47b4-b2e6-38a02b369aa1', '«أنا وجدته» — طفلكِ الدارج المتملّك 🔑', 'يلتقط جهاز التحكم أو مفاتيح والده من الأرض ويقول: «أنا وجدته، إذًا هو لي!». بالنسبة إليه، العثور على الشيء يعني امتلاكه. لا تنتزعيه من يده بالقوة، بل قولي: «شكرًا لأنك وجدته من أجلي»، ثم استعيديه بعد توجيه انتباهه إلى لعبة أخرى.'),
  ('53233246-1c9c-44d8-aa89-08a12ab1932c', 'حفل موسيقي في المطبخ 🥄', 'يُخرج القدور والملاعق الخشبية ويقيم حفلًا موسيقيًا في وسط المطبخ. حتى لو أصابكِ الصداع، فهذا جزء من تطور إحساسه بالإيقاع وإبداعه. لا تتدخلي على عجل، بل اسمحي لتلك الطاقة الجامحة بأن تملأ الغرفة بموجاتها الصوتية لبضع دقائق.'),
  ('54609407-cfb4-47a1-8f37-28a152cd5950', 'منتجع صحي مصغّر في الحمّام 🛀', 'هذا المساء، لا تجعلي الاستحمام لطفلكِ وحده، بل دلّلي نفسكِ أيضًا. بعد أن ينام، جهّزي ماءً دافئًا وقليلًا من الرغوة وأشعلي شمعة واحدة في الحمّام. أغلقي الباب، وتحرري من دور الأم لمدة 15 دقيقة فقط، وعودي إلى ذاتكِ؛ فأنتِ تستحقين ذلك.'),
  ('370a629d-a585-41ae-ad7c-85bbfe349f3d', 'اعتراف في يوميات المزاج', 'أمسكي هاتفكِ. وبدلًا من تصفّح حياة الآخرين على مواقع التواصل الاجتماعي، افتحي يوميات المزاج وسجّلي أطرف موقف قام به طفلكِ اليوم لتحتفظي به للمستقبل. ستساعدكِ هذه الاستراحة الرقمية على الاسترخاء أيضًا، وسترين همومكِ تتلاشى أمام الشاشة.'),
  ('8353b398-30f5-4594-98bd-74c894cfb243', 'أعيدي الأغنية! 🎶', 'يريد سماع الأغنية التي كانت تُبث عبر الراديو وانتهت مرة أخرى. تشرحين له أنها كانت على الهواء مباشرة وقد انتهت، لكنه يبكي قائلًا: أعيديها! لا يستطيع عقل الطفل استيعاب فكرة البث المباشر بعد. ولتشتيت انتباهه، ابدئي بغناء الأغنية بنفسكِ بصوت مختلف ومضحك.'),
  ('f3893094-7182-4330-982a-7ccd3eced333', 'شاي في هدوء ☕', 'إنه يرتّب ألعابه في صف وسط الغرفة ويلعب بمفرده. أرجوكِ، لا تضيّعي تلك اللحظة في كنس المنزل! اجلسي على الأريكة، واستمتعي بقهوتكِ أو شايكِ ساخنًا، ولا تفكّري في أي شيء لمدة 10 دقائق، بل تلذّذي بهذا الهدوء فحسب.'),
  ('52d5f808-8d3e-4769-9814-0abc72834d43', 'حيلة المؤقّت للنوم ⏱️', 'هل يشعر فجأة بالعطش عند حلول موعد النوم، أو يريد الذهاب إلى الحمّام، أو حتى يبدأ بتوديع الجدار؟ اضبطي مؤقّتًا. طبّقي قاعدة «عندما يرنّ المؤقّت، ينام الجميع»، وهكذا ستنهين هذا الوداع الذي لا ينتهي وهذه المماطلة المتقنة من دون جدال.'),
  ('7cbac7ca-9f74-4319-bb84-ce56d77a4832', 'قوة مجتمع Anacan 💬', 'هل تستنزفكِ فكرة: لماذا طفلي عنيد إلى هذا الحد؟ انضمّي إلى مجتمع Anacan. عندما تقرئين عن نوبات الغضب العبثية المشابهة التي تحدث في منازل الأمهات الأخريات، ستدركين أنكِ لستِ وحدكِ وأن ما تمرّين به طبيعي تمامًا.'),
  ('c2a3c84a-3b57-4bf9-bcc3-b6512c66a43b', 'الفنان الحقيقي يختار الجدار 🖍️', 'انتهت بضع ثوانٍ من الصمت بمفاجأة غير سارّة. دخلتِ الغرفة فوجدتِ طفلكِ قد رسم تحفة فنية على الجدار بأقلام التلوين. خذي نفسًا عميقًا. فمهاراته الحركية الدقيقة تتطور، ويمكن تنظيف الجدار على أي حال. احرصي على تصوير هذه التحفة لتضحكي عليها في المستقبل.'),
  ('017dd4ef-6a6d-470c-a536-c9d8157780f2', 'دعوة إلى الظلام 🌙', 'هل يشعر طفلكِ بالقلق عندما تنطفئ أنوار غرفة النوم؟ ضعي في إحدى زوايا الغرفة مصباحًا ليليًا صغيرًا بلون دافئ (برتقالي أو أحمر). أما بقية الغرفة فينبغي أن تظل مظلمة تمامًا لدعم إفراز الميلاتونين والنوم العميق.'),
  ('0cf9c44c-98af-4034-b557-39b1dbb9f133', 'محاولة لتصفيف الشعر ✂️', 'تدخلين الغرفة فتجدينه ممسكًا بالمقص ويحاول قص شعر دميته. عيش هذه اللحظة كابوس تخشاه كل أم. خذي المقص منه بهدوء، واحتفظي بصورة هذه المحاولة لتصفيف الشعر ضمن جلسة تصوير طفلكِ، لتصبح ذكرى طريفة في أرشيفكِ.'),
  ('8ca291c9-dcd2-4396-9580-b58e8c48c73a', 'دعيه يكتب السيناريو 🪄', 'لقد مللتما كلاكما من الكتب التقليدية، وبات جو الغرفة مملًا. افتحي الحكايات الذكية ودعيه يوجّه أحداث القصة هذا المساء. اسأليه: إلى أين ستذهب هذه السيارة الطائرة الآن؟ ودعيه ينام وهو يخوض مغامرات الفتح في خياله.'),
  ('bd553ea9-8ebf-4e59-8a1a-239cd4d4cf83', 'المنافس في المرآة 🪞', 'هل يقف أمام المرآة ويقطّب حاجبيه لنفسه، ويصنع تعابير غاضبة وغريبة؟ إنه يختبر كيف تبدو المشاعر على وجهه. شاهدي بصمت واستمتاع تدريبات هذا الممثل المسرحي الصغير.'),
  ('c78f6742-28ba-40d4-8884-94cee25316f0', 'حديث هامس مع الجدار 🤫', 'هل دخل فراشه وأدار وجهه نحو الجدار وبدأ يهمس لشخص ما بما يزعجه؟ كم هذا لطيف! أطفئي الأنوار، واسترخي وأنتِ تستمعين إلى تلك الهمسات وهي تمتزج بالنوم.'),
  ('ca5cea03-5260-4977-bf88-cfe3ed937e38', 'معركة الكوب الخطأ؟ 🥤', 'هل قامت الدنيا في الغرفة لأنكِ قدّمتِ الماء في الكوب الأصفر؟ لا تأخذي الأمر بجدية، فهو يختبر حدودكِ هذا الصباح فحسب. اسكبي الماء فورًا في الكوب الأزرق، وأعيدي السلام إلى الغرفة ووفّري طاقتكِ لبقية اليوم.'),
  ('f8e8bb79-94ba-4264-b58d-e4f81f8007f5', 'عداوة مع المكنسة الكهربائية 🌪️', 'هل يعترض طريقكِ باكيًا حين تنظفين المنزل ويقول: لا تشفطي غباري؟ لقد بلغ شعوره بالملكية حدًا عبثيًا. أطفئي المكنسة وأقيما مراسم وداع للغبار لمدة 5 دقائق. صدّقيني، سينهي ذلك هذه الفوضى بسرعة أكبر.'),
  ('0d30a53e-aee6-4a89-9af7-e9e0ea21f7c9', 'اختلطت الملابس مجددًا 🧥', 'هل تستعدان للخروج، لكنه يريد ارتداء حذاء مطري وقميص قصير الأكمام؟ لا تجادليه. افتحي قسم الطقس والملابس، وأريه أن الهاتف لا يسمح بذلك. اجعلي الشاشة الرقمية صاحبة القرار وانسحبي من الموقف، وسيرتدي قميصه بهدوء.'),
  ('310c5e1a-58e7-49ee-a785-62a8445bbaba', 'حلم كوب من الشاي ☕', 'هل أنتِ متعبة إلى درجة أنكِ تسللتِ إلى المطبخ بينما كان يلعب وأغلقتِ الباب؟ معكِ حق. افتحي مفكرة المزاج واكتبي كلمتين فقط: نجوت اليوم. أحيانًا لا تحتاج الأم سوى إلى تلك الاستراحة القصيرة التي تدوم 5 دقائق.'),
  ('a80cc41d-cd81-475f-9ddf-075470e2ad74', 'أمسكي بالسحابة كي لا ترحل! ☁️', 'هل ينظر من النافذة ويبكي لأن السحابة ترحل؟ لا تضيّعي وقتكِ في شرح حركة الرياح علميًا. قولي له: لقد ذهبت الآن لإلقاء التحية على أطفال آخرين. حوّلي فلسفته الغريبة إلى مزاح وحكايات صغيرة مختلقة، وأنقذي يومكِ.'),
  ('154abe48-3205-47d2-a68c-a06bfd4856c5', 'مصارعة الأريكة مع أبيه 🤼‍♂️', 'هل هرب واختبأ كي لا يذهب إلى السرير؟ مرّري الكرة إلى أبيه، ودعيهما يتظاهران بالمصارعة على الأريكة. هذه اللعبة الصاخبة والمُجهدة بين الأب وطفله ستستنزف آخر ما لديه من طاقة عنيدة وتجعله يستسلم للنوم.'),
  ('1d80be38-a3ec-4e4f-a266-479942a81b0f', 'هل سئمتِ من أمهات الإنترنت؟ 📵', 'لا تشعري بالإحباط حين تفتحين إنستغرام وترين أطفال الجميع مثاليين! أغلقي ذلك التطبيق وادخلي إلى مجتمع Anacan. عندما ترين أن بيوت الأخريات فوضوية مثل بيتكِ وأن أطفالهن صاخبون، خذي نفسًا عميقًا؛ فأنتِ لستِ وحدكِ!'),
  ('f6d7cbf6-3d15-4e2d-b2fb-3b33515a0a37', 'سأطهو هذا بنفسي! 🍳', 'أصرّ على خفق البيضة بنفسه، فانسكب نصف ما في الوعاء على الطاولة؟ دعي ذلك الطاهي الصغير يستمتع بنظرة الفخر في عينيه. سيُنظَّف المطبخ على أي حال، لكن لا تمسّي اعتزازه المتنامي بذاته واستقلاليته.'),
  ('66d60d54-4a5d-4de0-a372-047beaa63d3c', 'مخزون المعكرونة السرّي 🍝', 'هل وجدتِ قطعة معكرونة جافة في جيب سرواله أثناء غسله؟ ليس هذا جشعًا، بل تخطيط طفولي للمستقبل. ألقيها في سلة المهملات بوجه جاد، لكن ابتسمي في داخلكِ لهذا المستكشف الصغير الذي يعرف كيف يخزّن مؤونته. إنهم يكبرون!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ar = v.t, body_ar = v.b
FROM (VALUES
  ('d2eca751-d4a9-42ee-89e8-a1b216e785bc'::uuid, 'رقم الهدوء على الشاشة 🤫', 'لقد نام أخيرًا. هل غرق المنزل في صمت شديد حتى بدأتِ تسمعين طنينًا في أذنيكِ؟ افتحي مقياس الصوت في التطبيق. ستكون رؤية عبارة 0 ديسيبل أفضل تدليك بصري في العالم لدماغكِ المتعب والمُنهك من الضجيج.'),
  ('d6eb2191-63cd-4b2d-9410-9f12b1424bea', 'بطاقة القميص تخزني! 🏷️', 'يرفض ارتداء القميص لأن تلك البطاقة الصغيرة في الخلف تخزه كالإبرة؟ قد تدفعكِ الحساسية الحسية في عمر 3.5 سنوات إلى الجنون. لا تدخلي في أي جدال؛ خذي المقص واقطعيها من جذورها، وأنهي هذه الأزمة الصغيرة في ثوانٍ.'),
  ('772e1eef-c912-4a17-abaa-b5296c686fe3', 'كان ذلك حجري! 🪨', 'هل يصرخ لأنكِ رميتِ ذلك الحجر المتّسخ الذي أحضره من الحديقة؟ يبدو أنه كان أعز أصدقائه! سارعي إلى إيجاد شيء آخر لامع، وقولي له: «انظر، لقد أرسل لك الحجر هذا تذكارًا»، وأنقذي الموقف ببراعة بقصة من خيالكِ.'),
  ('8d7ffafe-9007-449d-a1c5-50fafa6a8a92', 'حكايتي، وقواعدي 📖', 'هل أخطأتِ في نطق كلمة أثناء قراءة الحكاية، فصحّحها لكِ فورًا؟ هذا يعني أنه حفظها! أغلقي الكتاب وقولي له: «إذًا اقرأها أنت لي هذا المساء». دعي خياله ينطلق، بينما تستلقين أنتِ وتستمعين إلى صوته فحسب.'),
  ('8d6625c2-a9b5-42f5-804d-da69978a47f8', 'لصّ الهاتف 📱', 'بينما كنتِ تصبّين لنفسكِ الشاي، لاحظتِ أن هاتفكِ قد اختفى، وإذا به خلف الأريكة يقول «ألو» مثلكِ. إنه يمسح عاداتكِ الرقمية.'),
  ('e750fc50-e44a-47b8-b631-5ac89b90275d', 'سياسة «ارتدِ ملابسك بنفسك!» 👖', 'يرفع ساقيه إلى الأعلى ويقول: «أنا صغير، ألبسيني أنتِ». يتأرجح الأطفال بين الاستقلالية والاعتماد عليكِ. لا تجبريه على ارتداء ملابسه. ضعيها بجانبه وقولي: «هذا السروال الخارق ينتظر صاحبه»، واستخدمي قليلًا من الحيلة المرحة.'),
  ('fa66784d-c126-46e1-ac35-502bd4ad5f50', 'سلام داخلي مع مقياس الصوت 🤫', 'لقد نام أخيرًا، لكن الطنين في أذنيكِ لا يتوقف. افتحي مقياس الصوت في التطبيق. راقبي عبارة «0 ديسيبل» على الشاشة، وتأملي بصريًا كيف يتسلل هدوء الغرفة إلى دماغكِ ويمنحكِ السكينة والتعافي.'),
  ('61c7ca48-5a19-4998-8086-07edd1d4d938', 'المواساة في مجتمع Anacan 💬', 'هل يخنقكِ شعور «لن أكون مثالية أبدًا»؟ تخلّصي من وهم أمهات إنستغرام. ادخلي إلى مجتمع Anacan، واقرئي الاعترافات الصادقة لأمهات تعمّ الفوضى منازلهن ويرسم أطفالهن على الجدران، ثم قولي: «أنا طبيعية تمامًا».'),
  ('7a600dc5-32dc-4b11-81f6-fb429bfb7588', 'قوة الهمس الغامضة 🌙', 'يختلق الأعذار للهروب من السرير. اخفضي صوتكِ تمامًا ولا تتحدثي إلا همسًا. سيضطر إلى تركيز انتباهه جسديًا كي يفهمكِ، وهذا التركيز سيهدّئ دماغه كما لو كان تحت تأثير التنويم، فيغفو.'),
  ('fbad87dc-8f76-4644-9e49-49107be8118b', 'منطق الديناصورات 🦖', 'لا يجيب عن أي سؤال في الصباح، بل يزمجر فقط. إنه اليوم ديناصور T-Rex. تماشي مع هذه الشخصية التي ابتكرها واسأليه: «هل تأكل ديناصورات T-Rex العصيدة؟»، لتُكملي روتين الصباح من دون دموع.'),
  ('401f5436-2de1-44e1-911f-f31af21dfae8', 'أبطال الأب الخياليون 🦸‍♂️', 'انسوا حكايات الكتب هذا المساء. دعي الأب يروي قصة خيالية مذهلة يكون طفلكِ بطلها. عبارات مثل: «ثم استلّ سيفه... ونظّف أسنانه!» ستغرق طفلكِ في الضحك وتهيئه للنوم.'),
  ('cc1183e6-40b5-4a08-b574-b47668387f44', 'انتقاد رسمه بنفسه 🖍️', 'يريكِ خربشاته السوداء ويقول: «كان هذا أنتِ، لكنه لم ينجح»، ثم يمزق الرسم ويرميه. بدأت تتكوّن لديه القدرة على نقد ذاته! لا تقللي من شأن مشاعره، بل ادعمي تطوره بقولكِ: «ما رأيك أن تجرّب اللون الأحمر أيضًا في الرسم التالي؟».'),
  ('ba68f77d-f963-479b-bdc5-453510fe2fd8', 'محققة الحساء في مهمة 🥕', 'هل غمست الملعقة في الحساء، وعثرت على قطعة البصل الوحيدة وأبعدتها؟ يا لها من دقة صائغ مجوهرات! تصفحي فورًا الوصفات الصحية، وتعلّمي كيف تخلطين تلك الخضراوات بالخلاط وتخفينها في الصلصات بدءًا من الغد، لتحققي انتصارًا سريًا.'),
  ('3f320efd-46d8-4e41-85e8-a584506068f1', 'صمت رومانسي بينكما 🥂', 'نام طفلكِ، وأصبح المنزل مرتبًا. اجلسي بجانب شريككِ على الأريكة، ولا تشغّلا التلفاز حتى. فقط تبادلا نظرة تقول: «نجحنا في هذا أيضًا ونجونا!». صدّقي أن هذه هي أكثر لحظات الأبوة والأمومة واقعية ورومانسية.'),
  ('5c1ffe1c-132b-41ee-89f2-40908e4efd15', '«أريده!» المرعبة في المتجر 🛒', 'هل يصرخ طلبًا للشوكولاتة أمام صندوق الدفع مباشرة؟ لا تستسلمي رغم نظرات الواقفين خلفكِ. افتحي قائمة التسوق وقولي: «ليست موجودة هنا، وصندوق الدفع لن يقبلها». فالسلطة الخارجية تبدو لهم دائمًا أكثر إقناعًا.'),
  ('68fe0739-89b9-4724-85e1-174aecc17d9d', 'لماذا تحدثتِ إليّ؟ 😤', 'هل غضب لمجرد أنكِ قلتِ له: «صباح الخير»؟ مرحلة الزعل بلا سبب مستمرة بأقصى قوتها. لا تضغطي عليه، بل اسكبي لنفسكِ كوبًا من الشاي واستمتعي به. ثقي أنه سيأتي بعد دقيقتين ليتشبث بركبتيكِ. فمشاعره مختلطة إلى هذا الحد!'),
  ('5a73dbf6-a948-449b-bd9f-bd6acec175f3', 'طفل يمشي على أربع 🐾', 'هل خرج من السرير هذا الصباح زاحفًا كالكلب بدلًا من أن يمشي كطفل؟ لا تبدئي بترديد القواعد فتغضبي. قولي: «أحسنت يا كلبي الصغير الذكي»، ثم قدّمي له الفطور. فمشاركته في لعب الأدوار توفّر طاقة أكبر بكثير من الدخول معه في صراع عناد.'),
  ('b5299007-402e-4c46-9a86-5fb45df938df', 'صرخة مفاجئة في منتصف الليل 😭', 'هل استيقظ ليلًا باكيًا وعيناه مغمضتان، ولا يستجيب لكِ؟ قارني حالته بدليل تحليل البكاء؛ فهذا رعب ليلي. حاولي ألّا توقظيه، وابقَي بجانبه فقط، وأمسكي يده وربّتي عليه. سيهدأ من تلقاء نفسه ويعود إلى النوم العميق.'),
  ('cd19d080-ed21-40f3-b449-164e996aed41', 'جسدي لم يعد ملكي 🔋', 'هل يتشبث بساقكِ طوال اليوم ويطلب أن تحمليه؟ لقد استُنزفتِ جسديًا. أنتِ تعانين من إرهاق اللمس (touched out). اتركيه في الغرفة مع ألعابه، واختلي بنفسكِ في الحمّام لمدة 5 دقائق لتستمتعي بلحظة من العزلة. فهذا من حقكِ.'),
  ('3c2e2a41-c838-4dd0-b137-24862355a226', 'أنا من سيفتح الباب! 🚪', 'هل بكى عند خروجكما من المنزل لأنكِ فتحتِ الباب، وأجبركِ على إغلاقه مجددًا؟ الشعور بالسيطرة هو أكبر احتياج نفسي في هذا العمر. دعيه يكلّفكِ دقيقة واحدة، فهذا قد يمنع نوبة غضب تستمر 30 دقيقة في الخارج ويعزز ثقته بنفسه.'),
  ('93ebf06c-8a17-42ec-bbd4-671ae644ffaa', 'فيضان الماء في حوض الاستحمام 🌊', 'هل الاستحمام مجرد حجة، بينما يحوّل حوض الاستحمام إلى محيط ويلعب بالأمواج؟ دعيه يلعب. فضجيج الماء وتناثره سيبددان تلك الطاقة العنيدة التي لا تنفد في داخله. وفي المساء، سيستلقي في سريره من دون أي مقاومة.'),
  ('ed5a44fd-8133-4d4a-859e-893fc179d90d', 'إجابة الذكاء الاصطناعي عن الأسئلة الغريبة 🤖', 'هل وقفتِ حائرة أمام سؤال: ماما، أين يذهب ظلي ليلًا؟ لا تختلقي إجابة. افتحي Anacan AI واحصلي على ألطف إجابة علمية بأسلوب قصصي تناسب طفلًا بعمر 3.5 سنوات، ثم اقرئيها له. ستشعرين بأنكِ فيلسوفة عظيمة وأم تعرف كل شيء.'),
  ('14c25fd3-e3ee-49fb-8520-527d8c11b191', 'فخر ارتداء القميص بالمقلوب 👕', 'هل ارتدى قميصه بالمقلوب ويرفض بإصرار أن تسمحي له بتعديله؟ هذا شأنه! فالثقة التي تملأ عينيه وتقول «لقد فعلتها بنفسي» أهم من ارتداء القميص بالطريقة الصحيحة. دعيه يتجول به فخورًا طوال اليوم، فهذا اختياره.'),
  ('4ffcb0aa-a9e4-48df-8c7b-2bcf41163980', 'النوم بالهمس 🤫', 'هل ينهض من السرير ويركض في الغرفة رافضًا النوم؟ لا تصرخي. ابدئي فجأة بالتحدث بصوت خافت جدًا وبهمس. سيضطر إلى التركيز بشدة كي يفهمكِ، حتى يتعب دماغه وينتقل تلقائيًا إلى وضع النوم. جرّبي ذلك!'),
  ('5dd3ffc3-a306-476f-91ee-6cb8332ca500', 'لحظة الصمت المثالية 🛋️', 'هل اندمج في تركيب أحاجيه بعمق حتى عمّ المنزل صمت مفاجئ؟ لا تشكّي في الأمر، بل اسكبي لنفسكِ فنجانًا من القهوة فورًا. لا تهدري تلك الدقائق النادرة والثمينة في التنظيف أو غسل الملابس، بل استثمريها في إراحة روحكِ. أنتِ لستِ آلة.'),
  ('3481c7e9-17f1-45e8-b5ca-16ba68fd1628', 'مختبر صغير في حوض الاستحمام 🛀', 'إنه يمزج قطع الصابون المختلفة الألوان بالماء ليصنع جرعة سحرية. نعم، ستعمّ الفوضى الحمّام. لكنه يتعلم عن المذيبات وامتزاج المواد. هذا الاستكشاف العلمي هو أفضل وسيلة لتخفيف تعب المساء وتهيئته لنوم هادئ.'),
  ('628064ef-a8e4-4e1f-b2f9-27acab4d05cf', 'ثورة الاكتفاء من اللمس 🔋', 'لقد استنزفكِ جسديًا طفلكِ الذي يتسلق جسدكِ ويشد شعركِ طوال اليوم. ضعيه فورًا في مكان آمن وانتقلي إلى غرفة أخرى. اكتبي في يوميات مزاجكِ «جسدي لم يعد ملكي» لتخففي العبء النفسي لمتلازمة الإنهاك من كثرة اللمس.'),
  ('6dfd2aa0-4f21-483a-bbab-d26de61eb620', 'العزلة الاجتماعية داخل الخزانة 🚪', 'توقفت الضوضاء فجأة في وسط المنزل. ثم وجدتِه يلعب وحده في الظلام داخل خزانة الملابس. هذا ليس اكتئابًا، بل مجرد لحظة لإعادة ضبط حواسه. أغلقي الباب برفق وامنحيه رفاهية الاستمتاع بهذه المساحة الخاصة.'),
  ('faf3013a-4d98-4178-82f0-b76954e80a74', 'وجدتُ هذا في المتجر 🛒', 'عندما تقتربين من صندوق الدفع، تظهر في العربة عبوة بسكويت لم تضعيها أنتِ. لقد نفّذ طفلكِ مهمة استكشافية بصمت. افتحي قائمة التسوق وقولي: «انظر، هذا غير موجود في قائمتنا، سنضيفه في المرة القادمة»، وبذلك اجعلي القائمة الرقمية هي صاحبة القرار.'),
  ('064802a6-44a3-418a-af04-e8b21366e4d7', 'أولمبياد تسلّق الأثاث 🧗‍♂️', 'يتسلّق حافة الأريكة متجهًا نحو النافذة. المنزل مليء بالمخاطر في نظركِ، لكنه صالة رياضية في نظره. بدلًا من إثارة الذعر بقولكِ: «انتبه، ستسقط!»، وجّهي حاجته إلى الحركة بطريقة صحيحة بقولكِ: «ضع يدك هنا».'),
  ('1c07d667-ff98-498d-8a14-c5dc48ceda8c', 'عملية الخضراوات السرية 🥦', 'يعثر على حبة الأرز أو قطعة الجزر الوحيدة في الحساء ويقول: «لن آكل هذا». ادخلي إلى خطة التغذية، وتعلّمي كيف تحوّلين البروتينات والخضراوات إلى كعكات ملوّنة لتتحايلي على عقل هذا الطاهي العنيد.'),
  ('7ce3cc61-1a21-499e-a7c2-d24e3693336c', 'شاي الزوجين 🥂', 'بعد يوم شاق، اسكبي شايًا ساخنًا عاديًا في الكوبين. اجلسي مع شريككِ على الأريكة وجهًا لوجه، وتبادلا نخب الشاي قائلين: «نجونا اليوم أيضًا من كل تلك الفوضى، نحن فريق رائع». فأنتما الأساس الراسخ للمنزل.'),
  ('1df156d6-3bcc-40f2-9b20-0e5a8f5c09c2', 'الخوف من الظل 👻', 'بينما كنتما تسيران في الشارع، خاف طفلكِ فجأة من ظلّه واختبأ خلفكِ. لا تبحثي عن المنطق، فخيال طفل في عمر 3.5 سنوات يعمل بهذه الطريقة. قولي له: «هيا نقفز فوق الظل»، وحوّلي ما يخيفه فورًا إلى لعبة حركية.'),
  ('9cee1c64-59c7-411a-9cc4-1d823dfe8c01', 'الذكاء الاصطناعي والطمأنينة 🤖', 'هل دفعتكِ التأتأة المفاجئة لدى طفلكِ أو نوبات غضبه إلى البحث على الإنترنت عن أمراض خطيرة؟ توقّفي! اسألي Anacan AI عمّا إذا كان ذلك مرتبطًا بطفرة النمو في سن 3 سنوات، واحصلي على إجابة مطمئنة ومعتمدة من أطباء الأطفال.'),
  ('d8c70945-12ad-4739-98a0-3d98184c5d44', 'المؤثرات الصوتية في الغرفة 🪄', 'افتحي الحكايات الذكية. وأثناء قراءة القصة، اصنعي مسرحًا صوتيًا في الغرفة بمجرد تقليد صرير الباب وصوت الرياح والهمسات. ستجذب هذه الموجات الصوتية غير المألوفة انتباه طفلكِ فورًا إلى عالم الحكاية، ومنه إلى نوم عميق.'),
  ('a4d74500-c7bc-4a1a-a200-c6bae74eb5ce', 'وسط الخبز لي! 🍞', 'هل يأكل طفلكِ وسط شريحة الخبز فقط ويناولكِ القشور؟ لا تجادليه بشأنها. بدءًا من الغد، قطّعي الخبز بقوالب البسكويت المعدنية على شكل حيوانات. فالتصميم يحلّ فورًا هذه المشكلة المتعلقة بفلسفته الغذائية.'),
  ('8d0e8d79-2ed2-4d47-9d71-055f26b53574', 'الحديث مع الجمادات 🗣️', 'قد يتحدث بجدية تامة إلى حجر في الحديقة أو إلى كرسي في المنزل، بل ويوبخهما. من خلال اللعب الرمزي، يحاول طفلكِ فهم العالم من حوله واستيعابه.'),
  ('b3a793f1-dd90-4ef7-9ff1-f7ee9746e0d9', 'لعبة الغميضة في الصباح الباكر 🙈', 'أنتِ متأخرة عن العمل أو الحضانة، بينما يختبئ هو خلف الستارة ويقول: «اعثري عليّ!». حتى لو أوشكت أعصابكِ على الانهيار، فإن الصراخ سيطيل الأمر أكثر. شاركيه اللعب لمدة 2 دقيقة وقولي: «تُرى أين اختفى صغيري الجميل؟»، ثم اعثري عليه وأخرجيه من مخبئه.'),
  ('5672be3d-87ec-469d-a4b7-fca0b00ec9ac', 'سياسة الحديقة 🤝', 'هل يدفع طفلًا آخر عن الزحليقة لأنه يريد أن يركبها بنفسه؟ لا تزال المشاركة مفهومًا معقدًا لم يترسخ لديه تمامًا. بدلًا من إحراجه أو معاقبته، ذكّريه ببساطة بالنظام وقولي: «إنه دوره الآن».'),
  ('7b9a42e6-44aa-4528-9036-fbb93f662348', 'لماذا تنظر إليّ الشمس؟! ☀️', 'هل يفتح عينيه صباحًا ثم ينفجر بالبكاء قائلًا: «لماذا تنظر الشمس مباشرةً إلى عينيّ؟» لا تبحثي عن المنطق ولا تحاولي شرح الظواهر الطبيعية؛ فهو غاضب فقط لأنه لا يستطيع التحكم في العالم. أغلقي الستارة وقولي: «لقد أخفيت الشمس من أجلك»، وهكذا تحلين هذه المشكلة العبثية في ثوانٍ.'),
  ('bf33243a-24ca-4b24-a11a-d703c038cdcf', 'سيارتي لم تنم بعد! 🚗', 'هل يصرّ على عدم الذهاب إلى الفراش قائلًا: «سيارتي ليست نعسانة»؟ كثيرًا ما يُسقط الأطفال أرقهم ومقاومتهم للنوم على ألعابهم. لا تجادليه، بل افتحي «الحكايات الذكية» وأنشئي حكاية عن السيارات. ما إن تنام السيارة حتى يغمض عينيه تلقائيًا. جرّبي وسترين!'),
  ('5c063277-1aff-4166-9dbe-d6ab5866cdbd', 'يجب إزالة قشرة الخبز! 🍞', 'هل يأكل الجزء الطري فقط من الخبز المحمص ويرفض أطرافه بإصرار؟ لهذا العمر ذوق بصري خاص. تعلّمي تقطيع الخبز على هيئة حيوانات لطيفة. سيُنهي هذا التصميم الخلاف فورًا.'),
  ('a42141c6-7a93-4719-be36-e495b333ffee', 'متعة تبادل النظرات بصمت 🥂', 'نام طفلكِ وأصبح المنزل مرتبًا. اجلسي بجوار شريككِ على الأريكة، ولا تشغّلا التلفاز حتى. فقط تبادلا نظرة تقول: «لقد نجونا اليوم أيضًا». صدّقي أن هذه أكثر لحظات الأبوة والأمومة المرهقة رومانسيةً وواقعية.'),
  ('fbd48b54-2407-4752-a5b5-4e335233ace4', 'مأساة البقعة غير المرئية 👕', 'هل وجد بقعة على قميصه لا تُرى إلا بالمجهر ورفض ارتداءه؟ تظاهري بمسحها بمنديل مبلل وقولي: «لقد جعلتها تختفي بالسحر». يثق عقل الطفل دائمًا بسحر أمه؛ جرّبي وسترين.'),
  ('0da92da6-227b-4bc4-8733-939d83f883ad', 'فلسفة منتصف الليل 🦉', 'بمجرد أن يدخل السرير، يطرح أسئلة عميقة مثل: «ماما، لماذا لا تسقط الغيوم؟». ليس هدفه تعلّم العلوم، بل التحدث معكِ وتأخير موعد نومه. قدّمي له إجابة قصيرة وخيالية مثل: «لأنها تنام في الأعلى»، ثم شغّلي اللحن الهادئ في «الحكايات الذكية» واحسمي وقت النوم بهدوء.'),
  ('1b4bdd7d-042a-4be6-a59f-82892d67ff8d', 'ذلك السؤال الصادم في المتجر 😳', 'هل سأل بصوت مرتفع وأنتما تنتظران عند صندوق الدفع: «لماذا يبدو شعر هذه السيدة هكذا؟». لا تُشعريه بالخجل ولا تُسكتيه، بل وجّهي انتباهه فورًا إلى «قائمة التسوق» في التطبيق، وقولي: «لنرَ، هل اشترينا التفاح؟»، واخرجي من الموقف بلباقة.'),
  ('62a75f9a-ac96-44d5-9f0d-ddc0ab3d545e', 'لماذا غُسل ذلك القميص؟! 👕', 'هل أُعلنت حالة الحداد في المنزل لأنكِ وضعتِ قميصه المفضل، الذي بهت لونه، في الغسالة؟ أحيانًا يتجاوز تعلّق الأطفال بأغراضهم حدود المنطق. لا تجادليه؛ افتحي فورًا «جلسة تصوير الطفل» وصوّريه وهو غاضب لتحوّلي الموقف إلى ضحك. جرّبي حيلة: «تعالَ نرَ كم تبدو غاضبًا على الشاشة!»؛ فهي تشتّت انتباهه على الفور.'),
  ('4e937fd6-67f9-496a-b0c5-be8bf0840c6d', 'أطفئي الأنوار، وليبدأ مسرح الظل 🐰', 'هل يخاف من الظلام ولا يريد الخروج إلى الممر بمفرده؟ أطفئي أنوار الغرفة تمامًا وشغّلي مصباحًا يدويًا صغيرًا. اصنعي بيديكِ على الحائط ظلال كلب وطائر، وحوّلي الظلام في نظره من مكان مخيف إلى ساحة للعب. عندها لن يستغرق نومه سوى لحظات.'),
  ('6d8c96e4-6f09-4805-a4a8-4acf034ab6c9', 'أنتِ أيضًا بحاجة إلى الانفصال عن العالم ☕', 'هل انشغل باللعب بألعابه في الغرفة لدرجة أن هدوءًا مفاجئًا عمّ المنزل؟ أرجوكِ، لا تضيّعي تلك اللحظة في كنس المنزل أو طيّ الملابس! تمدّدي على الأريكة، واكتبي في «مذكرات المزاج»: «5 دقائق من السلام»، واستمتعي بقهوتكِ وهي ساخنة. فأنتِ أيضًا إنسانة تعيش في هذا المنزل.'),
  ('f30558ce-2e74-4368-ad59-ff72d43fefc7', 'لم أُسقطه، دُبّي هو من فعل! 🧸', 'هل تعمّد سكب الماء على الأرض ثم ألقى اللوم على لعبته؟ إنه لا يكذب، بل اكتشف للتو آلية الدفاع لدى الأطفال في عمر 3.5 سنوات. لا تعانديه، بل قولي: «إذًا، تعالَ نعلّم دُبّك كيف ينظّف»، ثم ضعي المنشفة في يده. هكذا سيتعلّم تحمّل المسؤولية من دون أن تُجرح مشاعره.'),
  ('9415f8e5-8d8c-4d14-89d3-6bbcf1455c0e', 'عناد يتحدّى قوانين الفيزياء 💧', 'سكب الماء على الطاولة، ثم أخذ يبكي ويطالبكِ بإعادته إلى الكوب! نعم، لا مكان للمنطق الآن؛ فما يشعر به هو خيبة أمل بسبب خطأ لا يمكن التراجع عنه. لا تحاولي الشرح، بل أعطيه منشفة وقولي: «تعالَ نُخفِ هذا الماء»، وحوّلي الأمر إلى لعبة.'),
  ('aff11dbf-a5df-4f87-ba8b-797021b1bfe4', 'ملاذ ماما بعيدًا عن الضوضاء 🚪', 'الضجيج يصمّ أذنيكِ. اتركي طفلكِ في مكان آمن (أو مع والده)، وادخلي الحمّام وأغلقي الباب. حدّقي في الحائط لمدة 5 دقائق فقط، ولا تفعلي شيئًا، ولا تفتحي حتى هاتفكِ. هذا الهدوء القصير هو أقوى وسيلة تساعدكِ على استعادة طاقتكِ والعودة إلى دوركِ كأم.'),
  ('f965edcf-2124-46c3-82a9-e8d418ee755a', 'وضع الطيران مع الأب ✈️', 'لم يتمكن طفلكِ من تفريغ طاقته في المنزل ولا يريد الذهاب إلى السرير. استدعي الأب إلى الأريكة. عندما يرفعه في الهواء ويحمله كأنه طائرة، ستبدد ضحكاته التي تملأ الغرفة كل التوتر الجسدي المتراكم في ثوانٍ. الكرة الآن في ملعب الأب.'),
  ('535821ef-9689-4454-87b8-1d43fe500b62', 'ابتكار لغة جديدة 🗣️', 'يؤلف جملًا شاعرية خيالية تمامًا، فينسب المشاعر إلى الأشياء ويقول مثلًا: «حزنت لعبتي» و«بكت السماء». تنمو حصيلته اللغوية وذكاؤه العاطفي بسرعة مذهلة. وثّقي فلسفته اللطيفة فورًا باستخدام وضع الفيديو في جلسة تصوير طفلكِ.'),
  ('baf0af3c-984e-45f1-a68f-93e13e9f1cef', 'قائد المطبخ منهمك في العمل 🧑‍🍳', 'عندما تحضّرين الكعك، يصرّ على وضع كرسي بجانبكِ وسكب الدقيق بنفسه. إذا سمحتِ له، فستعمّ الفوضى المطبخ. أعطيه وعاءً فارغًا وماءً وقليلًا من الدقيق، وقولي له: «اعجن عجينة كعكتك بنفسك». ستحدث فوضى، لكنه سيشعر بالرضا التام عن نفسه.'),
  ('cba9ff3e-e38f-40b7-b48d-13e030f8993a', 'تمرّد «كُل بنفسك!» 🥣', 'مع أنه يستطيع تناول الطعام بنفسه، فإنه يصرّ على أن تطعميه، ثم يدفع الملعقة ويبكي. إنها مرحلة مليئة بالتناقضات. لا تحاولي إطعامه ولا تخافي من بقائه جائعًا. ضعي الطبق أمامه، وقولي: «ستأكل عندما تجوع»، ثم غادري المائدة. سيأكل بنفسه.'),
  ('1633765a-e691-4a02-b657-169e03223f3f', 'مخزون الأم الغذائي 🥗', 'فكرتِ في قوائم طعام متنوعة لإشباعه، لكن هل انتهى بكِ الأمر مجددًا إلى تناول شيء جاف وأنتِ واقفة؟ قدّري نفسكِ واختاري من الوصفات الصحية وجبة غداء تمنح الطاقة، وتُحضّر في 10 دقائق، وغنية بالحديد والكالسيوم؛ فهي ليست للأطفال فقط، بل للأمهات أيضًا.'),
  ('2d30d5d5-9abc-4c5e-847a-462fa693fbda', 'معركة «لعبتي مريضة» 🩺', 'يمسك بسماعته الطبية اللعبة، ويفحص دبه بجدية، ثم يضع له ضمادة لاصقة. من خلال اللعب التخيلي، يتعلم التعاطف والاهتمام بالآخرين. استلقي أنتِ أيضًا وتقمّصي دور مريضة في المستشفى، ودعيه يفحصكِ بهدوء لمدة 5 دقائق.'),
  ('37ed4aaf-5c8b-418c-8274-802f79f0bf41', 'نوم سهل مع الحكايات الذكية 🪄', 'لقد حفظتِ الكتب الكلاسيكية عن ظهر قلب. افتحي الحكايات الذكية، واجعلي طفلكِ بطل القصة وغرفته المكان الذي يجب فتحه، لتصنعي جلسة نوم استثنائية لا تتطلب أي جهد.'),
  ('72e4a373-da8e-4cf7-b36b-25d3d3a13b6e', 'فقط عانقيه 🫂', 'لا حاجة إلى أي لعبة أو كتاب أو حكاية. هذا المساء، ضمّيه إلى صدركِ فحسب، واستنشقي رائحته الجميلة بعمق، ثم اهمسي له في الظلام كم هو غالٍ عليكِ وكم تحبينه.'),
  ('e1513af5-17e8-478e-acc0-67084e546889', 'فقط استنشقي رائحته بعمق 🫂', 'هل دفعكِ اليوم فعلًا إلى الجنون واستنزف طاقتكِ؟ لكنه ينام في سريره بكل هذه البراءة... أطفئي الأنوار ولا تقرئي قصة. استلقي بجانبه، واستنشقي بعمق رائحة الطفولة النقية، واحمدي الله على هذا اليوم أيضًا.'),
  ('f1d4800f-e749-493d-9ba5-56a7cf6edfa0', 'مشكلة «لا أريد الخروج من المنزل» ⛅', 'هل تشعرين أن الجدران الأربعة تخنقكِ، بينما يبكي هو على الأريكة رافضًا الخروج؟ افتحي قسم الطقس والملابس، واختاري التنسيق المناسب، ثم اصطحبيه إلى الحديقة حتى لو اضطررتِ إلى الإصرار. ما إن يلامس الهواء النقي وجهه حتى يتلاشى كل ذلك الغضب. نحن نثق بكِ!'),
  ('3a198cfb-0f8d-4bb9-b96b-0ead690adcbf', 'قانون الأطعمة التي لا يجوز أن تتلامس 🚫', 'هل اندلعت ثورة على مائدة الإفطار لأن الطماطم لامست الخيار؟ مرحبًا بكِ في فلسفة الطعام الرسمية لعمر 3.5 سنوات. لا تبحثي عن المنطق؛ تعلّمي في قسم الوصفات الصحية كيف تقسّمين الطبق إلى مناطق منفصلة ومرحة، وأنهي هذه الأزمة العبثية بسلام.'),
  ('9f8b4dfd-dfd3-4045-969a-2d6b122add47', 'مفاوضات النوم الدبلوماسية 🤝', 'إنه يفاوضكِ رسميًا كي لا يدخل السرير: «سأشرب رشفتين من الماء، ثم عانقيني مرة واحدة، وبعدها سأنام». ابتسمي أمام هذا التلاعب البارع. وافقي على شرطه، ثم أطفئي الأنوار بحزم وأبرمي الاتفاق فورًا.'),
  ('d547337a-f6dc-44bb-a0b7-19904928148b', 'لعبة الحمم البركانية على الأرض 🌋', 'الأرض حمم بركانية، اصعدي إلى الأريكة! لقد حوّل خياله المنزل إلى غابة. ضعي أعمالكِ جانبًا وانضمي إلى عالمه، ولو لمدة 2 دقيقة فقط، واهربي معه من الحمم. أحيانًا يكون اتّباع قواعد طفلكِ أفضل طريقة للتخلص من التوتر.'),
  ('6c7ca9b4-c80b-4cd6-bdd7-ff280ab39cba', 'أسرار سلة المهملات 🗑️', 'هل يتجاهل اللعبة التي اشتريتها من المتجر، ويحتضن غلافها البلاستيكي ذا الفقاعات ويلعب به طوال اليوم؟ عقل الطفل لا يحب السيناريوهات الجاهزة، بل يحب الحرية. سجّلي بفخر لحظات الإبداع الاستثنائية هذه في متتبّع النمو.'),
  ('7fe2513f-2da9-40be-8ba2-3f77c91758aa', 'لحظات المساء الهادئة 🛀', 'لقد أرهقت أسئلة «لماذا؟» ذهنكِ طوال اليوم. ضعيه في حوض استحمام مملوء بالماء الفاتر، وأضيفي قليلًا من الرغوة. أما أنتِ، فاجلسي بجانبه وركّزي فقط على صوت الماء. سيساعد ذلك التأثير الساحر للماء على تهدئة عناد طفلكِ وأعصابكِ معًا.'),
  ('e5f2539f-4aa6-4c0d-ad49-b97d6f90a867', 'أنتِ لا تسمعينني! 😤', 'يقول لكِ: «استمعي إليّ!» ويدير وجهكِ نحوه بيديه. إنه لا يريد مجرد وجودكِ الجسدي، بل يريد أن يكون تركيزكِ منصبًّا عليه بنسبة 100%. اتركي هاتفكِ أو ما تفعلينه لمدة 3 دقائق فقط، واستمعي إليه مع الحفاظ على تواصل بصري كامل. فهذا يمنع تذمرًا قد يستمر ساعات.'),
  ('246edaf3-5d30-44d2-bda4-13ec5fbf5f36', 'مسرح الظلال في الغرفة المظلمة 🐰', 'هل يخاف طفلكِ من الظلام ويرفض الذهاب إلى السرير؟ أطفئي أضواء الغرفة تمامًا وشغّلي مصباحًا يدويًا صغيرًا. اصنعي بيديكِ على الحائط ظلالًا لكلب وطائر. حوّلي الظلام المخيف إلى ساحة للعب، وسيغفو في لمح البصر.'),
  ('d3b4180b-5723-4f72-a6c8-b4229f2e876c', 'الديناصورات لا تأكل العصيدة! 🦖', 'هل لا يجيب طفلكِ عن أي سؤال في الصباح، بل يكتفي بالزئير؟ إنه اليوم ديناصور T-Rex. سايريه في هذه الشخصية التي ابتكرها واسأليه: «هل تتناول ديناصورات T-Rex وجبة الإفطار؟»، وبذلك سيجلس إلى المائدة من دون دموع.'),
  ('e089800c-6f76-4909-bafd-021551368a5f', 'لقد استُنزفت طاقتي اليوم 🛑', 'تراكمت عليكِ الأمور ورفعتِ صوتكِ، والآن تشعرين بالذنب. أنتِ لستِ إنسانًا آليًا. افتحي مفكرة حالتكِ المزاجية واكتبي: «لقد كنت متعبة حقًا اليوم». سيساعدكِ هذا الاعتراف أكثر من إجبار نفسكِ على ابتسامة مصطنعة.'),
  ('a8aeb934-2767-4365-a584-e2b99fc16215', 'لعبة «من أنتِ؟» 🎭', 'هل نظر إليكِ صباحًا كأنكِ غريبة وقال: «من أنتِ؟ أين أمي؟» هذه لعبة أدوار جديدة. قولي له: «أنا جارتكم، وستأتي أمك بعد قليل». دعي الغرفة تضج بالضحك منذ الصباح؛ فهذا يوفر طاقة أكبر بكثير من الدخول في صراع عناد.'),
  ('cf7b3532-560e-4c59-af5f-4a64a8510605', 'ساعديه على النوم من دون قراءة قصة 🪄', 'ألا تملكين طاقة لقراءة قصة هذا المساء؟ شغّلي القصص الذكية، واكتفي بأصوات الغابة الهامسة والرياح في الخلفية. استمعا معًا إلى أصوات الطبيعة في الظلام واستريحا من الضوضاء. سيزول الإرهاق البصري على الفور.'),
  ('f8301d61-e90d-4d1c-b4e2-7f1feb3be70d', 'كنز منسي في الغسالة 🍝', 'هل وجدتِ في جيب سرواله قطعة معكرونة جافة أو حجرًا أثناء غسله؟ هذا ليس طمعًا، بل استكشاف طفولي. ألقيه في سلة المهملات بوجه جاد، لكن ابتسمي في سرّكِ لهذا الطفل الذي يحب جمع المؤن. سجّلي ذلك كلحظة طريفة في متتبّع النمو.'),
  ('081fe93d-51fc-4e73-b956-ea2d06dcec72', 'قدّمي الماء في كوب مختلف! 🥤', 'هل قامت القيامة في الغرفة لأنكِ قدّمتِ الماء في الكوب الأصفر؟ لا تعقّدي الأمر؛ فهو يختبر حدوده فحسب. اسكبي الماء فورًا في الكوب الذي يريده، وأعيدي السلام إلى الغرفة ووفّري طاقتكِ لبقية اليوم.'),
  ('12e39cd9-ad30-497d-8902-0c8e0d1a5c56', 'حيلة السباق لمغادرة الحديقة 🌳', 'حان وقت مغادرة الحديقة، وبدأت نوبة البكاء. لن يفيد أن تجرّيه معكِ. قولي له: «لنرَ من سيصل إلى السيارة أولًا وهو يمشي مثل البطريق؟»، ووجّهي انتباهه فورًا إلى منافسة مضحكة. لا بد أنه سيرغب في الفوز.'),
  ('ec5e51b0-e017-4226-9363-9dfff1dce391', 'مصارعة على الأريكة مع أبيه 🤼‍♂️', 'هل هرب واختبأ كي لا يذهب إلى السرير؟ مرّري المهمة إلى أبيه، ودعيهما يتظاهران بالمصارعة على الأريكة. ستستنزف هذه اللعبة الصاخبة والمجهدة آخر ما لديه من طاقة عنيدة، فيستسلم للنوم بسهولة.'),
  ('01fb525b-af8a-41d4-8fd1-724d4fd01667', 'تأثير التنويم بالموسيقى 🎶', 'جرّبي تهدئة نوبات الغضب المسائية التي تبدو بلا سبب بتشغيل موسيقى كلاسيكية هادئة، وأطفئي التلفاز. غالبًا ما تطغى هذه الحيلة البسيطة على الضوضاء العميقة، وتجلب إلى الغرفة سكونًا أشبه بالسحر.'),
  ('d8b40eb7-3665-4514-839c-874f3d30ec40', 'كلمات من اختراعه 🗣️', 'يؤلف جملًا غريبة مثل «بكت السماء» و«غضبت السيارة». تنمو حصيلته اللغوية بسرعة هائلة، وهو يلهو بالكلمات. افتحي متتبّع النمو واحتفظي بهذه الفلسفة الشعرية اللطيفة في أرشيفكِ؛ فستقرؤونها بعد سنوات وتضحكون كثيرًا.'),
  ('f96cc98d-a4e0-44e3-9617-a284b205c20e', 'استراحة من تأنيب الضمير بسبب الشاشات 📺', 'هل بقي طفلكِ اليوم طويلًا أمام التلفاز لأن مهامكِ كانت كثيرة؟ هل ينهشكِ الشعور بالذنب؟ لا يمكنكِ أن تكوني مثالية كل يوم. أحيانًا تكون الشاشات أكثر جليسة أطفال براءة، وتنقذنا من فوضى عارمة. لا تقسُي على نفسكِ.'),
  ('3f11dc71-3a89-4499-8bac-19038f6fdeb4', 'بداية المخاوف الغريبة 🤖', 'هل بدأ فجأة يخاف من فتحة تصريف المياه في الحمّام؟ لا تبحثي عن الأمراض على الإنترنت. اسألي Anacan AI، وستعرفين أن هذا رهاب طبيعي تمامًا ومؤقت، ناتج عن خيال الأطفال في هذا العمر، فتتبدد مخاوفكِ.'),
  ('51e9982e-8a0e-4e2c-9ee7-749ec67f6283', 'سآكل بنفسي! 🥣', 'مع أنه يستطيع تناول الطعام بنفسه، يصرّ على أن تطعميه، ثم يدفع الملعقة ويبكي عندما تمدّينها إليه. حتى هو لا يعرف ماذا يريد. ضعي الطبق أمامه وقولي: «كُل عندما تجوع»، ثم غادري المائدة. سيأكل بنفسه عندما يشعر بالجوع.'),
  ('cc8c59da-7b2e-4da4-87ec-e11a59ea5011', 'خصّصي بعض الوقت لنفسكِ أيضًا 💆‍♂️', 'بعد أن ينام طفلكِ، اطلبي من شريككِ تدليك كتفيكِ لمدة 10 دقائق. فقد تيبّست رقبتكِ من كثرة الركض طوال اليوم. أنتما لستما مجرد والدين يتشاركان المنزل نفسه، بل كل منكما أقرب داعم نفسي للآخر.'),
  ('68be8da2-a2bd-442f-bb8b-f854ddbaa84b', 'أمهات إنستغرام والواقع 📱', 'لا تحبطي عندما تفتحين إنستغرام وترين أطفال الجميع مثاليين! أغلقي التطبيق وادخلي إلى مجتمع Anacan. عندما ترين أن منازل الجميع مبعثرة مثل منزلكِ وأن أطفالهم صاخبون، قولي: «أنا طبيعية تمامًا!»'),
  ('63fa1eaa-e73f-4258-a342-669de7f7f892', 'جاذبية الطعام المسكوب على الأرض 🍝', 'هل يتعمّد رمي الطعام على الأرض ثم يراقبه؟ لا تصرخي، فهو لا يحاول استفزازكِ، بل يختبر الجاذبية. أبعدي الطبق عن أمامه بهدوء، ويمكنكِ تعليمه لاحقًا.'),
  ('6e8cabf6-04bc-4e0f-a26d-cdeb494389a5', 'ناديني باتمان! 🦇', 'هل استيقظ صباحًا ورفض اسمه، وأصرّ على أن تناديه باسم آخر؟ سايريه! قولي له لمدة ٥ دقائق: «تفضّل يا باتمان، تناول عصيدتك»، وحوّلي التوتر في الغرفة إلى موقف طريف.'),
  ('b81a0aff-ac53-43cf-bdca-b8bf4192300e', 'مشكلة مطّاطة البيجاما 👖', 'هل يصرخ لأن البيجاما تضايقه (مع أنها تكاد تسقط عنه)؟ إنها الحساسية الحسية. قولي له: «انتظر، سأقرأ تعويذة سحرية فتتّسع»، ثم تظاهري بشدّ البيجاما. سيصدّق ذلك!'),
  ('070422be-d317-4a23-a559-6432c6ae63ed', 'إذا أغمضت عينيّ فسأختفي 👀', 'هل يحاول ألّا يرمش ويقاوم حتى تدمع عيناه؟ يبتكر عقل الطفل مخاوف يصعب تفسيرها. حوّلي هذا الخوف غير المنطقي إلى لعبة بقولكِ: «انظر، لقد أغمضت عينيّ وما زلت هنا».'),
  ('652ec194-fa0e-4ca8-ab49-626452c474ad', 'لا تلمسيني، أشعر بالحرّ 🛑', 'هل رفض فجأة أن يعانقكِ؟ لا تنزعجي! إنه يختبر حدوده الشخصية ويكتشف أن جسده ملك له وحده. هذه علامة على الاستقلالية، فراقبيه بفخر من بعيد.'),
  ('c7f18643-0c26-48a6-bc85-4480566ce781', 'النوم تحت المقعد 🛋️', 'هل رفض سريره والتفّ على نفسه ونام تحت المقعد؟ لا تخرجيه بالقوة ولا توقظيه. دعيه يستمتع بالنوم في مكان مختلف يشعر فيه بالأمان، وخذي أنتِ قسطًا من الراحة أيضًا.'),
  ('553ac831-9d91-4727-b2a6-83bd86e98633', 'الوسادة ليست مستقيمة! 🛏️', 'هل يبكي كي تضبطي وسادته بدقة المليمتر؟ إنه يبحث عن الكمال. سايريه، واضبطي الوسادة كأنكِ قستِها بمسطرة، ثم أطفئي الأنوار بحزم.'),
  ('895f4c44-bb71-4d9f-917c-8dc75b779cc8', 'ذعر الصمت في المنزل 🚪', 'هل أصبح المنزل فجأة هادئًا جدًا؟ عندما تبحثين عنه، ستجدينه على الأرجح شاردًا خلف الباب. لا تقلقي، فهو يبتعد عن الضوضاء ليستعيد هدوءه، فامنحيه هذا الوقت.'),
  ('bf79338f-3f38-4811-b226-50574547225b', 'إجابة الذكاء الاصطناعي عن الأسئلة الغريبة 🤖', 'هل وقفتِ عاجزة أمام سؤال: «ماما، أين يذهب ظلي ليلًا؟» لا تختلقي إجابة. افتحي Anacan AI واحصلي على إجابة علمية لطيفة وخيالية تناسب عمره، ثم اقرئيها له. ستشعرين وكأنكِ فيلسوفة عظيمة.'),
  ('50a90b1b-61b0-4de1-8146-038e23b46eb9', 'اكتبي عن الغضب الذي بداخلي 📝', 'ألا يرى أحد مدى تعبكِ في المنزل، وهذا يجعلكِ تنفجرين غضبًا؟ افتحي مفكرة المزاج واكتبي فيها كل ما أثار جنونكِ اليوم. تقبّل مشاعركِ والتعبير عنها بالكتابة سيساعدكِ أكثر من التظاهر بالابتسام.'),
  ('86283ea0-922f-4b91-8fed-55bf6231330d', 'أحاديث طويلة مع الجمادات 🗣️', 'هل يتحدث بجدية تامة إلى حجر في الحديقة أو إلى كرسي في المنزل؟ إنه يتعلم القواعد ويكتشف العالم من خلال اللعب.'),
  ('b3273f0d-ec07-48f9-82e7-89e57daaf623', 'لنتعانق فقط هذا المساء 🫂', 'لا حاجة إلى أي لعبة أو كتاب صاخب. فقط ضمّيه إلى صدركِ هذا المساء، واستنشقي بعمق رائحته الطفولية النقية، واهمسي له في الظلام كم هو غالٍ عليكِ. سيكون ذلك كافيًا لكليكما.'),
  ('1d8c6250-cd7d-4c49-8588-80172d7ce7fd', 'لا تتوقعي الطقس من النافذة ⛅', 'هل الشمس مشرقة في الخارج، لكن الرياح تهب أيضًا؟ إذا نصحتكِ أداة الطقس والملابس بإلباسه عدة طبقات، فثقي بها. بدلًا من الوقوف عند الباب مترددة ومتذمرة، اختاري الملابس المناسبة واخرجا براحة.'),
  ('78e7980c-5a72-49e5-bf40-4486d421427a', 'لن يعطيكِ من طعامه 🍳', 'لا يعطيكِ مما في طبقه، لكنه يأتي ويصرّ على تناول الطعام من طبقكِ؟ يثق الأطفال دائمًا ثقة تامة باختيارات والديهم. لا تدخلي معه في صراع، بل ناوليه اللقمة بحب وابتسمي فحسب لهذه الأنانية الطريفة.'),
  ('bdc2de1f-725b-4742-942a-3e8bf91a38f3', 'قصتي وقواعدي 📖', 'هل أخطأتِ في نطق كلمة أثناء قراءة القصة، فسارع إلى تصحيحها؟ هذا يعني أنه حفظها! أغلقي الكتاب وقولي له: «إذًا، اقرأها لي أنت هذا المساء». دعي خياله يعمل، بينما تستلقين وتستمعين إلى صوته العذب.'),
  ('02c28ca2-9054-4fe0-ba4f-902da3aebfad', 'يبني البرج ثم يهدمه 🧱', 'هل يبني برجًا من المكعبات بجهد كبير، ثم يضحك بصوت عالٍ ويهدمه بضربة واحدة؟ قد يؤسفكِ ضياع جهده، لكنه يتعلم الفيزياء والعلاقة بين السبب والنتيجة. هذا الهدم يصنع روابط جديدة في دماغه، فلا تنزعجي.'),
  ('051e4221-4f19-4e4b-a097-d797006e0813', 'لحظة الصمت المثالية 🛋️', 'هل اندمج طفلكِ في تركيب أحاجيه لدرجة أن الصمت حلّ فجأة في المنزل؟ لا تترددي، واسكبي لنفسكِ فنجانًا من القهوة فورًا. لا تهدري تلك الدقائق النادرة والثمينة في التنظيف أو غسل الملابس، بل استغليها لإراحة روحكِ والتحديق في السقف. فأنتِ لستِ روبوتًا.'),
  ('87efef38-8bd8-470c-82a9-956ee26f1fa2', 'بطاقة القميص تخزني! 🏷️', 'يرفض ارتداء القميص لأن تلك البطاقة الصغيرة في الخلف تخزه كالإبرة؟ قد تدفعكِ الحساسية الحسية في هذا العمر إلى الجنون. لا تدخلي في أي جدال، بل أمسكي المقص واقطعيها من جذورها، وأنهي هذه الأزمة الصغيرة في ثوانٍ.'),
  ('d321475d-a2ef-4c95-8a95-ccdb6522c470', 'النوم على صوت الهمس 🤫', 'هل ينهض من السرير ويركض في الغرفة رافضًا النوم؟ لا تصرخي. ابدئي فجأة بالتحدث ببطء شديد وبصوت هامس. سيضطر إلى تركيز انتباهه بشدة كي يفهمكِ، حتى يتعب دماغه وينتقل تلقائيًا إلى وضع النوم. جرّبي ذلك!'),
  ('7e80987d-061d-4fcd-8171-45d84324b66e', 'كذبة «لعبتي أسقطته!» 🤷‍♂️', 'هل سكب الماء على الأرض عمدًا، ثم أشار بإصبعه إلى سيارته وقال: «هي التي دفعته»؟ هذا ليس كذبًا، بل آلية دفاع. قولي له: «تعالَ لنعلّم السيارة أيضًا كيف تنظف المكان»، وهكذا تحوّلين الموقف بذكاء.'),
  ('a3c5807d-b2c4-4369-a70a-3e8219c1c3ef', 'رقم الصمت على الشاشة 🤫', 'لقد نام أخيرًا. هل حلّ في المنزل صمت شديد لدرجة أنكِ تسمعين طنينًا في أذنيكِ؟ افتحي مقياس الصوت في التطبيق. إن رؤية عبارة 0 ديسيبل ستكون أفضل تدليك بصري في العالم لدماغكِ المتعب والمثقل بالضوضاء.'),
  ('c034d9ff-ba06-4346-b3af-4ee27df0fc64', 'مهمة الخضراوات الخفية 🥦', 'هل عثر على قطعة الجزر الوحيدة في الحساء وقال: «لن آكل هذا»؟ مشهد مألوف! اهرسي الخضراوات وامزجيها بالصلصات، ولنرَ كيف سيعثر عليها الآن! تغلّبي على ذكائه الانتقائي في الطعام.'),
  ('006ab58d-d1e7-4e1c-a78e-139ada266050', 'فخر ارتداء القميص بالمقلوب 👕', 'هل ارتدى قميصه بالمقلوب ويرفض بإصرار أن تدعيه يصححه؟ هذا شأنه! ثقته بنفسه التي تلمع في عينيه وتقول «لقد فعلتها» أهم من ارتداء القميص بالطريقة الصحيحة. دعيه يتجول به بفخر طوال اليوم، فهذا اختياره الحر.'),
  ('a6797020-6e00-4e51-85e1-ce4c1dc47785', 'حين لا يجدي صوتكِ، يأتي الأب 🤡', 'هل توقف عن الاهتمام بما تقولينه وأخذ يعاند؟ وما إن جاء والده وأصدر أصوات حيوانات غريبة ورسم تعابير مضحكة على وجهه حتى انفجر ضاحكًا؟ أحيانًا تنقذ دعابات الرجال غير المنطقية المنزل فعلًا. اكتفي بالمشاهدة من بعيد.'),
  ('9d186c69-6a80-405e-9b2f-01d72d720233', 'ننام عندما يرنّ المنبّه ⏱️', 'يظل موعد النوم يتأخر أكثر فأكثر: ماء، حمّام، وتوديع الجدار... اضبطي مؤقّت الهاتف، وضعي قاعدة مفادها أن الجميع يطفئون الأنوار عند سماع رنينه. وحين يسمع طفلكِ ذلك الصوت، سيدخل إلى فراشه من دون أي اعتراض.'),
  ('e4247830-a48b-4a17-9555-7ca391f03a7d', 'طفل يمشي على أربع 🐾', 'هل خرج من فراشه هذا الصباح زاحفًا كالكلب بدلًا من أن يمشي كطفل؟ لا تنفعلي وتبدئي بإلقاء القواعد عليه. قولي له: «أحسنت يا جرْوي الذكي»، ثم قدّمي له الفطور. مشاركتكِ في لعب الأدوار توفّر طاقة أكبر بكثير من الدخول في صراع عناد.'),
  ('3b221a5a-9106-4d1d-8e8e-3de653008273', 'جسدي لم يعد ملكي 🔋', 'هل يتشبث بساقكِ طوال اليوم ويطلب منكِ حمله؟ أنتِ منهكة جسديًا وتعانين من إرهاق كثرة اللمس. اتركيه في الغرفة مع ألعابه واذهبي إلى الحمّام لمدة 5 دقائق، ثم أغلقي الباب. فقط استشعري تلك اللحظات من الخلوة.'),
  ('633ad245-30eb-4956-9f39-7177c312745a', 'صراخ مفاجئ في منتصف الليل 😭', 'هل استيقظ ليلًا باكيًا وعيناه مغمضتان، ولا يستجيب لصوتكِ؟ راقبي طبيعة بكائه؛ فقد يكون هذا رعبًا ليليًا. حاولي ألّا توقظيه، وابقي بجانبه فحسب، وأمسكي يده وربّتي عليه. سيهدأ من تلقاء نفسه ويعود إلى النوم العميق.'),
  ('8febb55a-81bd-4c4c-969e-a2b64ee79f90', 'كارثة المساعد الصغير في المطبخ 🧑‍🍳', 'هل جاء بكرسيه بينما كنتِ تفردين العجين، وأصرّ على سكب الدقيق بنفسه؟ إن لم تسمحي له فسيبكي. أعطيه وعاءً بلاستيكيًا صغيرًا وقليلًا من الدقيق. ستعمّ الفوضى المطبخ، لكن ملامح الطاهي الجادّة على وجهه تستحق كل ذلك التنظيف.'),
  ('026f55a4-9f0c-4ac0-9b08-0a6b14b79c2b', 'أنا من سيفتح الباب! 🚪', 'هل بكى لأنكِ فتحتِ الباب عند مغادرة المنزل، وأجبركِ على إغلاقه مجددًا كي يفتحه بنفسه؟ الشعور بالتحكم هو أكبر احتياج نفسي في هذا العمر. دعيه يكلّفكِ 1 دقيقة، لتتفادي نوبة غضب في الشارع تستمر 30 دقيقة.'),
  ('9e3821dd-5beb-4da8-ba9b-4369b4836b0a', 'التسمّر في وسط المتجر 🛒', 'هل توقفتِ في وسط المتجر تتساءلين: «ماذا جئت لأشتري؟» عقل الأم مثقل فعلًا بالكثير من الأمور. افتحي قائمة التسوق في التطبيق واعتمدي على تلك الذاكرة الرقمية؛ فستنقذكِ دائمًا من هذه الفوضى.'),
  ('c3a12f76-8197-4f4b-b339-db8bd083cf0a', 'فيضان حوض الاستحمام 🌊', 'هل الاستحمام مجرد حجة، بينما يحوّل طفلكِ حوض الاستحمام إلى محيط ويلعب بالأمواج؟ دعيه يلعب. فضجيج الماء وتناثره سيبددان تلك الطاقة العنيدة التي لا تنفد في داخله. وفي المساء سيستلقي في فراشه من دون أي مقاومة.'),
  ('380dd8d0-d6f8-457c-b025-9b12f69938f2', 'أين غدائي؟ 🥗', 'تحضّرين لطفلكِ طبقًا خاصًا مليئًا بالخضراوات، بينما تكتفين أنتِ بقضم الخبز؟ توقفي! حضّري سلطة الأمهات السهلة التي لا تستغرق سوى ٥ دقائق والموجودة في خطة التغذية، ولا تنسي أخيرًا إعادة شحن المحرّك الأساسي لهذا المنزل، أي أنتِ. فأنتِ مهمة.'),
  ('44db284c-e980-4095-8376-f1dcb5c24c8a', 'أطفئي الأنوار ليأتي النوم 🌙', 'قبل موعد نوم طفلكِ بساعة، أطفئي جميع الأضواء الساطعة والتلفاز في الغرفة. وكلما أصبحت الغرفة أكثر عتمة، سيبدأ بالتثاؤب تلقائيًا. هكذا تحفّزين إفراز الميلاتونين (هرمون النوم) بهدوء وبطريقة طبيعية، وتسهّلين المهمة على نفسكِ.'),
  ('113aa528-0657-4840-905d-63eec2aa048b', 'أنا أعرف، دعيني أعلّمكِ أيضًا ☝️', 'هل يأتي طفلكِ ليشرح لكِ شيئًا تعرفينه أصلًا، بتعبير جاد وذكي جدًا على وجهه؟ إنه يختبر ذكاءه. عضّي على شفتكِ كي لا تضحكي، لكن استمعي إليه بمنتهى الجدية وقولي: حقًا؟ شكرًا جزيلًا.'),
  ('70129896-2f43-4370-bbff-f84bbbb58845', 'عندما يروي والده القصة بطريقة خاطئة 📖', 'لن يكون صوتكِ هو صوت الحكاية هذا المساء. أعطي كتاب القصص لوالده، ودعيه يروي القصة عمدًا بالمقلوب وبطريقة مضحكة وعبثية. واستمتعي من بعيد بمشاهدة طفلكِ وهو يصحّح له ويضحك من أعماق قلبه.'),
  ('e8ee7ad3-2e99-4bdc-96ae-5bf9e81fcc4a', 'دعي التنظيف جانبًا واتركي الألعاب مكانها 🎨', 'هل صنع طفلكِ عملًا فنيًا ضخمًا من القطع المتناثرة في وسط الغرفة، ولا يسمح لكِ بترتيبه؟ ضعي هوس النظافة جانبًا. لا تلمسي الفوضى التي صنعها؛ فالتنظيف يمكن أن ينتظر حتى الغد. المنزل ليس متحفًا.'),
  ('4501063e-24e5-4f32-a723-396adeab0d2a', 'يروي لكِ قصة الرسوم المتحركة 📺', 'هل يروي لكِ طفلكِ أحداث الرسوم المتحركة التي شاهدها بمنطق مختلف تمامًا، ويشرح بجدية مَن ذهب وإلى أين؟ استمعي إليه باهتمام وكأنكِ تصدّقين كل شيء. دعيه يشعر بأنه الأذكى والأقوى في العالم.'),
  ('68a8ce66-c86f-4596-b8d3-b0d44f55a37d', 'صرخة «أريد هذا» المرعبة في المتجر 🛒', 'هل يصرخ طفلكِ طالبًا الشوكولاتة أمام صندوق الدفع مباشرة؟ لا تستسلمي رغم نظرات الواقفين خلفكِ. افتحي قائمة المشتريات وقولي: إنها غير موجودة هنا، ولن تقبلها آلة الدفع. فالمرجعية الخارجية تبدو لهم دائمًا أكثر إقناعًا.'),
  ('7a348b09-00b7-46e1-8565-808daca1314c', 'اغسلي كل التعب بالماء 🛀', 'أحيانًا لا ينجح أي شيء، ويظل طفلكِ يبكي بسبب كل شيء. ضعيه في حوض استحمام مملوء بالماء الفاتر. ستجلب قوة الماء السحرية في تخفيف التوتر هدوءًا كبيرًا وفوريًا إلى الغرفة بأكملها وإلى جهازه العصبي. جرّبي وسترين.'),
  ('3d738e03-bc77-4be0-b44b-95ecf5e6cdb0', 'فلسفة تحت الطاولة 🤔', 'هل يختبئ تحت الطاولة ويبدأ بسرد حكايات من خياله؟ دعي ذلك الفيلسوف الصغير يعيش في عالمه الخيالي، واستفيدي أنتِ من هذا الوقت لتستريحي.'),
  ('b5d5bf11-5ce6-464a-892e-f00915b62103', 'صوت اللحاف يزعجه 🛌', 'يقول إنه لا يستطيع النوم بسبب حفيف اللحاف! يبدو أن الأعذار الغريبة بلغت ذروتها. غطّيه ببطانية خفيفة، وعندما يرى أنكِ تجدين حلًا لكل شيء، سيستسلم للنوم.'),
  ('56bcf6ad-42a4-41b4-a775-ca5dbc61f766', 'تمرّد وقت الاستحمام 🛀', 'لا يريد النزول في الماء؟ ضعي فيه أوعية بألوان مختلفة، أو حتى بعض أدوات المطبخ البلاستيكية. وفجأة سيتحول الماء من مكان مخيف إلى ساحة للمرح.'),
  ('7f7bb774-fd67-46a5-93fe-c0a784ba9885', 'أنا أبي 👔', 'هل يريد ارتداء حذاء أبيه الكبير والذهاب إلى العمل صباحًا؟ لا تتعجلي! رافقيه حتى الباب، وبمجرد أن يرى المصعد سيعود إليكِ ضاحكًا.'),
  ('dbd02f3e-2d56-4baa-bc3c-93886c747027', 'عشق الهدوء عند 0 ديسيبل 🤫', 'لقد نام أخيرًا! افتحي مقياس الصوت في التطبيق، وتأملي ذلك الهدوء المطلق حين ينخفض المؤشر إلى أدنى الشاشة. هذا الصمت المرئي سيداعب ذهنكِ المتعب كما لو كنتِ في منتجع صحي حقيقي.'),
  ('1c6686dd-4008-4750-acaf-4155c3330cdd', 'الشجرة أسقطت ورقتها 🍂', 'هل يغضب من الشجرة ويوبخها بسبب الورقة الملقاة على الأرض؟ يا لها من علاقة بريئة ومضحكة تجمعه بالطبيعة!'),
  ('806ceb98-90c4-4de6-a42b-37c72e8d03ae', 'ظلّي يسبقني 👻', 'هل يبكي في الشارع لأن ظلّه يسبقه؟ احمليه وقولي له: «انظر، لقد اتحد ظلّانا». بدلًا من شرح قوانين الفيزياء، امنحيه ببساطة شعورًا بالأمان.'),
  ('a0789257-db81-493e-9643-abeb1d193c59', 'مزحات الأب الغريبة 🤡', 'لا تغضبي لأن أباه أضحكه وأيقظه وقت النوم. فضحكاته المرحة ستبدد تمامًا كل التوتر الذي تراكم لديه طوال اليوم، فدعيهما يمرحان ويُحدثان بعض الضجيج.'),
  ('fceb9d37-669a-42ac-ae17-36b46f1fa546', 'مأساة انكسار البسكويت المقرمش 🍪', 'هل قامت القيامة لأن قطعة البسكويت انقسمت إلى نصفين؟ لا يمكنكِ لصقها من جديد. قولي له: انظر، أصبحت الآن قطعتين، واحدة لي وواحدة لك، وحوّلي الموقف إلى درس في الحساب والمشاركة.'),
  ('7871e777-44f4-425d-a10e-dda0547ccfc1', 'الآيس كريم بقي في الحلم 🍦', 'كان يأكل الآيس كريم في حلمه، فغضب منكِ لأنكِ أيقظته؟ لقد اختلط عليه الحلم بالواقع. احتضنيه رغم وجهه الغاضب واضحكي، وسيحتاج إلى 2 دقيقة فقط ليعود إلى الواقع.'),
  ('94d22bcb-5e09-49a0-bea6-432b56a92308', 'لون زجاجة الماء 🚰', 'يريد الماء ليلًا، لكن ليس في الكوب الأحمر؟ لا تبحثي عن المنطق في منتصف الليل ولا تحاولي تلقينه درسًا. بدّلي الكوب فورًا ووفّري طاقتكِ للصباح والسلام.'),
  ('c160b0b4-c39a-4e5d-bbc5-111f29e33385', 'هوس وجود حجر في حذائي 👟', 'يجعلكِ تخلعين حذاءه وتفحصينه 10 مرات، ولا يوجد أي حجر! هل يبدو هذا السيناريو مألوفًا؟ تظاهري بأنكِ التقطتِ حبة سوداء صغيرة بيدكِ، وقولي: انظر، وجدتها، لقد نجونا، ثم واصلا التنزّه.'),
  ('1fe87964-746d-4cf2-a7f3-21730045a9ae', 'لماذا العصيدة ساخنة؟ 🥣', 'لا يأكلها إن لم تكن ساخنة، لكنه يبكي الآن لأنها ساخنة؟ يا لها من معضلة! ضعي فيها عمدًا قطعة ثلج ملوّنة، فستجذب اهتمامه وتهدئه في لمح البصر.'),
  ('8d0f8dc1-b43d-411f-a7dc-2e0b87cf4d93', 'البكاء خلف الباب 🚪', 'أغلق الباب ويبكي وحده في غرفته ولا يريدكِ؟ لا تحاولي احتضانه بالقوة. أحيانًا يرغب الأطفال أيضًا في عيش مشاعرهم وحدهم، لذا امنحيه بعض الوقت والمساحة.'),
  ('f52f2ceb-159e-4eff-95c6-70eae6ed7217', 'الغضب من ذئب الكتاب 🐺', 'يضرب صورة الذئب في الكتاب بقبضته ويوبّخه؟ يا له من خيال رائع! من دون إفساد عالمه الخيالي، قولي له: لقد حميتني، ما أشجعك! وهكذا تعززين ثقته بنفسه.'),
  ('3c299611-0f24-405d-b774-857cf09c273e', 'لا تلبسيني جواربي! 🧦', 'هل يرفض بإصرار كل ما تفعلينه من أجله؟ رائع! ضعي ملابسه على الأريكة وابدئي تحدّي: من سيرتدي ملابسه أولًا؟ وسيرتديها بنفسه خلال ثوانٍ.'),
  ('a579865a-399f-44c5-a9b0-e44cc032ce14', 'أنا في الحكاية! 🪄', 'في الحكايات الذكية، استبدلي اسم بطل الحكاية باسم طفلكِ مباشرةً. وحين يرى طوال القصة كيف يخلد البطل إلى النوم سريعًا ويطيع الكلام، سيتحمس ليفعل مثله.'),
  ('2d3b049d-536d-441d-a015-9e7326fee52e', 'لا تتجمّدي وسط المتجر 🛒', 'دخلتِ المتجر ونسيتِ ما تريدين شراءه؟ إذا لم تحتفظي بقائمة مشترياتكِ رقميًا، فستنسين كل شيء وسط تلك الفوضى. ثقي دائمًا بذاكرتكِ الرقمية.'),
  ('47345c36-90d7-4e89-b816-0332dc1932ef', 'عدّ النجوم ليلًا 🌟', 'هل ينظر إلى سقف غرفة النوم ويعدّ نجومًا خيالية؟ دعيه يعدّها. فعندما يصل عدد تلك النجوم المتخيّلة إلى 10، سيكون قد غفا ودخل في نوم عميق.'),
  ('924a98d3-0af0-4add-81f0-0d94e1af83c6', 'صارت يداي قدمين 🤸‍♂️', 'هل يحاول المشي على يديه ثم يسقط؟ مهاراته الحركية الإبداعية تتطور بأقصى سرعة! أعدّي له مسارًا صغيرًا للحركة في مكان آمن بالمنزل، ودعيه يفرّغ طاقته.'),
  ('50f1584c-32c1-44e9-9ef5-89a70a2afc5e', 'دخول الأب بهدوء 👨‍🍼', 'في اللحظة التي تُنهكين فيها من قراءة الحكاية، يدخل الأب الغرفة بهدوء، ويداعب طفلكِ، ثم يشير إليكِ أن تذهبي لترتاحي. إنها من أجمل لحظات العمل الجماعي في رحلة الوالدية.'),
  ('6694bf7a-8c8c-47c1-8991-2a84701c94f1', 'لم تقشّري الموزة بالطريقة الصحيحة 🍌', 'يا له من ملك للأعذار! قامت القيامة لأنكِ أنتِ من قشّرتِ الموزة. أعطيه موزة جديدة ودعيه يقشّرها كما يشاء، حتى لو كسرها من المنتصف، كي لا يشعر بأن استقلاليته قد مُسّت.'),
  ('9aaf0e76-e78b-442f-afe1-7bb02c660da6', 'تمرّد «الجو حار جدًا» 🧥', 'هل يخلع سترته ويرميها في وسط الشارع، بينما تخشين أن يشعر بالبرد؟ لا تدخلي في صراع معه؛ فعندما يشعر بالبرد حقًا، سيأتي ويطلبها بنفسه. دعيه يختبر النتيجة بنفسه.'),
  ('02ff52cb-13af-47d3-83d9-4e3e21f04d45', 'أنا كرسي 🪑', 'هل يتظاهر بأنه قطعة أثاث ويقف بلا حراك؟ ضعي عليه لعبةً على سبيل المزاح وقولي: «يا له من كرسي جميل!». سيحب هذا الدور الغريب كثيرًا وسيبقى هادئًا.'),
  ('0879e029-e767-44f9-917b-506cde86d1a1', 'كي لا تبكي البيضة 🍳', 'عندما تكسرين البيضة، هل يشفق عليها ويرفض أكلها؟ تعاطفه لا حدود له. أنقذي الموقف بحكايات لطيفة من نسج الخيال، مثل أنها ستعيش الآن في عضلاته.'),
  ('7338df78-5f1a-4db5-ae07-ccfc779e153a', 'لعبة الهمس 🤫', 'لا يريد النوم ويهرب؟ اخفضي صوتكِ فجأة واهمسي بصوت خافت جدًا. سيركّز كي يسمعكِ، وسيتعب دماغه ويستسلم للنوم خلال 5 دقائق.'),
  ('b9a9483f-7511-4f19-847b-4d0786991104', 'صرخة الجسد 🩸', 'لا تستسلمي للانزعاج والإرهاق من دون سبب. تحققي من متتبع الدورة الشهرية، فجسدكِ يرسل إليكِ إشارة. وبدلًا من لوم نفسكِ، استريحي مع وجبة خفيفة غنية بالمغنيسيوم من قسم الوصفات الصحية.'),
  ('1bf9463f-7457-4983-af0a-2e62627ce701', 'الأطعمة الحمراء فقط 🍅', 'اليوم يوم الهوس! لا يريد سوى الأشياء الحمراء؟ راجعي خطة التغذية وقدّمي له اليوم الطماطم الحمراء والفراولة، ودعي هذه الرغبة الغريبة تتحقق بدلًا من مقاومتها.'),
  ('73d3b07e-eaa0-4423-b3b3-a6fb8656c01c', 'لعبتي مريضة 🩺', 'هل أدخل دبدوبه إلى المستشفى؟ تظاهري أنتِ أيضًا بالمرض! استلقي على الأريكة ودعيه يفحصكِ تمثيلًا لمدة 10 دقائق، فتكون هذه حجة لإراحة ظهركِ.'),
  ('ea408c5e-c419-4258-9053-eba96cea541e', 'إصراره على أن تنامي معي 🫂', 'هل يصرّ على أن تنامي بجانبه؟ خالفي القواعد ليوم واحد، واستنشقي رائحته بعمق ونامي معه. إنها جلسة علاج بالحب لكليكما.'),
  ('7d8bddb7-9260-4872-8287-e9bfde4a91d7', 'يا ذكاء اصطناعي، ساعدني 🤖', 'هل أنهكتكِ أسئلة طفلكِ الفلسفية التي لا تنتهي؟ اكتبي إلى Anacan AI، وسيُعدّ لكِ فورًا أكثر الإجابات علمية وصبرًا ولطفًا، بما يناسب طفلًا في عمر 4 سنوات.'),
  ('9135dd5f-177c-4a9d-97a6-1658abd0da9a', 'لم أعرف نفسي في المرآة 🪞', 'هل ينظر إلى نفسه في المرآة، ويغيّر تعابير وجهه ثم يغضب من نفسه؟ إن إحساسه بذاته ومشاعره في طور التشكّل. راقبي بصمت هذا الأداء التمثيلي من بعيد.'),
  ('a65f1e7a-ca07-4462-bac0-1293b0e5896c', 'علاجي الرقمي 🤫', 'نام جميع من في المنزل، لكن ذهنكِ ما زال يعجّ بالضجيج؟ افتحي مقياس الصوت. جرّبي النظر إلى عبارة 0 ديسيبل في الغرفة؛ فقد يمنحكِ ذلك راحة أكبر من جلسة مع اختصاصي نفسي.'),
  ('25ef7ba4-1698-4dbc-9412-9bb568472d80', 'تنويم ألعابه 🧸', 'لا ينام، لكنه يضع ألعابه في السرير واحدة تلو الأخرى ويغطّيها؟ هذه اللعبة التمثيلية تهيّئه في الواقع تدريجيًا ونفسيًا لنومه، فلا تتدخّلي.'),
  ('7626d265-88f4-40f1-a79c-e9d0f1238d73', 'لماذا فتحتِ أنتِ الباب؟ 🚪', 'هل يبكي لأنكِ فتحتِ الباب، ويطلب منكِ إغلاقه مجددًا كي يفتحه بنفسه؟ دعيه يستغرق 1 دقيقة، وتجنّبي بهدوء نوبة غضب وصراخ قد تستمر 20 دقيقة في المنزل.'),
  ('a5284401-af40-43a4-aa11-663792a88d21', 'اللون الأخضر فقط! 🥦', 'هل يبحث في طبقه عن الأطعمة الخضراء فقط؟ راجعي خطة التغذية، وتعلّمي كيف تصنعين من الخضراوات كرات خضراء بأشكال لطيفة، وأشبعي هذا التعلّق الغريب.'),
  ('1752e8bc-24e4-4f1b-97e5-c557a4522bda', 'أين ذهبت السماء؟ ☁️', 'هل فاجأكِ في الطقس الضبابي بسؤال فلسفي أربككِ؟ قولي له إن الغيوم غطّتها كي لا تشعر بالبرد؛ فعقله ليس مستعدًا بعد للتفسير العلمي، وكل ما يريده هو حكاية.'),
  ('2d5bfd88-008f-4b96-a72a-390cdfe7c90d', 'الركض في وسط المتجر 🛒', 'هل يركض فجأة عند صندوق الدفع ويختبئ خلف الرفوف؟ احتفظي بقائمة مشترياتكِ رقميًا، كي لا تنسي في لحظات الذعر هذه ما لم تشتريه وتعودي إلى المنزل خالية الوفاض.'),
  ('5c94e9c6-00cb-4c58-b265-f248e6c3e544', 'لعبة الهمس 🤫', 'هل يركض صارخًا ويرفض النوم؟ اخفضي صوتكِ فجأة حتى يكاد لا يُسمع، وابدئي بالتحدث همسًا بصوت خافت جدًا. سيركّز انتباهه كي يسمعكِ، وسيشعر بالنعاس.'),
  ('22c6ff37-5069-489b-9d49-2a97d14d2e2e', 'لستُ أمًا مثالية 🛑', 'هل انقلب كل شيء رأسًا على عقب اليوم وصرختِ؟ لا تقسُي على نفسكِ. اكتبي ببساطة في يوميات مزاجكِ: كان اليوم سيئًا، لكنني أم جيدة، وسأحاول مجددًا غدًا.'),
  ('50fd969e-9bd4-4e5e-8927-9b3b9067a4be', 'ماذا يقول لي المجتمع؟ 💬', 'هل تظنين أنكِ تفعلين كل شيء بطريقة خاطئة؟ ادخلي إلى مجتمع Anacan، واقرئي حكايات الأمهات الأخريات مع أطفالهن المشاغبين، وخذي نفسًا عميقًا، ثم احمدي الله على طفلكِ!'),
  ('8d85cb27-805f-4ca6-a6a0-16122a07af20', 'اجعلي الغرفة مظلمة تمامًا 🌙', 'ألا يستطيع النوم بسبب الضوء المتسلل من الممر؟ يبدو أنه يبحث عن الظروف المثالية. أغلقي الباب بإحكام واجعلي الغرفة مظلمة تمامًا، ودعي الميلاتونين يؤدي دوره الطبيعي ويساعده على النوم.'),
  ('6a3af8d6-9d3b-434e-ad40-18c53a8e8dfd', 'مشكلة البقعة الوهمية 👕', 'هل يبحث عن بقعة على سرواله رغم عدم وجود شيء؟ إنها مجددًا تلك الوساوس البصرية. تظاهري بمسحها بمنديل مبلل، وقولي له إنها اختفت. فعقل الطفل يصدق مثل هذه الحيلة بسرعة كبيرة.'),
  ('7da643f9-a304-476b-9165-6028a945c141', 'اجلسي بعيدًا 🛑', 'هل يصرّ على أن تجلسي بعيدًا عند عتبة الباب بدلًا من الجلوس بجوار سريره؟ لا تنزعجي! فهذه خطوة كبيرة نحو استقلاليته، ويحق لكِ أن تفرحي في داخلكِ.'),
  ('b72ecf4d-fe3f-4f6b-a417-a52c3a7a15ba', 'العصفور عند النافذة لي 🐦', 'هل يريد إحضار عصفور الحديقة إلى المنزل ويبكي؟ يبدو أن حبه للطبيعة يفيض! أخبريه بأن أم العصفور تنتظره في عشه، وسيتحول هذا الموقف في الحال إلى هدوء وسلام.'),
  ('544fb1ce-862b-49f6-8e2e-6b2192929ac3', 'بدأت مخاوف الليل 👻', 'هل يخاف من الوحش تحت السرير؟ املئي عبوة رذاذ فارغة بالماء، ورشي الغرفة كما لو أنه رذاذ سحري لطرد الوحوش. سيختفي خوفه في ثوانٍ.'),
  ('b51cc09c-00f6-4b63-945d-9cfceecedfb2', 'أريد تنظيف أسناني بإصبعي 🪥', 'هل يرفض فرشاة الأسنان ويصرّ على تنظيفها بإصبعه؟ لا تعترضي؛ يمكن إتمام الأمر بإصبع نظيف توضع عليه كمية صغيرة من معجون الأسنان، فلا داعي لتضخيم المشكلة.'),
  ('e403fe31-012f-4f6b-80cb-45dd719c9f06', 'متعة الشوكولاتة السرية 🍫', 'هل تأكلين الشوكولاتة سرًا في المطبخ بينما يشاهد طفلكِ التلفاز؟ هنيئًا لكِ! إنها لوح الطاقة الطبيعي الذي تحتاجينه لتحمّل كل هذه الأزمات، فلا تلومي نفسكِ.'),
  ('2d98107a-3331-4f7f-8930-8f762e325d02', 'حرية ارتداء القميص بالمقلوب 👕', 'هل يرتدي قميصه وظهره إلى الأمام ويتجول بفخر؟ لا تصححيه! ثقته بنفسه عالية جدًا، لذا اكتفي بمراقبته من بعيد وافتخري بقائد المستقبل ذي الروح الحرة.'),
  ('c5aa519b-baae-498e-a13b-bdf83115f0c9', 'نظرات مفعمة بالصمت 🥂', 'نام طفلكِ، وأنتِ وشريككِ تجلسان على الأريكة وتتبادلان النظرات بصمت. لا تتحدثان عن أي شيء. هذا الصمت هو في الواقع أكثر الطرق رومانسية للقول: لقد نجحنا في هذا أيضًا.'),
  ('eaade7fe-4846-47fa-9bc5-4c49360a0a4a', 'الريح دفعتني 💨', 'هل يغضب من الريح في الخارج ويحاول ضربها؟ لو ألقيتِ نظرة مسبقًا على أداة الطقس والملابس، فربما لما خرجتما أصلًا. الآن اضحكي فحسب على هذا المشهد الكوميدي وعودا مسرعين إلى المنزل.'),
  ('77606aaa-e2aa-442d-992d-f4dce779d9e5', 'فن الأرضية 🎨', 'هل رسم لوحة بقطع المعكرونة الجافة في وسط الغرفة وينظر إليكِ بفخر؟ دعي التنظيف جانبًا وابتسمي له.'),
  ('92c59586-e756-4176-87f0-6ee0836bd1f7', 'حكاية الأب الجالبة للنوم 📖', 'هل أُرهق صوتكِ ولا ترغبين في قراءة الحكاية؟ مرّري المهمة إلى الأب. فنبرة صوته العميقة والمختلفة، والتفاصيل العبثية التي يبتكرها، ستجعلان الطفل يستسلم للنوم بسرعة أكبر.'),
  ('dc97d51e-f4af-4633-84e4-fbe0fbe9e15a', 'شعري يؤلمني 🪮', 'هل تمشيط شعره أشبه بالموت؟ بلّليه قليلًا برذاذ الماء، ووجّهي انتباهه إلى الوجوه المضحكة التي تصنعينها أمام المرآة. وما إن يتشتت انتباهه، مشّطي شعره وانتهي بسرعة.'),
  ('1b495b8d-2c5f-47f5-aeda-e199006766ac', 'جسدي لم يعد ملكي 🔋', 'هل تخدّر جسدكِ من تسلّقه عليكِ طوال اليوم؟ اتركي الطفل وحده في الغرفة لمدة 5 دقائق، وأغلقي الباب فحسب، ثم أغمضي عينيكِ وخذي نفسًا عميقًا. عليكِ استعادة طاقتكِ.'),
  ('81591bb3-d8f2-475d-b7fc-1bd47693b91f', 'لا تقولي إنني طفل! 😤', 'هل يقول إنه أصبح كبيرًا ويضع لكِ القواعد في الغرفة؟ إنه يحاول إثبات أنه كبر بالفعل. خاطبيه بقولكِ «حسنًا، أيتها الشابة/أيها الشاب» وعامليه كشخص كبير لتكسبي احترامه.'),
  ('39a82edc-fce3-4cb5-8ef7-be6b2f9a1122', 'حكاية بصوت المطر 🌧️', 'صوتكِ متعب ولا طاقة لديكِ لقراءة حكاية؟ شغّلي فقط أصوات المطر والغابة في خلفية الحكايات الذكية. فسكون الطبيعة هذا قد يساعده أحيانًا على النوم أسرع من أجمل حكاية.'),
  ('69d7d720-ce5e-441e-ac6e-b3151e6557c4', 'لا تمسكي بيدي! 🚶‍♂️', 'هل يريد ترك يدكِ والمشي بحرية في الطريق؟ إذا كان المكان آمنًا، فدعيه يختبر استقلاليته، واكتفي بالسير خلفه بخطوتين ومراقبته بفخر.'),
  ('27e63f29-b167-40b2-aa6b-8ed0d0329ca3', 'أطراف الخبز هي العدو 🍞', 'هل يأكل وسط الخبز ثم يرمي أطرافه بإصرار؟ لا تخوضي معركة مع القشور. استخدمي قطّاعات بأشكال الحيوانات واصنعي له قطعًا بلا قشور، ودعيه يستمتع بهذا التصميم المبتكر للطعام.'),
  ('7c97a838-1745-4335-a86c-2bf011bb9f3b', 'لا يريد الخروج من المنزل ⛅', 'هل تضيق بكم جدران المنزل الأربعة، لكنه يبكي ولا يريد الخروج؟ استعيني بأداة الطقس والملابس، وأخرجيه حتى لو أبدى بعض المقاومة. فما إن يستنشق الهواء الطلق حتى يتلاشى في لحظات كل توتره داخل المنزل.'),
  ('f3fa598e-4bec-4396-a5cb-220c0c856d23', 'مصارعة البيجاما مع أبيه 🤼‍♂️', 'لا يريد النوم؟ دعي أباه يلاعبه بالمصارعة ويتظاهر بأنه يهزمه عند الحائط. سيبذل آخر ما لديه من طاقة ويتصبب عرقًا، ثم يركض إلى سريره.'),
  ('2ab3a16c-8538-4df6-b8df-c031bc53d6c7', 'استمدّي قوتكِ من المجتمع 💬', 'عندما ينفد صبركِ، ادخلي إلى مجتمع Anacan. حين ترين أن الأمهات هناك يعشن الفوضى نفسها، ستشعرين براحة كبيرة وبأنكِ لستِ وحدكِ.'),
  ('5a8f1d52-e3d3-4c7e-b491-d2552a236831', 'نجحنا في هذا أيضًا! 🚀', 'غرق الجميع في النوم. أنتِ مستعدة لفوضى الشهر المقبل الجديدة، فأنتِ خبيرة في هذا الأمر. أطفئي الأنوار واشكري نفسكِ على كل تلك المعجزات الصغيرة التي صنعتِها اليوم.'),
  ('83732257-57c8-43f0-99f6-cb1c1583874a', 'هذا الظل لي 👻', 'هل يعتبر ظلّه ملكًا له، ويتحدث إليه ويوجّه له الأوامر؟ خياله بلا حدود.'),
  ('2feec242-97b8-4207-9200-a80856e8121d', 'من هذا الطفل في المرآة؟ 🪞', 'هل يقف أمام المرآة ويقطّب حاجبيه ويصنع تعبيرات غاضبة وغريبة؟ إنه يكتشف كيف تبدو المشاعر على وجهه. راقبي بصمت واستمتاع تدريبات هذا الممثل المسرحي الصغير.'),
  ('70b38ef9-bf37-4439-be26-d9a4e96ca1a7', 'أطفئي الأنوار وابحثي عن الظلال 🔦', 'هل يخاف من الظلام ويرفض الذهاب إلى السرير؟ أطفئي أنوار الغرفة تمامًا وشغّلي مصباحًا يدويًا صغيرًا. اصنعي بيديكِ على الحائط ظلالًا لكلب وطائر. حوّلي الظلام المخيف إلى مسرح ممتع له، وسيصبح نومه أسهل.'),
  ('d5008830-7d32-4abc-8ae0-128b13041be3', 'تحفة فنية على الحائط 🖍️', 'هل ساد الصمت لبضع ثوانٍ، ثم وجدتِه يرسم تحفة فنية على الحائط بقلم تلوين؟ خذي نفسًا عميقًا. فمهاراته الحركية الدقيقة تتطور، ويمكن تنظيف الحائط على أي حال. احرصي على تصوير هذه التحفة قبل مسحها.'),
  ('56af6282-7207-49e4-b888-b735c8e4f791', 'ركوب الخيل على كتفي أبيه 🐴', 'هل ما زالت لديه طاقة ويرفض الذهاب إلى السرير؟ اطلبي مساعدة أبيه. عندما يحمله على ظهره ويتظاهر بأنه حصان، تملأ الضحكات الغرفة، ويتبدد التوتر الجسدي المتراكم خلال ثوانٍ مع التعرق والحركة.'),
  ('65ce993d-a029-4b05-8c87-ec0d7b807a64', 'استراحة في الحمّام لمدة 5 دقائق 🚪', 'هل تشعرين بأن الضوضاء تخترق رأسكِ وترغبين في الصراخ بسبب كل شيء؟ ضعيه في مكان آمن، وادخلي الحمّام وأغلقي الباب. حدّقي في الحائط لمدة 5 دقائق فقط من دون أن تفعلي شيئًا. سيعيد إليكِ هذا الهدوء القصير توازنكِ.'),
  ('a5a3dc3f-2634-4d40-9509-dbe4066d8a5a', 'العصيدة مستديرة أكثر من اللازم 🥣', 'هل غضب من شكل الطعام ورفض تناوله؟ لا تبحثي عن المنطق، بل حرّكي العصيدة بالملعقة وقولي ببساطة: «انظر، لقد أصلحتها». ستحتاجين دائمًا إلى فن الإيهام في رحلة الأمومة.'),
  ('9272ca67-0e34-4d81-b7cc-a00d43d2c52b', 'دموع بلا منطق 😭', 'هل أقام الدنيا لأنه لم يتمكن من ركل حجر في طريق العودة من الحديقة؟ لا تبحثي عن المنطق، فهو متعب فحسب. لا تجادليه؛ احمليه بين ذراعيكِ، واعترفي بمشاعره ثم حوّلي انتباهه إلى شيء آخر.'),
  ('bf4ef479-e79f-4536-adc8-2a33fe4bb476', 'أسرار الحكاية الهامسة 🤫', 'هل يختلق الأعذار للهرب من السرير؟ اخفضي صوتكِ تمامًا وابدئي بالتحدث همسًا فقط. سيضطر إلى تركيز انتباهه جيدًا كي يفهمكِ، وسرعان ما سيستسلم دماغه للنوم.'),
  ('4c512e27-6d0e-434b-b3b6-e7db7541662c', 'خطوط الأسفلت قانون لا يُخالف 🛣️', 'هل يقوم بحركات غريبة في الشارع كي لا يدوس على الخطوط بين الحجارة؟ هكذا تعمل المهارات الحركية الكبرى والانتباه في الوقت نفسه. لا تستعجليه، أمسكي بيده واقفزي معه فوق تلك الخطوط.'),
  ('685cde5b-1133-4e8c-aa85-09d262ad4afb', 'الخوف من فتحة تصريف الماء 🛁', 'هل يخاف من الفتحة التي يتدفق إليها الماء عند خروجه من حوض الاستحمام؟ خياله يعمل بطريقة غير منطقية. ضعي هناك سفينة لعبة بلاستيكية وقولي له: «انظر، هذه تحرسك ولن تسحب أي شيء». وهكذا سيتحول الخوف في لحظته إلى لعبة.'),
  ('e7c8a731-9f6f-40fe-bb36-efba9869846f', 'حفل يبدأ الساعة 6 صباحًا 🎤', 'هل يبدأ بغناء أغنية من تأليفه بأعلى صوته ما إن يفتح عينيه؟ لا تقطعي تلك الطاقة الجامحة بقولكِ: «اصمت، سيستيقظ الجيران». انضمي إليه. فالطفل الذي يبدأ صباحه بالغناء يكون أقل عدوانية طوال اليوم.'),
  ('7dbcfeb4-6b0f-40e0-a421-e16781d15f4a', 'رقصة الصمت عند 0 ديسيبل 🤫', 'أخيرًا، الغرفة مظلمة وقد نام. حلّ على المنزل صمت شديد حتى إن أذنيكِ تكادان تنسدّان. افتحي مقياس الصوت في التطبيق. إن مشاهدة الرقم على الشاشة وهو ينخفض إلى 0 ديسيبل بمثابة تدليك رقمي حقيقي لدماغكِ المتعب من كل تلك الضوضاء.'),
  ('80129e61-cd59-4c54-9d5e-e6507c3811da', 'لعبتي غاضبة منكِ 🧸', 'هل جاء إليكِ وقال: «دُبّي غاضب منكِ لأنكِ صرختِ»؟ إنه ينقل إليكِ مشاعره عبر إسقاطها على الأشياء. اعتذري من الدب بجدية شديدة واحتضنيه. سترين كيف سيشعر طفلكِ بالارتياح.'),
  ('e7d3487a-45d4-44a3-bf97-c34082190904', 'لماذا يتصاعد البخار من الشاي؟ ☕', 'هل ينظر إلى البخار المتصاعد من فنجانكِ ويطالبكِ بتفسير، أو ربما يخاف منه؟ ألا تستطيعين تقديم شرح علمي؟ اطلبي من Anacan AI تفسيرًا لطيفًا وفلسفيًا يناسب طفلًا في عمر 4 سنوات: «إنه يطير لينضم إلى الغيوم».'),
  ('37af8066-a97d-4233-891d-9eb3a99e296b', 'هجوم سري على القائمة 🛒', 'هل فتحتِ قائمة التسوق في التطبيق قبل الذهاب إلى المتجر، فوجدتِ أن 5 قطع من الشوكولاتة قد أُضيفت إليها؟ نعم، لقد تعلّم طفلكِ منذ مدة كيف يتسلل إلى هاتفكِ ويحاكي العالم الرقمي.'),
  ('709311bc-b001-46b6-bc4d-6ad222fa6ef4', 'دراما التفاحة الكاملة 🍏', 'هل ضجّ البيت بالصراخ لأنكِ قطّعتِ التفاحة إلى شرائح؟ يبكي قائلًا: «كنت أريدها كاملة!». لا تبحثي عن المنطق. ألصقي الشرائح ببعضها وقولي: «انظر، لقد أصلحتها»، ثم اخرجي دبلوماسيًا من هذه الدراما غير المنطقية.'),
  ('8b61be71-cfc2-42cd-ad4f-a58585ff674e', 'بطل من ابتكار الأب 🦸‍♂️', 'لا صوت لديكِ ولا طاقة لقراءة كتاب؟ مرّري المهمة إلى الأب. دعيه يروي حكاية خيالية عشوائية يكون طفلكِ بطلها الرئيسي. وما عليكِ سوى الاستلقاء على الأريكة والاستماع إلى الضحكات القادمة من الغرفة.'),
  ('167cc8b8-5aaf-4f2a-8be0-934651da76be', 'الإصرار على ارتداء الجورب بالمقلوب 🧦', 'ارتدى الجورب بحيث أصبح الكعب فوق قدمه ويرفض تمامًا أن تسمحي له بتعديله؟ دعيه كما هو. فشعوره بالفخر وهو يقول: أنا فعلتها بنفسي، أثمن بمليون مرة من ارتدائه بالطريقة الصحيحة.'),
  ('4081d285-b739-4c34-a223-ae2922366de7', 'حجة رشفة ماء أخرى 💧', 'هل يقفز من السرير قائلًا أنا عطشان جدًا، justo عندما يكاد يغطّ في النوم؟ هدفه ليس الماء، بل كسب مزيد من الوقت معكِ. ضعي مسبقًا زجاجة ماء مانعة للانسكاب بجانب سريره، لتقطعي الطريق على هذه الحيلة الشهيرة.'),
  ('7b85f446-78f0-4be5-9cc1-c336a25ea658', 'أنا متعبة، لكنني لا أقول ذلك 📝', 'لا أحد يرى مقدار التوتر الذي عانيتِ منه اليوم، وتشعرين بالاختناق لأنكِ تبتسمين للجميع؟ افتحي مفكرة المزاج. أفرغي على الشاشة كل ما بداخلكِ من مشاعر سلبية وغضب. هذا التنفيس الرقمي قد يريحكِ أسرع من جلسة مع أخصائي نفسي.'),
  ('1bdc66c1-4583-42f2-a981-0ba814be491d', 'معركة السترة 🧥', 'الشمس ساطعة في الخارج، لكنه لا يريد ارتداء سترته. لا تنخدعي بما ترينه من النافذة؛ أريه درجة الحرارة الحقيقية في أداة الطقس والملابس، وصورة الطفل الذي يرتدي عدة طبقات. دعي الهاتف يضع القاعدة بدلًا منكِ.'),
  ('8b4c98d1-27b9-49ae-b0a2-f93f650bdd45', 'لماذا لم ينظر إليّ الطائر؟ 🐦', 'هل انخرط في بكاء شديد لأن حمامة طارت بعيدًا في الحديقة؟ لا تبحثي عن المنطق في هذه اللحظة. فهذا بالنسبة إليه خيبة أمل كبيرة حقًا. أكّدي مشاعره بحنان وقولي له: سيشتاق إليك كثيرًا.'),
  ('cbcac766-bab8-4183-80ab-82267106b24d', 'أريد أن يكون اسمي في الحكاية 🪄', 'هل سئم أبطال الكتب الكلاسيكية؟ في الحكايات الذكية، استبدلي اسم البطل باسمه. وعندما يسمع كيف نام بشجاعة، سيستسلم للنوم في غرفته من دون أي اعتراض.'),
  ('83683b1a-77a6-45bf-bf9e-6b7ae022a7e3', 'أنا سيارة اليوم 🚗', 'هل يقول لكِ صباحًا: أنا لست طفلًا، أنا سيارة؟ لا تفرضي القواعد. قولي له: إذًا، لنملأ خزانك بالوقود (العصيدة) كي تنطلق بسرعة. ألعاب تقمّص الأدوار الطريفة هذه أسهل بكثير من الصراخ.'),
  ('87824b1c-6e01-4ebd-84b1-4bb784a464e0', 'كعكة مصنوعة من الرمل 🏖️', 'هل خلط الماء بالتراب في الحديقة، ولطّخ ملابسه بالطين، ثم أعدّ لكِ كعكة؟ لا تهتمي بالفوضى. فهذا ينمّي مهاراته الحركية الدقيقة وإبداعه.'),
  ('bc3aaf13-535b-4b7d-bc70-b3e5a5a87b99', 'مسابقة عدم الرمش 👀', 'لا يريد النوم ويتعمّد فتح عينيه على اتساعهما والنظر إليكِ؟ العبِي معه لعبة «من يغمض عينيه أولًا يخسر». ستدمع عيناه ويتعب في النهاية، وستُغمضان تلقائيًا خلال 2 دقيقة. جرّبي وسترين!'),
  ('20b06f39-a2df-4c97-aab5-39753c3a8a8f', 'الألعاب المختبئة في السرير 🧸', 'هل دخلتِ سريره فوجدتِ تحته 3 سيارات صلبة؟ إنه ينام وهو يحرسها. لا تقلقي، فبعد 10 دقائق من استغراقه في النوم، يمكنكِ إخراج تلك الأشياء المزعجة سرًا ليحظى بنوم مريح.'),
  ('29e9913a-41eb-42ab-96c8-cc6c3af590fd', 'مواساة صامتة في المجتمع 💬', 'هل أنتِ مرهقة جدًا ولا ترغبين حتى في البوح بما يزعجكِ لأحد؟ ادخلي إلى مجتمع Anacan واكتفي بالقراءة. فرؤية كيفية تعامل الأمهات الأخريات مع نوبات الغضب العبثية نفسها ستكون أقوى مواساة صامتة لكِ.'),
  ('bab27593-bee1-487c-a8d8-1d9f5c333dc2', 'أزمة الملعقة الخطأ 🥄', 'هل كادت ثورة تندلع لأنكِ قدّمتِ الحساء بملعقة كبيرة؟ قرب سن 4 سنوات، قد يغيّر الحجم الفعلي للأداة مذاق الطعام في منطق طفلكِ، حتى إن كان الطعام نفسه. لا تجادليه، بدّلي الملعقة فورًا ووفّري طاقتكِ.'),
  ('6072f87e-09eb-4773-9647-75d90ac37029', 'الاسترخاء بصمت على الأريكة 🥂', 'نام طفلكِ ورُتّب المنزل. اجلسي بجوار زوجكِ على الأريكة، ولا تشغّلا التلفاز حتى. فقط تبادلا نظرة تقول: «نجحنا في هذا أيضًا وخرجنا سالمين». صدّقي أن هذه هي أكثر لحظات الأبوة والأمومة رومانسية وواقعية.'),
  ('a980ec72-f146-48fe-a3b4-28ba8f8a9398', 'حب اللون الأخضر 🥦', 'هل يبحث في طبقه عن الأشياء الخضراء فقط ويُبعد الألوان الأخرى؟ اطّلعي على الوصفات الصحية وتعلّمي كيف تصنعين من الخضراوات الورقية كرات خضراء بأشكال لطيفة وشهية.'),
  ('e2f4da77-db67-4ed8-9acb-d0a907894c73', 'لماذا أغلقتِ أنتِ الباب؟ 🚪', 'هل أخذ يصرخ لأنكِ أغلقتِ الباب عند الخروج من المنزل، وأصرّ على فتحه مجددًا؟ الشعور بالتحكّم من أهم احتياجاته. دعيه يؤخّركِ 1 دقيقة، لكن تجنّبي بذلك نوبة بكاء في الشارع تستمر 30 دقيقة.'),
  ('48b463cd-d776-4db6-a471-4507d498dd54', 'التجمّد في منتصف المتجر 🛒', 'دخلتِ المتجر ونسيتِ ما تريدين شراءه؟ إن لم تحتفظي بقائمة تسوّقكِ رقميًا، فستنسين كل شيء وسط تلك الفوضى. اعتمدي دائمًا على ذاكرتكِ الرقمية في التطبيق كي لا تعودي إلى المنزل خالية الوفاض.'),
  ('9dc02f00-56a0-48da-87a7-8f742a42c374', 'أنتِ لا تلعبين معي! 😤', 'بينما تحرّكين الطعام، يأتي ويدير وجهكِ نحوه بيديه وكأنه يقول: انظري إليّ!? وهو محق. إنه لا يريد مجرد وجودكِ الجسدي، بل يريد اهتمامكِ الكامل. اتركي ما تفعلينه واستمعي إليه لدقيقتين فقط مع الحفاظ على تواصل بصري كامل.'),
  ('a00b84e6-561e-4101-8d5d-a0f8a705abed', 'غرفة على وقع صوت المطر 🌧️', 'لا صوت لديكِ ولا طاقة لقراءة حكاية؟ شغّلي فقط أصوات المطر والغابة في قسم الحكايات الذكية لتكون خلفية صوتية. هذا الهدوء الطبيعي الرتيب قد يساعده أحيانًا على النوم أسرع من أجمل حكاية.'),
  ('a4fa9d13-3510-4b51-9dcb-583bfd5c19ad', 'أن يُنادى باسم من اختياره 🦇', 'هل استيقظ ورفض اسمه، وأصرّ قائلًا: ناديني باتمان؟ سايريه! قولي له لمدة 5 دقائق: تفضّل يا باتمان، تناول عصيدتك، وحوّلي التوتر في الغرفة فورًا إلى موقف كوميدي.'),
  ('e5dd03b1-7179-4527-8c52-f0958fe208e9', 'الإرهاق من أمهات Instagram 📱', 'لا تشعري بالإحباط حين تفتحين Instagram وترين أطفال الجميع وكأنهم مثاليون! أغلقي ذلك التطبيق وادخلي إلى مجتمع Anacan. خذي نفسًا عميقًا عندما ترين أن منازل الجميع تعمّها الفوضى مثل منزلكِ؛ فأنتِ لستِ وحدكِ.'),
  ('17e2ffec-fd31-4ab8-8917-684e3ceaaff9', 'غسل كل التوتر بالماء 🛀', 'أحيانًا لا ينجح أي شيء، ويظل يبكي من كل شيء. ضعيه في حوض استحمام مملوء بالماء الفاتر. لذلك الماء تأثير ساحر يجذب التوتر بعيدًا، وسيملأ الغرفة وجهازه العصبي بقدر كبير من السكينة فورًا.'),
  ('d1311034-b416-403f-a981-34577f22c978', 'اذهبي، لا أريدكِ 💔', 'هل قال لكِ: أنتِ أم سيئة، اذهبي! لأنكِ رفضتِ طلبه؟ لا بد أن قلبكِ قد تألم. لكنه لا يزال عاجزًا عن التعبير عن غضبه بالكلمات؛ وما يقصده حقًا هو: لقد شعرت بخيبة أمل. لا تأخذي كلامه على محمل شخصي، بل عانقيه بحب.'),
  ('e3289711-a700-447f-9c8d-d0e1b469b80e', 'وقت الشاي مع الصديق الخيالي 🫖', 'هل يتظاهر بصبّ الشاي في الهواء عند زاوية الغرفة ويضحك؟ إنها مرحلة ظهور الصديق الخيالي!'),
  ('dd593bef-61fd-4b06-ae2c-84f70da4ad5c', 'لماذا أسكتِّ صوتي؟ 🎶', 'بدأتِ تدندنين مع أغنية الأطفال التي كانت تُعزف في الخلفية، فصرخ فورًا: لا تغنّي أنتِ! إنه المغني المنفرد الوحيد في الغرفة، ومحاولاتكِ الغنائية تزاحمه على مسرحه. لا تنزعجي، واتركي المسرح لهذا الأناني الصغير.'),
  ('0e5c772e-ad3b-4b0c-99e1-704d879eb64e', 'يختار ملابسه بنفسه 👗', 'بنطال أحمر، وحذاء رياضي، وقبعة شتوية... ويصرّ على الذهاب إلى الحديقة بهذا المظهر. لا تهتمي بما سيقوله الناس. دعيه يخرج بما اختاره، فحرية الاختيار أهم لديه من تناسق المظهر.'),
  ('1c02e319-6351-4dbf-93b0-072c9cbcabab', 'اتفاق النوم بالمؤقت ⏱️', 'هل يشعر فجأة بالعطش عند حلول موعد النوم، أو يبدأ بتوديع الجدار؟ اضبطي مؤقتًا، وضعي قاعدة تقول: عندما يرن الجرس، ينام الجميع. فالامتثال لسلطة خارجية يكون أسهل عليهم دائمًا.'),
  ('42320a1e-019f-4b03-8860-b2a7ebec874e', 'لماذا لم يذهب القمر بعد؟ 🌙', 'هل رأى القمر في السماء صباحًا وسأل: لماذا لم ينم القمر؟ لا ترهقي ذهنه بالمصطلحات العلمية. افتحي Anacan AI، ودعيه يجد تلك الحكاية الفلكية اللطيفة المناسبة لعمره، ثم اقرئيها له وأشبعي فضوله.'),
  ('37e1f058-26f3-4681-8381-3414a60ed5c9', 'لا يأكل سوى أطراف الخبز 🍞', 'هل يأكل قشرة الخبز فقط ويرمي لُبّه؟ لا بد أن فلسفات الطعام المعكوسة أصبحت مألوفة لديكِ. لا تخوضي حربًا من أجل القشور. تعلّمي في خطة التغذية كيف تقطّعين الخبز بقوالب مختلفة لتصنعي له المزيد من الأطراف.'),
  ('d40bcca0-d355-4520-b51b-bece0b2b8663', 'الظلام من أجل الميلاتونين 🌌', 'لمساعدته على النوم بسرعة أكبر، أطفئي جميع شاشات التلفاز والهواتف في الغرفة قبل موعد النوم بـ1 ساعة. فالميلاتونين (هرمون النوم) يُفرَز سريعًا في البيئة المعتمة، لذا ثقي بهذه العملية الطبيعية.'),
  ('eb8ec98b-d143-483a-b14c-964f86bd6a10', 'لماذا لا تنام الألعاب؟ 🧸', 'لا ينام، لكنه يضع ألعابه كلها في السرير واحدة تلو الأخرى ويغطيها؟ إن لعب الأدوار هذا يهيئه نفسيًا وبالتدريج لنومه، فلا تتدخلي إطلاقًا.'),
  ('22a3d2df-ec5e-47c6-9766-7dc689ce8423', 'استنشقي رائحته فحسب 🫂', 'هل أفقدكِ صوابكِ اليوم حقًا واستنزف طاقتكِ؟ لكنه ينام في سريره ببراءة شديدة... أطفئي الأنوار. استلقي بجانبه، واستنشقي بعمق رائحته الطفولية النقية، واهمسي له بحبكِ في الظلام.'),
  ('05726924-8563-423e-bd0f-f5be06f1d806', 'الحكاية التي يقرؤها والده بطريقة خاطئة 📖', 'أعطي والده كتاب الحكايات هذا المساء. ودعيه يروي القصة عمدًا بشكل معكوس ومضحك وعبثي. استمتعي بمشاهدته وهو يضحك من أعماق قلبه ويستمتع بتصحيح أخطاء والده.'),
  ('1b87ed18-3cf6-4e93-88b1-58f24b42513f', 'لعبة المطاردة في الصباح الباكر 🏃‍♂️', 'هل يركض فوق الأرائك في الساعة 7 صباحًا؟ لا تصرخي. اتركي ما تفعلينه لمدة 2 دقيقة وانضمي إليه بالقفز والمرح. فالدخول إلى عالم طفلكِ الخيالي طريقة غريبة لكنها فعالة لتخفيف توتركِ أيضًا.'),
  ('9c4135ea-bc1e-4450-aea1-64dfec877859', 'القلق من التأتأة المفاجئة 🤖', 'هل دفعتكِ التأتأة المفاجئة لدى طفلكِ إلى البحث عن الأمراض على الإنترنت؟ توقفي! اسألي Anacan AI لتعرفي ما إذا كانت مرتبطة بطفرة النمو في سن 4 سنوات، وهدّئي قلقكِ.'),
  ('15bb2b6b-7a84-4331-86dd-6aee2aba5539', 'رقم الصمت على الشاشة 📉', 'لقد نام أخيرًا. هل حلّ بالمنزل صمت شديد لدرجة أنكِ تسمعين طنينًا في أذنيكِ؟ افتحي مقياس الصوت في التطبيق. إن النظر إلى قراءة 0 ديسيبل سيكون أفضل تدليك بصري في العالم لدماغكِ المتعب والمثقل بالضوضاء.'),
  ('21cfa5ea-471d-459d-a626-6d4be6cf6e4c', 'معركة «أنتِ قشّرتِ الموزة» 🍌', 'هل اندلعت ثورة في الغرفة لأنكِ قشّرتِ الموزة؟ القاعدة الذهبية في هذا العمر: يجب أن يقرر هو كل شيء. لا يمكنكِ إعادة القشرة إلى الموزة، لذا أعطيه موزة جديدة ودعيه يقشّرها كما يريد، حتى لا يشعر بأن استقلاليته قد انتُزعت منه.'),
  ('e6cc1e43-997c-46d7-a69b-a71076271387', 'بهلوان الحبال على حافة الرصيف 🧱', 'هل يصرّ في طريقه إلى الحديقة على السير فوق أضيق حافة للرصيف بدلًا من الطريق المستوي؟ أمسكي بذراعه لحمايته، ودعيه يحقق هذا الإنجاز الصغير. فهكذا يتطور لديه التوازن والثقة بالنفس معًا بصورة رائعة.'),
  ('6daea202-5e39-49bd-9344-4fdbc59064e5', 'تخصيص وقت لنفسكِ ليس ذنبًا 🥗', 'أعددتِ قوائم طعام متنوعة لإطعامه، لكن ماذا أكلتِ أنتِ؟ حضّري من قسم الوصفات الصحية تلك السلطة السهلة المخصصة للأمهات، والتي لا تستغرق سوى 5 دقائق، ولا تنسي أخيرًا أن تستعيدي طاقتكِ.'),
  ('744c45ec-e43d-4be3-95b9-700cd56edef4', 'نظرات صامتة متبادلة 🥂', 'نام طفلكِ. تجلسين أنتِ وشريككِ على الأريكة وتنظران إلى بعضكما بصمت. لا تقولان شيئًا. هذا الصمت هو في الحقيقة أكثر الطرق رومانسية وصدقًا لقول: لقد نجحنا في هذا أيضًا، نحن فريق رائع.'),
  ('0a86e24e-bf60-4b61-ae36-925c5211691c', 'طلب تجفيف الماء 💧', 'هل يصرخ بدلًا من شرب الماء في الكوب: «هذا مبلل جدًا، جفّفيه»؟ لا تبحثي عن المنطق؛ اسكبي الماء في كوب بلون مختلف وقولي: «أحضرتُ لك ماءً جافًا». فن الإيهام هو أقوى أسلحتكِ في الأمومة.'),
  ('b27687ec-9619-4dbe-be9c-054706708b62', 'الخروج إلى الطبيعة ضرورة ⛅', 'هل تتحول طاقته بين أربعة جدران إلى سلوك عدواني، وتبدأ كل جملة يقولها بكلمة «لا»؟ ثقي بالطقس والملابس المناسبة، واحرصي على إخراجه. فملامسة التراب ستساعد جهازه العصبي على استعادة هدوئه فورًا.'),
  ('eeca2adc-6712-4238-9603-30877865ed81', 'نوم تلقائي على صوت الجرس ⏱️', 'هل يرغب فجأة في الذهاب إلى الحمّام عندما يحين موعد النوم؟ اضبطي مؤقتًا، وطبّقي قاعدة: «عندما يرن الجرس، يطفئ الجميع الأنوار». وهكذا تتخلصين بلا جدال من طقوس الوداع التي لا تنتهي ومحاولات المماطلة المتقنة.'),
  ('4e140178-6301-4406-9f9f-fe623cbcfff7', 'الغميضة خلف الباب 🙈', 'هل تأخرتما عن الروضة بينما يختبئ خلف الستارة ويقول: «اعثري عليّ!»؟ الصراخ لن يؤدي إلا إلى إطالة الأمر. قولي: «يا ترى، أين صغيري؟»، وشاركيه اللعب لمدة 2 دقيقة، ثم أخرجيه من مخبئه وأنتما تضحكان.'),
  ('7964aed1-1770-40a2-a565-23bfdc9aea21', 'مؤثرات صوتية متنوعة في الحكايات الذكية 🪄', 'افتحي الحكايات الذكية. وأثناء قراءة القصة، اصنعي مسرحًا صوتيًا في الغرفة بمحاكاة صرير الباب وصوت الرياح والهمسات. ستجذب هذه الأصوات غير المألوفة انتباهه فورًا إلى عالم الحكاية.'),
  ('c87486c1-f5de-473b-8cd5-b9e2e2bd31c1', 'لا للشعور بالذنب بسبب وقت الشاشة 📺', 'هل أمضى اليوم وقتًا طويلًا أمام التلفاز لأن لديكِ الكثير من المهام؟ هل ينهشكِ الشعور بالذنب؟ لا يمكنكِ أن تكوني مثالية كل يوم. أحيانًا تكون الشاشات ألطف جليسة أطفال تنقذنا من فوضى كبيرة، فاطمئني.')
) AS v(id, t, b)
WHERE x.id = v.id;
